STORAGE_CLEANUP_PREVIEW_TTL = timedelta(minutes=15)
STORAGE_CLEANUP_RECOVERY_WINDOW = timedelta(days=14)
# Environmental Context v2: bounds how often "today"'s own weather rows are
# re-fetched (see docs/environmental-context-v2-contract.md "Phase 10").
# Every other (non-today) date is fetched at most once, ever, per distinct
# location -- immutable-reuse, matching solar's per-day cache exactly.
WEATHER_REFRESH_INTERVAL = timedelta(minutes=30)
DEFAULT_STORAGE_REVIEWED_NON_BIRD_AGE_DAYS = 180
DEFAULT_STORAGE_SUPERSEDED_AGE_DAYS = 90
DEFAULT_STORAGE_ORPHANED_AGE_DAYS = 30
# Appliance / Storage / Privacy / Recovery v1, Phase B: bounds how stale
# `storage_summary()`'s cache can be between explicit invalidations (see
# `ProductRepository.__init__`). Short enough that a user actively watching
# the Dashboard after a cleanup/backup action sees it refresh within the
# same minute; long enough that rapid page navigation/reloads do not each
# pay this method's real per-`MediaAsset` query cost.
STORAGE_SUMMARY_CACHE_TTL_SECONDS = 30.0
MAX_ALERT_PAGE_SIZE = 50
MAX_RECENT_ALERTS = 12
# Dataset QA's own summary counts (issue_count, high_count, ...) are always
# computed from every qualifying record; only the detailed `issues` list
# returned for display is bounded, so a real installation's growing history
# (measured: 420 real issues rendered a 51,000+px Analytics page from this
# exact gap) cannot make the page itself unbounded the way it made the
# aggregate counts honest already.
MAX_DATASET_QUALITY_ISSUES = 50


