class FastReviewConflictError(ValueError):
    """The visible review snapshot no longer matches the current truth state."""


class ReviewRevisionConflictError(ValueError):
    """A reviewed Visit changed before an append-only revision could be applied."""


class ReviewProvenanceConflictError(ValueError):
    """A ReviewLabel's provenance already changed before a bounded repair
    (see docs/review-decision-provenance-contract.md Part 8 and
    scripts/repair_review_label_provenance.py) could be applied."""


class VisitCurationConflictError(ValueError):
    """A Visit or merge snapshot changed before structural curation could be applied."""


class MonitoringOperationConflictError(ValueError):
    """An idempotency key was reused for a different monitoring operation."""


class CameraConfigurationConflictError(ValueError):
    """A camera edit preview no longer matches the saved configuration state."""


class PlaceFeatureHasHistoryError(ValueError):
    """A Place Feature has recorded change-event history and cannot be
    hard-deleted -- see `ProductRepository.remove_place_feature`."""


