class SpeciesSuggestionModel(Base):
    __tablename__ = "species_suggestions"
    __table_args__ = (
        # Multimodal Observation & Soundscape v1, Phase B (schema 45, see
        # docs/multimodal-observation-soundscape-v1-contract.md,
        # "Acoustic idempotency"): the acoustic candidate-Visit idempotency
        # key was `(media_asset_id, window_start_ms, window_end_ms,
        # adapter_id)` -- species was never part of it, so two distinct
        # species genuinely detected in the identical merged window
        # collided: the second species' insert matched the first species'
        # already-inserted row and was silently dropped as
        # `idempotent_repeat`. `create_acoustic_candidate_visit`/`extend_
        # acoustic_candidate_visit` now filter on `suggested_label` too
        # (application-level fix); this index is the DB-level backstop.
        # Provably safe to add on any pre-existing real database: the *old*
        # 4-column key already guaranteed at most one row per
        # (media_asset_id, window_start_ms, window_end_ms, adapter_id)
        # combination regardless of species, so no two rows can already
        # share the *stricter* 5-column key either -- a real historical
        # duplicate under the new key is structurally impossible, only a
        # missing second-species row (see the migration for the full proof).
        # Scoped to `window_start_ms IS NOT NULL` (SQLite's own NULL-is-
        # distinct semantics would already exclude every image-backed
        # suggestion from colliding, but an explicit partial index matches
        # this codebase's established convention, e.g.
        # `VisitCollectionModel.uq_visit_collections_active_normalized_name`).
        Index(
            "ux_species_suggestions_acoustic_idempotency",
            "media_asset_id", "window_start_ms", "window_end_ms", "adapter_id", "suggested_label",
            unique=True,
            sqlite_where=text("window_start_ms IS NOT NULL"),
        ),
    )

    id: Mapped[str] = mapped_column(String, primary_key=True)
    source_id: Mapped[str | None] = mapped_column(ForeignKey("camera_sources.id"), nullable=True)
    stream_id: Mapped[str | None] = mapped_column(ForeignKey("streams.id"), nullable=True)
    event_id: Mapped[str | None] = mapped_column(ForeignKey("events.id"), nullable=True)
    visit_id: Mapped[str | None] = mapped_column(ForeignKey("visits.id"), nullable=True)
    media_asset_id: Mapped[str | None] = mapped_column(ForeignKey("media_assets.id"), nullable=True)
    motion_evidence_id: Mapped[str | None] = mapped_column(
        ForeignKey("motion_evidence.id"),
        nullable=True,
    )
    adapter_id: Mapped[str] = mapped_column(String, nullable=False)
    adapter_name: Mapped[str] = mapped_column(String, nullable=False)
    suggested_label: Mapped[str] = mapped_column(String, nullable=False)
    suggested_common_name: Mapped[str | None] = mapped_column(String, nullable=True)
    suggested_scientific_name: Mapped[str | None] = mapped_column(String, nullable=True)
    confidence: Mapped[float | None] = mapped_column(Float, nullable=True)
    rank: Mapped[int] = mapped_column(Integer, nullable=False)
    alternatives_json: Mapped[str] = mapped_column(Text, nullable=False)
    evidence_region_json: Mapped[str | None] = mapped_column(Text, nullable=True)
    status: Mapped[str] = mapped_column(String, nullable=False)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    notes: Mapped[str | None] = mapped_column(Text, nullable=True)
    # Acoustic / BirdNET Observation Foundation v1 (schema 43): the temporal
    # analog of `evidence_region_json` -- which bounded window of the
    # source audio clip this suggestion came from. `None` for every
    # image-backed suggestion (unchanged) and for any pre-schema-43 row.
    window_start_ms: Mapped[int | None] = mapped_column(Integer, nullable=True)
    window_end_ms: Mapped[int | None] = mapped_column(Integer, nullable=True)
    # One serialized, adapter-neutral provenance object -- model name/
    # version/license, runtime identity, resolved config (confidence floor,
    # location filter), and the source evidence's own content hash. Any
    # adapter may populate this (not audio-specific by construction); every
    # pre-schema-43 row and every suggestion whose adapter does not supply
    # one reads back `None`, never a fabricated value.
    model_provenance_json: Mapped[str | None] = mapped_column(Text, nullable=True)


class VisitAssociationModel(Base):
    """Multimodal Observation & Soundscape v1, Phase D/E (schema 46, see
    docs/multimodal-observation-soundscape-v1-contract.md): a durable,
    additive link between one visual candidate Visit and one acoustic
    candidate Visit that `multimodal_association.evaluate_temporal_
    association` judged temporally related. Deliberately NOT a merged
    "MultimodalObservation" truth object -- both original Visits/Events
    remain independently reviewable exactly as before; this table only
    records that a relationship was found, and how confidently.

    Species/taxon agreement is never stored here -- it is recomputed at
    read time from whatever each Visit's current top `SpeciesSuggestion`
    or `reviewed_label` is (see `multimodal_associations_for_visit`), so a
    later re-suggestion or human correction can never leave a stale
    "agrees"/"differs" fact behind.

    Only positive findings are persisted: two Visits judged clearly
    independent (outside even the wider `possible` window) never get a row
    at all -- consistent with this codebase's "never fabricate a
    relationship that was never found" convention (mirrors
    `SceneConfusorRegionModel`/`ObservationCandidateVisitModel` only ever
    recording what actually happened).

    Rows are upserted, not append-only: `ProductRepository._reconcile_
    multimodal_association_for_event` always recomputes every row for a
    visual Event's *current* full sibling set from scratch, so a Visit that
    was uniquely `"associated"` with one acoustic Visit correctly downgrades
    to `"possible"` the moment a second visual sibling later makes the
    acoustic evidence genuinely ambiguous (Phase H) -- never a stale,
    overconfident claim left standing after new evidence arrives."""

    __tablename__ = "visit_associations"
    __table_args__ = (
        UniqueConstraint("visual_visit_id", "acoustic_visit_id", name="uq_visit_association_pair"),
        Index("ix_visit_associations_visual_visit", "visual_visit_id"),
        Index("ix_visit_associations_acoustic_visit", "acoustic_visit_id"),
    )

    id: Mapped[str] = mapped_column(String, primary_key=True)
    visual_visit_id: Mapped[str] = mapped_column(ForeignKey("visits.id"), nullable=False)
    acoustic_visit_id: Mapped[str] = mapped_column(ForeignKey("visits.id"), nullable=False)
    # "associated" (clear) | "possible" (temporally coincident, not
    # confidently exclusive) -- see `multimodal_association.AssociationTier`.
    # There is deliberately no "independent" value; see class docstring.
    tier: Mapped[str] = mapped_column(String, nullable=False)
    overlap_ms: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    gap_ms: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    # Which version of the deterministic tiering rule produced this row --
    # mirrors `ObservationCandidateVisitModel.assembler_version`'s own
    # precedent, so a future stricter/looser engine can tell which rule
    # decided a given historical row without guessing.
    engine_version: Mapped[str] = mapped_column(String, nullable=False)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)


class CrossCameraVisitAssociationModel(Base):
    """Camera / Source + Multi-Camera Maturity v1, Phase I (schema 47; see
    "Overlapping-camera policy" in docs/camera-source-multi-camera-
    maturity-v1-contract.md): a durable, additive link between two visual
    candidate Visits on *different* Sources that `cross_camera_association.
    evaluate_cross_camera_association` judged the same wildlife encounter,
    or plausibly the same encounter.

    A deliberate sibling of `VisitAssociationModel`, not a reuse of its
    columns: `VisitAssociationModel.acoustic_visit_id` is `NOT NULL` and
    SQLite cannot cheaply loosen an existing column's nullability (no
    `ALTER COLUMN`), so a same-modality (visual+visual) pair gets its own
    additive table with honestly-named columns instead of overloading an
    acoustic-shaped column with a second visual id. Same discipline as
    `VisitAssociationModel` throughout: both original Visits/Events always
    remain independently reviewable, species/taxon agreement is never
    stored here (recomputed at read time, exactly like the multimodal
    case), and only positive findings are persisted -- two Events judged
    clearly independent never get a row at all.

    `primary_visit_id`/`secondary_visit_id` use a canonical order (the
    lexicographically smaller `Visit.id` first) purely so the same pair is
    never stored twice under swapped columns -- unlike a visual/acoustic
    pair, neither side of a cross-camera pair is intrinsically "first."
    Rows are upserted, not append-only, by the same full-recompute-per-
    Event-reconciliation pattern `_reconcile_multimodal_association_for_
    event` already established."""

    __tablename__ = "cross_camera_visit_associations"
    __table_args__ = (
        UniqueConstraint("primary_visit_id", "secondary_visit_id", name="uq_cross_camera_association_pair"),
        Index("ix_cross_camera_associations_primary_visit", "primary_visit_id"),
        Index("ix_cross_camera_associations_secondary_visit", "secondary_visit_id"),
    )

    id: Mapped[str] = mapped_column(String, primary_key=True)
    primary_visit_id: Mapped[str] = mapped_column(ForeignKey("visits.id"), nullable=False)
    secondary_visit_id: Mapped[str] = mapped_column(ForeignKey("visits.id"), nullable=False)
    # "associated" (clear) | "possible" (temporally coincident, not
    # confidently exclusive) -- see `cross_camera_association.AssociationTier`
    # (re-exported from `multimodal_association`). No "independent" value,
    # matching `VisitAssociationModel`'s own convention.
    tier: Mapped[str] = mapped_column(String, nullable=False)
    overlap_ms: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    gap_ms: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    # "matching_area_name" | "unknown" -- see `cross_camera_association.
    # SpatialSignal`. Never "differing_area_name" here: that case is dropped
    # before a row is ever created (see `evaluate_cross_camera_association`'s
    # own docstring), consistent with "only positive findings are
    # persisted," above. Persisted (unlike taxon agreement) because,
    # together with `tier`, it is *why* a pair reached its tier --
    # diagnostic and review-facing honesty, not a fact that goes stale the
    # way a re-suggested species label would.
    spatial_signal: Mapped[str] = mapped_column(String, nullable=False)
    # Two concurrent subjects on either camera made the pairing inherently
    # ambiguous (Phase J) -- kept alongside `spatial_signal` for the same
    # read-time-honesty reason.
    multi_subject: Mapped[bool] = mapped_column(Boolean, nullable=False, default=False)
    engine_version: Mapped[str] = mapped_column(String, nullable=False)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)


class CameraNodeTransportIngestionModel(Base):
    """Appliance / Storage / Privacy / Recovery v1, Phase E (schema 48; see
    docs/appliance-storage-privacy-recovery-v1-contract.md "Remote-transport
    host-file lifecycle"): the durable, idempotent record that one completed
    Camera Node WAN-transport item (see
    `mockingbird.storage.camera_node_transport_ledger.TransportLedger`) has
    been consumed into a `MediaAssetModel`.

    This closes a standing gap: before this table existed, a transport item
    reaching `complete()` had a durable filesystem home
    (`<transport_root>/<node_id>/completed/<item_id>.bin`) but nothing
    durable recorded whether it had ever been turned into product evidence.
    Since the Camera Node deletes its own spooled copy immediately on ack
    (`mockingbird_node.transport_worker`), that completed blob is the *only*
    surviving copy -- a consumer that could crash between "MediaAsset
    created" and "blob deleted" needed its own idempotency record, not a
    second, parallel Observation/Evidence authority path.

    Keyed `(node_id, item_id)` -- the same idempotency pair the transport
    protocol itself already uses. `media_asset_id` is set only on a
    successful ingest; `blob_deleted_at` is set only after the transport
    ledger's own completed blob has actually been removed, so a process
    killed between the two commits safely resumes by only finishing the
    delete, never re-ingesting the same bytes as a second MediaAsset. A
    `status="failed"` row with `error_reason="unattributed_source"` (no
    configured Source currently claims this `node_id`, even accounting for
    a recent Camera Node replacement) is deliberately retried on every
    sweep rather than ever silently dropped -- see
    `ProductRepository.consume_camera_node_transport_item`.
    """

    __tablename__ = "camera_node_transport_ingestions"
    __table_args__ = (
        UniqueConstraint("node_id", "item_id", name="uq_camera_node_transport_ingestion_item"),
        Index("ix_camera_node_transport_ingestions_status", "status"),
    )

    id: Mapped[str] = mapped_column(String, primary_key=True)
    node_id: Mapped[str] = mapped_column(String, nullable=False)
    item_id: Mapped[str] = mapped_column(String, nullable=False)
    source_id: Mapped[str | None] = mapped_column(ForeignKey("camera_sources.id"), nullable=True)
    content_sha256: Mapped[str] = mapped_column(String, nullable=False)
    content_length: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    # "pending" (attempt in progress) | "ingested" (a MediaAsset now exists,
    # see `media_asset_id`) | "failed" (see class docstring).
    status: Mapped[str] = mapped_column(String, nullable=False)
    media_asset_id: Mapped[str | None] = mapped_column(ForeignKey("media_assets.id"), nullable=True)
    error_reason: Mapped[str | None] = mapped_column(String, nullable=True)
    attempt_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    blob_deleted_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)


class SourceProviderConfigurationModel(Base):
    __tablename__ = "source_provider_configurations"

    source_id: Mapped[str] = mapped_column(ForeignKey("camera_sources.id"), primary_key=True)
    provider_key: Mapped[str] = mapped_column(String, nullable=False)
    config_json: Mapped[str] = mapped_column(Text, nullable=False)
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)


class ObservationAuthoritySettingsModel(Base):
    """One durable Stage 7 authority-mode row *per Stream* (see
    docs/candidate-visit-authority-contract.md, "Session/Stream scope").
    Never seeded by a schema migration -- `ProductRepository` lazily creates
    one, defaulted to `shadow`, the first time a given Stream's authority
    state is read or written, so an upgraded installation never silently
    gains candidate authority.

    Visit Authority Budget + Ambiguous-Boundary Recall Closure v1: this row
    used to be a single global singleton (`singleton_id=1`) shared by every
    Stream -- a real, demonstrated defect (2026-08-19 field session): one
    Stream's Stop silently reverted a different, still-running Stream's
    authority to shadow, and the session/hourly candidate-budget count was a
    cross-Stream total despite the name. Real Streams each own an
    independent Start/Stop Observation control (see
    docs/observation-engine-product-control-contract.md), so the durable
    authority state they each govern must be independently scoped too."""

    __tablename__ = "observation_authority_settings"
    __table_args__ = (
        CheckConstraint(
            "mode IN ('shadow', 'candidate_visit')",
            name="ck_observation_authority_mode",
        ),
    )

    stream_id: Mapped[str] = mapped_column(ForeignKey("streams.id"), primary_key=True)
    mode: Mapped[str] = mapped_column(String, nullable=False)
    # Deterministic activation/start fact: set fresh every time `mode`
    # transitions shadow -> candidate_visit, cleared back to `None` whenever
    # it transitions candidate_visit -> shadow (the kill switch). Only a
    # proposal observed at or after this timestamp may ever create a
    # candidate -- see "Activation boundary" in the contract doc.
    activation_boundary_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)
    max_candidates_per_session: Mapped[int] = mapped_column(Integer, nullable=False)
    max_candidates_per_hour: Mapped[int] = mapped_column(Integer, nullable=False)
    max_evidence_items_per_candidate: Mapped[int] = mapped_column(Integer, nullable=False)
    max_evidence_bytes_per_candidate: Mapped[int] = mapped_column(Integer, nullable=False)
    # Bounded, read-only, restart-durable diagnostics (see "Diagnostics" in
    # the contract doc). Every counter is monotonic for the lifetime of the
    # installation; only `activation_boundary_at` resets a rate window.
    proposals_observed_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    candidates_attempted_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    candidates_created_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    idempotent_repeat_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    suppressed_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    failure_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    last_failure_code: Mapped[str | None] = mapped_column(String, nullable=True)
    last_failure_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)
    last_candidate_visit_id: Mapped[str | None] = mapped_column(String, nullable=True)
    last_proposal_id: Mapped[str | None] = mapped_column(String, nullable=True)
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    # Site-Specific Learning & Local Adaptation v1 (schema 53, see
    # docs/scene-confusor-suspicion-contract.md, "Reset / disable"): the
    # operator-facing production-activation control, scoped to only the new
    # reviewed-negative-evidence suspicion path -- `False` (the default, see
    # below) leaves exactly this Stream's pre-milestone shipped scene-
    # confusor behavior in production (unreviewed occurrence-count
    # recurrence only), while every already-accumulated `reviewed_real_
    # count`/`reviewed_false_count` on this Stream's own regions still
    # accumulates, and remains fully visible to status/counterfactual
    # reporting, regardless of this flag. Distinct from "Reset local
    # learning" (`purge_scene_confusor_regions_for_stream`), which deletes
    # region history outright.
    #
    # Acceptance correction (2026-08-24): defaults `False`, not `True`.
    # `min_reviewed_false_to_suspect` (see `scene_confusor.
    # DEFAULT_MIN_REVIEWED_FALSE_TO_SUSPECT`) is disclosed as a candidate
    # threshold pending organic field validation, not a field-validated one
    # (this repository's own real local database has zero organic
    # `scene_confusor_regions` history to have validated it against) -- a
    # `True` default would have let an unvalidated threshold begin
    # influencing production admission the moment any Stream's own future
    # field use happened to produce two authority-eligible `false_positive`
    # reviews at the same geometry, with no explicit operator decision ever
    # made. `False` requires that decision to be explicit (see
    # `set_scene_confusor_reviewed_evidence_enabled`) -- an operator running
    # local field testing can still turn it on per-Stream at any time; nothing
    # about the mechanism's own accumulation, provenance, reversibility, or
    # reporting depends on this flag. Unlike this file's usual "nullable, no
    # backfill, honest absence" convention (there is no honest "unknown"
    # state for an on/off control -- it must always read as one or the
    # other): `server_default` in addition to the ORM-level `default` so a
    # freshly created table (`Base.metadata.create_all`) and a migrated one
    # (this column's own `ALTER TABLE ... DEFAULT 0`) carry an identical real
    # schema-level default, not just an ORM-level one -- correct for any
    # raw-SQL insert that omits this column too, not only ordinary
    # `session.add(...)` construction.
    scene_confusor_reviewed_evidence_enabled: Mapped[bool] = mapped_column(
        Boolean, nullable=False, default=False, server_default=text("0"),
    )


class ObservationCandidateVisitModel(Base):
    """Durable Stage 7 idempotency and lineage ledger: exactly one row per
    assembled shadow proposal that has ever become a candidate Visit.

    `proposal_id` is the primary key and *is* the durable idempotency key --
    `visit_episode_assembler.AssembledVisitProposal.proposal_id` is already
    a deterministic sha256 of the assembler version plus sorted constituent
    generation ids (see docs/tracklet-visit-assembly-contract.md), so it is
    stable across retry, process restart, reconnect, replayed frames, and
    repeated finalization without this table inventing a second identity."""

    __tablename__ = "observation_candidate_visits"
    __table_args__ = (
        UniqueConstraint("visit_id", name="uq_observation_candidate_visit_visit"),
        Index("ix_observation_candidate_visits_created_at", "created_at"),
    )

    proposal_id: Mapped[str] = mapped_column(String, primary_key=True)
    visit_id: Mapped[str] = mapped_column(ForeignKey("visits.id"), nullable=False)
    event_id: Mapped[str] = mapped_column(ForeignKey("events.id"), nullable=False)
    stream_id: Mapped[str] = mapped_column(ForeignKey("streams.id"), nullable=False)
    zone_id: Mapped[str | None] = mapped_column(ForeignKey("zones.id"), nullable=True)
    broad_class: Mapped[str] = mapped_column(String, nullable=False)
    start_offset_ms: Mapped[int] = mapped_column(Integer, nullable=False)
    end_offset_ms: Mapped[int] = mapped_column(Integer, nullable=False)
    assembler_version: Mapped[str] = mapped_column(String, nullable=False)
    authority_gate_version: Mapped[str] = mapped_column(String, nullable=False)
    detector_provenance: Mapped[str | None] = mapped_column(String, nullable=True)
    tracker_provenance: Mapped[str | None] = mapped_column(String, nullable=True)
    provider_key: Mapped[str | None] = mapped_column(String, nullable=True)
    # Full lineage, stored as bounded JSON arrays -- this ledger row, not the
    # Visit/Event/MediaAsset rows it points at, is the authoritative record
    # of "which tracklets/frames/evidence produced this candidate."
    constituent_generation_ids_json: Mapped[str] = mapped_column(Text, nullable=False)
    constituent_track_ids_json: Mapped[str] = mapped_column(Text, nullable=False)
    source_capture_frame_ids_json: Mapped[str] = mapped_column(Text, nullable=False)
    # Ordinary per-track frame identity -- see the matching field note on
    # `CandidateVisitProposalFacts` above. Additive, defaults to an empty
    # JSON array so it is safe for any pre-existing empty ledger table.
    supporting_frame_ids_json: Mapped[str] = mapped_column(Text, nullable=False, default="[]")
    evidence_candidate_ids_json: Mapped[str] = mapped_column(Text, nullable=False)
    selected_identification_media_asset_id: Mapped[str | None] = mapped_column(String, nullable=True)
    selected_context_media_asset_id: Mapped[str | None] = mapped_column(String, nullable=True)
    persisted_media_asset_ids_json: Mapped[str] = mapped_column(Text, nullable=False, default="[]")
    limitation_facts_json: Mapped[str] = mapped_column(Text, nullable=False, default="[]")
    ambiguous_adjacent_proposal_ids_json: Mapped[str] = mapped_column(Text, nullable=False, default="[]")
    # Multi-Subject Visit Assembly & Review v1, Phase 2 (schema 36, see
    # docs/multi-subject-visit-assembly-review-v1.md): the proposal's own
    # `concurrent_sibling_proposal_ids` as of the moment *this* candidate was
    # created -- diagnostic lineage only, never re-read to decide grouping
    # for a *different* candidate (that lookup queries this table by
    # `proposal_id`, the primary key, directly; see `_create_candidate_visit_
    # locked`). Nullable with no default: a row created before this concept
    # existed reads back `None`, never a fabricated relationship.
    concurrent_sibling_proposal_ids_json: Mapped[str | None] = mapped_column(Text, nullable=True)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    # Detection Quality Accounting v1 (schema 31, see
    # docs/detection-quality-accounting-contract.md): one serialized
    # `contracts.ConfidenceEvidenceSummary` JSON object -- diagnostic
    # detector-confidence/evidence lineage for this candidate, never
    # reviewed truth or observational authority. Nullable with no default:
    # every row created before this column existed reads back `None`
    # rather than a fabricated summary (see "no fabricated confidence for
    # legacy records" in product-doctrine.md).
    confidence_evidence_json: Mapped[str | None] = mapped_column(Text, nullable=True)


class SceneConfusorRegionModel(Base):
    """Durable, per-Stream recurring-geometry history backing the scene-
    confusor suspicion mechanism (schema 34, see
    docs/scene-confusor-suspicion-contract.md). Distinct in kind from the
    in-memory-only, per-session `burst_scheduler._RecurrenceGroup` and
    `temporal_capture.RecurringGeometryTracker`: this is the one place in
    the whole Observation Engine v2 tree that remembers recurring
    candidate geometry *across* sessions and app restarts, which is exactly
    what a persistent scene confusor (a shadow, a feeder-silhouette
    texture) requires -- those in-memory precedents are reset on every
    Stop/Start and would never build cross-session suspicion at all.

    `id` is a stable, content-addressed identity
    (`scene_confusor.region_fingerprint`) -- deterministic from
    `(stream_id, broad_class, rounded representative_box)`, never a
    session/process identity, so it survives restarts unlike
    `burst_scheduler`'s own in-memory group id. Diagnostic evidence only:
    nothing here is reviewed truth, and nothing here can be read as proof
    an animal was or was not present -- see `evaluate_scene_confusor_
    suspicion`'s own docstring for the decision this table's rows feed."""

    __tablename__ = "scene_confusor_regions"
    __table_args__ = (
        Index("ix_scene_confusor_regions_stream_updated", "stream_id", "updated_at"),
    )

    id: Mapped[str] = mapped_column(String, primary_key=True)
    stream_id: Mapped[str] = mapped_column(ForeignKey("streams.id"), nullable=False)
    broad_class: Mapped[str] = mapped_column(String, nullable=False)
    representative_box_json: Mapped[str] = mapped_column(Text, nullable=False)
    representative_area: Mapped[float] = mapped_column(Float, nullable=False)
    # How many admission attempts (created *or* blocked -- every one that
    # reached this check) have ever matched this region's own geometry.
    # The primary recurrence signal; never reset except by explicit
    # reconfiguration invalidation (see `purge_scene_confusor_regions_
    # for_stream`) or bounded per-Stream eviction (`max_regions_per_
    # stream`).
    occurrence_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    # How many of those attempts this mechanism actually suspected/blocked
    # -- a bounded diagnostic count, never itself part of the decision
    # (the decision reads `occurrence_count`/spread/review counts only).
    suspected_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    # Reviewed-truth interaction (see "Reviewed-truth interaction" in the
    # contract doc): incremented only from an authority-eligible ReviewLabel
    # (`review_provenance.is_authority_eligible`) on a Visit whose own
    # persisted evidence geometry matches this region. `reviewed_real_count
    # > 0` is unconditional, permanent protection -- see
    # `evaluate_scene_confusor_suspicion`. `reviewed_false_count` only ever
    # strengthens the reason disclosed to a reviewer; it is never required
    # for suspicion (most real confusors accumulate no review at all).
    reviewed_real_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    reviewed_false_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    max_confidence_observed: Mapped[float | None] = mapped_column(Float, nullable=True)
    # Cheap, O(1)-per-touch running bounds backing `centroid_spread` (see
    # `scene_confusor.update_region_bounds`) -- a bounded envelope, never a
    # retained per-occurrence history, matching this package's own
    # established "bounded structured facts, not full history" convention.
    centroid_min_x: Mapped[float] = mapped_column(Float, nullable=False)
    centroid_min_y: Mapped[float] = mapped_column(Float, nullable=False)
    centroid_max_x: Mapped[float] = mapped_column(Float, nullable=False)
    centroid_max_y: Mapped[float] = mapped_column(Float, nullable=False)
    first_observed_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    last_observed_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    updated_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)


class RecordedMediaAnalysisRunModel(Base):
    """Bounded progress/diagnostics and idempotency record for one offline
    recorded-video analysis attempt (schema 41, Offline / Recorded
    Observation Ingest v1). See docs/offline-recorded-media-observation-
    contract.md "Progress and diagnostics" / "Idempotency".

    This table is operational history, mirroring `MonitoringExposureInterval
    Model`'s own "operational history, never evidence" framing -- it never
    itself creates or gates a Visit/Event/MediaAsset (the same, unmodified
    candidate-Visit admission boundary still decides that); it only records
    *that* one bounded processing attempt happened, its outcome, and enough
    bounded counts for `GET .../analysis-runs/{id}` to answer "queued /
    processing / completed / failed" honestly without per-frame log spam.

    `(media_asset_id, pipeline_version)` is the idempotency key a caller
    checks before starting real work: a prior `completed` row for the exact
    same pair means "already processed under this pipeline," never silently
    duplicated; a caller explicitly requesting re-analysis under a newer
    detector/tracker/assembler build supplies a different `pipeline_version`
    string instead, which is a legitimate, distinct row, not a duplicate."""

    __tablename__ = "recorded_media_analysis_runs"
    __table_args__ = (
        CheckConstraint(
            "status IN ('queued', 'processing', 'completed', 'failed')",
            name="ck_recorded_media_analysis_run_status",
        ),
        Index(
            "ix_recorded_media_analysis_runs_asset_pipeline",
            "media_asset_id",
            "pipeline_version",
        ),
    )

    id: Mapped[str] = mapped_column(String, primary_key=True)
    media_asset_id: Mapped[str] = mapped_column(ForeignKey("media_assets.id"), nullable=False)
    stream_id: Mapped[str] = mapped_column(ForeignKey("streams.id"), nullable=False)
    # A stable identity for "which detector/tracker/assembler build produced
    # this run" -- never a raw model file path. Two rows sharing this value
    # for the same `media_asset_id` are the same idempotent attempt; a
    # different value is an explicit, legitimate re-analysis (see "Idempotent
    # vs. explicit reprocessing" in docs/offline-recorded-media-observation-
    # contract.md).
    pipeline_version: Mapped[str] = mapped_column(String, nullable=False)
    status: Mapped[str] = mapped_column(String, nullable=False)
    sample_fps: Mapped[float] = mapped_column(Float, nullable=False)
    source_duration_seconds: Mapped[float | None] = mapped_column(Float, nullable=True)
    frames_considered: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    frames_analyzed: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    events_created: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    visits_created: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    # A small, fixed-vocabulary code (see "Error taxonomy" in the contract
    # doc) -- `None` for a `queued`/`processing`/`completed` row. Never a
    # raw filesystem path or subprocess stderr.
    error_code: Mapped[str | None] = mapped_column(String, nullable=True)
    error_message: Mapped[str | None] = mapped_column(Text, nullable=True)
    started_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    completed_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)


class AcousticAnalysisRunModel(Base):
    """Bounded progress/diagnostics and idempotency record for one BirdNET
    analysis attempt over one audio `MediaAsset` (schema 43, Acoustic /
    BirdNET Observation Foundation v1). See docs/acoustic-birdnet-
    observation-foundation-v1-contract.md.

    Mirrors `RecordedMediaAnalysisRunModel` deliberately: same "operational
    history, never evidence" framing (this table never itself creates or
    gates a Visit/Event/SpeciesSuggestion -- `acoustic_ingest.py`'s own
    bounded admission path does that; this table only records *that* one
    bounded analysis attempt happened, its outcome, and enough bounded
    counts to answer "queued / processing / completed / failed" honestly).

    A completed run with `detections_above_threshold=0` is not a failure --
    it is the honest "BirdNET ran and found nothing" outcome the milestone
    doctrine requires be representable (abstention/no-detection are
    legitimate outcomes, never silently dropped or conflated with an error).

    `(media_asset_id, pipeline_version)` is the same idempotency key
    `RecordedMediaAnalysisRunModel` uses, for the same reason: a prior
    `completed` row for the exact same pair means "already analyzed under
    this model/config," never silently duplicated; explicit re-analysis
    under a materially different BirdNET model/config supplies a different
    `pipeline_version` string instead.

    Acoustic Runtime & Quality v1 (schema 44) additively turns this same row
    into a durable queue entry, not just an attempt log: a row can now be
    inserted `queued` (never analyzed yet) instead of always `processing`,
    and four new nullable columns (`consecutive_failure_count`,
    `next_retry_at`, `claimed_by`, `claimed_at`) carry bounded retry/backoff
    and a crash-safe ownership token -- mirroring `StreamRuntimeCheckpoint
    Model`'s established `consecutive_failure_count`/`next_retry_at`
    columns, adapted to per-item (not per-Stream) granularity. See
    `mockingbird.observation.acoustic_runtime` for the reconcile loop that
    reads/writes these.
    """

    __tablename__ = "acoustic_analysis_runs"
    __table_args__ = (
        CheckConstraint(
            "status IN ('queued', 'processing', 'completed', 'failed')",
            name="ck_acoustic_analysis_run_status",
        ),
        Index(
            "ix_acoustic_analysis_runs_asset_pipeline",
            "media_asset_id",
            "pipeline_version",
        ),
        Index(
            "ix_acoustic_analysis_runs_status_created",
            "status",
            "created_at",
        ),
    )

    id: Mapped[str] = mapped_column(String, primary_key=True)
    media_asset_id: Mapped[str] = mapped_column(ForeignKey("media_assets.id"), nullable=False)
    stream_id: Mapped[str] = mapped_column(ForeignKey("streams.id"), nullable=False)
    # A stable identity for "which BirdNET model/runtime/config produced
    # this run" -- never a raw model file path. See `pipeline_version` on
    # `RecordedMediaAnalysisRunModel` for the identical discipline.
    pipeline_version: Mapped[str] = mapped_column(String, nullable=False)
    status: Mapped[str] = mapped_column(String, nullable=False)
    min_confidence: Mapped[float] = mapped_column(Float, nullable=False)
    source_duration_seconds: Mapped[float | None] = mapped_column(Float, nullable=True)
    windows_analyzed: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    detections_above_threshold: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    species_suggestions_created: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    events_created: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    visits_created: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    # A small, fixed-vocabulary code -- `None` for a `queued`/`processing`/
    # `completed` row. Never a raw filesystem path or subprocess stderr.
    error_code: Mapped[str | None] = mapped_column(String, nullable=True)
    error_message: Mapped[str | None] = mapped_column(Text, nullable=True)
    started_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    completed_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)
    created_at: Mapped[datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    # Schema 44 (Acoustic Runtime & Quality v1) -- bounded retry/backoff and
    # a crash-safe claim token; see the class docstring above.
    consecutive_failure_count: Mapped[int] = mapped_column(Integer, nullable=False, default=0)
    next_retry_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)
    claimed_by: Mapped[str | None] = mapped_column(String, nullable=True)
    claimed_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), nullable=True)


def _acoustic_analysis_run_from_model(row: AcousticAnalysisRunModel) -> AcousticAnalysisRun:
    """Pure projection: durable row -> the read-only API/CLI shape."""

    return AcousticAnalysisRun(
        id=row.id,
        media_asset_id=row.media_asset_id,
        stream_id=row.stream_id,
        pipeline_version=row.pipeline_version,
        status=row.status,
        min_confidence=row.min_confidence,
        source_duration_seconds=row.source_duration_seconds,
        windows_analyzed=row.windows_analyzed,
        detections_above_threshold=row.detections_above_threshold,
        species_suggestions_created=row.species_suggestions_created,
        events_created=row.events_created,
        visits_created=row.visits_created,
        error_code=row.error_code,
        error_message=row.error_message,
        started_at=row.started_at,
        completed_at=row.completed_at,
        created_at=row.created_at,
        consecutive_failure_count=row.consecutive_failure_count,
        next_retry_at=row.next_retry_at,
        claimed_by=row.claimed_by,
        claimed_at=row.claimed_at,
    )


