def _scene_confusor_snapshot_from_model(row: SceneConfusorRegionModel) -> SceneRegionSnapshot:
    """Pure projection: durable row -> the small snapshot the pure
    `scene_confusor` decision module actually reads. Mirrors every other
    `_x_from_model` projection already used throughout this file."""

    return SceneRegionSnapshot(
        region_id=row.id,
        representative_box=tuple(json.loads(row.representative_box_json)),
        representative_area=row.representative_area,
        broad_class=row.broad_class,
        occurrence_count=row.occurrence_count,
        reviewed_real_count=row.reviewed_real_count,
        reviewed_false_count=row.reviewed_false_count,
        max_confidence_observed=row.max_confidence_observed,
        centroid_min=(row.centroid_min_x, row.centroid_min_y),
        centroid_max=(row.centroid_max_x, row.centroid_max_y),
    )


def _max_confidence_from_evidence_json(confidence_evidence_json: str | None) -> float | None:
    """Reads only `max_confidence` from an already-serialized
    `contracts.ConfidenceEvidenceSummary` JSON blob -- the one field the
    scene-confusor mechanism's own `stronger_confidence` escape needs.
    `None` for a missing, empty, or malformed payload (a legacy proposal,
    or one whose confidence lineage was never retained), never a
    fabricated value -- the same honesty rule every other confidence-
    evidence reader in this codebase already follows."""

    if not confidence_evidence_json:
        return None
    try:
        payload = json.loads(confidence_evidence_json)
    except (TypeError, ValueError):
        return None
    if not isinstance(payload, dict):
        return None
    value = payload.get("max_confidence")
    return float(value) if isinstance(value, (int, float)) else None


@dataclass(frozen=True)
class CameraConfigurationApplyResult:
    revision: CameraConfigurationRevision
    preview: CameraConfigurationImpactPreview
    idempotent: bool
    # True only for the one transaction that just confirmed a Camera Node
    # hardware replacement -- an in-process fact, deliberately not derived
    # from comparing persisted timestamps after a round trip through
    # SQLite's `DateTime(timezone=True)` (which does not preserve tzinfo;
    # see doctor.py's own documented convention for that exact gotcha).
    # Always False for an idempotent replay, matching every other field here.
    hardware_replacement_just_confirmed: bool = False


# =============================================================================
# Stage 7: candidate-Visit authority (see docs/candidate-visit-authority-
# contract.md). These request/response shapes are deliberately plain,
# repository-level dataclasses -- never the observation engine's own
# `AssembledVisitProposal`/`EvidenceCandidate`/`EvidenceSelection` types --
# so `product_repository.py` needs nothing from `visit_episode_assembler.py`
# or `evidence_scoring.py` beyond the shared pure `candidate_visit_authority`
# gate. The adapter module (`mockingbird.observation.candidate_visit_adapter`)
# is the one place that translates an engine-side proposal into this shape.
# =============================================================================


@dataclass(frozen=True)
class CandidateEvidenceItem:
    """One already-selected, already-bounded evidence item ready to persist.

    `engine_media_id` is the shadow engine's own transient identity (for
    example `"shadow-burst:<content_hash>"`); it becomes provenance on the
    persisted MediaAsset, never the persisted record's own id."""

    engine_media_id: str
    role: str  # "identification" | "context" | "alternate"
    content: bytes
    content_type: str
    width: int | None
    height: int | None
    captured_at: datetime | None
    subject_geometry: tuple[float, float, float, float] | None
    # Localization Attribution / Detection Geometry Lineage v1 (see
    # docs/localization-attribution-contract.md): a pre-serialized JSON
    # `contracts.GeometryAttribution` explaining where `subject_geometry`
    # came from, serialized by the caller (`candidate_visit_adapter`, the
    # one place that already imports the engine-side `EvidenceCandidate`)
    # rather than this repository-level dataclass importing an
    # observation-engine type -- the same boundary `CandidateVisitProposalFacts.
    # confidence_evidence_json` already establishes. `None` for a caller that
    # predates this field; never fabricated for a legacy record.
    geometry_attribution_json: str | None = None


@dataclass(frozen=True)
class CandidateVisitProposalFacts:
    """A plain, repository-level projection of one assembled shadow
    proposal -- structurally satisfies `candidate_visit_authority.
    ProposalLineage`, so the same shared gate function re-checks it inside
    the repository's own transaction without importing the assembler."""

    proposal_id: str
    stream_id: str
    zone_id: str | None
    broad_class: str
    start_offset_ms: int
    end_offset_ms: int
    constituent_generation_ids: tuple[str, ...]
    constituent_track_ids: tuple[str, ...]
    source_capture_frame_ids: tuple[str, ...]
    evidence_candidate_ids: tuple[str, ...]
    limitation_facts: tuple[str, ...]
    ambiguous_adjacent_proposal_ids: tuple[str, ...]
    assembler_version: str
    # Multi-Subject Visit Assembly & Review v1, Phase 2 (see
    # docs/multi-subject-visit-assembly-review-v1.md): copied verbatim from
    # `AssembledVisitProposal.concurrent_sibling_proposal_ids` by the adapter
    # -- never recomputed here, matching `ambiguous_adjacent_proposal_ids`'s
    # own boundary-crossing convention. Names every other proposal this one
    # was classified `incompatible`/`temporal_overlap` against (genuinely
    # concurrent, distinct subjects sharing one encounter) -- structurally
    # disjoint from `ambiguous_adjacent_proposal_ids` above, never the same
    # relationship. Defaults `()`, matching `AssembledVisitProposal`'s own
    # default, so a caller that predates this field is unaffected.
    concurrent_sibling_proposal_ids: tuple[str, ...] = ()
    # Ordinary per-track frame identity (Stage 4+, always populated live or
    # replay) -- distinct from `source_capture_frame_ids` (Stage 6.14's
    # reviewed-source identity, only ever populated when a proposal was
    # assembled from a temporal-review/replay pipeline). A genuine live
    # session has no reviewed-source identity to carry; this field is what
    # actually proves live frame lineage. See "Lineage validity" in
    # docs/candidate-visit-authority-contract.md.
    supporting_frame_ids: tuple[str, ...] = ()
    detector_provenance: str | None = None
    tracker_provenance: str | None = None
    provider_key: str | None = None
    # Detection Quality Accounting v1 (see
    # docs/detection-quality-accounting-contract.md): a pre-serialized JSON
    # `contracts.ConfidenceEvidenceSummary` -- serialized by the caller
    # (`candidate_visit_adapter`, the one place that already imports the
    # engine-side `AssembledVisitProposal`) rather than this repository-level
    # dataclass importing an observation-engine type. `None` for a caller
    # that predates this field; never fabricated for a legacy record.
    confidence_evidence_json: str | None = None
    # Visit Continuity / Provisional Admission Fix v1 (see
    # docs/tracklet-visit-assembly-contract.md "Episode finality"): copied
    # verbatim from `AssembledVisitProposal.continuation_pending` by the
    # adapter, exactly how `ambiguous_adjacent_proposal_ids` already crosses
    # this same engine-side/repository-side boundary -- lets `evaluate_
    # candidate_authority`'s transactional re-check see it without this
    # dataclass importing the assembler. Defaults `False` for a caller that
    # predates this field, matching `AssembledVisitProposal`'s own default.
    continuation_pending: bool = False
    # Ambiguous boundary arbitration (see "Ambiguous boundary arbitration"
    # in docs/tracklet-visit-assembly-contract.md): an explicit,
    # caller-supplied fact -- never recomputed inside the repository, which
    # has no visibility into sibling proposals -- set only by a tick-loop
    # caller that already ran `candidate_visit_authority.resolve_ambiguous_
    # boundary_arbitration` over the full current tick and confirmed this
    # exact proposal is the single best-evidenced, fully-stabilized member
    # of its own ambiguous cluster. Defaults `False`, matching every other
    # additive fact on this dataclass -- an ordinary non-ambiguous proposal,
    # or a caller that predates this field, is entirely unaffected.
    ambiguous_boundary_resolved: bool = False


@dataclass(frozen=True)
class CreateCandidateVisitRequest:
    proposal: CandidateVisitProposalFacts
    observed_at: datetime
    evidence_items: tuple[CandidateEvidenceItem, ...] = ()
    limits: AuthorityLimits | None = None


@dataclass(frozen=True)
class AcousticDetectionFacts:
    """One BirdNET-positive analysis window -- the minimal facts needed to
    create an acoustic candidate Visit (Acoustic / BirdNET Observation
    Foundation v1). Deliberately provider-neutral by type (not a
    `birdnet_adapter` dataclass), mirroring
    `CandidateVisitProposalFacts`'s identical role for the visual path:
    the repository layer never imports adapter-specific types."""

    common_name: str
    scientific_name: str | None
    confidence: float
    window_start_ms: int
    window_end_ms: int


@dataclass(frozen=True)
class AcousticCandidateVisitOutcome:
    """Always returned, never raised, for an ordinary idempotent-repeat
    outcome -- mirrors `CandidateVisitCreationOutcome`'s identical
    contract. `outcome` is `"created"`, `"idempotent_repeat"`, `"extended"`
    (Acoustic Runtime & Quality v1 cross-segment consolidation -- see
    `extend_acoustic_candidate_visit`), or `"not_extendable"` (the target
    Visit was reviewed/superseded between the caller's lookup and this call;
    the caller must fall back to `create_acoustic_candidate_visit`)."""

    outcome: str
    visit_id: str | None
    event_id: str | None
    species_suggestion_id: str | None


#: Acoustic Runtime & Quality v1 -- bounded retry budget shared by both the
#: crash-recovery reclaim path (`reclaim_stale_acoustic_analysis_work`) and
#: the live-failure path (`retry_or_fail_acoustic_analysis_run`), so the two
#: can never silently disagree about when a segment gives up for good.
#: Mirrors `durable_supervisor.DEFAULT_MAX_CONSECUTIVE_FAILURES`/`DEFAULT_
#: RETRY_DELAYS_SECONDS`'s identical shape (fixed ladder, not an exponential
#: formula) -- deliberately reusing the same small numbers this codebase
#: already validated for Camera Node reconnect backoff, rather than
#: inventing a second bounded-retry convention. Noted during review: with
#: `max_attempts=3`, `_apply_acoustic_retry_decision` only ever indexes the
#: ladder's first two entries (5s, 30s) before terminating on the third
#: failure -- the 120s entry is unreachable. This is the exact same shape
#: `durable_supervisor._recover_from_failure` already has with its own
#: `DEFAULT_MAX_CONSECUTIVE_FAILURES=3`/`DEFAULT_RETRY_DELAYS_SECONDS=
#: (5,30,120)` (an accepted, shipped precedent) -- kept identical rather
#: than deviated from here, not re-litigated by this milestone.
ACOUSTIC_RETRY_MAX_ATTEMPTS = 3
ACOUSTIC_RETRY_BACKOFF_SECONDS: tuple[float, ...] = (5.0, 30.0, 120.0)


@dataclass(frozen=True)
class AcousticQueueDiagnostics:
    """Bounded, always-derived-from-durable-rows runtime snapshot (Phase J)
    -- never a separately maintained in-memory counter that could drift
    from what the database actually holds."""

    queued_count: int
    processing_count: int
    oldest_queued_age_seconds: float | None
    recent_failure_count_24h: int
    recent_capacity_evicted_count_24h: int


@dataclass(frozen=True)
class AcousticRetentionSweepResult:
    """The bounded outcome of one `run_working_audio_retention_sweep` pass."""

    deleted_count: int
    failed_count: int
    considered_count: int


def _apply_acoustic_retry_decision(
    row: AcousticAnalysisRunModel,
    *,
    now: datetime,
    max_attempts: int,
    backoff_seconds_ladder: tuple[float, ...],
    error_code: str,
    error_message: str,
) -> str:
    """Shared bounded-retry decision, mutating `row` in place within the
    caller's already-open transaction. Returns `"requeued"` or `"failed"`.
    The one place this decision is made -- both `reclaim_stale_acoustic_
    analysis_work` (crash/stall recovery) and `retry_or_fail_acoustic_
    analysis_run` (a live, caught failure) call this instead of each
    re-implementing the backoff ladder, so a future change to the retry
    budget can never accidentally apply to only one of the two paths."""

    failure_count = row.consecutive_failure_count + 1
    if failure_count >= max_attempts:
        row.status = "failed"
        row.error_code = error_code
        row.error_message = error_message
        row.completed_at = now
        row.consecutive_failure_count = failure_count
        row.next_retry_at = None
        row.claimed_by = None
        row.claimed_at = None
        return "failed"
    delay_seconds = backoff_seconds_ladder[min(failure_count - 1, len(backoff_seconds_ladder) - 1)]
    row.status = "queued"
    row.consecutive_failure_count = failure_count
    row.next_retry_at = now + timedelta(seconds=delay_seconds)
    row.claimed_by = None
    row.claimed_at = None
    row.error_code = error_code
    row.error_message = error_message
    return "requeued"


