    def stream_privacy_ignore_regions(
        self, stream_id: str,
    ) -> tuple[tuple[float, float, float, float], ...]:
        """Side-effect-free: this Stream's active Privacy/Ignore Zones as
        normalized axis-aligned bounding boxes, for a caller that needs a
        bounded exclusion-region shape (for example
        `observation.camera_node_live.CameraNodeAnalysisSource.
        analysis_excluded_regions`) rather than a polygon. A bounding box is
        never smaller than the drawn polygon, so this stays conservative in
        the safe direction -- it can only exclude more area than the user
        drew, never less."""

        with self.session_factory() as session:
            zones = session.scalars(
                select(ZoneModel).where(
                    ZoneModel.stream_id == stream_id,
                    ZoneModel.zone_type.in_((ZoneType.privacy.value, ZoneType.ignore.value)),
                    ZoneModel.is_active.is_(True),
                )
            ).all()
            regions: list[tuple[float, float, float, float]] = []
            for zone in zones:
                try:
                    points = json.loads(zone.polygon_json)
                except (TypeError, json.JSONDecodeError):
                    continue
                if not isinstance(points, list) or len(points) < 3:
                    continue
                xs = [float(point["x"]) for point in points if isinstance(point, dict) and "x" in point]
                ys = [float(point["y"]) for point in points if isinstance(point, dict) and "y" in point]
                if len(xs) != len(points) or len(ys) != len(points):
                    continue
                left, right = max(0.0, min(xs)), min(1.0, max(xs))
                top, bottom = max(0.0, min(ys)), min(1.0, max(ys))
                if right > left and bottom > top:
                    regions.append((left, top, right, bottom))
            return tuple(regions[:64])

    def create_zone(self, payload: ZoneCreate) -> Zone:
        with self.session_factory() as session:
            with session.begin():
                zone = ZoneModel(
                    id=self._next_id(session, ZoneModel, "zone"),
                    stream_id=payload.stream_id,
                    name=payload.name,
                    zone_type=payload.zone_type.value,
                    polygon_json=_points_to_json(payload.polygon),
                    is_active=payload.is_active,
                )
                session.add(zone)
                session.flush()
                return _zone_from_model(zone)

    def update_zone(self, zone_id: str, payload: ZoneUpdate) -> Zone | None:
        with self.session_factory() as session:
            with session.begin():
                zone = session.get(ZoneModel, zone_id)
                if zone is None:
                    return None

                if payload.name is not None:
                    zone.name = payload.name
                if payload.zone_type is not None:
                    zone.zone_type = payload.zone_type.value
                if payload.polygon is not None:
                    zone.polygon_json = _points_to_json(payload.polygon)
                if payload.is_active is not None:
                    zone.is_active = payload.is_active

                session.flush()
                return _zone_from_model(zone)

    def update_zone_monitoring_policy(
        self,
        zone_id: str,
        payload: ZoneMonitoringPolicyUpdate,
    ) -> Zone | None:
        with self.session_factory() as session:
            with session.begin():
                zone = session.get(ZoneModel, zone_id)
                if zone is None:
                    return None
                if ZoneType(zone.zone_type) in {ZoneType.privacy, ZoneType.ignore}:
                    raise ValueError("restricted_zone_monitoring_policy")

                overrides = _zone_monitoring_policy_overrides(zone.monitoring_policy_json)
                overrides.update(payload.model_dump(exclude_none=True, mode="json"))
                zone.monitoring_policy_json = json.dumps(overrides, sort_keys=True)
                session.flush()
                return _zone_from_model(zone)

    def restore_zone_monitoring_policy_defaults(self, zone_id: str) -> Zone | None:
        with self.session_factory() as session:
            with session.begin():
                zone = session.get(ZoneModel, zone_id)
                if zone is None:
                    return None
                if ZoneType(zone.zone_type) in {ZoneType.privacy, ZoneType.ignore}:
                    raise ValueError("restricted_zone_monitoring_policy")
                zone.monitoring_policy_json = None
                session.flush()
                return _zone_from_model(zone)

    def delete_zone(self, zone_id: str) -> tuple[Zone, list[Zone]] | None:
        """Delete only an unreferenced Zone; linked review/evidence context is protected."""

        with self.session_factory() as session:
            with session.begin():
                zone = session.get(ZoneModel, zone_id)
                if zone is None:
                    return None

                linked_counts = (
                    session.scalar(
                        select(func.count(EventModel.id)).where(
                            EventModel.primary_zone_id == zone_id
                        )
                    )
                    or 0,
                    session.scalar(
                        select(func.count(DetectionModel.id)).where(
                            DetectionModel.zone_id == zone_id
                        )
                    )
                    or 0,
                    session.scalar(
                        select(func.count(MotionEvidenceModel.id)).where(
                            MotionEvidenceModel.zone_id == zone_id
                        )
                    )
                    or 0,
                    session.scalar(
                        select(func.count(DetectionProposalModel.id)).where(
                            DetectionProposalModel.zone_id == zone_id
                        )
                    )
                    or 0,
                )
                referenced_by_provider = any(
                    json.loads(configuration.config_json).get("default_zone_id") == zone_id
                    for configuration in session.scalars(
                        select(SourceProviderConfigurationModel)
                    ).all()
                )
                if any(linked_counts) or referenced_by_provider:
                    raise ValueError("zone_has_review_context")

                deleted_zone = _zone_from_model(zone)
                stream_id = zone.stream_id
                session.delete(zone)
                session.flush()
                return deleted_zone, self._zones_for_stream(session, stream_id)

