    def visit_organization(self, visit_id: str) -> VisitOrganizationState:
        with self.session_factory() as session:
            if session.get(VisitModel, visit_id) is None:
                raise ValueError("missing_visit")
            return self._visit_organization_state(session, visit_id)

    def update_visit_organization(
        self, visit_id: str, payload: VisitOrganizationUpdate
    ) -> VisitOrganizationState:
        with self.session_factory() as session:
            with session.begin():
                if session.get(VisitModel, visit_id) is None:
                    raise ValueError("missing_visit")
                model = session.get(VisitOrganizationModel, visit_id)
                current = self._visit_organization_state(session, visit_id, model)
                if model is not None and model.idempotency_key == payload.idempotency_key:
                    return current
                if current.state_token != payload.expected_state_token:
                    raise ValueError("organization_stale")
                note = model.note if model is not None else None
                if payload.note is not None:
                    note = payload.note.strip() or None
                    if any(ord(character) < 32 and character not in "\n\r\t" for character in note or ""):
                        raise ValueError("organization_note_control_character")
                favorite = payload.is_favorite if payload.is_favorite is not None else (model.is_favorite if model else False)
                now = datetime.now(UTC)
                if model is None:
                    model = VisitOrganizationModel(
                        visit_id=visit_id, is_favorite=favorite, note=note,
                        inherited_from_visit_id=None, version=1, created_at=now,
                        updated_at=now, idempotency_key=payload.idempotency_key,
                    )
                    session.add(model)
                else:
                    model.is_favorite = favorite
                    model.note = note
                    model.version += 1
                    model.updated_at = now
                    model.idempotency_key = payload.idempotency_key
                session.flush()
                return self._visit_organization_state(session, visit_id, model)

    def bulk_update_visit_organization(self, payload: VisitOrganizationBulkRequest) -> VisitOrganizationBulkResponse:
        results: list[VisitOrganizationBulkResult] = []
        with self.session_factory() as session:
            with session.begin():
                for visit_id in dict.fromkeys(payload.visit_ids):
                    visit = session.get(VisitModel, visit_id)
                    if visit is None or visit.is_superseded:
                        results.append(VisitOrganizationBulkResult(visit_id=visit_id, status="skipped"))
                        continue
                    model = session.get(VisitOrganizationModel, visit_id)
                    now = datetime.now(UTC)
                    favorite = payload.action.value == "favorite"
                    if model is None:
                        session.add(VisitOrganizationModel(visit_id=visit_id, is_favorite=favorite, note=None, inherited_from_visit_id=None, version=1, created_at=now, updated_at=now, idempotency_key=None))
                    elif model.is_favorite != favorite:
                        model.is_favorite = favorite
                        model.version += 1
                        model.updated_at = now
                    results.append(VisitOrganizationBulkResult(visit_id=visit_id, status="updated"))
        return VisitOrganizationBulkResponse(results=results)

    @staticmethod
    def _visit_organization_state(session: Session, visit_id: str, model: VisitOrganizationModel | None = None) -> VisitOrganizationState:
        model = model if model is not None else session.get(VisitOrganizationModel, visit_id)
        if model is None:
            return VisitOrganizationState(visit_id=visit_id, state_token=f"organization:{visit_id}:0")
        return VisitOrganizationState(visit_id=visit_id, is_favorite=model.is_favorite, note=model.note or "", inherited_from_visit_id=model.inherited_from_visit_id, created_at=_as_utc(model.created_at), updated_at=_as_utc(model.updated_at), state_token=f"organization:{visit_id}:{model.version}")

    @staticmethod
    def _normalized_collection_name(name: str) -> tuple[str, str]:
        display_name = name.strip()
        if not display_name:
            raise ValueError("collection_name_required")
        return display_name, display_name.casefold()

    @staticmethod
    def _collection_state_token(model: VisitCollectionModel) -> str:
        return f"collection:{model.id}:{model.version}"

    def _active_collection_name_conflict(
        self,
        session: Session,
        normalized_name: str,
        *,
        exclude_id: str | None = None,
    ) -> bool:
        query = select(VisitCollectionModel.id).where(
            VisitCollectionModel.normalized_name == normalized_name,
            VisitCollectionModel.archived_at.is_(None),
        )
        if exclude_id is not None:
            query = query.where(VisitCollectionModel.id != exclude_id)
        return session.scalar(query.limit(1)) is not None

    def _collection_summary(
        self,
        session: Session,
        model: VisitCollectionModel,
    ) -> VisitCollectionSummary:
        active_visit_count = session.scalar(
            select(func.count(VisitCollectionMembershipModel.visit_id))
            .join(VisitModel, VisitModel.id == VisitCollectionMembershipModel.visit_id)
            .where(
                VisitCollectionMembershipModel.collection_id == model.id,
                VisitModel.is_superseded.is_(False),
            )
        ) or 0
        latest_active_visit_at = session.scalar(
            select(EventModel.started_at)
            .select_from(VisitModel)
            .join(
                VisitCollectionMembershipModel,
                VisitCollectionMembershipModel.visit_id == VisitModel.id,
            )
            .join(EventModel, EventModel.id == VisitModel.event_id)
            .where(
                VisitCollectionMembershipModel.collection_id == model.id,
                VisitModel.is_superseded.is_(False),
            )
            .order_by(EventModel.started_at.desc(), EventModel.id.desc(), VisitModel.id.desc())
            .limit(1)
        )
        representative_row = session.execute(
            select(VisitModel, EventModel)
            .join(
                VisitCollectionMembershipModel,
                VisitCollectionMembershipModel.visit_id == VisitModel.id,
            )
            .join(EventModel, EventModel.id == VisitModel.event_id)
            .join(
                VisitEvidenceLinkModel,
                VisitEvidenceLinkModel.visit_id == VisitModel.id,
            )
            .join(MediaAssetModel, MediaAssetModel.id == VisitEvidenceLinkModel.media_asset_id)
            .where(
                VisitCollectionMembershipModel.collection_id == model.id,
                VisitModel.is_superseded.is_(False),
                VisitEvidenceLinkModel.is_primary.is_(True),
            )
            .order_by(EventModel.started_at.desc(), EventModel.id.desc(), VisitModel.id.desc())
            .limit(1)
        ).first()
        representative_evidence = None
        if representative_row is not None:
            visit, event = representative_row
            frames = self._visit_evidence_frames_from_visit(session, visit, event)
            representative_evidence = next((frame for frame in frames if frame.is_primary), None)
        return VisitCollectionSummary(
            id=model.id,
            name=model.name,
            description=model.description,
            created_at=_as_utc(model.created_at),
            updated_at=_as_utc(model.updated_at),
            archived_at=_as_utc(model.archived_at) if model.archived_at is not None else None,
            state_token=self._collection_state_token(model),
            active_visit_count=active_visit_count,
            latest_active_visit_at=(
                _as_utc(latest_active_visit_at)
                if latest_active_visit_at is not None
                else None
            ),
            representative_evidence=representative_evidence,
        )

    def _require_active_collection(
        self,
        session: Session,
        collection_id: str,
    ) -> VisitCollectionModel:
        model = session.get(VisitCollectionModel, collection_id)
        if model is None:
            raise ValueError("missing_collection")
        if model.archived_at is not None:
            raise ValueError("collection_archived")
        return model

    def list_visit_collections(self) -> list[VisitCollectionSummary]:
        with self.session_factory() as session:
            models = session.scalars(
                select(VisitCollectionModel)
                .where(VisitCollectionModel.archived_at.is_(None))
                .order_by(VisitCollectionModel.updated_at.desc(), VisitCollectionModel.id.desc())
                .limit(MAX_COLLECTION_LIST_ITEMS)
            ).all()
            return [self._collection_summary(session, model) for model in models]

    def get_visit_collection(self, collection_id: str) -> VisitCollectionSummary | None:
        with self.session_factory() as session:
            model = session.get(VisitCollectionModel, collection_id)
            return self._collection_summary(session, model) if model is not None else None

    def search_visit_collection(
        self,
        collection_id: str,
        payload: ActivityLibrarySearchRequest,
    ) -> ActivityLibrarySearchResponse:
        with self.session_factory() as session:
            self._require_active_collection(session, collection_id)
        return self.search_activity_library(
            payload.model_copy(update={"collection_id": collection_id, "include_superseded": False})
        )

    def create_visit_collection(self, payload: VisitCollectionCreate) -> VisitCollectionSummary:
        name, normalized_name = self._normalized_collection_name(payload.name)
        description = payload.description.strip() if payload.description is not None else None
        description = description or None
        with self.session_factory() as session:
            with session.begin():
                idempotent = session.scalar(
                    select(VisitCollectionModel).where(
                        VisitCollectionModel.last_idempotency_key == payload.idempotency_key
                    )
                )
                if idempotent is not None:
                    return self._collection_summary(session, idempotent)
                if self._active_collection_name_conflict(session, normalized_name):
                    raise ValueError("collection_name_conflict")
                count = session.scalar(
                    select(func.count(VisitCollectionModel.id)).where(
                        VisitCollectionModel.archived_at.is_(None)
                    )
                ) or 0
                if count >= MAX_ACTIVE_VISIT_COLLECTIONS:
                    raise ValueError("collection_limit")
                now = datetime.now(UTC)
                model = VisitCollectionModel(
                    id=self._next_id(session, VisitCollectionModel, "collection"),
                    name=name,
                    normalized_name=normalized_name,
                    description=description,
                    archived_at=None,
                    version=1,
                    created_at=now,
                    updated_at=now,
                    last_idempotency_key=payload.idempotency_key,
                )
                session.add(model)
                session.flush()
                return self._collection_summary(session, model)

    def update_visit_collection(
        self,
        collection_id: str,
        payload: VisitCollectionUpdate,
    ) -> VisitCollectionSummary:
        with self.session_factory() as session:
            with session.begin():
                model = self._require_active_collection(session, collection_id)
                if model.last_idempotency_key == payload.idempotency_key:
                    return self._collection_summary(session, model)
                if self._collection_state_token(model) != payload.expected_state_token:
                    raise ValueError("collection_stale")
                if "name" in payload.model_fields_set:
                    name, normalized_name = self._normalized_collection_name(payload.name or "")
                    if self._active_collection_name_conflict(
                        session, normalized_name, exclude_id=model.id
                    ):
                        raise ValueError("collection_name_conflict")
                    model.name = name
                    model.normalized_name = normalized_name
                if "description" in payload.model_fields_set:
                    model.description = (payload.description or "").strip() or None
                model.version += 1
                model.updated_at = datetime.now(UTC)
                model.last_idempotency_key = payload.idempotency_key
                session.flush()
                return self._collection_summary(session, model)

    def archive_visit_collection(
        self,
        collection_id: str,
        payload: VisitCollectionArchiveRequest,
    ) -> VisitCollectionSummary:
        with self.session_factory() as session:
            with session.begin():
                model = session.get(VisitCollectionModel, collection_id)
                if model is None:
                    raise ValueError("missing_collection")
                if model.last_idempotency_key == payload.idempotency_key:
                    return self._collection_summary(session, model)
                if self._collection_state_token(model) != payload.expected_state_token:
                    raise ValueError("collection_stale")
                if model.archived_at is None:
                    now = datetime.now(UTC)
                    model.archived_at = now
                    model.updated_at = now
                    model.version += 1
                    model.last_idempotency_key = payload.idempotency_key
                session.flush()
                return self._collection_summary(session, model)

    def visit_collections_for_visit(self, visit_id: str) -> VisitCollectionsForVisitResponse:
        with self.session_factory() as session:
            if session.get(VisitModel, visit_id) is None:
                raise ValueError("missing_visit")
            models = session.scalars(
                select(VisitCollectionModel)
                .join(
                    VisitCollectionMembershipModel,
                    VisitCollectionMembershipModel.collection_id == VisitCollectionModel.id,
                )
                .where(
                    VisitCollectionMembershipModel.visit_id == visit_id,
                    VisitCollectionModel.archived_at.is_(None),
                )
                .order_by(VisitCollectionModel.name.collate("NOCASE"), VisitCollectionModel.id)
                .limit(MAX_COLLECTIONS_PER_VISIT)
            ).all()
            return VisitCollectionsForVisitResponse(
                visit_id=visit_id,
                collections=[self._collection_summary(session, model) for model in models],
            )

    def _collection_membership_result(
        self,
        session: Session,
        *,
        model: VisitCollectionModel,
        visit_id: str,
        action: str,
    ) -> VisitCollectionMembershipResult:
        visit = session.get(VisitModel, visit_id)
        if visit is None:
            return VisitCollectionMembershipResult(
                visit_id=visit_id,
                status=VisitCollectionMembershipStatus.skipped_unavailable,
            )
        if visit.is_superseded:
            return VisitCollectionMembershipResult(
                visit_id=visit_id,
                status=VisitCollectionMembershipStatus.skipped_superseded,
            )
        membership = session.get(
            VisitCollectionMembershipModel,
            {"collection_id": model.id, "visit_id": visit_id},
        )
        if action == "add":
            if membership is not None:
                return VisitCollectionMembershipResult(
                    visit_id=visit_id,
                    status=VisitCollectionMembershipStatus.already_present,
                )
            count = session.scalar(
                select(func.count(VisitCollectionMembershipModel.collection_id))
                .join(
                    VisitCollectionModel,
                    VisitCollectionModel.id == VisitCollectionMembershipModel.collection_id,
                )
                .where(
                    VisitCollectionMembershipModel.visit_id == visit_id,
                    VisitCollectionModel.archived_at.is_(None),
                )
            ) or 0
            if count >= MAX_COLLECTIONS_PER_VISIT:
                return VisitCollectionMembershipResult(
                    visit_id=visit_id,
                    status=VisitCollectionMembershipStatus.skipped_unavailable,
                )
            session.add(
                VisitCollectionMembershipModel(
                    collection_id=model.id,
                    visit_id=visit_id,
                    created_at=datetime.now(UTC),
                )
            )
            return VisitCollectionMembershipResult(
                visit_id=visit_id,
                status=VisitCollectionMembershipStatus.updated,
            )
        if membership is None:
            return VisitCollectionMembershipResult(
                visit_id=visit_id,
                status=VisitCollectionMembershipStatus.already_absent,
            )
        session.delete(membership)
        return VisitCollectionMembershipResult(
            visit_id=visit_id,
            status=VisitCollectionMembershipStatus.updated,
        )

    def update_visit_collection_membership(
        self,
        collection_id: str,
        visit_id: str,
        *,
        action: str,
        payload: VisitCollectionMembershipRequest,
    ) -> VisitCollectionMembershipResponse:
        with self.session_factory() as session:
            with session.begin():
                model = self._require_active_collection(session, collection_id)
                if model.last_idempotency_key != payload.idempotency_key and (
                    self._collection_state_token(model) != payload.expected_state_token
                ):
                    raise ValueError("collection_stale")
                result = self._collection_membership_result(
                    session, model=model, visit_id=visit_id, action=action
                )
                if result.status == VisitCollectionMembershipStatus.updated:
                    model.version += 1
                    model.updated_at = datetime.now(UTC)
                    model.last_idempotency_key = payload.idempotency_key
                session.flush()
                return VisitCollectionMembershipResponse(
                    collection=self._collection_summary(session, model), result=result
                )

    def bulk_update_visit_collection_memberships(
        self,
        payload: VisitCollectionBulkRequest,
    ) -> VisitCollectionBulkResponse:
        with self.session_factory() as session:
            with session.begin():
                model = self._require_active_collection(session, payload.collection_id)
                if model.last_idempotency_key != payload.idempotency_key and (
                    self._collection_state_token(model) != payload.expected_state_token
                ):
                    raise ValueError("collection_stale")
                results = [
                    self._collection_membership_result(
                        session,
                        model=model,
                        visit_id=visit_id,
                        action=payload.action.value,
                    )
                    for visit_id in dict.fromkeys(payload.visit_ids)
                ]
                if any(result.status == VisitCollectionMembershipStatus.updated for result in results):
                    model.version += 1
                    model.updated_at = datetime.now(UTC)
                    model.last_idempotency_key = payload.idempotency_key
                session.flush()
                return VisitCollectionBulkResponse(
                    collection=self._collection_summary(session, model), results=results
                )

    @staticmethod
    def _normalized_tag_name(name: str) -> tuple[str, str]:
        if any(ord(character) < 32 or 127 <= ord(character) <= 159 for character in name):
            raise ValueError("tag_name_unsafe")
        display = " ".join(name.strip().split())
        if not display:
            raise ValueError("tag_name_required")
        return display, display.casefold()

    @staticmethod
    def _tag_token(model: VisitTagModel) -> str:
        return f"tag:{model.id}:{model.version}"

    def _tag_summary(self, session: Session, model: VisitTagModel) -> VisitTagSummary:
        count = session.scalar(
            select(func.count(VisitTagMembershipModel.visit_id))
            .join(VisitModel, VisitModel.id == VisitTagMembershipModel.visit_id)
            .where(VisitTagMembershipModel.tag_id == model.id, VisitModel.is_superseded.is_(False))
        ) or 0
        return VisitTagSummary(
            id=model.id, name=model.name, created_at=_as_utc(model.created_at),
            updated_at=_as_utc(model.updated_at),
            archived_at=_as_utc(model.archived_at) if model.archived_at else None,
            state_token=self._tag_token(model), active_visit_count=count,
        )

    def _require_active_tag(self, session: Session, tag_id: str) -> VisitTagModel:
        model = session.get(VisitTagModel, tag_id)
        if model is None:
            raise ValueError("missing_tag")
        if model.archived_at is not None:
            raise ValueError("tag_archived")
        return model

    def list_visit_tags(self) -> list[VisitTagSummary]:
        with self.session_factory() as session:
            models = session.scalars(
                select(VisitTagModel)
                .where(VisitTagModel.archived_at.is_(None))
                .order_by(VisitTagModel.name.collate("NOCASE"), VisitTagModel.id)
                .limit(MAX_TAG_LIST_ITEMS)
            ).all()
            return [self._tag_summary(session, model) for model in models]

    def list_manageable_visit_tags(self) -> list[VisitTagSummary]:
        """Return the bounded complete active-tag set for the organization surface."""

        with self.session_factory() as session:
            models = session.scalars(
                select(VisitTagModel)
                .where(VisitTagModel.archived_at.is_(None))
                .order_by(VisitTagModel.name.collate("NOCASE"), VisitTagModel.id)
                .limit(MAX_ACTIVE_VISIT_TAGS)
            ).all()
            return [self._tag_summary(session, model) for model in models]

    def create_visit_tag(self, payload: VisitTagCreate) -> VisitTagSummary:
        name, normalized = self._normalized_tag_name(payload.name)
        with self.session_factory() as session:
            with session.begin():
                repeated = session.scalar(select(VisitTagModel).where(VisitTagModel.last_idempotency_key == payload.idempotency_key))
                if repeated is not None: return self._tag_summary(session, repeated)
                if session.scalar(select(VisitTagModel.id).where(VisitTagModel.normalized_name == normalized, VisitTagModel.archived_at.is_(None)).limit(1)) is not None:
                    raise ValueError("tag_name_conflict")
                count = session.scalar(select(func.count(VisitTagModel.id)).where(VisitTagModel.archived_at.is_(None))) or 0
                if count >= MAX_ACTIVE_VISIT_TAGS: raise ValueError("tag_limit")
                now = datetime.now(UTC)
                model = VisitTagModel(id=self._next_id(session, VisitTagModel, "tag"), name=name, normalized_name=normalized, archived_at=None, version=1, created_at=now, updated_at=now, last_idempotency_key=payload.idempotency_key)
                session.add(model); session.flush()
                return self._tag_summary(session, model)

    def update_visit_tag(self, tag_id: str, payload: VisitTagUpdate) -> VisitTagSummary:
        name, normalized = self._normalized_tag_name(payload.name)
        with self.session_factory() as session:
            with session.begin():
                model = self._require_active_tag(session, tag_id)
                if model.last_idempotency_key == payload.idempotency_key: return self._tag_summary(session, model)
                if self._tag_token(model) != payload.expected_state_token: raise ValueError("tag_stale")
                if session.scalar(select(VisitTagModel.id).where(VisitTagModel.normalized_name == normalized, VisitTagModel.archived_at.is_(None), VisitTagModel.id != model.id).limit(1)) is not None:
                    raise ValueError("tag_name_conflict")
                model.name, model.normalized_name, model.version, model.updated_at, model.last_idempotency_key = name, normalized, model.version + 1, datetime.now(UTC), payload.idempotency_key
                session.flush(); return self._tag_summary(session, model)

    def archive_visit_tag(self, tag_id: str, payload: VisitTagArchiveRequest) -> VisitTagSummary:
        with self.session_factory() as session:
            with session.begin():
                model = session.get(VisitTagModel, tag_id)
                if model is None: raise ValueError("missing_tag")
                if model.last_idempotency_key == payload.idempotency_key: return self._tag_summary(session, model)
                if self._tag_token(model) != payload.expected_state_token: raise ValueError("tag_stale")
                if model.archived_at is None:
                    now = datetime.now(UTC); model.archived_at = now; model.updated_at = now; model.version += 1; model.last_idempotency_key = payload.idempotency_key
                session.flush(); return self._tag_summary(session, model)

    def tags_for_visit(self, visit_id: str) -> VisitTagsForVisitResponse:
        with self.session_factory() as session:
            if session.get(VisitModel, visit_id) is None: raise ValueError("missing_visit")
            models = session.scalars(select(VisitTagModel).join(VisitTagMembershipModel, VisitTagMembershipModel.tag_id == VisitTagModel.id).where(VisitTagMembershipModel.visit_id == visit_id, VisitTagModel.archived_at.is_(None)).order_by(VisitTagModel.name.collate("NOCASE"), VisitTagModel.id).limit(MAX_TAGS_PER_VISIT)).all()
            return VisitTagsForVisitResponse(visit_id=visit_id, tags=[self._tag_summary(session, model) for model in models])

    def _tag_membership(self, session: Session, model: VisitTagModel, visit_id: str, action: str) -> VisitTagMembershipResult:
        visit = session.get(VisitModel, visit_id)
        if visit is None: return VisitTagMembershipResult(visit_id=visit_id, status=VisitTagMembershipStatus.skipped_unavailable)
        if visit.is_superseded: return VisitTagMembershipResult(visit_id=visit_id, status=VisitTagMembershipStatus.skipped_superseded)
        membership = session.get(VisitTagMembershipModel, {"tag_id": model.id, "visit_id": visit_id})
        if action == "add":
            if membership is not None: return VisitTagMembershipResult(visit_id=visit_id, status=VisitTagMembershipStatus.already_present)
            count = session.scalar(select(func.count(VisitTagMembershipModel.tag_id)).join(VisitTagModel, VisitTagModel.id == VisitTagMembershipModel.tag_id).where(VisitTagMembershipModel.visit_id == visit_id, VisitTagModel.archived_at.is_(None))) or 0
            if count >= MAX_TAGS_PER_VISIT: return VisitTagMembershipResult(visit_id=visit_id, status=VisitTagMembershipStatus.skipped_limit)
            session.add(VisitTagMembershipModel(tag_id=model.id, visit_id=visit_id, created_at=datetime.now(UTC)))
        else:
            if membership is None: return VisitTagMembershipResult(visit_id=visit_id, status=VisitTagMembershipStatus.already_absent)
            session.delete(membership)
        return VisitTagMembershipResult(visit_id=visit_id, status=VisitTagMembershipStatus.updated)

    def update_visit_tag_membership(self, tag_id: str, visit_id: str, *, action: str, payload: VisitTagMembershipRequest) -> VisitTagMembershipResponse:
        with self.session_factory() as session:
            with session.begin():
                model = self._require_active_tag(session, tag_id)
                if model.last_idempotency_key != payload.idempotency_key and self._tag_token(model) != payload.expected_state_token: raise ValueError("tag_stale")
                result = self._tag_membership(session, model, visit_id, action)
                if result.status == VisitTagMembershipStatus.updated: model.version += 1; model.updated_at = datetime.now(UTC); model.last_idempotency_key = payload.idempotency_key
                session.flush(); return VisitTagMembershipResponse(tag=self._tag_summary(session, model), result=result)

    def bulk_update_visit_tag_memberships(self, payload: VisitTagBulkRequest) -> VisitTagBulkResponse:
        with self.session_factory() as session:
            with session.begin():
                model = self._require_active_tag(session, payload.tag_id)
                if model.last_idempotency_key != payload.idempotency_key and self._tag_token(model) != payload.expected_state_token: raise ValueError("tag_stale")
                results = [self._tag_membership(session, model, visit_id, payload.action) for visit_id in dict.fromkeys(payload.visit_ids)]
                if any(item.status == VisitTagMembershipStatus.updated for item in results): model.version += 1; model.updated_at = datetime.now(UTC); model.last_idempotency_key = payload.idempotency_key
                session.flush(); return VisitTagBulkResponse(tag=self._tag_summary(session, model), results=results)

    @staticmethod
    def _yard_map_token(model: YardMapModel) -> str:
        return f"yard-map:{model.id}:{model.version}"

    @staticmethod
    def _yard_map_stream_placement_token(model: YardMapStreamPlacementModel) -> str:
        return f"yard-map-stream:{model.map_id}:{model.stream_id}:{model.version}"

    @staticmethod
    def _yard_map_zone_placement_token(model: YardMapZonePlacementModel) -> str:
        return f"yard-map-zone:{model.map_id}:{model.zone_id}:{model.version}"

    def _yard_map_background_path(self, relative_path: str | None) -> Path | None:
        if not relative_path:
            return None
        try:
            relative = Path(relative_path)
            root = self.media_root.resolve()
            if relative.is_absolute() or not relative.parts or relative.parts[0] != "property-map":
                return None
            candidate = (self.media_root / relative).resolve(strict=False)
            if not candidate.is_relative_to(root) or candidate.is_symlink():
                return None
            return candidate
        except OSError:
            return None

    def _yard_map_settings(self, model: YardMapModel) -> YardMapSettings:
        background_path = self._yard_map_background_path(model.background_relative_path)
        background_missing = bool(
            model.background_relative_path
            and (background_path is None or not background_path.exists() or not background_path.is_file())
        )
        background = None
        if not background_missing and model.background_relative_path and model.background_content_type:
            background = YardMapBackground(
                preview_url="/api/yard-map/background",
                content_type=model.background_content_type,
                width=model.background_width or 1,
                height=model.background_height or 1,
            )
        return YardMapSettings(
            id=model.id,
            canvas_width=model.canvas_width,
            canvas_height=model.canvas_height,
            background=background,
            background_missing=background_missing,
            state_token=self._yard_map_token(model),
            created_at=_as_utc(model.created_at),
            updated_at=_as_utc(model.updated_at),
        )

    def _yard_map_stream_placement(
        self,
        model: YardMapStreamPlacementModel,
    ) -> YardMapStreamPlacement:
        return YardMapStreamPlacement(
            stream_id=model.stream_id,
            x=model.x,
            y=model.y,
            heading_degrees=model.heading_degrees,
            field_of_view_degrees=model.field_of_view_degrees,
            display_scale=model.display_scale,
            state_token=self._yard_map_stream_placement_token(model),
            updated_at=_as_utc(model.updated_at),
        )

    def _yard_map_zone_placement(
        self,
        model: YardMapZonePlacementModel,
    ) -> YardMapZonePlacement:
        area = _json_list(model.area_json) if model.area_json else None
        return YardMapZonePlacement(
            zone_id=model.zone_id,
            x=model.x,
            y=model.y,
            area=area or None,
            state_token=self._yard_map_zone_placement_token(model),
            updated_at=_as_utc(model.updated_at),
        )

    def _yard_map_range_start(
        self,
        activity_range: str,
        now: datetime,
    ) -> datetime:
        if activity_range == "last_24_hours":
            return now - timedelta(hours=24)
        if activity_range == "last_7_days":
            return now - timedelta(days=7)
        local_now = now.astimezone()
        return _as_utc(local_now.replace(hour=0, minute=0, second=0, microsecond=0))

    def _yard_map_activity_summary(
        self,
        session: Session,
        stream: StreamModel,
        *,
        start_at: datetime,
    ) -> YardMapActivitySummary:
        policy = session.get(StreamMonitoringPolicyModel, stream.id)
        checkpoint = session.get(StreamRuntimeCheckpointModel, stream.id)
        try:
            desired_state = StreamMonitoringMode(policy.mode) if policy else StreamMonitoringMode.off
        except ValueError:
            desired_state = StreamMonitoringMode.off
        try:
            actual_state = StreamRuntimeState(checkpoint.actual_state) if checkpoint else StreamRuntimeState.stopped
        except ValueError:
            actual_state = StreamRuntimeState.stopped
        visit_rows = session.execute(
            select(VisitModel, EventModel)
            .join(EventModel, VisitModel.event_id == EventModel.id)
            .where(
                EventModel.stream_id == stream.id,
                EventModel.started_at >= start_at,
                VisitModel.is_superseded.is_(False),
            )
            .order_by(EventModel.started_at.desc(), EventModel.id.desc(), VisitModel.id.desc())
            .limit(50)
        ).all()
        summaries = [
            self._stream_visit_summary_from_models(session, visit, event)
            for visit, event in visit_rows
        ]
        latest = summaries[0] if summaries else None
        confirmed = next(
            (
                summary.reviewed_label
                for summary in summaries
                if summary.review_outcome == VisitReviewOutcome.confirmed_bird
                and summary.reviewed_label
            ),
            None,
        )
        needs_review_count = session.scalar(
            select(func.count(VisitModel.id))
            .join(EventModel, VisitModel.event_id == EventModel.id)
            .where(
                EventModel.stream_id == stream.id,
                EventModel.started_at >= start_at,
                VisitModel.is_superseded.is_(False),
                VisitModel.review_status == ReviewStatus.needs_review.value,
            )
        ) or 0
        needs_review_visit_ids = session.scalars(
            select(VisitModel.id)
            .join(EventModel, VisitModel.event_id == EventModel.id)
            .where(
                EventModel.stream_id == stream.id,
                EventModel.started_at >= start_at,
                VisitModel.is_superseded.is_(False),
                VisitModel.review_status == ReviewStatus.needs_review.value,
            )
            .order_by(EventModel.started_at.desc(), EventModel.id.desc(), VisitModel.id.desc())
            .limit(50)
        ).all()
        open_activity = session.scalar(
            select(EventModel.id)
            .where(EventModel.stream_id == stream.id, EventModel.ended_at.is_(None))
            .limit(1)
        ) is not None
        try:
            playback = self.get_stream_playback_status(stream.id)
        except Exception:
            playback = None
        health = self._camera_health_summary_from_models(
            session,
            stream,
            source=session.get(CameraSourceModel, stream.source_id),
            playback=playback,
            now=datetime.now(UTC),
            open_activity_session_count=1 if open_activity else 0,
            latest_visit_at=latest.activity_started_at if latest else None,
        )
        return YardMapActivitySummary(
            monitoring_desired_state=desired_state,
            monitoring_actual_state=actual_state,
            camera_health_state=health.state,
            open_activity_session=open_activity,
            needs_review_count=needs_review_count,
            needs_review_visit_ids=needs_review_visit_ids,
            latest_visit_id=latest.id if latest else None,
            latest_visit_at=latest.activity_started_at if latest else None,
            latest_confirmed_label=confirmed,
            latest_preview_url=(latest.primary_evidence.preview_url if latest and latest.primary_evidence else None),
        )

    def yard_map(
        self,
        *,
        activity_range: str = "today",
        now: datetime | None = None,
    ) -> YardMapResponse:
        current_time = _as_utc(now or datetime.now(UTC))
        start_at = self._yard_map_range_start(activity_range, current_time)
        with self.session_factory() as session:
            map_model = session.get(YardMapModel, YARD_MAP_ID)
            stream_placements = {
                item.stream_id: item
                for item in session.scalars(
                    select(YardMapStreamPlacementModel).where(
                        YardMapStreamPlacementModel.map_id == YARD_MAP_ID
                    )
                ).all()
            }
            zone_placements = {
                item.zone_id: item
                for item in session.scalars(
                    select(YardMapZonePlacementModel).where(
                        YardMapZonePlacementModel.map_id == YARD_MAP_ID
                    )
                ).all()
            }
            stream_rows = session.execute(
                select(StreamModel, CameraSourceModel)
                .join(CameraSourceModel, CameraSourceModel.id == StreamModel.source_id)
                .where(CameraSourceModel.status != SourceStatus.archived.value)
                .order_by(CameraSourceModel.name.collate("NOCASE"), StreamModel.name.collate("NOCASE"), StreamModel.id)
                .limit(50)
            ).all()
            streams = [
                YardMapStreamItem(
                    id=stream.id,
                    name=stream.name,
                    source_name=source.name,
                    is_live=stream.is_live,
                    placement=(
                        self._yard_map_stream_placement(stream_placements[stream.id])
                        if stream.id in stream_placements
                        else None
                    ),
                    activity=self._yard_map_activity_summary(session, stream, start_at=start_at),
                )
                for stream, source in stream_rows
            ]
            active_stream_ids = {stream.id for stream, _source in stream_rows}
            zones = [
                YardMapZoneItem(
                    id=zone.id,
                    stream_id=zone.stream_id,
                    name=zone.name,
                    zone_type=ZoneType(zone.zone_type),
                    is_active=zone.is_active,
                    placement=(
                        self._yard_map_zone_placement(zone_placements[zone.id])
                        if zone.id in zone_placements
                        else None
                    ),
                )
                for zone in session.scalars(
                    select(ZoneModel)
                    .where(ZoneModel.stream_id.in_(active_stream_ids))
                    .order_by(ZoneModel.stream_id, ZoneModel.name.collate("NOCASE"), ZoneModel.id)
                    .limit(200)
                ).all()
            ] if active_stream_ids else []
            warnings: list[str] = []
            if map_model is None:
                warnings.append("No Yard Map is configured yet. Choose a blank canvas or a local yard image.")
            elif self._yard_map_settings(map_model).background_missing:
                warnings.append("The configured yard background is unavailable. Placements remain on the blank canvas.")
            return YardMapResponse(
                map=self._yard_map_settings(map_model) if map_model else None,
                streams=streams,
                zones=zones,
                range=activity_range,
                warnings=warnings,
            )

    def create_blank_yard_map(self, payload: YardMapBlankCreate) -> YardMapResponse:
        with self.session_factory() as session:
            with session.begin():
                model = session.get(YardMapModel, YARD_MAP_ID)
                if model is not None:
                    if model.last_idempotency_key == payload.idempotency_key:
                        return self.yard_map()
                    raise ValueError("yard_map_exists")
                now = datetime.now(UTC)
                session.add(
                    YardMapModel(
                        id=YARD_MAP_ID,
                        background_relative_path=None,
                        background_content_type=None,
                        background_width=None,
                        background_height=None,
                        canvas_width=payload.canvas_width,
                        canvas_height=payload.canvas_height,
                        version=1,
                        created_at=now,
                        updated_at=now,
                        last_idempotency_key=payload.idempotency_key,
                    )
                )
        return self.yard_map()

    def update_yard_map_settings(self, payload: YardMapSettingsUpdate) -> YardMapResponse:
        with self.session_factory() as session:
            with session.begin():
                model = session.get(YardMapModel, YARD_MAP_ID)
                if model is None:
                    raise ValueError("missing_yard_map")
                if model.last_idempotency_key == payload.idempotency_key:
                    return self.yard_map()
                if self._yard_map_token(model) != payload.expected_state_token:
                    raise ValueError("yard_map_stale")
                model.canvas_width = payload.canvas_width
                model.canvas_height = payload.canvas_height
                model.version += 1
                model.updated_at = datetime.now(UTC)
                model.last_idempotency_key = payload.idempotency_key
        return self.yard_map()

    def replace_yard_map_background(
        self,
        *,
        content: bytes,
        content_type: str,
        expected_state_token: str | None,
        idempotency_key: str,
    ) -> YardMapResponse:
        normalized_type, width, height, extension = _yard_map_image_metadata(content, content_type)
        if len(content) > MAX_YARD_MAP_BACKGROUND_BYTES:
            raise ValueError("yard_map_background_too_large")
        relative_path, stored_path = self._write_yard_map_background(content, extension)
        old_relative_path: str | None = None
        try:
            with self.session_factory() as session:
                with session.begin():
                    model = session.get(YardMapModel, YARD_MAP_ID)
                    if model is None:
                        now = datetime.now(UTC)
                        model = YardMapModel(
                            id=YARD_MAP_ID,
                            background_relative_path=relative_path,
                            background_content_type=normalized_type,
                            background_width=width,
                            background_height=height,
                            canvas_width=1200,
                            canvas_height=800,
                            version=1,
                            created_at=now,
                            updated_at=now,
                            last_idempotency_key=idempotency_key,
                        )
                        session.add(model)
                    else:
                        if model.last_idempotency_key == idempotency_key:
                            self._delete_yard_map_background(stored_path)
                            return self.yard_map()
                        if expected_state_token is None or self._yard_map_token(model) != expected_state_token:
                            raise ValueError("yard_map_stale")
                        old_relative_path = model.background_relative_path
                        model.background_relative_path = relative_path
                        model.background_content_type = normalized_type
                        model.background_width = width
                        model.background_height = height
                        model.version += 1
                        model.updated_at = datetime.now(UTC)
                        model.last_idempotency_key = idempotency_key
        except Exception:
            self._delete_yard_map_background(stored_path)
            raise
        self._delete_yard_map_background(self._yard_map_background_path(old_relative_path))
        return self.yard_map()

    def remove_yard_map_background(self, payload: YardMapBackgroundDelete) -> YardMapResponse:
        old_relative_path: str | None = None
        with self.session_factory() as session:
            with session.begin():
                model = session.get(YardMapModel, YARD_MAP_ID)
                if model is None:
                    raise ValueError("missing_yard_map")
                if model.last_idempotency_key == payload.idempotency_key:
                    return self.yard_map()
                if self._yard_map_token(model) != payload.expected_state_token:
                    raise ValueError("yard_map_stale")
                old_relative_path = model.background_relative_path
                model.background_relative_path = None
                model.background_content_type = None
                model.background_width = None
                model.background_height = None
                model.version += 1
                model.updated_at = datetime.now(UTC)
                model.last_idempotency_key = payload.idempotency_key
        self._delete_yard_map_background(self._yard_map_background_path(old_relative_path))
        return self.yard_map()

    def _write_yard_map_background(self, content: bytes, extension: str) -> tuple[str, Path]:
        root = self.media_root / "property-map"
        if root.exists() and root.is_symlink():
            raise ValueError("yard_map_media_root_unsafe")
        root.mkdir(parents=True, exist_ok=True)
        if root.is_symlink() or not root.resolve().is_relative_to(self.media_root.resolve()):
            raise ValueError("yard_map_media_root_unsafe")
        relative_path = f"property-map/background-{uuid.uuid4().hex}{extension}"
        path = self.media_root / relative_path
        temporary = path.with_suffix(f"{path.suffix}.tmp")
        temporary.write_bytes(content)
        temporary.replace(path)
        return relative_path, path

    @staticmethod
    def _delete_yard_map_background(path: Path | None) -> None:
        try:
            if path is not None and path.exists() and path.is_file() and not path.is_symlink():
                path.unlink()
        except OSError:
            pass

    def yard_map_background_file(self) -> tuple[Path, str] | None:
        with self.session_factory() as session:
            model = session.get(YardMapModel, YARD_MAP_ID)
            if model is None or not model.background_content_type:
                return None
            path = self._yard_map_background_path(model.background_relative_path)
            if path is None or not path.exists() or not path.is_file() or path.is_symlink():
                return None
            return path, model.background_content_type

    def update_yard_map_stream_placement(
        self,
        stream_id: str,
        payload: YardMapStreamPlacementUpdate,
    ) -> YardMapResponse:
        with self.session_factory() as session:
            with session.begin():
                if session.get(YardMapModel, YARD_MAP_ID) is None:
                    raise ValueError("missing_yard_map")
                stream = session.get(StreamModel, stream_id)
                source = session.get(CameraSourceModel, stream.source_id) if stream else None
                if stream is None or source is None or source.status == SourceStatus.archived.value:
                    raise ValueError("missing_yard_map_stream")
                model = session.get(YardMapStreamPlacementModel, {"map_id": YARD_MAP_ID, "stream_id": stream_id})
                if model is not None and model.last_idempotency_key == payload.idempotency_key:
                    return self.yard_map()
                now = datetime.now(UTC)
                if model is None:
                    model = YardMapStreamPlacementModel(
                        map_id=YARD_MAP_ID,
                        stream_id=stream_id,
                        x=payload.x,
                        y=payload.y,
                        heading_degrees=payload.heading_degrees,
                        field_of_view_degrees=payload.field_of_view_degrees,
                        display_scale=payload.display_scale,
                        version=1,
                        updated_at=now,
                        last_idempotency_key=payload.idempotency_key,
                    )
                    session.add(model)
                else:
                    if payload.expected_state_token is None or self._yard_map_stream_placement_token(model) != payload.expected_state_token:
                        raise ValueError("yard_map_placement_stale")
                    model.x, model.y = payload.x, payload.y
                    model.heading_degrees = payload.heading_degrees
                    model.field_of_view_degrees = payload.field_of_view_degrees
                    model.display_scale = payload.display_scale
                    model.version += 1
                    model.updated_at = now
                    model.last_idempotency_key = payload.idempotency_key
        return self.yard_map()

    def remove_yard_map_stream_placement(
        self,
        stream_id: str,
        payload: YardMapPlacementDelete,
    ) -> YardMapResponse:
        with self.session_factory() as session:
            with session.begin():
                model = session.get(YardMapStreamPlacementModel, {"map_id": YARD_MAP_ID, "stream_id": stream_id})
                if model is None:
                    if session.get(YardMapModel, YARD_MAP_ID) is None:
                        raise ValueError("missing_yard_map")
                elif self._yard_map_stream_placement_token(model) != payload.expected_state_token:
                    raise ValueError("yard_map_placement_stale")
                else:
                    session.delete(model)
        return self.yard_map()

    def update_yard_map_zone_placement(
        self,
        zone_id: str,
        payload: YardMapZonePlacementUpdate,
    ) -> YardMapResponse:
        with self.session_factory() as session:
            with session.begin():
                if session.get(YardMapModel, YARD_MAP_ID) is None:
                    raise ValueError("missing_yard_map")
                zone = session.get(ZoneModel, zone_id)
                stream = session.get(StreamModel, zone.stream_id) if zone else None
                source = session.get(CameraSourceModel, stream.source_id) if stream else None
                if zone is None or stream is None or source is None or source.status == SourceStatus.archived.value:
                    raise ValueError("missing_yard_map_zone")
                model = session.get(YardMapZonePlacementModel, {"map_id": YARD_MAP_ID, "zone_id": zone_id})
                if model is not None and model.last_idempotency_key == payload.idempotency_key:
                    return self.yard_map()
                now = datetime.now(UTC)
                area_json = json.dumps([item.model_dump() for item in payload.area]) if payload.area else None
                if model is None:
                    session.add(YardMapZonePlacementModel(
                        map_id=YARD_MAP_ID, zone_id=zone_id, x=payload.x, y=payload.y,
                        area_json=area_json, version=1, updated_at=now,
                        last_idempotency_key=payload.idempotency_key,
                    ))
                else:
                    if payload.expected_state_token is None or self._yard_map_zone_placement_token(model) != payload.expected_state_token:
                        raise ValueError("yard_map_placement_stale")
                    model.x, model.y, model.area_json = payload.x, payload.y, area_json
                    model.version += 1
                    model.updated_at = now
                    model.last_idempotency_key = payload.idempotency_key
        return self.yard_map()

    def remove_yard_map_zone_placement(
        self,
        zone_id: str,
        payload: YardMapPlacementDelete,
    ) -> YardMapResponse:
        with self.session_factory() as session:
            with session.begin():
                model = session.get(YardMapZonePlacementModel, {"map_id": YARD_MAP_ID, "zone_id": zone_id})
                if model is None:
                    if session.get(YardMapModel, YARD_MAP_ID) is None:
                        raise ValueError("missing_yard_map")
                elif self._yard_map_zone_placement_token(model) != payload.expected_state_token:
                    raise ValueError("yard_map_placement_stale")
                else:
                    session.delete(model)
        return self.yard_map()

    def search_activity_library(
        self,
        payload: ActivityLibrarySearchRequest,
    ) -> ActivityLibrarySearchResponse:
        """Read one stable, bounded newest-first page of cross-Stream activity."""

        with self.session_factory() as session:
            effective_zone_id = func.coalesce(VisitModel.zone_id, EventModel.primary_zone_id)
            latest_visit_label = (
                select(ReviewLabelModel.label)
                .where(
                    ReviewLabelModel.target_type == "visit",
                    ReviewLabelModel.target_id == VisitModel.id,
                )
                .order_by(ReviewLabelModel.created_at.desc(), ReviewLabelModel.id.desc())
                .limit(1)
                .scalar_subquery()
            )
            latest_event_label = (
                select(ReviewLabelModel.label)
                .where(
                    ReviewLabelModel.target_type == "event",
                    ReviewLabelModel.target_id == EventModel.id,
                )
                .order_by(ReviewLabelModel.created_at.desc(), ReviewLabelModel.id.desc())
                .limit(1)
                .scalar_subquery()
            )
            effective_reviewed_label = func.coalesce(
                VisitModel.reviewed_label,
                latest_visit_label,
                latest_event_label,
            )
            review_label_key = func.lower(effective_reviewed_label)
            suggestion_exists = (
                select(SpeciesSuggestionModel.id)
                .where(SpeciesSuggestionModel.visit_id == VisitModel.id)
                .exists()
            )
            query = (
                select(
                    VisitModel,
                    EventModel,
                    StreamModel,
                    CameraSourceModel,
                    ZoneModel,
                )
                .join(EventModel, VisitModel.event_id == EventModel.id)
                .join(StreamModel, EventModel.stream_id == StreamModel.id)
                .outerjoin(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                .outerjoin(ZoneModel, ZoneModel.id == effective_zone_id)
                .outerjoin(VisitOrganizationModel, VisitOrganizationModel.visit_id == VisitModel.id)
                .outerjoin(
                    TaxonomyLabelModel,
                    func.lower(TaxonomyLabelModel.label) == review_label_key,
                )
            )

            # Provenance is opt-in: active Visits are the current product truth by default.
            if not payload.include_superseded:
                query = query.where(VisitModel.is_superseded.is_(False))
            if payload.stream_id is not None:
                query = query.where(EventModel.stream_id == payload.stream_id)
            if payload.source_id is not None:
                query = query.where(StreamModel.source_id == payload.source_id)
            if payload.zone_id is not None:
                query = query.where(effective_zone_id == payload.zone_id)
            if payload.start_at is not None:
                query = query.where(EventModel.started_at >= payload.start_at)
            if payload.end_at is not None:
                query = query.where(EventModel.started_at <= payload.end_at)
            if payload.confirmed_label is not None:
                query = query.where(
                    review_label_key
                    == payload.confirmed_label.strip().lower()
                )
            if payload.has_suggestion is True:
                query = query.where(suggestion_exists)
            elif payload.has_suggestion is False:
                query = query.where(~suggestion_exists)
            if payload.favorites_only:
                query = query.where(VisitOrganizationModel.is_favorite.is_(True))
            if payload.has_note is True:
                query = query.where(
                    VisitOrganizationModel.note.is_not(None),
                    func.length(func.trim(VisitOrganizationModel.note)) > 0,
                )
            elif payload.has_note is False:
                query = query.where(
                    or_(
                        VisitOrganizationModel.visit_id.is_(None),
                        VisitOrganizationModel.note.is_(None),
                        func.length(func.trim(VisitOrganizationModel.note)) == 0,
                    )
                )
            if payload.collection_id is not None:
                query = (
                    query.join(
                        VisitCollectionMembershipModel,
                        VisitCollectionMembershipModel.visit_id == VisitModel.id,
                    )
                    .join(
                        VisitCollectionModel,
                        VisitCollectionModel.id == VisitCollectionMembershipModel.collection_id,
                    )
                    .where(
                        VisitCollectionModel.id == payload.collection_id,
                        VisitCollectionModel.archived_at.is_(None),
                    )
                )
            if payload.tag_id is not None:
                query = query.join(VisitTagMembershipModel, VisitTagMembershipModel.visit_id == VisitModel.id).join(VisitTagModel, VisitTagModel.id == VisitTagMembershipModel.tag_id).where(VisitTagModel.id == payload.tag_id, VisitTagModel.archived_at.is_(None))
            blank_keys = {"blank", "empty", "no_activity", "no_animal"}
            ambiguous_keys = {"ambiguous", "unknown_bird", "unknown_animal", "unknown"}
            non_bird_keys = {"non_bird", "non_bird_activity"}
            if payload.review_filter == ActivityLibraryReviewFilter.needs_review:
                query = query.where(VisitModel.review_status == ReviewStatus.needs_review.value)
            elif payload.review_filter == ActivityLibraryReviewFilter.reviewed_observation:
                query = query.where(VisitModel.review_status == ReviewStatus.reviewed.value)
                query = query.where(
                    or_(
                        TaxonomyLabelModel.category == LabelCategory.bird.value,
                        and_(
                            TaxonomyLabelModel.id.is_(None),
                            effective_reviewed_label.is_not(None),
                            ~review_label_key.in_(
                                {"false_positive", *blank_keys, *ambiguous_keys, *non_bird_keys}
                            ),
                        ),
                    )
                )
            elif payload.review_filter == ActivityLibraryReviewFilter.confirmed_wildlife:
                # Everyday Discovery / Product Experience v2 (Phase K): this
                # was bird-only (`category == bird`), silently excluding a
                # confirmed non-bird wildlife record (squirrel, deer, ...)
                # from a filter literally labeled "Confirmed wildlife" --
                # inconsistent with the canonical `is_wildlife_category`
                # denylist boundary Bird Log/Today already use (see
                # `_wildlife_journal_confirmed_records`). A taxonomy row is
                # wildlife whenever its category is not in the denylist;
                # `TaxonomyLabelModel.id.is_(None)` (no matched taxonomy row
                # at all, e.g. a free-form reviewed label) is never wildlife.
                query = query.where(VisitModel.review_status == ReviewStatus.reviewed.value).where(
                    TaxonomyLabelModel.id.is_not(None),
                    TaxonomyLabelModel.category.not_in(NON_WILDLIFE_LABEL_CATEGORIES),
                )
            elif payload.review_filter == ActivityLibraryReviewFilter.non_bird:
                query = query.where(VisitModel.review_status == ReviewStatus.reviewed.value).where(
                    or_(
                        review_label_key.in_(non_bird_keys),
                        and_(
                            TaxonomyLabelModel.id.is_not(None),
                            TaxonomyLabelModel.category.not_in(
                                [LabelCategory.bird.value, LabelCategory.false_positive.value]
                            ),
                        ),
                    )
                )
            elif payload.review_filter == ActivityLibraryReviewFilter.blank_false:
                query = query.where(VisitModel.review_status == ReviewStatus.reviewed.value).where(
                    or_(
                        review_label_key.in_({"false_positive", *blank_keys}),
                        TaxonomyLabelModel.category == LabelCategory.false_positive.value,
                    )
                )
            elif payload.review_filter == ActivityLibraryReviewFilter.blank:
                query = query.where(VisitModel.review_status == ReviewStatus.reviewed.value).where(
                    review_label_key.in_(blank_keys)
                )
            elif payload.review_filter == ActivityLibraryReviewFilter.ambiguous_unknown:
                query = query.where(VisitModel.review_status == ReviewStatus.reviewed.value).where(
                    review_label_key.in_(ambiguous_keys)
                )

            search = (payload.search or "").strip().lower()
            if search:
                pattern = f"%{search}%"
                suggestion_match = (
                    select(SpeciesSuggestionModel.id)
                    .where(
                        SpeciesSuggestionModel.visit_id == VisitModel.id,
                        func.lower(SpeciesSuggestionModel.suggested_label).like(pattern),
                    )
                    .exists()
                )
                query = query.where(
                    or_(
                        func.lower(VisitModel.subject_label).like(pattern),
                        func.lower(VisitModel.species_guess).like(pattern),
                        review_label_key.like(pattern),
                        func.lower(StreamModel.name).like(pattern),
                        func.lower(CameraSourceModel.name).like(pattern),
                        func.lower(ZoneModel.name).like(pattern),
                        suggestion_match,
                    )
                )

            # Event timestamp plus immutable IDs makes offset pages deterministic when times tie.
            ordering = (
                (EventModel.started_at.asc(), EventModel.id.asc(), VisitModel.id.asc())
                if payload.oldest_first
                else (EventModel.started_at.desc(), EventModel.id.desc(), VisitModel.id.desc())
            )
            rows = session.execute(
                query.order_by(*ordering)
                .offset(payload.offset)
                .limit(payload.page_size + 1)
            ).all()
            has_more = len(rows) > payload.page_size
            summaries = [
                self._activity_library_visit_summary_from_models(
                    session,
                    visit,
                    event,
                    stream,
                    source,
                )
                for visit, event, stream, source, _zone in rows[: payload.page_size]
            ]
            summaries = [
                summary
                for summary in summaries
                if self._activity_library_review_filter_matches(
                    session,
                    summary,
                    payload.review_filter,
                )
            ]
            return ActivityLibrarySearchResponse(
                visits=summaries,
                has_more=has_more,
                next_offset=(payload.offset + payload.page_size) if has_more else None,
            )

    def _activity_library_visit_summary_from_models(
        self,
        session: Session,
        visit: VisitModel,
        event: EventModel,
        stream: StreamModel,
        source: CameraSourceModel | None,
    ) -> ActivityLibraryVisitSummary:
        history = session.scalars(
            select(VisitCurationHistoryModel)
            .where(VisitCurationHistoryModel.visit_id == visit.id)
            .order_by(
                VisitCurationHistoryModel.created_at.desc(),
                VisitCurationHistoryModel.id.desc(),
            )
            .limit(8)
        ).all()
        organization = session.get(VisitOrganizationModel, visit.id)
        collection_count = session.scalar(
            select(func.count(VisitCollectionMembershipModel.collection_id))
            .join(
                VisitCollectionModel,
                VisitCollectionModel.id == VisitCollectionMembershipModel.collection_id,
            )
            .where(
                VisitCollectionMembershipModel.visit_id == visit.id,
                VisitCollectionModel.archived_at.is_(None),
            )
        ) or 0
        tag_models = session.scalars(select(VisitTagModel).join(VisitTagMembershipModel, VisitTagMembershipModel.tag_id == VisitTagModel.id).where(VisitTagMembershipModel.visit_id == visit.id, VisitTagModel.archived_at.is_(None)).order_by(VisitTagModel.name.collate("NOCASE"), VisitTagModel.id).limit(MAX_TAGS_PER_VISIT)).all()
        return ActivityLibraryVisitSummary(
            **self._stream_visit_summary_from_models(session, visit, event).model_dump(),
            stream_name=stream.name,
            source_id=stream.source_id,
            source_name=source.name if source is not None else "Unavailable Source",
            curation_actions=[entry.action for entry in history],
            is_favorite=bool(organization and organization.is_favorite),
            has_note=bool(organization and organization.note and organization.note.strip()),
            collection_count=collection_count,
            tags=[model.name for model in tag_models],
            tag_count=len(tag_models),
        )

    def _activity_library_review_filter_matches(
        self,
        session: Session,
        summary: ActivityLibraryVisitSummary,
        review_filter: ActivityLibraryReviewFilter,
    ) -> bool:
        # Outcome is resolved through the existing Visit truth helper, never suggestion evidence.
        if review_filter == ActivityLibraryReviewFilter.all:
            return True
        if review_filter == ActivityLibraryReviewFilter.needs_review:
            return summary.review_outcome == VisitReviewOutcome.needs_review
        if review_filter == ActivityLibraryReviewFilter.reviewed_observation:
            return summary.review_outcome in {
                VisitReviewOutcome.confirmed_bird,
                VisitReviewOutcome.reviewed_other,
            }
        if review_filter == ActivityLibraryReviewFilter.confirmed_wildlife:
            # Everyday Discovery / Product Experience v2 (Phase K): wildlife-
            # inclusive, matching the query-level fix above and the
            # canonical `is_wildlife_category` boundary Bird Log/Today
            # already use -- a confirmed non-bird wildlife outcome
            # (`non_bird`) is real confirmed wildlife, not merely excluded
            # "everything else."
            if summary.review_outcome == VisitReviewOutcome.confirmed_bird:
                return True
            if summary.review_outcome == VisitReviewOutcome.non_bird and summary.reviewed_label:
                taxonomy = self._taxonomy_label_model_for_input(session, summary.reviewed_label)
                return bool(taxonomy is not None and is_wildlife_category(taxonomy.category))
            return False
        if review_filter == ActivityLibraryReviewFilter.non_bird:
            return summary.review_outcome == VisitReviewOutcome.non_bird
        if review_filter == ActivityLibraryReviewFilter.blank_false:
            return summary.review_outcome in {
                VisitReviewOutcome.blank,
                VisitReviewOutcome.false_positive,
            }
        if review_filter == ActivityLibraryReviewFilter.blank:
            return summary.review_outcome == VisitReviewOutcome.blank
        return summary.review_outcome == VisitReviewOutcome.ambiguous

    def list_activity_library_saved_views(self) -> list[ActivityLibrarySavedView]:
        with self.session_factory() as session:
            models = session.scalars(
                select(ActivityLibrarySavedViewModel).order_by(
                    ActivityLibrarySavedViewModel.updated_at.desc(),
                    ActivityLibrarySavedViewModel.id.desc(),
                )
            ).all()
            return [self._activity_library_saved_view_from_model(model) for model in models]

    def create_activity_library_saved_view(
        self,
        payload: ActivityLibrarySavedViewCreate,
    ) -> ActivityLibrarySavedView:
        name = payload.name.strip()
        if not name:
            raise ValueError("activity_library_saved_view_name_required")
        with self.session_factory() as session:
            with session.begin():
                count = session.scalar(select(func.count(ActivityLibrarySavedViewModel.id))) or 0
                if count >= MAX_ACTIVITY_LIBRARY_SAVED_VIEWS:
                    raise ValueError("activity_library_saved_view_limit")
                now = datetime.now(UTC)
                model = ActivityLibrarySavedViewModel(
                    id=self._next_id(
                        session,
                        ActivityLibrarySavedViewModel,
                        "activity-view",
                    ),
                    name=name,
                    filters_json=json.dumps(payload.filters.model_dump(mode="json")),
                    created_at=now,
                    updated_at=now,
                )
                session.add(model)
                session.flush()
                return self._activity_library_saved_view_from_model(model)

    def update_activity_library_saved_view(
        self,
        view_id: str,
        payload: ActivityLibrarySavedViewUpdate,
    ) -> ActivityLibrarySavedView | None:
        with self.session_factory() as session:
            with session.begin():
                model = session.get(ActivityLibrarySavedViewModel, view_id)
                if model is None:
                    return None
                if payload.name is not None:
                    name = payload.name.strip()
                    if not name:
                        raise ValueError("activity_library_saved_view_name_required")
                    model.name = name
                if payload.filters is not None:
                    # Saved definitions pass the same strict server schema as live searches.
                    model.filters_json = json.dumps(payload.filters.model_dump(mode="json"))
                model.updated_at = datetime.now(UTC)
                session.flush()
                return self._activity_library_saved_view_from_model(model)

    def delete_activity_library_saved_view(self, view_id: str) -> bool:
        with self.session_factory() as session:
            with session.begin():
                model = session.get(ActivityLibrarySavedViewModel, view_id)
                if model is None:
                    return False
                session.delete(model)
                return True

    def _activity_library_saved_view_from_model(
        self,
        model: ActivityLibrarySavedViewModel,
    ) -> ActivityLibrarySavedView:
        return ActivityLibrarySavedView(
            id=model.id,
            name=model.name,
            filters=ActivityLibraryFilters.model_validate(json.loads(model.filters_json)),
            created_at=_as_utc(model.created_at),
            updated_at=_as_utc(model.updated_at),
        )

    def create_activity_library_export_selection(
        self,
        payload: ActivityLibraryExportSelectionRequest,
    ) -> ActivityLibraryExportSelectionResponse:
        included: list[str] = []
        excluded: list[ActivityLibraryExportExclusion] = []
        with self.session_factory() as session:
            for visit_id in payload.visit_ids:
                visit_model = session.get(VisitModel, visit_id)
                if visit_model is None:
                    excluded.append(
                        ActivityLibraryExportExclusion(visit_id=visit_id, reason="missing_visit")
                    )
                    continue
                if visit_model.is_superseded:
                    excluded.append(
                        ActivityLibraryExportExclusion(visit_id=visit_id, reason="superseded")
                    )
                    continue
                visit = _visit_from_model(visit_model)
                if not self._visit_is_dataset_ready(session, visit):
                    excluded.append(
                        ActivityLibraryExportExclusion(
                            visit_id=visit_id,
                            reason="needs_review",
                        )
                    )
                    continue
                included.append(visit_id)

        if not included:
            return ActivityLibraryExportSelectionResponse(
                included_visit_ids=[],
                excluded=excluded,
            )

        # Selection only narrows the existing reviewed-export engine; it never writes truth.
        dataset_export = self.create_dataset_export(
            DatasetExportCreate(
                name=payload.name.strip(),
                reviewed_only=True,
                selected_visit_ids=included,
            )
        )
        manifest = self.build_dataset_manifest(dataset_export.id)
        if manifest is None:
            raise ValueError("activity_library_export_missing")
        return ActivityLibraryExportSelectionResponse(
            export=DatasetExportDetail(export=dataset_export, manifest=manifest),
            included_visit_ids=included,
            excluded=excluded,
        )

    def recent_visits_for_stream(
        self,
        stream_id: str,
        *,
        limit: int = 12,
        review_status: ReviewStatus | None = None,
        zone_id: str | None = None,
        start_at: datetime | None = None,
        end_at: datetime | None = None,
    ) -> list[StreamVisitSummary]:
        """Read a bounded Visit history without crossing the requested Stream."""

        bounded_limit = max(1, min(limit, 50))
        with self.session_factory() as session:
            query = (
                select(VisitModel, EventModel)
                .join(EventModel, VisitModel.event_id == EventModel.id)
                .where(
                    EventModel.stream_id == stream_id,
                    VisitModel.is_superseded.is_(False),
                )
            )
            if review_status is not None:
                query = query.where(VisitModel.review_status == review_status.value)
            if zone_id is not None:
                query = query.where(
                    func.coalesce(VisitModel.zone_id, EventModel.primary_zone_id) == zone_id
                )
            if start_at is not None:
                query = query.where(EventModel.started_at >= start_at)
            if end_at is not None:
                query = query.where(EventModel.started_at <= end_at)
            rows = session.execute(
                query.order_by(
                    EventModel.started_at.desc(),
                    EventModel.id.desc(),
                    VisitModel.id.desc(),
                ).limit(bounded_limit)
            ).all()
            return [
                self._stream_visit_summary_from_models(session, visit, event)
                for visit, event in rows
            ]

    def _stream_visit_summary_from_models(
        self,
        session: Session,
        visit: VisitModel,
        event: EventModel,
        *,
        taxonomy_index: dict[str, TaxonomyLabelModel] | None = None,
    ) -> StreamVisitSummary:
        """Build the canonical per-Visit summary. `taxonomy_index` is an
        optional, purely additive performance parameter: a caller that
        already preloaded the whole (small, bounded) taxonomy table once
        per report call (`_taxonomy_label_index`) can pass it here so this
        resolver's own `_visit_review_outcome` taxonomy lookup reuses that
        preload instead of issuing a fresh full-table scan for every
        reviewed Visit with a real species label. Omitting it (the
        default, used by every caller that does not opt in) preserves this
        method's original per-Visit query behavior exactly -- this never
        changes `review_outcome`'s *result*, only how many queries produce
        it. See `ProductRepository.place_activity_report` and
        `zone_insights` for the two callers that opt in today, and
        docs/place-activity-report-contract.md's "Taxonomy query behavior
        (hardened)" section."""

        evidence = self._motion_evidence_model_for_visit(session, visit.id)
        evidence_frames = self._visit_evidence_frames_from_visit(session, visit, event)
        primary_evidence = next(
            (frame for frame in evidence_frames if frame.is_primary),
            evidence_frames[0] if evidence_frames else None,
        )
        activity_started_at, activity_ended_at = self._visit_activity_window_for_frames(
            event,
            evidence,
            evidence_frames,
        )
        reviewed_label = self._visit_reviewed_label(session, visit, event)
        suggestion = session.scalars(
            select(SpeciesSuggestionModel)
            .where(SpeciesSuggestionModel.visit_id == visit.id)
            .order_by(
                SpeciesSuggestionModel.created_at.desc(),
                SpeciesSuggestionModel.rank,
                SpeciesSuggestionModel.id.desc(),
            )
        ).first()
        effective_zone_id = visit.zone_id or event.primary_zone_id
        zone = (
            session.get(ZoneModel, effective_zone_id)
            if effective_zone_id is not None
            else None
        )
        if zone is not None and zone.stream_id != event.stream_id:
            zone = None

        duration_seconds = (
            max(0.0, (activity_ended_at - activity_started_at).total_seconds())
            if activity_ended_at is not None
            else 0.0
        )
        return StreamVisitSummary(
            id=visit.id,
            event_id=event.id,
            stream_id=event.stream_id,
            captured_at=(
                primary_evidence.captured_at if primary_evidence is not None else activity_started_at
            ),
            activity_started_at=activity_started_at,
            activity_ended_at=activity_ended_at,
            duration_seconds=duration_seconds,
            zone_id=zone.id if zone is not None else None,
            zone_name=zone.name if zone is not None else None,
            zone_type=ZoneType(zone.zone_type) if zone is not None else None,
            review_status=ReviewStatus(visit.review_status),
            reviewed_label=reviewed_label,
            review_outcome=self._visit_review_outcome(
                session,
                review_status=ReviewStatus(visit.review_status),
                reviewed_label=reviewed_label,
                taxonomy_index=taxonomy_index,
            ),
            suggested_label=suggestion.suggested_label if suggestion is not None else None,
            has_suggestion=suggestion is not None,
            evidence_frame_count=len(evidence_frames),
            primary_evidence=primary_evidence,
            evidence_modality=(
                "acoustic" if event.event_type == "acoustic_observation_candidate" else "visual"
            ),
        )

    def _visit_activity_window(
        self,
        event: EventModel,
        evidence: MotionEvidenceModel | None,
    ) -> tuple[datetime, datetime | None]:
        started_at = _as_utc(event.started_at)
        ended_at = _as_utc(event.ended_at) if event.ended_at is not None else None
        if evidence is None:
            return started_at, ended_at
        try:
            config = dict(json.loads(evidence.scoring_config_json))
        except (TypeError, ValueError):
            return started_at, ended_at
        return (
            _optional_datetime(config.get("activity_started_at")) or started_at,
            _optional_datetime(config.get("activity_last_seen_at")) or ended_at,
        )

    def _visit_activity_window_for_frames(
        self,
        event: EventModel,
        evidence: MotionEvidenceModel | None,
        frames: list[VisitEvidenceFrame],
    ) -> tuple[datetime, datetime | None]:
        if frames:
            ordered = sorted(
                frames,
                key=lambda frame: (
                    frame.captured_at,
                    frame.frame_sequence if frame.frame_sequence is not None else -1,
                    frame.media_asset_id,
                ),
            )
            started_at = ordered[0].captured_at
            ended_at = ordered[-1].captured_at
            # `event.ended_at` is a raw persisted column -- may come back
            # naive from SQLite -- while `started_at` is always an
            # already-`_as_utc`-normalized frame timestamp; normalize before
            # comparing, matching this file's established convention (see
            # `_visit_activity_window`, directly below) to avoid a naive/aware
            # comparison error.
            normalized_event_ended_at = (
                _as_utc(event.ended_at) if event.ended_at is not None else None
            )
            if (
                started_at == ended_at
                and len(ordered) == 1
                and ordered[0].content_type.startswith("audio/")
                and normalized_event_ended_at is not None
                and normalized_event_ended_at > started_at
            ):
                # A single audio evidence frame can only carry one instant
                # (`VisitEvidenceLinkModel.captured_at` is the BirdNET window's
                # start), but the acoustic Event's own window genuinely spans
                # the clip's real start/end (see `create_acoustic_candidate_
                # visit`) -- prefer that honest duration over a false
                # "Duration 0 sec" (Everyday Product / Discovery UX Closure v1).
                # Scoped to audio specifically: an image Visit's single frame
                # legitimately means an instantaneous capture.
                return started_at, normalized_event_ended_at
            return started_at, ended_at
        return self._visit_activity_window(event, evidence)

    def _visit_reviewed_label(
        self,
        session: Session,
        visit: VisitModel,
        event: EventModel,
    ) -> str | None:
        if visit.reviewed_label:
            return visit.reviewed_label
        labels = [
            *self._review_label_models_for_visit(session, visit.id),
            *self._review_label_models_for_event(session, event.id),
        ]
        return max(labels, key=lambda label: label.created_at).label if labels else None

    def _visit_review_outcome(
        self,
        session: Session,
        *,
        review_status: ReviewStatus,
        reviewed_label: str | None,
        taxonomy_index: dict[str, TaxonomyLabelModel] | None = None,
    ) -> VisitReviewOutcome:
        """`taxonomy_index`, when supplied, is forwarded to
        `_taxonomy_label_model_for_input` so a report-scoped caller
        resolving many Visits pays for one preloaded table scan instead of
        one fresh scan per reviewed Visit with a real species label. See
        `_stream_visit_summary_from_models`'s docstring."""

        if review_status == ReviewStatus.needs_review:
            return VisitReviewOutcome.needs_review
        if review_status == ReviewStatus.rejected:
            return VisitReviewOutcome.rejected
        if not reviewed_label:
            return VisitReviewOutcome.reviewed_other

        key = _taxonomy_key(reviewed_label)
        if key == "false_positive":
            return VisitReviewOutcome.false_positive
        if key in {"blank", "empty", "no_activity", "no_animal"}:
            return VisitReviewOutcome.blank
        if key in {"ambiguous", "unknown_bird", "unknown_animal", "unknown"}:
            return VisitReviewOutcome.ambiguous
        if key in {"non_bird", "non_bird_activity"}:
            return VisitReviewOutcome.non_bird

        taxonomy = self._taxonomy_label_model_for_input(
            session, reviewed_label, taxonomy_index=taxonomy_index
        )
        if taxonomy is not None:
            if taxonomy.category == LabelCategory.bird.value:
                return VisitReviewOutcome.confirmed_bird
            if taxonomy.category == LabelCategory.false_positive.value:
                return VisitReviewOutcome.false_positive
            return VisitReviewOutcome.non_bird
        return VisitReviewOutcome.reviewed_other

    def dashboard_summary(
        self,
        runtime_by_stream: dict[str, DashboardStreamRuntimeStatus] | None = None,
        *,
        now: datetime | None = None,
        local_date: date | None = None,
    ) -> DashboardSummary:
        """Build the bounded landing-page view from product state, never suggestions."""

        runtime_by_stream = runtime_by_stream or {}
        local_now = (now or datetime.now().astimezone()).astimezone()
        selected_local_day = local_date or local_now.date()
        local_day_start = datetime.combine(
            selected_local_day,
            datetime.min.time(),
            local_now.tzinfo,
        )
        next_local_day_start = local_day_start + timedelta(days=1)
        day_start = _as_utc(local_day_start)
        day_end = _as_utc(next_local_day_start)

        with self.session_factory() as session:
            configured_stream_count = (
                session.scalar(
                    select(func.count(StreamModel.id))
                    .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                    .where(CameraSourceModel.status != SourceStatus.archived.value)
                )
                or 0
            )
            real_stream_count = (
                session.scalar(
                    select(func.count(StreamModel.id))
                    .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                    # Deliberately keys off the Source's *effective* provider
                    # configuration, the same field `engine_active`/
                    # `live_active`/`source_active` already gate on in
                    # `_dashboard_runtime_by_stream` -- not the Source's own
                    # `kind`, which records only how a Source was originally
                    # created and never updates when its provider
                    # configuration is later changed (for example, Guided
                    # Camera Editing repurposing the seeded demo Source into
                    # a real `camera_node` Source keeps `kind="demo"`
                    # forever; filtering on stale `kind` alone would make
                    # that genuinely real, actively observing camera
                    # disappear from this denominator while it still counted
                    # in the numerator -- a nonsensical "observing more
                    # cameras than exist"). No `SourceProviderConfiguration
                    # Model` row is ever eagerly seeded for a fresh demo
                    # Source, though -- `_default_source_provider_key`
                    # resolves its *effective* provider_key ("demo") from
                    # `kind` alone in that case -- so this replicates that
                    # exact fallback in SQL via an outer join: a real row's
                    # own `provider_key` wins when present, `kind` decides
                    # only when no row exists yet.
                    .outerjoin(
                        SourceProviderConfigurationModel,
                        SourceProviderConfigurationModel.source_id == CameraSourceModel.id,
                    )
                    .where(
                        CameraSourceModel.status != SourceStatus.archived.value,
                        or_(
                            and_(
                                SourceProviderConfigurationModel.source_id.isnot(None),
                                SourceProviderConfigurationModel.provider_key != "demo",
                            ),
                            and_(
                                SourceProviderConfigurationModel.source_id.is_(None),
                                CameraSourceModel.kind != SourceKind.demo.value,
                            ),
                        ),
                    )
                )
                or 0
            )
            stream_models = session.scalars(
                select(StreamModel)
                .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                .where(CameraSourceModel.status != SourceStatus.archived.value)
                .order_by(StreamModel.id)
                .limit(50)
            ).all()
            sources_by_id = {
                source.id: source
                for source in session.scalars(
                    select(CameraSourceModel).where(
                        CameraSourceModel.id.in_({stream.source_id for stream in stream_models})
                    )
                ).all()
            }
            zone_overlays_by_stream: dict[str, list[DashboardZoneOverlay]] = {
                stream.id: [] for stream in stream_models
            }
            stream_ids = set(zone_overlays_by_stream)
            if stream_ids:
                for zone in session.scalars(
                    select(ZoneModel)
                    .where(ZoneModel.stream_id.in_(stream_ids))
                    .order_by(ZoneModel.stream_id, ZoneModel.id)
                ).all():
                    zone_overlays_by_stream.setdefault(zone.stream_id, []).append(
                        DashboardZoneOverlay(
                            id=zone.id,
                            stream_id=zone.stream_id,
                            name=zone.name,
                            zone_type=ZoneType(zone.zone_type),
                            polygon=[Point(**point) for point in json.loads(zone.polygon_json)],
                            is_active=zone.is_active,
                        )
                    )
            needs_review_visit_count = (
                session.scalar(
                    select(func.count(VisitModel.id))
                    .join(EventModel, VisitModel.event_id == EventModel.id)
                    .where(
                        VisitModel.review_status == ReviewStatus.needs_review.value,
                        VisitModel.is_superseded.is_(False),
                    )
                )
                or 0
            )
            needs_review_counts = dict(
                session.execute(
                    select(EventModel.stream_id, func.count(VisitModel.id))
                    .join(VisitModel, VisitModel.event_id == EventModel.id)
                    .where(
                        VisitModel.review_status == ReviewStatus.needs_review.value,
                        VisitModel.is_superseded.is_(False),
                    )
                    .group_by(EventModel.stream_id)
                ).all()
            )

            warnings: list[str] = []
            stream_summaries: list[DashboardStreamSummary] = []
            camera_attention: list[CameraHealthSummary] = []
            for stream in stream_models:
                source = sources_by_id.get(stream.source_id)
                source_name = source.name if source is not None else "Unavailable Source"
                source_status = (
                    SourceStatus(source.status)
                    if source is not None
                    else SourceStatus.needs_setup
                )
                try:
                    playback = self.get_stream_playback_status(stream.id)
                except Exception:
                    # One unavailable adapter must not empty the operations view.
                    playback = None
                    warnings.append(f"Readiness is temporarily unavailable for {stream.name}.")
                latest_row = session.execute(
                    select(VisitModel, EventModel)
                    .join(EventModel, VisitModel.event_id == EventModel.id)
                    .where(
                        EventModel.stream_id == stream.id,
                        VisitModel.is_superseded.is_(False),
                    )
                    .order_by(
                        EventModel.started_at.desc(),
                        EventModel.id.desc(),
                        VisitModel.id.desc(),
                    )
                    .limit(1)
                ).first()
                latest_visit = (
                    self._dashboard_visit_summary_from_models(session, latest_row[0], latest_row[1])
                    if latest_row is not None
                    else None
                )
                runtime = runtime_by_stream.get(stream.id, DashboardStreamRuntimeStatus())
                camera_health = self._camera_health_summary_from_models(
                    session,
                    stream,
                    source=source,
                    playback=playback,
                    now=_as_utc(local_now),
                    open_activity_session_count=runtime.open_activity_session_count,
                    latest_visit_at=(
                        latest_visit.activity_started_at if latest_visit is not None else None
                    ),
                    engine_terminally_unavailable=runtime.engine_terminally_unavailable,
                    engine_unavailable_message=runtime.engine_unavailable_message,
                )
                stream_summaries.append(
                    DashboardStreamSummary(
                        stream_id=stream.id,
                        stream_name=stream.name,
                        source_id=stream.source_id,
                        source_name=source_name,
                        source_kind=(
                            SourceKind(source.kind)
                            if source is not None
                            else SourceKind.manual_upload
                        ),
                        source_status=source_status,
                        setup_incomplete=(
                            source_status == SourceStatus.needs_setup
                            or playback is None
                            or playback.status
                            in {
                                StreamPlaybackStatusValue.not_configured,
                                StreamPlaybackStatusValue.needs_stream_url,
                            }
                        ),
                        availability_status=(
                            playback.status
                            if playback is not None
                            else StreamPlaybackStatusValue.unavailable
                        ),
                        availability_message=(
                            playback.message
                            if playback is not None
                            else "Readiness is temporarily unavailable."
                        ),
                        playback_kind=(
                            playback.playback_kind
                            if playback is not None
                            else StreamPlaybackKind.placeholder
                        ),
                        live_preview=self._dashboard_live_preview(playback),
                        zone_overlays=zone_overlays_by_stream.get(stream.id, []),
                        monitoring_active=runtime.monitoring_active,
                        monitor_control=runtime.monitor_control,
                        can_start_monitor=runtime.can_start_monitor,
                        can_stop_monitor=runtime.can_stop_monitor,
                        open_activity_session_count=runtime.open_activity_session_count,
                        ready_activity_session_count=runtime.ready_activity_session_count,
                        needs_review_visit_count=needs_review_counts.get(stream.id, 0),
                        latest_visit=latest_visit,
                        camera_health=camera_health,
                    )
                )
                if camera_health.state not in {
                    CameraHealthState.healthy,
                    CameraHealthState.starting,
                    CameraHealthState.stopped,
                }:
                    camera_attention.append(camera_health)

            recent_rows = session.execute(
                select(VisitModel, EventModel)
                .join(EventModel, VisitModel.event_id == EventModel.id)
                .where(VisitModel.is_superseded.is_(False))
                .order_by(
                    EventModel.started_at.desc(),
                    EventModel.id.desc(),
                    VisitModel.id.desc(),
                )
                .limit(25)
            ).all()
            # Everyday Discovery / Product Experience v2 (Phase B; see docs/
            # multimodal-list-presentation-contract.md): a confidently-
            # associated visual+acoustic pair collapses to one row here so
            # it never reads as two independent encounters -- see
            # `_collapse_associated_multimodal_pairs`'s own docstring.
            recent_activity = self._collapse_associated_cross_camera_pairs(
                session,
                self._collapse_associated_multimodal_pairs(
                    session,
                    [
                        self._dashboard_visit_summary_from_models(session, visit, event)
                        for visit, event in recent_rows
                    ],
                ),
            )
            # The query is bounded so the landing surface cannot become an event log.

            needs_review_visits = [
                visit
                for visit in recent_activity
                if visit.review_status == ReviewStatus.needs_review
            ][:12]
            if len(needs_review_visits) < 12:
                needs_rows = session.execute(
                    select(VisitModel, EventModel)
                    .join(EventModel, VisitModel.event_id == EventModel.id)
                    .where(
                        VisitModel.review_status == ReviewStatus.needs_review.value,
                        VisitModel.is_superseded.is_(False),
                    )
                    .order_by(
                        EventModel.started_at.desc(),
                        EventModel.id.desc(),
                        VisitModel.id.desc(),
                    )
                    .limit(12)
                ).all()
                needs_review_visits = [
                    self._dashboard_visit_summary_from_models(session, visit, event)
                    for visit, event in needs_rows
                ]

            reviewed_today_rows = session.execute(
                select(VisitModel, EventModel)
                .join(EventModel, VisitModel.event_id == EventModel.id)
                .where(
                    VisitModel.review_status == ReviewStatus.reviewed.value,
                    VisitModel.is_superseded.is_(False),
                    EventModel.started_at >= day_start,
                    EventModel.started_at < day_end,
                )
                .order_by(
                    EventModel.started_at.desc(),
                    EventModel.id.desc(),
                    VisitModel.id.desc(),
                )
            ).all()
            bird_observations, non_bird_activity = self._dashboard_reviewed_observations(
                session,
                reviewed_today_rows,
            )
            product_review_items = self._review_queue_items(session)
            actionable_animal_visits: list[DashboardVisitSummary] = []
            for item in product_review_items:
                if item.product_category != "animal" or item.visit_id is None:
                    continue
                visit_model = session.get(VisitModel, item.visit_id)
                event_model = (
                    session.get(EventModel, visit_model.event_id)
                    if visit_model is not None
                    else None
                )
                if visit_model is None or event_model is None:
                    continue
                actionable_animal_visits.append(
                    self._dashboard_visit_summary_from_models(
                        session,
                        visit_model,
                        event_model,
                    )
                )
                if len(actionable_animal_visits) == 12:
                    break
            legacy_activity_count = sum(
                item.product_category == "legacy_activity"
                for item in product_review_items
            )
            today = self._dashboard_today_summary(
                session,
                day_start=day_start,
                day_end=day_end,
                local_timezone=local_now.tzinfo,
                camera_attention=camera_attention,
                stream_ids=list(stream_ids),
            )

            return DashboardSummary(
                local_day=local_day_start.date().isoformat(),
                generated_at=_as_utc(local_now),
                headline=DashboardHeadline(
                    configured_stream_count=configured_stream_count,
                    real_stream_count=real_stream_count,
                    monitored_stream_count=sum(
                        summary.monitoring_active for summary in stream_summaries
                    ),
                    open_activity_session_count=sum(
                        summary.open_activity_session_count
                        for summary in stream_summaries
                    ),
                    needs_review_visit_count=needs_review_visit_count,
                    actionable_animal_visit_count=len(actionable_animal_visits),
                    legacy_activity_count=legacy_activity_count,
                    reviewed_observation_count_today=sum(
                        observation.observation_count for observation in bird_observations
                    ),
                ),
                today=today,
                streams=stream_summaries,
                needs_review_visits=needs_review_visits,
                actionable_animal_visits=actionable_animal_visits,
                today_observations=bird_observations,
                reviewed_non_bird_activity=non_bird_activity,
                recent_activity=recent_activity,
                camera_attention=camera_attention[:12],
                warnings=warnings[:12],
            )

    @staticmethod
    def _best_moments_diversity_capped(
        ranked: Sequence[DashboardVisitSummary], *, limit: int, max_per_label: int,
    ) -> list[DashboardVisitSummary]:
        """Everyday Discovery / Product Experience v2 (Phase D): take the
        top `limit` items from an already-ranked list, but skip a candidate
        once its own reviewed (or, absent that, suggested) label has already
        contributed `max_per_label` -- a simple, interpretable diversity cap
        so one common species confirmed several times in one day cannot
        occupy every "Best moments" slot. A Visit with neither a reviewed
        nor a suggested label (an unresolved encounter) is never capped --
        there is no label to be "the same species" as another one by.
        `ranked`'s own ordering is otherwise fully preserved; this never
        reorders, only selectively skips.
        """

        selected: list[DashboardVisitSummary] = []
        label_counts: Counter[str] = Counter()
        for item in ranked:
            if len(selected) == limit:
                break
            label = item.reviewed_label or item.suggested_label
            if label is not None and label_counts[label] >= max_per_label:
                continue
            selected.append(item)
            if label is not None:
                label_counts[label] += 1
        return selected

    def _dashboard_today_summary(
        self,
        session: Session,
        *,
        day_start: datetime,
        day_end: datetime,
        local_timezone: Any,
        camera_attention: list[CameraHealthSummary],
        stream_ids: list[str],
    ) -> DashboardTodaySummary:
        """Build one bounded local-day nature story without treating suggestions as truth."""

        rows = session.execute(
            select(VisitModel, EventModel, StreamModel, CameraSourceModel)
            .join(EventModel, VisitModel.event_id == EventModel.id)
            .join(StreamModel, EventModel.stream_id == StreamModel.id)
            .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
            .where(
                VisitModel.is_superseded.is_(False),
                CameraSourceModel.status != SourceStatus.archived.value,
                EventModel.started_at >= day_start,
                EventModel.started_at < day_end,
            )
            .order_by(EventModel.started_at.desc(), EventModel.id.desc(), VisitModel.id.desc())
            .limit(501)
        ).all()
        truncated = len(rows) > 500
        qualified: list[DashboardVisitSummary] = []
        confirmed_species: dict[str, list[DashboardVisitSummary]] = {}
        likely_species: dict[str, list[DashboardVisitSummary]] = {}
        unresolved: list[DashboardVisitSummary] = []
        for visit, event, _stream, _source in rows[:500]:
            if not self._dashboard_today_is_nature_event(event.event_type):
                continue
            summary = self._dashboard_visit_summary_from_models(session, visit, event)
            evidence = self._motion_evidence_for_review_queue_item(
                session,
                event_id=event.id,
                visit_id=visit.id,
                media_asset_id=None,
            )
            context = _review_queue_product_context(
                session=session,
                stream_id=event.stream_id,
                evidence=evidence,
                review_status=ReviewStatus(visit.review_status),
                media_asset=self._media_asset_for_path_from_session(
                    session, visit.representative_media_path
                ),
                evidence_frames=self._visit_evidence_frames_from_visit(session, visit, event),
                fallback_captured_at=event.started_at,
                event_type=event.event_type,
                subject_label=visit.subject_label,
            )
            if context["is_demo_source"] or context["detector_class"] != "animal":
                continue
            if not self._dashboard_today_is_countable_animal_visit(summary):
                continue
            if not self._dashboard_today_is_nature_visit(summary):
                continue
            qualified.append(summary)
            if summary.review_status == ReviewStatus.needs_review:
                unresolved.append(summary)
            if self._dashboard_today_is_confirmed_species(session, summary):
                assert summary.reviewed_label is not None
                confirmed_species.setdefault(
                    self._normalize_label_from_session(session, summary.reviewed_label), []
                ).append(summary)
            elif self._dashboard_today_is_likely_species(session, summary):
                assert summary.suggested_label is not None
                likely_species.setdefault(
                    self._normalize_label_from_session(session, summary.suggested_label), []
                ).append(summary)

        # Acoustic Productization, Licensing & Field Acceptance v1: a
        # confidently-associated visual+acoustic (or cross-camera) pair is
        # one real encounter, not two -- collapse once here and reuse this
        # single collapsed view for every "how many/where/when" count below
        # (zone/hour activity, confirmed-bird total), instead of computing
        # each from the raw pre-collapse `qualified` list independently.
        # `best_moments` below already collapsed `qualified` itself (Everyday
        # Discovery / Product Experience v2); this is that exact same
        # collapse, computed once and shared, not a second policy.
        # `unresolved`/`needs_help` and `detector_qualified_animal_visit_
        # count` deliberately keep using the raw, uncollapsed view -- those
        # represent outstanding review work / raw detector qualification,
        # not "how many animals were seen," so per-Visit independence is the
        # honest count there (a human may still need to separately correct
        # each side of a pair), not a defect to fix.
        collapsed_qualified = self._collapse_associated_cross_camera_pairs(
            session, self._collapse_associated_multimodal_pairs(session, qualified),
        )
        zone_counts: Counter[tuple[str | None, str]] = Counter()
        hour_counts: Counter[int] = Counter()
        for summary in collapsed_qualified:
            zone_counts[(summary.zone_id, summary.zone_name or "No Zone")] += 1
            hour_counts[summary.activity_started_at.astimezone(local_timezone).hour] += 1

        detector_qualified_animal_visit_count = 0
        detector_count_rows = session.execute(
            select(VisitModel, EventModel, StreamModel, CameraSourceModel)
            .join(EventModel, VisitModel.event_id == EventModel.id)
            .join(StreamModel, EventModel.stream_id == StreamModel.id)
            .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
            .where(
                VisitModel.is_superseded.is_(False),
                CameraSourceModel.status != SourceStatus.archived.value,
                EventModel.started_at < day_end,
                or_(EventModel.ended_at.is_(None), EventModel.ended_at > day_start),
            )
            .order_by(EventModel.started_at.desc(), EventModel.id.desc(), VisitModel.id.desc())
            .limit(501)
        ).all()
        detector_count_truncated = len(detector_count_rows) > 500
        for visit, event, _stream, _source in detector_count_rows[:500]:
            if not self._dashboard_today_is_nature_event(event.event_type):
                continue
            summary = self._dashboard_visit_summary_from_models(session, visit, event)
            if not self._dashboard_today_is_countable_animal_visit(summary):
                continue
            evidence = self._motion_evidence_for_review_queue_item(
                session,
                event_id=event.id,
                visit_id=visit.id,
                media_asset_id=None,
            )
            context = _review_queue_product_context(
                session=session,
                stream_id=event.stream_id,
                evidence=evidence,
                review_status=ReviewStatus(visit.review_status),
                media_asset=self._media_asset_for_path_from_session(
                    session, visit.representative_media_path
                ),
                evidence_frames=self._visit_evidence_frames_from_visit(session, visit, event),
                fallback_captured_at=event.started_at,
                event_type=event.event_type,
                subject_label=visit.subject_label,
            )
            if not context["is_demo_source"] and context["detector_class"] == "animal":
                detector_qualified_animal_visit_count += 1

        history_rows = session.execute(
            select(VisitModel, EventModel, StreamModel, CameraSourceModel)
            .join(EventModel, VisitModel.event_id == EventModel.id)
            .join(StreamModel, EventModel.stream_id == StreamModel.id)
            .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
            .where(
                VisitModel.is_superseded.is_(False),
                VisitModel.review_status == ReviewStatus.reviewed.value,
                CameraSourceModel.status != SourceStatus.archived.value,
                EventModel.started_at >= day_start - timedelta(days=14),
                EventModel.started_at < day_end,
            )
            .order_by(EventModel.started_at.desc(), EventModel.id.desc(), VisitModel.id.desc())
            .limit(2001)
        ).all()
        history_truncated = len(history_rows) > 2000
        species_history: dict[str, list[DashboardVisitSummary]] = {}
        for visit, event, _stream, _source in history_rows[:2000]:
            if not self._dashboard_today_is_nature_event(event.event_type):
                continue
            summary = self._dashboard_visit_summary_from_models(session, visit, event)
            if not (
                self._dashboard_today_is_nature_visit(summary)
                and self._dashboard_today_is_confirmed_species(session, summary)
            ):
                continue
            assert summary.reviewed_label is not None
            species_history.setdefault(
                self._normalize_label_from_session(session, summary.reviewed_label), []
            ).append(summary)

        # Canonical New/Regular Species v1 (Everyday Discovery / Product
        # Experience v2; see docs/canonical-new-regular-species-contract.md):
        # `new_today`/`recent_regulars` now consume the exact same
        # `compute_species_historical_statuses` machinery Today's own Place
        # Activity Report digest and Bird Log already use, rather than a
        # second, independent computation that was bird-only, coverage-blind,
        # and could (and did) disagree with them for the same species on the
        # same day. `period_start_at`/`period_end_at` are today's own
        # `day_start`/`day_end` -- the identical boundaries `TodayReportPanel`
        # requests via `getPlaceActivityReport(todayLocalRange())` -- so a
        # taxon's "new"/"first_record"/"regular" verdict here is always
        # identical to the one the digest would show for the same taxon. This
        # also replaces the previous `previous_rows` (5000-row-capped) scan
        # with an unbounded `GROUP BY` aggregate -- strictly cheaper, and
        # immune to the truncation-driven false "new" the old cap allowed.
        taxonomy_index = self._taxonomy_label_index(session)
        species_historical_statuses = self._historical_place_baseline_and_species_statuses(
            session,
            stream_ids=stream_ids,
            taxonomy_index=taxonomy_index,
            window_end_at=day_end,
            local_timezone=local_timezone,
            period_start_at=day_start,
            period_end_at=day_end,
        ).species_historical_statuses
        new_today = [
            self._dashboard_today_species(
                session, label, summaries, distinct_days=1, historical_status=status.status,
            )
            for label, summaries in confirmed_species.items()
            if (status := species_historical_statuses.get(label)) is not None
            and status.status in ("new", "first_record")
        ]
        regulars = [
            self._dashboard_today_species(
                session,
                label,
                summaries,
                distinct_days=len(
                    {
                        item.activity_started_at.astimezone(local_timezone).date()
                        for item in summaries
                    }
                ),
                historical_status="regular",
            )
            for label, summaries in species_history.items()
            if (status := species_historical_statuses.get(label)) is not None
            and status.status == "regular"
        ]
        order = lambda item: (item.latest_visit.activity_started_at, item.label)
        likely_today = [
            self._dashboard_today_species(
                session, label, summaries, distinct_days=1, is_confirmed=False,
            )
            for label, summaries in likely_species.items()
        ]
        # Everyday Discovery / Product Experience v2 (Phase B/D): collapse
        # before ranking/truncating to 6, not after -- a confidently-
        # associated pair should cost one "Best moments" slot, not two, and
        # collapsing first lets a real 7th distinct encounter fill the freed
        # slot. See `_collapse_associated_multimodal_pairs`'s own docstring.
        #
        # Phase D -- Best Moments: a fixed-tier, interpretable ranking (the
        # same bounded-tuple house style `daily_digest.py`'s own `_sort_key`
        # already established -- never a learned/weighted score), not pure
        # recency. Tiers, in priority order: reviewed with visible evidence;
        # multimodal (doctrine's own named "multimodal evidence" signal);
        # strong representative evidence (the identical `resolution_
        # provenance == "synchronized"` signal `place_activity_report_
        # adapter.has_strong_representative_evidence` already uses -- no new
        # threshold invented); has a real subject region; most recent.
        # `_best_moments_diversity_capped` then bounds any single species to
        # at most 2 of the 6 slots so one common, frequently-confirmed
        # species cannot crowd out a rarer single encounter.
        best_moments = self._best_moments_diversity_capped(
            sorted(
                collapsed_qualified,
                key=lambda item: (
                    item.review_status == ReviewStatus.reviewed and item.primary_evidence is not None,
                    item.evidence_modality == "seen_and_heard",
                    bool(
                        item.primary_evidence
                        and item.primary_evidence.resolution_provenance == "synchronized"
                    ),
                    bool(item.primary_evidence and item.primary_evidence.normalized_track_box),
                    item.activity_started_at,
                    item.id,
                ),
                reverse=True,
            ),
            limit=6,
            max_per_label=2,
        )
        warnings = []
        if truncated or detector_count_truncated or history_truncated:
            warnings.append("Today is showing a bounded recent set of Visits.")
        return DashboardTodaySummary(
            detector_qualified_animal_visit_count=detector_qualified_animal_visit_count,
            confirmed_bird_visit_count=sum(
                item.review_outcome == VisitReviewOutcome.confirmed_bird for item in collapsed_qualified
            ),
            confirmed_species_count=len(confirmed_species),
            unresolved_animal_visit_count=len(unresolved),
            best_moments=best_moments,
            new_today=sorted(new_today, key=order, reverse=True)[:12],
            recent_regulars=sorted(regulars, key=order, reverse=True)[:12],
            likely_today=sorted(likely_today, key=order, reverse=True)[:12],
            activity_by_zone=[
                DashboardTodayZoneActivity(
                    zone_id=zone_id,
                    zone_name=zone_name,
                    animal_visit_count=count,
                )
                for (zone_id, zone_name), count in sorted(
                    zone_counts.items(),
                    key=lambda item: (-item[1], item[0][1], item[0][0] or ""),
                )[:50]
            ],
            activity_by_hour=[
                DashboardTodayHourActivity(hour=hour, animal_visit_count=hour_counts[hour])
                for hour in range(24)
            ],
            needs_help=sorted(
                unresolved,
                key=lambda item: (item.activity_started_at, item.id),
                reverse=True,
            )[:3],
            observation_health=camera_attention[:12],
            warnings=warnings,
        )

    @staticmethod
    def _dashboard_today_is_nature_event(event_type: str) -> bool:
        lowered = event_type.lower()
        return not any(marker in lowered for marker in ("demo", "test", "legacy"))

    @staticmethod
    def _dashboard_today_is_countable_animal_visit(summary: DashboardVisitSummary) -> bool:
        return summary.review_status != ReviewStatus.rejected and (
            summary.reviewed_label is None
            or _taxonomy_key(summary.reviewed_label)
            not in {
                "blank",
                "empty",
                "no_activity",
                "no_animal",
                "false_positive",
            }
        )

    @staticmethod
    def _dashboard_today_is_nature_visit(summary: DashboardVisitSummary) -> bool:
        if summary.review_status == ReviewStatus.rejected:
            return False
        if summary.reviewed_label is None:
            return True
        return _taxonomy_key(summary.reviewed_label) not in {
            "person",
            "vehicle",
            "demo",
            "test",
            "legacy",
            "blank",
            "empty",
            "no_activity",
            "no_animal",
            "false_positive",
        }

    def _dashboard_today_is_confirmed_species(
        self,
        session: Session,
        summary: DashboardVisitSummary,
    ) -> bool:
        # Everyday Discovery / Product Experience v2 -- Canonical New/Regular
        # Species v1 (see docs/canonical-new-regular-species-contract.md):
        # wildlife-inclusive, matching `_wildlife_journal_confirmed_records`'s
        # identical bird-or-wildlife boundary. A confirmed non-bird wildlife
        # taxon (squirrel, deer, ...) is real historical-species truth, not
        # just a bird -- this was previously bird-only, one of the two
        # disagreeing New/Regular implementations the contract closes.
        if summary.review_outcome not in (
            VisitReviewOutcome.confirmed_bird,
            VisitReviewOutcome.non_bird,
        ):
            return False
        if not summary.reviewed_label:
            return False
        taxonomy = self._taxonomy_label_model_for_input(session, summary.reviewed_label)
        return bool(
            taxonomy is not None
            and taxonomy.is_species
            and is_wildlife_category(taxonomy.category)
        )

    def _dashboard_today_is_likely_species(
        self,
        session: Session,
        summary: DashboardVisitSummary,
    ) -> bool:
        """A provisional (unreviewed) counterpart to `_dashboard_today_is_
        confirmed_species`: true only for a Visit that still needs review
        but already carries an automatic top-1 BioCLIP species suggestion.
        Human truth always wins first -- this only ever applies once
        `_dashboard_today_is_confirmed_species` has already returned False
        for the same summary (see the caller), so a reviewed Visit can
        never also be counted as "likely"."""

        if summary.review_status != ReviewStatus.needs_review or not summary.suggested_label:
            return False
        taxonomy = self._taxonomy_label_model_for_input(session, summary.suggested_label)
        return bool(taxonomy is not None and taxonomy.is_species)

    def _dashboard_today_species(
        self,
        session: Session,
        label: str,
        summaries: list[DashboardVisitSummary],
        *,
        distinct_days: int,
        is_confirmed: bool = True,
        historical_status: SpeciesHistoricalStatusValue | None = None,
    ) -> DashboardTodaySpecies:
        taxonomy = self._taxonomy_label_model_for_input(session, label)
        latest = max(summaries, key=lambda item: (item.activity_started_at, item.id))
        return DashboardTodaySpecies(
            label=label,
            display_name=taxonomy.display_name if taxonomy is not None else label,
            distinct_days_seen=distinct_days,
            latest_visit=latest,
            is_confirmed=is_confirmed,
            historical_status=historical_status,
        )

    @staticmethod
    def _dashboard_live_preview(
        playback: StreamPlaybackStatus | None,
    ) -> DashboardLivePreview:
        """Return only safe playback capability metadata for an explicit tile action."""

        if playback is None:
            return DashboardLivePreview(
                message="Preview unavailable while this Stream's readiness is loading."
            )
        if not playback.supports_live_playback:
            return DashboardLivePreview(message="Preview unavailable. " + playback.message)
        if playback.playback_kind in {
            StreamPlaybackKind.rtsp,
            StreamPlaybackKind.local_usb,
            StreamPlaybackKind.windows_dshow,
            StreamPlaybackKind.camera_node,
        }:
            return DashboardLivePreview(
                kind=DashboardLivePreviewKind.backend_session,
                available=True,
                media_kind="image",
                message="Select Show live view to open this local preview.",
            )
        if playback.playback_kind in {
            StreamPlaybackKind.mjpeg,
            StreamPlaybackKind.browser_video,
            StreamPlaybackKind.hls,
        }:
            safe_preview_url = ProductRepository._safe_browser_preview_url(
                playback.preview_url
            )
            if safe_preview_url is not None:
                return DashboardLivePreview(
                    kind=DashboardLivePreviewKind.browser_direct,
                    available=True,
                    media_kind=(
                        "image"
                        if playback.playback_kind == StreamPlaybackKind.mjpeg
                        else "video"
                    ),
                    preview_url=safe_preview_url,
                    message="Select Show live view to load this configured browser preview.",
                )
        return DashboardLivePreview(message="Preview unavailable. " + playback.message)

    @staticmethod
    def _safe_browser_preview_url(value: str | None) -> str | None:
        """Never surface a credential-bearing configured URL in an overview response."""

        if not value:
            return None
        try:
            parsed = urlsplit(value)
        except ValueError:
            return None
        if (
            parsed.scheme.lower() not in {"http", "https"}
            or not parsed.hostname
            or parsed.username is not None
            or parsed.password is not None
        ):
            return None
        return value

    def _dashboard_visit_summary_from_models(
        self,
        session: Session,
        visit: VisitModel,
        event: EventModel,
    ) -> DashboardVisitSummary:
        stream = session.get(StreamModel, event.stream_id)
        if stream is None:
            raise ValueError("dashboard_visit_missing_stream")
        source = session.get(CameraSourceModel, stream.source_id)
        return DashboardVisitSummary(
            **self._stream_visit_summary_from_models(session, visit, event).model_dump(),
            stream_name=stream.name,
            source_id=stream.source_id,
            source_name=source.name if source is not None else "Unavailable Source",
        )

    def _dashboard_reviewed_observations(
        self,
        session: Session,
        rows: list[tuple[VisitModel, EventModel]],
    ) -> tuple[list[DashboardReviewedObservation], list[DashboardReviewedObservation]]:
        birds: dict[str, list[DashboardVisitSummary]] = {}
        non_birds: dict[str, list[DashboardVisitSummary]] = {}
        for visit, event in rows:
            summary = self._dashboard_visit_summary_from_models(session, visit, event)
            if not summary.reviewed_label:
                continue
            normalized_label = self._normalize_label_from_session(session, summary.reviewed_label)
            if summary.review_outcome == VisitReviewOutcome.confirmed_bird:
                birds.setdefault(normalized_label, []).append(summary)
            elif summary.review_outcome == VisitReviewOutcome.non_bird:
                non_birds.setdefault(normalized_label, []).append(summary)

        def grouped(
            values: dict[str, list[DashboardVisitSummary]],
            *,
            limit: int,
        ) -> list[DashboardReviewedObservation]:
            observations: list[DashboardReviewedObservation] = []
            for label, summaries in values.items():
                latest = max(
                    summaries,
                    key=lambda summary: (summary.activity_started_at, summary.id),
                )
                taxonomy = self._taxonomy_label_model_for_input(session, label)
                observations.append(
                    DashboardReviewedObservation(
                        label=label,
                        display_name=(taxonomy.display_name if taxonomy is not None else label),
                        category=(
                            LabelCategory(taxonomy.category)
                            if taxonomy is not None
                            else LabelCategory.unknown
                        ),
                        observation_count=len(summaries),
                        latest_visit=latest,
                    )
                )
            return sorted(
                observations,
                key=lambda observation: (
                    observation.latest_visit.activity_started_at,
                    observation.label,
                ),
                reverse=True,
            )[:limit]

        # Reviewed bird truth and reviewed non-bird activity are intentionally separate.
        return grouped(birds, limit=12), grouped(non_birds, limit=8)

    def list_media_assets(self) -> list[MediaAsset]:
        with self.session_factory() as session:
            assets = session.scalars(
                select(MediaAssetModel).order_by(MediaAssetModel.created_at, MediaAssetModel.id)
            ).all()
            return [_media_asset_from_model(asset) for asset in assets]

    def get_media_asset(self, media_id: str) -> MediaAsset | None:
        with self.session_factory() as session:
            asset = session.get(MediaAssetModel, media_id)
            return _media_asset_from_model(asset) if asset else None

    def media_asset_for_path(self, media_path: str | None) -> MediaAsset | None:
        if media_path is None:
            return None

        with self.session_factory() as session:
            return self._media_asset_for_path_from_session(session, media_path)

    def media_file_path(self, media_id: str) -> Path | None:
        asset = self.get_media_asset(media_id)
        if asset is None:
            return None
        return Path(asset.local_path)

    def list_product_alerts(
        self,
        *,
        category: AlertCategory | None = None,
        offset: int = 0,
        page_size: int = 30,
        viewer: CurrentUser | None = None,
    ) -> ProductAlertListResponse:
        """Read bounded inbox history. Reading never reconciles product
        conditions. `viewer` is optional only for internal/test callers
        that pre-date Calm Attention & Notifications v1's per-user
        preferences; every real route passes the signed-in user (Phase 16/
        18: preferences and the Viewer Needs-Help ceiling are enforced
        here, once, rather than in each caller)."""

        bounded_size = max(1, min(page_size, MAX_ALERT_PAGE_SIZE))
        bounded_offset = max(0, min(offset, 10_000))
        visible = (
            self._visible_alert_categories(viewer_role=viewer.role, user_id=viewer.id)
            if viewer is not None
            else None
        )
        if category is not None and visible is not None and category not in visible:
            return ProductAlertListResponse(items=[], next_offset=None)
        with self.session_factory() as session:
            query = select(ProductAlertModel)
            if category is not None:
                query = query.where(ProductAlertModel.category == category.value)
            elif visible is not None:
                query = query.where(ProductAlertModel.category.in_([item.value for item in visible]))
            rows = session.scalars(
                query.order_by(ProductAlertModel.created_at.desc(), ProductAlertModel.id.desc())
                .offset(bounded_offset)
                .limit(bounded_size + 1)
            ).all()
            return ProductAlertListResponse(
                items=[self._product_alert_from_model(session, row) for row in rows[:bounded_size]],
                next_offset=(bounded_offset + bounded_size if len(rows) > bounded_size else None),
            )

    def product_alert_unread(self, *, viewer: CurrentUser | None = None) -> ProductAlertUnreadResponse:
        visible = (
            self._visible_alert_categories(viewer_role=viewer.role, user_id=viewer.id)
            if viewer is not None
            else None
        )
        with self.session_factory() as session:
            unread_query = select(func.count(ProductAlertModel.id)).where(
                ProductAlertModel.read_at.is_(None),
                ProductAlertModel.dismissed_at.is_(None),
                ProductAlertModel.resolved_at.is_(None),
            )
            recent_query = select(ProductAlertModel).where(ProductAlertModel.dismissed_at.is_(None))
            if visible is not None:
                allowed_values = [item.value for item in visible]
                unread_query = unread_query.where(ProductAlertModel.category.in_(allowed_values))
                recent_query = recent_query.where(ProductAlertModel.category.in_(allowed_values))
            unread_count = session.scalar(unread_query) or 0
            recent = session.scalars(
                recent_query.order_by(ProductAlertModel.created_at.desc(), ProductAlertModel.id.desc())
                .limit(MAX_RECENT_ALERTS)
            ).all()
            return ProductAlertUnreadResponse(
                unread_count=unread_count,
                recent=[self._product_alert_from_model(session, row) for row in recent],
            )

    def mark_product_alert_read(self, alert_id: str) -> bool:
        now = datetime.now(UTC)
        with self.session_factory() as session:
            with session.begin():
                alert = session.get(ProductAlertModel, alert_id)
                if alert is None:
                    return False
                if alert.read_at is None:
                    alert.read_at = now
                    alert.updated_at = now
                return True

    def mark_product_alerts_read(self, alert_ids: list[str]) -> int:
        now = datetime.now(UTC)
        seen = {alert_id.strip() for alert_id in alert_ids if alert_id.strip()}
        with self.session_factory() as session:
            with session.begin():
                rows = session.scalars(
                    select(ProductAlertModel).where(ProductAlertModel.id.in_(list(seen)[:50]))
                ).all()
                for alert in rows:
                    if alert.read_at is None:
                        alert.read_at = now
                        alert.updated_at = now
                return len(rows)

    def dismiss_product_alert(self, alert_id: str) -> bool:
        now = datetime.now(UTC)
        with self.session_factory() as session:
            with session.begin():
                alert = session.get(ProductAlertModel, alert_id)
                if alert is None:
                    return False
                if alert.dismissed_at is None:
                    alert.dismissed_at = now
                    alert.updated_at = now
                return True

    def _product_alert_from_model(self, session: Session, alert: ProductAlertModel) -> ProductAlert:
        stream = session.get(StreamModel, alert.stream_id) if alert.stream_id else None
        zone = session.get(ZoneModel, alert.zone_id) if alert.zone_id else None
        try:
            action_data = json.loads(alert.action_parameters_json)
        except (TypeError, ValueError):
            action_data = {}
        action_type = AlertActionType(alert.action_type)
        # Action parameters were server-authored. Reconfirm targets so old history
        # never sends the browser to an arbitrary or now-invalid route.
        if action_type == AlertActionType.review_visit:
            visit = session.get(VisitModel, alert.visit_id) if alert.visit_id else None
            if visit is None or visit.is_superseded:
                action_type = AlertActionType.open_stream if stream is not None else AlertActionType.open_storage_retention
        elif action_type == AlertActionType.open_stream and stream is None:
            action_type = AlertActionType.open_storage_retention
        action = ProductAlertAction(
            action_type=action_type,
            visit_id=alert.visit_id if action_type == AlertActionType.review_visit else None,
            stream_id=alert.stream_id if action_type == AlertActionType.open_stream else None,
            label=(str(action_data.get("label")) if action_type == AlertActionType.open_wildlife_journal and action_data.get("label") else None),
            taxon_label=(str(action_data["taxon_label"]) if action_type == AlertActionType.open_place_story and action_data.get("taxon_label") else None),
            feature_id=(str(action_data["feature_id"]) if action_type == AlertActionType.open_place_story and action_data.get("feature_id") else None),
            story_kind=(str(action_data["story_kind"]) if action_type == AlertActionType.open_place_story and action_data.get("story_kind") else None),
        )
        status = (
            "dismissed" if alert.dismissed_at is not None else
            "resolved" if alert.resolved_at is not None else
            "read" if alert.read_at is not None else "unread"
        )
        category = AlertCategory(alert.category)
        severity = AlertSeverity(alert.severity)
        return ProductAlert(
            id=alert.id,
            category=category,
            severity=severity,
            title=alert.title,
            message=alert.message,
            created_at=_as_utc(alert.created_at),
            updated_at=_as_utc(alert.updated_at),
            read_at=_as_utc(alert.read_at) if alert.read_at else None,
            dismissed_at=_as_utc(alert.dismissed_at) if alert.dismissed_at else None,
            resolved_at=_as_utc(alert.resolved_at) if alert.resolved_at else None,
            status=status,
            stream_id=alert.stream_id,
            stream_name=stream.name if stream is not None else None,
            zone_id=alert.zone_id,
            zone_name=zone.name if zone is not None else None,
            visit_id=alert.visit_id,
            source_id=alert.source_id,
            action=action,
            attention_category=self._attention_category_for(category),
            urgency=self._attention_urgency_for(category, severity),
        )

    @staticmethod
    def _attention_category_for(category: AlertCategory) -> AttentionCategory:
        """Calm Attention & Notifications v1, Phase 2: map this product's
        existing, internal `AlertCategory` vocabulary onto the small,
        user-centered taxonomy the milestone brief defines -- a pure
        presentation function, computed fresh on every read and never
        persisted, so refining this mapping later needs no migration."""

        return {
            AlertCategory.review: AttentionCategory.needs_help,
            AlertCategory.monitoring: AttentionCategory.observatory_health,
            AlertCategory.storage: AttentionCategory.observatory_health,
            AlertCategory.journal: AttentionCategory.discovery,
            AlertCategory.insight: AttentionCategory.insight,
        }[category]

    @staticmethod
    def _attention_urgency_for(category: AlertCategory, severity: AlertSeverity) -> AttentionUrgency:
        """Phase 3: explicit delivery urgency, distinct from `severity`
        (how bad) and `AttentionCategory` (what kind). Per-Visit review
        work is always `in_app_only` -- Phase 10 groups it into the daily
        digest's own "N observations could use your help" sentence
        instead of a second, per-item interruption (see `_compose_digest_
        message`). Wildlife Discovery/Insight content -- even a first-ever
        species -- defaults to `digest`, never `immediate` (Phase 9: "Do
        NOT notify for every ordinary Visit... Do NOT use raw classifier
        confidence as importance"). `immediate` is reserved for a `high`-
        severity Observatory Health condition, and only ever reached after
        `_sync_camera_health_incident`/`_sync_storage_alert`'s own existing,
        already-debounced sustained-failure thresholds are crossed -- see
        docs/calm-attention-notifications-v1-report.md "Debounce /
        hysteresis" for the exact thresholds reused, not reinvented, here.
        """

        if category == AlertCategory.review:
            return AttentionUrgency.in_app_only
        if category in (AlertCategory.monitoring, AlertCategory.storage):
            return AttentionUrgency.immediate if severity == AlertSeverity.high else AttentionUrgency.in_app_only
        return AttentionUrgency.digest

    def _refresh_product_alert(
        self,
        session: Session,
        *,
        category: AlertCategory,
        severity: AlertSeverity,
        title: str,
        message: str,
        deduplication_key: str,
        condition_fingerprint: str,
        action_type: AlertActionType,
        action_parameters: dict[str, str],
        now: datetime,
        stream_id: str | None = None,
        zone_id: str | None = None,
        visit_id: str | None = None,
        source_id: str | None = None,
        cleanup_context: str | None = None,
    ) -> ProductAlertModel:
        """Update one condition in place; a changed fingerprint starts a new version."""

        active = session.scalars(
            select(ProductAlertModel)
            .where(
                ProductAlertModel.deduplication_key == deduplication_key,
                ProductAlertModel.resolved_at.is_(None),
            )
            .order_by(ProductAlertModel.condition_version.desc())
        ).first()
        if active is not None and active.condition_fingerprint == condition_fingerprint:
            active.severity = severity.value
            active.title = title
            active.message = message
            active.updated_at = now
            active.stream_id, active.zone_id, active.visit_id = stream_id, zone_id, visit_id
            active.source_id, active.cleanup_context = source_id, cleanup_context
            active.action_type = action_type.value
            active.action_parameters_json = json.dumps(action_parameters, sort_keys=True)
            return active
        if active is not None:
            active.resolved_at = now
            active.updated_at = now
        version = (session.scalar(
            select(func.max(ProductAlertModel.condition_version)).where(
                ProductAlertModel.deduplication_key == deduplication_key
            )
        ) or 0) + 1
        created = ProductAlertModel(
            id=f"alert-{uuid.uuid4().hex}", category=category.value, severity=severity.value,
            title=title, message=message, created_at=now, updated_at=now,
            read_at=None, dismissed_at=None, resolved_at=None,
            stream_id=stream_id, zone_id=zone_id, visit_id=visit_id, source_id=source_id,
            cleanup_context=cleanup_context, deduplication_key=deduplication_key,
            condition_fingerprint=condition_fingerprint, condition_version=version,
            action_type=action_type.value, action_parameters_json=json.dumps(action_parameters, sort_keys=True),
        )
        session.add(created)
        return created

    def _resolve_product_alerts(self, session: Session, deduplication_key: str, now: datetime) -> None:
        for alert in session.scalars(
            select(ProductAlertModel).where(
                ProductAlertModel.deduplication_key == deduplication_key,
                ProductAlertModel.resolved_at.is_(None),
            )
        ).all():
            alert.resolved_at = now
            alert.updated_at = now

    def _sync_review_alert(self, session: Session, visit: VisitModel, now: datetime) -> None:
        key = f"review:{visit.id}"
        event = session.get(EventModel, visit.event_id)
        stream = session.get(StreamModel, event.stream_id) if event is not None else None
        if visit.is_superseded or visit.review_status != ReviewStatus.needs_review.value or stream is None:
            self._resolve_product_alerts(session, key, now)
            return
        zone_id = visit.zone_id or event.primary_zone_id
        self._refresh_product_alert(
            session, category=AlertCategory.review, severity=AlertSeverity.warning,
            title="Visit ready for review", message="Outdoor activity is ready for your explicit review and correction.",
            deduplication_key=key, condition_fingerprint="needs_review",
            action_type=AlertActionType.review_visit, action_parameters={}, now=now,
            stream_id=stream.id, zone_id=zone_id, visit_id=visit.id, source_id=stream.source_id,
        )

    def _sync_journal_milestone_alert(self, session: Session, visit: VisitModel, now: datetime) -> None:
        if visit.is_superseded or visit.review_status != ReviewStatus.reviewed.value or not visit.reviewed_label:
            return
        event = session.get(EventModel, visit.event_id)
        if event is None or self._visit_review_outcome(session, review_status=ReviewStatus.reviewed, reviewed_label=visit.reviewed_label) != VisitReviewOutcome.confirmed_bird:
            return
        label = self._normalize_label_from_session(session, visit.reviewed_label)
        earlier = session.scalar(select(func.count(VisitModel.id)).where(
            VisitModel.id != visit.id, VisitModel.is_superseded.is_(False),
            VisitModel.review_status == ReviewStatus.reviewed.value, VisitModel.reviewed_label == label,
        )) or 0
        if earlier:
            return
        stream = session.get(StreamModel, event.stream_id)
        self._refresh_product_alert(
            session, category=AlertCategory.journal, severity=AlertSeverity.info,
            title="First confirmed local observation", message="This is the first current local reviewed observation of this wildlife label in MockingBird.",
            deduplication_key=f"journal:first-label:{label}", condition_fingerprint="first_confirmed_local_observation",
            action_type=AlertActionType.open_wildlife_journal, action_parameters={"label": label}, now=now,
            stream_id=stream.id if stream else None, zone_id=visit.zone_id or event.primary_zone_id,
            visit_id=visit.id, source_id=stream.source_id if stream else None,
        )

    def _maybe_resolve_stale_journal_milestone_alert(
        self, session: Session, *, old_label: str, now: datetime,
    ) -> None:
        """Resolve a "first confirmed local observation" milestone alert for
        `old_label` once no other active, reviewed Visit still carries it.

        Everyday Discovery / Product Experience v2 (Phase L -- stale
        milestone truth reconciliation, see docs/canonical-new-regular-
        species-contract.md): `_sync_journal_milestone_alert` only ever
        evaluates a Visit's *new* label, so a milestone claim about the
        label a Visit is being corrected or reopened *away from* would
        otherwise never be resolved and could keep presenting as current
        truth indefinitely. Call this whenever a reviewed Visit's
        `reviewed_label` is about to be cleared (reopen) or replaced
        (correction) with a *different* label, passing the label it is
        leaving. A no-op if another reviewed Visit still carries `old_label`
        -- the milestone claim ("first confirmed") remains true for that
        other Visit.
        """

        normalized = self._normalize_label_from_session(session, old_label)
        remaining = session.scalar(
            select(func.count(VisitModel.id)).where(
                VisitModel.is_superseded.is_(False),
                VisitModel.review_status == ReviewStatus.reviewed.value,
                VisitModel.reviewed_label == normalized,
            )
        ) or 0
        if remaining == 0:
            self._resolve_product_alerts(session, f"journal:first-label:{normalized}", now)

    def _sync_monitoring_alert(self, session: Session, stream_id: str, now: datetime) -> None:
        # Monitoring lifecycle is the sole writer. Alert and incident resolution
        # share this one resolver so health reads cannot create attention state.
        self._sync_camera_health_incident(session, stream_id, now)

    def _sync_storage_alert(self, session: Session, now: datetime) -> None:
        # Already the established "storage state meaningfully changed" hook
        # (called after every cleanup/restore/purge/settings-update) --
        # reused to invalidate the cache above rather than inventing a
        # second call site for the same fact.
        self.invalidate_storage_summary_cache()
        settings = session.get(StorageRetentionSettingsModel, 1)
        target = settings.maximum_managed_media_bytes if settings is not None else None
        key = "storage:managed_target"
        total = self._storage_total_managed_bytes(session)
        if target is None or total <= target:
            self._resolve_product_alerts(session, key, now)
            return
        evaluation = self._storage_retention_evaluation(session, self._storage_retention_settings_response(settings), now)
        protected = sum(evaluation.protected_bytes.values()) > 0
        self._refresh_product_alert(
            session, category=AlertCategory.storage, severity=AlertSeverity.high if protected else AlertSeverity.warning,
            title="Managed storage is above its target", message=(
                "Protected evidence is keeping managed storage above its target. Cleanup remains an explicit local action."
                if protected else "Managed storage is above its configured target. Review Storage & Retention before choosing any cleanup."
            ), deduplication_key=key, condition_fingerprint=("protected_target" if protected else "managed_target"),
            action_type=AlertActionType.open_storage_retention, action_parameters={}, now=now,
            cleanup_context="protected_target" if protected else "managed_target",
        )

    # ------------------------------------------------------------------
    # Calm Attention & Notifications v1: Insight/Discovery/digest sync.
    # See docs/calm-attention-notifications-v1-report.md.
    # ------------------------------------------------------------------

    _PLACE_STORY_ATTENTION_LOOKBACK_DAYS = 30
    _DIGEST_SUPPRESSED_COVERAGE_STATES = frozenset(
        {"no_monitoring", "sparse_monitoring", "no_confirmed_activity"}
    )
    _STORY_KIND_TO_ALERT_CATEGORY: dict[str, AlertCategory] = {
        # Discovery: notable wildlife facts, the same spirit as `journal`'s
        # existing "first confirmed local observation" (Bird Log-flavored).
        "return": AlertCategory.journal,
        "diversity_milestone": AlertCategory.journal,
        # Insight: longer-horizon understanding -- regularity/activity
        # transitions, Reviewed Place facts, and mature before/after
        # comparisons.
        "regularity_change": AlertCategory.insight,
        "noteworthy_activity": AlertCategory.insight,
        "feature_change": AlertCategory.insight,
        "phenology": AlertCategory.insight,
        "comparison_insight": AlertCategory.insight,
        # "first_seen" is deliberately absent -- see `_sync_place_story_
        # attention`'s own docstring below.
    }

    def _sync_place_story_attention(self, session: Session, story: PlaceStoryResponse, *, now: datetime) -> int:
        """Calm Attention & Notifications v1, Phase 4/6/9: turn recent Place
        Story events into durable attention items -- a thin adapter over
        `place_story`'s own already-idempotent, already-deduplicated event
        stream (stable ids, structural dedup -- see `place_story.build_
        place_story`'s own docstring), never a second computation of "is
        this worth mentioning."

        `first_seen` is deliberately excluded: `_sync_journal_milestone_
        alert` (already called inline at Visit-review-commit time) owns
        that exact fact today. Surfacing it a second time here, computed a
        second way (via `historical_baseline` instead of a raw label
        COUNT), is exactly the "four notifications from four subsystems"
        anti-pattern Phase 6 warns against -- see the milestone report's
        "Semantic deduplication" for the full reasoning this repository
        chose not to unify the two mechanisms outright (the existing
        per-Visit check is cheap and synchronous; recomputing full
        historical intelligence at every Visit-review commit would
        reintroduce the Phase 38 performance problem this method's own
        bounded, periodic cadence exists to avoid).

        Returns the count of Place Story-derived alerts left active after
        this call (created, updated, or already current).
        """

        current_keys: set[str] = set()
        for entry in story.entries:
            if entry.kind == "first_seen":
                continue
            if entry.kind == "diversity_milestone" and entry.id == "diversity-milestone:1":
                # The Place's 1st-species milestone is, by construction,
                # always dated at that same taxon's own all-time-first
                # confirmation (`compute_diversity_milestone_events` sorts
                # taxa by `first_confirmed_at`) -- i.e. it always co-occurs
                # with the `journal:first-label:{taxon}` alert `_sync_
                # journal_milestone_alert` already created for that exact
                # moment. A second "1st species recorded!" alert beside
                # "First <taxon> observation" is the same Phase 6 anti-
                # pattern this method's `first_seen` exclusion above
                # already avoids -- so this one ordinal is excluded too.
                # Ordinals 5/10/25/50/100 are kept: by the time a Place
                # reaches its 5th+ species, that species' own "first
                # confirmed" fact is comparatively routine, and "5th
                # species recorded here" is genuinely new, calm-worthy
                # information a per-taxon alert does not otherwise convey.
                continue
            category = self._STORY_KIND_TO_ALERT_CATEGORY.get(entry.kind)
            if category is None:
                continue
            key = f"place-story:{entry.id}"
            current_keys.add(key)
            action_parameters = {
                field_name: field_value
                for field_name, field_value in (
                    ("taxon_label", entry.taxon_label),
                    ("feature_id", entry.feature_id),
                    ("story_kind", entry.kind),
                )
                if field_value
            }
            self._refresh_product_alert(
                session,
                category=category,
                severity=AlertSeverity.info,
                title=entry.title,
                message=entry.summary,
                deduplication_key=key,
                # `entry.id` already encodes every fact that could change
                # this event's meaning (taxon, state, date, or change-event
                # id) -- `place_story` never reuses one id for two
                # different facts (`build_place_story` asserts this) -- so
                # a constant fingerprint is correct: once true, this
                # condition never needs a second version under the same
                # key.
                condition_fingerprint="place_story_event",
                action_type=AlertActionType.open_place_story,
                action_parameters=action_parameters,
                now=now,
                zone_id=entry.zone_id,
                source_id=entry.source_id,
            )

        # Correction safety (Phase 32): resolve any previously-active
        # Place Story attention item whose underlying fact no longer
        # recomputes -- e.g. a correction changed the confirmed taxon
        # behind a `return`/`regularity_change` event, or a Reviewed
        # Place Feature change event was deleted. Bounded to alerts
        # created within this same lookback window, so an older, already-
        # read/dismissed item from outside the recomputed range is never
        # touched (Phase 33: "Attention history retention").
        stale_cutoff = now - timedelta(days=self._PLACE_STORY_ATTENTION_LOOKBACK_DAYS)
        for alert in session.scalars(
            select(ProductAlertModel).where(
                ProductAlertModel.deduplication_key.like("place-story:%"),
                ProductAlertModel.resolved_at.is_(None),
                ProductAlertModel.created_at >= stale_cutoff,
            )
        ).all():
            if alert.deduplication_key not in current_keys:
                alert.resolved_at = now
                alert.updated_at = now
        return len(current_keys)

    @staticmethod
    def _compose_digest_message(digest: PlaceActivityReportDigest) -> str:
        """Calm Attention & Notifications v1, Phase 14/15: calm digest
        copy composed entirely from `daily_digest.compute_daily_digest`'s
        own already-resolved, already-ranked facts -- no new wildlife
        judgment is made here, only sentence assembly. Reuses the exact
        same `other_activity.unresolved_visit_count` Today/the Place
        Report already display for Phase 10's "N observations could use
        your help" clause, instead of a second, separately-computed Needs
        Help summary."""

        if not digest.primary_highlights:
            parts = [digest.coverage.message]
        else:
            names = [highlight.display_name for highlight in digest.primary_highlights[:3]]
            if len(names) == 1:
                joined = names[0]
            elif len(names) == 2:
                joined = f"{names[0]} and {names[1]}"
            else:
                joined = f"{', '.join(names[:-1])}, and {names[-1]}"
            lead = digest.primary_highlights[0]
            note = (
                lead.historical_note or lead.regularity_note
                or lead.change_note or lead.pattern_note or lead.seasonal_note
            )
            parts = [f"{joined} recorded."]
            if note:
                parts.append(note)
        if digest.place_change_note:
            parts.append(digest.place_change_note)
        unresolved = digest.other_activity.unresolved_visit_count
        if unresolved > 0:
            parts.append(f"{unresolved} observation{'s' if unresolved != 1 else ''} could use your help.")
        return " ".join(parts)

    def _sync_digest_attention_for_period(
        self,
        session: Session,
        *,
        digest: PlaceActivityReportDigest | None,
        dedup_key: str,
        title: str,
        now: datetime,
    ) -> bool:
        """One idempotent-per-period digest attention item. Phase 14: "Do
        not send '0 birds detected today' as a depressing routine
        notification" -- suppressed entirely (and any previously-active
        item for this exact period resolved) whenever coverage has
        genuinely nothing meaningful to say, never merely "less than
        usual." An ordinary day of confirmed regular species still
        produces a calm recap; that is what a digest is for (Phase 15's
        own "cardinals remained regular" example)."""

        if digest is None or digest.coverage.state in self._DIGEST_SUPPRESSED_COVERAGE_STATES:
            self._resolve_product_alerts(session, dedup_key, now)
            return False
        self._refresh_product_alert(
            session,
            category=AlertCategory.insight,
            severity=AlertSeverity.info,
            title=title,
            message=self._compose_digest_message(digest),
            deduplication_key=dedup_key,
            # Coarse and constant, not content-derived: the same digest
            # period should refresh its text in place as later-arriving
            # facts sharpen it throughout the day/week, never re-version
            # (and so never re-mark unread) merely because the wording
            # changed (Phase 8: cooldowns/hysteresis -- "do not produce a
            # new message every recomputation").
            condition_fingerprint="digest_has_content",
            action_type=AlertActionType.open_place_report,
            action_parameters={},
            now=now,
        )
        return True

    def sync_attention_signals(self, *, now: datetime | None = None) -> None:
        """Calm Attention & Notifications v1, Phase 4/13/38: the one
        periodic, bounded reconciliation between already-authoritative
        Place facts and durable attention state. Every fact this method
        turns into an attention item is read through the exact same
        public, already-accepted methods Place Story/Today/the Place
        Report call themselves (`place_story`, `place_activity_report`) --
        never a second query or statistical path. Read and write happen in
        separate sessions/transactions on purpose: `place_story`/`place_
        activity_report` are top-level, already-accepted entry points that
        open and close their own session, exactly like a normal Place
        Story/Place Report page load would; this method's own write phase
        then reconciles attention state from their already-computed,
        already-detached results in one short transaction.

        Called on a bounded periodic cadence (see
        `mockingbird.monitoring.attention_sync_service.AttentionSyncService`,
        default every 15 minutes) rather than per-Visit/per-frame -- Phase
        38 explicitly warns against re-running Place history computation
        at that frequency; this is the same cost `place_activity_report`
        already pays on every ordinary Dashboard/Today page load today, so
        it adds no new order of magnitude of work, and idempotent reruns
        (a missed tick, a restart) are always safe: every alert this
        method creates or resolves is keyed by a stable, content-derived
        `deduplication_key`, never a counter or a timestamp.
        """

        moment = now or datetime.now(UTC)
        window_start_at = moment - timedelta(days=self._PLACE_STORY_ATTENTION_LOOKBACK_DAYS)
        story = self.place_story(start_at=window_start_at, end_at=moment, now=moment, page_size=200)

        resolved_local_timezone = resolve_host_local_timezone(moment)
        local_now = moment.astimezone(resolved_local_timezone)
        local_day_start = datetime.combine(local_now.date(), datetime.min.time(), tzinfo=resolved_local_timezone)
        report = self.place_activity_report(
            PlaceActivityReportRequest(start_at=local_day_start, end_at=moment),
            now=moment,
            local_timezone=resolved_local_timezone,
        )
        iso_year, iso_week, _ = local_now.isocalendar()

        with self.session_factory() as session:
            with session.begin():
                story_alert_count = self._sync_place_story_attention(session, story, now=moment)
                daily_active = self._sync_digest_attention_for_period(
                    session, digest=report.digest,
                    dedup_key=f"digest:daily:{local_now.date().isoformat()}",
                    title="Today in your yard", now=moment,
                )
                weekly_active = self._sync_digest_attention_for_period(
                    session, digest=report.weekly_digest,
                    dedup_key=f"digest:weekly:{iso_year}-W{iso_week:02d}",
                    title="This week at your Place", now=moment,
                )
        log_event(
            "attention", "sync_completed",
            place_story_alerts_active=story_alert_count,
            daily_digest_active=daily_active, weekly_digest_active=weekly_active,
        )

    def get_notification_preferences(self, user_id: str) -> UserNotificationPreferences:
        """Calm Attention & Notifications v1, Phase 16: read-only,
        mirroring `storage_retention_settings`'s own established "read
        intent without creating settings" discipline exactly -- a row is
        persisted only by `update_notification_preferences`'s first real
        write, never merely by reading (this method is also called from
        `_visible_alert_categories`, itself called on every `/api/alerts*`
        poll, so a read-triggered write here would mean an ordinary GET
        request writing to the database on a signed-in user's very first
        poll). When no row exists yet, the response schema's own declared
        field defaults -- the same conservative values a real saved row
        would start with -- are returned computed, not persisted."""

        with self.session_factory() as session:
            row = session.get(UserNotificationPreferenceModel, user_id)
            if row is None:
                return UserNotificationPreferences(updated_at=datetime.now(UTC))
            return self._notification_preferences_from_model(row)

    def update_notification_preferences(
        self, user_id: str, payload: UserNotificationPreferencesUpdate
    ) -> UserNotificationPreferences:
        now = datetime.now(UTC)
        updates = payload.model_dump(exclude_unset=True)
        with self.session_factory() as session:
            with session.begin():
                row = session.get(UserNotificationPreferenceModel, user_id)
                if row is None:
                    row = UserNotificationPreferenceModel(user_id=user_id, updated_at=now)
                    session.add(row)
                for field_name, value in updates.items():
                    setattr(row, field_name, value)
                row.updated_at = now
                session.flush()
                return self._notification_preferences_from_model(row)

    @staticmethod
    def _notification_preferences_from_model(row: UserNotificationPreferenceModel) -> UserNotificationPreferences:
        return UserNotificationPreferences(
            discovery_enabled=row.discovery_enabled,
            insight_enabled=row.insight_enabled,
            needs_help_enabled=row.needs_help_enabled,
            observatory_health_enabled=row.observatory_health_enabled,
            browser_notifications_enabled=row.browser_notifications_enabled,
            quiet_hours_enabled=row.quiet_hours_enabled,
            quiet_hours_start_minute=row.quiet_hours_start_minute,
            quiet_hours_end_minute=row.quiet_hours_end_minute,
            updated_at=_as_utc(row.updated_at),
        )

    _ATTENTION_CATEGORY_PREFERENCE_FIELD: dict[AttentionCategory, str] = {
        AttentionCategory.discovery: "discovery_enabled",
        AttentionCategory.insight: "insight_enabled",
        AttentionCategory.needs_help: "needs_help_enabled",
        AttentionCategory.observatory_health: "observatory_health_enabled",
    }

    def _visible_alert_categories(self, *, viewer_role: UserRole, user_id: str) -> set[AlertCategory] | None:
        """Calm Attention & Notifications v1, Phase 16/18: which
        `AlertCategory` values this signed-in user should see, combining
        their own stored preferences with one fixed role ceiling. Returns
        `None` (meaning "no filter, show every category") only when every
        category is both enabled and role-permitted, so an ordinary
        Administrator/Reviewer with default preferences sees exactly what
        every alert-listing endpoint already showed before this milestone
        -- adding preferences changes nothing for a user who never opens
        Settings.

        The one fixed role rule (Phase 18: "Do not send Reviewer-only
        action notifications to a Viewer who cannot act"): a Viewer can
        open a Visit to look, but never submit a correction, so `review`
        (Needs Help) attention is never shown to a Viewer regardless of
        their own stored toggle -- there is nothing they could do about
        it, only something to feel nagged by.
        """

        preferences = self.get_notification_preferences(user_id)
        hidden: set[AttentionCategory] = set()
        for category, field_name in self._ATTENTION_CATEGORY_PREFERENCE_FIELD.items():
            if not getattr(preferences, field_name):
                hidden.add(category)
        # Inlined rank check (not `mockingbird.api.auth.role_at_least`):
        # this repository module must not import from the API auth layer,
        # which itself imports `ProductRepository` only under
        # `TYPE_CHECKING` today -- a real top-level import here would risk
        # a circular import. `UserRole`'s three values are a fixed,
        # already-imported ladder (viewer < reviewer < administrator), so
        # "at least reviewer" is exactly "not a Viewer."
        if viewer_role == UserRole.viewer:
            hidden.add(AttentionCategory.needs_help)
        if not hidden:
            return None
        return {
            category
            for category in AlertCategory
            if self._attention_category_for(category) not in hidden
        }

    def storage_retention_settings(self) -> StorageRetentionSettings:
        """Read retention intent without creating settings or starting cleanup."""

        with self.session_factory() as session:
            model = session.get(StorageRetentionSettingsModel, 1)
            return self._storage_retention_settings_response(model)

    def update_storage_retention_settings(
        self,
        payload: StorageRetentionSettingsUpdate,
    ) -> tuple[StorageRetentionSettings, bool]:
        """Persist explicit bounded retention intent; migration itself never enables it."""

        now = datetime.now(UTC)
        with self.session_factory() as session:
            with session.begin():
                model = session.get(StorageRetentionSettingsModel, 1)
                if (
                    model is not None
                    and model.last_settings_idempotency_key == payload.idempotency_key
                ):
                    return self._storage_retention_settings_response(model), True
                if model is None:
                    model = StorageRetentionSettingsModel(
                        singleton_id=1,
                        automatic_cleanup_enabled=payload.automatic_cleanup_enabled,
                        cleanup_frequency=payload.cleanup_frequency.value,
                        # Active needs-review evidence is a product protection, not
                        # an operator tradeoff. Keep the stored compatibility field
                        # true even if an older caller supplied false.
                        retain_unresolved_visit_evidence=True,
                        retain_reviewed_bird_wildlife_evidence=(
                            payload.retain_reviewed_bird_wildlife_evidence
                        ),
                        reviewed_non_bird_age_days=payload.reviewed_non_bird_age_days,
                        superseded_evidence_age_days=payload.superseded_evidence_age_days,
                        orphaned_media_age_days=payload.orphaned_media_age_days,
                        rejected_analysis_media_age_days=payload.rejected_analysis_media_age_days,
                        maximum_managed_media_bytes=payload.maximum_managed_media_bytes,
                        policy_revision=1,
                        updated_at=now,
                        last_automatic_run_at=None,
                        last_automatic_result=None,
                        last_settings_idempotency_key=payload.idempotency_key,
                    )
                    session.add(model)
                else:
                    model.automatic_cleanup_enabled = payload.automatic_cleanup_enabled
                    model.cleanup_frequency = payload.cleanup_frequency.value
                    model.retain_unresolved_visit_evidence = True
                    model.retain_reviewed_bird_wildlife_evidence = (
                        payload.retain_reviewed_bird_wildlife_evidence
                    )
                    model.reviewed_non_bird_age_days = payload.reviewed_non_bird_age_days
                    model.superseded_evidence_age_days = payload.superseded_evidence_age_days
                    model.orphaned_media_age_days = payload.orphaned_media_age_days
                    model.rejected_analysis_media_age_days = payload.rejected_analysis_media_age_days
                    model.maximum_managed_media_bytes = payload.maximum_managed_media_bytes
                    model.policy_revision += 1
                    model.updated_at = now
                    model.last_settings_idempotency_key = payload.idempotency_key
                session.flush()
                self._sync_storage_alert(session, now)
                return self._storage_retention_settings_response(model), False

    def most_recent_camera_node_service_version(self) -> str | None:
        """The most-recently-observed paired Camera Node's own reported
        software version, for `/api/product/health`'s advanced-only version
        reporting (First-Hour Onboarding + Whole-Product Observability
        Closure v1, "C5"). A bare, read-only, side-effect-free read of the
        same durable `CameraSourceModel.camera_node_service_version`
        column Doctor's own Camera Node check already reads (Boot Identity
        + Autonomous Recovery v1) -- never a second implementation, and
        never a live network call to the Node. `None` when no Camera Node
        has ever reported a version (never configured, or configured but
        never yet successfully connected)."""

        with self.session_factory() as session:
            rows = session.scalars(
                select(CameraSourceModel)
                .where(
                    CameraSourceModel.kind == SourceKind.integration.value,
                    CameraSourceModel.camera_node_service_version.is_not(None),
                )
                .order_by(CameraSourceModel.camera_node_last_seen_at.desc().nulls_last())
            ).all()
        return rows[0].camera_node_service_version if rows else None

    def storage_summary(self) -> StorageSummary:
        """Summarize managed media with no path disclosure and no filesystem mutation.

        Cached for `STORAGE_SUMMARY_CACHE_TTL_SECONDS` (Appliance / Storage /
        Privacy / Recovery v1, Phase B) -- see `__init__`'s own comment for
        why a bounded TTL, not a SQL-aggregate rewrite, was chosen, and
        `invalidate_storage_summary_cache` for where staleness is actively
        closed rather than merely time-boxed. A cache miss/expiry recomputes
        exactly the same value this always computed; nothing about the
        classification logic below changed."""

        with self._storage_summary_cache_lock:
            cached = self._storage_summary_cache
            if cached is not None and (time.monotonic() - cached[0]) < STORAGE_SUMMARY_CACHE_TTL_SECONDS:
                return cached[1]
        summary = self._compute_storage_summary()
        with self._storage_summary_cache_lock:
            self._storage_summary_cache = (time.monotonic(), summary)
        return summary

    def invalidate_storage_summary_cache(self) -> None:
        """Force the next `storage_summary()` call to recompute rather than
        wait out the TTL -- called from the points that already exist to
        mark storage state as meaningfully changed (`_sync_storage_alert`)
        plus the Camera Node transport consumer, so a newly-ingested item
        is reflected promptly rather than after a full TTL window."""

        with self._storage_summary_cache_lock:
            self._storage_summary_cache = None

    def _compute_storage_summary(self) -> StorageSummary:
        with self.session_factory() as session:
            settings = session.get(StorageRetentionSettingsModel, 1)
            assets = session.scalars(
                select(MediaAssetModel).order_by(MediaAssetModel.created_at, MediaAssetModel.id)
            ).all()
            totals = Counter[str]()
            total_bytes = 0
            oldest: datetime | None = None
            newest: datetime | None = None
            active_count = superseded_count = orphaned_count = 0
            active_bytes = superseded_bytes = orphaned_bytes = 0
            unresolved_count = reviewed_wildlife_count = reviewed_other_count = 0
            linked_evidence_or_analysis_count = linked_evidence_or_analysis_bytes = 0
            for asset in assets:
                path, relative_path, size, safe_reason = self._storage_managed_media_path(asset)
                if path is None or relative_path is None or size is None:
                    continue
                total_bytes += size
                created_at = _as_utc(asset.created_at)
                oldest = created_at if oldest is None or created_at < oldest else oldest
                newest = created_at if newest is None or created_at > newest else newest
                links = session.scalars(
                    select(VisitEvidenceLinkModel).where(
                        VisitEvidenceLinkModel.media_asset_id == asset.id
                    )
                ).all()
                visits = [session.get(VisitModel, link.visit_id) for link in links]
                visit_models = [visit for visit in visits if visit is not None]
                active_visits = [visit for visit in visit_models if not visit.is_superseded]
                if active_visits:
                    active_count += 1
                    active_bytes += size
                elif visit_models and all(visit.is_superseded for visit in visit_models):
                    superseded_count += 1
                    superseded_bytes += size
                elif not links and not self._storage_has_non_visit_reference(session, asset.id):
                    orphaned_count += 1
                    orphaned_bytes += size
                elif not links:
                    # Appliance / Storage / Privacy / Recovery v1, Phase B:
                    # the `linked_evidence_or_analysis` category -- a file
                    # referenced only by a rejected/suppressed detection/
                    # analysis record, never by a Visit. Previously never
                    # counted anywhere in this summary at all.
                    linked_evidence_or_analysis_count += 1
                    linked_evidence_or_analysis_bytes += size
                if any(visit.review_status == ReviewStatus.needs_review.value for visit in active_visits):
                    unresolved_count += 1
                if any(
                    visit.review_status == ReviewStatus.reviewed.value
                    and self._storage_visit_is_wildlife(session, visit)
                    for visit in active_visits
                ):
                    reviewed_wildlife_count += 1
                if any(
                    visit.review_status == ReviewStatus.reviewed.value
                    and not self._storage_visit_is_wildlife(session, visit)
                    for visit in active_visits
                ):
                    reviewed_other_count += 1

            database_bytes: int | None = None
            database_path = _database_path_from_url(self.db_url)
            if database_path:
                try:
                    database_bytes = Path(database_path).stat().st_size
                except OSError:
                    database_bytes = None
            target = settings.maximum_managed_media_bytes if settings else None
            warning = (
                "Storage target could not be reached because protected evidence was retained."
                if target is not None and total_bytes > target
                else None
            )
            disk_status = probe_local_storage_disk(
                Path(database_path).parent if database_path else self.media_root
            )
            if warning is None and not disk_status.is_writable:
                warning = "MockingBird's local storage location is not writable."
            elif warning is None and disk_status.storage_health_tier == "critical":
                # Appliance / Storage / Privacy / Recovery v1, Phase C: a
                # distinct, more urgent message than plain "running low" --
                # ingestion (new evidence, backups) is genuinely at risk.
                warning = "Local storage space is critically low. New evidence may soon fail to save."
            elif warning is None and disk_status.storage_health_tier == "action_recommended":
                warning = "Local storage space is running low."
            elif warning is None and disk_status.storage_health_tier == "getting_low":
                warning = "Local storage space is getting low."
            return StorageSummary(
                total_managed_media_bytes=total_bytes,
                total_managed_media_count=sum(1 for asset in assets if self._storage_managed_media_path(asset)[0] is not None),
                oldest_managed_media_at=oldest,
                newest_managed_media_at=newest,
                approximate_database_bytes=database_bytes,
                active_visit_media_count=active_count,
                active_visit_media_bytes=active_bytes,
                superseded_only_media_count=superseded_count,
                superseded_only_media_bytes=superseded_bytes,
                orphaned_managed_media_count=orphaned_count,
                orphaned_managed_media_bytes=orphaned_bytes,
                unresolved_visit_evidence_count=unresolved_count,
                reviewed_bird_wildlife_evidence_count=reviewed_wildlife_count,
                reviewed_non_bird_blank_ambiguous_evidence_count=reviewed_other_count,
                linked_evidence_or_analysis_count=linked_evidence_or_analysis_count,
                linked_evidence_or_analysis_bytes=linked_evidence_or_analysis_bytes,
                disk_total_bytes=disk_status.total_bytes,
                disk_free_bytes=disk_status.free_bytes,
                is_writable=disk_status.is_writable,
                storage_health_tier=disk_status.storage_health_tier,
                storage_warning=warning,
                message="Managed media is summarized locally. Protected evidence is counted but never treated as cleanup permission.",
            )

    def preview_storage_cleanup(
        self,
        *,
        origin: str = "manual",
    ) -> StorageCleanupPreviewResponse:
        """Create a bounded server-owned cleanup plan; the browser never chooses media IDs."""

        now = datetime.now(UTC)
        with self.session_factory() as session:
            with session.begin():
                settings_model = session.get(StorageRetentionSettingsModel, 1)
                settings = self._storage_retention_settings_response(settings_model)
                evaluation = self._storage_retention_evaluation(session, settings, now)
                candidates = self._storage_candidates_for_target(
                    evaluation.candidates,
                    settings.maximum_managed_media_bytes,
                    self._storage_total_managed_bytes(session),
                )[:MAX_STORAGE_CLEANUP_PREVIEW_ITEMS]
                fingerprint = self._storage_cleanup_fingerprint(candidates, settings)
                batch = StorageCleanupBatchModel(
                    id=f"storage-cleanup-{uuid.uuid4().hex}",
                    origin=origin,
                    state="previewed",
                    preview_token=uuid.uuid4().hex,
                    state_fingerprint=fingerprint,
                    policy_revision=settings.policy_revision,
                    idempotency_key=None,
                    created_at=now,
                    executed_at=None,
                    recovery_expires_at=None,
                    restored_at=None,
                    purged_at=None,
                    summary_json=json.dumps({"preview_count": len(candidates)}, sort_keys=True),
                    safe_error=None,
                )
                session.add(batch)
                session.flush()
                return self._storage_cleanup_preview_response(
                    batch=batch,
                    candidates=candidates,
                    evaluation=evaluation,
                    now=now,
                    capped=len(evaluation.candidates) > len(candidates),
                )

    def execute_storage_cleanup(
        self,
        payload: StorageCleanupExecuteRequest,
    ) -> StorageCleanupResult:
        """Move a still-valid preview into managed recovery before unlinking evidence."""

        if not payload.confirm:
            raise ValueError("storage_cleanup_requires_confirmation")
        if not self._storage_retention_lock.acquire(blocking=False):
            raise ValueError("storage_cleanup_busy")
        try:
            now = datetime.now(UTC)
            with self.session_factory() as session:
                with session.begin():
                    existing = session.scalar(
                        select(StorageCleanupBatchModel).where(
                            StorageCleanupBatchModel.idempotency_key == payload.idempotency_key
                        )
                    )
                    if existing is not None:
                        if existing.preview_token != payload.preview_token:
                            raise ValueError("storage_cleanup_idempotency_conflict")
                        return self._storage_cleanup_result_from_batch(existing, idempotent=True)
                    batch = session.scalar(
                        select(StorageCleanupBatchModel).where(
                            StorageCleanupBatchModel.preview_token == payload.preview_token
                        )
                    )
                    if batch is None:
                        raise ValueError("storage_cleanup_preview_missing")
                    if (
                        batch.state != "previewed"
                        or now - _as_utc(batch.created_at) > STORAGE_CLEANUP_PREVIEW_TTL
                    ):
                        raise ValueError("storage_cleanup_preview_expired")
                    settings = self._storage_retention_settings_response(
                        session.get(StorageRetentionSettingsModel, 1)
                    )
                    evaluation = self._storage_retention_evaluation(session, settings, now)
                    candidates = self._storage_candidates_for_target(
                        evaluation.candidates,
                        settings.maximum_managed_media_bytes,
                        self._storage_total_managed_bytes(session),
                    )[:MAX_STORAGE_CLEANUP_PREVIEW_ITEMS]
                    if self._storage_cleanup_fingerprint(candidates, settings) != batch.state_fingerprint:
                        raise ValueError("storage_cleanup_preview_stale")
                    batch.idempotency_key = payload.idempotency_key
                    batch.state = "staging"
                    batch.executed_at = now
                    batch.recovery_expires_at = now + STORAGE_CLEANUP_RECOVERY_WINDOW
                    batch.summary_json = json.dumps(
                        {"planned_count": len(candidates), "skipped_count": 0, "failed_count": 0},
                        sort_keys=True,
                    )
                    for candidate in candidates:
                        session.add(
                            StorageCleanupItemModel(
                                id=f"storage-cleanup-item-{uuid.uuid4().hex}",
                                batch_id=batch.id,
                                media_asset_id=candidate.asset_id,
                                category=candidate.category,
                                original_local_path=str(candidate.local_path),
                                quarantine_relative_path=str(candidate.relative_path),
                                file_size_bytes=candidate.file_size_bytes,
                                evidence_links_json=json.dumps(candidate.evidence_links),
                                state="staged",
                                created_at=now,
                                restored_at=None,
                                purged_at=None,
                            )
                        )
                    batch_id = batch.id

            with self.session_factory() as session:
                item_ids = list(session.scalars(
                    select(StorageCleanupItemModel.id).where(
                        StorageCleanupItemModel.batch_id == batch_id
                    )
                ))
            for item_id in item_ids:
                try:
                    with self.session_factory() as session:
                        with session.begin():
                            item = session.get(StorageCleanupItemModel, item_id)
                            if item is None or item.state != "staged":
                                continue
                            if not self._storage_cleanup_item_is_still_eligible_in_session(
                                session,
                                item,
                                now=now,
                            ):
                                item.state = "failed"
                                continue
                            # Acquire the local database write boundary before moving a
                            # file. This serializes final Visit changes with the last
                            # eligibility check, filesystem move, and link removal.
                            item.state = "moving"
                            session.flush()
                            if not self._storage_cleanup_item_is_still_eligible_in_session(
                                session,
                                item,
                                now=now,
                            ):
                                item.state = "failed"
                                continue
                            if not self._move_storage_item_to_recovery(item):
                                item.state = "failed"
                                continue
                            current_links = session.scalars(
                                select(VisitEvidenceLinkModel).where(
                                    VisitEvidenceLinkModel.media_asset_id == item.media_asset_id
                                )
                            ).all()
                            expected_links = self._storage_link_snapshot_signature(
                                _json_list(item.evidence_links_json)
                            )
                            actual_links = self._storage_link_snapshot_signature(
                                self._storage_link_snapshot(link) for link in current_links
                            )
                            if actual_links != expected_links:
                                # No link is removed if product context changed. Put the
                                # media back when possible; otherwise retain a durable
                                # moving state so recovery remains available.
                                item.state = (
                                    "failed"
                                    if self._restore_storage_item_from_recovery(item)
                                    else "moving"
                                )
                                continue
                            for link in current_links:
                                session.delete(link)
                            item.state = "quarantined"
                except Exception:
                    # A failure after a filesystem move rolls its database transaction
                    # back to staged. Final reconciliation below detects the recovery
                    # file and leaves that batch recoverable rather than successful.
                    continue

            with self.session_factory() as session:
                with session.begin():
                    persisted_batch = session.get(StorageCleanupBatchModel, batch_id)
                    persisted_items = session.scalars(
                    select(StorageCleanupItemModel).where(
                        StorageCleanupItemModel.batch_id == batch_id
                    )
                    ).all()
                    moved_count = 0
                    recovered_bytes = 0
                    recoverable_staged_count = 0
                    for item in persisted_items:
                        if item.state == "quarantined":
                            moved_count += 1
                            recovered_bytes += item.file_size_bytes
                            continue
                        if item.state in {"staged", "moving"} and self._storage_item_has_recovery_file(
                            item
                        ):
                            recoverable_staged_count += 1
                            continue
                        if item.state != "failed":
                            item.state = "failed"
                    if persisted_batch is None:
                        raise ValueError("storage_cleanup_preview_missing")
                    failed_count = sum(item.state == "failed" for item in persisted_items)
                    persisted_batch.state = (
                        "staging"
                        if recoverable_staged_count
                        else "quarantined"
                        if moved_count
                        else "failed"
                    )
                    persisted_batch.summary_json = json.dumps(
                        {
                            "media_count": moved_count,
                            "recovered_bytes": recovered_bytes,
                            "skipped_count": 0,
                            "failed_count": failed_count,
                            "recoverable_staged_count": recoverable_staged_count,
                            "permanently_purged_count": 0,
                        },
                        sort_keys=True,
                    )
                    persisted_batch.safe_error = (
                        "Cleanup was interrupted after a recoverable file move; no evidence links were removed for unfinished items."
                        if recoverable_staged_count
                        else "Some media could not be moved to recovery; no links were removed for those files."
                        if failed_count
                        else None
                    )
                    session.flush()
                    self._sync_storage_alert(session, now)
                    return self._storage_cleanup_result_from_batch(persisted_batch)
        finally:
            self._storage_retention_lock.release()

    def storage_cleanup_history(self, *, limit: int = MAX_STORAGE_CLEANUP_HISTORY_ITEMS) -> StorageCleanupHistoryResponse:
        with self.session_factory() as session:
            batches = session.scalars(
                select(StorageCleanupBatchModel)
                .where(StorageCleanupBatchModel.state != "previewed")
                .order_by(StorageCleanupBatchModel.created_at.desc(), StorageCleanupBatchModel.id.desc())
                .limit(max(1, min(limit, MAX_STORAGE_CLEANUP_HISTORY_ITEMS)))
            ).all()
            return StorageCleanupHistoryResponse(
                items=[self._storage_cleanup_history_item(batch) for batch in batches],
                message="Cleanup history is local and bounded. Recovery remains available only before its deadline.",
            )

    def restore_storage_cleanup_batch(
        self,
        batch_id: str,
        payload: StorageCleanupRestoreRequest,
    ) -> StorageCleanupResult | None:
        """Restore staged files only when their managed destination remains unoccupied."""

        if not self._storage_retention_lock.acquire(blocking=False):
            raise ValueError("storage_cleanup_busy")
        try:
            with self.session_factory() as session:
                batch = session.get(StorageCleanupBatchModel, batch_id)
                if batch is None:
                    return None
                if batch.last_restore_idempotency_key == payload.idempotency_key:
                    return self._storage_cleanup_result_from_batch(batch, idempotent=True)
                if batch.state == "restored":
                    return self._storage_cleanup_result_from_batch(batch, idempotent=True)
                if batch.state not in {"quarantined", "staging"}:
                    raise ValueError("storage_cleanup_restore_unavailable")
                items = session.scalars(
                    select(StorageCleanupItemModel).where(
                        StorageCleanupItemModel.batch_id == batch.id,
                        StorageCleanupItemModel.state.in_(
                            ("quarantined", "moved", "moving", "staged")
                        ),
                    )
                ).all()
            conflicts = 0
            restored_ids: list[str] = []
            for item in items:
                if not self._storage_cleanup_item_snapshot_is_valid(item):
                    conflicts += 1
                elif self._restore_storage_item_from_recovery(item):
                    restored_ids.append(item.id)
                else:
                    conflicts += 1
            now = datetime.now(UTC)
            with self.session_factory() as session:
                with session.begin():
                    batch = session.get(StorageCleanupBatchModel, batch_id)
                    if batch is None:
                        return None
                    items = session.scalars(
                        select(StorageCleanupItemModel).where(
                            StorageCleanupItemModel.batch_id == batch.id
                        )
                    ).all()
                    restored_count = 0
                    for item in items:
                        if item.id not in restored_ids:
                            continue
                        asset = session.get(MediaAssetModel, item.media_asset_id)
                        if asset is None:
                            item.state = "failed"
                            conflicts += 1
                            continue
                        for link_payload in _json_list(item.evidence_links_json):
                            visit = session.get(VisitModel, link_payload.get("visit_id"))
                            if visit is None:
                                continue
                            existing = session.scalar(
                                select(VisitEvidenceLinkModel).where(
                                    VisitEvidenceLinkModel.visit_id == visit.id,
                                    VisitEvidenceLinkModel.media_asset_id == asset.id,
                                )
                            )
                            if existing is None:
                                restored_primary = bool(link_payload.get("is_primary", False))
                                if restored_primary:
                                    another_primary = session.scalar(
                                        select(VisitEvidenceLinkModel.id).where(
                                            VisitEvidenceLinkModel.visit_id == visit.id,
                                            VisitEvidenceLinkModel.is_primary.is_(True),
                                        )
                                    )
                                    restored_primary = another_primary is None
                                session.add(
                                    VisitEvidenceLinkModel(
                                        id=str(link_payload["id"]),
                                        visit_id=visit.id,
                                        media_asset_id=asset.id,
                                        captured_at=_parse_datetime(link_payload["captured_at"]),
                                        frame_sequence=link_payload.get("frame_sequence"),
                                        sort_order=int(link_payload.get("sort_order", 0)),
                                        is_primary=restored_primary,
                                        evidence_role=(
                                            _optional_string(
                                                link_payload.get("evidence_role")
                                            )
                                            or "monitoring_frame"
                                        ),
                                        created_at=_parse_datetime(link_payload["created_at"]),
                                    )
                                )
                                if restored_primary and not visit.representative_media_path:
                                    visit.representative_media_path = asset.local_path
                        item.state = "restored"
                        item.restored_at = now
                        restored_count += 1
                    batch.state = "restored" if conflicts == 0 else "restore_conflict"
                    batch.restored_at = now if conflicts == 0 else None
                    batch.safe_error = (
                        "Some media could not be restored because its original location or product context changed."
                        if conflicts
                        else None
                    )
                    batch.last_restore_idempotency_key = payload.idempotency_key
                    summary = _json_object(batch.summary_json)
                    summary["restored_count"] = restored_count
                    summary["failed_count"] = int(summary.get("failed_count", 0)) + conflicts
                    batch.summary_json = json.dumps(summary, sort_keys=True)
                    self._sync_storage_alert(session, now)
                    return self._storage_cleanup_result_from_batch(batch, idempotent=False)
        finally:
            self._storage_retention_lock.release()

    def purge_storage_cleanup_batch(
        self,
        batch_id: str,
        payload: StorageCleanupPurgeRequest,
        *,
        allow_before_deadline: bool = False,
    ) -> StorageCleanupResult | None:
        if not payload.confirm:
            raise ValueError("storage_cleanup_purge_requires_confirmation")
        if not self._storage_retention_lock.acquire(blocking=False):
            raise ValueError("storage_cleanup_busy")
        try:
            now = datetime.now(UTC)
            with self.session_factory() as session:
                batch = session.get(StorageCleanupBatchModel, batch_id)
                if batch is None:
                    return None
                if batch.last_purge_idempotency_key == payload.idempotency_key:
                    return self._storage_cleanup_result_from_batch(batch, idempotent=True)
                if batch.state == "purged":
                    return self._storage_cleanup_result_from_batch(batch, idempotent=True)
                if batch.state not in {"quarantined", "restore_conflict"}:
                    raise ValueError("storage_cleanup_purge_unavailable")
                if (
                    not allow_before_deadline
                    and batch.recovery_expires_at is not None
                    and _as_utc(batch.recovery_expires_at) > now
                ):
                    raise ValueError("storage_cleanup_recovery_active")
                items = session.scalars(
                    select(StorageCleanupItemModel).where(
                        StorageCleanupItemModel.batch_id == batch.id,
                        StorageCleanupItemModel.state == "quarantined",
                    )
                ).all()
            purged_ids = [item.id for item in items if self._purge_storage_item(item)]
            with self.session_factory() as session:
                with session.begin():
                    batch = session.get(StorageCleanupBatchModel, batch_id)
                    if batch is None:
                        return None
                    items = session.scalars(
                        select(StorageCleanupItemModel).where(
                            StorageCleanupItemModel.batch_id == batch.id
                        )
                    ).all()
                    purged_count = 0
                    for item in items:
                        if item.id in purged_ids:
                            item.state = "purged"
                            item.purged_at = now
                            purged_count += 1
                    remaining = any(item.state == "quarantined" for item in items)
                    batch.state = "restore_conflict" if remaining else "purged"
                    batch.purged_at = now if not remaining else None
                    summary = _json_object(batch.summary_json)
                    summary["permanently_purged_count"] = int(
                        summary.get("permanently_purged_count", 0)
                    ) + purged_count
                    batch.summary_json = json.dumps(summary, sort_keys=True)
                    batch.last_purge_idempotency_key = payload.idempotency_key
                    self._sync_storage_alert(session, now)
                    return self._storage_cleanup_result_from_batch(batch)
        finally:
            self._storage_retention_lock.release()

    def run_automatic_storage_retention(self) -> StorageCleanupResult | None:
        """Run one fresh, local policy pass; browser previews are never reused automatically."""

        settings = self.storage_retention_settings()
        if not settings.automatic_cleanup_enabled:
            return None
        now = datetime.now(UTC)
        if settings.last_automatic_run_at is not None:
            cadence = timedelta(days=1 if settings.cleanup_frequency == "daily" else 7)
            if _as_utc(settings.last_automatic_run_at) + cadence > now:
                return None
        preview = self.preview_storage_cleanup(origin="automatic")
        if preview.eligible_media_count == 0:
            with self.session_factory() as session:
                with session.begin():
                    model = session.get(StorageRetentionSettingsModel, 1)
                    if model is not None:
                        model.last_automatic_run_at = now
                        model.last_automatic_result = "no_eligible_media"
            return None
        result = self.execute_storage_cleanup(
            StorageCleanupExecuteRequest(
                preview_token=preview.preview_token,
                confirm=True,
                idempotency_key=f"automatic-retention-{now.strftime('%Y%m%d%H')}",
            )
        )
        with self.session_factory() as session:
            with session.begin():
                model = session.get(StorageRetentionSettingsModel, 1)
                if model is not None:
                    model.last_automatic_run_at = now
                    model.last_automatic_result = result.state
        return result

    def purge_expired_storage_recovery(self) -> int:
        """Purge only expired quarantined files; disabled automatic retention never calls this."""

        now = datetime.now(UTC)
        with self.session_factory() as session:
            batch_ids = session.scalars(
                select(StorageCleanupBatchModel.id).where(
                    StorageCleanupBatchModel.state.in_(("quarantined", "restore_conflict")),
                    StorageCleanupBatchModel.recovery_expires_at.is_not(None),
                    StorageCleanupBatchModel.recovery_expires_at <= now,
                )
            ).all()
        purged = 0
        for batch_id in batch_ids[:MAX_STORAGE_CLEANUP_HISTORY_ITEMS]:
            result = self.purge_storage_cleanup_batch(
                batch_id,
                StorageCleanupPurgeRequest(
                    confirm=True,
                    idempotency_key=f"automatic-purge-{batch_id}",
                ),
                allow_before_deadline=True,
            )
            if result is not None:
                purged += result.moved_to_recovery_count
        return purged

    def _storage_retention_settings_response(
        self,
        model: StorageRetentionSettingsModel | None,
    ) -> StorageRetentionSettings:
        if model is None:
            return StorageRetentionSettings(
                persisted=False,
                recommended_defaults=True,
                policy_revision=1,
                message="Automatic cleanup is disabled by default. Existing media remains untouched until you preview and confirm cleanup.",
            )
        recommended = (
            not model.automatic_cleanup_enabled
            and model.cleanup_frequency == StorageRetentionFrequency.weekly.value
            and model.retain_unresolved_visit_evidence
            and model.retain_reviewed_bird_wildlife_evidence
            and model.reviewed_non_bird_age_days == DEFAULT_STORAGE_REVIEWED_NON_BIRD_AGE_DAYS
            and model.superseded_evidence_age_days == DEFAULT_STORAGE_SUPERSEDED_AGE_DAYS
            and model.orphaned_media_age_days == DEFAULT_STORAGE_ORPHANED_AGE_DAYS
            and model.rejected_analysis_media_age_days is None
            and model.maximum_managed_media_bytes is None
        )
        return StorageRetentionSettings(
            automatic_cleanup_enabled=model.automatic_cleanup_enabled,
            cleanup_frequency=StorageRetentionFrequency(model.cleanup_frequency),
            retain_unresolved_visit_evidence=True,
            retain_reviewed_bird_wildlife_evidence=(
                model.retain_reviewed_bird_wildlife_evidence
            ),
            reviewed_non_bird_age_days=model.reviewed_non_bird_age_days,
            superseded_evidence_age_days=model.superseded_evidence_age_days,
            orphaned_media_age_days=model.orphaned_media_age_days,
            rejected_analysis_media_age_days=model.rejected_analysis_media_age_days,
            maximum_managed_media_bytes=model.maximum_managed_media_bytes,
            policy_revision=model.policy_revision,
            persisted=True,
            recommended_defaults=recommended,
            updated_at=model.updated_at,
            last_automatic_run_at=model.last_automatic_run_at,
            last_automatic_result=model.last_automatic_result,
            message=(
                "Automatic cleanup is enabled. Every run calculates a fresh local preview and keeps protected evidence."
                if model.automatic_cleanup_enabled
                else "Automatic cleanup is disabled. Preview and confirm cleanup before any managed file moves to recovery."
            ),
        )

    def _storage_managed_media_path(
        self,
        asset: MediaAssetModel,
    ) -> tuple[Path | None, Path | None, int | None, str | None]:
        """Fail closed for paths, symlinks, missing files, and integrity mismatches."""

        try:
            root = self.media_root.resolve()
            raw = Path(asset.local_path)
            raw_candidates = [raw] if raw.is_absolute() else [raw, self.media_root / raw]
            candidate = next(
                (
                    item.absolute()
                    for item in raw_candidates
                    if item.absolute().resolve(strict=False).is_relative_to(root)
                ),
                None,
            )
        except OSError:
            return None, None, None, "path_integrity"
        if candidate is None:
            return None, None, None, "outside_managed_storage"
        resolved = candidate.resolve(strict=False)
        if not resolved.is_relative_to(root):
            return None, None, None, "outside_managed_storage"
        relative = resolved.relative_to(root)
        if not relative.parts or relative.parts[0] == ".recovery":
            return None, None, None, "recovery_or_ambiguous_path"
        current = root
        for part in relative.parts:
            current = current / part
            if current.is_symlink():
                return None, None, None, "symlink_path"
        if not candidate.exists() or not candidate.is_file():
            return None, None, None, "missing_or_incomplete_file"
        try:
            size = candidate.stat().st_size
        except OSError:
            return None, None, None, "path_integrity"
        if size != asset.file_size_bytes:
            return None, None, None, "integrity_mismatch"
        return candidate, relative, size, None

    def _storage_has_non_visit_reference(self, session: Session, media_asset_id: str) -> bool:
        """Any reference outside Visit links is ownership context, not safe orphan evidence."""

        reference_queries = (
            select(MotionEvidenceModel.id).where(
                MotionEvidenceModel.snapshot_media_asset_id == media_asset_id
            ),
            select(DetectionRunModel.id).where(DetectionRunModel.media_asset_id == media_asset_id),
            select(DetectionProposalModel.id).where(
                DetectionProposalModel.media_asset_id == media_asset_id
            ),
            select(SpeciesSuggestionModel.id).where(
                SpeciesSuggestionModel.media_asset_id == media_asset_id
            ),
            select(BioClipIdentificationAttemptModel.id).where(
                BioClipIdentificationAttemptModel.media_asset_id == media_asset_id
            ),
        )
        return any(session.scalar(query.limit(1)) is not None for query in reference_queries)

    def _storage_visit_is_wildlife(self, session: Session, visit: VisitModel) -> bool:
        """Fail-closed retention check: does this Visit's label mean wildlife?

        Routes the taxonomy-matched branch through the shared
        `wildlife_taxonomy.is_wildlife_category` denylist (also used by
        `analytics.place_activity_report`) instead of a second local
        `{"bird", "mammal"}` allowlist, so a future wildlife taxonomy
        category (reptile, amphibian, ...) is protected from storage
        cleanup automatically instead of silently falling outside this
        retention guard until this method is separately updated. The
        untaxonomized fallback below is unrelated (no taxonomy row to read
        a category from) and is unchanged.
        """

        label = (visit.reviewed_label or visit.subject_label or "").strip()
        taxonomy = session.scalar(
            select(TaxonomyLabelModel).where(TaxonomyLabelModel.label == label)
        )
        if taxonomy is not None:
            return is_wildlife_category(taxonomy.category)
        return label in {"bird", "unknown_bird", "wildlife"}

    def _storage_visit_required_by_export(self, session: Session, visit: VisitModel) -> bool:
        if visit.review_status != ReviewStatus.reviewed.value:
            return False
        exports = session.scalars(select(DatasetExportModel)).all()
        for export in exports:
            selected = _json_list(export.selected_visit_ids_json)
            if selected and visit.id in selected:
                return True
            event = session.get(EventModel, visit.event_id)
            if (
                not selected
                and export.reviewed_only
                and event is not None
                and _as_utc(event.started_at) <= _as_utc(export.created_at)
            ):
                # An unscoped export preserves the reviewed context that existed
                # when it was created. Later Visits are not retroactively part of
                # that exported dataset, so their secondary evidence follows the
                # explicit retention policy instead.
                return True
        return False

    def _storage_active_visit_has_valid_primary(
        self,
        session: Session,
        visit: VisitModel,
    ) -> bool:
        """Fail closed when an active Visit has evidence but no retained primary frame."""

        links = session.scalars(
            select(VisitEvidenceLinkModel).where(VisitEvidenceLinkModel.visit_id == visit.id)
        ).all()
        if not links:
            return True
        for link in links:
            asset = session.get(MediaAssetModel, link.media_asset_id)
            if asset is None:
                continue
            is_representative = visit.representative_media_path == asset.local_path
            if (link.is_primary or is_representative) and self._storage_managed_media_path(asset)[0] is not None:
                return True
        return False

    def _storage_retention_evaluation(
        self,
        session: Session,
        settings: StorageRetentionSettings,
        now: datetime,
    ) -> _StorageRetentionEvaluation:
        candidates: list[_StorageRetentionCandidate] = []
        protected_counts: Counter[str] = Counter()
        protected_bytes: Counter[str] = Counter()
        warnings: list[str] = []
        assets = session.scalars(
            select(MediaAssetModel).order_by(MediaAssetModel.created_at, MediaAssetModel.id)
        ).all()
        parent_ids_with_derivatives = {
            asset.parent_media_asset_id
            for asset in assets
            if asset.parent_media_asset_id
        }
        for asset in assets:
            path, relative, size, unsafe_reason = self._storage_managed_media_path(asset)
            if path is None or relative is None or size is None:
                protected_counts[unsafe_reason or "ambiguous_media"] += 1
                continue
            if asset.id in parent_ids_with_derivatives:
                # A retained derivative must never point at a silently removed
                # original. Resolve that relationship explicitly before cleanup.
                protected_counts["derived_media_reference"] += 1
                protected_bytes["derived_media_reference"] += size
                continue
            age_days = max(0, (now - _as_utc(asset.created_at)).days)
            links = session.scalars(
                select(VisitEvidenceLinkModel).where(
                    VisitEvidenceLinkModel.media_asset_id == asset.id
                )
            ).all()
            visits_by_link = [(link, session.get(VisitModel, link.visit_id)) for link in links]
            if any(visit is None for _link, visit in visits_by_link):
                protected_counts["ambiguous_visit_linkage"] += 1
                protected_bytes["ambiguous_visit_linkage"] += size
                continue
            visits = [visit for _link, visit in visits_by_link if visit is not None]
            # Older records can have a representative path without a materialized
            # VisitEvidenceLink. Treat that ambiguous legacy relationship as protected.
            legacy_representative_visits = session.scalars(
                select(VisitModel).where(VisitModel.representative_media_path == asset.local_path)
            ).all()
            if legacy_representative_visits and not links:
                protected_counts["legacy_representative_evidence"] += 1
                protected_bytes["legacy_representative_evidence"] += size
                continue
            active_pairs = [
                (link, visit)
                for link, visit in visits_by_link
                if visit is not None and not visit.is_superseded
            ]
            non_visit_reference = self._storage_has_non_visit_reference(session, asset.id)
            if not links and not non_visit_reference:
                if age_days >= settings.orphaned_media_age_days:
                    candidates.append(
                        _StorageRetentionCandidate(
                            asset_id=asset.id,
                            category="orphaned_managed_media",
                            local_path=path,
                            relative_path=relative,
                            file_size_bytes=size,
                            created_at=_as_utc(asset.created_at),
                            affected_visit_ids=(),
                            evidence_links=(),
                        )
                    )
                else:
                    protected_counts["orphaned_media_too_recent"] += 1
                    protected_bytes["orphaned_media_too_recent"] += size
                continue
            if non_visit_reference:
                # Appliance / Storage / Privacy / Recovery v1, Phase D: the
                # one opt-in lever for this category (default `None` ->
                # exactly today's protected-forever behavior, unchanged for
                # every installation that never configures it explicitly).
                if (
                    settings.rejected_analysis_media_age_days is not None
                    and age_days >= settings.rejected_analysis_media_age_days
                ):
                    candidates.append(
                        _StorageRetentionCandidate(
                            asset_id=asset.id,
                            category="rejected_analysis_media",
                            local_path=path,
                            relative_path=relative,
                            file_size_bytes=size,
                            created_at=_as_utc(asset.created_at),
                            affected_visit_ids=(),
                            evidence_links=(),
                        )
                    )
                    continue
                protected_counts["linked_evidence_or_analysis"] += 1
                protected_bytes["linked_evidence_or_analysis"] += size
                continue
            if asset.evidence_role in {"activity_crop", "user_refined_crop"} and links:
                # Crop revisions are deliberate reviewer evidence; preview cleanup
                # must not discard the automatic or prior refined crop history.
                protected_counts["crop_revision_history"] += 1
                protected_bytes["crop_revision_history"] += size
                continue
            if active_pairs:
                # A single asset with both active and superseded Visit links has
                # ambiguous recovery context. Keep it until that relationship is
                # explicitly resolved rather than moving media behind either Visit.
                if len(active_pairs) != len(visits_by_link):
                    protected_counts["mixed_visit_lineage_evidence"] += 1
                    protected_bytes["mixed_visit_lineage_evidence"] += size
                    continue
                active_visits = [visit for _link, visit in active_pairs]
                if any(visit.review_status == ReviewStatus.needs_review.value for visit in active_visits):
                    protected_counts["unresolved_visit_evidence"] += 1
                    protected_bytes["unresolved_visit_evidence"] += size
                    continue
                if any(
                    not self._storage_active_visit_has_valid_primary(session, visit)
                    for visit in active_visits
                ):
                    protected_counts["active_visit_missing_valid_primary"] += 1
                    protected_bytes["active_visit_missing_valid_primary"] += size
                    continue
                if any(
                    link.is_primary or visit.representative_media_path == asset.local_path
                    for link, visit in active_pairs
                ):
                    protected_counts["active_visit_primary_evidence"] += 1
                    protected_bytes["active_visit_primary_evidence"] += size
                    continue
                if any(self._storage_visit_required_by_export(session, visit) for visit in active_visits):
                    protected_counts["retained_export_context"] += 1
                    protected_bytes["retained_export_context"] += size
                    continue
                has_wildlife = any(
                    visit.review_status == ReviewStatus.reviewed.value
                    and self._storage_visit_is_wildlife(session, visit)
                    for visit in active_visits
                )
                if has_wildlife and settings.retain_reviewed_bird_wildlife_evidence:
                    protected_counts["reviewed_bird_wildlife_evidence"] += 1
                    protected_bytes["reviewed_bird_wildlife_evidence"] += size
                    continue
                if (
                    all(visit.review_status == ReviewStatus.reviewed.value for visit in active_visits)
                    and age_days >= settings.reviewed_non_bird_age_days
                ):
                    category = (
                        "reviewed_bird_wildlife_secondary"
                        if has_wildlife
                        else "reviewed_non_bird_secondary"
                    )
                    candidates.append(
                        _StorageRetentionCandidate(
                            asset_id=asset.id,
                            category=category,
                            local_path=path,
                            relative_path=relative,
                            file_size_bytes=size,
                            created_at=_as_utc(asset.created_at),
                            affected_visit_ids=tuple(sorted({visit.id for visit in active_visits})),
                            evidence_links=tuple(
                                self._storage_link_snapshot(link) for link, _visit in active_pairs
                            ),
                        )
                    )
                else:
                    protected_counts["active_visit_evidence"] += 1
                    protected_bytes["active_visit_evidence"] += size
                continue
            if visits and all(visit.is_superseded for visit in visits):
                if age_days >= settings.superseded_evidence_age_days:
                    candidates.append(
                        _StorageRetentionCandidate(
                            asset_id=asset.id,
                            category="superseded_only_evidence",
                            local_path=path,
                            relative_path=relative,
                            file_size_bytes=size,
                            created_at=_as_utc(asset.created_at),
                            affected_visit_ids=tuple(sorted({visit.id for visit in visits})),
                            evidence_links=tuple(
                                self._storage_link_snapshot(link) for link, _visit in visits_by_link
                            ),
                        )
                    )
                else:
                    protected_counts["superseded_evidence_too_recent"] += 1
                    protected_bytes["superseded_evidence_too_recent"] += size
                continue
            protected_counts["ambiguous_media_linkage"] += 1
            protected_bytes["ambiguous_media_linkage"] += size
        if protected_counts.get("integrity_mismatch", 0):
            warnings.append("Some managed media failed integrity checks and was retained.")
        return _StorageRetentionEvaluation(
            candidates=tuple(candidates),
            protected_counts=protected_counts,
            protected_bytes=protected_bytes,
            warnings=tuple(warnings),
        )

    def _storage_link_snapshot(self, link: VisitEvidenceLinkModel) -> dict[str, Any]:
        return {
            "id": link.id,
            "visit_id": link.visit_id,
            "captured_at": _as_utc(link.captured_at).isoformat(),
            "frame_sequence": link.frame_sequence,
            "sort_order": link.sort_order,
            "is_primary": link.is_primary,
            "evidence_role": link.evidence_role,
            "created_at": _as_utc(link.created_at).isoformat(),
        }

    def _storage_total_managed_bytes(self, session: Session) -> int:
        total = 0
        for asset in session.scalars(select(MediaAssetModel)).all():
            _path, _relative, size, _reason = self._storage_managed_media_path(asset)
            total += size or 0
        return total

    def _storage_candidates_for_target(
        self,
        candidates: tuple[_StorageRetentionCandidate, ...],
        target_bytes: int | None,
        total_bytes: int,
    ) -> list[_StorageRetentionCandidate]:
        ordered = sorted(candidates, key=lambda item: (item.created_at, item.asset_id))
        if target_bytes is None or total_bytes <= target_bytes:
            return ordered
        needed = total_bytes - target_bytes
        selected: list[_StorageRetentionCandidate] = []
        reclaimed = 0
        for candidate in ordered:
            selected.append(candidate)
            reclaimed += candidate.file_size_bytes
            if reclaimed >= needed:
                break
        return selected

    def _storage_cleanup_fingerprint(
        self,
        candidates: list[_StorageRetentionCandidate],
        settings: StorageRetentionSettings,
    ) -> str:
        state = {
            "policy_revision": settings.policy_revision,
            "maximum_managed_media_bytes": settings.maximum_managed_media_bytes,
            "candidates": [
                {
                    "asset_id": candidate.asset_id,
                    "category": candidate.category,
                    "size": candidate.file_size_bytes,
                    "created_at": candidate.created_at.isoformat(),
                    "links": [link["id"] for link in candidate.evidence_links],
                }
                for candidate in candidates
            ],
        }
        return hashlib.sha256(json.dumps(state, sort_keys=True).encode("utf-8")).hexdigest()

    def _storage_cleanup_preview_response(
        self,
        *,
        batch: StorageCleanupBatchModel,
        candidates: list[_StorageRetentionCandidate],
        evaluation: _StorageRetentionEvaluation,
        now: datetime,
        capped: bool,
    ) -> StorageCleanupPreviewResponse:
        category_counts: Counter[str] = Counter(candidate.category for candidate in candidates)
        category_bytes: Counter[str] = Counter()
        for candidate in candidates:
            category_bytes[candidate.category] += candidate.file_size_bytes
        categories = [
            StorageCleanupCategorySummary(
                category=category,
                media_count=category_counts[category],
                bytes=category_bytes[category],
            )
            for category in sorted(category_counts)
        ]
        protected = [
            StorageCleanupCategorySummary(
                category=category,
                media_count=evaluation.protected_counts[category],
                bytes=evaluation.protected_bytes[category],
            )
            for category in sorted(evaluation.protected_counts)
        ]
        warnings = list(evaluation.warnings)
        if any(candidate.category.endswith("_secondary") for candidate in candidates):
            warnings.append(
                "Eligible cleanup would reduce secondary Visit evidence; each active Visit retains its primary frame."
            )
        if capped:
            warnings.append("Preview is bounded. Run cleanup and preview again to continue with remaining eligible media.")
        if not candidates:
            warnings.append("No managed media is currently eligible. Protected evidence was retained.")
        return StorageCleanupPreviewResponse(
            preview_token=batch.preview_token,
            generated_at=now,
            expires_at=now + STORAGE_CLEANUP_PREVIEW_TTL,
            eligible_media_count=len(candidates),
            estimated_recoverable_bytes=sum(candidate.file_size_bytes for candidate in candidates),
            categories=categories,
            oldest_eligible_at=min((candidate.created_at for candidate in candidates), default=None),
            newest_eligible_at=max((candidate.created_at for candidate in candidates), default=None),
            affected_visit_count=len(
                {visit_id for candidate in candidates for visit_id in candidate.affected_visit_ids}
            ),
            protected_counts=protected,
            warnings=warnings,
            message="Preview only. No media or evidence links moved until you confirm this unchanged server-issued plan.",
        )

    def _storage_recovery_root(self) -> Path:
        return self.media_root / ".recovery"

    def _storage_recovery_path_for_item(self, item: StorageCleanupItemModel) -> Path | None:
        try:
            relative = Path(item.quarantine_relative_path or "")
            if relative.is_absolute() or not relative.parts or any(part in {"", ".", ".."} for part in relative.parts):
                return None
            managed_root = self.media_root.resolve()
            configured_root = self._storage_recovery_root()
            if configured_root.exists() and configured_root.is_symlink():
                return None
            root = configured_root.resolve(strict=False)
            if not root.is_relative_to(managed_root):
                return None
            candidate = (root / item.batch_id / relative).resolve(strict=False)
            return candidate if candidate.is_relative_to(root) else None
        except OSError:
            return None

    def _storage_cleanup_item_is_still_eligible(
        self,
        item: StorageCleanupItemModel,
        *,
        now: datetime,
    ) -> bool:
        """Reject a staged move when Visit or file state changed after preview."""

        with self.session_factory() as session:
            return self._storage_cleanup_item_is_still_eligible_in_session(
                session,
                item,
                now=now,
            )

    def _storage_cleanup_item_is_still_eligible_in_session(
        self,
        session: Session,
        item: StorageCleanupItemModel,
        *,
        now: datetime,
    ) -> bool:
        """Check the complete current policy from within the caller's transaction."""

        settings = self._storage_retention_settings_response(
            session.get(StorageRetentionSettingsModel, 1)
        )
        evaluation = self._storage_retention_evaluation(session, settings, now)
        candidate = next(
            (
                value
                for value in evaluation.candidates
                if value.asset_id == item.media_asset_id
            ),
            None,
        )
        if candidate is None:
            return False
        expected_links = self._storage_link_snapshot_signature(
            _json_list(item.evidence_links_json)
        )
        return (
            candidate.category == item.category
            and candidate.local_path == Path(item.original_local_path)
            and candidate.file_size_bytes == item.file_size_bytes
            and self._storage_link_snapshot_signature(candidate.evidence_links)
            == expected_links
        )

    @staticmethod
    def _storage_link_snapshot_signature(
        snapshots: Iterable[dict[str, Any]],
    ) -> tuple[str, ...]:
        """Compare links independent of database return order."""

        return tuple(
            sorted(json.dumps(snapshot, sort_keys=True, default=str) for snapshot in snapshots)
        )

    def _storage_cleanup_item_snapshot_is_valid(self, item: StorageCleanupItemModel) -> bool:
        """Never restore a file unless its durable link snapshot can be reconstructed."""

        for link in _json_list(item.evidence_links_json):
            if not isinstance(link.get("id"), str) or not isinstance(link.get("visit_id"), str):
                return False
            if _parse_datetime(link.get("captured_at")) is None:
                return False
            if _parse_datetime(link.get("created_at")) is None:
                return False
        return True

    def _storage_item_has_recovery_file(self, item: StorageCleanupItemModel) -> bool:
        """Recognize only a complete, managed recovery file as recoverable staging."""

        try:
            path = self._storage_recovery_path_for_item(item)
            return bool(
                path is not None
                and path.exists()
                and path.is_file()
                and not path.is_symlink()
                and path.stat().st_size == item.file_size_bytes
                and not Path(item.original_local_path).exists()
            )
        except OSError:
            return False

    def _move_storage_item_to_recovery(self, item: StorageCleanupItemModel) -> bool:
        """Filesystem movement is staged after a durable DB record, never an unlink first."""

        try:
            source = Path(item.original_local_path)
            root = self.media_root.resolve()
            resolved_source = source.resolve(strict=False)
            if (
                not resolved_source.is_relative_to(root)
                or not resolved_source.relative_to(root).parts
                or resolved_source.relative_to(root).parts[0] == ".recovery"
                or not source.exists()
                or not source.is_file()
                or source.is_symlink()
                or source.stat().st_size != item.file_size_bytes
            ):
                return False
            target = self._storage_recovery_path_for_item(item)
            if target is None or target.exists():
                return False
            target.parent.mkdir(parents=True, exist_ok=True)
            if target.parent.is_symlink():
                return False
            source.replace(target)
            return True
        except OSError:
            return False

    def _restore_storage_item_from_recovery(self, item: StorageCleanupItemModel) -> bool:
        try:
            source = self._storage_recovery_path_for_item(item)
            target = Path(item.original_local_path)
            root = self.media_root.resolve()
            resolved_target = target.resolve(strict=False)
            if (
                source is None
                or not source.exists()
                or not source.is_file()
                or source.is_symlink()
                or not resolved_target.is_relative_to(root)
                or not resolved_target.relative_to(root).parts
                or resolved_target.relative_to(root).parts[0] == ".recovery"
                or target.exists()
            ):
                return False
            target.parent.mkdir(parents=True, exist_ok=True)
            if target.parent.is_symlink():
                return False
            source.replace(target)
            return True
        except OSError:
            return False

    def _purge_storage_item(self, item: StorageCleanupItemModel) -> bool:
        try:
            path = self._storage_recovery_path_for_item(item)
            if path is None:
                return False
            if not path.exists():
                return True
            if not path.is_file() or path.is_symlink():
                return False
            path.unlink()
            return True
        except OSError:
            return False

    def _storage_cleanup_result_from_batch(
        self,
        batch: StorageCleanupBatchModel,
        *,
        idempotent: bool = False,
    ) -> StorageCleanupResult:
        summary = _json_object(batch.summary_json)
        return StorageCleanupResult(
            batch_id=batch.id,
            state=batch.state,
            moved_to_recovery_count=int(summary.get("media_count", 0)),
            skipped_count=int(summary.get("skipped_count", 0)),
            failed_count=int(summary.get("failed_count", 0)),
            recovered_bytes=int(summary.get("recovered_bytes", 0)),
            recovery_expires_at=batch.recovery_expires_at,
            message=(
                "Media moved to recovery. You can restore it until the recovery deadline."
                if batch.state == "quarantined"
                else "Cleanup completed with recoverable conflicts; inspect the local cleanup history."
                if batch.state == "restore_conflict"
                else "Media was restored safely."
                if batch.state == "restored"
                else "Recovery media was permanently purged."
                if batch.state == "purged"
                else "Cleanup was interrupted after a recoverable file move; restore remains available."
                if batch.state == "staging"
                else "Cleanup did not move any media."
            ),
            warnings=[batch.safe_error] if batch.safe_error else [],
            idempotent=idempotent,
        )

    def _storage_cleanup_history_item(
        self,
        batch: StorageCleanupBatchModel,
    ) -> StorageCleanupHistoryItem:
        summary = _json_object(batch.summary_json)
        return StorageCleanupHistoryItem(
            batch_id=batch.id,
            origin=batch.origin,
            state=batch.state,
            created_at=batch.created_at,
            media_count=int(summary.get("media_count", summary.get("planned_count", 0))),
            recovered_bytes=int(summary.get("recovered_bytes", 0)),
            permanently_purged_count=int(summary.get("permanently_purged_count", 0)),
            skipped_count=int(summary.get("skipped_count", 0)),
            failed_count=int(summary.get("failed_count", 0)),
            recovery_expires_at=batch.recovery_expires_at,
            message=(
                batch.safe_error
                or "Managed media was moved only after a confirmed local cleanup preview."
            ),
            can_restore=(
                batch.state in {"quarantined", "staging"}
                and batch.recovery_expires_at is not None
                and _as_utc(batch.recovery_expires_at) > datetime.now(UTC)
            ),
        )

    def saved_preview_retention_report(self) -> SavedMediaRetentionReportResponse:
        with self.session_factory() as session:
            asset_models = session.scalars(
                select(MediaAssetModel).order_by(MediaAssetModel.created_at, MediaAssetModel.id)
            ).all()
            items = [
                self._saved_preview_retention_item(session, asset_model)
                for asset_model in asset_models
                if _is_external_url_preview_media_asset(asset_model)
            ]

        risk_counts = Counter(item.risk_level for item in items)
        summary_warnings: list[str] = []
        if any(item.warnings for item in items):
            summary_warnings.append(
                "Some saved preview media has retention warnings; inspect item warnings."
            )

        return SavedMediaRetentionReportResponse(
            items=items,
            summary=SavedMediaRetentionSummary(
                total_items=len(items),
                total_known_bytes=sum(item.size_bytes or 0 for item in items),
                unknown_size_count=sum(1 for item in items if item.size_bytes is None),
                low_risk_count=risk_counts["low"],
                medium_risk_count=risk_counts["medium"],
                high_risk_count=risk_counts["high"],
                protected_count=risk_counts["protected"],
                warnings=summary_warnings,
            ),
            generated_at=datetime.now(UTC),
            dry_run_only=True,
        )

    def saved_preview_cleanup_dry_run(
        self,
        payload: SavedMediaCleanupDryRunRequest,
    ) -> SavedMediaCleanupDryRunResponse:
        report = self.saved_preview_retention_report()
        report_ids = {item.media_asset_id for item in report.items}
        selected_ids = {
            media_id.strip()
            for media_id in payload.media_asset_ids or []
            if media_id.strip()
        }
        selected_risk_levels = {
            risk_level.strip().lower()
            for risk_level in payload.risk_levels or []
            if risk_level.strip()
        }
        if not selected_ids and not selected_risk_levels:
            selected_risk_levels = {"low"}

        valid_risk_levels = {"low", "medium", "high", "protected"}
        unsupported_risk_levels = selected_risk_levels - valid_risk_levels
        selected_risk_levels &= valid_risk_levels

        warnings = ["Dry-run only; no files or records were deleted."]
        for media_id in sorted(selected_ids - report_ids):
            warnings.append(
                f"MediaAsset {media_id} is not a saved external_url preview retention item."
            )
        for risk_level in sorted(unsupported_risk_levels):
            warnings.append(f"Unsupported retention risk level ignored: {risk_level}.")

        dry_run_items: list[SavedMediaCleanupDryRunItem] = []
        for item in report.items:
            if selected_ids and item.media_asset_id not in selected_ids:
                continue
            if selected_risk_levels and item.risk_level not in selected_risk_levels:
                continue

            dry_run_items.append(self._saved_preview_cleanup_dry_run_item(item, payload))

        return SavedMediaCleanupDryRunResponse(
            items=dry_run_items,
            total_would_delete_files=sum(1 for item in dry_run_items if item.would_delete_file),
            total_would_delete_records=sum(
                1 for item in dry_run_items if item.would_delete_record
            ),
            total_known_bytes_to_delete=sum(
                item.size_bytes or 0 for item in dry_run_items if item.would_delete_file
            ),
            skipped_count=sum(1 for item in dry_run_items if item.would_skip),
            protected_skipped_count=sum(
                1
                for item in dry_run_items
                if item.skip_reason == "protected_media_skipped"
            ),
            dry_run=True,
            creates_truth=False,
            deletes_truth=False,
            warnings=warnings,
        )

    def _saved_preview_retention_item(
        self,
        session: Session,
        asset_model: MediaAssetModel,
    ) -> SavedMediaRetentionItem:
        note_fields = _external_url_preview_note_fields(asset_model.notes)
        warnings: list[str] = []
        fetched_at = _parsed_note_datetime(note_fields.get("fetched_at"), warnings)
        size_bytes, size_warnings = self._saved_preview_size_bytes(asset_model)
        warnings.extend(size_warnings)

        motion_evidence = session.scalars(
            select(MotionEvidenceModel)
            .where(MotionEvidenceModel.snapshot_media_asset_id == asset_model.id)
            .order_by(MotionEvidenceModel.created_at, MotionEvidenceModel.id)
        ).all()
        linked_event_ids = {
            evidence.promoted_event_id
            for evidence in motion_evidence
            if evidence.promoted_event_id is not None
        }
        linked_visit_ids = {
            evidence.promoted_visit_id
            for evidence in motion_evidence
            if evidence.promoted_visit_id is not None
        }

        visit_models_by_id: dict[str, VisitModel] = {}
        if asset_model.local_path:
            for visit_model in session.scalars(
                select(VisitModel).where(
                    VisitModel.representative_media_path == asset_model.local_path
                )
            ).all():
                linked_visit_ids.add(visit_model.id)
                linked_event_ids.add(visit_model.event_id)
                visit_models_by_id[visit_model.id] = visit_model

        for visit_id in linked_visit_ids:
            if visit_id not in visit_models_by_id:
                visit_model = session.get(VisitModel, visit_id)
                if visit_model is not None:
                    visit_models_by_id[visit_id] = visit_model
                else:
                    warnings.append(
                        f"Linked Visit {visit_id} was not found; classified conservatively."
                    )

        event_models_by_id: dict[str, EventModel] = {}
        for event_id in linked_event_ids:
            event_model = session.get(EventModel, event_id)
            if event_model is not None:
                event_models_by_id[event_id] = event_model
            else:
                warnings.append(
                    f"Linked Event {event_id} was not found; classified conservatively."
                )

        reviewed_truth_refs: set[str] = set()
        for visit_id, visit_model in visit_models_by_id.items():
            if (
                visit_model.review_status == ReviewStatus.reviewed.value
                or visit_model.reviewed_label is not None
            ):
                reviewed_truth_refs.add(f"visit:{visit_id}")
            for label_model in self._review_label_models_for_visit(session, visit_id):
                reviewed_truth_refs.add(f"review-label:{label_model.id}")

        for event_id, event_model in event_models_by_id.items():
            if event_model.review_status == ReviewStatus.reviewed.value:
                reviewed_truth_refs.add(f"event:{event_id}")
            for label_model in self._review_label_models_for_event(session, event_id):
                reviewed_truth_refs.add(f"review-label:{label_model.id}")

        pending_count = sum(
            1
            for evidence in motion_evidence
            if evidence.status == MotionEvidenceStatus.pending.value
        )
        ignored_count = sum(
            1
            for evidence in motion_evidence
            if evidence.status == MotionEvidenceStatus.ignored.value
        )
        promoted_count = sum(
            1
            for evidence in motion_evidence
            if evidence.status == MotionEvidenceStatus.promoted.value
        )
        known_statuses = {
            MotionEvidenceStatus.pending.value,
            MotionEvidenceStatus.ignored.value,
            MotionEvidenceStatus.promoted.value,
        }
        if any(evidence.status not in known_statuses for evidence in motion_evidence):
            warnings.append(
                "Unknown MotionEvidence status encountered; classified conservatively."
            )

        reviewed_truth_count = len(reviewed_truth_refs)
        if reviewed_truth_count > 0:
            media_state = "reviewed_truth_context"
            risk_level = "protected"
            recommended_action = "Skip by default; media is linked to reviewed truth."
        elif linked_event_ids or linked_visit_ids:
            media_state = "linked_event_visit"
            risk_level = "high"
            recommended_action = "Keep by default; media supports Event/Visit review context."
        elif promoted_count > 0:
            media_state = "linked_promoted_evidence"
            risk_level = "high"
            recommended_action = "Keep by default; media is linked to promoted evidence."
        elif pending_count > 0:
            media_state = "linked_pending_evidence"
            risk_level = "medium"
            recommended_action = "Review pending MotionEvidence before cleanup."
        elif ignored_count > 0:
            media_state = "linked_ignored_evidence"
            risk_level = "medium"
            recommended_action = "Review ignored MotionEvidence before cleanup."
        elif not motion_evidence:
            media_state = "saved_unlinked"
            risk_level = "low"
            recommended_action = "Eligible for future low-risk cleanup dry run."
        else:
            media_state = "unknown"
            risk_level = "high"
            recommended_action = "Inspect manually before cleanup."
            warnings.append("Insufficient linkage metadata; classified as high risk.")

        return SavedMediaRetentionItem(
            media_asset_id=asset_model.id,
            source_id=asset_model.source_id,
            stream_id=asset_model.stream_id,
            file_name=asset_model.filename,
            content_type=asset_model.content_type,
            size_bytes=size_bytes,
            created_at=_as_utc(asset_model.created_at),
            fetched_at=fetched_at,
            provider_key=note_fields.get("provider_key"),
            provenance=_saved_preview_provenance(note_fields),
            linked_motion_evidence_count=len(motion_evidence),
            linked_event_count=len(linked_event_ids),
            linked_visit_count=len(linked_visit_ids),
            reviewed_truth_count=reviewed_truth_count,
            risk_level=risk_level,
            media_state=media_state,
            recommended_action=recommended_action,
            warnings=warnings,
        )

    def _saved_preview_size_bytes(
        self,
        asset_model: MediaAssetModel,
    ) -> tuple[int | None, list[str]]:
        warnings: list[str] = []
        size_bytes = asset_model.file_size_bytes if asset_model.file_size_bytes >= 0 else None
        media_root = self.media_root.resolve()
        try:
            media_path = Path(asset_model.local_path).resolve()
        except OSError:
            warnings.append("Local media path could not be resolved; filesystem metadata skipped.")
            return size_bytes, warnings

        if not media_path.is_relative_to(media_root):
            warnings.append(
                "Local media path is outside the configured media root; filesystem metadata skipped."
            )
            return size_bytes, warnings

        if not media_path.exists():
            warnings.append("Local media file is missing or stale; no file was opened.")
            return size_bytes, warnings

        if size_bytes is None:
            try:
                size_bytes = media_path.stat().st_size
            except OSError:
                warnings.append("Local media size could not be read from filesystem metadata.")
        return size_bytes, warnings

    def _saved_preview_cleanup_dry_run_item(
        self,
        item: SavedMediaRetentionItem,
        payload: SavedMediaCleanupDryRunRequest,
    ) -> SavedMediaCleanupDryRunItem:
        warnings = list(item.warnings)
        skip_reason: str | None = None
        mode = payload.mode.strip() if payload.mode.strip() else "delete_file_only"

        if item.risk_level == "protected" and not payload.include_protected:
            skip_reason = "protected_media_skipped"
        elif any("outside the configured media root" in warning for warning in warnings):
            skip_reason = "unsafe_media_path"
        elif any("missing or stale" in warning for warning in warnings):
            skip_reason = "stale_media_reference"
        elif mode not in {"delete_file_only", "delete_media_asset", "archive"}:
            skip_reason = "unsupported_mode"
            warnings.append(f"Unsupported cleanup mode ignored: {mode}.")

        would_skip = skip_reason is not None
        would_delete_file = False
        would_delete_record = False
        if not would_skip:
            if mode == "delete_file_only":
                would_delete_file = True
            elif mode == "delete_media_asset":
                would_delete_file = True
                would_delete_record = True

        return SavedMediaCleanupDryRunItem(
            media_asset_id=item.media_asset_id,
            risk_level=item.risk_level,
            would_delete_file=would_delete_file,
            would_delete_record=would_delete_record,
            would_skip=would_skip,
            skip_reason=skip_reason,
            file_name=item.file_name,
            size_bytes=item.size_bytes,
            warnings=warnings,
        )

    def cleanup_saved_preview_media(
        self,
        media_asset_id: str,
        payload: SavedMediaCleanupRequest,
    ) -> SavedMediaCleanupResponse | None:
        media_id = media_asset_id.strip()
        if not media_id:
            return None

        mode = payload.mode.strip() if payload.mode.strip() else "delete_file_only"
        if not payload.confirm:
            raise ValueError("cleanup_requires_confirmation")
        if mode != "delete_file_only":
            raise ValueError("unsupported_cleanup_mode")

        with self.session_factory() as session:
            asset_model = session.get(MediaAssetModel, media_id)
            if asset_model is None:
                return None

            if not _is_external_url_preview_media_asset(asset_model):
                return SavedMediaCleanupResponse(
                    media_asset_id=media_id,
                    status="rejected",
                    risk_level="unknown",
                    media_state="unknown",
                    file_deleted=False,
                    record_deleted=False,
                    creates_truth=False,
                    deletes_truth=False,
                    message=(
                        "Only saved external_url preview MediaAssets are eligible for "
                        "file-only cleanup in this phase."
                    ),
                    file_name=asset_model.filename,
                    size_bytes=asset_model.file_size_bytes,
                    warnings=["MediaAsset is not a saved external_url preview."],
                )

            item = self._saved_preview_retention_item(session, asset_model)
            local_path = asset_model.local_path

        warnings = list(item.warnings)
        warnings.append(
            "Direct irreversible file deletion is retired; use Storage & Retention preview and recovery instead."
        )
        return SavedMediaCleanupResponse(
            media_asset_id=item.media_asset_id,
            status="rejected",
            risk_level=item.risk_level,
            media_state=item.media_state,
            file_deleted=False,
            record_deleted=False,
            creates_truth=False,
            deletes_truth=False,
            message=(
                "Direct file-only cleanup is no longer available. Preview a recoverable "
                "cleanup from Local Data instead."
            ),
            file_name=item.file_name,
            size_bytes=item.size_bytes,
            warnings=warnings,
        )

        if item.risk_level != "low" or item.media_state != "saved_unlinked":
            warnings.append(
                "Phase 12F cleanup is limited to low-risk unlinked saved preview media."
            )
            return SavedMediaCleanupResponse(
                media_asset_id=item.media_asset_id,
                status="rejected",
                risk_level=item.risk_level,
                media_state=item.media_state,
                file_deleted=False,
                record_deleted=False,
                creates_truth=False,
                deletes_truth=False,
                message=(
                    "Cleanup rejected. This MediaAsset is linked to evidence, "
                    "Event/Visit context, reviewed truth, or unknown retention state."
                ),
                file_name=item.file_name,
                size_bytes=item.size_bytes,
                warnings=warnings,
            )

        media_path, rejection_reason, path_warnings = self._safe_saved_preview_cleanup_path(
            local_path,
        )
        warnings.extend(path_warnings)
        if rejection_reason is not None or media_path is None:
            return SavedMediaCleanupResponse(
                media_asset_id=item.media_asset_id,
                status="rejected",
                risk_level=item.risk_level,
                media_state=item.media_state,
                file_deleted=False,
                record_deleted=False,
                creates_truth=False,
                deletes_truth=False,
                message=rejection_reason or "Cleanup rejected by path safety checks.",
                file_name=item.file_name,
                size_bytes=item.size_bytes,
                warnings=warnings,
            )

        if not media_path.exists():
            return SavedMediaCleanupResponse(
                media_asset_id=item.media_asset_id,
                status="already_missing",
                risk_level=item.risk_level,
                media_state=item.media_state,
                file_deleted=False,
                record_deleted=False,
                creates_truth=False,
                deletes_truth=False,
                message=(
                    "Local file was already missing. The MediaAsset record remains and "
                    "no truth was changed."
                ),
                file_name=item.file_name,
                size_bytes=item.size_bytes,
                warnings=warnings,
            )

        try:
            media_path.unlink()
        except OSError:
            warnings.append("Local file could not be deleted; no records were changed.")
            return SavedMediaCleanupResponse(
                media_asset_id=item.media_asset_id,
                status="rejected",
                risk_level=item.risk_level,
                media_state=item.media_state,
                file_deleted=False,
                record_deleted=False,
                creates_truth=False,
                deletes_truth=False,
                message="File-only cleanup failed before deleting the local file.",
                file_name=item.file_name,
                size_bytes=item.size_bytes,
                warnings=warnings,
            )

        return SavedMediaCleanupResponse(
            media_asset_id=item.media_asset_id,
            status="deleted_file",
            risk_level=item.risk_level,
            media_state=item.media_state,
            file_deleted=True,
            record_deleted=False,
            creates_truth=False,
            deletes_truth=False,
            message=(
                "Deleted the local saved preview file only. The MediaAsset record, "
                "evidence, Events, Visits, labels, exports, and truth remain unchanged."
            ),
            file_name=item.file_name,
            size_bytes=item.size_bytes,
            warnings=warnings,
        )

    def _safe_saved_preview_cleanup_path(
        self,
        local_path: str,
    ) -> tuple[Path | None, str | None, list[str]]:
        warnings: list[str] = []
        try:
            media_root = self.media_root.resolve()
            candidate = Path(local_path)
            if not candidate.is_absolute():
                candidate = self.media_root / candidate
            candidate = candidate.absolute()
            resolved_candidate = candidate.resolve(strict=False)
        except OSError:
            return (
                None,
                "Cleanup rejected because the local media path could not be resolved.",
                ["Local media path could not be resolved."],
            )

        if not resolved_candidate.is_relative_to(media_root):
            return (
                None,
                "Cleanup rejected because the local media path is outside the media root.",
                ["Local media path is outside the configured media root."],
            )

        for path_part in (candidate, *candidate.parents):
            if path_part == media_root:
                break
            if path_part.is_symlink():
                return (
                    None,
                    "Cleanup rejected because symlink media paths are not eligible.",
                    ["Local media path includes a symlink; file-only cleanup skipped."],
                )

        if candidate.exists() and candidate.is_dir():
            return (
                None,
                "Cleanup rejected because the local media path is a directory.",
                ["Local media path points to a directory; file-only cleanup skipped."],
            )

        if candidate.exists() and not candidate.is_file():
            return (
                None,
                "Cleanup rejected because the local media path is not a regular file.",
                ["Local media path is not a regular file; file-only cleanup skipped."],
            )

        return candidate, None, warnings

    def create_external_url_preview_media_asset(
        self,
        *,
        source_id: str,
        stream_id: str,
        content: bytes,
        content_type: str,
        fetched_at: datetime,
        url_host: str | None = None,
        note: str | None = None,
    ) -> MediaAsset:
        if not content:
            raise ValueError("empty_file")

        media_type = SUPPORTED_MEDIA_CONTENT_TYPES.get(content_type)
        extension = EXTERNAL_URL_PREVIEW_EXTENSIONS.get(content_type)
        if media_type != "image" or extension is None:
            raise ValueError("unsupported_content_type")

        with self.session_factory() as session:
            with session.begin():
                source_model = session.get(CameraSourceModel, source_id)
                if source_model is None:
                    raise ValueError("missing_source")

                stream_model = session.get(StreamModel, stream_id)
                if stream_model is None:
                    raise ValueError("missing_stream")
                if stream_model.source_id != source_id:
                    raise ValueError("stream_source_mismatch")

                media_id = self._next_id(session, MediaAssetModel, "media-asset")
                original_filename = f"external-url-preview-{media_id}{extension}"
                filename = f"{media_id}-external-url-preview{extension}"
                filename, local_path = self._write_media_file(filename, content)
                notes = self._external_url_preview_media_notes(
                    source_id=source_id,
                    stream_id=stream_id,
                    fetched_at=fetched_at,
                    content_type=content_type,
                    bytes_written=len(content),
                    url_host=url_host,
                    note=note,
                )
                asset_model = MediaAssetModel(
                    id=media_id,
                    source_id=source_id,
                    stream_id=stream_id,
                    filename=filename,
                    content_type=content_type,
                    media_type=media_type,
                    local_path=str(local_path),
                    original_filename=original_filename,
                    file_size_bytes=len(content),
                    created_at=fetched_at,
                    notes=notes,
                )
                session.add(asset_model)
                session.flush()
                return _media_asset_from_model(asset_model)

