    def create_motion_evidence_from_saved_media(
        self,
        media_asset_id: str,
        payload: SavedPreviewMotionEvidenceRequest,
    ) -> _SavedMediaMotionEvidenceResult:
        media_id = media_asset_id.strip()
        if not media_id:
            raise ValueError("missing_media_asset")
        duplicate_policy = _clean_optional_text(payload.duplicate_policy) or "skip_existing"
        if duplicate_policy not in {"skip_existing", "allow_duplicate"}:
            raise ValueError("unsupported_duplicate_policy")

        with self.session_factory() as session:
            with session.begin():
                asset_model = session.get(MediaAssetModel, media_id)
                if asset_model is None:
                    raise ValueError("missing_media_asset")
                if (
                    asset_model.media_type != "image"
                    or asset_model.content_type not in EXTERNAL_URL_PREVIEW_EXTENSIONS
                ):
                    raise ValueError("unsupported_motion_evidence_media_type")
                if not Path(asset_model.local_path).is_file():
                    raise ValueError("missing_media_file")

                stream_id = _clean_optional_text(payload.stream_id) or asset_model.stream_id
                stream_model = session.get(StreamModel, stream_id)
                if stream_model is None:
                    raise ValueError("missing_stream")
                if asset_model.stream_id != stream_model.id:
                    raise ValueError("media_stream_mismatch")

                source_id = asset_model.source_id or stream_model.source_id
                source_model = session.get(CameraSourceModel, source_id)
                if source_model is None:
                    raise ValueError("missing_source")
                if stream_model.source_id != source_id:
                    raise ValueError("stream_source_mismatch")

                provenance_kind = _media_asset_motion_evidence_provenance_kind(asset_model)
                warnings: list[str] = []
                zone_id = _clean_optional_text(payload.zone_id)
                if zone_id is not None:
                    zone_model = session.get(ZoneModel, zone_id)
                    if zone_model is None:
                        raise ValueError("missing_zone")
                    if zone_model.stream_id != stream_model.id:
                        raise ValueError("zone_stream_mismatch")
                    if zone_model.zone_type in {
                        ZoneType.privacy.value,
                        ZoneType.ignore.value,
                    }:
                        raise ValueError("motion_evidence_creation_zone_blocked")
                else:
                    zone_model = next(
                        (
                            zone
                            for zone in session.scalars(
                                select(ZoneModel)
                                .where(
                                    ZoneModel.stream_id == stream_model.id,
                                    ZoneModel.is_active.is_(True),
                                )
                                .order_by(ZoneModel.id)
                            ).all()
                            if zone.zone_type
                            not in {
                                ZoneType.privacy.value,
                                ZoneType.ignore.value,
                            }
                        ),
                        None,
                    )
                    if zone_model is None:
                        raise ValueError("missing_reviewable_zone")
                    warnings.append(
                        "No zone was supplied; MockingBird used the first active "
                        "reviewable zone for this stream."
                    )

                existing_evidence = session.scalars(
                    select(MotionEvidenceModel)
                    .where(
                        MotionEvidenceModel.snapshot_media_asset_id == media_id,
                        MotionEvidenceModel.status.in_(
                            [
                                MotionEvidenceStatus.pending.value,
                                MotionEvidenceStatus.promoted.value,
                                MotionEvidenceStatus.ignored.value,
                            ]
                        ),
                    )
                    .order_by(MotionEvidenceModel.created_at, MotionEvidenceModel.id)
                ).first()
                if existing_evidence is not None and duplicate_policy == "skip_existing":
                    warnings.append(
                        "Existing MotionEvidence already references this MediaAsset; "
                        "no duplicate pending evidence was created."
                    )
                    return _SavedMediaMotionEvidenceResult(
                        evidence=_motion_evidence_from_model(existing_evidence),
                        warnings=warnings,
                        duplicate_skipped=True,
                        existing_motion_evidence_id=existing_evidence.id,
                        provenance_kind=provenance_kind,
                    )

                scoring_source = {
                    "external_url_preview": "saved_preview_media_asset",
                    "folder_import": "folder_import_media_asset",
                }.get(provenance_kind, "media_asset")
                source_label = {
                    "external_url_preview": "saved MediaAsset",
                    "folder_import": "folder-imported MediaAsset",
                }.get(provenance_kind, "MediaAsset")
                note_parts = [
                    f"Created from {source_label} {media_id} by explicit user action.",
                    "No Events, Visits, ReviewLabels, or truth were created.",
                ]
                reason = _clean_optional_text(payload.reason)
                if reason is not None:
                    note_parts.append(f"Reason: {reason}")
                note = _clean_optional_text(payload.note)
                if note is not None:
                    note_parts.append(f"Note: {note}")

                evidence_model = MotionEvidenceModel(
                    id=self._next_id(session, MotionEvidenceModel, "motion-evidence"),
                    source_id=source_id,
                    stream_id=stream_model.id,
                    zone_id=zone_model.id,
                    start_frame_index=None,
                    end_frame_index=None,
                    best_frame_index=None,
                    start_time=None,
                    end_time=None,
                    best_frame_time=None,
                    peak_changed_ratio=0.0,
                    triggered_frame_count=1,
                    scoring_config_json=json.dumps(
                        {
                            "source": scoring_source,
                            "media_asset_id": media_id,
                            "motion_score_available": False,
                            "requires_review": True,
                        },
                        sort_keys=True,
                    ),
                    snapshot_media_asset_id=media_id,
                    status=MotionEvidenceStatus.pending.value,
                    promoted_event_id=None,
                    promoted_visit_id=None,
                    created_at=datetime.now(UTC),
                    notes="\n".join(note_parts),
                )
                session.add(evidence_model)
                session.flush()
                return _SavedMediaMotionEvidenceResult(
                    evidence=_motion_evidence_from_model(evidence_model),
                    warnings=warnings,
                    provenance_kind=provenance_kind,
                )

    def bulk_create_motion_evidence_from_saved_media(
        self,
        payload: SavedMediaBulkMotionEvidenceRequest,
    ) -> SavedMediaBulkMotionEvidenceResponse:
        results: list[SavedMediaBulkMotionEvidenceResult] = []
        seen_media_ids: set[str] = set()

        for raw_media_id in payload.media_asset_ids:
            media_id = raw_media_id.strip()
            if not media_id:
                results.append(
                    SavedMediaBulkMotionEvidenceResult(
                        media_asset_id=media_id,
                        status=MotionEvidenceBulkActionResultStatus.skipped,
                        message="MediaAsset id is required.",
                    )
                )
                continue
            if media_id in seen_media_ids:
                results.append(
                    SavedMediaBulkMotionEvidenceResult(
                        media_asset_id=media_id,
                        status=MotionEvidenceBulkActionResultStatus.skipped,
                        message=(
                            "Duplicate MediaAsset id in request; only the first "
                            "occurrence was processed."
                        ),
                    )
                )
                continue
            seen_media_ids.add(media_id)

            try:
                result = self.create_motion_evidence_from_saved_media(
                    media_id,
                    SavedPreviewMotionEvidenceRequest(),
                )
            except ValueError as error:
                results.append(
                    SavedMediaBulkMotionEvidenceResult(
                        media_asset_id=media_id,
                        status=MotionEvidenceBulkActionResultStatus.skipped,
                        message=_saved_media_motion_evidence_skip_message(str(error)),
                    )
                )
                continue

            if result.duplicate_skipped:
                results.append(
                    SavedMediaBulkMotionEvidenceResult(
                        media_asset_id=media_id,
                        status=MotionEvidenceBulkActionResultStatus.skipped,
                        message=(
                            "Existing MotionEvidence already references this media. "
                            "No duplicate evidence was created."
                        ),
                        created_motion_evidence_id=None,
                    )
                )
                continue

            results.append(
                SavedMediaBulkMotionEvidenceResult(
                    media_asset_id=media_id,
                    status=MotionEvidenceBulkActionResultStatus.succeeded,
                    message=(
                        "Created pending MotionEvidence from media. "
                        "No Events, Visits, labels, or truth were created."
                    ),
                    created_motion_evidence_id=result.evidence.id,
                )
            )

        return SavedMediaBulkMotionEvidenceResponse(
            requested_count=len(payload.media_asset_ids),
            succeeded_count=sum(
                1
                for result in results
                if result.status == MotionEvidenceBulkActionResultStatus.succeeded
            ),
            skipped_count=sum(
                1
                for result in results
                if result.status == MotionEvidenceBulkActionResultStatus.skipped
            ),
            failed_count=sum(
                1
                for result in results
                if result.status == MotionEvidenceBulkActionResultStatus.failed
            ),
            results=results,
        )

    def dry_run_folder_import_evidence_batch(
        self,
        payload: FolderImportEvidenceBatchDryRunRequest,
    ) -> FolderImportEvidenceBatchDryRunResponse:
        media_asset_ids = [
            media_asset_id.strip()
            for media_asset_id in (payload.media_asset_ids or [])
            if media_asset_id and media_asset_id.strip()
        ]
        source_id = _clean_optional_text(payload.source_id)
        stream_id = _clean_optional_text(payload.stream_id)
        zone_id = _clean_optional_text(payload.zone_id)
        duplicate_policy = _clean_optional_text(payload.duplicate_policy) or "skip_existing"
        if duplicate_policy not in {"skip_existing", "allow_duplicate"}:
            raise ValueError("unsupported_duplicate_policy")
        if not media_asset_ids and source_id is None and stream_id is None:
            raise ValueError("batch_dry_run_requires_selection")

        max_items = payload.max_items or 100
        warnings: list[str] = []
        if max_items > 500:
            max_items = 500
            warnings.append("max_items was capped at 500.")

        items: list[FolderImportEvidenceBatchDryRunItem] = []
        with self.session_factory() as session:
            if source_id is not None and session.get(CameraSourceModel, source_id) is None:
                raise ValueError("missing_source")
            if stream_id is not None:
                stream_model = session.get(StreamModel, stream_id)
                if stream_model is None:
                    raise ValueError("missing_stream")
                if source_id is not None and stream_model.source_id != source_id:
                    raise ValueError("stream_source_mismatch")

            if media_asset_ids:
                evaluation_ids = media_asset_ids[:max_items]
                overflow_ids = media_asset_ids[max_items:]
                if overflow_ids:
                    warnings.append(f"Dry run truncated at {max_items} items.")

                for media_asset_id in evaluation_ids:
                    items.append(
                        self._folder_import_evidence_batch_dry_run_item(
                            session,
                            media_asset_id=media_asset_id,
                            asset_model=session.get(MediaAssetModel, media_asset_id),
                            requested_source_id=source_id,
                            requested_stream_id=stream_id,
                            requested_zone_id=zone_id,
                            duplicate_policy=duplicate_policy,
                        )
                    )
                for media_asset_id in overflow_ids:
                    items.append(
                        FolderImportEvidenceBatchDryRunItem(
                            media_asset_id=media_asset_id,
                            eligible=False,
                            would_create_motion_evidence=False,
                            skip_reason="max_items_exceeded",
                            warnings=["Dry run max_items limit skipped this MediaAsset."],
                        )
                    )
            else:
                query = select(MediaAssetModel).order_by(
                    MediaAssetModel.created_at,
                    MediaAssetModel.id,
                )
                if source_id is not None:
                    query = query.where(MediaAssetModel.source_id == source_id)
                if stream_id is not None:
                    query = query.where(MediaAssetModel.stream_id == stream_id)

                folder_assets = [
                    asset_model
                    for asset_model in session.scalars(query).all()
                    if _is_folder_import_media_asset(asset_model)
                ]
                if len(folder_assets) > max_items:
                    warnings.append(f"Dry run truncated at {max_items} items.")
                for asset_model in folder_assets[:max_items]:
                    items.append(
                        self._folder_import_evidence_batch_dry_run_item(
                            session,
                            media_asset_id=asset_model.id,
                            asset_model=asset_model,
                            requested_source_id=source_id,
                            requested_stream_id=stream_id,
                            requested_zone_id=zone_id,
                            duplicate_policy=duplicate_policy,
                        )
                    )

        eligible_count = sum(1 for item in items if item.eligible)
        would_create_count = sum(1 for item in items if item.would_create_motion_evidence)
        duplicate_skipped_count = sum(1 for item in items if item.duplicate_skipped)
        return FolderImportEvidenceBatchDryRunResponse(
            items=items,
            total_items=len(items),
            eligible_count=eligible_count,
            would_create_count=would_create_count,
            duplicate_skipped_count=duplicate_skipped_count,
            skipped_count=len(items) - would_create_count,
            dry_run=True,
            creates_motion_evidence=False,
            creates_events=False,
            creates_visits=False,
            creates_truth=False,
            warnings=warnings,
        )

    def create_folder_import_evidence_batch(
        self,
        payload: FolderImportEvidenceBatchCreateRequest,
    ) -> FolderImportEvidenceBatchCreateResponse:
        if not payload.confirm:
            raise ValueError("batch_create_requires_confirmation")

        duplicate_policy = _clean_optional_text(payload.duplicate_policy) or "skip_existing"
        if duplicate_policy not in {"skip_existing", "allow_duplicate"}:
            raise ValueError("unsupported_duplicate_policy")

        dry_run = self.dry_run_folder_import_evidence_batch(
            FolderImportEvidenceBatchDryRunRequest(
                media_asset_ids=payload.media_asset_ids,
                source_id=payload.source_id,
                stream_id=payload.stream_id,
                zone_id=payload.zone_id,
                duplicate_policy=duplicate_policy,
                max_items=payload.max_items,
            )
        )

        items: list[FolderImportEvidenceBatchCreateItem] = []
        for dry_run_item in dry_run.items:
            if not dry_run_item.would_create_motion_evidence:
                items.append(
                    FolderImportEvidenceBatchCreateItem(
                        media_asset_id=dry_run_item.media_asset_id,
                        motion_evidence_id=None,
                        source_id=dry_run_item.source_id,
                        stream_id=dry_run_item.stream_id,
                        zone_id=dry_run_item.zone_id,
                        created=False,
                        duplicate_skipped=dry_run_item.duplicate_skipped,
                        existing_motion_evidence_id=dry_run_item.existing_motion_evidence_id,
                        skip_reason=dry_run_item.skip_reason,
                        warnings=dry_run_item.warnings,
                    )
                )
                continue

            result = self.create_motion_evidence_from_saved_media(
                dry_run_item.media_asset_id,
                SavedPreviewMotionEvidenceRequest(
                    stream_id=dry_run_item.stream_id,
                    zone_id=dry_run_item.zone_id,
                    note=payload.note,
                    reason=payload.reason,
                    duplicate_policy=duplicate_policy,
                ),
            )
            warnings = _unique_strings([*dry_run_item.warnings, *result.warnings])
            items.append(
                FolderImportEvidenceBatchCreateItem(
                    media_asset_id=dry_run_item.media_asset_id,
                    motion_evidence_id=(
                        None if result.duplicate_skipped else result.evidence.id
                    ),
                    source_id=result.evidence.source_id,
                    stream_id=result.evidence.stream_id,
                    zone_id=result.evidence.zone_id,
                    created=not result.duplicate_skipped,
                    duplicate_skipped=result.duplicate_skipped,
                    existing_motion_evidence_id=result.existing_motion_evidence_id,
                    skip_reason="duplicate_evidence" if result.duplicate_skipped else None,
                    warnings=warnings,
                )
            )

        created_count = sum(1 for item in items if item.created)
        duplicate_skipped_count = sum(1 for item in items if item.duplicate_skipped)
        return FolderImportEvidenceBatchCreateResponse(
            items=items,
            total_items=len(items),
            created_count=created_count,
            skipped_count=len(items) - created_count,
            duplicate_skipped_count=duplicate_skipped_count,
            creates_motion_evidence=created_count > 0,
            creates_events=False,
            creates_visits=False,
            creates_truth=False,
            message=(
                "Created pending MotionEvidence from eligible folder-imported media. "
                "No Events, Visits, labels, or truth were created."
                if created_count > 0
                else (
                    "No pending MotionEvidence was created. "
                    "No Events, Visits, labels, or truth were created."
                )
            ),
            warnings=dry_run.warnings,
        )

    def _folder_import_evidence_batch_dry_run_item(
        self,
        session: Session,
        *,
        media_asset_id: str,
        asset_model: MediaAssetModel | None,
        requested_source_id: str | None,
        requested_stream_id: str | None,
        requested_zone_id: str | None,
        duplicate_policy: str,
    ) -> FolderImportEvidenceBatchDryRunItem:
        source_id = asset_model.source_id if asset_model else requested_source_id
        stream_id = asset_model.stream_id if asset_model else requested_stream_id
        file_name = (
            asset_model.original_filename or asset_model.filename
            if asset_model is not None
            else None
        )

        def skipped(
            skip_reason: str,
            *,
            item_source_id: str | None = source_id,
            item_stream_id: str | None = stream_id,
            item_zone_id: str | None = requested_zone_id,
            item_warnings: list[str] | None = None,
            duplicate_skipped: bool = False,
            existing_motion_evidence_id: str | None = None,
        ) -> FolderImportEvidenceBatchDryRunItem:
            return FolderImportEvidenceBatchDryRunItem(
                media_asset_id=media_asset_id,
                source_id=item_source_id,
                stream_id=item_stream_id,
                zone_id=item_zone_id,
                file_name=file_name,
                eligible=False,
                would_create_motion_evidence=False,
                duplicate_skipped=duplicate_skipped,
                existing_motion_evidence_id=existing_motion_evidence_id,
                skip_reason=skip_reason,
                warnings=item_warnings or [],
            )

        if asset_model is None:
            return skipped(
                "unknown_media_asset",
                item_source_id=None,
                item_stream_id=None,
                item_zone_id=None,
                item_warnings=["MediaAsset was not found."],
            )
        if not _is_folder_import_media_asset(asset_model):
            return skipped(
                "not_folder_import_media",
                item_warnings=["MediaAsset was not created by folder import."],
            )
        if (
            asset_model.media_type != "image"
            or asset_model.content_type not in EXTERNAL_URL_PREVIEW_EXTENSIONS
        ):
            return skipped(
                "unsupported_media_type",
                item_warnings=["Only folder-imported still-image MediaAssets are eligible."],
            )
        if not Path(asset_model.local_path).is_file():
            return skipped(
                "missing_local_file",
                item_warnings=["Local media file was not found."],
            )

        stream_id = requested_stream_id or asset_model.stream_id
        if stream_id is None:
            return skipped("missing_stream_context", item_stream_id=None)
        stream_model = session.get(StreamModel, stream_id)
        if stream_model is None:
            return skipped("missing_stream_context", item_stream_id=stream_id)
        if asset_model.stream_id != stream_model.id:
            return skipped("stream_source_mismatch", item_stream_id=stream_model.id)

        source_id = asset_model.source_id or stream_model.source_id
        if requested_source_id is not None and source_id != requested_source_id:
            return skipped("stream_source_mismatch", item_source_id=source_id)
        if stream_model.source_id != source_id:
            return skipped("stream_source_mismatch", item_source_id=source_id)

        warnings: list[str] = []
        if requested_zone_id is not None:
            zone_model = session.get(ZoneModel, requested_zone_id)
            if zone_model is None or zone_model.stream_id != stream_model.id:
                return skipped(
                    "invalid_zone",
                    item_source_id=source_id,
                    item_stream_id=stream_model.id,
                    item_zone_id=requested_zone_id,
                )
            if zone_model.zone_type == ZoneType.privacy.value:
                return skipped(
                    "privacy_zone",
                    item_source_id=source_id,
                    item_stream_id=stream_model.id,
                    item_zone_id=zone_model.id,
                )
            if zone_model.zone_type == ZoneType.ignore.value:
                return skipped(
                    "ignore_zone",
                    item_source_id=source_id,
                    item_stream_id=stream_model.id,
                    item_zone_id=zone_model.id,
                )
        else:
            zone_model = next(
                (
                    zone
                    for zone in session.scalars(
                        select(ZoneModel)
                        .where(
                            ZoneModel.stream_id == stream_model.id,
                            ZoneModel.is_active.is_(True),
                        )
                        .order_by(ZoneModel.id)
                    ).all()
                    if zone.zone_type
                    not in {
                        ZoneType.privacy.value,
                        ZoneType.ignore.value,
                    }
                ),
                None,
            )
            if zone_model is None:
                return skipped(
                    "insufficient_context",
                    item_source_id=source_id,
                    item_stream_id=stream_model.id,
                    item_zone_id=None,
                )
            warnings.append(
                "No zone was supplied; MockingBird used the first active "
                "reviewable zone for this stream."
            )

        existing_evidence = session.scalars(
            select(MotionEvidenceModel)
            .where(
                MotionEvidenceModel.snapshot_media_asset_id == media_asset_id,
                MotionEvidenceModel.status.in_(
                    [
                        MotionEvidenceStatus.pending.value,
                        MotionEvidenceStatus.promoted.value,
                        MotionEvidenceStatus.ignored.value,
                    ]
                ),
            )
            .order_by(MotionEvidenceModel.created_at, MotionEvidenceModel.id)
        ).first()
        if existing_evidence is not None:
            if duplicate_policy == "skip_existing":
                return skipped(
                    "duplicate_evidence",
                    item_source_id=source_id,
                    item_stream_id=stream_model.id,
                    item_zone_id=zone_model.id,
                    item_warnings=[
                        "Existing MotionEvidence already references this MediaAsset; "
                        "no duplicate pending evidence would be created."
                    ],
                    duplicate_skipped=True,
                    existing_motion_evidence_id=existing_evidence.id,
                )
            warnings.append(
                "Existing MotionEvidence already references this MediaAsset; "
                "duplicate creation would be allowed by policy."
            )

        return FolderImportEvidenceBatchDryRunItem(
            media_asset_id=media_asset_id,
            source_id=source_id,
            stream_id=stream_model.id,
            zone_id=zone_model.id,
            file_name=file_name,
            eligible=True,
            would_create_motion_evidence=True,
            duplicate_skipped=False,
            existing_motion_evidence_id=(
                existing_evidence.id if existing_evidence is not None else None
            ),
            skip_reason=None,
            warnings=warnings,
        )

    def create_motion_evidence(
        self,
        payload: MotionEvidenceCreateRequest,
    ) -> MotionEvidenceResponse:
        with self.session_factory() as session:
            with session.begin():
                requested_zone_id = _clean_optional_text(payload.zone_id)
                zone_model = (
                    session.get(ZoneModel, requested_zone_id)
                    if requested_zone_id is not None
                    else None
                )
                if requested_zone_id is not None and zone_model is None:
                    raise ValueError("missing_zone")

                stream_id = _clean_optional_text(payload.stream_id) or (
                    zone_model.stream_id if zone_model is not None else None
                )
                if stream_id is None:
                    raise ValueError("missing_stream")
                stream_model = session.get(StreamModel, stream_id)
                if stream_model is None:
                    raise ValueError("missing_stream")
                if zone_model is not None and zone_model.stream_id != stream_model.id:
                    raise ValueError("zone_stream_mismatch")

                source_id = payload.source_id or stream_model.source_id
                if source_id is not None:
                    source_model = session.get(CameraSourceModel, source_id)
                    if source_model is None:
                        raise ValueError("missing_source")
                    if stream_model.source_id != source_id:
                        raise ValueError("stream_source_mismatch")

                snapshot_media_asset_id = (
                    payload.snapshot_media_asset_id.strip()
                    if payload.snapshot_media_asset_id and payload.snapshot_media_asset_id.strip()
                    else None
                )
                if snapshot_media_asset_id is not None:
                    asset_model = session.get(MediaAssetModel, snapshot_media_asset_id)
                    if asset_model is None:
                        raise ValueError("missing_media_asset")
                    if asset_model.stream_id != stream_model.id:
                        raise ValueError("media_stream_mismatch")

                evidence_model = MotionEvidenceModel(
                    id=self._next_id(session, MotionEvidenceModel, "motion-evidence"),
                    source_id=source_id,
                    stream_id=stream_model.id,
                    zone_id=zone_model.id if zone_model is not None else None,
                    start_frame_index=payload.start_frame_index,
                    end_frame_index=payload.end_frame_index,
                    best_frame_index=payload.best_frame_index,
                    start_time=payload.start_time.strip() if payload.start_time else None,
                    end_time=payload.end_time.strip() if payload.end_time else None,
                    best_frame_time=(
                        payload.best_frame_time.strip() if payload.best_frame_time else None
                    ),
                    peak_changed_ratio=payload.peak_changed_ratio,
                    triggered_frame_count=payload.triggered_frame_count,
                    scoring_config_json=json.dumps(payload.scoring_config, sort_keys=True),
                    snapshot_media_asset_id=snapshot_media_asset_id,
                    status=MotionEvidenceStatus.pending.value,
                    promoted_event_id=None,
                    promoted_visit_id=None,
                    created_at=datetime.now(UTC),
                    notes=payload.notes.strip() if payload.notes and payload.notes.strip() else None,
                )
                session.add(evidence_model)
                session.flush()
                return _motion_evidence_from_model(evidence_model)

    def list_motion_evidence(
        self,
        *,
        status: MotionEvidenceStatus | None = None,
        zone_id: str | None = None,
        stream_id: str | None = None,
    ) -> list[MotionEvidenceResponse]:
        with self.session_factory() as session:
            query = select(MotionEvidenceModel)
            if status is not None:
                query = query.where(MotionEvidenceModel.status == status.value)
            if zone_id is not None:
                query = query.where(MotionEvidenceModel.zone_id == zone_id)
            if stream_id is not None:
                query = query.where(MotionEvidenceModel.stream_id == stream_id)
            evidence_models = session.scalars(
                query.order_by(MotionEvidenceModel.created_at, MotionEvidenceModel.id)
            ).all()
            return [_motion_evidence_from_model(evidence) for evidence in evidence_models]

    def get_motion_evidence(self, evidence_id: str) -> MotionEvidenceResponse | None:
        with self.session_factory() as session:
            evidence_model = session.get(MotionEvidenceModel, evidence_id)
            return _motion_evidence_from_model(evidence_model) if evidence_model else None

    def motion_evidence_for_event(self, event_id: str) -> MotionEvidenceResponse | None:
        with self.session_factory() as session:
            evidence_model = session.scalars(
                select(MotionEvidenceModel)
                .where(MotionEvidenceModel.promoted_event_id == event_id)
                .order_by(MotionEvidenceModel.created_at, MotionEvidenceModel.id)
            ).first()
            return _motion_evidence_from_model(evidence_model) if evidence_model else None

    def motion_evidence_for_visit(self, visit_id: str) -> MotionEvidenceResponse | None:
        with self.session_factory() as session:
            evidence_model = session.scalars(
                select(MotionEvidenceModel)
                .where(MotionEvidenceModel.promoted_visit_id == visit_id)
                .order_by(MotionEvidenceModel.created_at, MotionEvidenceModel.id)
            ).first()
            return _motion_evidence_from_model(evidence_model) if evidence_model else None

    def visit_evidence_frames(self, visit_id: str) -> list[VisitEvidenceFrame]:
        """Return bounded evidence, retaining a legacy Visit's primary image when present."""

        with self.session_factory() as session:
            visit = session.get(VisitModel, visit_id)
            if visit is None:
                return []
            event = session.get(EventModel, visit.event_id)
            if event is None:
                return []
            return self._visit_evidence_frames_from_visit(session, visit, event)

    def effective_primary_preview(self, visit_id: str) -> dict[str, Any] | None:
        """Read-only recommendation; never rewrites historical evidence links."""
        with self.session_factory() as session:
            visit = session.get(VisitModel, visit_id)
            if visit is None:
                return None
            event = session.get(EventModel, visit.event_id)
            if event is None:
                return None
            return self._effective_primary_preview_from_visit(session, visit)

    def _effective_primary_preview_from_visit(
        self,
        session: Session,
        visit: VisitModel,
    ) -> dict[str, Any] | None:
        """Build a bounded presentation preview inside an existing read session."""

        # Same-Frame Species Evidence v1 (see docs/same-frame-species-
        # evidence-contract.md): a `classifier_same_frame` asset is
        # diagnostic/classifier-input evidence only -- excluded here before
        # the bounded top-4 truncation below so it can neither occupy one of
        # those 4 slots nor ever be recommended as the effective primary
        # (see "Do not promote the classifier crop to canonical Visit
        # image").
        links = [
            link for link in self._visit_evidence_link_models(session, visit.id)
            if link.evidence_role != CLASSIFIER_SAME_FRAME_EVIDENCE_ROLE
        ][:4]
        if not links:
            return None
        dimensions = self._visit_evidence_dimensions_from_motion_evidence(session, visit.id)
        items: list[EvidenceCandidate] = []
        persisted: str | None = None
        for link in links:
            asset = session.get(MediaAssetModel, link.media_asset_id)
            if asset is None:
                continue
            if link.is_primary:
                persisted = asset.id
            width, height = dimensions.get(
                asset.id,
                (asset.image_width, asset.image_height),
            )
            items.append(
                EvidenceCandidate(
                    asset.id,
                    link.evidence_role or asset.evidence_role or "monitoring_frame",
                    _as_utc(link.captured_at),
                    width,
                    height,
                    _normalized_box_from_json(asset.normalized_track_box_json),
                    _normalized_box_from_json(asset.normalized_padded_crop_box_json),
                    asset.alignment_status,
                    available=Path(asset.local_path).is_file(),
                    track_supported=(link.evidence_role == "tracked_best_frame"),
                    lineage_valid=(
                        asset.parent_media_asset_id is not None
                        if link.evidence_role == "activity_crop"
                        else None
                    ),
                )
            )
        choice = select_effective_primary(items)
        selected = choice.media_asset_id or persisted
        selected_item = next(
            (item for item in items if item.media_asset_id == selected),
            None,
        )
        role = selected_item.role if selected_item is not None else None
        return {
            "selected_media_asset_id": selected,
            "persisted_primary_media_asset_id": persisted,
            "recommended_effective_primary_media_asset_id": choice.media_asset_id,
            "evidence_role": role,
            "selection_reason": choice.reason,
            "is_useful": (
                choice.media_asset_id is not None
                and choice.reason != "no_useful_primary_evidence"
            ),
            "is_user_controlled": choice.reason in {
                "user_selected_primary",
                "user_refined_primary",
            },
            "temporally_supported": choice.temporally_supported,
            "temporal_status": (
                "supported"
                if choice.temporally_supported is True
                else "rejected"
                if choice.temporally_supported is False
                else "uncertain"
            ),
            "containment_status": choice.contained,
            "edge_clipped": choice.edge_clipped,
            "width": selected_item.width if selected_item is not None else None,
            "height": selected_item.height if selected_item is not None else None,
            "candidate_count": len(items),
            "historical_preview_only": choice.media_asset_id != persisted,
            "would_change_automatically": (
                choice.media_asset_id is not None and choice.media_asset_id != persisted
            ),
        }

    def _visit_evidence_dimensions_from_motion_evidence(
        self,
        session: Session,
        visit_id: str,
    ) -> dict[str, tuple[int | None, int | None]]:
        """Reuse retained activity-frame dimensions without reading media files."""

        evidence = self._motion_evidence_model_for_visit(session, visit_id)
        if evidence is None:
            return {}
        try:
            frames = json.loads(evidence.scoring_config_json).get("visit_evidence_frames", [])
        except (TypeError, ValueError, json.JSONDecodeError):
            return {}
        if not isinstance(frames, list):
            return {}
        dimensions: dict[str, tuple[int | None, int | None]] = {}
        for frame in frames:
            if not isinstance(frame, dict) or not isinstance(frame.get("media_asset_id"), str):
                continue
            width = frame.get("width")
            height = frame.get("height")
            dimensions[frame["media_asset_id"]] = (
                width if isinstance(width, int) and width > 0 else None,
                height if isinstance(height, int) and height > 0 else None,
            )
        return dimensions

    def attach_visit_evidence_media_assets(
        self,
        visit_id: str,
        frames: Iterable[dict[str, Any]],
    ) -> list[VisitEvidenceFrame]:
        """Attach one bounded, already-persisted evidence set to a new Visit.

        This is deliberately narrower than reviewer curation: it establishes the
        initial evidence relationship during pending-motion promotion and cannot
        create labels, corrections, or any review truth.
        """

        requested = list(frames)
        if not requested or len(requested) > MAX_LIVE_VISIT_EVIDENCE_FRAMES:
            raise ValueError("invalid_visit_evidence_selection")
        with self.session_factory() as session:
            with session.begin():
                visit, event = self._require_active_visit(session, visit_id)
                existing = self._visit_evidence_link_models(session, visit.id)
                if existing:
                    return self._visit_evidence_frames_from_links(
                        session,
                        visit=visit,
                        event=event,
                        links=existing,
                    )

                parsed: list[tuple[MediaAssetModel, datetime, int | None, str, bool]] = []
                seen_media_ids: set[str] = set()
                primary_count = 0
                for raw in requested:
                    media_asset_id = _optional_string(raw.get("media_asset_id"))
                    captured_at = _optional_datetime(raw.get("captured_at"))
                    role = _optional_string(raw.get("evidence_role")) or "monitoring_frame"
                    is_primary = bool(raw.get("is_primary"))
                    if (
                        media_asset_id is None
                        or captured_at is None
                        or media_asset_id in seen_media_ids
                        or not re.fullmatch(r"[a-z_]{1,64}", role)
                    ):
                        raise ValueError("invalid_visit_evidence_selection")
                    asset = session.get(MediaAssetModel, media_asset_id)
                    if asset is None or asset.stream_id != event.stream_id:
                        raise ValueError("media_stream_mismatch")
                    seen_media_ids.add(media_asset_id)
                    primary_count += int(is_primary)
                    parsed.append(
                        (
                            asset,
                            captured_at,
                            _optional_int(raw.get("frame_sequence")),
                            role,
                            is_primary,
                        )
                    )
                if primary_count != 1:
                    raise ValueError("invalid_visit_evidence_selection")

                # Initial primary choice is evidence presentation, not truth or
                # curation. Existing links are never revisited here; reviewers
                # retain the established explicit primary-selection flow.
                support_times = [
                    asset.trigger_started_at
                    for asset, *_ in parsed
                    if asset.trigger_started_at is not None
                ]
                selection = select_effective_primary(
                    [EvidenceCandidate(
                        media_asset_id=asset.id,
                        role=role,
                        captured_at=captured_at,
                        width=asset.image_width,
                        height=asset.image_height,
                        track_box=_normalized_box_from_json(asset.normalized_track_box_json),
                        crop_box=_normalized_box_from_json(asset.normalized_padded_crop_box_json),
                        alignment_status=asset.alignment_status,
                        user_refined=role == "user_refined_crop",
                    ) for asset, captured_at, _sequence, role, _is_primary in parsed],
                    support_start=min(support_times) if support_times else None,
                    support_end=max(support_times) if support_times else None,
                )
                if selection.media_asset_id is not None:
                    parsed = [(*entry[:-1], entry[0].id == selection.media_asset_id) for entry in parsed]

                created_at = datetime.now(UTC)
                primary_asset: MediaAssetModel | None = None
                for sort_order, (asset, captured_at, frame_sequence, role, is_primary) in enumerate(parsed):
                    session.add(
                        VisitEvidenceLinkModel(
                            id=f"visit-evidence-{uuid.uuid4().hex}",
                            visit_id=visit.id,
                            media_asset_id=asset.id,
                            captured_at=captured_at,
                            frame_sequence=frame_sequence,
                            sort_order=sort_order,
                            is_primary=is_primary,
                            evidence_role=role,
                            created_at=created_at,
                        )
                    )
                    if is_primary:
                        primary_asset = asset
                if primary_asset is not None:
                    visit.representative_media_path = primary_asset.local_path
                session.flush()
                return self._visit_evidence_frames_from_visit(session, visit, event)

    def _visit_evidence_link_models(
        self,
        session: Session,
        visit_id: str,
    ) -> list[VisitEvidenceLinkModel]:
        return list(
            session.scalars(
                select(VisitEvidenceLinkModel)
                .where(VisitEvidenceLinkModel.visit_id == visit_id)
                .order_by(
                    VisitEvidenceLinkModel.captured_at,
                    VisitEvidenceLinkModel.frame_sequence,
                    VisitEvidenceLinkModel.sort_order,
                    VisitEvidenceLinkModel.id,
                )
            ).all()
        )

    def _visit_evidence_frames_from_links(
        self,
        session: Session,
        *,
        visit: VisitModel,
        event: EventModel,
        links: list[VisitEvidenceLinkModel],
    ) -> list[VisitEvidenceFrame]:
        parsed: list[tuple[VisitEvidenceLinkModel, MediaAssetModel]] = []
        seen_media_ids: set[str] = set()
        # Same-Frame Species Evidence v1 (see docs/same-frame-species-
        # evidence-contract.md): excluded from every human-facing evidence
        # gallery/API listing this shared function serves, before the
        # bounded `MAX_LIVE_VISIT_EVIDENCE_FRAMES` truncation below -- it is
        # supporting classifier/diagnostic evidence, never a browsable Visit
        # image (see "Do not promote the classifier crop to canonical Visit
        # image"). Still fully queryable directly by evidence_role for
        # diagnostics/species inference (see `_classifier_same_frame_asset_
        # for_visit`), just never surfaced here.
        links = [link for link in links if link.evidence_role != CLASSIFIER_SAME_FRAME_EVIDENCE_ROLE]
        for link in links[:MAX_LIVE_VISIT_EVIDENCE_FRAMES]:
            if link.media_asset_id in seen_media_ids:
                continue
            asset = session.get(MediaAssetModel, link.media_asset_id)
            # Evidence ownership stays Stream-scoped even when a historic link
            # is malformed. Curation must never reveal media from another Stream.
            if asset is None or asset.stream_id != event.stream_id:
                continue
            seen_media_ids.add(link.media_asset_id)
            parsed.append((link, asset))
        if not parsed:
            return []

        parsed.sort(
            key=lambda item: (
                _as_utc(item[0].captured_at),
                item[0].frame_sequence if item[0].frame_sequence is not None else -1,
                item[0].sort_order,
                item[0].media_asset_id,
            )
        )
        primary_id = next((link.media_asset_id for link, _asset in parsed if link.is_primary), parsed[0][0].media_asset_id)
        first_capture = _as_utc(parsed[0][0].captured_at)
        last_capture = _as_utc(parsed[-1][0].captured_at)
        duration_seconds = (last_capture - first_capture).total_seconds()
        return [
            self._visit_evidence_frame_from_link_and_asset(
                link,
                asset,
                is_primary=link.media_asset_id == primary_id,
                relative_position=(
                    0.0
                    if duration_seconds <= 0
                    else max(
                        0.0,
                        min(
                            1.0,
                            (_as_utc(link.captured_at) - first_capture).total_seconds()
                            / duration_seconds,
                        ),
                    )
                ),
                normalized_track_box=_frame_local_subject_box(
                    _normalized_box_from_json(asset.normalized_track_box_json),
                    alignment_status=asset.alignment_status,
                    parent_media_asset_id=asset.parent_media_asset_id,
                ),
            )
            for link, asset in parsed
        ]

    @staticmethod
    def _evidence_preview_url(media_asset_id: str, media_type_or_content_type: str) -> str:
        """The bounded-preview endpoint (`get_media_preview`) only ever serves images --
        it unconditionally rejects audio/video with a 413. An evidence frame's
        `preview_url` must resolve to the unrestricted `/file` endpoint for any
        non-image asset, or its primary evidence player renders a dead, silently
        non-functional control (Everyday Product / Discovery UX Closure v1,
        Visit/Evidence detail D1). Accepts either a coarse `media_type`
        ("image"/"audio"/"video") or a MIME `content_type` ("image/jpeg") --
        both start with "image" for, and only for, an actual image.
        """
        endpoint = "preview" if media_type_or_content_type.startswith("image") else "file"
        return f"/api/media/{media_asset_id}/{endpoint}"

    def _visit_evidence_frame_from_link_and_asset(
        self,
        link: VisitEvidenceLinkModel | None,
        asset: MediaAssetModel,
        *,
        is_primary: bool,
        relative_position: float = 0.0,
        normalized_track_box: list[float] | None = None,
    ) -> VisitEvidenceFrame:
        """One `VisitEvidenceFrame` from an already-resolved (link, asset)
        pair -- pure serialization, no querying. Extracted from `_visit_
        evidence_frames_from_links`'s own per-item construction (Visit Same-
        Frame Classifier Evidence Visibility v1) so a caller resolving a
        single asset outside that function's own multi-frame sequencing
        (`_classifier_supporting_evidence_from_session`) reuses the exact
        same `VisitEvidenceFrame` shape instead of a second, drifting
        construction. `relative_position`/`normalized_track_box` stay
        caller-supplied parameters rather than computed here: both depend on
        context this single-item helper does not have -- a whole sequence's
        first/last capture times for the former, a deliberately different
        (same-frame-proof-gated, see `_classifier_supporting_evidence_from_
        session`) trust rule for the latter. `link` is optional so a caller
        with only a `MediaAssetModel` (no `VisitEvidenceLinkModel` row, e.g.
        a historical record whose link was since removed) still degrades to
        an honest frame rather than failing.
        """

        return VisitEvidenceFrame(
            media_asset_id=asset.id,
            preview_url=self._evidence_preview_url(asset.id, asset.media_type),
            captured_at=_as_utc(link.captured_at if link is not None else (asset.captured_at or asset.created_at)),
            relative_position=relative_position,
            frame_sequence=link.frame_sequence if link is not None else None,
            is_primary=is_primary,
            content_type=asset.content_type,
            width=asset.image_width,
            height=asset.image_height,
            evidence_role=(
                (link.evidence_role if link is not None else None)
                or asset.evidence_role
                or "monitoring_frame"
            ),
            normalized_crop_box=(
                _normalized_box_from_json(asset.normalized_crop_box_json)
                or _normalized_box_from_json(asset.normalized_padded_crop_box_json)
            ),
            normalized_track_box=normalized_track_box,
            # Read back verbatim from this asset's own already-persisted
            # attribution -- `None` when it never had one recorded. See
            # docs/source-resolution-multi-frame-species-evidence-contract.md.
            resolution_provenance=(
                attribution.resolution_provenance
                if (attribution := geometry_attribution_from_json(asset.geometry_attribution_json))
                is not None
                else None
            ),
        )

    def classifier_supporting_evidence(self, visit_id: str) -> ClassifierSupportingEvidence | None:
        """Read-only recommendation; never rewrites the species suggestion
        or any evidence link. See `_classifier_supporting_evidence_from_
        session`."""

        with self.session_factory() as session:
            visit = session.get(VisitModel, visit_id)
            if visit is None:
                return None
            event = session.get(EventModel, visit.event_id)
            if event is None:
                return None
            return self._classifier_supporting_evidence_from_session(session, visit=visit, event=event)

    def _classifier_supporting_evidence_from_session(
        self,
        session: Session,
        *,
        visit: VisitModel,
        event: EventModel,
    ) -> ClassifierSupportingEvidence | None:
        """Visit Same-Frame Classifier Evidence Visibility v1 (see docs/
        visit-classifier-evidence-visibility-contract.md): the real
        MediaAsset `species/classifier_input.py` actually resolved and fed
        BioCLIP for this Visit's latest SpeciesSuggestion (Same-Frame
        Species Evidence v1's own `classifier_input` provenance, already
        persisted on `SpeciesSuggestionModel.evidence_region_json` -- never
        re-derived or re-resolved here), whenever that asset is not already
        one of the Visit's own ordinary `evidence_frames`. Read-only
        diagnostic-lineage exposure: never alters the suggestion, never
        promotes the asset to primary/canonical evidence (see "Non-
        promotion" in docs/same-frame-species-evidence-contract.md), and
        degrades to `None` -- never raises -- for every "nothing to
        honestly show" case: no suggestion, no recorded classifier input,
        the referenced asset gone/deleted/cross-Stream, or the asset
        already visible in the ordinary gallery.
        """

        suggestions = session.scalars(
            select(SpeciesSuggestionModel)
            .where(SpeciesSuggestionModel.visit_id == visit.id)
            .order_by(
                SpeciesSuggestionModel.created_at,
                SpeciesSuggestionModel.rank,
                SpeciesSuggestionModel.id,
            )
        ).all()
        if not suggestions:
            return None
        # Mirrors `mockingbird.api.main._latest_species_suggestion_for_visit`
        # exactly (same ordering, same `[-1]` pick) -- the identical
        # suggestion a reviewer already sees as "the" current one for this
        # Visit, so the evidence exposed here always explains that
        # suggestion, never a stale or different one.
        latest = suggestions[-1]
        if not latest.evidence_region_json:
            return None
        try:
            evidence_region = json.loads(latest.evidence_region_json)
        except (TypeError, ValueError, json.JSONDecodeError):
            return None
        if not isinstance(evidence_region, dict):
            return None
        classifier_input = evidence_region.get("classifier_input")
        if not isinstance(classifier_input, dict):
            return None
        source_media_asset_id = classifier_input.get("source_media_asset_id")
        if not isinstance(source_media_asset_id, str) or not source_media_asset_id:
            return None

        asset = session.get(MediaAssetModel, source_media_asset_id)
        # Evidence ownership stays Stream-scoped, exactly like `_visit_
        # evidence_frames_from_links`'s own check: never trust a stored id
        # (recorded at suggestion time, potentially stale) without
        # re-verifying it still belongs to this Visit's own Stream.
        # Curation must never reveal media from another Stream.
        if asset is None or asset.stream_id != event.stream_id:
            return None
        if not Path(asset.local_path).is_file():
            # Retention/cleanup since the suggestion was made -- degrade
            # cleanly rather than link to a file that is no longer there.
            return None

        # Avoid duplicate-image clutter (see "Avoid duplicate-image
        # clutter" in the contract): if this exact asset already appears in
        # the Visit's ordinary evidence_frames gallery -- by asset
        # identity, never a visual/pixel comparison -- it needs no separate
        # presentation here. `classifier_same_frame`-role assets are always
        # excluded from that gallery by construction (Same-Frame Species
        # Evidence v1), so this only ever actually suppresses the dormant
        # `persisted_crop` tier (an `activity_crop`/`user_refined_crop`
        # asset the ordinary gallery already shows).
        ordinary_links = self._visit_evidence_link_models(session, visit.id)
        ordinary_frames = self._visit_evidence_frames_from_links(
            session, visit=visit, event=event, links=ordinary_links,
        )
        if any(frame.media_asset_id == source_media_asset_id for frame in ordinary_frames):
            return None

        link = next(
            (candidate for candidate in ordinary_links if candidate.media_asset_id == source_media_asset_id),
            None,
        )
        # Same-frame proof (not the generic `alignment_status` gate `_frame_
        # local_subject_box` uses for the ordinary gallery) authorizes the
        # subject-box overlay here: `alignment_status` reconciles two
        # *different* camera profiles, which does not apply to an asset
        # that *is* the exact frame the tracker's own box was computed
        # against (`same_frame=True`, a stronger, capture-time-proven fact
        # -- see "Geometry provenance" in docs/same-frame-species-evidence-
        # contract.md). Absent that proof, no box is shown, matching the
        # ordinary gallery's own safe default.
        attribution = geometry_attribution_from_json(asset.geometry_attribution_json)
        normalized_track_box = (
            _normalized_box_from_json(asset.normalized_track_box_json)
            if attribution is not None and attribution.same_frame is True
            else None
        )
        frame = self._visit_evidence_frame_from_link_and_asset(
            link,
            asset,
            is_primary=False,
            normalized_track_box=normalized_track_box,
        )
        return ClassifierSupportingEvidence(
            frame=frame,
            species_suggestion_id=latest.id,
            same_frame=(
                classifier_input.get("same_frame")
                if isinstance(classifier_input.get("same_frame"), bool)
                else None
            ),
            input_type=(
                classifier_input.get("input_type")
                if isinstance(classifier_input.get("input_type"), str)
                else None
            ),
        )

    def _motion_evidence_model_for_visit(
        self,
        session: Session,
        visit_id: str,
    ) -> MotionEvidenceModel | None:
        return session.scalars(
            select(MotionEvidenceModel)
            .where(MotionEvidenceModel.promoted_visit_id == visit_id)
            .order_by(MotionEvidenceModel.created_at, MotionEvidenceModel.id)
        ).first()

    def _visit_evidence_frames_from_visit(
        self,
        session: Session,
        visit: VisitModel,
        event: EventModel,
    ) -> list[VisitEvidenceFrame]:
        links = self._visit_evidence_link_models(session, visit.id)
        if links:
            return self._visit_evidence_frames_from_links(
                session,
                visit=visit,
                event=event,
                links=links,
            )
        evidence_model = self._motion_evidence_model_for_visit(session, visit.id)
        evidence_frames = (
            self._visit_evidence_frames_from_model(session, evidence_model)
            if evidence_model is not None
            else []
        )
        if evidence_frames:
            return evidence_frames

        # Older one-frame Visits predate live activity sequences. Preserve that
        # evidence shape without exposing a local filesystem path.
        asset = self._media_asset_for_path_from_session(session, visit.representative_media_path)
        if asset is None or asset.stream_id != event.stream_id:
            return []
        return [
            VisitEvidenceFrame(
                media_asset_id=asset.id,
                preview_url=self._evidence_preview_url(asset.id, asset.media_type),
                captured_at=asset.created_at,
                relative_position=0.0,
                frame_sequence=None,
                is_primary=True,
                content_type=asset.content_type,
                width=asset.image_width,
                height=asset.image_height,
                evidence_role=asset.evidence_role or "monitoring_frame",
                normalized_crop_box=(
                    asset.normalized_crop_box or asset.normalized_padded_crop_box
                ),
                normalized_track_box=_frame_local_subject_box(
                    asset.normalized_track_box,
                    alignment_status=asset.alignment_status,
                    parent_media_asset_id=asset.parent_media_asset_id,
                ),
            )
        ]

    def _ensure_visit_evidence_links(
        self,
        session: Session,
        *,
        visit: VisitModel,
        event: EventModel,
    ) -> list[VisitEvidenceLinkModel]:
        links = self._visit_evidence_link_models(session, visit.id)
        if links:
            return links
        frames = self._visit_evidence_frames_from_visit(session, visit, event)
        created_at = datetime.now(UTC)
        for index, frame in enumerate(frames):
            session.add(
                VisitEvidenceLinkModel(
                    id=f"visit-evidence-{uuid.uuid4().hex}",
                    visit_id=visit.id,
                    media_asset_id=frame.media_asset_id,
                    captured_at=frame.captured_at,
                    frame_sequence=frame.frame_sequence,
                    sort_order=index,
                    is_primary=frame.is_primary,
                    evidence_role=frame.evidence_role,
                    created_at=created_at,
                )
            )
        session.flush()
        return self._visit_evidence_link_models(session, visit.id)

    def _visit_curation_entries_from_session(
        self,
        session: Session,
        visit_id: str,
    ) -> list[VisitCurationHistoryEntry]:
        entries = session.scalars(
            select(VisitCurationHistoryModel)
            .where(VisitCurationHistoryModel.visit_id == visit_id)
            .order_by(VisitCurationHistoryModel.created_at.desc(), VisitCurationHistoryModel.id.desc())
            .limit(50)
        ).all()
        result: list[VisitCurationHistoryEntry] = []
        for entry in entries:
            details = _json_object(entry.details_json)
            if entry.action == "evidence_curation":
                message = "Updated the primary evidence and supporting evidence."
            elif entry.action == "split":
                message = "Split into two Visits. Original Visit retained in history."
            elif entry.action == "merge":
                message = "Merged into a newer Visit. Original Visit retained in history."
            elif entry.action == "merged_from":
                message = "Merged from earlier Visits."
            elif entry.action == "crop_refinement":
                message = "Saved a refined high-resolution crop without changing review truth."
            elif entry.action == "crop_primary_promoted":
                message = "Restored an earlier crop as the primary review image without regenerating media."
            elif entry.action == "zone_reassigned":
                prior_zone = session.get(ZoneModel, entry.prior_zone_id) if entry.prior_zone_id else None
                destination = session.get(ZoneModel, details.get("zone_id")) if details.get("zone_id") else None
                if prior_zone is not None and destination is not None:
                    message = f"Moved from {prior_zone.name} to {destination.name}."
                elif destination is not None:
                    message = f"Moved to {destination.name}."
                else:
                    message = "Moved to another activity Zone."
            else:
                message = "Visit curation was updated."
            result.append(
                VisitCurationHistoryEntry(
                    action=entry.action,
                    message=message,
                    created_at=_as_utc(entry.created_at),
                )
            )
        return result

    def visit_curation_history(self, visit_id: str) -> list[VisitCurationHistoryEntry]:
        with self.session_factory() as session:
            if session.get(VisitModel, visit_id) is None:
                return []
            return self._visit_curation_entries_from_session(session, visit_id)

    def resulting_visits_for(self, visit_id: str) -> list[Visit]:
        with self.session_factory() as session:
            relationships = session.scalars(
                select(VisitRelationshipModel)
                .where(VisitRelationshipModel.source_visit_id == visit_id)
                .order_by(VisitRelationshipModel.created_at, VisitRelationshipModel.result_visit_id)
            ).all()
            return [
                _visit_from_model(visit)
                for relation in relationships
                if (visit := session.get(VisitModel, relation.result_visit_id)) is not None
            ]

    def _record_visit_curation(
        self,
        session: Session,
        *,
        visit_id: str,
        action: str,
        created_at: datetime,
        prior_zone_id: str | None = None,
        result_visit_ids: list[str] | None = None,
        details: dict[str, Any] | None = None,
        idempotency_key: str | None = None,
    ) -> VisitCurationHistoryModel:
        history = VisitCurationHistoryModel(
            id=f"visit-curation-{uuid.uuid4().hex}",
            visit_id=visit_id,
            action=action,
            prior_zone_id=prior_zone_id,
            result_visit_ids_json=json.dumps(result_visit_ids) if result_visit_ids else None,
            details_json=json.dumps(details, sort_keys=True) if details else None,
            idempotency_key=idempotency_key,
            created_at=created_at,
        )
        session.add(history)
        return history

    def _curation_idempotency_entry(
        self,
        session: Session,
        key: str,
    ) -> VisitCurationHistoryModel | None:
        return session.scalar(
            select(VisitCurationHistoryModel).where(
                VisitCurationHistoryModel.idempotency_key == key
            )
        )

    def _visit_curation_state(self, session: Session, visit: VisitModel) -> str:
        links = self._visit_evidence_link_models(session, visit.id)
        link_state = ",".join(
            f"{link.media_asset_id}:{_as_utc(link.captured_at).isoformat()}:"
            f"{link.frame_sequence}:{link.sort_order}:{int(link.is_primary)}"
            for link in links
        )
        results = ",".join(
            relation.result_visit_id
            for relation in session.scalars(
                select(VisitRelationshipModel)
                .where(VisitRelationshipModel.source_visit_id == visit.id)
                .order_by(VisitRelationshipModel.result_visit_id)
            ).all()
        )
        return f"{visit.zone_id or ''}|{int(visit.is_superseded)}|{link_state}|{results}"

    def _require_active_visit(
        self,
        session: Session,
        visit_id: str,
    ) -> tuple[VisitModel, EventModel]:
        visit = session.get(VisitModel, visit_id)
        if visit is None:
            raise ValueError("missing_visit")
        if visit.is_superseded:
            raise VisitCurationConflictError("visit_superseded")
        event = session.get(EventModel, visit.event_id)
        if event is None:
            raise ValueError("missing_event")
        return visit, event

    def _require_visit_state(
        self,
        session: Session,
        visit: VisitModel,
        expected_state_token: str,
    ) -> None:
        if self._review_state_token(session, "visit", visit.id) != expected_state_token:
            raise VisitCurationConflictError("stale_visit_curation")

    def _sequence_preview(
        self,
        frames: list[VisitEvidenceFrame],
    ) -> VisitCurationSequencePreview:
        ordered = sorted(
            frames,
            key=lambda frame: (
                frame.captured_at,
                frame.frame_sequence if frame.frame_sequence is not None else -1,
                frame.media_asset_id,
            ),
        )
        return VisitCurationSequencePreview(
            evidence_frames=ordered,
            activity_started_at=ordered[0].captured_at if ordered else None,
            activity_ended_at=ordered[-1].captured_at if ordered else None,
            evidence_count=len(ordered),
        )

    def curate_visit_evidence(
        self,
        visit_id: str,
        payload: VisitEvidenceCurationRequest,
    ) -> VisitEvidenceCurationResponse:
        with self.session_factory() as session:
            with session.begin():
                existing = self._curation_idempotency_entry(session, payload.idempotency_key)
                if existing is not None:
                    if existing.action != "evidence_curation" or existing.visit_id != visit_id:
                        raise VisitCurationConflictError("curation_idempotency_conflict")
                    visit = session.get(VisitModel, visit_id)
                    event = session.get(EventModel, visit.event_id) if visit else None
                    if visit is None or event is None:
                        raise ValueError("missing_visit")
                    return VisitEvidenceCurationResponse(
                        visit=_visit_from_model(visit),
                        evidence_frames=self._visit_evidence_frames_from_visit(session, visit, event),
                        review_state_token=self._review_state_token(session, "visit", visit.id),
                        idempotent=True,
                        message="Visit evidence was already saved.",
                    )

                visit, event = self._require_active_visit(session, visit_id)
                self._require_visit_state(session, visit, payload.expected_state_token)
                links = self._ensure_visit_evidence_links(session, visit=visit, event=event)
                current_ids = {link.media_asset_id for link in links}
                retained_ids = list(dict.fromkeys(payload.retained_media_asset_ids))
                if (
                    len(retained_ids) != len(payload.retained_media_asset_ids)
                    or not retained_ids
                    or len(retained_ids) > MAX_LIVE_VISIT_EVIDENCE_FRAMES
                    or not set(retained_ids).issubset(current_ids)
                    or payload.primary_media_asset_id not in retained_ids
                ):
                    raise ValueError("invalid_visit_evidence_selection")
                for link in links:
                    if link.media_asset_id not in retained_ids:
                        # This unlinks review evidence only. The MediaAsset can
                        # still be referenced by other Visits and retention rules.
                        session.delete(link)
                    else:
                        link.is_primary = link.media_asset_id == payload.primary_media_asset_id
                primary_asset = session.get(MediaAssetModel, payload.primary_media_asset_id)
                if primary_asset is None or primary_asset.stream_id != event.stream_id:
                    raise ValueError("media_stream_mismatch")
                visit.representative_media_path = primary_asset.local_path
                self._record_visit_curation(
                    session,
                    visit_id=visit.id,
                    action="evidence_curation",
                    created_at=datetime.now(UTC),
                    details={
                        "retained_media_asset_ids": retained_ids,
                        "primary_media_asset_id": payload.primary_media_asset_id,
                    },
                    idempotency_key=payload.idempotency_key,
                )
                session.flush()
                return VisitEvidenceCurationResponse(
                    visit=_visit_from_model(visit),
                    evidence_frames=self._visit_evidence_frames_from_visit(session, visit, event),
                    review_state_token=self._review_state_token(session, "visit", visit.id),
                    message="Visit evidence updated. The original media files were retained.",
                )

    def _visit_crop_history_from_session(
        self,
        session: Session,
        *,
        visit: VisitModel,
        event: EventModel,
    ) -> list[VisitCropHistoryEntry]:
        entries: list[VisitCropHistoryEntry] = []
        for link in self._visit_evidence_link_models(session, visit.id):
            role = link.evidence_role
            if role not in {"activity_crop", "user_refined_crop"}:
                continue
            asset = session.get(MediaAssetModel, link.media_asset_id)
            if (
                asset is None
                or asset.stream_id != event.stream_id
                or asset.parent_media_asset_id is None
            ):
                continue
            parent = session.get(MediaAssetModel, asset.parent_media_asset_id)
            if parent is None or parent.stream_id != event.stream_id:
                continue
            entries.append(
                VisitCropHistoryEntry(
                    media_asset_id=asset.id,
                    preview_url=f"/api/media/{asset.id}/preview",
                    parent_media_asset_id=parent.id,
                    evidence_role=role,
                    derivation_source=(
                        asset.derivation_source
                        or ("user_refined_crop" if role == "user_refined_crop" else "activity_crop")
                    ),
                    normalized_crop_box=(
                        _normalized_box_from_json(asset.normalized_crop_box_json)
                        or _normalized_box_from_json(asset.normalized_padded_crop_box_json)
                    ),
                    width=asset.image_width,
                    height=asset.image_height,
                    created_at=_as_utc(asset.created_at),
                    is_primary=link.is_primary,
                    previous_effective_crop_media_asset_id=(
                        asset.previous_effective_crop_media_asset_id
                    ),
                )
            )
        return sorted(
            entries,
            key=lambda entry: (entry.created_at, entry.media_asset_id),
            reverse=True,
        )

    def visit_crop_history(self, visit_id: str) -> list[VisitCropHistoryEntry]:
        with self.session_factory() as session:
            visit = session.get(VisitModel, visit_id)
            if visit is None:
                return []
            event = session.get(EventModel, visit.event_id)
            if event is None:
                return []
            return self._visit_crop_history_from_session(
                session,
                visit=visit,
                event=event,
            )

    def _visit_has_stale_species_suggestions(
        self,
        session: Session,
        *,
        visit_id: str,
        effective_media_asset_id: str | None = None,
    ) -> bool:
        if effective_media_asset_id is None:
            links = self._visit_evidence_link_models(session, visit_id)
            effective_media_asset_id = next(
                (link.media_asset_id for link in links if link.is_primary),
                None,
            )
        if effective_media_asset_id is None:
            return False
        return session.scalar(
            select(SpeciesSuggestionModel.id)
            .where(
                SpeciesSuggestionModel.visit_id == visit_id,
                SpeciesSuggestionModel.media_asset_id.is_not(None),
                SpeciesSuggestionModel.media_asset_id != effective_media_asset_id,
            )
            .limit(1)
        ) is not None

    def visit_has_stale_species_suggestions(self, visit_id: str) -> bool:
        with self.session_factory() as session:
            if session.get(VisitModel, visit_id) is None:
                return False
            return self._visit_has_stale_species_suggestions(
                session,
                visit_id=visit_id,
            )

    def _set_visit_crop_primary(
        self,
        session: Session,
        *,
        visit: VisitModel,
        event: EventModel,
        links: list[VisitEvidenceLinkModel],
        crop_link: VisitEvidenceLinkModel,
    ) -> None:
        # One Visit primary is an invariant shared by the queue, Fast Review,
        # and exported review context. Full evidence stays linked for zoom.
        for link in links:
            link.is_primary = link.id == crop_link.id
        crop_asset = session.get(MediaAssetModel, crop_link.media_asset_id)
        if crop_asset is None or crop_asset.stream_id != event.stream_id:
            raise ValueError("invalid_refined_crop_history")
        visit.representative_media_path = crop_asset.local_path

    def _refined_crop_parent(
        self,
        session: Session,
        *,
        links: list[VisitEvidenceLinkModel],
        event: EventModel,
    ) -> tuple[VisitEvidenceLinkModel, MediaAssetModel]:
        parents: list[tuple[VisitEvidenceLinkModel, MediaAssetModel]] = []
        for link in links:
            asset = session.get(MediaAssetModel, link.media_asset_id)
            if (
                asset is not None
                and asset.stream_id == event.stream_id
                and link.evidence_role == "high_resolution_original"
                and asset.evidence_role == "high_resolution_original"
                and asset.parent_media_asset_id is None
                and asset.image_width is not None
                and asset.image_height is not None
            ):
                parents.append((link, asset))
        if not parents:
            raise ValueError("missing_high_resolution_parent")
        return parents[-1]

    def create_refined_visit_crop(
        self,
        visit_id: str,
        payload: RefinedCropCreateRequest,
    ) -> RefinedCropResponse:
        with self.session_factory() as session:
            with session.begin():
                visit, event = self._require_active_visit(session, visit_id)
                links = self._ensure_visit_evidence_links(session, visit=visit, event=event)
                parent_link, parent = self._refined_crop_parent(
                    session,
                    links=links,
                    event=event,
                )
                requested_box = validate_refined_crop_box(
                    (payload.left, payload.top, payload.right, payload.bottom),
                    image_width=parent.image_width,
                    image_height=parent.image_height,
                )
                if requested_box is None:
                    raise ValueError("invalid_refined_crop_geometry")
                parent_path, _relative, _size, unsafe_reason = self._storage_managed_media_path(parent)
                if parent_path is None:
                    raise ValueError(unsafe_reason or "missing_media_file")
                try:
                    crop = crop_jpeg(parent_path.read_bytes(), requested_box)
                except OSError as error:
                    raise ValueError("missing_media_file") from error
                if crop is None:
                    raise ValueError("invalid_high_resolution_parent")
                normalized_box_json = _normalized_box_to_json(crop.normalized_crop_box)
                if normalized_box_json is None:
                    raise ValueError("invalid_refined_crop_geometry")

                existing = session.scalars(
                    select(MediaAssetModel)
                    .where(
                        MediaAssetModel.parent_media_asset_id == parent.id,
                        MediaAssetModel.derived_from_visit_id == visit.id,
                        MediaAssetModel.derivation_source == "user_refined_crop",
                        MediaAssetModel.normalized_crop_box_json == normalized_box_json,
                    )
                    .order_by(MediaAssetModel.created_at, MediaAssetModel.id)
                ).first()
                created = existing is None
                now = datetime.now(UTC)
                current_primary = next((link for link in links if link.is_primary), None)
                primary_changed = (
                    existing is None
                    or current_primary is None
                    or current_primary.media_asset_id != existing.id
                )
                previous_effective_crop_id = (
                    current_primary.media_asset_id
                    if current_primary is not None
                    and current_primary.evidence_role in {"activity_crop", "user_refined_crop"}
                    else None
                )
                if existing is None:
                    media_id = self._next_id(session, MediaAssetModel, "media-asset")
                    filename, local_path = self._write_media_file(
                        f"{media_id}-user-refined-crop.jpg",
                        crop.image,
                    )
                    existing = MediaAssetModel(
                        id=media_id,
                        source_id=parent.source_id,
                        stream_id=event.stream_id,
                        filename=filename,
                        content_type="image/jpeg",
                        media_type="image",
                        local_path=str(local_path),
                        original_filename=f"user-refined-crop-{media_id}.jpg",
                        file_size_bytes=len(crop.image),
                        created_at=now,
                        notes=(
                            "User-refined crop derived from retained high-resolution Visit evidence. "
                            "Creates no Event, Visit, candidate, ReviewLabel, or truth."
                        ),
                        parent_media_asset_id=parent.id,
                        evidence_role="user_refined_crop",
                        image_width=crop.width,
                        image_height=crop.height,
                        normalized_crop_box_json=normalized_box_json,
                        derived_from_visit_id=visit.id,
                        derived_from_event_id=event.id,
                        derived_from_zone_id=visit.zone_id or event.primary_zone_id,
                        parent_image_width=parent.image_width,
                        parent_image_height=parent.image_height,
                        content_sha256=hashlib.sha256(crop.image).hexdigest(),
                        derivation_source="user_refined_crop",
                        previous_effective_crop_media_asset_id=previous_effective_crop_id,
                        captured_at=parent.captured_at or parent.created_at,
                    )
                    session.add(existing)
                    session.flush()

                crop_link = next(
                    (link for link in links if link.media_asset_id == existing.id),
                    None,
                )
                if crop_link is None:
                    crop_link = VisitEvidenceLinkModel(
                        id=f"visit-evidence-{uuid.uuid4().hex}",
                        visit_id=visit.id,
                        media_asset_id=existing.id,
                        captured_at=parent_link.captured_at,
                        frame_sequence=parent_link.frame_sequence,
                        sort_order=max((link.sort_order for link in links), default=-1) + 1,
                        is_primary=False,
                        evidence_role="user_refined_crop",
                        created_at=now,
                    )
                    session.add(crop_link)
                    links.append(crop_link)
                self._set_visit_crop_primary(
                    session,
                    visit=visit,
                    event=event,
                    links=links,
                    crop_link=crop_link,
                )
                if created or primary_changed:
                    self._record_visit_curation(
                        session,
                        visit_id=visit.id,
                        action="crop_refinement",
                        created_at=now,
                        details={
                            "crop_media_asset_id": existing.id,
                            "parent_media_asset_id": parent.id,
                            "created": created,
                        },
                    )
                session.flush()
                frames = self._visit_evidence_frames_from_visit(session, visit, event)
                return RefinedCropResponse(
                    visit=_visit_from_model(visit),
                    refined_crop=_media_asset_from_model(existing),
                    evidence_frames=frames,
                    crop_history=self._visit_crop_history_from_session(
                        session,
                        visit=visit,
                        event=event,
                    ),
                    stale_species_suggestions=self._visit_has_stale_species_suggestions(
                        session,
                        visit_id=visit.id,
                        effective_media_asset_id=existing.id,
                    ),
                    created=created,
                    message=(
                        "Refined crop saved as the primary review image. Existing suggestions remain evidence only."
                        if created
                        else "This exact refined crop already exists and is now the primary review image."
                    ),
                )

    def promote_visit_crop_history(
        self,
        visit_id: str,
        media_asset_id: str,
    ) -> RefinedCropResponse:
        with self.session_factory() as session:
            with session.begin():
                visit, event = self._require_active_visit(session, visit_id)
                links = self._ensure_visit_evidence_links(session, visit=visit, event=event)
                crop_link = next(
                    (
                        link
                        for link in links
                        if link.media_asset_id == media_asset_id
                        and link.evidence_role in {"activity_crop", "user_refined_crop"}
                    ),
                    None,
                )
                if crop_link is None:
                    raise ValueError("invalid_refined_crop_history")
                crop = session.get(MediaAssetModel, crop_link.media_asset_id)
                parent = (
                    session.get(MediaAssetModel, crop.parent_media_asset_id)
                    if crop is not None and crop.parent_media_asset_id
                    else None
                )
                if (
                    crop is None
                    or parent is None
                    or crop.stream_id != event.stream_id
                    or parent.stream_id != event.stream_id
                    or parent.evidence_role != "high_resolution_original"
                ):
                    raise ValueError("invalid_refined_crop_history")
                self._set_visit_crop_primary(
                    session,
                    visit=visit,
                    event=event,
                    links=links,
                    crop_link=crop_link,
                )
                now = datetime.now(UTC)
                self._record_visit_curation(
                    session,
                    visit_id=visit.id,
                    action="crop_primary_promoted",
                    created_at=now,
                    details={"crop_media_asset_id": crop.id},
                )
                session.flush()
                return RefinedCropResponse(
                    visit=_visit_from_model(visit),
                    refined_crop=_media_asset_from_model(crop),
                    evidence_frames=self._visit_evidence_frames_from_visit(session, visit, event),
                    crop_history=self._visit_crop_history_from_session(
                        session,
                        visit=visit,
                        event=event,
                    ),
                    stale_species_suggestions=self._visit_has_stale_species_suggestions(
                        session,
                        visit_id=visit.id,
                        effective_media_asset_id=crop.id,
                    ),
                    created=False,
                    message="Earlier crop restored as the primary review image. No media was regenerated.",
                )

    def preview_visit_split(
        self,
        visit_id: str,
        payload: VisitSplitPreviewRequest,
    ) -> VisitSplitPreview:
        with self.session_factory() as session:
            visit, event = self._require_active_visit(session, visit_id)
            self._require_visit_state(session, visit, payload.expected_state_token)
            first, second = self._split_evidence_frames(
                self._visit_evidence_frames_from_visit(session, visit, event),
                payload.boundary_after_media_asset_id,
            )
            implication = (
                "Both resulting Visits will need review; the original correction remains in history."
                if visit.review_status == ReviewStatus.reviewed.value
                else "Both resulting Visits will be available in Review Queue."
            )
            return VisitSplitPreview(
                first=self._sequence_preview(first),
                second=self._sequence_preview(second),
                review_implication=implication,
                state_token=self._review_state_token(session, "visit", visit.id),
            )

    def _split_evidence_frames(
        self,
        frames: list[VisitEvidenceFrame],
        boundary_after_media_asset_id: str,
    ) -> tuple[list[VisitEvidenceFrame], list[VisitEvidenceFrame]]:
        boundary = next(
            (index for index, frame in enumerate(frames) if frame.media_asset_id == boundary_after_media_asset_id),
            None,
        )
        if boundary is None or boundary < 0 or boundary >= len(frames) - 1:
            raise ValueError("invalid_split_boundary")
        first = frames[: boundary + 1]
        second = frames[boundary + 1 :]
        if not first or not second:
            raise ValueError("invalid_split_boundary")
        return self._with_primary(first), self._with_primary(second)

    def _with_primary(
        self,
        frames: list[VisitEvidenceFrame],
        preferred_primary_id: str | None = None,
    ) -> list[VisitEvidenceFrame]:
        primary_id = preferred_primary_id if preferred_primary_id in {frame.media_asset_id for frame in frames} else next(
            (frame.media_asset_id for frame in frames if frame.is_primary),
            frames[0].media_asset_id,
        )
        return [frame.model_copy(update={"is_primary": frame.media_asset_id == primary_id}) for frame in frames]

    def split_visit(self, visit_id: str, payload: VisitSplitRequest) -> VisitSplitResponse:
        with self.session_factory() as session:
            with session.begin():
                existing = self._curation_idempotency_entry(session, payload.idempotency_key)
                if existing is not None:
                    if existing.action != "split" or existing.visit_id != visit_id:
                        raise VisitCurationConflictError("curation_idempotency_conflict")
                    source = session.get(VisitModel, visit_id)
                    result_ids = _json_string_list(existing.result_visit_ids_json)
                    results = [session.get(VisitModel, result_id) for result_id in result_ids]
                    if source is None or len(results) != 2 or any(result is None for result in results):
                        raise VisitCurationConflictError("curation_idempotency_incomplete")
                    return VisitSplitResponse(
                        source_visit=_visit_from_model(source),
                        resulting_visits=[_visit_from_model(result) for result in results if result is not None],
                        review_state_token=self._review_state_token(session, "visit", results[0].id),
                        idempotent=True,
                        message="This Visit was already split. The original remains in history.",
                    )
                source, event = self._require_active_visit(session, visit_id)
                self._require_visit_state(session, source, payload.expected_state_token)
                frames = self._visit_evidence_frames_from_visit(session, source, event)
                first_frames, second_frames = self._split_evidence_frames(
                    frames,
                    payload.boundary_after_media_asset_id,
                )
                if len(first_frames) > MAX_LIVE_VISIT_EVIDENCE_FRAMES or len(second_frames) > MAX_LIVE_VISIT_EVIDENCE_FRAMES:
                    raise ValueError("visit_evidence_limit")
                self._ensure_visit_evidence_links(session, visit=source, event=event)
                created_at = datetime.now(UTC)
                results: list[VisitModel] = []
                for frames_for_result in (first_frames, second_frames):
                    primary = next(frame for frame in frames_for_result if frame.is_primary)
                    primary_asset = session.get(MediaAssetModel, primary.media_asset_id)
                    if primary_asset is None or primary_asset.stream_id != event.stream_id:
                        raise ValueError("media_stream_mismatch")
                    result = VisitModel(
                        id=self._next_id(session, VisitModel, "visit-curated"),
                        event_id=event.id,
                        subject_label=source.subject_label,
                        species_guess=source.species_guess,
                        confidence=source.confidence,
                        reviewed_label=None,
                        review_status=ReviewStatus.needs_review.value,
                        representative_media_path=primary_asset.local_path,
                        zone_id=source.zone_id or event.primary_zone_id,
                        is_superseded=False,
                    )
                    session.add(result)
                    session.flush()
                    for order, frame in enumerate(frames_for_result):
                        session.add(
                            VisitEvidenceLinkModel(
                                id=f"visit-evidence-{uuid.uuid4().hex}",
                                visit_id=result.id,
                                media_asset_id=frame.media_asset_id,
                                captured_at=frame.captured_at,
                                frame_sequence=frame.frame_sequence,
                                sort_order=order,
                                is_primary=frame.is_primary,
                                evidence_role=frame.evidence_role,
                                created_at=created_at,
                            )
                        )
                    session.add(
                        VisitRelationshipModel(
                            id=f"visit-relationship-{uuid.uuid4().hex}",
                            source_visit_id=source.id,
                            result_visit_id=result.id,
                            relationship_type="split",
                            created_at=created_at,
                        )
                    )
                    self._copy_visit_organization(
                        session,
                        source_visit_id=source.id,
                        result_visit_id=result.id,
                        created_at=created_at,
                    )
                    self._copy_visit_collection_memberships(
                        session,
                        source_visit_id=source.id,
                        result_visit_id=result.id,
                        created_at=created_at,
                    )
                    self._copy_visit_tag_memberships(session, source.id, result.id, created_at)
                    results.append(result)
                source.is_superseded = True
                event.review_status = ReviewStatus.needs_review.value
                self._record_visit_curation(
                    session,
                    visit_id=source.id,
                    action="split",
                    created_at=created_at,
                    result_visit_ids=[result.id for result in results],
                    idempotency_key=payload.idempotency_key,
                )
                for result in results:
                    self._record_visit_curation(
                        session,
                        visit_id=result.id,
                        action="split_from",
                        created_at=created_at,
                        details={"source_visit_id": source.id},
                    )
                self._sync_review_alert(session, source, created_at)
                for result in results:
                    self._sync_review_alert(session, result, created_at)
                session.flush()
                return VisitSplitResponse(
                    source_visit=_visit_from_model(source),
                    resulting_visits=[_visit_from_model(result) for result in results],
                    review_state_token=self._review_state_token(session, "visit", results[0].id),
                    message="Visit split into two new Visits. Review each result before it contributes truth.",
                )

    def _visit_time_bounds(
        self,
        session: Session,
        visit: VisitModel,
        event: EventModel,
    ) -> tuple[datetime, datetime]:
        frames = self._visit_evidence_frames_from_visit(session, visit, event)
        start, end = self._visit_activity_window_for_frames(
            event,
            self._motion_evidence_model_for_visit(session, visit.id),
            frames,
        )
        return start, end or start

    @staticmethod
    def _copy_visit_organization(
        session: Session,
        *,
        source_visit_id: str,
        result_visit_id: str,
        created_at: datetime,
    ) -> None:
        """Carry private curation context through a structural split, never review truth."""

        source = session.get(VisitOrganizationModel, source_visit_id)
        if source is None:
            return
        session.add(
            VisitOrganizationModel(
                visit_id=result_visit_id,
                is_favorite=source.is_favorite,
                note=source.note,
                inherited_from_visit_id=source_visit_id,
                version=1,
                created_at=created_at,
                updated_at=created_at,
                idempotency_key=None,
            )
        )

    @staticmethod
    def _merged_visit_organization(
        session: Session,
        *,
        source_visit_ids: list[str],
        result_visit_id: str,
        created_at: datetime,
    ) -> None:
        """Merge user-owned favorite and note context without silently dropping text."""

        sources = [
            session.get(VisitOrganizationModel, visit_id) for visit_id in source_visit_ids
        ]
        sources = [source for source in sources if source is not None]
        if not sources:
            return
        notes: list[str] = []
        for source in sources:
            note = (source.note or "").strip()
            if note and note not in notes:
                notes.append(note)
        merged_note = "\n\n".join(notes) or None
        if merged_note is not None and len(merged_note) > 4000:
            raise ValueError("merge_organization_note_limit")
        session.add(
            VisitOrganizationModel(
                visit_id=result_visit_id,
                is_favorite=any(source.is_favorite for source in sources),
                note=merged_note,
                inherited_from_visit_id=sources[0].visit_id,
                version=1,
                created_at=created_at,
                updated_at=created_at,
                idempotency_key=None,
            )
        )

    @staticmethod
    def _copy_visit_collection_memberships(
        session: Session,
        *,
        source_visit_id: str,
        result_visit_id: str,
        created_at: datetime,
    ) -> None:
        """Copy local gallery membership only; the source remains historical context."""

        collection_ids = session.scalars(
            select(VisitCollectionMembershipModel.collection_id).where(
                VisitCollectionMembershipModel.visit_id == source_visit_id
            )
        ).all()
        for collection_id in collection_ids:
            session.add(
                VisitCollectionMembershipModel(
                    collection_id=collection_id,
                    visit_id=result_visit_id,
                    created_at=created_at,
                )
            )

    @staticmethod
    def _merge_visit_collection_memberships(
        session: Session,
        *,
        source_visit_ids: list[str],
        result_visit_id: str,
        created_at: datetime,
    ) -> None:
        """Union structural membership without changing Collection or review state."""

        collection_ids = set(
            session.scalars(
                select(VisitCollectionMembershipModel.collection_id).where(
                    VisitCollectionMembershipModel.visit_id.in_(source_visit_ids)
                )
            ).all()
        )
        for collection_id in collection_ids:
            session.add(
                VisitCollectionMembershipModel(
                    collection_id=collection_id,
                    visit_id=result_visit_id,
                    created_at=created_at,
                )
            )

    @staticmethod
    def _copy_visit_tag_memberships(session: Session, source_visit_id: str, result_visit_id: str, created_at: datetime) -> None:
        for tag_id in session.scalars(select(VisitTagMembershipModel.tag_id).where(VisitTagMembershipModel.visit_id == source_visit_id)).all():
            session.add(VisitTagMembershipModel(tag_id=tag_id, visit_id=result_visit_id, created_at=created_at))

    @staticmethod
    def _merge_visit_tag_memberships(session: Session, source_visit_ids: list[str], result_visit_id: str, created_at: datetime) -> None:
        tag_ids = set(session.scalars(select(VisitTagMembershipModel.tag_id).where(VisitTagMembershipModel.visit_id.in_(source_visit_ids))).all())
        if len(tag_ids) > MAX_TAGS_PER_VISIT:
            raise ValueError("merge_tag_limit")
        for tag_id in tag_ids:
            session.add(VisitTagMembershipModel(tag_id=tag_id, visit_id=result_visit_id, created_at=created_at))

    def _visit_merge_gap_seconds(
        self,
        session: Session,
        left: VisitModel,
        left_event: EventModel,
        right: VisitModel,
        right_event: EventModel,
    ) -> float:
        left_start, left_end = self._visit_time_bounds(session, left, left_event)
        right_start, right_end = self._visit_time_bounds(session, right, right_event)
        if right_start < left_start:
            left_start, left_end, right_start, right_end = right_start, right_end, left_start, left_end
        return max(0.0, (right_start - left_end).total_seconds())

    def _visit_merge_source_models(
        self,
        session: Session,
        visit_id: str,
        candidate_ids: list[str],
    ) -> list[tuple[VisitModel, EventModel]]:
        if len(candidate_ids) != len(set(candidate_ids)) or visit_id in candidate_ids:
            raise ValueError("invalid_merge_candidates")
        if not candidate_ids or len(candidate_ids) >= MAX_VISIT_MERGE_CANDIDATES:
            raise ValueError("invalid_merge_candidates")
        source, source_event = self._require_active_visit(session, visit_id)
        source_zone_id = source.zone_id or source_event.primary_zone_id
        if source_zone_id is None:
            raise ValueError("merge_requires_zone")
        source_stream = session.get(StreamModel, source_event.stream_id)
        if source_stream is None:
            raise ValueError("missing_stream")
        models: list[tuple[VisitModel, EventModel]] = [(source, source_event)]
        for candidate_id in candidate_ids:
            candidate, candidate_event = self._require_active_visit(session, candidate_id)
            candidate_zone_id = candidate.zone_id or candidate_event.primary_zone_id
            candidate_stream = session.get(StreamModel, candidate_event.stream_id)
            if (
                candidate_event.stream_id != source_event.stream_id
                or candidate_zone_id != source_zone_id
                or candidate_stream is None
                or candidate_stream.source_id != source_stream.source_id
            ):
                raise ValueError("merge_stream_or_zone_mismatch")
            models.append((candidate, candidate_event))
        models.sort(
            key=lambda item: (*self._visit_time_bounds(session, item[0], item[1]), item[0].id)
        )
        for (left, left_event), (right, right_event) in zip(models, models[1:]):
            gap = self._visit_merge_gap_seconds(session, left, left_event, right, right_event)
            if gap > MAX_VISIT_MERGE_GAP.total_seconds():
                raise ValueError("merge_time_gap_exceeded")
        return models

    def _merge_state_token(
        self,
        session: Session,
        models: list[tuple[VisitModel, EventModel]],
    ) -> str:
        state = "|".join(
            f"{visit.id}:{self._review_state_token(session, 'visit', visit.id)}"
            for visit, _event in models
        )
        return hashlib.sha256(state.encode("utf-8")).hexdigest()[:24]

    def _merged_evidence_frames(
        self,
        session: Session,
        models: list[tuple[VisitModel, EventModel]],
        *,
        preferred_primary_visit_id: str,
    ) -> list[VisitEvidenceFrame]:
        frames_by_media_id: dict[str, VisitEvidenceFrame] = {}
        preferred_primary_id: str | None = None
        for visit, event in models:
            for frame in self._visit_evidence_frames_from_visit(session, visit, event):
                existing = frames_by_media_id.get(frame.media_asset_id)
                if existing is None or (
                    frame.captured_at,
                    frame.frame_sequence if frame.frame_sequence is not None else -1,
                ) < (
                    existing.captured_at,
                    existing.frame_sequence if existing.frame_sequence is not None else -1,
                ):
                    frames_by_media_id[frame.media_asset_id] = frame
                if visit.id == preferred_primary_visit_id and frame.is_primary:
                    preferred_primary_id = frame.media_asset_id
        frames = sorted(
            frames_by_media_id.values(),
            key=lambda frame: (
                frame.captured_at,
                frame.frame_sequence if frame.frame_sequence is not None else -1,
                frame.media_asset_id,
            ),
        )
        if len(frames) > MAX_LIVE_VISIT_EVIDENCE_FRAMES:
            raise ValueError("merge_evidence_limit")
        if not frames:
            raise ValueError("merge_requires_evidence")
        return self._with_primary(frames, preferred_primary_id)

    def _merge_reviewed_label(
        self,
        session: Session,
        models: list[tuple[VisitModel, EventModel]],
    ) -> str | None:
        labels: list[str] = []
        for visit, event in models:
            if visit.review_status != ReviewStatus.reviewed.value:
                return None
            label = self._visit_reviewed_label(session, visit, event)
            if label is None or self._visit_review_outcome(
                session,
                review_status=ReviewStatus.reviewed,
                reviewed_label=label,
            ) != VisitReviewOutcome.confirmed_bird:
                return None
            labels.append(self._normalize_label_from_session(session, label))
        return labels[0] if labels and len(set(labels)) == 1 else None

    def merge_candidates_for_visit(self, visit_id: str) -> VisitMergeCandidatesResponse:
        with self.session_factory() as session:
            source, source_event = self._require_active_visit(session, visit_id)
            source_zone_id = source.zone_id or source_event.primary_zone_id
            if source_zone_id is None:
                return VisitMergeCandidatesResponse(
                    candidates=[],
                    maximum_gap_seconds=int(MAX_VISIT_MERGE_GAP.total_seconds()),
                )
            candidates: list[VisitMergeCandidate] = []
            rows = session.execute(
                select(VisitModel, EventModel)
                .join(EventModel, VisitModel.event_id == EventModel.id)
                .where(
                    VisitModel.is_superseded.is_(False),
                    VisitModel.id != source.id,
                    EventModel.stream_id == source_event.stream_id,
                    func.coalesce(VisitModel.zone_id, EventModel.primary_zone_id) == source_zone_id,
                )
                .order_by(EventModel.started_at.desc(), VisitModel.id)
                .limit(MAX_VISIT_MERGE_CANDIDATES * 5)
            ).all()
            for candidate, candidate_event in rows:
                gap = self._visit_merge_gap_seconds(
                    session,
                    source,
                    source_event,
                    candidate,
                    candidate_event,
                )
                if gap <= MAX_VISIT_MERGE_GAP.total_seconds():
                    candidates.append(
                        VisitMergeCandidate(
                            visit=self._stream_visit_summary_from_models(
                                session,
                                candidate,
                                candidate_event,
                            ),
                            gap_seconds=gap,
                        )
                    )
            candidates.sort(key=lambda candidate: (candidate.gap_seconds, candidate.visit.id))
            return VisitMergeCandidatesResponse(
                candidates=candidates[:MAX_VISIT_MERGE_CANDIDATES],
                maximum_gap_seconds=int(MAX_VISIT_MERGE_GAP.total_seconds()),
            )

    def preview_visit_merge(
        self,
        visit_id: str,
        payload: VisitMergePreviewRequest,
    ) -> VisitMergePreview:
        with self.session_factory() as session:
            source, _event = self._require_active_visit(session, visit_id)
            self._require_visit_state(session, source, payload.expected_state_token)
            models = self._visit_merge_source_models(session, visit_id, payload.candidate_visit_ids)
            merged_frames = self._merged_evidence_frames(
                session,
                models,
                preferred_primary_visit_id=source.id,
            )
            safe_label = self._merge_reviewed_label(session, models)
            implication = (
                f"Matching reviewed bird correction {safe_label} can be retained."
                if safe_label is not None
                else "The merged Visit will need review; source corrections remain in history."
            )
            return VisitMergePreview(
                source_visits=[_visit_from_model(visit) for visit, _event in models],
                combined=self._sequence_preview(merged_frames),
                review_implication=implication,
                state_token=self._merge_state_token(session, models),
            )

    def merge_visits(self, visit_id: str, payload: VisitMergeRequest) -> VisitMergeResponse:
        with self.session_factory() as session:
            with session.begin():
                existing = self._curation_idempotency_entry(session, payload.idempotency_key)
                if existing is not None:
                    if existing.action != "merge" or existing.visit_id != visit_id:
                        raise VisitCurationConflictError("curation_idempotency_conflict")
                    result_ids = _json_string_list(existing.result_visit_ids_json)
                    result = session.get(VisitModel, result_ids[0]) if len(result_ids) == 1 else None
                    source_ids = _json_object(existing.details_json).get("source_visit_ids", [])
                    sources = [session.get(VisitModel, source_id) for source_id in source_ids]
                    if result is None or any(source is None for source in sources):
                        raise VisitCurationConflictError("curation_idempotency_incomplete")
                    return VisitMergeResponse(
                        visit=_visit_from_model(result),
                        source_visits=[_visit_from_model(source) for source in sources if source is not None],
                        review_state_token=self._review_state_token(session, "visit", result.id),
                        idempotent=True,
                        message="These Visits were already merged. Earlier Visits remain in history.",
                    )
                source, _source_event = self._require_active_visit(session, visit_id)
                models = self._visit_merge_source_models(session, visit_id, payload.candidate_visit_ids)
                if self._merge_state_token(session, models) != payload.expected_state_token:
                    raise VisitCurationConflictError("stale_merge_preview")
                merged_frames = self._merged_evidence_frames(
                    session,
                    models,
                    preferred_primary_visit_id=source.id,
                )
                first_start, _ = self._visit_time_bounds(session, models[0][0], models[0][1])
                _, last_end = self._visit_time_bounds(session, models[-1][0], models[-1][1])
                source_event = models[0][1]
                zone_id = models[0][0].zone_id or source_event.primary_zone_id
                safe_label = self._merge_reviewed_label(session, models)
                created_at = datetime.now(UTC)
                new_event = EventModel(
                    id=self._next_id(session, EventModel, "event-curated"),
                    stream_id=source_event.stream_id,
                    title="Merged outdoor activity",
                    event_type=source_event.event_type,
                    started_at=first_start,
                    ended_at=last_end,
                    primary_zone_id=zone_id,
                    review_status=(
                        ReviewStatus.reviewed.value
                        if safe_label is not None
                        else ReviewStatus.needs_review.value
                    ),
                )
                primary = next(frame for frame in merged_frames if frame.is_primary)
                primary_asset = session.get(MediaAssetModel, primary.media_asset_id)
                if primary_asset is None or primary_asset.stream_id != source_event.stream_id:
                    raise ValueError("media_stream_mismatch")
                merged_visit = VisitModel(
                    id=self._next_id(session, VisitModel, "visit-curated"),
                    event_id=new_event.id,
                    subject_label=source.subject_label,
                    species_guess=source.species_guess,
                    confidence=source.confidence,
                    reviewed_label=safe_label,
                    review_status=(
                        ReviewStatus.reviewed.value
                        if safe_label is not None
                        else ReviewStatus.needs_review.value
                    ),
                    representative_media_path=primary_asset.local_path,
                    zone_id=zone_id,
                    is_superseded=False,
                )
                session.add_all([new_event, merged_visit])
                session.flush()
                source_ids = [visit.id for visit, _event in models]
                self._merged_visit_organization(
                    session,
                    source_visit_ids=source_ids,
                    result_visit_id=merged_visit.id,
                    created_at=created_at,
                )
                self._merge_visit_collection_memberships(
                    session,
                    source_visit_ids=source_ids,
                    result_visit_id=merged_visit.id,
                    created_at=created_at,
                )
                self._merge_visit_tag_memberships(session, source_ids, merged_visit.id, created_at)
                for order, frame in enumerate(merged_frames):
                    session.add(
                        VisitEvidenceLinkModel(
                            id=f"visit-evidence-{uuid.uuid4().hex}",
                            visit_id=merged_visit.id,
                            media_asset_id=frame.media_asset_id,
                            captured_at=frame.captured_at,
                            frame_sequence=frame.frame_sequence,
                            sort_order=order,
                            is_primary=frame.is_primary,
                            evidence_role=frame.evidence_role,
                            created_at=created_at,
                        )
                    )
                if safe_label is not None:
                    session.add(
                        ReviewLabelModel(
                            id=self._next_id(session, ReviewLabelModel, "review-label"),
                            target_type="visit",
                            target_id=merged_visit.id,
                            label=safe_label,
                            notes="Retained after merging Visits with the same reviewed bird correction.",
                            created_at=created_at,
                            review_action="merge_inherited",
                        )
                    )
                for index, (old_visit, _old_event) in enumerate(models):
                    old_visit.is_superseded = True
                    session.add(
                        VisitRelationshipModel(
                            id=f"visit-relationship-{uuid.uuid4().hex}",
                            source_visit_id=old_visit.id,
                            result_visit_id=merged_visit.id,
                            relationship_type="merge",
                            created_at=created_at,
                        )
                    )
                    self._record_visit_curation(
                        session,
                        visit_id=old_visit.id,
                        action="merge",
                        created_at=created_at,
                        result_visit_ids=[merged_visit.id],
                        details={"source_visit_ids": source_ids},
                        idempotency_key=payload.idempotency_key if index == 0 else None,
                    )
                self._record_visit_curation(
                    session,
                    visit_id=merged_visit.id,
                    action="merged_from",
                    created_at=created_at,
                    details={"source_visit_ids": source_ids},
                )
                for old_visit, _old_event in models:
                    self._sync_review_alert(session, old_visit, created_at)
                self._sync_review_alert(session, merged_visit, created_at)
                session.flush()
                return VisitMergeResponse(
                    visit=_visit_from_model(merged_visit),
                    source_visits=[_visit_from_model(old_visit) for old_visit, _event in models],
                    review_state_token=self._review_state_token(session, "visit", merged_visit.id),
                    message=(
                        "Visits merged and the matching reviewed bird correction was retained."
                        if safe_label is not None
                        else "Visits merged. Review the merged Visit before it contributes truth."
                    ),
                )

    def reassign_visit_zone(
        self,
        visit_id: str,
        payload: VisitZoneReassignmentRequest,
    ) -> VisitZoneReassignmentResponse:
        with self.session_factory() as session:
            with session.begin():
                existing = self._curation_idempotency_entry(session, payload.idempotency_key)
                if existing is not None:
                    if existing.action != "zone_reassigned" or existing.visit_id != visit_id:
                        raise VisitCurationConflictError("curation_idempotency_conflict")
                    visit = session.get(VisitModel, visit_id)
                    if visit is None:
                        raise ValueError("missing_visit")
                    return VisitZoneReassignmentResponse(
                        visit=_visit_from_model(visit),
                        review_state_token=self._review_state_token(session, "visit", visit.id),
                        idempotent=True,
                        message="Visit Zone was already updated.",
                    )
                visit, event = self._require_active_visit(session, visit_id)
                self._require_visit_state(session, visit, payload.expected_state_token)
                destination = session.get(ZoneModel, payload.zone_id)
                if (
                    destination is None
                    or destination.stream_id != event.stream_id
                    or not destination.is_active
                    or destination.zone_type in {ZoneType.privacy.value, ZoneType.ignore.value}
                ):
                    raise ValueError("invalid_visit_zone")
                prior_zone_id = visit.zone_id or event.primary_zone_id
                visit.zone_id = destination.id
                self._record_visit_curation(
                    session,
                    visit_id=visit.id,
                    action="zone_reassigned",
                    prior_zone_id=prior_zone_id,
                    created_at=datetime.now(UTC),
                    details={"zone_id": destination.id},
                    idempotency_key=payload.idempotency_key,
                )
                session.flush()
                return VisitZoneReassignmentResponse(
                    visit=_visit_from_model(visit),
                    review_state_token=self._review_state_token(session, "visit", visit.id),
                    message=f"Visit moved to {destination.name}. Media and correction history were preserved.",
                )

    def _visit_evidence_frames_from_model(
        self,
        session: Session,
        evidence: MotionEvidenceModel,
    ) -> list[VisitEvidenceFrame]:
        try:
            config = dict(json.loads(evidence.scoring_config_json))
        except (TypeError, ValueError):
            return []
        if config.get("source") != "live_stream_motion_session_activity":
            return []

        activity_session_id = _optional_string(config.get("activity_session_id"))
        raw_frames = config.get("visit_evidence_frames")
        if not activity_session_id or not isinstance(raw_frames, list):
            return []

        parsed: list[
            tuple[
                datetime,
                int | None,
                str,
                bool,
                str,
                int | None,
                int | None,
                str,
                list[float] | None,
            ]
        ] = []
        seen_media_ids: set[str] = set()
        for raw_frame in raw_frames[:MAX_LIVE_VISIT_EVIDENCE_FRAMES]:
            if not isinstance(raw_frame, dict):
                continue
            if raw_frame.get("activity_session_id") != activity_session_id:
                continue
            media_asset_id = _optional_string(raw_frame.get("media_asset_id"))
            captured_at = _optional_datetime(raw_frame.get("captured_at"))
            if media_asset_id is None or captured_at is None or media_asset_id in seen_media_ids:
                continue
            asset = session.get(MediaAssetModel, media_asset_id)
            # Evidence can only surface media from this evidence's Stream. This
            # prevents a malformed association from exposing another Visit's frame.
            if asset is None or asset.stream_id != evidence.stream_id:
                continue
            seen_media_ids.add(media_asset_id)
            parsed.append(
                (
                    captured_at,
                    _optional_int(raw_frame.get("frame_sequence")),
                    media_asset_id,
                    bool(raw_frame.get("is_primary")),
                    asset.content_type,
                    _optional_int(raw_frame.get("width")),
                    _optional_int(raw_frame.get("height")),
                    _optional_string(raw_frame.get("evidence_role"))
                    or asset.evidence_role
                    or "monitoring_frame",
                    _frame_local_subject_box(
                        _normalized_box_from_json(asset.normalized_track_box_json),
                        alignment_status=asset.alignment_status,
                        parent_media_asset_id=asset.parent_media_asset_id,
                    ),
                )
            )

        if not parsed:
            return []

        parsed.sort(key=lambda frame: (frame[0], frame[1] if frame[1] is not None else -1))
        primary_media_asset_id = next(
            (
                frame[2]
                for frame in parsed
                if frame[2] == evidence.snapshot_media_asset_id
            ),
            next((frame[2] for frame in parsed if frame[3]), parsed[0][2]),
        )
        first_capture = parsed[0][0]
        last_capture = parsed[-1][0]
        duration_seconds = (last_capture - first_capture).total_seconds()
        return [
            VisitEvidenceFrame(
                media_asset_id=media_asset_id,
                preview_url=self._evidence_preview_url(media_asset_id, content_type),
                captured_at=captured_at,
                relative_position=(
                    0.0
                    if duration_seconds <= 0
                    else max(
                        0.0,
                        min(
                            1.0,
                            (captured_at - first_capture).total_seconds()
                            / duration_seconds,
                        ),
                    )
                ),
                frame_sequence=frame_sequence,
                is_primary=media_asset_id == primary_media_asset_id,
                content_type=content_type,
                width=width if width and width > 0 else None,
                height=height if height and height > 0 else None,
                evidence_role=evidence_role,
                normalized_track_box=normalized_track_box,
            )
            for (
                captured_at,
                frame_sequence,
                media_asset_id,
                _is_primary,
                content_type,
                width,
                height,
                evidence_role,
                normalized_track_box,
            ) in parsed
        ]

    def ignore_motion_evidence(self, evidence_id: str) -> MotionEvidenceResponse | None:
        with self.session_factory() as session:
            with session.begin():
                evidence_model = session.get(MotionEvidenceModel, evidence_id)
                if evidence_model is None:
                    return None
                return self._ignore_motion_evidence_model(session, evidence_model)

    def _ignore_motion_evidence_model(
        self,
        session: Session,
        evidence_model: MotionEvidenceModel,
    ) -> MotionEvidenceResponse:
        if evidence_model.status != MotionEvidenceStatus.pending.value:
            raise ValueError("motion_evidence_not_pending")

        evidence_model.status = MotionEvidenceStatus.ignored.value
        session.flush()
        return _motion_evidence_from_model(evidence_model)

    def attach_motion_evidence_media(
        self,
        evidence_id: str,
        snapshot_media_asset_id: str | None,
    ) -> MotionEvidenceResponse | None:
        with self.session_factory() as session:
            with session.begin():
                evidence_model = session.get(MotionEvidenceModel, evidence_id)
                if evidence_model is None:
                    return None
                if evidence_model.status == MotionEvidenceStatus.ignored.value:
                    raise ValueError("motion_evidence_attach_ignored")
                if evidence_model.status == MotionEvidenceStatus.promoted.value:
                    raise ValueError("motion_evidence_attach_promoted")
                if evidence_model.status != MotionEvidenceStatus.pending.value:
                    raise ValueError("motion_evidence_attach_not_pending")

                media_id = (
                    snapshot_media_asset_id.strip()
                    if snapshot_media_asset_id and snapshot_media_asset_id.strip()
                    else None
                )
                if media_id is not None:
                    asset_model = session.get(MediaAssetModel, media_id)
                    if asset_model is None:
                        raise ValueError("missing_media_asset")
                    if asset_model.stream_id != evidence_model.stream_id:
                        raise ValueError("media_stream_mismatch")

                evidence_model.snapshot_media_asset_id = media_id
                session.flush()
                return _motion_evidence_from_model(evidence_model)

    def promote_motion_evidence(
        self,
        evidence_id: str,
        payload: MotionEvidencePromoteRequest,
    ) -> MotionEvidencePromoteResponse | None:
        with self.session_factory() as session:
            with session.begin():
                evidence_model = session.get(MotionEvidenceModel, evidence_id)
                if evidence_model is None:
                    return None
                return self._promote_motion_evidence_model(session, evidence_model, payload)

    def _promote_motion_evidence_model(
        self,
        session: Session,
        evidence_model: MotionEvidenceModel,
        payload: MotionEvidencePromoteRequest,
    ) -> MotionEvidencePromoteResponse:
        if evidence_model.status == MotionEvidenceStatus.ignored.value:
            raise ValueError("motion_evidence_ignored")
        if evidence_model.status == MotionEvidenceStatus.promoted.value:
            raise ValueError("motion_evidence_already_promoted")
        if evidence_model.status != MotionEvidenceStatus.pending.value:
            raise ValueError("motion_evidence_promote_not_pending")
        if not payload.create_event and not payload.create_visit:
            raise ValueError("motion_evidence_promote_empty")
        if payload.create_visit and not payload.create_event:
            raise ValueError("motion_evidence_visit_requires_event")

        zone_model = (
            session.get(ZoneModel, evidence_model.zone_id)
            if evidence_model.zone_id is not None
            else None
        )
        if evidence_model.zone_id is not None and zone_model is None:
            raise ValueError("missing_zone")
        if zone_model is not None and zone_model.zone_type in {
            ZoneType.privacy.value,
            ZoneType.ignore.value,
        }:
            raise ValueError("motion_evidence_zone_blocked")

        stream_model = session.get(StreamModel, evidence_model.stream_id)
        if stream_model is None:
            raise ValueError("missing_stream")

        snapshot_media_asset_id = (
            payload.attach_snapshot_media_asset_id
            or evidence_model.snapshot_media_asset_id
        )
        asset_model: MediaAssetModel | None = None
        if snapshot_media_asset_id is not None:
            asset_model = session.get(MediaAssetModel, snapshot_media_asset_id)
            if asset_model is None:
                raise ValueError("missing_media_asset")
            if asset_model.stream_id != stream_model.id:
                raise ValueError("media_stream_mismatch")
            evidence_model.snapshot_media_asset_id = snapshot_media_asset_id

        created_at = datetime.now(UTC)
        event_id: str | None = None
        visit_id: str | None = None

        if payload.create_event:
            event_id = self._next_id(session, EventModel, "event-motion")
            if payload.event_title and payload.event_title.strip():
                event_title = payload.event_title.strip()
            elif zone_model is not None:
                event_title = f"Motion evidence in {zone_model.name}"
            else:
                event_title = f"Motion activity on {stream_model.name}"
            event_model = EventModel(
                id=event_id,
                stream_id=stream_model.id,
                title=event_title,
                event_type="motion_evidence",
                started_at=created_at,
                ended_at=created_at,
                primary_zone_id=zone_model.id if zone_model is not None else None,
                review_status=ReviewStatus.needs_review.value,
            )
            session.add(event_model)

        if payload.create_visit:
            visit_id = self._next_id(session, VisitModel, "visit-motion")
            visit_label = (
                payload.visit_label_hint.strip()
                if payload.visit_label_hint and payload.visit_label_hint.strip()
                else "unknown_animal"
            )
            visit_model = VisitModel(
                id=visit_id,
                event_id=event_id,
                subject_label=visit_label,
                species_guess=None,
                confidence=None,
                reviewed_label=None,
                review_status=ReviewStatus.needs_review.value,
                representative_media_path=(
                    asset_model.local_path if asset_model is not None else None
                ),
            )
            session.add(visit_model)

        if payload.notes and payload.notes.strip():
            promotion_note = payload.notes.strip()
            evidence_model.notes = (
                f"{evidence_model.notes}\nPromotion note: {promotion_note}"
                if evidence_model.notes
                else promotion_note
            )
        evidence_model.status = MotionEvidenceStatus.promoted.value
        evidence_model.promoted_event_id = event_id
        evidence_model.promoted_visit_id = visit_id
        session.flush()
        if visit_id is not None:
            visit_for_alert = session.get(VisitModel, visit_id)
            if visit_for_alert is not None:
                self._sync_review_alert(session, visit_for_alert, created_at)

        return MotionEvidencePromoteResponse(
            evidence=_motion_evidence_from_model(evidence_model),
            event_id=event_id,
            visit_id=visit_id,
        )

    def bulk_motion_evidence_action(
        self,
        payload: MotionEvidenceBulkActionRequest,
    ) -> MotionEvidenceBulkActionResponse:
        results: list[MotionEvidenceBulkActionResult] = []
        seen_ids: set[str] = set()

        with self.session_factory() as session:
            with session.begin():
                for raw_id in payload.motion_evidence_ids:
                    evidence_id = raw_id.strip()
                    if not evidence_id:
                        results.append(
                            _motion_evidence_bulk_result(
                                evidence_id=raw_id,
                                status=MotionEvidenceBulkActionResultStatus.skipped,
                                message="Blank Motion Evidence ID skipped.",
                            )
                        )
                        continue
                    if evidence_id in seen_ids:
                        results.append(
                            _motion_evidence_bulk_result(
                                evidence_id=evidence_id,
                                status=MotionEvidenceBulkActionResultStatus.skipped,
                                message="Duplicate Motion Evidence ID skipped.",
                            )
                        )
                        continue
                    seen_ids.add(evidence_id)

                    evidence_model = session.get(MotionEvidenceModel, evidence_id)
                    if evidence_model is None:
                        results.append(
                            _motion_evidence_bulk_result(
                                evidence_id=evidence_id,
                                status=MotionEvidenceBulkActionResultStatus.skipped,
                                message="Motion Evidence not found.",
                            )
                        )
                        continue

                    if payload.action == MotionEvidenceBulkAction.ignore:
                        result = self._bulk_ignore_motion_evidence(session, evidence_model)
                    else:
                        result = self._bulk_promote_motion_evidence(session, evidence_model)
                    results.append(result)

        return MotionEvidenceBulkActionResponse(
            action=payload.action,
            requested_count=len(payload.motion_evidence_ids),
            succeeded_count=sum(
                1
                for result in results
                if result.status == MotionEvidenceBulkActionResultStatus.succeeded
            ),
            skipped_count=sum(
                1
                for result in results
                if result.status == MotionEvidenceBulkActionResultStatus.skipped
            ),
            failed_count=sum(
                1
                for result in results
                if result.status == MotionEvidenceBulkActionResultStatus.failed
            ),
            results=results,
        )

    def _bulk_ignore_motion_evidence(
        self,
        session: Session,
        evidence_model: MotionEvidenceModel,
    ) -> MotionEvidenceBulkActionResult:
        if evidence_model.status == MotionEvidenceStatus.ignored.value:
            return _motion_evidence_bulk_result(
                evidence_id=evidence_model.id,
                status=MotionEvidenceBulkActionResultStatus.skipped,
                message="Motion Evidence is already ignored.",
            )
        if evidence_model.status == MotionEvidenceStatus.promoted.value:
            return _motion_evidence_bulk_result(
                evidence_id=evidence_model.id,
                status=MotionEvidenceBulkActionResultStatus.skipped,
                message="Promoted Motion Evidence cannot be ignored.",
            )
        if evidence_model.status != MotionEvidenceStatus.pending.value:
            return _motion_evidence_bulk_result(
                evidence_id=evidence_model.id,
                status=MotionEvidenceBulkActionResultStatus.skipped,
                message="Only pending Motion Evidence can be ignored.",
            )

        ignored = self._ignore_motion_evidence_model(session, evidence_model)
        return _motion_evidence_bulk_result(
            evidence_id=ignored.id,
            status=MotionEvidenceBulkActionResultStatus.succeeded,
            message="Motion Evidence ignored. No Event, Visit, or truth was created.",
        )

    def _bulk_promote_motion_evidence(
        self,
        session: Session,
        evidence_model: MotionEvidenceModel,
    ) -> MotionEvidenceBulkActionResult:
        if evidence_model.status == MotionEvidenceStatus.promoted.value:
            return _motion_evidence_bulk_result(
                evidence_id=evidence_model.id,
                status=MotionEvidenceBulkActionResultStatus.skipped,
                message="Motion Evidence has already been promoted.",
                created_event_id=evidence_model.promoted_event_id,
                created_visit_id=evidence_model.promoted_visit_id,
            )
        if evidence_model.status == MotionEvidenceStatus.ignored.value:
            return _motion_evidence_bulk_result(
                evidence_id=evidence_model.id,
                status=MotionEvidenceBulkActionResultStatus.skipped,
                message="Ignored Motion Evidence cannot be promoted.",
            )
        if evidence_model.status != MotionEvidenceStatus.pending.value:
            return _motion_evidence_bulk_result(
                evidence_id=evidence_model.id,
                status=MotionEvidenceBulkActionResultStatus.skipped,
                message="Only pending Motion Evidence can be promoted.",
            )

        try:
            promoted = self._promote_motion_evidence_model(
                session,
                evidence_model,
                MotionEvidencePromoteRequest(),
            )
        except ValueError as error:
            return _motion_evidence_bulk_result(
                evidence_id=evidence_model.id,
                status=MotionEvidenceBulkActionResultStatus.failed,
                message=_motion_evidence_bulk_failure_message(str(error)),
            )

        return _motion_evidence_bulk_result(
            evidence_id=promoted.evidence.id,
            status=MotionEvidenceBulkActionResultStatus.succeeded,
            message="Motion Evidence promoted to reviewable Event/Visit evidence, not truth.",
            created_event_id=promoted.event_id,
            created_visit_id=promoted.visit_id,
        )

    def create_species_suggestion(
        self,
        payload: SpeciesSuggestionCreateRequest,
    ) -> SpeciesSuggestionResponse:
        with self.session_factory() as session:
            with session.begin():
                return self._create_species_suggestion_in_session(session, payload)

    def _create_species_suggestion_in_session(
        self,
        session: Session,
        payload: SpeciesSuggestionCreateRequest,
    ) -> SpeciesSuggestionResponse:
        source_id = _clean_optional_text(payload.source_id)
        stream_id = _clean_optional_text(payload.stream_id)
        event_id = _clean_optional_text(payload.event_id)
        visit_id = _clean_optional_text(payload.visit_id)
        media_asset_id = _clean_optional_text(payload.media_asset_id)
        motion_evidence_id = _clean_optional_text(payload.motion_evidence_id)

        if source_id is not None and session.get(CameraSourceModel, source_id) is None:
            raise ValueError("missing_source")
        if stream_id is not None and session.get(StreamModel, stream_id) is None:
            raise ValueError("missing_stream")
        if event_id is not None and session.get(EventModel, event_id) is None:
            raise ValueError("missing_event")
        if visit_id is not None and session.get(VisitModel, visit_id) is None:
            raise ValueError("missing_visit")
        if (
            media_asset_id is not None
            and session.get(MediaAssetModel, media_asset_id) is None
        ):
            raise ValueError("missing_media_asset")
        if (
            motion_evidence_id is not None
            and session.get(MotionEvidenceModel, motion_evidence_id) is None
        ):
            raise ValueError("missing_motion_evidence")

        suggestion_model = SpeciesSuggestionModel(
            id=self._next_id(session, SpeciesSuggestionModel, "species-suggestion"),
            source_id=source_id,
            stream_id=stream_id,
            event_id=event_id,
            visit_id=visit_id,
            media_asset_id=media_asset_id,
            motion_evidence_id=motion_evidence_id,
            adapter_id=payload.adapter_id.strip(),
            adapter_name=payload.adapter_name.strip(),
            suggested_label=payload.suggested_label.strip(),
            suggested_common_name=_clean_optional_text(payload.suggested_common_name),
            suggested_scientific_name=_clean_optional_text(
                payload.suggested_scientific_name
            ),
            confidence=payload.confidence,
            rank=payload.rank,
            alternatives_json=json.dumps(payload.alternatives, sort_keys=True),
            evidence_region_json=(
                json.dumps(payload.evidence_region, sort_keys=True)
                if payload.evidence_region is not None
                else None
            ),
            status=SpeciesSuggestionStatus.pending.value,
            created_at=datetime.now(UTC),
            notes=_clean_optional_text(payload.notes),
            window_start_ms=payload.window_start_ms,
            window_end_ms=payload.window_end_ms,
            model_provenance_json=(
                json.dumps(payload.model_provenance, sort_keys=True)
                if payload.model_provenance is not None
                else None
            ),
        )
        session.add(suggestion_model)
        session.flush()
        return _species_suggestion_from_model(suggestion_model)

    def list_species_suggestions(
        self,
        *,
        status: SpeciesSuggestionStatus | None = None,
        visit_id: str | None = None,
        event_id: str | None = None,
        media_asset_id: str | None = None,
        suggested_label: str | None = None,
    ) -> list[SpeciesSuggestionResponse]:
        with self.session_factory() as session:
            query = select(SpeciesSuggestionModel)
            if status is not None:
                query = query.where(SpeciesSuggestionModel.status == status.value)
            normalized_visit_id = _clean_optional_text(visit_id)
            if normalized_visit_id is not None:
                query = query.where(SpeciesSuggestionModel.visit_id == normalized_visit_id)
            normalized_event_id = _clean_optional_text(event_id)
            if normalized_event_id is not None:
                query = query.where(SpeciesSuggestionModel.event_id == normalized_event_id)
            normalized_media_asset_id = _clean_optional_text(media_asset_id)
            if normalized_media_asset_id is not None:
                query = query.where(
                    SpeciesSuggestionModel.media_asset_id == normalized_media_asset_id
                )
            normalized_label = _clean_optional_text(suggested_label)
            if normalized_label is not None:
                query = query.where(SpeciesSuggestionModel.suggested_label == normalized_label)

            suggestion_models = session.scalars(
                query.order_by(
                    SpeciesSuggestionModel.created_at,
                    SpeciesSuggestionModel.rank,
                    SpeciesSuggestionModel.id,
                )
            ).all()
            return [
                _species_suggestion_from_model(suggestion)
                for suggestion in suggestion_models
            ]

    def get_species_suggestion(self, suggestion_id: str) -> SpeciesSuggestionResponse | None:
        with self.session_factory() as session:
            suggestion_model = session.get(SpeciesSuggestionModel, suggestion_id)
            return (
                _species_suggestion_from_model(suggestion_model)
                if suggestion_model
                else None
            )

    def update_species_suggestion_status(
        self,
        suggestion_id: str,
        payload: SpeciesSuggestionStatusUpdateRequest,
    ) -> SpeciesSuggestionResponse | None:
        with self.session_factory() as session:
            with session.begin():
                suggestion_model = session.get(SpeciesSuggestionModel, suggestion_id)
                if suggestion_model is None:
                    return None
                if suggestion_model.status != SpeciesSuggestionStatus.pending.value:
                    raise ValueError("species_suggestion_not_pending")

                suggestion_model.status = payload.status.value
                session.flush()
                return _species_suggestion_from_model(suggestion_model)

    def list_model_adapters(self) -> list[ModelAdapter]:
        return [adapter.model_copy(deep=True) for adapter in _model_adapters()]

    def get_model_adapter(self, adapter_id: str) -> ModelAdapter | None:
        adapter = _model_adapter_by_id(adapter_id)
        return adapter.model_copy(deep=True) if adapter else None

    def model_adapter_evaluation_summary(
        self,
        adapter_id: str | None = None,
    ) -> AdapterEvaluationSummary:
        adapter_filter = _model_adapter_by_id(adapter_id) if adapter_id else None
        if adapter_id is not None and adapter_filter is None:
            raise ValueError("missing_adapter")

        with self.session_factory() as session:
            proposal_models = session.scalars(
                select(DetectionProposalModel).order_by(
                    DetectionProposalModel.created_at,
                    DetectionProposalModel.id,
                )
            ).all()
            items: list[AdapterEvaluationItem] = []
            converted_count = 0

            for proposal_model in proposal_models:
                run_model = session.get(DetectionRunModel, proposal_model.run_id)
                adapter = _model_adapter_for_detection_run(run_model)
                if adapter_filter is not None and (
                    adapter is None or adapter.id != adapter_filter.id
                ):
                    continue

                if proposal_model.event_id is not None or proposal_model.visit_id is not None:
                    converted_count += 1

                items.append(
                    self._adapter_evaluation_item(
                        session,
                        proposal_model=proposal_model,
                        adapter=adapter,
                    )
                )

            outcome_counts = Counter(item.outcome for item in items)
            matched_count = outcome_counts[AdapterEvaluationOutcome.matched_reviewed_truth]
            mismatched_count = outcome_counts[AdapterEvaluationOutcome.mismatched_reviewed_truth]
            unknown_reviewed_count = outcome_counts[
                AdapterEvaluationOutcome.unknown_reviewed_label
            ]
            reviewed_count = matched_count + mismatched_count + unknown_reviewed_count
            unreviewed_count = (
                outcome_counts[AdapterEvaluationOutcome.awaiting_review]
                + outcome_counts[AdapterEvaluationOutcome.converted_needs_review]
            )
            match_denominator = matched_count + mismatched_count

            return AdapterEvaluationSummary(
                adapter_id=adapter_filter.id if adapter_filter else None,
                adapter_name=adapter_filter.name if adapter_filter else None,
                proposal_count=len(items),
                reviewed_count=reviewed_count,
                unreviewed_count=unreviewed_count,
                matched_count=matched_count,
                mismatched_count=mismatched_count,
                rejected_count=outcome_counts[AdapterEvaluationOutcome.rejected_evidence],
                converted_count=converted_count,
                unknown_reviewed_count=unknown_reviewed_count,
                match_rate=(
                    matched_count / match_denominator
                    if match_denominator > 0
                    else None
                ),
                items=items,
                generated_at=datetime.now(UTC),
                local_first_note=(
                    "Adapter evaluation is a local readiness signal. Proposal labels "
                    "are evidence; reviewed corrections are truth. Match rate only uses "
                    "reviewed non-unknown labels and is not a deployment score."
                ),
            )

    def model_readiness_summary(self) -> ModelReadinessSummary:
        coverage = self.dataset_coverage_summary()
        quality = self.dataset_quality_summary()
        evaluation = self.model_adapter_evaluation_summary()
        taxonomy_count = len(self.list_taxonomy_labels())
        adapters = self.list_model_adapters()
        adapter_contract_ready = bool(adapters) and all(
            not adapter.creates_review_truth for adapter in adapters
        )
        ready_for_first_detector_spike = (
            coverage.export_ready_count > 0
            and quality.high_count == 0
            and taxonomy_count > 0
            and adapter_contract_ready
        )

        return ModelReadinessSummary(
            reviewed_record_count=coverage.reviewed_record_count,
            export_ready_count=coverage.export_ready_count,
            dataset_quality_issue_count=quality.issue_count,
            high_quality_issue_count=quality.high_count,
            reviewed_species_count=coverage.reviewed_species_count,
            target_species_count=coverage.target_species_count,
            covered_target_species_count=coverage.covered_target_species_count,
            missing_target_species_count=coverage.missing_target_species_count,
            adapter_proposal_count=evaluation.proposal_count,
            adapter_reviewed_count=evaluation.reviewed_count,
            adapter_match_rate=evaluation.match_rate,
            ready_for_first_detector_spike=ready_for_first_detector_spike,
            recommended_next_step=_model_readiness_next_step(
                coverage=coverage,
                quality=quality,
                taxonomy_count=taxonomy_count,
                adapter_contract_ready=adapter_contract_ready,
            ),
            adapter_setup=[
                _model_adapter_setup_summary(adapter)
                for adapter in adapters
            ],
            checklist=_model_readiness_checklist(
                coverage=coverage,
                quality=quality,
                evaluation=evaluation,
                taxonomy_count=taxonomy_count,
                adapter_contract_ready=adapter_contract_ready,
            ),
            generated_at=datetime.now(UTC),
            local_first_note=(
                "Pre-model readiness combines reviewed local dataset coverage, QA, "
                "and adapter evidence guardrails. It does not run ML or inspect media. "
                "Future detectors must create DetectionProposal evidence and user "
                "corrections remain dataset truth."
            ),
        )

    def run_model_adapter(
        self,
        adapter_id: str,
        payload: ModelAdapterRunRequest,
        *,
        activity_focus: BoundingBox | None = None,
    ) -> ModelAdapterRunResult:
        adapter = _model_adapter_by_id(adapter_id)
        if adapter is None:
            raise ValueError("missing_adapter")
        if payload.adapter_id != adapter_id:
            raise ValueError("adapter_mismatch")
        if adapter_id == LOCAL_IMAGE_DETECTOR_ID:
            return self._run_local_image_detector_adapter(adapter, payload)
        if adapter_id == MEGADETECTOR_ADAPTER_ID:
            return self._run_megadetector_adapter(
                adapter,
                payload,
                activity_focus=activity_focus,
            )
        if adapter.kind == ModelAdapterKind.species_classifier:
            # The generic run response is detector-shaped. Species inference belongs
            # to the bounded Review Queue path and persists SpeciesSuggestion only.
            raise ValueError("species_classifier_review_queue_only")
        if adapter.status != ModelAdapterStatus.available:
            raise ValueError("adapter_unavailable")

        with self.session_factory() as session:
            with session.begin():
                asset_model = session.get(MediaAssetModel, payload.media_asset_id)
                if asset_model is None:
                    raise ValueError("missing_media_asset")
                if asset_model.media_type not in adapter.supported_media_types:
                    raise ValueError("unsupported_media_type")

                stream_model = session.get(StreamModel, asset_model.stream_id)
                if stream_model is None:
                    raise ValueError("missing_stream")

                zone_models: list[ZoneModel | None]
                if payload.zone_ids:
                    zone_models = []
                    seen_zone_ids: set[str] = set()
                    for zone_id in payload.zone_ids:
                        if zone_id in seen_zone_ids:
                            continue
                        seen_zone_ids.add(zone_id)
                        zone_models.append(
                            self._resolve_import_zone(session, zone_id, stream_model.id)
                        )
                else:
                    zone_models = [self._default_demo_zone(session, stream_model.id)]

                requested_labels = [
                    label.strip()
                    for label in payload.requested_labels or []
                    if label.strip()
                ] or ["unknown_bird"]
                created_at = datetime.now(UTC)
                run_model = DetectionRunModel(
                    id=self._next_id(session, DetectionRunModel, "detection-run"),
                    media_asset_id=asset_model.id,
                    source=DetectionSource.demo_rule.value,
                    summary=(
                        f"Model adapter contract run for {adapter.name} ({adapter.id}); "
                        "proposal evidence only, no media analysis."
                    ),
                    status=DetectionRunStatus.completed.value,
                    created_at=created_at,
                    completed_at=created_at,
                )
                session.add(run_model)

                proposal_models: list[DetectionProposalModel] = []
                for zone_model in zone_models:
                    for requested_label in requested_labels:
                        normalized_label = self._normalize_label_from_session(
                            session,
                            requested_label,
                        )
                        suggested_subject_label, suggested_species = (
                            self._adapter_subject_and_species(session, normalized_label)
                        )
                        proposal_model = DetectionProposalModel(
                            id=self._next_id(
                                session,
                                DetectionProposalModel,
                                "detection-proposal",
                            ),
                            run_id=run_model.id,
                            media_asset_id=asset_model.id,
                            stream_id=stream_model.id,
                            zone_id=zone_model.id if zone_model else None,
                            event_id=None,
                            visit_id=None,
                            label=normalized_label,
                            confidence=0.0,
                            bbox_json=None,
                            suggested_event_type="animal_visit",
                            suggested_subject_label=suggested_subject_label,
                            suggested_species=suggested_species,
                            status=DetectionProposalStatus.proposed.value,
                            notes=(
                                payload.notes.strip()
                                if payload.notes and payload.notes.strip()
                                else (
                                    "Placeholder analyzer generated proposal evidence; "
                                    "no model inspected media and no species confidence "
                                    "was produced. Review and correction remain required."
                                )
                            ),
                            created_at=created_at,
                            decided_at=None,
                        )
                        session.add(proposal_model)
                        session.flush()
                        proposal_models.append(proposal_model)

                session.flush()
                return ModelAdapterRunResult(
                    adapter=adapter.model_copy(deep=True),
                    detection_run=_detection_run_from_model(run_model),
                    proposals=[
                        _detection_proposal_from_model(proposal)
                        for proposal in proposal_models
                    ],
                    review_queue_count=len(self._review_queue_items(session)),
                    local_first_note=(
                        "Model adapters create proposal evidence, not review truth. "
                        "Users must convert, review, and correct proposals before exports, "
                        "coverage, or QA treat labels as dataset truth."
                    ),
                )

    def _run_local_image_detector_adapter(
        self,
        adapter: ModelAdapter,
        payload: ModelAdapterRunRequest,
    ) -> ModelAdapterRunResult:
        with self.session_factory() as session:
            with session.begin():
                asset_model = session.get(MediaAssetModel, payload.media_asset_id)
                if asset_model is None:
                    raise ValueError("missing_media_asset")
                if (
                    asset_model.media_type != "image"
                    or asset_model.content_type not in SUPPORTED_IMAGE_CONTENT_TYPES
                ):
                    raise ValueError("local_detector_unsupported_media_type")

                stream_model = session.get(StreamModel, asset_model.stream_id)
                if stream_model is None:
                    raise ValueError("missing_stream")

                if not Path(asset_model.local_path).exists():
                    raise ValueError("missing_media_file")

                zone_model: ZoneModel | None = None
                if payload.zone_ids:
                    zone_model = self._resolve_import_zone(
                        session,
                        payload.zone_ids[0],
                        stream_model.id,
                    )
                else:
                    zone_model = self._default_demo_zone(session, stream_model.id)

                try:
                    detector_proposals = run_local_image_detector(
                        local_path=asset_model.local_path,
                        content_type=asset_model.content_type,
                    )
                except LocalDetectorConfigurationError as error:
                    raise ValueError("local_detector_not_configured") from error
                except LocalDetectorRuntimeUnavailableError as error:
                    raise ValueError("local_detector_runtime_unavailable") from error
                except LocalDetectorUnsupportedMediaError as error:
                    if str(error) == "missing_media_file":
                        raise ValueError("missing_media_file") from error
                    raise ValueError("local_detector_unsupported_media_type") from error
                except LocalDetectorOutputError as error:
                    raise ValueError(str(error) or "unsupported_detector_output") from error

                created_at = datetime.now(UTC)
                run_model = DetectionRunModel(
                    id=self._next_id(session, DetectionRunModel, "detection-run"),
                    media_asset_id=asset_model.id,
                    source=DetectionSource.future_model.value,
                    summary=(
                        f"Model adapter contract run for {adapter.name} ({adapter.id}); "
                        "local image detector proposal evidence only."
                    ),
                    status=DetectionRunStatus.completed.value,
                    created_at=created_at,
                    completed_at=created_at,
                )
                session.add(run_model)
                session.flush()

                proposal_models: list[DetectionProposalModel] = []
                for detector_proposal in detector_proposals:
                    normalized_label = self._normalize_label_from_session(
                        session,
                        detector_proposal.label,
                    )
                    suggested_subject_label, suggested_species = (
                        self._adapter_subject_and_species(session, normalized_label)
                    )
                    proposal_model = DetectionProposalModel(
                        id=self._next_id(
                            session,
                            DetectionProposalModel,
                            "detection-proposal",
                        ),
                        run_id=run_model.id,
                        media_asset_id=asset_model.id,
                        stream_id=stream_model.id,
                        zone_id=zone_model.id if zone_model else None,
                        event_id=None,
                        visit_id=None,
                        label=normalized_label,
                        confidence=detector_proposal.confidence,
                        bbox_json=_detector_bbox_to_json(detector_proposal.bbox),
                        suggested_event_type="animal_visit",
                        suggested_subject_label=suggested_subject_label,
                        suggested_species=suggested_species,
                        status=DetectionProposalStatus.proposed.value,
                        notes=(
                            payload.notes.strip()
                            if payload.notes and payload.notes.strip()
                            else (
                                "Local image detector generated proposal evidence; "
                                "review and correction remain required."
                            )
                        ),
                        created_at=created_at,
                        decided_at=None,
                    )
                    session.add(proposal_model)
                    session.flush()
                    proposal_models.append(proposal_model)

                return ModelAdapterRunResult(
                    adapter=adapter.model_copy(deep=True),
                    detection_run=_detection_run_from_model(run_model),
                    proposals=[
                        _detection_proposal_from_model(proposal)
                        for proposal in proposal_models
                    ],
                    review_queue_count=len(self._review_queue_items(session)),
                    local_first_note=(
                        "Local image detector outputs are proposal evidence only. "
                        "Convert, review, and correct proposals before exports, coverage, "
                        "QA, or analytics treat labels as dataset truth."
                    )
                    if proposal_models
                    else (
                        "Local image detector completed with no proposal evidence. "
                        "No events, visits, review labels, or dataset truth were created."
                    ),
                )

    def _run_megadetector_adapter(
        self,
        adapter: ModelAdapter,
        payload: ModelAdapterRunRequest,
        *,
        activity_focus: BoundingBox | None,
    ) -> ModelAdapterRunResult:
        with self.session_factory() as session:
            with session.begin():
                asset_model = session.get(MediaAssetModel, payload.media_asset_id)
                if asset_model is None:
                    raise ValueError("missing_media_asset")
                if (
                    asset_model.media_type != "image"
                    or asset_model.content_type not in SUPPORTED_MEGADETECTOR_IMAGE_CONTENT_TYPES
                ):
                    raise ValueError("megadetector_unsupported_media_type")

                stream_model = session.get(StreamModel, asset_model.stream_id)
                if stream_model is None:
                    raise ValueError("missing_stream")

                if not Path(asset_model.local_path).exists():
                    raise ValueError("missing_media_file")

                zone_model: ZoneModel | None = None
                if payload.zone_ids:
                    zone_model = self._resolve_import_zone(
                        session,
                        payload.zone_ids[0],
                        stream_model.id,
                    )
                else:
                    zone_model = self._default_demo_zone(session, stream_model.id)

                if zone_model is not None and zone_model.zone_type in {
                    ZoneType.privacy.value,
                    ZoneType.ignore.value,
                }:
                    # Privacy and Ignore zones suppress analysis itself; they must never
                    # degrade to a full-frame detector run when no focus crop is allowed.
                    raise ValueError("megadetector_zone_suppressed")

                try:
                    detector_proposals = run_megadetector_on_image(
                        local_path=asset_model.local_path,
                        content_type=asset_model.content_type,
                        zone_context=zone_model.id if zone_model else None,
                        focus_box=_megadetector_activity_focus_box(activity_focus),
                    )
                except MegaDetectorModelFormatError as error:
                    raise ValueError("megadetector_model_format_unsupported") from error
                except MegaDetectorModelChecksumError as error:
                    raise ValueError("megadetector_model_checksum_mismatch") from error
                except MegaDetectorModelFileError as error:
                    raise ValueError("megadetector_model_file_missing") from error
                except MegaDetectorConfigurationError as error:
                    raise ValueError("megadetector_not_configured") from error
                except MegaDetectorRuntimeUnavailableError as error:
                    raise ValueError("megadetector_runtime_unavailable") from error
                except MegaDetectorUnsupportedMediaError as error:
                    if str(error) == "missing_media_file":
                        raise ValueError("missing_media_file") from error
                    raise ValueError("megadetector_unsupported_media_type") from error
                except MegaDetectorOutputError as error:
                    raise ValueError(str(error) or "unsupported_detector_output") from error

                created_at = datetime.now(UTC)
                run_model = DetectionRunModel(
                    id=self._next_id(session, DetectionRunModel, "detection-run"),
                    media_asset_id=asset_model.id,
                    source=DetectionSource.future_model.value,
                    summary=(
                        f"Model adapter contract run for {adapter.name} ({adapter.id}); "
                        "MegaDetector-family proposal evidence only."
                    ),
                    status=DetectionRunStatus.completed.value,
                    created_at=created_at,
                    completed_at=created_at,
                )
                session.add(run_model)
                session.flush()

                proposal_models: list[DetectionProposalModel] = []
                for detector_proposal in detector_proposals:
                    mapped_label = normalize_megadetector_label(detector_proposal.label)
                    normalized_label = self._normalize_label_from_session(session, mapped_label)
                    suggested_subject_label, suggested_species = (
                        self._adapter_subject_and_species(session, normalized_label)
                    )
                    proposal_model = DetectionProposalModel(
                        id=self._next_id(
                            session,
                            DetectionProposalModel,
                            "detection-proposal",
                        ),
                        run_id=run_model.id,
                        media_asset_id=asset_model.id,
                        stream_id=stream_model.id,
                        zone_id=zone_model.id if zone_model else None,
                        event_id=None,
                        visit_id=None,
                        label=normalized_label,
                        confidence=detector_proposal.confidence,
                        bbox_json=_detector_bbox_to_json(detector_proposal.bbox),
                        suggested_event_type="animal_visit",
                        suggested_subject_label=suggested_subject_label,
                        suggested_species=suggested_species,
                        status=DetectionProposalStatus.proposed.value,
                        notes=(
                            payload.notes.strip()
                            if payload.notes and payload.notes.strip()
                            else (
                                "MegaDetector-family adapter generated proposal evidence; "
                                "review and correction remain required."
                            )
                        ),
                        created_at=created_at,
                        decided_at=None,
                    )
                    session.add(proposal_model)
                    session.flush()
                    proposal_models.append(proposal_model)

                return ModelAdapterRunResult(
                    adapter=adapter.model_copy(deep=True),
                    detection_run=_detection_run_from_model(run_model),
                    proposals=[
                        _detection_proposal_from_model(proposal)
                        for proposal in proposal_models
                    ],
                    review_queue_count=len(self._review_queue_items(session)),
                    local_first_note=(
                        "MegaDetector-family outputs are animal/person/vehicle proposal "
                        "evidence only. Convert, review, and correct proposals before "
                        "exports, coverage, QA, or analytics treat labels as dataset truth."
                    )
                    if proposal_models
                    else (
                        "MegaDetector-family adapter completed with no proposal evidence. "
                        "No events, visits, review labels, or dataset truth were created."
                    ),
                )

    def list_detection_runs(self) -> list[DetectionRun]:
        with self.session_factory() as session:
            runs = session.scalars(
                select(DetectionRunModel).order_by(
                    DetectionRunModel.created_at,
                    DetectionRunModel.id,
                )
            ).all()
            return [_detection_run_from_model(run) for run in runs]

    def get_detection_run(self, run_id: str) -> DetectionRun | None:
        with self.session_factory() as session:
            run = session.get(DetectionRunModel, run_id)
            return _detection_run_from_model(run) if run else None

    def create_detection_run(self, payload: DetectionRunCreate) -> DetectionRun:
        with self.session_factory() as session:
            with session.begin():
                if session.get(MediaAssetModel, payload.media_asset_id) is None:
                    raise ValueError("missing_media_asset")

                created_at = datetime.now(UTC)
                run_model = DetectionRunModel(
                    id=self._next_id(session, DetectionRunModel, "detection-run"),
                    media_asset_id=payload.media_asset_id,
                    source=payload.source.value,
                    summary=(
                        payload.summary.strip()
                        if payload.summary and payload.summary.strip()
                        else None
                    ),
                    status=DetectionRunStatus.completed.value,
                    created_at=created_at,
                    completed_at=created_at,
                )
                session.add(run_model)
                session.flush()
                return _detection_run_from_model(run_model)

    def create_demo_detection_run(
        self,
        payload: DemoDetectionRunCreate,
    ) -> DemoDetectionRunResult:
        with self.session_factory() as session:
            with session.begin():
                asset_model = session.get(MediaAssetModel, payload.media_asset_id)
                if asset_model is None:
                    raise ValueError("missing_media_asset")

                stream_model = session.get(StreamModel, asset_model.stream_id)
                if stream_model is None:
                    raise ValueError("missing_stream")

                zone_model = (
                    self._resolve_import_zone(session, payload.zone_id, stream_model.id)
                    if payload.zone_id
                    else self._default_demo_zone(session, stream_model.id)
                )
                created_at = datetime.now(UTC)
                run_model = DetectionRunModel(
                    id=self._next_id(session, DetectionRunModel, "detection-run"),
                    media_asset_id=asset_model.id,
                    source=DetectionSource.demo_rule.value,
                    summary="Demo detector proposal generation without media analysis.",
                    status=DetectionRunStatus.completed.value,
                    created_at=created_at,
                    completed_at=created_at,
                )
                proposal_model = DetectionProposalModel(
                    id=self._next_id(session, DetectionProposalModel, "detection-proposal"),
                    run_id=run_model.id,
                    media_asset_id=asset_model.id,
                    stream_id=stream_model.id,
                    zone_id=zone_model.id if zone_model else None,
                    event_id=None,
                    visit_id=None,
                    label=payload.label.strip() or "bird",
                    confidence=payload.confidence,
                    bbox_json=None,
                    suggested_event_type="animal_visit",
                    suggested_subject_label=(
                        payload.suggested_subject_label.strip() or "unknown_bird"
                    ),
                    suggested_species=(
                        payload.suggested_species.strip()
                        if payload.suggested_species and payload.suggested_species.strip()
                        else None
                    ),
                    status=DetectionProposalStatus.proposed.value,
                    notes=(
                        payload.notes.strip()
                        if payload.notes and payload.notes.strip()
                        else "Demo proposal generated without running a model."
                    ),
                    created_at=created_at,
                    decided_at=None,
                )
                session.add_all([run_model, proposal_model])
                session.flush()
                return DemoDetectionRunResult(
                    detection_run=_detection_run_from_model(run_model),
                    proposals=[_detection_proposal_from_model(proposal_model)],
                    review_queue_count=len(self._review_queue_items(session)),
                )

