    def create_detection_proposal(
        self,
        payload: DetectionProposalCreate,
    ) -> DetectionProposal:
        with self.session_factory() as session:
            with session.begin():
                asset_model = session.get(MediaAssetModel, payload.media_asset_id)
                if asset_model is None:
                    raise ValueError("missing_media_asset")

                stream_id = payload.stream_id or asset_model.stream_id
                stream_model = session.get(StreamModel, stream_id)
                if stream_model is None:
                    raise ValueError("missing_stream")
                if asset_model.stream_id != stream_id:
                    raise ValueError("media_stream_mismatch")

                zone_model = self._resolve_import_zone(session, payload.zone_id, stream_id)
                created_at = datetime.now(UTC)
                run_model = DetectionRunModel(
                    id=self._next_id(session, DetectionRunModel, "detection-run"),
                    media_asset_id=asset_model.id,
                    source=DetectionSource.manual.value,
                    summary="Manual detection proposal from local media input.",
                    status=DetectionRunStatus.completed.value,
                    created_at=created_at,
                    completed_at=created_at,
                )
                proposal_model = DetectionProposalModel(
                    id=self._next_id(session, DetectionProposalModel, "detection-proposal"),
                    run_id=run_model.id,
                    media_asset_id=asset_model.id,
                    stream_id=stream_model.id,
                    zone_id=zone_model.id if zone_model else None,
                    event_id=None,
                    visit_id=None,
                    label=payload.label.strip() or "unknown_animal",
                    confidence=payload.confidence,
                    bbox_json=_bbox_to_json(payload.bbox),
                    suggested_event_type=payload.suggested_event_type.strip() or "animal_visit",
                    suggested_subject_label=(
                        payload.suggested_subject_label.strip() or "unknown_animal"
                    ),
                    suggested_species=(
                        payload.suggested_species.strip()
                        if payload.suggested_species and payload.suggested_species.strip()
                        else None
                    ),
                    status=DetectionProposalStatus.proposed.value,
                    notes=payload.notes.strip() if payload.notes and payload.notes.strip() else None,
                    created_at=created_at,
                    decided_at=None,
                )
                session.add_all([run_model, proposal_model])
                session.flush()
                return _detection_proposal_from_model(proposal_model)

    def decide_detection_proposal(
        self,
        proposal_id: str,
        payload: DetectionProposalDecisionCreate,
    ) -> DetectionProposalDecisionResult | None:
        with self.session_factory() as session:
            with session.begin():
                proposal_model = session.get(DetectionProposalModel, proposal_id)
                if proposal_model is None:
                    return None
                if proposal_model.status != DetectionProposalStatus.proposed.value:
                    raise ValueError("proposal_already_decided")

                event: Event | None = None
                visit: Visit | None = None
                decided_at = datetime.now(UTC)

                if payload.notes and payload.notes.strip():
                    proposal_model.notes = _merge_notes(proposal_model.notes, payload.notes.strip())

                if payload.decision == DetectionProposalDecision.reject:
                    proposal_model.status = DetectionProposalStatus.rejected.value
                    proposal_model.decided_at = decided_at
                elif payload.decision in {
                    DetectionProposalDecision.accept,
                    DetectionProposalDecision.convert_to_event,
                }:
                    event, visit = self._create_detection_proposal_review_records(
                        session,
                        proposal_model=proposal_model,
                        payload=payload,
                        created_at=decided_at,
                    )
                    proposal_model.status = (
                        DetectionProposalStatus.accepted.value
                        if payload.decision == DetectionProposalDecision.accept
                        else DetectionProposalStatus.converted.value
                    )
                    proposal_model.event_id = event.id
                    proposal_model.visit_id = visit.id
                    proposal_model.decided_at = decided_at
                else:
                    raise ValueError("unsupported_decision")

                session.flush()
                return DetectionProposalDecisionResult(
                    proposal=_detection_proposal_from_model(proposal_model),
                    event=event,
                    visit=visit,
                    review_queue_count=len(self._review_queue_items(session)),
                    analytics=self._analytics_summary(session),
                )

    def create_media_import(
        self,
        *,
        content: bytes,
        original_filename: str,
        content_type: str,
        stream_id: str | None = None,
        zone_id: str | None = None,
        title: str | None = None,
        subject_label: str = "unknown_animal",
        species_guess: str | None = None,
        notes: str | None = None,
    ) -> MediaImportResult:
        if not content:
            raise ValueError("empty_file")

        media_type = SUPPORTED_MEDIA_CONTENT_TYPES.get(content_type)
        if media_type is None:
            raise ValueError("unsupported_content_type")

        with self.session_factory() as session:
            with session.begin():
                stream_model = self._resolve_import_stream(session, stream_id)
                zone_model = self._resolve_import_zone(session, zone_id, stream_model.id)
                media_asset, event, visit = self._create_media_product_records(
                    session,
                    stream_model=stream_model,
                    zone_model=zone_model,
                    content=content,
                    original_filename=original_filename,
                    content_type=content_type,
                    media_type=media_type,
                    title=title,
                    event_type="manual_media_import",
                    default_title="Imported media observation",
                    subject_label=subject_label,
                    species_guess=species_guess,
                    notes=notes,
                )

                return MediaImportResult(
                    media_asset=media_asset,
                    event=event,
                    visit=visit,
                    stream=_stream_from_model(stream_model),
                    review_queue_count=len(self._review_queue_items(session)),
                )

    def preview_folder_import(self, folder_path: str) -> FolderImportPreview:
        if not folder_path.strip():
            raise ValueError("folder_required")
        folder = _folder_path(folder_path)
        return self._preview_folder_import_for_path(folder)

    def import_folder_media(self, payload: FolderImportCreate) -> FolderImportResult:
        if not payload.folder_path.strip():
            raise ValueError("folder_required")
        folder = _folder_path(payload.folder_path)
        preview = self._preview_folder_import_for_path(folder)
        candidates = preview.supported_files[: payload.limit] if payload.limit else preview.supported_files
        skipped_files = list(preview.skipped_files)

        media_assets: list[MediaAsset] = []
        events: list[Event] = []
        visits: list[Visit] = []

        with self.session_factory() as session:
            with session.begin():
                stream_model = self._resolve_import_stream(session, payload.stream_id)
                zone_model = self._resolve_import_zone(session, payload.zone_id, stream_model.id)

                for candidate in candidates:
                    source_path = Path(candidate.path)
                    try:
                        content = source_path.read_bytes()
                    except OSError:
                        skipped_files.append(
                            FolderImportSkippedFile(
                                filename=candidate.filename,
                                reason="read_error",
                            )
                        )
                        continue

                    if not content:
                        skipped_files.append(
                            FolderImportSkippedFile(
                                filename=candidate.filename,
                                reason="empty_file",
                            )
                        )
                        continue

                    media_asset, event, visit = self._create_media_product_records(
                        session,
                        stream_model=stream_model,
                        zone_model=zone_model,
                        content=content,
                        original_filename=candidate.filename,
                        content_type=candidate.content_type,
                        media_type=candidate.media_type,
                        title=f"Imported folder media: {candidate.filename}",
                        event_type="folder_media_import",
                        default_title="Imported folder media",
                        subject_label=payload.subject_label,
                        species_guess=payload.species_guess,
                        notes=payload.notes,
                    )
                    media_assets.append(media_asset)
                    events.append(event)
                    visits.append(visit)

                return FolderImportResult(
                    folder_path=str(folder),
                    imported_count=len(media_assets),
                    skipped_count=len(skipped_files),
                    media_assets=media_assets,
                    events=events,
                    visits=visits,
                    skipped_files=skipped_files,
                    review_queue_count=len(self._review_queue_items(session)),
                )

    def list_review_labels(self) -> list[ReviewLabel]:
        with self.session_factory() as session:
            labels = session.scalars(
                select(ReviewLabelModel).order_by(ReviewLabelModel.created_at, ReviewLabelModel.id)
            ).all()
            return [
                _review_label_from_model(label)
                for label in self._effective_review_label_models(labels)
                if label.target_type != "visit"
                or (
                    (visit := session.get(VisitModel, label.target_id)) is not None
                    and not visit.is_superseded
                )
            ]

    def review_labels_for_event(self, event_id: str) -> list[ReviewLabel]:
        with self.session_factory() as session:
            return self._review_labels_for_event(session, event_id)

    def review_labels_for_visit(self, visit_id: str) -> list[ReviewLabel]:
        with self.session_factory() as session:
            return self._review_labels_for_visit(session, visit_id)

    def visit_review_history(self, visit_id: str) -> VisitReviewHistory | None:
        with self.session_factory() as session:
            visit = session.get(VisitModel, visit_id)
            if visit is None:
                return None
            return self._visit_review_history_from_session(session, visit)

    def review_labels_for_event_tree(self, event_id: str) -> list[ReviewLabel]:
        with self.session_factory() as session:
            visit_ids = {visit.id for visit in self._visits_for_event(session, event_id)}
            labels = session.scalars(
                select(ReviewLabelModel).order_by(ReviewLabelModel.created_at, ReviewLabelModel.id)
            ).all()
            return [
                _review_label_from_model(label)
                for label in self._effective_review_label_models(labels)
                if (label.target_type == "event" and label.target_id == event_id)
                or (label.target_type == "visit" and label.target_id in visit_ids)
            ]

    @staticmethod
    def _reviewer_identity_with_signed_in_default(
        review_origin: str | None, reviewer_identity: str | None, acting_user: CurrentUser | None,
    ) -> str | None:
        """Fill in a blank `reviewer_identity` with the signed-in actor's
        own display name -- but ONLY for an explicitly `"human"`-origin
        request that omitted it, never for any other origin (including a
        merely-omitted one) and never overriding a value the client did
        supply. Confirmed via direct audit of the existing test suite that
        no test asserts `reviewer_identity` stays blank for this exact
        case -- see docs/local-identity-multi-user-contract.md "Review
        attribution". `review_origin` itself is never touched here or
        anywhere else in this class: the product's own interactive review
        UI already stamps it `"human"` at the API client boundary
        (`web/src/api/client.ts`), so this only ever activates for a real
        signed-in session's own request, not a client asserting authority
        it doesn't have.
        """

        if reviewer_identity or review_origin != "human" or acting_user is None:
            return reviewer_identity
        return acting_user.display_name

    def create_review_label(
        self,
        payload: ReviewCorrectionCreate,
        created_at: datetime | None = None,
        *,
        acting_user: CurrentUser | None = None,
    ) -> ReviewCorrectionResult:
        """The initial confirm/correct on a Visit or Event. `acting_user` is
        supplied only by an authenticated HTTP handler in `mockingbird.api.
        main`; when present it durably attaches `reviewed_by_user_id` --
        the new, trustworthy actor reference (see `ReviewLabelModel.
        reviewed_by_user_id`'s docstring). It deliberately does NOT also
        override `payload.review_origin`/`.reviewer_identity`: the
        product's own interactive review UI already stamps `review_origin:
        "human"` itself at the API client boundary (`web/src/api/client.ts`
        -- confirmed, not assumed), so those two fields stay pure
        passthrough here exactly as before this milestone, which is also
        what keeps every existing HTTP-level test (`ReviewCorrectionCreate`
        payloads constructing `agent_diagnostic`/`imported_curated`/
        omitted-origin cases) completely unaffected by `acting_user`'s
        presence.

        `payload.expected_state_token`, when supplied, closes this
        endpoint's own optimistic-concurrency gap by reusing the exact
        `_review_state_token`/`ReviewRevisionConflictError` mechanism
        `revise_visit_review`/`reopen_visit_review` already use -- see
        `ReviewCorrectionCreate.expected_state_token`'s own docstring for
        why it stays optional rather than required.
        """

        with self.session_factory() as session:
            with session.begin():
                if payload.expected_state_token is not None:
                    current_token = self._review_state_token(session, payload.target_type, payload.target_id)
                    if current_token != payload.expected_state_token:
                        raise ReviewRevisionConflictError("stale_reviewed_visit")
                return self._create_review_label_result_in_session(
                    session,
                    payload,
                    created_at,
                    review_origin=payload.review_origin,
                    reviewer_identity=self._reviewer_identity_with_signed_in_default(
                        payload.review_origin, payload.reviewer_identity, acting_user
                    ),
                    reviewed_by_user_id=acting_user.id if acting_user is not None else None,
                )

    def revise_visit_review(
        self,
        visit_id: str,
        payload: VisitReviewRevisionCreate,
        *,
        acting_user: CurrentUser | None = None,
    ) -> VisitReviewRevisionResponse:
        # See `create_review_label`'s docstring: `acting_user` only sets
        # `reviewed_by_user_id`, never `review_origin`/`reviewer_identity`.
        reviewed_by_user_id = acting_user.id if acting_user is not None else None
        with self.session_factory() as session:
            with session.begin():
                existing = session.scalar(
                    select(ReviewLabelModel).where(
                        ReviewLabelModel.revision_idempotency_key == payload.idempotency_key
                    )
                )
                normalized_label = self._normalize_label_from_session(session, payload.label)
                normalized_notes = _clean_optional_text(payload.notes)
                if existing is not None:
                    if (
                        existing.review_action != "revision"
                        or existing.target_type != "visit"
                        or existing.target_id != visit_id
                        or existing.label != normalized_label
                        or _clean_optional_text(existing.notes) != normalized_notes
                    ):
                        raise ReviewRevisionConflictError("review_revision_idempotency_conflict")
                    return VisitReviewRevisionResponse(
                        result=self._review_correction_result_for_model(session, existing),
                        review_state_token=self._review_state_token(session, "visit", visit_id),
                        idempotent=True,
                    )

                visit = session.get(VisitModel, visit_id)
                if visit is None:
                    raise ValueError("missing_visit")
                if visit.is_superseded:
                    raise ReviewRevisionConflictError("review_revision_unavailable")
                event = session.get(EventModel, visit.event_id)
                if event is None:
                    raise ValueError("missing_event")
                if self._review_state_token(session, "visit", visit.id) != payload.expected_state_token:
                    raise ReviewRevisionConflictError("stale_reviewed_visit")
                current = self._current_effective_review_label_model_for_visit(session, visit.id)
                if visit.review_status != ReviewStatus.reviewed.value or current is None:
                    raise ReviewRevisionConflictError("review_revision_unavailable")
                if not review_provenance.is_authority_eligible(payload.review_origin):
                    # Unlike plain correction, a revision has no meaningful
                    # "recorded but not applied" behavior -- its only
                    # purpose is to replace existing reviewed truth, so a
                    # non-authoritative attempt fails loudly rather than
                    # silently no-op'ing (see Part 11: only an
                    # authority-eligible Review Decision may correct
                    # durable reviewed truth).
                    raise ReviewRevisionConflictError("review_revision_requires_authority")

                # A revision is a new explicit truth row. It never changes the prior label.
                result = self._create_review_label_result_in_session(
                    session,
                    ReviewCorrectionCreate(
                        target_type="visit",
                        target_id=visit.id,
                        label=normalized_label,
                        notes=normalized_notes,
                    ),
                    supersedes_review_label_id=current.id,
                    review_action="revision",
                    revision_idempotency_key=payload.idempotency_key,
                    review_origin=payload.review_origin,
                    reviewer_identity=self._reviewer_identity_with_signed_in_default(
                        payload.review_origin, payload.reviewer_identity, acting_user
                    ),
                    reviewed_by_user_id=reviewed_by_user_id,
                )
                return VisitReviewRevisionResponse(
                    result=result,
                    review_state_token=self._review_state_token(session, "visit", visit.id),
                )

    def reopen_visit_review(
        self,
        visit_id: str,
        payload: VisitReviewReopenCreate,
        *,
        acting_user: CurrentUser | None = None,
    ) -> VisitReviewReopenResponse:
        # See `create_review_label`'s docstring: `acting_user` only sets
        # `reviewed_by_user_id`, never `review_origin`/`reviewer_identity`.
        reviewed_by_user_id = acting_user.id if acting_user is not None else None
        with self.session_factory() as session:
            with session.begin():
                existing = session.scalar(
                    select(ReviewLabelModel).where(
                        ReviewLabelModel.revision_idempotency_key == payload.idempotency_key
                    )
                )
                normalized_notes = _clean_optional_text(payload.notes)
                if existing is not None:
                    if (
                        existing.review_action != "reopen"
                        or existing.target_type != "visit"
                        or existing.target_id != visit_id
                        or _clean_optional_text(existing.notes) != normalized_notes
                    ):
                        raise ReviewRevisionConflictError("review_reopen_idempotency_conflict")
                    return self._visit_review_reopen_response(session, visit_id, idempotent=True)

                visit = session.get(VisitModel, visit_id)
                if visit is None:
                    raise ValueError("missing_visit")
                if visit.is_superseded:
                    raise ReviewRevisionConflictError("review_reopen_unavailable")
                event = session.get(EventModel, visit.event_id)
                if event is None:
                    raise ValueError("missing_event")
                if self._review_state_token(session, "visit", visit.id) != payload.expected_state_token:
                    raise ReviewRevisionConflictError("stale_reviewed_visit")
                current = self._current_effective_review_label_model_for_visit(session, visit.id)
                if visit.review_status != ReviewStatus.reviewed.value or current is None:
                    raise ReviewRevisionConflictError("review_reopen_unavailable")
                if not review_provenance.is_authority_eligible(payload.review_origin):
                    # Same reasoning as revise_visit_review above: reopening
                    # is purely a truth mutation with no non-authoritative
                    # equivalent, so it fails loudly instead of silently
                    # doing nothing.
                    raise ReviewRevisionConflictError("review_reopen_requires_authority")

                # Reopen replaces effective truth with an append-only transition; media and evidence stay put.
                session.add(
                    ReviewLabelModel(
                        id=self._next_id(session, ReviewLabelModel, "review-label"),
                        target_type="visit",
                        target_id=visit.id,
                        label=current.label,
                        notes=normalized_notes,
                        created_at=datetime.now(UTC),
                        supersedes_review_label_id=current.id,
                        review_action="reopen",
                        revision_idempotency_key=payload.idempotency_key,
                        review_origin=payload.review_origin,
                        reviewer_identity=_clean_optional_text(
                            self._reviewer_identity_with_signed_in_default(
                                payload.review_origin, payload.reviewer_identity, acting_user
                            )
                        ),
                        reviewed_by_user_id=reviewed_by_user_id,
                    )
                )
                prior_reviewed_label = visit.reviewed_label
                visit.reviewed_label = None
                visit.review_status = ReviewStatus.needs_review.value
                event.review_status = ReviewStatus.needs_review.value
                now = datetime.now(UTC)
                # Site-Specific Learning & Local Adaptation v1
                # (reversibility -- see "Reversibility" in docs/scene-
                # confusor-suspicion-contract.md and Phase 8 requirement #4
                # of the governing milestone brief): reopening deliberately
                # returns this Visit to `needs_review` -- it no longer
                # carries authoritative reviewed truth, so whatever
                # `current` (the label being reopened) had previously
                # contributed to a scene-confusor region's counts must be
                # retracted now, not left stale indefinitely. This is the
                # one path in this whole interaction that only ever
                # retracts -- reopening creates no new reviewed truth, so
                # there is nothing to increment afterward.
                self._retract_scene_confusor_region_contribution(session, current, now=now)
                self._sync_review_alert(session, visit, now)
                # Everyday Discovery / Product Experience v2 (Phase L): this
                # Visit no longer carries `prior_reviewed_label` -- resolve
                # any "first confirmed local observation" milestone alert for
                # it that no other reviewed Visit still earns. See
                # `_maybe_resolve_stale_journal_milestone_alert`'s docstring.
                # The flush before it is required, not cosmetic: that helper
                # counts remaining reviewed Visits with a raw `session.
                # scalar(select(...))`, which does not implicitly see this
                # session's own pending `reviewed_label = None` write until
                # flushed.
                if prior_reviewed_label:
                    session.flush()
                    self._maybe_resolve_stale_journal_milestone_alert(
                        session, old_label=prior_reviewed_label, now=now,
                    )
                session.flush()
                return self._visit_review_reopen_response(session, visit.id)

    def reclassify_review_label_provenance(
        self,
        review_label_id: str,
        *,
        review_origin: str,
        reviewer_identity: str,
        expected_current_review_origin: str | None = None,
    ) -> ReviewLabel:
        """Bounded maintenance operation (Review Decision Provenance / Truth
        Boundary v1, Part 8; see docs/review-decision-provenance-contract.md
        and scripts/repair_review_label_provenance.py): durably repair
        exactly one existing ReviewLabel row's provenance, then recompute
        the resulting Visit/Event truth state from scratch.

        This exists for a narrow, real, already-identified situation: a
        row that was written through this exact `agent_diagnostic`-shaped
        gap before it was closed (an LLM/agent's own visual inspection,
        submitted through the real `POST /api/review-labels` path,
        indistinguishable at the time from a genuine human correction) and
        therefore incorrectly flipped its target to `review_status=
        "reviewed"`. It never deletes the row, its `label`, or its
        `notes` -- "Do not delete or pretend they never happened" applies
        to a maintenance repair exactly as it does to a live product
        action. `expected_current_review_origin` is an optional safety
        check (mirrors the idempotency-key convention used elsewhere in
        this file) so a repair script can assert the row is still in the
        state it already inspected before mutating it, and so re-running
        the same repair twice fails loudly on the second attempt instead
        of silently re-deriving state from an already-repaired row.
        """

        review_provenance.validate_review_origin(review_origin, reviewer_identity)
        with self.session_factory() as session:
            with session.begin():
                label_model = session.get(ReviewLabelModel, review_label_id)
                if label_model is None:
                    raise ValueError("missing_review_label")
                if (
                    expected_current_review_origin is not None
                    and label_model.review_origin != expected_current_review_origin
                ):
                    raise ReviewProvenanceConflictError("review_label_provenance_already_changed")

                label_model.review_origin = review_origin
                label_model.reviewer_identity = _clean_optional_text(reviewer_identity)
                session.flush()

                if label_model.target_type == "visit":
                    self._recompute_visit_review_truth(session, label_model.target_id)
                    now = datetime.now(UTC)
                    visit_model = session.get(VisitModel, label_model.target_id)
                    if visit_model is not None:
                        # Reconcile the "ready for review"/journal-milestone
                        # alerts the same way a live correction would --
                        # `_sync_review_alert` is fully reconciling in both
                        # directions (creates/refreshes when needs_review,
                        # resolves when reviewed), so this is safe to call
                        # unconditionally after either a promotion or a
                        # demotion.
                        self._sync_review_alert(session, visit_model, now)
                        self._sync_journal_milestone_alert(session, visit_model, now)
                elif label_model.target_type == "event":
                    self._recompute_event_only_review_truth(session, label_model.target_id)

                session.flush()
                return _review_label_from_model(label_model)

    def _recompute_visit_review_truth(self, session: Session, visit_id: str) -> None:
        """Re-derive `VisitModel.review_status`/`reviewed_label` (and its
        parent Event's rollup) from the Visit's own current *authoritative*
        ReviewLabel rows, from scratch -- used only by the bounded
        provenance-repair path above. A repaired row that turns out
        non-authoritative can no longer justify a "reviewed" status it
        previously (incorrectly) established; if some other authoritative
        row already exists for this Visit, that one becomes effective
        instead, exactly as `_create_review_label_in_session` would have
        left it had the repaired row never been authoritative in the
        first place."""

        visit_model = session.get(VisitModel, visit_id)
        if visit_model is None or visit_model.is_superseded:
            return
        effective = self._current_effective_review_label_model_for_visit(session, visit_id)
        if effective is None:
            visit_model.reviewed_label = None
            visit_model.review_status = ReviewStatus.needs_review.value
        else:
            visit_model.reviewed_label = self._normalize_label_from_session(session, effective.label)
            visit_model.review_status = ReviewStatus.reviewed.value

        event_model = session.get(EventModel, visit_model.event_id)
        if event_model is None:
            return
        child_visits = self._visit_models_for_event(session, event_model.id)
        if child_visits and all(
            child_visit.review_status != ReviewStatus.needs_review.value for child_visit in child_visits
        ):
            event_model.review_status = ReviewStatus.reviewed.value
        elif child_visits:
            # At least one child Visit is not reviewed -- unlike the
            # create path (which only ever *promotes* an Event to
            # reviewed), a repair can also legitimately *demote* one: a
            # sibling Visit's only reviewed status may itself have come
            # from the very row just repaired.
            event_model.review_status = ReviewStatus.needs_review.value

    def _recompute_event_only_review_truth(self, session: Session, event_id: str) -> None:
        """Event-level equivalent of `_recompute_visit_review_truth` for a
        Visit-less Event (mirrors `_event_is_dataset_ready`'s event-only
        branch)."""

        event_model = session.get(EventModel, event_id)
        if event_model is None:
            return
        if self._visit_models_for_event(session, event_id):
            return
        effective = self._latest_label(self._review_labels_for_event(session, event_id))
        event_model.review_status = (
            ReviewStatus.reviewed.value if effective is not None else ReviewStatus.needs_review.value
        )

    def _create_review_label_result_in_session(
        self,
        session: Session,
        payload: ReviewCorrectionCreate,
        created_at: datetime | None = None,
        *,
        fast_review_session_id: str | None = None,
        fast_review_idempotency_key: str | None = None,
        supersedes_review_label_id: str | None = None,
        review_action: str | None = None,
        revision_idempotency_key: str | None = None,
        review_origin: str | None = None,
        reviewer_identity: str | None = None,
        reviewed_by_user_id: str | None = None,
    ) -> ReviewCorrectionResult:
        review_label, visit, event = self._create_review_label_in_session(
            session,
            payload,
            created_at,
            fast_review_session_id=fast_review_session_id,
            fast_review_idempotency_key=fast_review_idempotency_key,
            supersedes_review_label_id=supersedes_review_label_id,
            review_action=review_action,
            revision_idempotency_key=revision_idempotency_key,
            review_origin=review_origin,
            reviewer_identity=reviewer_identity,
            reviewed_by_user_id=reviewed_by_user_id,
        )
        return ReviewCorrectionResult(
            review_label=review_label,
            visit=visit,
            event=event,
            review_queue_count=len(self._review_queue_items(session)),
            analytics=self._analytics_summary(session),
        )

    def bulk_correct_review_queue_items(
        self,
        payload: ReviewQueueBulkCorrectionRequest,
        *,
        acting_user: CurrentUser | None = None,
    ) -> ReviewQueueBulkCorrectionResponse:
        correction_label = _clean_optional_text(payload.label)
        if correction_label is None:
            raise ValueError("missing_review_label")

        # See `create_review_label`'s docstring: `acting_user` only sets
        # `reviewed_by_user_id` (applied uniformly to every target_id in
        # this one bulk request -- there is no per-item actor), never
        # `review_origin`; `reviewer_identity` gets the same narrow
        # signed-in default as every other review-mutation method.
        reviewed_by_user_id = acting_user.id if acting_user is not None else None
        effective_reviewer_identity = self._reviewer_identity_with_signed_in_default(
            payload.review_origin, payload.reviewer_identity, acting_user
        )

        target_type = payload.target_type.value
        notes = _clean_optional_text(payload.notes)
        results: list[ReviewQueueBulkCorrectionResult] = []
        seen_target_ids: set[str] = set()

        with self.session_factory() as session:
            with session.begin():
                for raw_target_id in payload.target_ids:
                    target_id = raw_target_id.strip()
                    if not target_id:
                        results.append(
                            ReviewQueueBulkCorrectionResult(
                                target_id=target_id,
                                status=ReviewQueueBulkCorrectionResultStatus.skipped,
                                message="Target id is required.",
                            )
                        )
                        continue
                    if target_id in seen_target_ids:
                        results.append(
                            ReviewQueueBulkCorrectionResult(
                                target_id=target_id,
                                status=ReviewQueueBulkCorrectionResultStatus.skipped,
                                message=(
                                    "Duplicate target id in request; only the first "
                                    "occurrence was processed."
                                ),
                            )
                        )
                        continue
                    seen_target_ids.add(target_id)

                    skip_reason = self._review_queue_bulk_correction_skip_reason(
                        session,
                        payload.target_type,
                        target_id,
                    )
                    if skip_reason is not None:
                        results.append(
                            ReviewQueueBulkCorrectionResult(
                                target_id=target_id,
                                status=ReviewQueueBulkCorrectionResultStatus.skipped,
                                message=skip_reason,
                            )
                        )
                        continue

                    expected_state_token = (payload.expected_state_tokens or {}).get(target_id)

                    try:
                        if expected_state_token is not None:
                            # Same mechanism `create_review_label`/
                            # `revise_visit_review`/`reopen_visit_review`
                            # already use, checked inside this same
                            # try/except so a stale item is reported
                            # through the exact same per-item `failed`
                            # path as any other rejected write below --
                            # never a whole-batch abort.
                            current_state_token = self._review_state_token(session, target_type, target_id)
                            if current_state_token != expected_state_token:
                                raise ReviewRevisionConflictError("stale_reviewed_visit")
                        review_label, _, _ = self._create_review_label_in_session(
                            session,
                            ReviewCorrectionCreate(
                                target_type=target_type,
                                target_id=target_id,
                                label=correction_label,
                                notes=notes,
                            ),
                            review_origin=payload.review_origin,
                            reviewer_identity=effective_reviewer_identity,
                            reviewed_by_user_id=reviewed_by_user_id,
                        )
                    except ValueError as error:
                        results.append(
                            ReviewQueueBulkCorrectionResult(
                                target_id=target_id,
                                status=ReviewQueueBulkCorrectionResultStatus.failed,
                                message=_review_queue_bulk_correction_failure_message(
                                    str(error),
                                ),
                            )
                        )
                        continue

                    results.append(
                        ReviewQueueBulkCorrectionResult(
                            target_id=target_id,
                            status=ReviewQueueBulkCorrectionResultStatus.succeeded,
                            message="Correction saved as ReviewLabel truth.",
                            created_review_label_id=review_label.id,
                        )
                    )

        return ReviewQueueBulkCorrectionResponse(
            requested_count=len(payload.target_ids),
            succeeded_count=sum(
                1
                for result in results
                if result.status == ReviewQueueBulkCorrectionResultStatus.succeeded
            ),
            skipped_count=sum(
                1
                for result in results
                if result.status == ReviewQueueBulkCorrectionResultStatus.skipped
            ),
            failed_count=sum(
                1
                for result in results
                if result.status == ReviewQueueBulkCorrectionResultStatus.failed
            ),
            results=results,
        )


    def prepare_review_queue_species_suggestions(
        self,
        payload: ReviewQueueSpeciesSuggestionBatchPrepareRequest,
    ) -> ReviewQueueSpeciesSuggestionBatchPrepareResponse:
        """Validate bounded unresolved Visits before client-side serial analysis."""

        results: list[ReviewQueueSpeciesSuggestionBatchPrepareResult] = []
        seen_visit_ids: set[str] = set()
        with self.session_factory() as session:
            # Same rationale as `_review_queue_items`: this batch can cover
            # several Visits in one bounded request, so resolve
            # model-adapter/BioCLIP status once and reuse it, rather than
            # once per Visit.
            adapter_status = _ReviewAdapterStatusContext.resolve()
            for raw_visit_id in payload.visit_ids:
                visit_id = raw_visit_id.strip()
                if not visit_id:
                    results.append(
                        ReviewQueueSpeciesSuggestionBatchPrepareResult(
                            visit_id=visit_id,
                            status=ReviewQueueSpeciesSuggestionBatchPrepareStatus.skipped,
                            message="Visit id is required.",
                        )
                    )
                    continue
                if visit_id in seen_visit_ids:
                    results.append(
                        ReviewQueueSpeciesSuggestionBatchPrepareResult(
                            visit_id=visit_id,
                            status=ReviewQueueSpeciesSuggestionBatchPrepareStatus.skipped,
                            message="Duplicate Visit id was skipped.",
                        )
                    )
                    continue
                seen_visit_ids.add(visit_id)
                visit = session.get(VisitModel, visit_id)
                if visit is None or visit.is_superseded:
                    results.append(
                        ReviewQueueSpeciesSuggestionBatchPrepareResult(
                            visit_id=visit_id,
                            status=ReviewQueueSpeciesSuggestionBatchPrepareStatus.skipped,
                            message="Visit is unavailable for species suggestions.",
                        )
                    )
                    continue
                if visit.review_status != ReviewStatus.needs_review.value:
                    results.append(
                        ReviewQueueSpeciesSuggestionBatchPrepareResult(
                            visit_id=visit_id,
                            status=ReviewQueueSpeciesSuggestionBatchPrepareStatus.skipped,
                            message="Visit is no longer unresolved and was skipped.",
                        )
                    )
                    continue
                try:
                    item = self._review_identification_item_for_visit(session, visit_id)
                except ValueError:
                    results.append(
                        ReviewQueueSpeciesSuggestionBatchPrepareResult(
                            visit_id=visit_id,
                            status=ReviewQueueSpeciesSuggestionBatchPrepareStatus.skipped,
                            message="Visit review evidence is unavailable and was skipped.",
                        )
                    )
                    continue
                frames = self._review_identification_assistant_frames(
                    item.evidence_frames,
                    VisitIdentificationEvidenceMode.primary_only,
                )
                candidate_label = (
                    item.suggested_label
                    or visit.species_guess
                    or visit.subject_label
                    or ""
                )
                candidate_taxonomy = self._taxonomy_label_model_for_input(
                    session,
                    candidate_label,
                )
                is_bird_candidate = (
                    _taxonomy_key(candidate_label) in {"bird", "unknown_bird"}
                    or (
                        candidate_taxonomy is not None
                        and candidate_taxonomy.category == LabelCategory.bird
                    )
                )
                if not is_bird_candidate:
                    results.append(
                        ReviewQueueSpeciesSuggestionBatchPrepareResult(
                            visit_id=visit_id,
                            status=ReviewQueueSpeciesSuggestionBatchPrepareStatus.skipped,
                            message="Visit is not currently a bird-review candidate and was skipped.",
                        )
                    )
                    continue
                if not frames:
                    results.append(
                        ReviewQueueSpeciesSuggestionBatchPrepareResult(
                            visit_id=visit_id,
                            status=ReviewQueueSpeciesSuggestionBatchPrepareStatus.skipped,
                            message="No usable saved image is available for this Visit.",
                        )
                    )
                    continue
                summary = self._review_identification_summary_for_item(
                    session,
                    item,
                    media_asset_id=frames[0].media_asset_id,
                    adapter_status=adapter_status,
                )
                legacy_reuse_available = False
                if not summary.can_run:
                    try:
                        run_context = self._review_species_run_context(
                            session,
                            item,
                            target_type="visit",
                            target_id=visit_id,
                            media_asset_id=frames[0].media_asset_id,
                        )
                    except ValueError:
                        run_context = None
                    if run_context is not None:
                        legacy_reuse_available = (
                            self._reusable_legacy_bioclip_suggestion(
                                session,
                                run_context=run_context,
                            )
                            is not None
                        )
                    if not legacy_reuse_available:
                        results.append(
                            ReviewQueueSpeciesSuggestionBatchPrepareResult(
                                visit_id=visit_id,
                                status=ReviewQueueSpeciesSuggestionBatchPrepareStatus.setup_required,
                                message="Local species suggestion setup is required for this Visit.",
                                media_asset_id=frames[0].media_asset_id,
                                candidate_pack=summary.candidate_pack,
                                candidate_pack_warning=summary.candidate_pack_warning,
                            )
                        )
                        continue
                results.append(
                    ReviewQueueSpeciesSuggestionBatchPrepareResult(
                        visit_id=visit_id,
                        status=ReviewQueueSpeciesSuggestionBatchPrepareStatus.queued,
                        message="Visit is queued for one explicit local species suggestion.",
                        media_asset_id=frames[0].media_asset_id,
                        candidate_pack=summary.candidate_pack,
                        candidate_pack_warning=summary.candidate_pack_warning,
                    )
                )
        return ReviewQueueSpeciesSuggestionBatchPrepareResponse(
            requested_count=len(payload.visit_ids),
            queued_count=sum(
                1
                for result in results
                if result.status == ReviewQueueSpeciesSuggestionBatchPrepareStatus.queued
            ),
            skipped_count=sum(
                1
                for result in results
                if result.status == ReviewQueueSpeciesSuggestionBatchPrepareStatus.skipped
            ),
            setup_required_count=sum(
                1
                for result in results
                if result.status
                == ReviewQueueSpeciesSuggestionBatchPrepareStatus.setup_required
            ),
            results=results,
        )


    def review_queue_items(
        self,
        *,
        include_reviewed: bool = False,
    ) -> list[ReviewQueueItem]:
        with self.session_factory() as session:
            return self._review_queue_items(session, include_reviewed=include_reviewed)

    def get_visit_identification_assistant(
        self,
        visit_id: str,
    ) -> VisitIdentificationAssistantResponse:
        """Read bounded, saved Visit evidence without starting an analyzer."""

        with self.session_factory() as session:
            item = self._review_identification_item_for_visit(session, visit_id)
            frames = self._review_identification_assistant_frames(
                item.evidence_frames,
                VisitIdentificationEvidenceMode.primary_only,
            )
            summary = self._review_identification_summary_for_item(session, item)
            latest_run = session.scalars(
                select(ReviewIdentificationAssistantRunModel)
                .where(ReviewIdentificationAssistantRunModel.visit_id == visit_id)
                .order_by(
                    ReviewIdentificationAssistantRunModel.started_at.desc(),
                    ReviewIdentificationAssistantRunModel.id.desc(),
                )
            ).first()
            return self._visit_identification_assistant_response(
                session,
                item=item,
                summary=summary,
                evidence_mode=(
                    VisitIdentificationEvidenceMode(latest_run.evidence_mode)
                    if latest_run is not None
                    else VisitIdentificationEvidenceMode.primary_only
                ),
                selected_frames=frames,
                run=latest_run,
                message=(
                    "Review saved evidence or request a new local analysis. Suggestions "
                    "remain evidence until an explicit correction is saved."
                ),
            )

    def start_visit_identification_assistant(
        self,
        visit_id: str,
        payload: VisitIdentificationAssistantRequest,
    ) -> VisitIdentificationAssistantResponse:
        """Run configured local identification over retained frames only, on request."""

        # This lock covers durable request creation through completion. It prevents
        # duplicate clicks from starting competing per-Visit runs; the underlying
        # BioCLIP runner has its own shorter-lived process boundary.
        with self._review_identification_assistant_lock:
            with self.session_factory() as session:
                item = self._review_identification_item_for_visit(session, visit_id)
                frames = self._review_identification_assistant_frames(
                    item.evidence_frames,
                    payload.evidence_mode,
                )
                summary = self._review_identification_summary_for_item(
                    session,
                    item,
                    media_asset_id=(frames[0].media_asset_id if frames else None),
                )
                selected_ids = [frame.media_asset_id for frame in frames]
                input_hash = hashlib.sha256(
                    json.dumps(
                        {
                            "visit_id": visit_id,
                            "evidence_mode": payload.evidence_mode.value,
                            "media_asset_ids": selected_ids,
                            "adapter_id": summary.adapter_id,
                            "candidate_pack_sha256": (
                                summary.candidate_pack.content_sha256
                                if summary.candidate_pack is not None
                                else None
                            ),
                        },
                        sort_keys=True,
                        separators=(",", ":"),
                    ).encode("utf-8")
                ).hexdigest()
                existing = session.scalar(
                    select(ReviewIdentificationAssistantRunModel).where(
                        ReviewIdentificationAssistantRunModel.idempotency_key
                        == payload.idempotency_key
                    )
                )
                if existing is not None:
                    if (
                        existing.visit_id != visit_id
                        or existing.evidence_mode != payload.evidence_mode.value
                        or existing.input_configuration_sha256 != input_hash
                    ):
                        raise ValueError("identification_idempotency_conflict")
                    return self._visit_identification_assistant_response(
                        session,
                        item=item,
                        summary=summary,
                        evidence_mode=payload.evidence_mode,
                        selected_frames=frames,
                        run=existing,
                        message="This identification request was already recorded.",
                    )

                active = session.scalar(
                    select(ReviewIdentificationAssistantRunModel).where(
                        ReviewIdentificationAssistantRunModel.visit_id == visit_id,
                        ReviewIdentificationAssistantRunModel.status == "running",
                    )
                )
                if active is not None:
                    return self._visit_identification_assistant_response(
                        session,
                        item=item,
                        summary=summary,
                        evidence_mode=payload.evidence_mode,
                        selected_frames=frames,
                        run=active,
                        message="Identification is already running for this Visit.",
                    )

                prior_completed_input = session.scalar(
                    select(ReviewIdentificationAssistantRunModel)
                    .where(
                        ReviewIdentificationAssistantRunModel.visit_id == visit_id,
                        ReviewIdentificationAssistantRunModel.input_configuration_sha256
                        == input_hash,
                        ReviewIdentificationAssistantRunModel.status.in_(
                            ["succeeded", "no_result"]
                        ),
                    )
                    .order_by(
                        ReviewIdentificationAssistantRunModel.completed_at.desc(),
                        ReviewIdentificationAssistantRunModel.id.desc(),
                    )
                )
                if prior_completed_input is not None:
                    return self._visit_identification_assistant_response(
                        session,
                        item=item,
                        summary=summary,
                        evidence_mode=payload.evidence_mode,
                        selected_frames=frames,
                        run=prior_completed_input,
                        message=(
                            "This exact saved input already has identification evidence."
                        ),
                    )

                if frames and summary.adapter_id == BIOCLIP_ADAPTER_ID:
                    try:
                        reusable_context = self._review_species_run_context(
                            session,
                            item,
                            target_type="visit",
                            target_id=visit_id,
                            media_asset_id=frames[0].media_asset_id,
                        )
                    except ValueError:
                        reusable_context = None
                    reusable = False
                    if reusable_context is not None and summary.can_run:
                        reusable = (
                            self._reusable_bioclip_suggestion(
                                run_context=reusable_context
                            )
                            is not None
                        )
                    if not reusable and reusable_context is not None:
                        try:
                            prepare_bioclip_run(
                                _bioclip_config(
                                    _species_candidate_pack_prompt_labels(
                                        reusable_context.candidate_pack
                                    )
                                )
                            )
                        except BioClipConfigurationError:
                            # Older suggestion records predate durable Assistant runs.
                            # If the current runtime cannot prepare, reuse only an
                            # exact verified legacy record instead of logging a
                            # futile unavailable attempt.
                            reusable = (
                                self._reusable_legacy_bioclip_suggestion(
                                    session,
                                    run_context=reusable_context,
                                )
                                is not None
                            )
                    if reusable:
                        return self._visit_identification_assistant_response(
                            session,
                            item=item,
                            summary=summary,
                            evidence_mode=payload.evidence_mode,
                            selected_frames=frames,
                            run=None,
                            message="This exact saved input already has identification evidence.",
                        )
                run = ReviewIdentificationAssistantRunModel(
                    id=f"review-identification-assistant-{uuid.uuid4().hex}",
                    visit_id=visit_id,
                    idempotency_key=payload.idempotency_key,
                    evidence_mode=payload.evidence_mode.value,
                    selected_media_asset_ids_json=json.dumps(selected_ids),
                    input_configuration_sha256=input_hash,
                    request_origin="user_triggered_review_assistance",
                    status="running",
                    started_at=datetime.now(UTC),
                    completed_at=None,
                    attempt_ids_json="[]",
                    error_code=None,
                )
                session.add(run)
                session.commit()
                run_id = run.id

            attempt_ids: list[str] = []
            last_summary = summary
            terminal_error: str | None = None
            if not frames:
                terminal_status = "unavailable"
                terminal_error = "missing_retained_evidence"
            else:
                for frame in frames:
                    existing_attempt_ids = {
                        str(attempt["id"])
                        for attempt in self.list_bioclip_identification_attempts(
                            target_type="visit",
                            target_id=visit_id,
                        )
                    }
                    try:
                        response = self.identify_review_queue_item(
                            "visit",
                            visit_id,
                            ReviewIdentificationRequest(
                                adapter_id=summary.adapter_id,
                                media_asset_id=frame.media_asset_id,
                                notes=(
                                    "User-triggered Identification Assistant request; "
                                    f"assistant_run={run_id}; frame_role="
                                    f"{'primary' if frame.is_primary else 'supporting'}."
                                ),
                            ),
                        )
                    except ValueError as error:
                        terminal_error = str(error)
                        break
                    except Exception:
                        terminal_error = "assistant_execution_failed"
                        break
                    last_summary = response.identification
                    for attempt in self.list_bioclip_identification_attempts(
                        target_type="visit",
                        target_id=visit_id,
                    ):
                        if (
                            attempt.get("media_asset_id") == frame.media_asset_id
                            and str(attempt["id"]) not in existing_attempt_ids
                        ):
                            attempt_ids.append(str(attempt["id"]))

                if terminal_error is not None:
                    terminal_status = "failed"
                elif last_summary.status in {
                    ReviewIdentificationStatus.suggestion_created,
                    ReviewIdentificationStatus.suggestion_present,
                }:
                    terminal_status = "succeeded"
                elif last_summary.status in {
                    ReviewIdentificationStatus.no_proposal,
                    ReviewIdentificationStatus.proposal_created,
                }:
                    terminal_status = "no_result"
                elif last_summary.status in {
                    ReviewIdentificationStatus.setup_required,
                    ReviewIdentificationStatus.unavailable,
                    ReviewIdentificationStatus.unavailable_no_adapter,
                    ReviewIdentificationStatus.unsupported_media,
                    ReviewIdentificationStatus.no_best_frame,
                }:
                    terminal_status = "unavailable"
                    terminal_error = last_summary.unavailable_reason
                else:
                    terminal_status = "failed"
                    terminal_error = last_summary.unavailable_reason

            with self.session_factory() as session:
                with session.begin():
                    run = session.get(ReviewIdentificationAssistantRunModel, run_id)
                    if run is None:
                        raise RuntimeError("Identification Assistant request evidence is missing.")
                    run.status = terminal_status
                    run.completed_at = datetime.now(UTC)
                    run.attempt_ids_json = json.dumps(sorted(set(attempt_ids)))
                    run.error_code = terminal_error
                item = self._review_identification_item_for_visit(session, visit_id)
                refreshed_summary = self._review_identification_summary_for_item(
                    session,
                    item,
                    media_asset_id=(frames[0].media_asset_id if frames else None),
                )
                return self._visit_identification_assistant_response(
                    session,
                    item=item,
                    summary=refreshed_summary,
                    evidence_mode=payload.evidence_mode,
                    selected_frames=frames,
                    run=run,
                    message=(
                        "Identification analysis completed as evidence only. Use a suggestion "
                        "to prefill the correction, then save explicitly to create truth."
                        if terminal_status == "succeeded"
                        else refreshed_summary.message
                    ),
                )

    def _review_identification_assistant_frames(
        self,
        frames: list[VisitEvidenceFrame],
        evidence_mode: VisitIdentificationEvidenceMode,
    ) -> list[VisitEvidenceFrame]:
        """Select one persisted image without silently lowering evidence quality."""

        retained = frames[:MAX_LIVE_VISIT_EVIDENCE_FRAMES]
        if not retained:
            return []
        # A completed activity crop is the reviewed bird evidence.  The full
        # high-resolution still is the explicit fallback, followed only then by
        # the normal primary/best monitoring frame.  Keep the legacy request
        # enum for API compatibility, but one manual suggestion run always has
        # one accountable MediaAsset input.
        for evidence_role in (
            "user_refined_crop",
            "activity_crop",
            "high_resolution_original",
        ):
            candidates = [
                frame for frame in retained if frame.evidence_role == evidence_role
            ]
            if candidates:
                primary = next(
                    (frame for frame in candidates if frame.is_primary),
                    None,
                )
                return [primary or candidates[0]]
        primary = next((frame for frame in retained if frame.is_primary), None)
        return [primary] if primary is not None else retained[:1]

    def _review_identification_item_for_visit(
        self,
        session: Session,
        visit_id: str,
    ) -> ReviewQueueItem:
        """Build review evidence context for either an unresolved or reviewed Visit."""

        visit = session.get(VisitModel, visit_id)
        if visit is None or visit.is_superseded:
            raise ValueError("missing_visit")
        event = session.get(EventModel, visit.event_id)
        if event is None:
            raise ValueError("missing_review_candidate")
        zone_id, zone_name, zone_type = self._zone_context(
            session,
            visit.zone_id or event.primary_zone_id,
        )
        stream_name, source_id, source_name = self._review_queue_stream_context(
            session,
            event.stream_id,
        )
        evidence_frames = self._visit_evidence_frames_from_visit(session, visit, event)
        selected_frames = self._review_identification_assistant_frames(
            evidence_frames,
            VisitIdentificationEvidenceMode.primary_only,
        )
        primary_frame = selected_frames[0] if selected_frames else None
        media_asset = (
            session.get(MediaAssetModel, primary_frame.media_asset_id)
            if primary_frame is not None
            else self._media_asset_for_path_from_session(
                session,
                visit.representative_media_path,
            )
        )
        evidence = self._motion_evidence_for_review_queue_item(
            session,
            event_id=event.id,
            visit_id=visit.id,
            media_asset_id=media_asset.id if media_asset is not None else None,
        )
        best_media_asset_id = (
            media_asset.id
            if media_asset is not None
            else evidence.snapshot_media_asset_id
            if evidence is not None
            else None
        )
        suggestion_model = session.scalars(
            select(SpeciesSuggestionModel)
            .where(
                SpeciesSuggestionModel.visit_id == visit.id,
                SpeciesSuggestionModel.status == SpeciesSuggestionStatus.pending.value,
            )
            .order_by(
                SpeciesSuggestionModel.created_at.desc(),
                SpeciesSuggestionModel.rank,
                SpeciesSuggestionModel.id.desc(),
            )
        ).first()
        suggestion = (
            _species_suggestion_from_model(suggestion_model)
            if suggestion_model is not None
            else None
        )
        focus_crop_context = self._review_focus_crop_context(
            session,
            zone_id=zone_id,
            media_asset_id=best_media_asset_id,
            evidence=evidence,
        )
        return ReviewQueueItem(
            id=f"review-queue-{visit.id}",
            item_type="visit",
            target_type="visit",
            target_id=visit.id,
            title=f"Review {visit.subject_label} visit",
            stream_id=event.stream_id,
            stream_name=stream_name,
            source_id=source_id,
            source_name=source_name,
            event_id=event.id,
            visit_id=visit.id,
            primary_zone_id=zone_id,
            primary_zone_name=zone_name,
            primary_zone_type=zone_type,
            zone_id=zone_id,
            zone_name=zone_name,
            zone_type=zone_type,
            best_media_asset_id=best_media_asset_id,
            **self._review_queue_activity_context(evidence),
            suggested_label=(
                suggestion.suggested_label
                if suggestion is not None
                else visit.species_guess or visit.subject_label
            ),
            suggestion_id=suggestion.id if suggestion is not None else None,
            suggestion_confidence=suggestion.confidence if suggestion is not None else None,
            suggestion_reason=suggestion.notes if suggestion is not None else None,
            suggestion_creates_truth=False,
            **_review_focus_crop_fields(focus_crop_context),
            media_asset=_media_asset_from_model(media_asset) if media_asset is not None else None,
            evidence_frames=evidence_frames,
            effective_primary=self._effective_primary_preview_from_visit(session, visit),
            stale_species_suggestions=self._visit_has_stale_species_suggestions(
                session,
                visit_id=visit.id,
                effective_media_asset_id=best_media_asset_id,
            ),
            review_status=ReviewStatus(visit.review_status),
            reviewed_label=visit.reviewed_label,
            review_state_token=self._review_state_token(session, "visit", visit.id),
            reason="Review saved Visit evidence and explicitly correct the final label.",
        )

    def _visit_identification_assistant_response(
        self,
        session: Session,
        *,
        item: ReviewQueueItem,
        summary: ReviewIdentificationSummary,
        evidence_mode: VisitIdentificationEvidenceMode,
        selected_frames: list[VisitEvidenceFrame],
        run: ReviewIdentificationAssistantRunModel | None,
        message: str,
    ) -> VisitIdentificationAssistantResponse:
        attempts = list(
            session.scalars(
                select(BioClipIdentificationAttemptModel)
                .where(
                    BioClipIdentificationAttemptModel.target_type == "visit",
                    BioClipIdentificationAttemptModel.target_id == item.target_id,
                )
                .order_by(
                    BioClipIdentificationAttemptModel.started_at.desc(),
                    BioClipIdentificationAttemptModel.id.desc(),
                )
                .limit(20)
            ).all()
        )
        attempt_records = [_bioclip_attempt_record(attempt) for attempt in attempts]
        run_attempt_ids = set()
        if run is not None:
            try:
                run_attempt_ids = set(json.loads(run.attempt_ids_json))
            except (TypeError, json.JSONDecodeError):
                run_attempt_ids = set()
        for attempt in attempt_records:
            attempt["origin"] = (
                "user_triggered_review_assistance"
                if attempt["id"] in run_attempt_ids
                else "previously_generated"
            )

        suggestion_models = list(
            session.scalars(
                select(SpeciesSuggestionModel)
                .where(SpeciesSuggestionModel.visit_id == item.target_id)
                .order_by(
                    SpeciesSuggestionModel.created_at.desc(),
                    SpeciesSuggestionModel.rank,
                    SpeciesSuggestionModel.id.desc(),
                )
                .limit(40)
            ).all()
        )
        attempt_for_suggestion = {
            attempt.resulting_species_suggestion_id: attempt
            for attempt in attempts
            if attempt.resulting_species_suggestion_id is not None
        }
        selected_roles = {
            frame.media_asset_id: ("primary" if frame.is_primary else "supporting")
            for frame in selected_frames
        }
        suggestion_rows: list[dict[str, Any]] = []
        seen: set[tuple[str, str | None, str | None, str]] = set()
        for suggestion in suggestion_models:
            attempt = attempt_for_suggestion.get(suggestion.id)
            candidates = [
                {
                    "label": suggestion.suggested_label,
                    "rank": suggestion.rank,
                    "score": suggestion.confidence,
                },
                *[
                    {
                        "label": candidate.get("suggested_label") or candidate.get("label"),
                        "rank": candidate.get("rank"),
                        "score": candidate.get("score"),
                    }
                    for candidate in _assistant_suggestion_alternatives(suggestion)
                    if isinstance(candidate, dict)
                ],
            ]
            for candidate in candidates:
                label = _clean_optional_text(candidate.get("label"))
                if label is None:
                    continue
                key = (suggestion.adapter_id, attempt.id if attempt else suggestion.id, suggestion.media_asset_id, label)
                if key in seen:
                    continue
                seen.add(key)
                suggestion_rows.append(
                    {
                        "suggestion_id": suggestion.id,
                        "attempt_id": attempt.id if attempt is not None else None,
                        "label": label,
                        "rank": _optional_int(candidate.get("rank")) or suggestion.rank,
                        "score": candidate.get("score"),
                        "score_label": "uncalibrated score"
                        if suggestion.adapter_id == BIOCLIP_ADAPTER_ID
                        else "score",
                        "provider": suggestion.adapter_name,
                        "provider_id": suggestion.adapter_id,
                        "media_asset_id": suggestion.media_asset_id,
                        "frame_role": selected_roles.get(suggestion.media_asset_id, "previously_saved"),
                        "model_runtime_version": _assistant_model_runtime_version(attempt),
                        "analyzed_at": suggestion.created_at,
                        "status": suggestion.status,
                        "origin": (
                            "user_triggered_review_assistance"
                            if attempt is not None and attempt.id in run_attempt_ids
                            else "previously_generated"
                        ),
                    }
                )
        support_keys: dict[tuple[str, str], set[str | None]] = {}
        for row in suggestion_rows:
            support_keys.setdefault(
                (str(row["provider_id"]), str(row["label"])), set()
            ).add(row["media_asset_id"] if isinstance(row["media_asset_id"], str) else None)
        for row in suggestion_rows:
            row["support_count"] = len(
                support_keys[(str(row["provider_id"]), str(row["label"]))]
            )
        suggestion_rows.sort(
            key=lambda row: (
                -int(row["support_count"]),
                int(row["rank"]),
                str(row["label"]),
                str(row["provider_id"]),
                str(row["suggestion_id"]),
            )
        )
        run_record = _review_identification_assistant_run_record(run) if run else None
        return VisitIdentificationAssistantResponse(
            visit_id=item.target_id,
            availability=summary,
            evidence_mode=evidence_mode,
            selected_evidence_frames=selected_frames,
            run=run_record,
            attempts=attempt_records,
            suggestions=suggestion_rows[:BIOCLIP_REVIEW_TOP_K],
            message=message,
            creates_truth=False,
            creates_export=False,
        )

    def navigate_fast_review_queue(
        self,
        payload: FastReviewQueueNavigationRequest,
    ) -> FastReviewQueueNavigationResponse:
        """Resolve one item from a bounded client-filtered snapshot.

        The client supplies its current filter order; the repository verifies each
        target remains unresolved and, when requested, remains on the same Stream.
        That keeps a fast review session from drifting into a different queue view.
        """

        with self.session_factory() as session:
            current_queue = {
                (item.target_type, item.target_id): item
                for item in self._review_queue_items(session)
            }
            ordered_keys: list[tuple[str, str]] = []
            seen_keys: set[tuple[str, str]] = set()
            for target in payload.ordered_targets:
                key = (target.target_type.value, target.target_id)
                if key in seen_keys:
                    continue
                seen_keys.add(key)
                ordered_keys.append(key)

            unresolved_keys = [
                key
                for key in ordered_keys
                if key in current_queue
                and (
                    payload.stream_id is None
                    or current_queue[key].stream_id == payload.stream_id
                )
            ]
            current_key = (
                (payload.current_target.target_type.value, payload.current_target.target_id)
                if payload.current_target is not None
                else None
            )
            current_index = ordered_keys.index(current_key) if current_key in ordered_keys else None
            candidate_keys = (
                ordered_keys[current_index + 1 :]
                if payload.direction.value == "next" and current_index is not None
                else list(reversed(ordered_keys[:current_index]))
                if payload.direction.value == "previous" and current_index is not None
                else ordered_keys
                if payload.direction.value == "next"
                else list(reversed(ordered_keys))
            )
            next_key = next((key for key in candidate_keys if key in unresolved_keys), None)
            if next_key is None:
                message = (
                    "This is the last unresolved Visit in this filtered queue."
                    if current_key in unresolved_keys
                    else "No unresolved Visit remains in this filtered queue."
                )
                return FastReviewQueueNavigationResponse(
                    unresolved_count=len(unresolved_keys),
                    message=message,
                )

            return FastReviewQueueNavigationResponse(
                item=current_queue[next_key],
                position=unresolved_keys.index(next_key) + 1,
                unresolved_count=len(unresolved_keys),
                message="Next unresolved Visit selected from the current filtered queue.",
            )

    def create_fast_review_correction(
        self,
        payload: FastReviewCorrectionCreate,
        *,
        acting_user: CurrentUser | None = None,
    ) -> FastReviewCorrectionResponse:
        # See `create_review_label`'s docstring: `acting_user` only sets
        # `reviewed_by_user_id`, never `review_origin`; `reviewer_identity`
        # gets the same narrow signed-in default as every other review-
        # mutation method.
        reviewed_by_user_id = acting_user.id if acting_user is not None else None
        effective_reviewer_identity = self._reviewer_identity_with_signed_in_default(
            payload.review_origin, payload.reviewer_identity, acting_user
        )
        with self.session_factory() as session:
            with session.begin():
                existing = session.scalar(
                    select(ReviewLabelModel).where(
                        ReviewLabelModel.fast_review_idempotency_key == payload.idempotency_key
                    )
                )
                if existing is not None:
                    if (
                        existing.reversal_of_review_label_id is not None
                        or existing.fast_review_session_id != payload.review_session_id
                        or existing.target_type != payload.target_type.value
                        or existing.target_id != payload.target_id
                    ):
                        raise FastReviewConflictError("fast_review_idempotency_conflict")
                    return FastReviewCorrectionResponse(
                        result=self._review_correction_result_for_model(session, existing),
                        idempotent=True,
                        undo_state_token=self._review_state_token(
                            session,
                            existing.target_type,
                            existing.target_id,
                        ),
                    )

                if payload.target_type != ReviewQueueBulkCorrectionTargetType.visit:
                    raise ValueError("fast_review_visits_only")
                visit = session.get(VisitModel, payload.target_id)
                if visit is None:
                    raise ValueError("missing_visit")
                if self._review_state_token(session, "visit", visit.id) != payload.expected_state_token:
                    raise FastReviewConflictError("stale_review_item")
                if visit.review_status != ReviewStatus.needs_review.value:
                    raise FastReviewConflictError("review_item_already_resolved")

                # Fast Review calls the established ReviewLabel writer; suggestion evidence
                # is only a prefilled label until this explicit action completes.
                result = self._create_review_label_result_in_session(
                    session,
                    ReviewCorrectionCreate(
                        target_type="visit",
                        target_id=visit.id,
                        label=payload.label,
                        notes=payload.notes,
                    ),
                    fast_review_session_id=payload.review_session_id,
                    fast_review_idempotency_key=payload.idempotency_key,
                    review_origin=payload.review_origin,
                    reviewer_identity=effective_reviewer_identity,
                    reviewed_by_user_id=reviewed_by_user_id,
                )
                return FastReviewCorrectionResponse(
                    result=result,
                    undo_state_token=self._review_state_token(session, "visit", visit.id),
                )

    def undo_fast_review_correction(
        self,
        payload: FastReviewUndoRequest,
        *,
        acting_user: CurrentUser | None = None,
    ) -> FastReviewUndoResponse:
        with self.session_factory() as session:
            with session.begin():
                repeated_reversal = session.scalar(
                    select(ReviewLabelModel).where(
                        ReviewLabelModel.fast_review_idempotency_key == payload.idempotency_key
                    )
                )
                if repeated_reversal is not None:
                    if (
                        repeated_reversal.reversal_of_review_label_id != payload.review_label_id
                        or repeated_reversal.fast_review_session_id != payload.review_session_id
                    ):
                        raise FastReviewConflictError("fast_review_idempotency_conflict")
                    return self._fast_review_undo_response(
                        session,
                        repeated_reversal,
                        idempotent=True,
                    )

                original = session.get(ReviewLabelModel, payload.review_label_id)
                if (
                    original is None
                    or original.reversal_of_review_label_id is not None
                    or original.fast_review_session_id != payload.review_session_id
                    or original.target_type != "visit"
                    or original.prior_review_status is None
                ):
                    raise FastReviewConflictError("fast_review_undo_unavailable")
                if self._review_state_token(session, original.target_type, original.target_id) != payload.expected_state_token:
                    raise FastReviewConflictError("stale_review_item")

                latest_session_correction = session.scalars(
                    select(ReviewLabelModel)
                    .where(
                        ReviewLabelModel.fast_review_session_id == payload.review_session_id,
                        ReviewLabelModel.reversal_of_review_label_id.is_(None),
                    )
                    .order_by(ReviewLabelModel.created_at.desc(), ReviewLabelModel.id.desc())
                ).first()
                if latest_session_correction is None or latest_session_correction.id != original.id:
                    raise FastReviewConflictError("fast_review_undo_not_latest")

                effective_labels = self._review_label_models_for_visit(session, original.target_id)
                latest = max(
                    effective_labels,
                    key=lambda label: (label.created_at, label.id),
                    default=None,
                )
                if latest is None or latest.id != original.id:
                    # A later correction is authoritative; never undo past it.
                    raise FastReviewConflictError("fast_review_undo_replaced")

                visit = session.get(VisitModel, original.target_id)
                if visit is None:
                    raise ValueError("missing_visit")
                event = session.get(EventModel, visit.event_id)
                visit.review_status = original.prior_review_status
                visit.reviewed_label = original.prior_reviewed_label
                if event is not None and original.prior_event_review_status is not None:
                    event.review_status = original.prior_event_review_status

                reversal = ReviewLabelModel(
                    id=self._next_id(session, ReviewLabelModel, "review-label"),
                    target_type=original.target_type,
                    target_id=original.target_id,
                    label=original.label,
                    notes="Fast Review undo. The prior review state was restored.",
                    created_at=datetime.now(UTC),
                    reversal_of_review_label_id=original.id,
                    fast_review_session_id=payload.review_session_id,
                    fast_review_idempotency_key=payload.idempotency_key,
                    review_origin="human" if acting_user is not None else None,
                    reviewer_identity=acting_user.display_name if acting_user is not None else None,
                    reviewed_by_user_id=acting_user.id if acting_user is not None else None,
                )
                session.add(reversal)
                self._sync_review_alert(session, visit, datetime.now(UTC))
                session.flush()
                return self._fast_review_undo_response(session, reversal)

    def identify_review_queue_item(
        self,
        target_type: str,
        target_id: str,
        payload: ReviewIdentificationRequest | None = None,
    ) -> ReviewIdentificationResponse:
        request = payload or ReviewIdentificationRequest()
        normalized_target_type = target_type.strip()
        normalized_target_id = target_id.strip()
        if normalized_target_type not in {"event", "visit"}:
            raise ValueError("unsupported_target")
        if not normalized_target_id:
            raise ValueError("missing_review_candidate")

        with self.session_factory() as session:
            queue_item = (
                self._review_identification_item_for_visit(session, normalized_target_id)
                if normalized_target_type == "visit"
                else self._review_queue_item_by_target(
                    session,
                    normalized_target_type,
                    normalized_target_id,
                )
            )
            if queue_item is None:
                raise ValueError("missing_review_candidate")

            requested_media_asset_id = _clean_optional_text(request.media_asset_id)
            if (
                requested_media_asset_id is not None
                and session.get(MediaAssetModel, requested_media_asset_id) is None
            ):
                raise ValueError("missing_media_asset")

            media_asset_id = (
                requested_media_asset_id
                or queue_item.best_media_asset_id
                or (queue_item.media_asset.id if queue_item.media_asset else None)
            )
            summary = self._review_identification_summary_for_item(
                session,
                queue_item,
                requested_adapter_id=_clean_optional_text(request.adapter_id),
                media_asset_id=media_asset_id,
            )
            zone_id = queue_item.zone_id or queue_item.primary_zone_id
            species_run_context: _ReviewSpeciesRunContext | None = None
            species_run_error: str | None = None
            if summary.can_run and _review_item_has_active_restricted_zone(
                session,
                queue_item,
            ):
                species_run_error = "identification_zone_suppressed"
                summary = self._review_identification_error_summary(
                    summary,
                    ValueError(species_run_error),
                )
            elif (
                summary.can_run
                and summary.adapter_kind == ModelAdapterKind.species_classifier
                and summary.adapter_id == BIOCLIP_ADAPTER_ID
                and media_asset_id is not None
            ):
                try:
                    species_run_context = self._review_species_run_context(
                        session,
                        queue_item,
                        target_type=normalized_target_type,
                        target_id=normalized_target_id,
                        media_asset_id=media_asset_id,
                    )
                except ValueError as error:
                    species_run_error = _safe_bioclip_error_code(str(error))
                    summary = self._review_identification_error_summary(summary, error)
            bioclip_attempt_context = (
                self._review_bioclip_attempt_context(
                    session,
                    queue_item,
                    target_type=normalized_target_type,
                    target_id=normalized_target_id,
                    media_asset_id=media_asset_id,
                    run_context=species_run_context,
                )
                if summary.adapter_id == BIOCLIP_ADAPTER_ID
                and media_asset_id is not None
                else None
            )

        if (
            summary.can_run
            and summary.adapter_id == BIOCLIP_ADAPTER_ID
            and species_run_context is not None
        ):
            reused_suggestion = self._reusable_bioclip_suggestion(
                run_context=species_run_context,
            )
            if reused_suggestion is not None:
                reused_summary = summary.model_copy(
                    update={
                        "status": ReviewIdentificationStatus.suggestion_present,
                        "message": (
                            "BioCLIP reused the completed result for this exact "
                            "saved input and local model configuration. No new "
                            "suggestion evidence was created."
                        ),
                        "suggestion": reused_suggestion,
                        "suggestion_count": max(summary.suggestion_count, 1),
                        "created_suggestion_ids": [],
                        "created_proposal_ids": [],
                        **_review_species_focus_fields(
                            species_run_context.crop,
                            queue_item,
                        ),
                    }
                )
                return self._review_identification_response(
                    target_type=normalized_target_type,
                    target_id=normalized_target_id,
                    identification=reused_summary,
                    review_queue_item=queue_item,
                )

        bioclip_attempt_id: str | None = None
        if bioclip_attempt_context is not None:
            bioclip_attempt_id = self._create_bioclip_identification_attempt(
                bioclip_attempt_context
            )
            if not summary.can_run:
                error_code = species_run_error or _bioclip_preflight_error_code(summary)
                outcome, stage, detail = _bioclip_attempt_failure_fields(error_code)
                self._complete_bioclip_identification_attempt(
                    bioclip_attempt_id,
                    attempt_context=bioclip_attempt_context,
                    outcome=outcome,
                    duration_ms=None,
                    timeout_exceeded=False,
                    error_code=error_code,
                    error_stage=stage,
                    error_detail=detail,
                )

        if not summary.can_run or summary.adapter_id is None or media_asset_id is None:
            return self._review_identification_response(
                target_type=normalized_target_type,
                target_id=normalized_target_id,
                identification=summary,
                review_queue_item=queue_item,
            )

        adapter = _model_adapter_by_id(summary.adapter_id)
        if adapter is not None and adapter.kind == ModelAdapterKind.species_classifier:
            if adapter.id != BIOCLIP_ADAPTER_ID:
                error_summary = self._review_identification_error_summary(
                    summary,
                    ValueError("species_classifier_not_supported"),
                )
                return self._review_identification_response(
                    target_type=normalized_target_type,
                    target_id=normalized_target_id,
                    identification=error_summary,
                    review_queue_item=queue_item,
                )
            if species_run_context is None:
                if bioclip_attempt_id is not None:
                    error_code = "bioclip_input_unavailable"
                    outcome, stage, detail = _bioclip_attempt_failure_fields(error_code)
                    self._complete_bioclip_identification_attempt(
                        bioclip_attempt_id,
                        attempt_context=bioclip_attempt_context,
                        outcome=outcome,
                        duration_ms=None,
                        timeout_exceeded=False,
                        error_code=error_code,
                        error_stage=stage,
                        error_detail=detail,
                    )
                error_summary = self._review_identification_error_summary(
                    summary,
                    ValueError("bioclip_input_unavailable"),
                )
                return self._review_identification_response(
                    target_type=normalized_target_type,
                    target_id=normalized_target_id,
                    identification=error_summary,
                    review_queue_item=queue_item,
                )
            if bioclip_attempt_id is None or bioclip_attempt_context is None:
                raise RuntimeError(
                    "A manual BioCLIP run cannot start without durable attempt evidence."
                )
            return self._identify_review_queue_with_bioclip(
                target_type=normalized_target_type,
                target_id=normalized_target_id,
                summary=summary,
                queue_item=queue_item,
                run_context=species_run_context,
                attempt_context=bioclip_attempt_context,
                attempt_id=bioclip_attempt_id,
                request=request,
            )

        requested_labels = request.requested_labels
        if adapter is not None and adapter.kind == ModelAdapterKind.demo and not requested_labels:
            requested_labels = ["unknown_bird"]
        notes = _clean_optional_text(request.notes)
        if notes is None:
            notes = (
                "Demo identification assist placeholder analyzer; no model inspected "
                "media, no species confidence, and proposal evidence only."
                if adapter is not None and adapter.kind == ModelAdapterKind.demo
                else "Review Queue identification assist run; proposal evidence only."
            )
        focus_note = _review_focus_crop_proposal_note(queue_item)
        if focus_note is not None:
            notes = _merge_notes(notes, focus_note)

        try:
            run_result = self.run_model_adapter(
                summary.adapter_id,
                ModelAdapterRunRequest(
                    adapter_id=summary.adapter_id,
                    media_asset_id=media_asset_id,
                    zone_ids=[zone_id] if zone_id else None,
                    requested_labels=requested_labels,
                    notes=notes,
                ),
                activity_focus=(
                    queue_item.focus_crop_box_normalized
                    if queue_item.focus_crop_source == FocusCropSource.activity
                    else None
                ),
            )
        except ValueError as error:
            error_summary = self._review_identification_error_summary(summary, error)
            return self._review_identification_response(
                target_type=normalized_target_type,
                target_id=normalized_target_id,
                identification=error_summary,
                review_queue_item=queue_item,
                warnings=[str(error)],
            )

        with self.session_factory() as session:
            refreshed_item = self._review_queue_item_by_target(
                session,
                normalized_target_type,
                normalized_target_id,
            )
            refreshed_summary = (
                refreshed_item.identification
                if refreshed_item is not None and refreshed_item.identification is not None
                else summary
            )

        if run_result.proposals:
            created_proposal_ids = [proposal.id for proposal in run_result.proposals]
            created_suggestion_ids: list[str] = []
            outcome_summary = refreshed_summary.model_copy(
                update={
                    "status": ReviewIdentificationStatus.proposal_created,
                    "message": (
                        "Placeholder analyzer created demo proposal evidence. No species "
                        "confidence, ReviewLabel, Bird Log entry, or export was created."
                        if summary.adapter_is_demo
                        else (
                            f"{len(run_result.proposals)} identification proposal"
                            f"{'' if len(run_result.proposals) == 1 else 's'} "
                            "created as evidence only."
                        )
                    ),
                    "proposal": run_result.proposals[0],
                    "proposal_count": max(
                        refreshed_summary.proposal_count,
                        len(run_result.proposals),
                    ),
                    "adapter_id": summary.adapter_id,
                    "adapter_name": summary.adapter_name,
                    "adapter_kind": summary.adapter_kind,
                    "adapter_status": summary.adapter_status,
                    "adapter_is_demo": summary.adapter_is_demo,
                    "setup_status": summary.setup_status,
                    "local_only": summary.local_only,
                    "supported_media_types": summary.supported_media_types,
                    "can_run": summary.can_run,
                    "can_run_on_best_frame": summary.can_run_on_best_frame,
                    "required_env_var": summary.required_env_var,
                    "model_path_hint": summary.model_path_hint,
                    "setup_hint": summary.setup_hint,
                    "unavailable_reason": None,
                    "created_suggestion_ids": created_suggestion_ids,
                    "created_proposal_ids": created_proposal_ids,
                }
            )
        else:
            outcome_summary = refreshed_summary.model_copy(
                update={
                    "status": ReviewIdentificationStatus.no_proposal,
                    "message": (
                        "Identification adapter completed without proposal evidence. "
                        "No review truth, Bird Log entry, or export data was created."
                    ),
                    "proposal": None,
                    "proposal_count": refreshed_summary.proposal_count,
                    "adapter_id": summary.adapter_id,
                    "adapter_name": summary.adapter_name,
                    "adapter_kind": summary.adapter_kind,
                    "adapter_status": summary.adapter_status,
                    "adapter_is_demo": summary.adapter_is_demo,
                    "setup_status": summary.setup_status,
                    "local_only": summary.local_only,
                    "supported_media_types": summary.supported_media_types,
                    "can_run": summary.can_run,
                    "can_run_on_best_frame": summary.can_run_on_best_frame,
                    "required_env_var": summary.required_env_var,
                    "model_path_hint": summary.model_path_hint,
                    "setup_hint": summary.setup_hint,
                    "unavailable_reason": None,
                    "created_suggestion_ids": [],
                    "created_proposal_ids": [],
                }
            )

        return self._review_identification_response(
            target_type=normalized_target_type,
            target_id=normalized_target_id,
            identification=outcome_summary,
            detection_run=run_result.detection_run,
            proposals=run_result.proposals,
            review_queue_item=refreshed_item,
        )

    def _reusable_bioclip_suggestion(
        self,
        *,
        run_context: _ReviewSpeciesRunContext,
    ) -> SpeciesSuggestion | None:
        """Return pending evidence only when its exact input and artifacts match."""

        with self.session_factory() as session:
            attempts = session.scalars(
                select(BioClipIdentificationAttemptModel)
                .where(
                    BioClipIdentificationAttemptModel.target_type
                    == run_context.target_type,
                    BioClipIdentificationAttemptModel.target_id
                    == run_context.target_id,
                    BioClipIdentificationAttemptModel.media_asset_id
                    == run_context.media_asset_id,
                    BioClipIdentificationAttemptModel.adapter_id == BIOCLIP_ADAPTER_ID,
                    BioClipIdentificationAttemptModel.candidate_pack_sha256
                    == run_context.candidate_pack.content_sha256,
                    BioClipIdentificationAttemptModel.outcome == "succeeded",
                    BioClipIdentificationAttemptModel.resulting_species_suggestion_id.is_not(None),
                )
                .order_by(
                    BioClipIdentificationAttemptModel.completed_at.desc(),
                    BioClipIdentificationAttemptModel.id.desc(),
                )
            ).all()
            candidates = []
            for attempt in attempts:
                suggestion = session.get(
                    SpeciesSuggestionModel,
                    attempt.resulting_species_suggestion_id,
                )
                if (
                    suggestion is not None
                    and suggestion.status == SpeciesSuggestionStatus.pending.value
                ):
                    candidates.append(
                        (
                            _species_suggestion_from_model(suggestion),
                            _safe_json_object(attempt.crop_provenance_json),
                            _safe_json_object(attempt.model_provenance_json),
                            _safe_json_object(suggestion.evidence_region_json),
                        )
                    )
        if not candidates:
            return None

        observation = _initial_bioclip_crop_provenance(run_context.crop)
        image: Any | None = None
        try:
            image = _load_bioclip_input_image(
                local_path=run_context.local_path,
                expected_size_bytes=run_context.media_file_size_bytes,
                expected_mtime_ns=run_context.media_file_mtime_ns,
                content_type=run_context.content_type,
                crop=run_context.crop,
                observation=observation,
            )
        except (
            BioClipRuntimeUnavailableError,
            BioClipUnsupportedImageError,
            OSError,
            ValueError,
        ):
            return None
        finally:
            if image is not None:
                try:
                    image.close()
                except Exception:
                    pass
        input_sha256 = observation.get("input_sha256")
        if not isinstance(input_sha256, str) or len(input_sha256) != 64:
            return None
        try:
            prepared_run = prepare_bioclip_run(
                _bioclip_config(
                    _species_candidate_pack_prompt_labels(run_context.candidate_pack)
                )
            )
        except BioClipConfigurationError:
            return None
        for suggestion, crop_provenance, model_provenance, evidence_region in candidates:
            identification_policy = evidence_region.get("identification_policy")
            reused_policy_version = (
                identification_policy.get("policy_version")
                if isinstance(identification_policy, dict)
                else None
            )
            if (
                crop_provenance.get("input_sha256") == input_sha256
                and _bioclip_provenance_matches_prepared_run(
                    model_provenance,
                    prepared_run,
                    candidate_pack_sha256=run_context.candidate_pack.content_sha256,
                )
                # A pending suggestion recorded under an older (or absent, i.e.
                # pre-2026-08-21) eligibility/abstention policy version must never
                # be silently reused as-is: today's policy may abstain where the
                # old one did not. Force fresh inference so the CURRENT policy is
                # the one that actually decides, instead of serving a stale
                # confident answer the current abstention gate never evaluated.
                and reused_policy_version == IDENTIFICATION_ELIGIBILITY_POLICY_VERSION
            ):
                return suggestion
        return None


    def _reusable_legacy_bioclip_suggestion(
        self,
        session: Session,
        *,
        run_context: _ReviewSpeciesRunContext,
    ) -> SpeciesSuggestion | None:
        """Reuse legacy built-in evidence only when the exact prepared input still matches."""

        if (
            run_context.candidate_pack.id != BUILTIN_SPECIES_CANDIDATE_PACK_ID
            or run_context.candidate_pack.content_sha256
            != _species_candidate_pack_content_sha256(
                BUILTIN_SPECIES_CANDIDATE_TAXONOMY_IDS
            )
        ):
            return None
        # A legacy suggestion has no durable pack record.  Its exact regenerated
        # crop hash still binds reuse to the same saved media and geometry, so it
        # is safe only for the unchanged built-in candidate scope above.
        crop = run_context.crop
        observation = _initial_bioclip_crop_provenance(crop)
        image: Any | None = None
        try:
            image = _load_bioclip_input_image(
                local_path=run_context.local_path,
                expected_size_bytes=run_context.media_file_size_bytes,
                expected_mtime_ns=run_context.media_file_mtime_ns,
                content_type=run_context.content_type,
                crop=crop,
                observation=observation,
            )
        except (
            BioClipRuntimeUnavailableError,
            BioClipUnsupportedImageError,
            OSError,
            ValueError,
        ):
            return None
        finally:
            if image is not None:
                try:
                    image.close()
                except Exception:
                    pass
        input_sha256 = observation.get("input_sha256")
        if not isinstance(input_sha256, str) or len(input_sha256) != 64:
            return None
        candidates = session.scalars(
            select(SpeciesSuggestionModel)
            .where(
                SpeciesSuggestionModel.visit_id == run_context.visit_id,
                SpeciesSuggestionModel.media_asset_id == run_context.media_asset_id,
                SpeciesSuggestionModel.adapter_id == BIOCLIP_ADAPTER_ID,
                SpeciesSuggestionModel.status == SpeciesSuggestionStatus.pending.value,
            )
            .order_by(
                SpeciesSuggestionModel.created_at.desc(),
                SpeciesSuggestionModel.rank,
                SpeciesSuggestionModel.id.desc(),
            )
        ).all()
        for candidate in candidates:
            evidence_region = _safe_json_object(candidate.evidence_region_json)
            provenance = evidence_region.get("model_provenance")
            identification_policy = evidence_region.get("identification_policy")
            reused_policy_version = (
                identification_policy.get("policy_version")
                if isinstance(identification_policy, dict)
                else None
            )
            if (
                evidence_region.get("input_sha256") == input_sha256
                and isinstance(provenance, dict)
                and provenance.get("adapter_id") == BIOCLIP_ADAPTER_ID
                and provenance.get("model_weights_verified") is True
                and provenance.get("labels_sha256")
                == _candidate_bank_sha256(
                    _species_candidate_pack_prompt_labels(run_context.candidate_pack)
                )
                # Same reasoning as _reusable_bioclip_suggestion above: never reuse
                # a suggestion recorded under a stale/absent eligibility policy
                # version -- a legacy pre-policy suggestion (no "identification_policy"
                # block at all) must always fall through to fresh inference.
                and reused_policy_version == IDENTIFICATION_ELIGIBILITY_POLICY_VERSION
            ):
                return _species_suggestion_from_model(candidate)
        return None

    def _apply_species_guess_from_suggestion(
        self,
        session: Session,
        *,
        target_type: str,
        target_id: str,
        suggestion: SpeciesSuggestionResponse,
    ) -> None:
        """Surface a fresh top-1 BioCLIP suggestion through the Visit's
        existing `species_guess` fallback -- already read everywhere
        `reviewed_label` is absent (Visit Detail, Dashboard Today,
        Stream/Event summaries) -- so an automatic suggestion is useful
        immediately, without a human review step first (Automatic Species
        Suggestion v1: docs/species-suggestion-adapter-design.md).

        Never touches a Visit that already carries authoritative reviewed
        truth: human confirmation/correction permanently wins, and a later
        automatic suggestion -- whether from the background engine hook or
        a manual "Identify again" -- must never overwrite it. This is a
        display convenience only; it creates no `ReviewLabel` and never
        marks a Visit reviewed, so training/export eligibility
        (`_visit_is_dataset_ready`) is unaffected.
        """

        if target_type != "visit":
            return
        visit_model = session.get(VisitModel, target_id)
        if visit_model is None or visit_model.review_status == ReviewStatus.reviewed.value:
            return
        visit_model.species_guess = suggestion.suggested_label

    def _identify_review_queue_with_bioclip(
        self,
        *,
        target_type: str,
        target_id: str,
        summary: ReviewIdentificationSummary,
        queue_item: ReviewQueueItem,
        run_context: _ReviewSpeciesRunContext,
        attempt_context: _BioClipAttemptContext,
        attempt_id: str,
        request: ReviewIdentificationRequest,
    ) -> ReviewIdentificationResponse:
        # Image decode and optional model inference deliberately happen after the
        # read session has closed. A slow local model must never hold a DB transaction.
        prepared_run: BioClipPreparedRun | None = None
        provenance_persistence_ns = 0
        crop_observation = _initial_bioclip_crop_provenance(attempt_context.crop)

        def retain_prepared_run(value: BioClipPreparedRun) -> None:
            nonlocal prepared_run, provenance_persistence_ns
            prepared_run = value
            persistence_started = time.monotonic_ns()
            try:
                self._record_bioclip_prepared_provenance(
                    attempt_id,
                    attempt_context=attempt_context,
                    prepared_run=value,
                )
            except Exception as error:
                raise ValueError("bioclip_persistence_failed") from error
            finally:
                provenance_persistence_ns += time.monotonic_ns() - persistence_started

        def load_input_image() -> Any:
            nonlocal provenance_persistence_ns
            image = _load_bioclip_input_image(
                local_path=run_context.local_path,
                expected_size_bytes=run_context.media_file_size_bytes,
                expected_mtime_ns=run_context.media_file_mtime_ns,
                content_type=run_context.content_type,
                crop=run_context.crop,
                observation=crop_observation,
            )
            persistence_started = time.monotonic_ns()
            try:
                self._record_bioclip_input_provenance(
                    attempt_id,
                    attempt_context=attempt_context,
                    crop_provenance=crop_observation,
                )
            except Exception as error:
                try:
                    image.close()
                except Exception:
                    pass
                raise ValueError("bioclip_persistence_failed") from error
            finally:
                provenance_persistence_ns += time.monotonic_ns() - persistence_started
            return image

        execution_started = time.monotonic_ns()
        try:
            prediction = run_bioclip_from_image_loader(
                load_input_image,
                _bioclip_config(
                    _species_candidate_pack_prompt_labels(run_context.candidate_pack)
                ),
                top_k=BIOCLIP_REVIEW_TOP_K,
                on_prepared=retain_prepared_run,
            )
            if not _bioclip_prediction_has_complete_candidate_bank(prediction):
                raise BioClipOutputError(
                    "BioCLIP did not return complete candidate-bank provenance."
                )
            if not prediction.suggestions:
                raise BioClipNoResultError(
                    "BioCLIP completed without a usable ranked suggestion."
                )
            # Identification Eligibility + Abstention v1: classification
            # abstention -- "even given a real result, is it strong and
            # specific enough to present as a species suggestion?" -- runs
            # here, after inference, distinct from the evidence-eligibility
            # check already applied before inference in
            # `_review_species_run_context`. Never averages/discards raw
            # candidates; only decides whether to present rank 1 at all.
            abstention = evaluate_classification_abstention(
                tuple(
                    IdentificationScoredCandidate(label=candidate.label, score=candidate.score)
                    for candidate in prediction.suggestions
                ),
                tier=classifier_input_tier(
                    classifier_input_type=run_context.crop.classifier_input_type,
                    crop_source=run_context.crop.source,
                ),
            )
            # Recorded on `crop_observation` -- already threaded through to
            # both the success (`SpeciesSuggestionModel.evidence_region_json`)
            # and failure (`bioclip_identification_attempts.crop_provenance_
            # json`) persistence paths below -- so the policy decision is
            # honestly recorded either way, never only on success.
            crop_observation["identification_policy"] = {
                "policy_version": IDENTIFICATION_ELIGIBILITY_POLICY_VERSION,
                "tier": abstention.tier,
                "top1_label": abstention.top1_label,
                "top1_score": abstention.top1_score,
                "margin": abstention.margin,
                "score_floor": abstention.score_floor,
                "margin_floor": abstention.margin_floor,
                "abstained": abstention.abstained,
            }
            if abstention.abstained:
                raise ValueError("bioclip_identification_ambiguous")
            suggestion_payload = _bioclip_species_suggestion_payload(
                prediction,
                run_context=run_context,
                crop_provenance=crop_observation,
                request_notes=_clean_optional_text(request.notes),
            )
            if suggestion_payload is None:
                raise BioClipNoResultError(
                    "BioCLIP completed without a usable ranked suggestion."
                )
        except BioClipBusyError:
            error_code = "bioclip_busy"
        except BioClipTimeoutError:
            error_code = "bioclip_timed_out"
        except BioClipNoResultError:
            error_code = "bioclip_no_result"
        except BioClipConfigurationError:
            error_code = "bioclip_configuration_error"
        except BioClipWorkerFailureError:
            error_code = "bioclip_worker_failed"
        except BioClipRuntimeUnavailableError:
            error_code = "bioclip_runtime_unavailable"
        except BioClipUnsupportedImageError:
            error_code = "bioclip_unsupported_image"
        except BioClipOutputError:
            error_code = "bioclip_failed"
        except (OSError, ValueError) as caught:
            error_code = _safe_bioclip_error_code(str(caught))
        except Exception:
            error_code = "bioclip_unexpected_failure"
        else:
            error_code = None
        duration_ms = _elapsed_milliseconds(
            execution_started,
            excluded_ns=provenance_persistence_ns,
        )

        if error_code is not None:
            attempt_outcome, error_stage, error_detail = (
                _bioclip_attempt_failure_fields(error_code)
            )
            self._complete_bioclip_identification_attempt(
                attempt_id,
                attempt_context=attempt_context,
                outcome=attempt_outcome,
                duration_ms=duration_ms,
                timeout_exceeded=error_code == "bioclip_timed_out",
                crop_provenance=crop_observation,
                prepared_run=prepared_run,
                error_code=error_code,
                error_stage=error_stage,
                error_detail=error_detail,
            )
            error = ValueError(error_code)
            error_summary = self._review_identification_error_summary(summary, error)
            return self._review_identification_response(
                target_type=target_type,
                target_id=target_id,
                identification=error_summary,
                review_queue_item=queue_item,
                warnings=[str(error)],
            )

        try:
            with self.session_factory() as session:
                with session.begin():
                    current_item = self._review_queue_item_by_target(
                        session,
                        target_type,
                        target_id,
                    )
                    if current_item is None:
                        raise ValueError("missing_review_candidate")
                    if session.get(MediaAssetModel, run_context.media_asset_id) is None:
                        raise ValueError("missing_media_asset")
                    # Same-Frame Species Evidence v1: the classifier-input
                    # override asset (if any) is re-validated too -- the same
                    # "nothing was silently removed underneath this read"
                    # discipline the primary review asset already gets above.
                    if (
                        run_context.crop.classifier_input_media_asset_id is not None
                        and session.get(
                            MediaAssetModel, run_context.crop.classifier_input_media_asset_id,
                        )
                        is None
                    ):
                        raise ValueError("missing_media_asset")
                    current_media_asset_id = current_item.best_media_asset_id or (
                        current_item.media_asset.id
                        if current_item.media_asset is not None
                        else None
                    )
                    if current_media_asset_id != run_context.media_asset_id:
                        raise ValueError("bioclip_media_not_review_frame")
                    if not _bioclip_media_file_matches_run_context(run_context):
                        raise ValueError("bioclip_media_changed")
                    if _review_item_has_active_restricted_zone(
                        session,
                        current_item,
                    ) or _review_species_crop_intersects_restricted_zone(
                        session,
                        stream_id=run_context.stream_id,
                        crop=run_context.crop,
                    ):
                        raise ValueError("identification_zone_suppressed")

                    self._supersede_pending_bioclip_suggestions(
                        session,
                        run_context=run_context,
                    )
                    suggestion = self._create_species_suggestion_in_session(
                        session,
                        suggestion_payload,
                    )
                    self._apply_species_guess_from_suggestion(
                        session,
                        target_type=target_type,
                        target_id=target_id,
                        suggestion=suggestion,
                    )
                    self._complete_bioclip_identification_attempt_in_session(
                        session,
                        attempt_id,
                        attempt_context=attempt_context,
                        outcome="succeeded",
                        duration_ms=duration_ms,
                        timeout_exceeded=False,
                        crop_provenance=crop_observation,
                        prepared_run=prepared_run,
                        prediction=prediction,
                        resulting_species_suggestion_id=suggestion.id,
                    )
                    refreshed_item = self._review_queue_item_by_target(
                        session,
                        target_type,
                        target_id,
                    )
                    refreshed_summary = (
                        refreshed_item.identification
                        if refreshed_item is not None
                        and refreshed_item.identification is not None
                        else summary
                    )
                    outcome = refreshed_summary.model_copy(
                        update={
                            "status": ReviewIdentificationStatus.suggestion_created,
                            "message": (
                                "BioCLIP created one ranked SpeciesSuggestion as "
                                "candidate-relative, uncalibrated evidence. Review and "
                                "explicit correction still create truth."
                            ),
                            "adapter_id": BIOCLIP_ADAPTER_ID,
                            "adapter_name": BIOCLIP_ADAPTER_NAME,
                            "adapter_kind": ModelAdapterKind.species_classifier,
                            "adapter_status": summary.adapter_status,
                            "adapter_is_demo": False,
                            "setup_status": summary.setup_status,
                            "suggestion": suggestion,
                            "suggestion_count": max(
                                refreshed_summary.suggestion_count,
                                1,
                            ),
                            "unavailable_reason": None,
                            "created_suggestion_ids": [suggestion.id],
                            "created_proposal_ids": [],
                            **_review_species_focus_fields(
                                run_context.crop,
                                refreshed_item or queue_item,
                            ),
                        }
                    )
                    return self._review_identification_response(
                        target_type=target_type,
                        target_id=target_id,
                        identification=outcome,
                        review_queue_item=refreshed_item,
                    )
        except Exception as caught:
            caught_code = (
                _safe_bioclip_revalidation_error_code(str(caught))
                if isinstance(caught, ValueError)
                else None
            )
            error_code = caught_code or "bioclip_persistence_failed"
            attempt_outcome, error_stage, error_detail = (
                _bioclip_attempt_failure_fields(error_code)
            )
            self._complete_bioclip_identification_attempt(
                attempt_id,
                attempt_context=attempt_context,
                outcome=attempt_outcome,
                duration_ms=duration_ms,
                timeout_exceeded=False,
                crop_provenance=crop_observation,
                prepared_run=prepared_run,
                prediction=prediction,
                error_code=error_code,
                error_stage=error_stage,
                error_detail=error_detail,
            )
            safe_error = ValueError(error_code)
            error_summary = self._review_identification_error_summary(
                summary,
                safe_error,
            )
            return self._review_identification_response(
                target_type=target_type,
                target_id=target_id,
                identification=error_summary,
                review_queue_item=queue_item,
                warnings=[error_code],
            )

    def _review_species_run_context(
        self,
        session: Session,
        item: ReviewQueueItem,
        *,
        target_type: str,
        target_id: str,
        media_asset_id: str,
    ) -> _ReviewSpeciesRunContext:
        media_asset = session.get(MediaAssetModel, media_asset_id)
        if media_asset is None:
            raise ValueError("missing_media_asset")
        review_media_asset_id = item.best_media_asset_id or (
            item.media_asset.id if item.media_asset is not None else None
        )
        if review_media_asset_id != media_asset_id:
            # Activity/detector crop provenance belongs to the Review Queue item's
            # selected frame. A same-Stream asset is not automatically part of
            # this Event/Visit evidence graph.
            raise ValueError("bioclip_media_not_review_frame")
        if (
            media_asset.media_type != "image"
            or media_asset.content_type not in BIOCLIP_SUPPORTED_IMAGE_CONTENT_TYPES
        ):
            raise ValueError("bioclip_unsupported_media_type")
        if media_asset.stream_id != item.stream_id:
            raise ValueError("media_stream_mismatch")
        media_path = Path(media_asset.local_path)
        try:
            media_stat = media_path.stat()
        except OSError as error:
            raise ValueError("missing_media_file") from error
        if not media_path.is_file():
            raise ValueError("missing_media_file")

        evidence = self._motion_evidence_for_review_queue_item(
            session,
            event_id=item.event_id,
            visit_id=item.visit_id,
            media_asset_id=media_asset_id,
        )
        if _review_item_has_active_restricted_zone(session, item):
            raise ValueError("identification_zone_suppressed")
        crop = self._review_species_crop_context(
            session,
            item,
            media_asset_id=media_asset_id,
        )
        if _review_species_crop_intersects_restricted_zone(
            session,
            stream_id=item.stream_id,
            crop=crop,
        ):
            raise ValueError("identification_zone_suppressed")
        # Identification Eligibility + Abstention v1 (docs/identification-
        # eligibility-abstention-v1-report.md): evidence eligibility is
        # evaluated once, here, before any model call -- "is this evidence
        # good enough to attempt identification?" -- distinct from
        # classification abstention (evaluated after inference, in
        # `_identify_review_queue_with_bioclip`, "is the result strong
        # enough to present?"). A structural floor only; do not add a
        # tuned small-subject cutoff here -- real field data proved bbox
        # coverage does not separate real animals from background evidence
        # (see the report).
        classifier_input_width, classifier_input_height = (
            _classifier_input_pixel_dimensions(crop, media_asset)
        )
        eligibility = evaluate_identification_eligibility(
            classifier_input_width=classifier_input_width,
            classifier_input_height=classifier_input_height,
        )
        if not eligibility.eligible:
            raise ValueError("bioclip_identification_evidence_ineligible")

        pack_model, _pack_warning, _selected_pack_id = (
            self._effective_species_candidate_pack_for_stream(session, item.stream_id)
        )
        candidate_pack = self._species_candidate_pack_from_model(session, pack_model)

        # Same-Frame Species Evidence v1 (see docs/same-frame-species-
        # evidence-contract.md): when `crop` resolved to a *different*
        # persisted MediaAsset (a same-frame exact-box crop or a reused
        # persisted crop), the bytes BioCLIP actually reads come from THAT
        # asset's own file -- never the Visit's ordinary review frame -- so
        # the anti-TOCTOU identity this context carries must describe the
        # file that is actually opened, not `media_asset`. `media_asset_id`
        # itself deliberately stays the Visit's own review frame throughout
        # (every concurrency re-check keyed on it elsewhere is unaffected);
        # only the physical file identity changes here.
        local_path = crop.classifier_input_local_path or media_asset.local_path
        file_size_bytes = (
            crop.classifier_input_size_bytes
            if crop.classifier_input_size_bytes is not None
            else media_stat.st_size
        )
        file_mtime_ns = (
            crop.classifier_input_mtime_ns
            if crop.classifier_input_mtime_ns is not None
            else media_stat.st_mtime_ns
        )
        content_type = crop.classifier_input_content_type or media_asset.content_type
        return _ReviewSpeciesRunContext(
            target_type=target_type,
            target_id=target_id,
            local_path=local_path,
            media_file_size_bytes=file_size_bytes,
            media_file_mtime_ns=file_mtime_ns,
            content_type=content_type,
            source_id=item.source_id,
            stream_id=item.stream_id,
            event_id=item.event_id,
            visit_id=item.visit_id if target_type == "visit" else None,
            media_asset_id=media_asset_id,
            motion_evidence_id=evidence.id if evidence is not None else None,
            zone_id=(
                item.zone_id
                or item.primary_zone_id
                or (evidence.zone_id if evidence is not None else None)
            ),
            crop=crop,
            candidate_pack=candidate_pack,
        )

    def _review_bioclip_attempt_context(
        self,
        session: Session,
        item: ReviewQueueItem,
        *,
        target_type: str,
        target_id: str,
        media_asset_id: str,
        run_context: _ReviewSpeciesRunContext | None,
    ) -> _BioClipAttemptContext:
        if run_context is not None:
            return _BioClipAttemptContext(
                target_type=run_context.target_type,
                target_id=run_context.target_id,
                source_id=run_context.source_id,
                stream_id=run_context.stream_id,
                zone_id=run_context.zone_id,
                event_id=run_context.event_id,
                visit_id=run_context.visit_id,
                media_asset_id=run_context.media_asset_id,
                motion_evidence_id=run_context.motion_evidence_id,
                crop=run_context.crop,
                candidate_pack=run_context.candidate_pack,
            )

        media_asset = session.get(MediaAssetModel, media_asset_id)
        if media_asset is None:
            raise ValueError("missing_media_asset")
        evidence = self._motion_evidence_for_review_queue_item(
            session,
            event_id=item.event_id,
            visit_id=item.visit_id if target_type == "visit" else None,
            media_asset_id=media_asset_id,
        )
        crop: _ReviewSpeciesCropContext | None = None
        review_media_asset_id = item.best_media_asset_id or (
            item.media_asset.id if item.media_asset is not None else None
        )
        if (
            review_media_asset_id == media_asset_id
            and media_asset.stream_id == item.stream_id
            and media_asset.media_type == "image"
            and media_asset.content_type in BIOCLIP_SUPPORTED_IMAGE_CONTENT_TYPES
        ):
            crop = self._review_species_crop_context(
                session,
                item,
                media_asset_id=media_asset_id,
            )
        pack_model, _pack_warning, _selected_pack_id = (
            self._effective_species_candidate_pack_for_stream(session, item.stream_id)
        )
        candidate_pack = self._species_candidate_pack_from_model(session, pack_model)

        return _BioClipAttemptContext(
            target_type=target_type,
            target_id=target_id,
            source_id=item.source_id,
            stream_id=item.stream_id,
            zone_id=(
                item.zone_id
                or item.primary_zone_id
                or (evidence.zone_id if evidence is not None else None)
            ),
            event_id=item.event_id,
            visit_id=item.visit_id if target_type == "visit" else None,
            media_asset_id=media_asset_id,
            motion_evidence_id=evidence.id if evidence is not None else None,
            crop=crop,
            candidate_pack=candidate_pack,
        )

    def _create_bioclip_identification_attempt(
        self,
        attempt_context: _BioClipAttemptContext,
    ) -> str:
        """Persist the one durable start record before optional runtime work begins."""

        attempt_id = f"bioclip-attempt-{uuid.uuid4().hex}"
        config = _bioclip_config(
            _species_candidate_pack_prompt_labels(attempt_context.candidate_pack)
        )
        with self.session_factory() as session:
            with session.begin():
                session.add(
                    BioClipIdentificationAttemptModel(
                        id=attempt_id,
                        target_type=attempt_context.target_type,
                        target_id=attempt_context.target_id,
                        event_id=attempt_context.event_id,
                        visit_id=(
                            attempt_context.visit_id
                            if attempt_context.target_type == "visit"
                            else None
                        ),
                        media_asset_id=attempt_context.media_asset_id,
                        source_id=attempt_context.source_id,
                        stream_id=attempt_context.stream_id,
                        zone_id=attempt_context.zone_id,
                        motion_evidence_id=attempt_context.motion_evidence_id,
                        detection_proposal_id=(
                            attempt_context.crop.detection_proposal_id
                            if attempt_context.crop is not None
                            else None
                        ),
                        resulting_species_suggestion_id=None,
                        adapter_id=BIOCLIP_ADAPTER_ID,
                        started_at=datetime.now(UTC),
                        completed_at=None,
                        duration_ms=None,
                        timeout_limit_ms=round(BIOCLIP_RUN_TIMEOUT_SECONDS * 1000),
                        timeout_exceeded=False,
                        outcome=None,
                        crop_source=(
                            attempt_context.crop.source
                            if attempt_context.crop is not None
                            else None
                        ),
                        crop_provenance_json=(
                            _bioclip_attempt_json(
                                _initial_bioclip_crop_provenance(attempt_context.crop),
                            )
                            if attempt_context.crop is not None
                            else None
                        ),
                        model_provenance_json=_bioclip_attempt_json(
                            {
                                "adapter_id": BIOCLIP_ADAPTER_ID,
                                "adapter_name": BIOCLIP_ADAPTER_NAME,
                                "device": (
                                    "cpu"
                                    if config.device == "cpu"
                                    else "unvalidated"
                                ),
                                "prepared": False,
                                "candidate_pack": _species_candidate_pack_provenance(
                                    attempt_context.candidate_pack
                                ),
                            },
                        ),
                        preprocessing_json=None,
                        candidate_manifest_json=None,
                        candidate_set_count=None,
                        candidate_set_sha256=None,
                        candidate_set_version=None,
                        candidate_pack_id=attempt_context.candidate_pack.id,
                        candidate_pack_version=attempt_context.candidate_pack.version,
                        candidate_pack_sha256=attempt_context.candidate_pack.content_sha256,
                        candidate_manifest_complete=False,
                        error_code=None,
                        error_stage=None,
                        error_detail=None,
                        provenance_schema_version=1,
                    )
                )
                session.flush()
        return attempt_id

    def _complete_bioclip_identification_attempt(
        self,
        attempt_id: str,
        *,
        attempt_context: _BioClipAttemptContext,
        outcome: str,
        duration_ms: int | None,
        timeout_exceeded: bool,
        crop_provenance: dict[str, Any] | None = None,
        prepared_run: BioClipPreparedRun | None = None,
        prediction: BioClipPrediction | None = None,
        resulting_species_suggestion_id: str | None = None,
        error_code: str | None = None,
        error_stage: str | None = None,
        error_detail: str | None = None,
    ) -> None:
        with self.session_factory() as session:
            with session.begin():
                self._complete_bioclip_identification_attempt_in_session(
                    session,
                    attempt_id,
                    attempt_context=attempt_context,
                    outcome=outcome,
                    duration_ms=duration_ms,
                    timeout_exceeded=timeout_exceeded,
                    crop_provenance=crop_provenance,
                    prepared_run=prepared_run,
                    prediction=prediction,
                    resulting_species_suggestion_id=(resulting_species_suggestion_id),
                    error_code=error_code,
                    error_stage=error_stage,
                    error_detail=error_detail,
                )

    def _record_bioclip_prepared_provenance(
        self,
        attempt_id: str,
        *,
        attempt_context: _BioClipAttemptContext,
        prepared_run: BioClipPreparedRun,
    ) -> None:
        """Durably retain validated bank/model context before decode or inference."""

        artifacts = _bioclip_attempt_artifacts(
            prepared_run=prepared_run,
            prediction=None,
            candidate_pack=attempt_context.candidate_pack,
        )
        with self.session_factory() as session:
            with session.begin():
                attempt = session.get(
                    BioClipIdentificationAttemptModel,
                    attempt_id,
                )
                if (
                    attempt is None
                    or attempt.outcome is not None
                    or attempt.target_type != attempt_context.target_type
                    or attempt.target_id != attempt_context.target_id
                    or attempt.media_asset_id != attempt_context.media_asset_id
                ):
                    raise RuntimeError(
                        "BioCLIP attempt cannot accept prepared provenance."
                    )
                attempt.model_provenance_json = _bioclip_attempt_json(
                    artifacts["model_provenance"]
                )
                attempt.preprocessing_json = _bioclip_attempt_json(
                    artifacts["preprocessing"]
                )
                attempt.candidate_manifest_json = _bioclip_attempt_json(
                    artifacts["candidate_manifest"]
                )
                attempt.candidate_set_count = artifacts["candidate_set_count"]
                attempt.candidate_set_sha256 = artifacts["candidate_set_sha256"]
                attempt.candidate_set_version = artifacts["candidate_set_version"]
                attempt.candidate_pack_id = attempt_context.candidate_pack.id
                attempt.candidate_pack_version = attempt_context.candidate_pack.version
                attempt.candidate_pack_sha256 = attempt_context.candidate_pack.content_sha256
                attempt.candidate_manifest_complete = artifacts[
                    "candidate_manifest_complete"
                ]
                session.flush()

    def _record_bioclip_input_provenance(
        self,
        attempt_id: str,
        *,
        attempt_context: _BioClipAttemptContext,
        crop_provenance: dict[str, Any],
    ) -> None:
        """Durably retain the exact prepared crop before worker inference."""

        with self.session_factory() as session:
            with session.begin():
                attempt = session.get(
                    BioClipIdentificationAttemptModel,
                    attempt_id,
                )
                if (
                    attempt is None
                    or attempt.outcome is not None
                    or attempt.target_type != attempt_context.target_type
                    or attempt.target_id != attempt_context.target_id
                    or attempt.media_asset_id != attempt_context.media_asset_id
                ):
                    raise RuntimeError(
                        "BioCLIP attempt cannot accept input provenance."
                    )
                attempt.crop_provenance_json = _bioclip_attempt_json(crop_provenance)
                session.flush()

    def _complete_bioclip_identification_attempt_in_session(
        self,
        session: Session,
        attempt_id: str,
        *,
        attempt_context: _BioClipAttemptContext,
        outcome: str,
        duration_ms: int | None,
        timeout_exceeded: bool,
        crop_provenance: dict[str, Any] | None = None,
        prepared_run: BioClipPreparedRun | None = None,
        prediction: BioClipPrediction | None = None,
        resulting_species_suggestion_id: str | None = None,
        error_code: str | None = None,
        error_stage: str | None = None,
        error_detail: str | None = None,
    ) -> None:
        attempt = session.get(BioClipIdentificationAttemptModel, attempt_id)
        if attempt is None:
            raise RuntimeError("BioCLIP attempt evidence is missing.")
        if attempt.outcome is not None or attempt.completed_at is not None:
            raise RuntimeError("BioCLIP attempt evidence is already terminal.")
        if (
            attempt.target_type != attempt_context.target_type
            or attempt.target_id != attempt_context.target_id
            or attempt.media_asset_id != attempt_context.media_asset_id
        ):
            raise RuntimeError("BioCLIP attempt linkage changed before completion.")
        if (
            resulting_species_suggestion_id is not None
            and session.get(
                SpeciesSuggestionModel,
                resulting_species_suggestion_id,
            )
            is None
        ):
            raise RuntimeError("BioCLIP result suggestion is missing.")

        effective_crop = (
            crop_provenance
            if crop_provenance is not None
            else _initial_bioclip_crop_provenance(attempt_context.crop)
        )
        attempt.completed_at = datetime.now(UTC)
        attempt.duration_ms = duration_ms
        attempt.timeout_exceeded = timeout_exceeded
        attempt.outcome = outcome
        attempt.crop_source = (
            attempt_context.crop.source if attempt_context.crop is not None else None
        )
        attempt.crop_provenance_json = (
            _bioclip_attempt_json(effective_crop) if effective_crop else None
        )
        if prediction is not None or prepared_run is not None:
            artifacts = _bioclip_attempt_artifacts(
                prepared_run=prepared_run,
                prediction=prediction,
                candidate_pack=attempt_context.candidate_pack,
            )
            attempt.model_provenance_json = (
                _bioclip_attempt_json(artifacts["model_provenance"])
                if artifacts["model_provenance"]
                else attempt.model_provenance_json
            )
            attempt.preprocessing_json = (
                _bioclip_attempt_json(artifacts["preprocessing"])
                if artifacts["preprocessing"]
                else None
            )
            attempt.candidate_manifest_json = (
                _bioclip_attempt_json(artifacts["candidate_manifest"])
                if artifacts["candidate_manifest"]
                else None
            )
            attempt.candidate_set_count = artifacts["candidate_set_count"]
            attempt.candidate_set_sha256 = artifacts["candidate_set_sha256"]
            attempt.candidate_set_version = artifacts["candidate_set_version"]
            attempt.candidate_manifest_complete = artifacts[
                "candidate_manifest_complete"
            ]
        attempt.resulting_species_suggestion_id = resulting_species_suggestion_id
        attempt.error_code = error_code
        attempt.error_stage = error_stage
        attempt.error_detail = error_detail
        session.flush()

    def list_bioclip_identification_attempts(
        self,
        *,
        target_type: str | None = None,
        target_id: str | None = None,
    ) -> list[dict[str, Any]]:
        """Return safe evidence summaries; attempt records have no mutation API."""

        with self.session_factory() as session:
            query = select(BioClipIdentificationAttemptModel)
            if target_type is not None:
                query = query.where(
                    BioClipIdentificationAttemptModel.target_type == target_type.strip()
                )
            if target_id is not None:
                query = query.where(
                    BioClipIdentificationAttemptModel.target_id == target_id.strip()
                )
            attempts = session.scalars(
                query.order_by(
                    BioClipIdentificationAttemptModel.started_at,
                    BioClipIdentificationAttemptModel.id,
                )
            ).all()
            return [_bioclip_attempt_record(attempt) for attempt in attempts]

    def _classifier_same_frame_asset_for_visit(
        self, session: Session, visit_id: str,
    ) -> MediaAssetModel | None:
        """The (at most one, by construction -- see `candidate_visit_adapter.
        _build_evidence_items`) `classifier_same_frame`-role MediaAsset
        linked to this Visit, if any. Deterministic when, contrary to that
        construction guarantee, more than one somehow exists: earliest
        `VisitEvidenceLinkModel.created_at`, then link id."""

        link = session.scalars(
            select(VisitEvidenceLinkModel)
            .where(
                VisitEvidenceLinkModel.visit_id == visit_id,
                VisitEvidenceLinkModel.evidence_role == CLASSIFIER_SAME_FRAME_EVIDENCE_ROLE,
            )
            .order_by(VisitEvidenceLinkModel.created_at, VisitEvidenceLinkModel.id)
        ).first()
        return session.get(MediaAssetModel, link.media_asset_id) if link is not None else None

    def _persisted_subject_crop_assets_for_visit(
        self, session: Session, visit_id: str,
    ) -> list[MediaAssetModel]:
        """Every already-persisted derived-crop MediaAsset
        (`classifier_input.PERSISTED_CROP_EVIDENCE_ROLES`) linked to this
        Visit -- reused as-is by the resolver's own tier 1, never re-derived
        here. Today this is always empty (see project memory: 0/24 real
        MediaAssets have ever had a derived crop); kept real and queried
        honestly rather than skipped, so a future reviewer-refinement/
        activity-crop feature activates this tier for free."""

        links = session.scalars(
            select(VisitEvidenceLinkModel).where(
                VisitEvidenceLinkModel.visit_id == visit_id,
                VisitEvidenceLinkModel.evidence_role.in_(PERSISTED_CROP_EVIDENCE_ROLES),
            )
        ).all()
        assets = [session.get(MediaAssetModel, link.media_asset_id) for link in links]
        return [asset for asset in assets if asset is not None]

    def _native_resolution_candidate_assets_for_visit(
        self, session: Session, visit_id: str,
    ) -> list[MediaAssetModel]:
        """Every already-persisted evidence MediaAsset linked to this Visit
        whose own lineage proves genuinely higher-resolution, FOV-aligned
        correspondence (`GeometryAttribution.resolution_provenance ==
        "synchronized"` -- Source-Resolution + Multi-Frame Species Evidence
        v1). Deliberately not filtered by `evidence_role`: a winning
        `high_resolution_burst`-origin `EvidenceCandidate` is persisted under
        whichever role `evidence_scoring.score_proposal_evidence` assigned it
        (`identification`/`context`/`alternate`), never the origin role
        string itself -- see `candidate_visit_adapter._build_evidence_items`.
        `resolution_provenance` is the one signal that survives that
        relabeling, and only a genuine burst-origin candidate can ever carry
        it, so this needs no separate role check.

        Ordered by `VisitEvidenceLinkModel.created_at`/id -- the exact order
        `_build_evidence_items` inserted them in (identification pick first,
        then context, then alternates by identification score) -- reusing
        the Stage 6 scorer's already-computed quality ranking rather than
        re-deriving one here (see "Quality ranking" in
        docs/source-resolution-multi-frame-species-evidence-contract.md)."""

        links = session.scalars(
            select(VisitEvidenceLinkModel)
            .where(VisitEvidenceLinkModel.visit_id == visit_id)
            .order_by(VisitEvidenceLinkModel.created_at, VisitEvidenceLinkModel.id)
        ).all()
        candidates: list[MediaAssetModel] = []
        for link in links:
            asset = session.get(MediaAssetModel, link.media_asset_id)
            if asset is None:
                continue
            attribution = geometry_attribution_from_json(asset.geometry_attribution_json)
            if attribution is not None and attribution.resolution_provenance == "synchronized":
                candidates.append(asset)
        return candidates

    def _native_resolution_subject_frames_for_visit(
        self, session: Session, visit_id: str,
    ) -> tuple[ClassifierInputSubjectFrame, ...]:
        """`_native_resolution_candidate_assets_for_visit`, projected into
        the pure resolver's own input shape -- the one seam both the
        single-best-frame override below and the multi-frame candidate
        builder (`species_multi_frame_candidate_plans`) share, so neither
        can silently diverge on which assets count."""

        assets = self._native_resolution_candidate_assets_for_visit(session, visit_id)
        frames = (
            _classifier_input_subject_frame_from_asset(asset) for asset in assets
        )
        return tuple(frame for frame in frames if frame is not None)

    def species_multi_frame_candidate_plans(
        self, visit_id: str, *, max_candidates: int = MAX_LIVE_VISIT_EVIDENCE_FRAMES,
    ) -> tuple[ClassifierInputPlan, ...]:
        """Bounded, quality-ranked classifier-input plans for every
        genuinely distinct, safe-to-crop evidence frame this Visit has --
        the same-frame analysis-resolution asset (if any) plus native-
        resolution candidates, each independently resolved via the exact
        same pure resolver tiers `_classifier_input_override` uses for its
        single-best pick (never a second, parallel selection system).

        Read-only and side-effect-free: never runs a model, never persists
        anything, never mutates a Visit. The one seam a multi-frame species-
        identification consumer (today: the governed benchmark in
        `scripts/benchmark_source_resolution_species_evidence.py`; a future
        production consensus pass would use the identical seam) builds its
        candidate set from.

        `max_candidates` defaults to `MAX_LIVE_VISIT_EVIDENCE_FRAMES` (4) --
        not an arbitrary new number, but the existing, already-measured
        ceiling on how many evidence frames a Visit ever retains at all
        (see that constant's own definition); a real Visit can supply at
        most one same-frame asset and `MAX_LIVE_VISIT_EVIDENCE_FRAMES - 1`
        distinct native-resolution alternates today. Order is best-quality-
        first (same-frame, when eligible, then native candidates in
        `_native_resolution_subject_frames_for_visit`'s already-established
        evidence-scoring-derived order) -- the exact order a consensus
        policy should evaluate/report from.
        """

        if max_candidates < 1:
            raise ValueError("invalid_max_candidates")
        with self.session_factory() as session:
            plans: list[ClassifierInputPlan] = []
            same_frame_asset = self._classifier_same_frame_asset_for_visit(session, visit_id)
            if same_frame_asset is not None:
                subject_frame = _classifier_input_subject_frame_from_asset(same_frame_asset)
                if subject_frame is not None:
                    plan = resolve_classifier_input(subject_frame=subject_frame)
                    if not plan.used_full_frame_fallback:
                        plans.append(plan)
            for native_frame in self._native_resolution_subject_frames_for_visit(session, visit_id):
                if len(plans) >= max_candidates:
                    break
                native_plan = resolve_native_resolution_subject_crop(native_frame)
                if native_plan is not None and native_plan.media_asset_id not in {
                    plan.media_asset_id for plan in plans
                }:
                    plans.append(native_plan)
            return tuple(plans[:max_candidates])

    def _classifier_input_override(
        self,
        session: Session,
        item: ReviewQueueItem,
        *,
        media_asset_id: str,
    ) -> _ReviewSpeciesCropContext | None:
        """Same-Frame Species Evidence v1 (see docs/same-frame-species-
        evidence-contract.md): prefer `classifier_input.
        resolve_classifier_input`'s own subject-centric classifier input
        over this Visit's ordinary review frame, when a genuinely safer
        input actually exists.

        Returns `None` -- never raises -- the instant anything about the
        same-frame/persisted-crop evidence is missing, malformed, or merely
        "not better than full frame": the caller (`_review_species_crop_
        context`) falls through to the existing megadetector/activity/
        full_frame tiers completely unchanged in every one of those cases.
        This is the concrete "missing asset fallback" / "species inference
        must remain non-blocking" guarantee, enforced structurally rather
        than by convention.

        Only ever consulted for a Visit (`item.visit_id`): both new resolver
        tiers need a Visit-linked MediaAsset only the Observation Engine's
        candidate-Visit path can ever produce -- a legacy Event-only Review
        Queue item safely short-circuits on the very first check below.

        Source-Resolution + Multi-Frame Species Evidence v1 adds a third
        input source here, `native_resolution_candidates` -- this Visit's
        already-persisted, genuinely higher-resolution evidence whose own
        lineage proves FOV-aligned correspondence (see
        `_native_resolution_subject_frames_for_visit`). `resolve_classifier_
        input` ranks it ahead of the same-frame/full-frame tiers on the
        *primary* `subject_frame` below, but never ahead of tier 1 (an
        already-curated persisted crop) -- see that resolver's own decision
        order.
        """
        if item.visit_id is None:
            return None
        try:
            same_frame_asset = self._classifier_same_frame_asset_for_visit(session, item.visit_id)
            persisted_crop_assets = self._persisted_subject_crop_assets_for_visit(session, item.visit_id)
            native_resolution_candidates = self._native_resolution_subject_frames_for_visit(
                session, item.visit_id,
            )
            if (
                same_frame_asset is None
                and not persisted_crop_assets
                and not native_resolution_candidates
            ):
                return None
            subject_asset = same_frame_asset or session.get(MediaAssetModel, media_asset_id)
            if subject_asset is None:
                return None
            subject_frame = _classifier_input_subject_frame_from_asset(subject_asset)
            if subject_frame is None:
                return None
            persisted_candidates = tuple(
                _classifier_input_crop_asset_from_model(asset) for asset in persisted_crop_assets
            )
            plan = resolve_classifier_input(
                subject_frame=subject_frame,
                persisted_crop_candidates=persisted_candidates,
                native_resolution_candidates=native_resolution_candidates,
            )
            if plan.used_full_frame_fallback:
                return None
            override_asset = session.get(MediaAssetModel, plan.media_asset_id)
            if override_asset is None:
                return None
            override_path = Path(override_asset.local_path)
            if not override_path.is_file():
                return None
            override_stat = override_path.stat()
        except (OSError, ValueError, TypeError, json.JSONDecodeError):
            return None
        box_normalized = (
            _bounding_box_from_crop_box(plan.crop_box_normalized)
            if plan.crop_box_normalized is not None
            else BoundingBox(x=0.0, y=0.0, width=1.0, height=1.0)
        )
        input_type = {
            "exact_frame_subject_box": "same_frame_crop",
            "native_resolution_subject_box": "native_resolution_crop",
        }.get(plan.source, "persisted_crop")
        label = {
            "same_frame_crop": "Same-frame subject crop (classifier evidence)",
            "native_resolution_crop": "Native-resolution subject crop (classifier evidence)",
        }.get(input_type, "Reused persisted subject crop (classifier evidence)")
        return _ReviewSpeciesCropContext(
            source="activity",
            box_normalized=box_normalized,
            label=label,
            classifier_input_media_asset_id=override_asset.id,
            classifier_input_local_path=str(override_path),
            classifier_input_size_bytes=override_stat.st_size,
            classifier_input_mtime_ns=override_stat.st_mtime_ns,
            classifier_input_content_type=override_asset.content_type,
            classifier_input_source_width=plan.original_width,
            classifier_input_source_height=plan.original_height,
            classifier_input_width=plan.input_width,
            classifier_input_height=plan.input_height,
            classifier_input_type=input_type,
            # Honest "not applicable" (`None`), never a fabricated `False`,
            # for a reused persisted crop -- `same_frame` is a fact about
            # *this* resolution's own tier 2 proof, not a property a reused
            # tier-1 crop asset is being asked to re-prove here. A native-
            # resolution crop *positively* proves `same_frame=False` (that
            # is exactly what `resolution_provenance == "synchronized"`
            # means -- a genuinely separate, later capture), so it reports
            # the real fact rather than "not applicable."
            classifier_input_same_frame=(
                True if input_type == "same_frame_crop"
                else False if input_type == "native_resolution_crop"
                else None
            ),
            classifier_input_crop_method=plan.crop_method,
            classifier_input_selection_reason=plan.selection_reason,
        )

    def _review_species_crop_context(
        self,
        session: Session,
        item: ReviewQueueItem,
        *,
        media_asset_id: str,
    ) -> _ReviewSpeciesCropContext:
        override = self._classifier_input_override(session, item, media_asset_id=media_asset_id)
        if override is not None:
            return override
        proposal = self._credible_megadetector_animal_proposal(
            session,
            item,
            media_asset_id=media_asset_id,
        )
        if proposal is not None:
            bbox = _valid_detection_proposal_bbox(proposal)
            assert bbox is not None
            padded = plan_activity_crop_bounds(
                left=bbox.x,
                top=bbox.y,
                right=bbox.x + bbox.width,
                bottom=bbox.y + bbox.height,
            )
            if not padded.is_full_frame_fallback:
                return _ReviewSpeciesCropContext(
                    source="megadetector",
                    box_normalized=_bounding_box_from_crop_box(
                        padded.crop_box_normalized
                    ),
                    label="MegaDetector animal focus",
                    detection_proposal_id=proposal.id,
                )

        if (
            item.focus_crop_available
            and item.focus_crop_source == FocusCropSource.activity
            and item.focus_crop_box_normalized is not None
        ):
            return _ReviewSpeciesCropContext(
                source="activity",
                box_normalized=item.focus_crop_box_normalized,
                label=item.focus_crop_label or "Detected activity focus",
            )

        return _ReviewSpeciesCropContext(
            source="full_frame",
            box_normalized=BoundingBox(x=0.0, y=0.0, width=1.0, height=1.0),
            label="Full frame fallback",
        )

    def _credible_megadetector_animal_proposal(
        self,
        session: Session,
        item: ReviewQueueItem,
        *,
        media_asset_id: str,
    ) -> DetectionProposalModel | None:
        candidates = self._review_identification_proposal_models(
            session,
            item,
            media_asset_id=media_asset_id,
        )
        credible: list[DetectionProposalModel] = []
        for proposal in candidates:
            if proposal.media_asset_id != media_asset_id:
                continue
            if proposal.status == DetectionProposalStatus.rejected.value:
                continue
            if proposal.label not in {"animal", "unknown_animal"}:
                continue
            if (
                not math.isfinite(proposal.confidence)
                or proposal.confidence < MEGADETECTOR_DEFAULT_CONFIDENCE_THRESHOLD
            ):
                continue
            if _valid_detection_proposal_bbox(proposal) is None:
                continue
            run = session.get(DetectionRunModel, proposal.run_id)
            adapter = _model_adapter_for_detection_run(run)
            if adapter is None or adapter.id != MEGADETECTOR_ADAPTER_ID:
                continue
            credible.append(proposal)
        activity_focus = (
            item.focus_crop_box_normalized
            if item.focus_crop_available
            and item.focus_crop_source == FocusCropSource.activity
            else None
        )
        if activity_focus is not None:
            related = [
                proposal
                for proposal in credible
                if (
                    (bbox := _valid_detection_proposal_bbox(proposal)) is not None
                    and _normalized_box_overlap_ratio(bbox, activity_focus) > 0
                )
            ]
            if not related:
                # A detector box elsewhere in the frame is not evidence about the
                # activity that created this review item.
                return None
            credible = related
        return max(
            credible,
            key=lambda proposal: (
                (
                    _normalized_box_overlap_ratio(
                        _valid_detection_proposal_bbox(proposal),
                        activity_focus,
                    )
                    if activity_focus is not None
                    else 0.0
                ),
                proposal.confidence,
                _review_queue_timestamp(proposal.created_at),
                proposal.id,
            ),
            default=None,
        )

    def _supersede_pending_bioclip_suggestions(
        self,
        session: Session,
        *,
        run_context: _ReviewSpeciesRunContext,
    ) -> None:
        filters = [
            SpeciesSuggestionModel.adapter_id == BIOCLIP_ADAPTER_ID,
            SpeciesSuggestionModel.status == SpeciesSuggestionStatus.pending.value,
        ]
        if run_context.visit_id is not None:
            filters.append(SpeciesSuggestionModel.visit_id == run_context.visit_id)
        elif run_context.event_id is not None:
            filters.append(SpeciesSuggestionModel.event_id == run_context.event_id)
        else:
            return
        prior_suggestions = session.scalars(
            select(SpeciesSuggestionModel).where(*filters)
        ).all()
        for prior in prior_suggestions:
            prior.status = SpeciesSuggestionStatus.superseded.value

    def _review_queue_item_by_target(
        self,
        session: Session,
        target_type: str,
        target_id: str,
    ) -> ReviewQueueItem | None:
        return next(
            (
                item
                for item in self._review_queue_items(session)
                if item.target_type == target_type and item.target_id == target_id
            ),
            None,
        )

    def _review_identification_response(
        self,
        *,
        target_type: str,
        target_id: str,
        identification: ReviewIdentificationSummary,
        detection_run: DetectionRun | None = None,
        proposals: list[DetectionProposal] | None = None,
        review_queue_item: ReviewQueueItem | None = None,
        warnings: list[str] | None = None,
    ) -> ReviewIdentificationResponse:
        return ReviewIdentificationResponse(
            target_type=target_type,
            target_id=target_id,
            identification=identification,
            detection_run=detection_run,
            proposals=proposals or [],
            species_suggestion=identification.suggestion,
            review_queue_item=review_queue_item,
            created_suggestion_ids=identification.created_suggestion_ids,
            created_proposal_ids=identification.created_proposal_ids,
            creates_truth=False,
            creates_export=False,
            creates_review_label=False,
            warnings=warnings or [],
        )

    def _review_identification_summary_for_item(
        self,
        session: Session,
        item: ReviewQueueItem,
        *,
        requested_adapter_id: str | None = None,
        media_asset_id: str | None = None,
        adapter_status: "_ReviewAdapterStatusContext | None" = None,
    ) -> ReviewIdentificationSummary:
        # `adapter_status`, when supplied by a caller building several
        # review items in one bounded operation (see
        # `_ReviewAdapterStatusContext`), is reused for every model-
        # adapter/BioCLIP status lookup below instead of re-running local
        # filesystem/model-bundle validation once per lookup, once per
        # item. Omitting it (every other, single-item caller) resolves a
        # fresh context right here, preserving the original always-fresh
        # per-call behavior exactly.
        resolved_adapter_status = adapter_status or _ReviewAdapterStatusContext.resolve()
        model_adapters = resolved_adapter_status.model_adapters
        normalized_media_asset_id = (
            media_asset_id
            or item.best_media_asset_id
            or (item.media_asset.id if item.media_asset else None)
        )
        media_asset_model = (
            session.get(MediaAssetModel, normalized_media_asset_id)
            if normalized_media_asset_id is not None
            else None
        )
        if media_asset_model is None:
            normalized_media_asset_id = None

        pack_model, candidate_pack_warning, _selected_pack_id = (
            self._effective_species_candidate_pack_for_stream(session, item.stream_id)
        )
        candidate_pack = self._species_candidate_pack_from_model(session, pack_model)

        suggestion_models = self._review_identification_suggestion_models(
            session,
            item,
            media_asset_id=normalized_media_asset_id,
        )
        proposal_models = self._review_identification_proposal_models(
            session,
            item,
            media_asset_id=normalized_media_asset_id,
        )
        suggestion = (
            _species_suggestion_from_model(suggestion_models[0])
            if suggestion_models
            else None
        )
        proposal_model = proposal_models[0] if proposal_models else None
        proposal = (
            _detection_proposal_from_model(proposal_model)
            if proposal_model is not None
            else None
        )
        proposal_adapter = (
            _model_adapter_for_detection_run(
                session.get(DetectionRunModel, proposal_model.run_id),
                model_adapters=model_adapters,
            )
            if proposal_model is not None
            else None
        )
        suggestion_adapter = (
            _model_adapter_by_id(suggestion.adapter_id, model_adapters=model_adapters)
            if suggestion is not None
            else None
        )
        selected_adapter = self._select_review_identification_adapter(
            requested_adapter_id=requested_adapter_id,
            media_asset_model=media_asset_model,
            model_adapters=model_adapters,
        )
        if requested_adapter_id is not None:
            adapter = selected_adapter
        elif suggestion_adapter is not None:
            adapter = suggestion_adapter
        elif (
            selected_adapter is not None
            and (
                selected_adapter.kind == ModelAdapterKind.species_classifier
                or self._review_identification_adapter_can_run(
                    selected_adapter,
                    media_asset_model,
                )
            )
        ):
            # Species setup and runnable adapters own the identification action.
            # Existing MegaDetector evidence remains available as classifier crop context.
            adapter = selected_adapter
        else:
            adapter = proposal_adapter or selected_adapter
        adapter_supports_media = (
            self._review_identification_adapter_supports_media(adapter, media_asset_model)
            if adapter is not None
            else False
        )
        can_run = (
            self._review_identification_adapter_can_run(adapter, media_asset_model)
            if adapter is not None
            else False
        )
        setup_summary = (
            _model_adapter_setup_summary(adapter)
            if adapter is not None
            else None
        )
        setup_hint = (
            setup_summary.setup_hint
            if setup_summary is not None
            else adapter.notes
            if adapter is not None
            else None
        )
        supported_media_types = list(adapter.supported_media_types) if adapter is not None else []
        unavailable_reason: str | None = None
        candidate_pack_setup_status: BioClipAdapterStatus | None = None
        if adapter is not None and adapter.id == BIOCLIP_ADAPTER_ID:
            candidate_pack_setup_status = resolved_adapter_status.bioclip_status_for_candidate_pack(
                _species_candidate_pack_prompt_labels(candidate_pack)
            )
            if candidate_pack_setup_status.status != "available":
                can_run = False
        unavailable_reason: str | None = None
        analysis_input_blocked = False
        if can_run and adapter is not None and normalized_media_asset_id is not None:
            crop: _ReviewSpeciesCropContext | None = None
            if adapter.kind == ModelAdapterKind.species_classifier:
                crop = self._review_species_crop_context(
                    session,
                    item,
                    media_asset_id=normalized_media_asset_id,
                )
            elif adapter.kind == ModelAdapterKind.object_detector:
                crop = _review_detector_input_crop_context(item, adapter.id)
            if crop is not None and (
                _review_item_has_active_restricted_zone(session, item)
                or _review_species_crop_intersects_restricted_zone(
                    session,
                    stream_id=item.stream_id,
                    crop=crop,
                )
            ):
                can_run = False
                analysis_input_blocked = True
                unavailable_reason = "identification_zone_suppressed"

        if suggestion is not None:
            status = ReviewIdentificationStatus.suggestion_present
            message = (
                "Pending identification suggestion is available. Accepting it still "
                "requires an explicit review correction."
            )
        elif proposal is not None:
            status = ReviewIdentificationStatus.proposal_present
            message = (
                "Detection proposal evidence is available for this candidate. "
                "Review correction still creates truth."
            )
        elif normalized_media_asset_id is None:
            status = ReviewIdentificationStatus.no_best_frame
            unavailable_reason = "missing_best_frame"
            message = "Add or save a best frame before running identification assist."
        elif adapter is None:
            status = ReviewIdentificationStatus.unavailable_no_adapter
            unavailable_reason = "no_adapter_registered"
            message = "No identification adapter is registered for Review Queue assist."
        elif analysis_input_blocked:
            status = ReviewIdentificationStatus.unsupported_media
            message = (
                "Identification is blocked because its selected image region intersects "
                "an active Privacy or Ignore Zone. No full-frame fallback is allowed."
            )
        elif not adapter_supports_media:
            status = ReviewIdentificationStatus.unsupported_media
            unavailable_reason = (
                f"unsupported_media_type:{media_asset_model.content_type}"
                if media_asset_model is not None
                else "unsupported_media_type"
            )
            message = (
                f"{adapter.name} does not support this candidate media type. "
                "No evidence or truth was created."
            )
        elif (
            candidate_pack_setup_status is not None
            and candidate_pack_setup_status.status != "available"
        ):
            status = (
                ReviewIdentificationStatus.setup_required
                if candidate_pack_setup_status.status == "not_configured"
                else ReviewIdentificationStatus.unavailable
            )
            unavailable_reason = candidate_pack_setup_status.detail
            message = (
                f"{adapter.name} needs configured local candidate embeddings for "
                f"{candidate_pack.display_name} v{candidate_pack.version}."
            )
        elif can_run:
            status = ReviewIdentificationStatus.configured_available
            message = (
                "Placeholder analyzer can create demo proposal evidence without media inspection."
                if adapter.kind == ModelAdapterKind.demo
                else f"{adapter.name} is ready to run on this best frame."
            )
        elif adapter.status == ModelAdapterStatus.not_configured:
            status = ReviewIdentificationStatus.setup_required
            unavailable_reason = (
                adapter.configuration_status.status_reason
                if adapter.configuration_status is not None
                else "adapter_not_configured"
            )
            message = (
                f"{adapter.name} needs local setup before identification assist can run."
            )
        else:
            status = ReviewIdentificationStatus.unavailable
            unavailable_reason = (
                adapter.configuration_status.status_reason
                if adapter.configuration_status is not None
                else "adapter_unavailable"
            )
            message = f"{adapter.name} is unavailable for identification assist."

        return ReviewIdentificationSummary(
            status=status,
            message=message,
            media_asset_id=normalized_media_asset_id,
            adapter_id=adapter.id if adapter is not None else None,
            adapter_name=adapter.name if adapter is not None else None,
            adapter_kind=adapter.kind if adapter is not None else None,
            adapter_status=adapter.status if adapter is not None else None,
            adapter_is_demo=adapter.kind == ModelAdapterKind.demo if adapter is not None else False,
            setup_status=setup_summary.status if setup_summary is not None else None,
            local_only=adapter.local_only if adapter is not None else True,
            supported_media_types=supported_media_types,
            can_run=can_run,
            can_run_on_best_frame=can_run,
            required_env_var=setup_summary.required_env_var if setup_summary is not None else None,
            model_path_hint=setup_summary.model_path_hint if setup_summary is not None else None,
            setup_hint=setup_hint,
            unavailable_reason=unavailable_reason,
            suggestion=suggestion,
            proposal=proposal,
            suggestion_count=len(suggestion_models),
            proposal_count=len(proposal_models),
            created_suggestion_ids=[],
            created_proposal_ids=[],
            **(
                _review_species_suggestion_focus_fields(suggestion, item)
                if suggestion is not None
                else _review_identification_focus_fields(item)
            ),
            creates_truth=False,
            creates_export=False,
            candidate_pack=self._species_candidate_pack_summary_from_model(candidate_pack),
            candidate_pack_warning=candidate_pack_warning,
        )

    def _review_identification_suggestion_models(
        self,
        session: Session,
        item: ReviewQueueItem,
        *,
        media_asset_id: str | None,
    ) -> list[SpeciesSuggestionModel]:
        filters = []
        if item.visit_id:
            filters.append(SpeciesSuggestionModel.visit_id == item.visit_id)
        elif item.event_id:
            filters.append(SpeciesSuggestionModel.event_id == item.event_id)
        elif media_asset_id:
            filters.append(SpeciesSuggestionModel.media_asset_id == media_asset_id)
        if not filters:
            return []
        return list(
            session.scalars(
                select(SpeciesSuggestionModel)
                .where(
                    SpeciesSuggestionModel.status == SpeciesSuggestionStatus.pending.value,
                    or_(*filters),
                )
                .order_by(
                    SpeciesSuggestionModel.created_at.desc(),
                    SpeciesSuggestionModel.rank,
                    SpeciesSuggestionModel.id.desc(),
                )
            ).all()
        )

    def _review_identification_proposal_models(
        self,
        session: Session,
        item: ReviewQueueItem,
        *,
        media_asset_id: str | None,
    ) -> list[DetectionProposalModel]:
        filters = []
        if item.visit_id:
            filters.append(DetectionProposalModel.visit_id == item.visit_id)
        if item.event_id:
            filters.append(DetectionProposalModel.event_id == item.event_id)
        if media_asset_id:
            filters.append(
                and_(
                    DetectionProposalModel.media_asset_id == media_asset_id,
                    DetectionProposalModel.event_id.is_(None),
                    DetectionProposalModel.visit_id.is_(None),
                )
            )
        if not filters:
            return []
        return list(
            session.scalars(
                select(DetectionProposalModel)
                .where(or_(*filters))
                .order_by(
                    DetectionProposalModel.created_at.desc(),
                    DetectionProposalModel.id.desc(),
                )
            ).all()
        )

    def _select_review_identification_adapter(
        self,
        *,
        requested_adapter_id: str | None,
        media_asset_model: MediaAssetModel | None,
        model_adapters: tuple[ModelAdapter, ...] | None = None,
    ) -> ModelAdapter | None:
        # See `_model_adapter_by_id`: an explicit `model_adapters` snapshot
        # (from a caller-shared `_ReviewAdapterStatusContext`) is reused
        # rather than re-running the whole adapter registry's own status
        # validation again; omitting it preserves always-fresh resolution.
        if requested_adapter_id is not None:
            adapter = _model_adapter_by_id(requested_adapter_id, model_adapters=model_adapters)
            if adapter is None:
                raise ValueError("missing_adapter")
            return adapter

        real_adapters = [
            adapter
            for adapter in (model_adapters if model_adapters is not None else _model_adapters())
            if adapter.kind
            in {ModelAdapterKind.object_detector, ModelAdapterKind.species_classifier}
        ]
        supported_adapters = [
            adapter
            for adapter in real_adapters
            if self._review_identification_adapter_supports_media(adapter, media_asset_model)
        ]
        candidates = supported_adapters or real_adapters
        runnable = [
            adapter
            for adapter in candidates
            if self._review_identification_adapter_can_run(adapter, media_asset_model)
        ]
        return next(
            (
                adapter
                for adapter in runnable
                if adapter.kind == ModelAdapterKind.species_classifier
            ),
            runnable[0]
            if runnable
            else next(
                (
                    adapter
                    for adapter in candidates
                    if adapter.kind == ModelAdapterKind.species_classifier
                ),
                candidates[0] if candidates else None,
            ),
        )

    def _review_identification_adapter_supports_media(
        self,
        adapter: ModelAdapter | None,
        media_asset_model: MediaAssetModel | None,
    ) -> bool:
        if adapter is None or media_asset_model is None:
            return adapter is not None
        return (
            media_asset_model.media_type in adapter.supported_media_types
            or media_asset_model.content_type in adapter.supported_media_types
        )

    def _review_identification_adapter_can_run(
        self,
        adapter: ModelAdapter | None,
        media_asset_model: MediaAssetModel | None,
    ) -> bool:
        if adapter is None or media_asset_model is None:
            return False
        if not self._review_identification_adapter_supports_media(adapter, media_asset_model):
            return False
        if adapter.kind == ModelAdapterKind.demo:
            return adapter.status == ModelAdapterStatus.available
        if adapter.configuration_status is not None:
            return adapter.configuration_status.can_run
        return adapter.status == ModelAdapterStatus.available

    def _review_identification_error_summary(
        self,
        summary: ReviewIdentificationSummary,
        error: ValueError,
    ) -> ReviewIdentificationSummary:
        reason = str(error)
        setup_errors = {
            "bioclip_configuration_error",
            "bioclip_not_configured",
            "local_detector_not_configured",
            "megadetector_not_configured",
            "megadetector_model_file_missing",
            "megadetector_model_format_unsupported",
        }
        unsupported_errors = {
            "bioclip_crop_preparation_failed",
            "bioclip_input_too_large",
            "bioclip_media_changed",
            "bioclip_media_not_review_frame",
            "bioclip_unsupported_image",
            "bioclip_unsupported_media_type",
            "identification_zone_suppressed",
            "local_detector_unsupported_media_type",
            "megadetector_unsupported_media_type",
            "megadetector_zone_suppressed",
            "species_classifier_not_supported",
            "unsupported_media_type",
        }
        failed_errors = {
            "bioclip_failed",
            "bioclip_input_unavailable",
            "bioclip_persistence_failed",
            "bioclip_runtime_unavailable",
            "bioclip_timed_out",
            "bioclip_unexpected_failure",
            "bioclip_worker_failed",
            "local_detector_failed",
            "local_detector_runtime_unavailable",
            "megadetector_runtime_unavailable",
            "megadetector_failed",
            "missing_media_file",
            "unsupported_detector_output",
        }
        if reason == "bioclip_busy":
            status = ReviewIdentificationStatus.running
            message = (
                "Another species identification is already running. "
                "The cancelled attempt was recorded, and no second model process "
                "or suggestion was created."
            )
        elif reason == "bioclip_no_result":
            status = ReviewIdentificationStatus.no_proposal
            message = (
                "BioCLIP completed without a usable ranked suggestion. "
                "The attempt was recorded and no truth was created."
            )
        elif reason == "bioclip_timed_out":
            status = ReviewIdentificationStatus.failed
            message = (
                "BioCLIP exceeded its local run timeout. The timed-out attempt "
                "was recorded and no truth was created."
            )
        elif reason in setup_errors:
            status = ReviewIdentificationStatus.setup_required
            message = "Identification setup is required before this candidate can be analyzed."
        elif reason == "identification_zone_suppressed":
            status = ReviewIdentificationStatus.unsupported_media
            message = (
                "Identification is blocked by an active Privacy or Ignore Zone. "
                "No analyzer or full-frame fallback ran."
            )
        elif reason == "bioclip_identification_evidence_ineligible":
            status = ReviewIdentificationStatus.identification_uncertain
            message = (
                "Evidence is insufficient for species assistance. No model call was "
                "made, and no truth was created. This Visit remains a valid, unreviewed "
                "candidate -- species identification is separate from Visit correctness."
            )
        elif reason == "bioclip_identification_ambiguous":
            status = ReviewIdentificationStatus.identification_uncertain
            message = (
                "Bird or wildlife activity is present, but the species is uncertain: "
                "BioCLIP's ranked candidates were too close or too weak to name a "
                "species. The attempt was recorded and no truth was created."
            )
        elif reason in unsupported_errors:
            status = ReviewIdentificationStatus.unsupported_media
            message = "Identification adapter does not support this best-frame media type."
        elif reason in failed_errors:
            status = ReviewIdentificationStatus.failed
            message = "Identification adapter failed cleanly. No truth or export data was created."
        else:
            status = ReviewIdentificationStatus.failed
            message = "Identification adapter could not analyze this candidate. No truth was created."
        return summary.model_copy(
            update={
                "status": status,
                "can_run": False,
                "can_run_on_best_frame": False,
                "message": message,
                "unavailable_reason": reason,
                "created_suggestion_ids": [],
                "created_proposal_ids": [],
            }
        )

    def _review_queue_stream_context(
        self,
        session: Session,
        stream_id: str,
    ) -> tuple[str | None, str | None, str | None]:
        stream_model = session.get(StreamModel, stream_id)
        if stream_model is None:
            return None, None, None
        source_model = session.get(CameraSourceModel, stream_model.source_id)
        return (
            stream_model.name,
            stream_model.source_id,
            source_model.name if source_model is not None else None,
        )

    def _motion_evidence_for_review_queue_item(
        self,
        session: Session,
        *,
        event_id: str | None,
        visit_id: str | None,
        media_asset_id: str | None,
    ) -> MotionEvidenceModel | None:
        target_filters = []
        if visit_id:
            target_filters.append(MotionEvidenceModel.promoted_visit_id == visit_id)
        if event_id:
            target_filters.append(MotionEvidenceModel.promoted_event_id == event_id)
        if media_asset_id:
            media_filter = MotionEvidenceModel.snapshot_media_asset_id == media_asset_id
            filters = (
                [media_filter, or_(*target_filters)]
                if target_filters
                else [media_filter]
            )
        else:
            filters = [or_(*target_filters)] if target_filters else []
        if not filters:
            return None
        return session.scalars(
            select(MotionEvidenceModel)
            .where(*filters)
            .order_by(MotionEvidenceModel.created_at.desc(), MotionEvidenceModel.id.desc())
        ).first()

    def _review_queue_activity_context(
        self,
        evidence: MotionEvidenceModel | None,
    ) -> dict[str, Any]:
        if evidence is None:
            return {
                "activity_session_id": None,
                "activity_started_at": None,
                "activity_last_seen_at": None,
                "detection_count": 0,
                "near_miss_count": 0,
                "frames_evaluated_count": 0,
                "candidate_frame_count": 0,
                "saved_candidate_count": 0,
                "best_frame_sequence": None,
                "best_changed_ratio": None,
                "best_changed_pixels": None,
                "best_total_scored_pixels": None,
                "effective_threshold_used": None,
                "threshold_source": None,
                "fine_motion_applied": False,
                "image_quality_warnings": [],
            }
        config = dict(json.loads(evidence.scoring_config_json))
        return {
            "activity_session_id": _optional_string(config.get("activity_session_id")),
            "activity_started_at": _optional_datetime(
                config.get("activity_started_at")
            ),
            "activity_last_seen_at": _optional_datetime(
                config.get("activity_last_seen_at") or evidence.best_frame_time
            ),
            "detection_count": (
                _optional_int(config.get("detection_count"))
                or evidence.triggered_frame_count
            ),
            "near_miss_count": _optional_int(config.get("near_miss_count")) or 0,
            "frames_evaluated_count": (
                _optional_int(config.get("frames_evaluated_count")) or 0
            ),
            "candidate_frame_count": (
                _optional_int(config.get("candidate_frame_count")) or 0
            ),
            "saved_candidate_count": (
                _optional_int(config.get("saved_candidate_count")) or 0
            ),
            "best_frame_sequence": evidence.best_frame_index,
            "best_changed_ratio": (
                _optional_float(config.get("best_changed_ratio"))
                or evidence.peak_changed_ratio
            ),
            "best_changed_pixels": _optional_int(config.get("best_changed_pixels")),
            "best_total_scored_pixels": _optional_int(
                config.get("best_total_scored_pixels")
            ),
            "effective_threshold_used": (
                _optional_float(config.get("effective_threshold_used"))
                or _optional_float(config.get("threshold_used"))
            ),
            "threshold_source": _optional_string(config.get("threshold_source")),
            "fine_motion_applied": bool(config.get("fine_motion_applied")),
            "image_quality_warnings": _string_list(
                config.get("image_quality_warnings")
            ),
        }

    def _review_focus_crop_context(
        self,
        session: Session,
        *,
        zone_id: str | None,
        media_asset_id: str | None,
        evidence: MotionEvidenceModel | None,
    ) -> _ReviewFocusCropContext:
        if media_asset_id is None:
            return _empty_review_focus_crop_context(["focus_crop_best_frame_unavailable"])

        context_zone_id = zone_id or (evidence.zone_id if evidence is not None else None)
        zone_model = session.get(ZoneModel, context_zone_id) if context_zone_id else None
        if zone_model is not None and zone_model.zone_type in {
            ZoneType.privacy.value,
            ZoneType.ignore.value,
        }:
            return _empty_review_focus_crop_context(
                [f"focus_crop_suppressed_for_{zone_model.zone_type}_zone"]
            )

        activity_bounds = _motion_evidence_activity_bounds(evidence)
        if activity_bounds is None:
            return _empty_review_focus_crop_context(
                ["focus_crop_activity_bounds_unavailable"]
            )

        warnings: list[str] = []
        activity_width = activity_bounds.right - activity_bounds.left
        activity_height = activity_bounds.bottom - activity_bounds.top
        if activity_width < 0.15 or activity_height < 0.15:
            warnings.append("focus_crop_small_activity_expanded")

        image_width, image_height = _motion_evidence_frame_dimensions(evidence)
        if image_width is not None and image_height is not None:
            crop_plan = plan_activity_crop(
                source_media_asset_id=media_asset_id,
                image_width=image_width,
                image_height=image_height,
                left=activity_bounds.left,
                top=activity_bounds.top,
                right=activity_bounds.right,
                bottom=activity_bounds.bottom,
                crop_reason="activity_motion",
            )
            crop_box = crop_plan.crop_box_normalized
            pixel_box = _pixel_bounding_box_from_crop_plan(crop_plan)
            if crop_plan.warning:
                warnings.append(crop_plan.warning)
            is_full_frame_fallback = crop_plan.is_full_frame_fallback
        else:
            bounds_plan = plan_activity_crop_bounds(
                left=activity_bounds.left,
                top=activity_bounds.top,
                right=activity_bounds.right,
                bottom=activity_bounds.bottom,
            )
            crop_box = bounds_plan.crop_box_normalized
            pixel_box = None
            warnings.append("focus_crop_pixels_unavailable")
            if bounds_plan.warning:
                warnings.append(bounds_plan.warning)
            is_full_frame_fallback = bounds_plan.is_full_frame_fallback

        if is_full_frame_fallback:
            return _empty_review_focus_crop_context(warnings or ["focus_crop_unavailable"])

        crop_width = crop_box.right - crop_box.left
        crop_height = crop_box.bottom - crop_box.top
        if crop_width >= 0.9 or crop_height >= 0.9 or crop_width * crop_height >= 0.75:
            warnings.append("focus_crop_large_context")

        return _ReviewFocusCropContext(
            available=True,
            source=FocusCropSource.activity,
            box_normalized=_bounding_box_from_crop_box(crop_box),
            box_pixels=pixel_box,
            label="Detected activity focus",
            warnings=_unique_strings(warnings),
        )

    def list_dataset_exports(self) -> list[DatasetExport]:
        with self.session_factory() as session:
            exports = session.scalars(
                select(DatasetExportModel).order_by(
                    DatasetExportModel.created_at,
                    DatasetExportModel.id,
                )
            ).all()
            return [_dataset_export_from_model(dataset_export) for dataset_export in exports]

    def get_dataset_export(self, export_id: str) -> DatasetExport | None:
        with self.session_factory() as session:
            dataset_export = session.get(DatasetExportModel, export_id)
            return _dataset_export_from_model(dataset_export) if dataset_export else None

    def create_dataset_export(self, payload: DatasetExportCreate) -> DatasetExport:
        with self.session_factory() as session:
            with session.begin():
                dataset_export = DatasetExport(
                    id=self._next_id(session, DatasetExportModel, "dataset-export"),
                    name=payload.name,
                    status=ExportStatus.ready,
                    reviewed_only=payload.reviewed_only,
                    include_detections=payload.include_detections,
                    include_zone_context=payload.include_zone_context,
                    record_count=0,
                    created_at=datetime.now(UTC),
                    selected_visit_ids=payload.selected_visit_ids,
                )
                records, _ = self._export_records_for_current_reviews(session, dataset_export)
                model = DatasetExportModel(
                    id=dataset_export.id,
                    name=dataset_export.name,
                    status=dataset_export.status.value,
                    reviewed_only=dataset_export.reviewed_only,
                    include_detections=dataset_export.include_detections,
                    include_zone_context=dataset_export.include_zone_context,
                    record_count=len(records),
                    created_at=dataset_export.created_at,
                    selected_visit_ids_json=(
                        json.dumps(dataset_export.selected_visit_ids)
                        if dataset_export.selected_visit_ids is not None
                        else None
                    ),
                )
                session.add(model)
                session.flush()
                return _dataset_export_from_model(model)

    def build_dataset_manifest(self, export_id: str) -> DatasetExportManifest | None:
        with self.session_factory() as session:
            dataset_export = session.get(DatasetExportModel, export_id)
            if dataset_export is None:
                return None

            return self._build_dataset_manifest_for_export(
                session,
                _dataset_export_from_model(dataset_export),
            )

    def analytics_summary(self) -> AnalyticsSummary:
        with self.session_factory() as session:
            return self._analytics_summary(session)

    def build_analytics_summary(self) -> AnalyticsSummary:
        return self.analytics_summary()


    def zone_insights(
        self,
        payload: ZoneInsightsRequest,
        *,
        now: datetime | None = None,
    ) -> ZoneInsightsSummary:
        """Return bounded, auditable Zone metrics without mutating product state."""

        generated_at = _as_utc(now or datetime.now(UTC))
        if payload.start_at is None:
            start_at = generated_at - timedelta(days=7)
            end_at = generated_at
        else:
            start_at = _as_utc(payload.start_at)
            end_at = _as_utc(payload.end_at)
        local_timezone = (now or datetime.now().astimezone()).astimezone().tzinfo
        applied = ZoneInsightsAppliedFilters(
            start_at=start_at,
            end_at=end_at,
            stream_id=payload.stream_id,
            source_id=payload.source_id,
            zone_type=payload.zone_type,
            confirmed_taxonomy_id=payload.confirmed_taxonomy_id,
        )

        with self.session_factory() as session:
            taxonomy_filter = (
                session.get(TaxonomyLabelModel, payload.confirmed_taxonomy_id)
                if payload.confirmed_taxonomy_id is not None
                else None
            )
            zone_query = (
                select(ZoneModel, StreamModel, CameraSourceModel)
                .join(StreamModel, ZoneModel.stream_id == StreamModel.id)
                .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                .where(
                    ZoneModel.is_active.is_(True),
                    CameraSourceModel.status != SourceStatus.archived.value,
                    ZoneModel.zone_type.not_in({ZoneType.privacy.value, ZoneType.ignore.value}),
                )
                .order_by(CameraSourceModel.name.collate("NOCASE"), StreamModel.name.collate("NOCASE"), ZoneModel.name.collate("NOCASE"), ZoneModel.id)
            )
            if payload.stream_id is not None:
                zone_query = zone_query.where(StreamModel.id == payload.stream_id)
            if payload.source_id is not None:
                zone_query = zone_query.where(CameraSourceModel.id == payload.source_id)
            if payload.zone_type is not None:
                zone_query = zone_query.where(ZoneModel.zone_type == payload.zone_type.value)
            zone_rows = session.execute(zone_query.limit(51)).all()
            truncated_zones = len(zone_rows) > 50
            zone_rows = zone_rows[:50]
            zone_ids = {zone.id for zone, _stream, _source in zone_rows}
            records_by_zone: dict[str, list[dict[str, Any]]] = {zone.id: [] for zone, _stream, _source in zone_rows}
            if zone_ids:
                # Preloaded once per call and reused for both this method's
                # own `taxonomy` lookup below and the canonical resolver's
                # internal one (`_stream_visit_summary_from_models` ->
                # `_visit_review_outcome`) -- the same optimization
                # `place_activity_report` uses, applied here because Zone
                # Insights can iterate just as many Visits across just as
                # wide a date range. See `_taxonomy_label_index`'s and
                # `_stream_visit_summary_from_models`'s docstrings.
                taxonomy_index = self._taxonomy_label_index(session)
                effective_zone_id = func.coalesce(VisitModel.zone_id, EventModel.primary_zone_id)
                visit_rows = session.execute(
                    select(VisitModel, EventModel, StreamModel, CameraSourceModel)
                    .join(EventModel, VisitModel.event_id == EventModel.id)
                    .join(StreamModel, EventModel.stream_id == StreamModel.id)
                    .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                    .where(
                        VisitModel.is_superseded.is_(False),
                        CameraSourceModel.status != SourceStatus.archived.value,
                        effective_zone_id.in_(zone_ids),
                        EventModel.started_at >= start_at,
                        EventModel.started_at < end_at,
                    )
                    .order_by(EventModel.started_at, EventModel.id, VisitModel.id)
                ).all()
                for visit, event, stream, source in visit_rows:
                    summary = self._stream_visit_summary_from_models(
                        session, visit, event, taxonomy_index=taxonomy_index
                    )
                    if summary.zone_id not in records_by_zone:
                        continue
                    taxonomy = (
                        self._taxonomy_label_model_for_input(
                            session, summary.reviewed_label, taxonomy_index=taxonomy_index
                        )
                        if summary.reviewed_label
                        else None
                    )
                    records_by_zone[summary.zone_id].append(
                        {
                            "summary": summary,
                            "observed_at": _as_utc(summary.activity_started_at),
                            "taxonomy": taxonomy,
                            "stream_id": stream.id,
                            "source_id": source.id,
                        }
                    )

            exposure_by_stream = {
                stream.id: self._zone_insights_exposure(
                    session,
                    stream_id=stream.id,
                    start_at=start_at,
                    end_at=end_at,
                )
                for _zone, stream, _source in zone_rows
            }
            results: list[ZoneInsightsZone] = []
            aggregate_records: list[dict[str, Any]] = []
            for zone, stream, source in zone_rows:
                records = records_by_zone[zone.id]
                aggregate_records.extend(records)
                confirmed = self._zone_insight_confirmed_records(records, taxonomy_filter)
                metrics = self._zone_insight_metrics(
                    records=records,
                    confirmed_records=confirmed,
                    exposure=exposure_by_stream[stream.id],
                )
                results.append(
                    ZoneInsightsZone(
                        zone_id=zone.id,
                        zone_name=zone.name,
                        zone_type=ZoneType(zone.zone_type),
                        stream_id=stream.id,
                        stream_name=stream.name,
                        source_id=source.id,
                        source_name=source.name,
                        metrics=metrics,
                        species_composition=self._zone_insight_species_composition(
                            confirmed,
                            start_at=start_at,
                            end_at=end_at,
                            stream_id=stream.id,
                            source_id=source.id,
                            zone_id=zone.id,
                        ),
                        confirmed_activity_drilldown=self._zone_insight_drilldown(
                            start_at=start_at,
                            end_at=end_at,
                            stream_id=stream.id,
                            source_id=source.id,
                            zone_id=zone.id,
                            review_filter=ActivityLibraryReviewFilter.confirmed_wildlife,
                            confirmed_label=taxonomy_filter.label if taxonomy_filter is not None else None,
                        ),
                        unresolved_activity_drilldown=self._zone_insight_drilldown(
                            start_at=start_at,
                            end_at=end_at,
                            stream_id=stream.id,
                            source_id=source.id,
                            zone_id=zone.id,
                            review_filter=ActivityLibraryReviewFilter.needs_review,
                        ),
                        reviewed_blank_drilldown=self._zone_insight_drilldown(
                            start_at=start_at,
                            end_at=end_at,
                            stream_id=stream.id,
                            source_id=source.id,
                            zone_id=zone.id,
                            review_filter=ActivityLibraryReviewFilter.blank,
                        ),
                        reviewed_non_bird_drilldown=self._zone_insight_drilldown(
                            start_at=start_at,
                            end_at=end_at,
                            stream_id=stream.id,
                            source_id=source.id,
                            zone_id=zone.id,
                            review_filter=ActivityLibraryReviewFilter.non_bird,
                        ),
                    )
                )

            aggregate_confirmed = self._zone_insight_confirmed_records(
                aggregate_records,
                taxonomy_filter,
            )
            stream_exposures = list(exposure_by_stream.values())
            exposure_history_starts = [
                exposure.history_available_from
                for exposure in stream_exposures
                if exposure.history_available_from is not None
            ]
            aggregate_exposure = _ZoneExposure(
                healthy_seconds=(
                    sum(exposure.healthy_seconds or 0.0 for exposure in stream_exposures)
                    if stream_exposures
                    and all(exposure.healthy_seconds is not None for exposure in stream_exposures)
                    else None
                ),
                history_available_from=(
                    min(exposure_history_starts) if exposure_history_starts else None
                ),
                history_is_partial=(
                    any(exposure.history_is_partial for exposure in stream_exposures)
                    or any(exposure.history_available_from is None for exposure in stream_exposures)
                ),
                interval_count=sum(
                    exposure.interval_count for exposure in stream_exposures
                ),
            )
            aggregate = self._zone_insight_metrics(
                records=aggregate_records,
                confirmed_records=aggregate_confirmed,
                exposure=aggregate_exposure,
            )
            aggregate_drilldown = self._zone_insight_drilldown(
                start_at=start_at,
                end_at=end_at,
                stream_id=payload.stream_id,
                source_id=payload.source_id,
                review_filter=ActivityLibraryReviewFilter.confirmed_wildlife,
                confirmed_label=taxonomy_filter.label if taxonomy_filter is not None else None,
            )
            daily_counts = Counter(
                record["observed_at"].astimezone(local_timezone).date()
                for record in aggregate_confirmed
            )
            hour_counts = Counter(
                record["observed_at"].astimezone(local_timezone).hour
                for record in aggregate_confirmed
            )
            period_days = max(1, (end_at.astimezone(local_timezone).date() - start_at.astimezone(local_timezone).date()).days + 1)
            first_day = start_at.astimezone(local_timezone).date()
            daily_trend = [
                ZoneInsightsDailyBucket(
                    local_date=first_day + timedelta(days=offset),
                    confirmed_bird_visit_count=daily_counts[first_day + timedelta(days=offset)],
                    drilldown=self._zone_insight_drilldown(
                        start_at=_as_utc(datetime.combine(first_day + timedelta(days=offset), datetime.min.time(), local_timezone)),
                        end_at=_as_utc(datetime.combine(first_day + timedelta(days=offset) + timedelta(days=1), datetime.min.time(), local_timezone)),
                        stream_id=payload.stream_id,
                        source_id=payload.source_id,
                        review_filter=ActivityLibraryReviewFilter.confirmed_wildlife,
                        confirmed_label=taxonomy_filter.label if taxonomy_filter is not None else None,
                    ),
                )
                for offset in range(min(period_days, 366))
            ]
            activity_by_hour = [
                ZoneInsightsHourBucket(
                    hour=hour,
                    confirmed_bird_visit_count=hour_counts[hour],
                    drilldown=aggregate_drilldown,
                )
                for hour in range(24)
            ]
            warnings = [
                "Visits are activity sessions, not estimates of unique birds. A bird may create more than one Visit if it leaves and returns. Visit totals do not represent unique individuals.",
            ]
            if aggregate.exposure_history_is_partial and aggregate.exposure_history_available_from is not None:
                warnings.append(
                    "Durable monitoring exposure is available from "
                    f"{aggregate.exposure_history_available_from.strftime('%B %d, %Y').replace(' 0', ' ')}. "
                    "Earlier time in this range is excluded from rate calculations."
                )
            elif aggregate.exposure_history_available_from is None:
                warnings.append(
                    "No durable monitoring exposure has been recorded for every selected Stream yet, so aggregate rates are withheld."
                )
            if taxonomy_filter is None and payload.confirmed_taxonomy_id is not None:
                warnings.append("The selected confirmed taxonomy is unavailable, so no confirmed species matches were counted.")
            if truncated_zones:
                warnings.append("Showing the first 50 matching Zones.")
            if not results:
                warnings.append("No active feeder, birdbath, perch, ground, yard, or driveway Zones match these filters.")
            return ZoneInsightsSummary(
                generated_at=generated_at,
                applied_filters=applied,
                aggregate=aggregate,
                zone_count=len(results),
                zones=sorted(
                    results,
                    key=lambda item: (
                        0
                        if item.metrics.data_quality_status == ZoneInsightsQualityStatus.sufficient
                        and item.metrics.confirmed_bird_visits_per_monitored_hour is not None
                        else 1,
                        -(
                            item.metrics.confirmed_bird_visits_per_monitored_hour
                            if item.metrics.confirmed_bird_visits_per_monitored_hour is not None
                            and item.metrics.data_quality_status == ZoneInsightsQualityStatus.sufficient
                            else item.metrics.confirmed_bird_visit_count
                        ),
                        item.zone_name.lower(),
                        item.zone_id,
                    ),
                ),
                daily_trend=daily_trend,
                activity_by_hour=activity_by_hour,
                busiest_supported_hour=(
                    max(hour_counts, key=lambda hour: (hour_counts[hour], -hour))
                    if len(aggregate_confirmed) >= 5 and hour_counts
                    else None
                ),
                warnings=warnings,
            )

    def _zone_insights_exposure(
        self,
        session: Session,
        *,
        stream_id: str,
        start_at: datetime,
        end_at: datetime,
    ) -> _ZoneExposure:
        """Aggregate only persisted fresh-frame intervals; never infer historical uptime."""

        history_available_from = session.scalar(
            select(func.min(MonitoringExposureIntervalModel.started_at)).where(
                MonitoringExposureIntervalModel.stream_id == stream_id
            )
        )
        if history_available_from is None:
            return _ZoneExposure(
                healthy_seconds=None,
                history_available_from=None,
                history_is_partial=False,
                interval_count=0,
            )
        history_available_from = _as_utc(history_available_from)
        rows = session.scalars(
            select(MonitoringExposureIntervalModel).where(
                MonitoringExposureIntervalModel.stream_id == stream_id,
                MonitoringExposureIntervalModel.started_at < end_at,
                func.coalesce(
                    MonitoringExposureIntervalModel.ended_at,
                    MonitoringExposureIntervalModel.last_confirmed_fresh_at,
                ) > start_at,
            )
        ).all()
        intervals = [
            TimeInterval(
                max(start_at, _as_utc(row.started_at)),
                min(
                    end_at,
                    _as_utc(
                        row.ended_at
                        if row.ended_at is not None
                        else row.last_confirmed_fresh_at
                    ),
                ),
            )
            for row in rows
        ]
        healthy_seconds = interval_seconds(merge_intervals(intervals))
        return _ZoneExposure(
            healthy_seconds=healthy_seconds,
            history_available_from=history_available_from,
            history_is_partial=start_at < history_available_from,
            interval_count=len(rows),
        )

    @staticmethod
    def _zone_insight_confirmed_records(
        records: list[dict[str, Any]],
        taxonomy_filter: TaxonomyLabelModel | None,
    ) -> list[dict[str, Any]]:
        return [
            record
            for record in records
            if record["summary"].review_outcome == VisitReviewOutcome.confirmed_bird
            and (
                taxonomy_filter is None
                or (
                    record["taxonomy"] is not None
                    and record["taxonomy"].id == taxonomy_filter.id
                )
            )
        ]

    def _zone_insight_metrics(
        self,
        *,
        records: list[dict[str, Any]],
        confirmed_records: list[dict[str, Any]],
        exposure: _ZoneExposure,
    ) -> ZoneInsightsMetrics:
        reviewed_records = [
            record
            for record in records
            if record["summary"].review_status == ReviewStatus.reviewed
        ]
        blank_count = sum(
            record["summary"].review_outcome == VisitReviewOutcome.blank
            for record in reviewed_records
        )
        non_bird_count = sum(
            record["summary"].review_outcome == VisitReviewOutcome.non_bird
            for record in reviewed_records
        )
        false_positive_count = sum(
            record["summary"].review_outcome == VisitReviewOutcome.false_positive
            for record in reviewed_records
        )
        healthy_seconds = exposure.healthy_seconds
        healthy_hours = healthy_seconds / 3600 if healthy_seconds is not None else None
        quality, warnings = quality_status(
            healthy_monitored_seconds=healthy_seconds,
            reviewed_visit_count=len(reviewed_records),
            active_visit_count=len(records),
            confirmed_bird_visit_count=len(confirmed_records),
        )
        if exposure.history_is_partial and exposure.history_available_from is not None:
            warnings.append(
                "Durable monitoring exposure is available from "
                f"{exposure.history_available_from.strftime('%B %d, %Y').replace(' 0', ' ')}. "
                "Earlier time in this range is excluded from rate calculations."
            )
        elif exposure.history_available_from is None:
            warnings.append(
                "No durable monitoring exposure has been recorded for this Stream yet."
            )
        warnings.append(
            "Evidence success percentage is unavailable because durable capture-attempt history is not retained."
        )
        ordered_confirmed = sorted(
            confirmed_records,
            key=lambda record: (record["observed_at"], record["summary"].id),
        )
        species_ids = {
            record["taxonomy"].id
            for record in confirmed_records
            if record["taxonomy"] is not None and record["taxonomy"].is_species
        }
        return ZoneInsightsMetrics(
            healthy_monitored_hours=round(healthy_hours, 4) if healthy_hours is not None else None,
            exposure_history_available_from=exposure.history_available_from,
            exposure_history_is_partial=exposure.history_is_partial,
            exposure_interval_count=exposure.interval_count,
            confirmed_bird_visit_count=len(confirmed_records),
            confirmed_bird_visits_per_monitored_hour=(
                round(len(confirmed_records) / healthy_hours, 4)
                if healthy_hours is not None and healthy_hours >= 2
                else None
            ),
            total_confirmed_bird_dwell_seconds=round(
                sum(record["summary"].duration_seconds for record in confirmed_records),
                4,
            ),
            median_confirmed_bird_duration_seconds=median_duration_seconds(
                record["summary"].duration_seconds for record in confirmed_records
            ),
            confirmed_species_richness=len(species_ids),
            unresolved_visit_count=sum(
                record["summary"].review_outcome == VisitReviewOutcome.needs_review
                for record in records
            ),
            reviewed_visit_count=len(reviewed_records),
            reviewed_blank_count=blank_count,
            reviewed_non_bird_count=non_bird_count,
            reviewed_false_positive_count=false_positive_count,
            review_coverage_percentage=(
                round(len(reviewed_records) / len(records) * 100, 2)
                if records
                else None
            ),
            reviewed_false_positive_percentage=(
                round(false_positive_count / len(reviewed_records) * 100, 2)
                if reviewed_records
                else None
            ),
            evidence_success_percentage=None,
            first_confirmed_activity_at=(
                ordered_confirmed[0]["observed_at"] if ordered_confirmed else None
            ),
            last_confirmed_activity_at=(
                ordered_confirmed[-1]["observed_at"] if ordered_confirmed else None
            ),
            data_quality_status=ZoneInsightsQualityStatus(quality),
            warnings=warnings,
        )

    @staticmethod
    def _zone_insight_drilldown(
        *,
        start_at: datetime,
        end_at: datetime,
        review_filter: ActivityLibraryReviewFilter,
        stream_id: str | None = None,
        source_id: str | None = None,
        zone_id: str | None = None,
        confirmed_label: str | None = None,
    ) -> ZoneInsightsDrilldown:
        return ZoneInsightsDrilldown(
            filters=ActivityLibraryFilters(
                review_filter=review_filter,
                stream_id=stream_id,
                source_id=source_id,
                zone_id=zone_id,
                confirmed_label=confirmed_label,
                start_at=start_at,
                # Zone Insights queries [start_at, end_at); the Activity
                # Library treats its end as inclusive, so preserve the same
                # auditable set for click-throughs.
                end_at=end_at - timedelta(microseconds=1),
            )
        )

    def _zone_insight_species_composition(
        self,
        confirmed_records: list[dict[str, Any]],
        *,
        start_at: datetime,
        end_at: datetime,
        stream_id: str,
        source_id: str,
        zone_id: str,
    ) -> list[ZoneInsightsSpeciesComposition]:
        grouped: dict[str, list[dict[str, Any]]] = {}
        for record in confirmed_records:
            taxonomy = record["taxonomy"]
            if taxonomy is None or not taxonomy.is_species:
                continue
            grouped.setdefault(taxonomy.id, []).append(record)
        total = sum(len(records) for records in grouped.values())
        return [
            ZoneInsightsSpeciesComposition(
                taxonomy_id=taxonomy_id,
                label=records[0]["taxonomy"].label,
                display_name=records[0]["taxonomy"].display_name,
                visit_count=len(records),
                percentage=round(len(records) / total * 100, 2),
                drilldown=self._zone_insight_drilldown(
                    start_at=start_at,
                    end_at=end_at,
                    stream_id=stream_id,
                    source_id=source_id,
                    zone_id=zone_id,
                    review_filter=ActivityLibraryReviewFilter.confirmed_wildlife,
                    confirmed_label=records[0]["taxonomy"].label,
                ),
            )
            for taxonomy_id, records in sorted(
                grouped.items(),
                key=lambda item: (-len(item[1]), item[1][0]["taxonomy"].display_name.lower(), item[0]),
            )
        ]

    def wildlife_insights(
        self,
        payload: WildlifeInsightsRequest,
        *,
        now: datetime | None = None,
    ) -> WildlifeInsightsSummary:
        """Aggregate bounded, current reviewed wildlife truth for the Analytics surface."""

        local_now = (now or datetime.now().astimezone()).astimezone()
        local_timezone = local_now.tzinfo
        if payload.preset == WildlifeInsightsRangePreset.today:
            end_date = local_now.date()
            start_date = end_date
        elif payload.preset == WildlifeInsightsRangePreset.last_7_days:
            end_date = local_now.date()
            start_date = end_date - timedelta(days=6)
        elif payload.preset == WildlifeInsightsRangePreset.last_30_days:
            end_date = local_now.date()
            start_date = end_date - timedelta(days=29)
        else:
            start_date = payload.start_date
            end_date = payload.end_date
            assert start_date is not None and end_date is not None

        period_days = (end_date - start_date).days + 1
        previous_end_date = start_date - timedelta(days=1)
        previous_start_date = previous_end_date - timedelta(days=period_days - 1)
        current_start_at = _as_utc(datetime.combine(start_date, datetime.min.time(), local_timezone))
        current_end_at = _as_utc(
            datetime.combine(end_date + timedelta(days=1), datetime.min.time(), local_timezone)
        )
        previous_start_at = _as_utc(
            datetime.combine(previous_start_date, datetime.min.time(), local_timezone)
        )
        previous_end_at = _as_utc(
            datetime.combine(previous_end_date + timedelta(days=1), datetime.min.time(), local_timezone)
        )
        timezone_name = local_now.tzname() or "local time"

        with self.session_factory() as session:
            current_records = self._wildlife_insight_records(
                session,
                start_at=current_start_at,
                end_at=current_end_at,
            )
            previous_records = self._wildlife_insight_records(
                session,
                start_at=previous_start_at,
                end_at=previous_end_at,
            )
            active_stream_count = (
                session.scalar(
                    select(func.count(StreamModel.id))
                    .join(
                        CameraSourceModel,
                        StreamModel.source_id == CameraSourceModel.id,
                    )
                    .where(CameraSourceModel.status != SourceStatus.archived.value)
                )
                or 0
            )

            current_wildlife = [
                record
                for record in current_records
                if record["summary"].review_outcome == VisitReviewOutcome.confirmed_bird
            ]
            previous_wildlife = [
                record
                for record in previous_records
                if record["summary"].review_outcome == VisitReviewOutcome.confirmed_bird
            ]
            leading_labels = self._wildlife_insight_breakdowns(
                current_wildlife,
                previous_wildlife,
                grouping="label",
                start_date=start_date,
                end_date=end_date,
            )
            stream_breakdown = self._wildlife_insight_breakdowns(
                current_wildlife,
                previous_wildlife,
                grouping="stream",
                start_date=start_date,
                end_date=end_date,
            )
            zone_breakdown = self._wildlife_insight_breakdowns(
                [record for record in current_wildlife if record["summary"].zone_id],
                [record for record in previous_wildlife if record["summary"].zone_id],
                grouping="zone",
                start_date=start_date,
                end_date=end_date,
            )
            daily_counts = Counter(
                record["observed_at"].astimezone(local_timezone).date()
                for record in current_wildlife
            )
            hour_counts = Counter(
                record["observed_at"].astimezone(local_timezone).hour
                for record in current_wildlife
            )
            sorted_wildlife = sorted(
                current_wildlife,
                key=lambda record: (record["observed_at"], record["summary"].id),
            )
            current_labels = {record["label"] for record in current_wildlife}
            previous_labels = {record["label"] for record in previous_wildlife}
            label_display_names = {
                record["label"]: record["display_name"]
                for record in [*current_wildlife, *previous_wildlife]
                if record["label"] is not None
            }

            return WildlifeInsightsSummary(
                period=WildlifeInsightsPeriod(
                    preset=payload.preset,
                    start_date=start_date,
                    end_date=end_date,
                    previous_start_date=previous_start_date,
                    previous_end_date=previous_end_date,
                    timezone_name=timezone_name,
                ),
                headline=WildlifeInsightsHeadline(
                    active_stream_count=active_stream_count,
                    active_visit_count=len(current_records),
                    reviewed_wildlife_observation_count=len(current_wildlife),
                    unique_confirmed_label_count=len(current_labels),
                    unresolved_visit_count=sum(
                        record["summary"].review_outcome == VisitReviewOutcome.needs_review
                        for record in current_records
                    ),
                    reviewed_non_bird_activity_count=sum(
                        record["summary"].review_outcome == VisitReviewOutcome.non_bird
                        for record in current_records
                    ),
                    busiest_stream=stream_breakdown[0] if stream_breakdown else None,
                    busiest_zone=zone_breakdown[0] if zone_breakdown else None,
                    peak_activity_hour=(
                        max(hour_counts, key=lambda hour: (hour_counts[hour], -hour))
                        if hour_counts
                        else None
                    ),
                    first_observation=(
                        self._wildlife_insight_representative(sorted_wildlife[0])
                        if sorted_wildlife
                        else None
                    ),
                    latest_observation=(
                        self._wildlife_insight_representative(sorted_wildlife[-1])
                        if sorted_wildlife
                        else None
                    ),
                ),
                comparison=WildlifeInsightsComparison(
                    previous_reviewed_wildlife_observation_count=len(previous_wildlife),
                    reviewed_wildlife_observation_change=(
                        len(current_wildlife) - len(previous_wildlife)
                    ),
                    new_labels=sorted(
                        label_display_names[label]
                        for label in current_labels - previous_labels
                        if label is not None
                    )[:12],
                    labels_not_seen=sorted(
                        label_display_names[label]
                        for label in previous_labels - current_labels
                        if label is not None
                    )[:12],
                ),
                leading_labels=leading_labels[:12],
                daily_trend=[
                    WildlifeInsightsDailyBucket(
                        local_date=start_date + timedelta(days=offset),
                        count=daily_counts[start_date + timedelta(days=offset)],
                    )
                    for offset in range(period_days)
                ],
                activity_by_hour=[
                    WildlifeInsightsHourBucket(hour=hour, count=hour_counts[hour])
                    for hour in range(24)
                ],
                stream_breakdown=stream_breakdown[:12],
                zone_breakdown=zone_breakdown[:12],
                review_context=WildlifeInsightsReviewContext(
                    blank_or_false_count=sum(
                        record["summary"].review_outcome
                        in {VisitReviewOutcome.blank, VisitReviewOutcome.false_positive}
                        for record in current_records
                    ),
                    ambiguous_or_unknown_count=sum(
                        record["summary"].review_outcome == VisitReviewOutcome.ambiguous
                        for record in current_records
                    ),
                    rejected_count=sum(
                        record["summary"].review_outcome == VisitReviewOutcome.rejected
                        for record in current_records
                    ),
                    unclassified_reviewed_count=sum(
                        record["summary"].review_outcome == VisitReviewOutcome.reviewed_other
                        for record in current_records
                    ),
                    pending_suggestion_evidence_count=sum(
                        record["summary"].has_suggestion
                        and record["summary"].review_outcome == VisitReviewOutcome.needs_review
                        for record in current_records
                    ),
                ),
                confirmed_activity_drilldown=WildlifeInsightsDrilldown(
                    review_filter=ActivityLibraryReviewFilter.confirmed_wildlife,
                    start_date=start_date,
                    end_date=end_date,
                ),
                unresolved_activity_drilldown=WildlifeInsightsDrilldown(
                    review_filter=ActivityLibraryReviewFilter.needs_review,
                    start_date=start_date,
                    end_date=end_date,
                ),
            )

    def _wildlife_insight_records(
        self,
        session: Session,
        *,
        start_at: datetime | None,
        end_at: datetime | None,
    ) -> list[dict[str, Any]]:
        query = (
            select(VisitModel, EventModel, StreamModel, CameraSourceModel)
            .join(EventModel, VisitModel.event_id == EventModel.id)
            .join(StreamModel, EventModel.stream_id == StreamModel.id)
            .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
            .where(
                VisitModel.is_superseded.is_(False),
                CameraSourceModel.status != SourceStatus.archived.value,
            )
        )
        if start_at is not None:
            query = query.where(EventModel.started_at >= start_at)
        if end_at is not None:
            query = query.where(EventModel.started_at < end_at)
        rows = session.execute(
            query.order_by(EventModel.started_at, EventModel.id, VisitModel.id)
        ).all()
        records: list[dict[str, Any]] = []
        for visit, event, stream, source in rows:
            summary = self._stream_visit_summary_from_models(session, visit, event)
            label = (
                self._normalize_label_from_session(session, summary.reviewed_label)
                if summary.reviewed_label
                else None
            )
            records.append(
                {
                    "summary": summary,
                    "stream_name": stream.name,
                    "source_name": source.name,
                    "observed_at": _as_utc(event.started_at),
                    "label": label,
                    "display_name": self._display_name_for_label(session, label)
                    if label
                    else None,
                }
            )
        return records

    def _wildlife_insight_breakdowns(
        self,
        current_records: list[dict[str, Any]],
        previous_records: list[dict[str, Any]],
        *,
        grouping: str,
        start_date: date,
        end_date: date,
    ) -> list[WildlifeInsightsBreakdown]:
        def key_and_name(record: dict[str, Any]) -> tuple[str, str]:
            summary: StreamVisitSummary = record["summary"]
            if grouping == "label":
                return record["label"], record["display_name"]
            if grouping == "stream":
                return summary.stream_id, record["stream_name"]
            assert summary.zone_id is not None
            return summary.zone_id, summary.zone_name or "Current Zone unavailable"

        grouped_current: dict[str, list[dict[str, Any]]] = {}
        previous_counts: Counter[str] = Counter()
        for record in current_records:
            key, _name = key_and_name(record)
            grouped_current.setdefault(key, []).append(record)
        for record in previous_records:
            key, _name = key_and_name(record)
            previous_counts[key] += 1

        breakdowns: list[WildlifeInsightsBreakdown] = []
        for key, records in grouped_current.items():
            ordered = sorted(
                records,
                key=lambda record: (record["observed_at"], record["summary"].id),
            )
            _ignored_key, name = key_and_name(ordered[0])
            drilldown = WildlifeInsightsDrilldown(
                review_filter=ActivityLibraryReviewFilter.confirmed_wildlife,
                start_date=start_date,
                end_date=end_date,
                confirmed_label=key if grouping == "label" else None,
                stream_id=key if grouping == "stream" else None,
                zone_id=key if grouping == "zone" else None,
            )
            breakdowns.append(
                WildlifeInsightsBreakdown(
                    id=key,
                    name=name,
                    count=len(ordered),
                    previous_count=previous_counts[key],
                    change=len(ordered) - previous_counts[key],
                    first_observed_at=ordered[0]["observed_at"],
                    latest_observed_at=ordered[-1]["observed_at"],
                    representative=self._wildlife_insight_representative(ordered[-1]),
                    drilldown=drilldown,
                )
            )
        return sorted(
            breakdowns,
            key=lambda item: (-item.count, item.name.lower(), item.id),
        )

    @staticmethod
    def _wildlife_insight_representative(
        record: dict[str, Any],
    ) -> WildlifeInsightsRepresentative:
        summary: StreamVisitSummary = record["summary"]
        return WildlifeInsightsRepresentative(
            visit_id=summary.id,
            event_id=summary.event_id,
            stream_id=summary.stream_id,
            stream_name=record["stream_name"],
            zone_id=summary.zone_id,
            zone_name=summary.zone_name,
            label=record["label"],
            display_name=record["display_name"],
            observed_at=record["observed_at"],
            primary_evidence=summary.primary_evidence,
        )

    def place_activity_report(
        self,
        payload: PlaceActivityReportRequest,
        *,
        now: datetime | None = None,
        local_timezone: tzinfo | None = None,
    ) -> PlaceActivityReportResponse:
        """Build one deterministic Place activity report for the explicit
        `[payload.start_at, payload.end_at)` period (see
        docs/place-activity-report-contract.md). Read-only: this method
        never creates or mutates a ReviewLabel, SpeciesSuggestion, Visit,
        Event, or any other product/review state -- it only reads already-
        durable facts through the same canonical resolver `zone_insights`/
        `wildlife_insights` already use (`_stream_visit_summary_from_models`)
        and delegates all report math to the pure
        `mockingbird.analytics.place_activity_report` module; this method
        performs none of its own.

        `now` is a test-only override for the report's generation moment
        (used for `generated_at` and the display `timezone_name`), mirroring
        `zone_insights`/`wildlife_insights`'s own convention. `local_timezone`
        is a test-only override for the IANA zone used to bucket each
        Visit's local hour, so DST-transition tests stay deterministic
        regardless of the host's own configured zone. Production callers
        never pass either.
        """

        period_start_at = _as_utc(payload.start_at)
        period_end_at = _as_utc(payload.end_at)
        generation_moment = now or datetime.now(UTC)
        generated_at = _as_utc(generation_moment)
        # Each Visit is converted to local time using the host's actual IANA
        # timezone rules (mockingbird.time_utils.resolve_host_local_timezone),
        # so a report period spanning a real DST transition buckets each
        # Visit by the offset that genuinely applied at its own timestamp --
        # never one fixed offset resolved once from the generation moment
        # and reused for the whole period. See "Local time and DST
        # correctness" in docs/place-activity-report-contract.md. This can
        # fall back to a fixed-offset snapshot (the product's original
        # behavior) only when no IANA zone can be discovered on this host --
        # see `resolve_host_local_timezone`'s own docstring.
        resolved_local_timezone = local_timezone or resolve_host_local_timezone(generation_moment)
        local_now = generation_moment.astimezone(resolved_local_timezone)
        timezone_name = local_now.tzname() or "local time"

        with self.session_factory() as session:
            stream_id_query = (
                select(StreamModel.id, CameraSourceModel.id, CameraSourceModel.name)
                .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                .where(CameraSourceModel.status != SourceStatus.archived.value)
            )
            if payload.source_ids:
                # Camera / Source + Multi-Camera Maturity v1, Phase N: an
                # additive narrowing of the same in-scope Stream set every
                # downstream computation (coverage, historical baseline,
                # representative evidence, digest) already uses -- this
                # never changes reviewed truth, only which of it this one
                # report call includes.
                stream_id_query = stream_id_query.where(
                    CameraSourceModel.id.in_(payload.source_ids)
                )
            # Place / Yard Intelligence v2, Phase 7: `stream_source_index`
            # is built from the exact same query this method already ran
            # for `stream_ids` -- zero additional queries -- so `source_
            # activity.py`'s per-Source comparison can resolve each Visit's
            # Source without joining CameraSourceModel a second time into
            # the much larger per-Visit query below.
            stream_source_index: dict[str, tuple[str, str]] = {}
            stream_ids: list[str] = []
            for stream_id, source_id, source_name in session.execute(stream_id_query).all():
                stream_ids.append(stream_id)
                stream_source_index[stream_id] = (source_id, source_name)

            # Always preloaded now (previously only when stream_ids was
            # non-empty): Historical Baseline Maturity + New/Regular Species
            # v1's own historical-facts lookup below needs it regardless of
            # whether any Stream is currently configured, and the taxonomy
            # table is always small and bounded -- one extra query only in
            # the rare zero-Stream first-run state.
            taxonomy_index = self._taxonomy_label_index(session)

            visit_facts: list[VisitFact] = []
            # Gate C -- Representative Species Evidence v1: gathered in the
            # same pass as `visit_facts` above so this costs zero additional
            # queries beyond what this report already issues -- `summary.
            # primary_evidence` is already resolved by `_stream_visit_
            # summary_from_models` regardless. Keyed by confirmed taxon
            # label only, mirroring `_classify`'s own CONFIRMED_WILDLIFE
            # branch exactly (never populated from a provisional
            # SpeciesSuggestion alone -- see "Truth contract" in
            # docs/representative-species-evidence-contract.md), and
            # deliberately scoped to this report's own period only -- see
            # "Time scope" in that contract doc.
            confirmed_summaries_by_label: dict[str, list[StreamVisitSummary]] = {}

            # Hoisted above `if stream_ids:` below (Place / Yard
            # Intelligence v2) so the weekly-window Visit gathering further
            # down -- its own separate, later `if` block, not nested inside
            # this one -- can reuse it too, without relying on Python's
            # def-executes-once-then-persists-in-the-enclosing-function
            # closure behavior across two sibling `if` blocks.
            def resolve_taxon(label: str | None) -> TaxonFact | None:
                if not label:
                    return None
                taxonomy = taxonomy_index.get(_taxonomy_key(label))
                if taxonomy is None:
                    return None
                return taxon_fact_from_taxonomy_label(_taxonomy_label_from_model(taxonomy))

            if stream_ids:

                visit_rows = session.execute(
                    select(VisitModel, EventModel)
                    .join(EventModel, VisitModel.event_id == EventModel.id)
                    .where(
                        VisitModel.is_superseded.is_(False),
                        EventModel.stream_id.in_(stream_ids),
                        # Same coarse Event-level candidate-row boundary
                        # zone_insights/wildlife_insights already filter on;
                        # the pure module below applies the exact
                        # activity_started_at half-open bound authoritatively,
                        # so a Visit whose refined activity window crosses
                        # this coarse boundary is still handled correctly.
                        EventModel.started_at >= period_start_at,
                        EventModel.started_at < period_end_at,
                    )
                    .order_by(EventModel.started_at, EventModel.id, VisitModel.id)
                ).all()

                for visit, event in visit_rows:
                    # Reuses the same preloaded `taxonomy_index` this method
                    # already built for its own confirmed_taxon/
                    # provisional_taxon resolution just above, so the
                    # resolver's own internal taxonomy lookup
                    # (`_visit_review_outcome`) no longer costs a second,
                    # per-Visit full-table scan on top of it -- see
                    # `_stream_visit_summary_from_models`'s docstring and
                    # `test_taxonomy_resolution_adds_no_second_per_visit_
                    # query` in tests/test_place_activity_report_repository.py.
                    summary = self._stream_visit_summary_from_models(
                        session, visit, event, taxonomy_index=taxonomy_index
                    )
                    confirmed_taxon = resolve_taxon(summary.reviewed_label)
                    source_id, source_name = stream_source_index.get(event.stream_id, (None, None))
                    visit_facts.append(
                        visit_fact_from_stream_visit_summary(
                            summary,
                            confirmed_taxon=confirmed_taxon,
                            provisional_taxon=resolve_taxon(summary.suggested_label),
                            source_id=source_id,
                            source_name=source_name,
                        )
                    )
                    if (
                        summary.review_status == ReviewStatus.reviewed
                        and confirmed_taxon is not None
                        and is_wildlife_category(confirmed_taxon.category)
                    ):
                        confirmed_summaries_by_label.setdefault(confirmed_taxon.label, []).append(summary)

                # Camera / Source + Multi-Camera Maturity v1, Phase H: a
                # confirmed multimodal or cross-camera "associated" pair is
                # one real encounter observed by two Sources -- excluded here
                # (not merged/relabeled -- see `_associated_visit_ids_to_
                # exclude_from_counting`'s own docstring) so every downstream
                # count (species-day totals, historical baseline, change
                # windows, digest) counts it once. Representative-evidence
                # selection just below is deliberately left unfiltered: it
                # already picks one photo per species regardless of how many
                # Visits contributed, so it is not itself a double-counting
                # surface.
                excluded_visit_ids = self._associated_visit_ids_to_exclude_from_counting(
                    session, [fact.visit_id for fact in visit_facts],
                )
                if excluded_visit_ids:
                    visit_facts = [fact for fact in visit_facts if fact.visit_id not in excluded_visit_ids]

            # Gate C -- Representative Species Evidence v1: the same
            # canonical selector Bird Log uses (`_representative_evidence_
            # response`), run once per taxon that had a confirmed Visit
            # this period. A label absent here (no qualifying Visit, or no
            # candidate had safe/present evidence) correctly yields no
            # representative_evidence below -- see "No-image semantics" in
            # docs/representative-species-evidence-contract.md.
            representative_evidence_by_label: dict[str, RepresentativeEvidence] = {
                label: response
                for label, summaries_for_label in confirmed_summaries_by_label.items()
                if (response := self._representative_evidence_response(session, summaries_for_label))
                is not None
            }

            coverage, streams_without_history = self._place_activity_coverage_summary(
                session,
                stream_ids=stream_ids,
                period_start_at=period_start_at,
                period_end_at=period_end_at,
            )

            # Historical Baseline Maturity + New/Regular Species v1 (see
            # docs/historical-baseline-maturity-contract.md). window_end_at
            # is deliberately this report's own period_end_at, not "now" --
            # see `_historical_place_baseline_and_species_statuses`'s
            # docstring for why a past-period report must stay reproducible.
            historical_place_intelligence = self._historical_place_baseline_and_species_statuses(
                session,
                stream_ids=stream_ids,
                taxonomy_index=taxonomy_index,
                window_end_at=period_end_at,
                local_timezone=resolved_local_timezone,
                period_start_at=period_start_at,
                period_end_at=period_end_at,
            )

            # Place / Yard Intelligence v2, Phase 6: at most one "was this
            # Visit's own timing unusual" check per taxon (stops at the
            # first unusual Visit found -- the digest only needs a bool),
            # reusing `temporal_patterns` this call already computed above
            # and this report's own already-gathered `visit_facts` -- zero
            # additional queries.
            unusual_timing_by_label: dict[str, bool] = {}
            for fact in visit_facts:
                if fact.confirmed_taxon is None or unusual_timing_by_label.get(fact.confirmed_taxon.label):
                    continue
                pattern = historical_place_intelligence.temporal_patterns.get(fact.confirmed_taxon.label)
                if pattern is None:
                    continue
                local_hour = fact.activity_started_at.astimezone(resolved_local_timezone).hour
                if compare_visit_timing(local_hour, pattern) == "unusual":
                    unusual_timing_by_label[fact.confirmed_taxon.label] = True

            # Phase 7/8: per-Source coverage-normalized activity + a bounded
            # admission-yield comparison, both grouped from the same
            # `stream_source_index` this call already built -- a Source
            # with more than one Stream (not the norm today) has its
            # Streams' own coverage/counters summed, never double-counted.
            source_stream_ids: dict[str, list[str]] = {}
            source_names: dict[str, str] = {}
            for stream_id, (source_id, source_name) in stream_source_index.items():
                source_stream_ids.setdefault(source_id, []).append(stream_id)
                source_names[source_id] = source_name

            source_coverage_facts: dict[str, SourceCoverageFact] = {}
            for source_id, streams_for_source in source_stream_ids.items():
                source_monitored_intervals, source_history_available_from, _ = (
                    self._monitoring_exposure_intervals_and_history(
                        session,
                        stream_ids=streams_for_source,
                        period_start_at=period_start_at,
                        period_end_at=period_end_at,
                    )
                )
                source_coverage = compute_coverage_summary(
                    period_start_at=period_start_at,
                    period_end_at=period_end_at,
                    monitored_intervals=source_monitored_intervals,
                    history_available_from=source_history_available_from,
                )
                source_coverage_facts[source_id] = SourceCoverageFact(
                    source_id=source_id,
                    source_name=source_names[source_id],
                    monitored_seconds=source_coverage.monitored_seconds,
                )
            activity_by_source = compute_source_activity(
                visit_facts, coverage_by_source=source_coverage_facts,
            )

            authority_counters_by_source: dict[str, list[int]] = {}
            if stream_ids:
                for row_stream_id, attempted, created, suppressed in session.execute(
                    select(
                        ObservationAuthoritySettingsModel.stream_id,
                        ObservationAuthoritySettingsModel.candidates_attempted_count,
                        ObservationAuthoritySettingsModel.candidates_created_count,
                        ObservationAuthoritySettingsModel.suppressed_count,
                    ).where(ObservationAuthoritySettingsModel.stream_id.in_(stream_ids))
                ).all():
                    row_source_id = stream_source_index.get(row_stream_id, (None, None))[0]
                    if row_source_id is None:
                        continue
                    totals = authority_counters_by_source.setdefault(row_source_id, [0, 0, 0])
                    totals[0] += attempted
                    totals[1] += created
                    totals[2] += suppressed
            source_quality_signals = compute_source_quality_signals(
                [
                    SourceAuthorityCounters(
                        source_id=source_id,
                        source_name=source_names[source_id],
                        candidates_attempted_count=totals[0],
                        candidates_created_count=totals[1],
                        suppressed_count=totals[2],
                    )
                    for source_id, totals in authority_counters_by_source.items()
                ]
            )

            # Phase 13: the identical report shape as `report` below, over
            # the 7-usable-day recent window `change_summary.windows`
            # already establishes -- `None` (no weekly digest at all) when
            # that window is not valid yet, mirroring every other consumer
            # of `is_valid`. Representative evidence is deliberately not
            # re-gathered for this window (a bounded scope decision, see
            # docs/place-yard-intelligence-v2-contract.md); a weekly
            # highlight's `representative_evidence` is `None` unless the
            # same taxon also had confirmed evidence within *today's* own
            # period -- an honest "no image" outcome, never a wrong one.
            weekly_report: PlaceActivityReport | None = None
            weekly_windows = historical_place_intelligence.change_summary.windows
            if weekly_windows.is_valid and stream_ids:
                assert weekly_windows.recent_window_start_at is not None
                weekly_start_at = weekly_windows.recent_window_start_at
                weekly_end_at = weekly_windows.recent_window_end_at
                weekly_visit_rows = session.execute(
                    select(VisitModel, EventModel)
                    .join(EventModel, VisitModel.event_id == EventModel.id)
                    .where(
                        VisitModel.is_superseded.is_(False),
                        EventModel.stream_id.in_(stream_ids),
                        EventModel.started_at >= weekly_start_at,
                        EventModel.started_at < weekly_end_at,
                    )
                    .order_by(EventModel.started_at, EventModel.id, VisitModel.id)
                ).all()
                weekly_visit_facts: list[VisitFact] = []
                for visit, event in weekly_visit_rows:
                    weekly_summary = self._stream_visit_summary_from_models(
                        session, visit, event, taxonomy_index=taxonomy_index
                    )
                    weekly_visit_facts.append(
                        visit_fact_from_stream_visit_summary(
                            weekly_summary,
                            confirmed_taxon=resolve_taxon(weekly_summary.reviewed_label),
                            provisional_taxon=resolve_taxon(weekly_summary.suggested_label),
                        )
                    )
                if len(weekly_visit_facts) >= 2:
                    weekly_excluded_ids = self._associated_visit_ids_to_exclude_from_counting(
                        session, [fact.visit_id for fact in weekly_visit_facts],
                    )
                    if weekly_excluded_ids:
                        weekly_visit_facts = [
                            fact for fact in weekly_visit_facts if fact.visit_id not in weekly_excluded_ids
                        ]
                weekly_coverage, _ = self._place_activity_coverage_summary(
                    session, stream_ids=stream_ids, period_start_at=weekly_start_at, period_end_at=weekly_end_at,
                )
                weekly_report = compute_place_activity_report(
                    weekly_visit_facts,
                    period_start_at=weekly_start_at,
                    period_end_at=weekly_end_at,
                    local_timezone=resolved_local_timezone,
                    coverage=weekly_coverage,
                    generated_at=generated_at,
                )

        report = compute_place_activity_report(
            visit_facts,
            period_start_at=period_start_at,
            period_end_at=period_end_at,
            local_timezone=resolved_local_timezone,
            coverage=coverage,
            generated_at=generated_at,
        )

        warnings: list[str] = [
            "Visits are activity sessions, not estimates of unique animals. "
            "The same animal may create more than one Visit if it leaves and returns.",
        ]
        if not stream_ids:
            warnings.append("No Streams are configured yet.")
        elif coverage.history_available_from is None:
            warnings.append(
                "No durable monitoring exposure has been recorded for any Stream yet, "
                "so coverage is withheld."
            )
        else:
            if coverage.history_is_partial:
                warnings.append(
                    "Durable monitoring exposure is available from "
                    f"{coverage.history_available_from.strftime('%B %d, %Y').replace(' 0', ' ')}. "
                    "Earlier time in this period is excluded from coverage."
                )
            if streams_without_history:
                # A honest, additive disclosure -- not a withholding --
                # see the coverage-policy audit in
                # `_place_activity_coverage_summary`'s own docstring.
                warnings.append(
                    "One or more Streams have no durable monitoring exposure recorded yet; "
                    "coverage reflects only Streams with recorded history."
                )

        return place_activity_report_response(
            report,
            timezone_name=timezone_name,
            warnings=warnings,
            historical_place_intelligence=historical_place_intelligence,
            representative_evidence=representative_evidence_by_label,
            unusual_timing_by_label=unusual_timing_by_label,
            activity_by_source=activity_by_source,
            source_quality_signals=source_quality_signals,
            weekly_report=weekly_report,
        )

    def _taxonomy_label_index(self, session: Session) -> dict[str, TaxonomyLabelModel]:
        """Preload every `TaxonomyLabelModel` once per report call and index
        it by every normalized candidate key (id/label/display_name/each
        alias), so resolving this report's own `confirmed_taxon`/
        `provisional_taxon` facts for many Visits costs one query total, not
        one additional query per Visit.

        This mirrors -- without modifying -- `_taxonomy_label_model_for_
        input`'s own matching rule (same `_taxonomy_key` normalization, same
        candidate fields), so a Place Activity Report's taxonomy resolution
        can never diverge from every other feature's. A Place Activity
        Report can span far more Visits than any existing bounded per-Visit
        caller of that helper (a Zone Insights window scoped to one Zone,
        for example), so this batches deliberately rather than reusing its
        per-call full-table scan unchanged -- see the "Performance" note in
        docs/place-activity-report-contract.md and this milestone's final
        report. `_taxonomy_label_model_for_input` itself is intentionally
        left unmodified: it backs many truth-writing paths
        (`_normalize_label_from_session` alone underlies every review-
        correction creation path), so a reporting-only performance concern
        is not a reason to change its signature.

        This does not, and is not intended to, eliminate every taxonomy
        query this method issues: `_stream_visit_summary_from_models` (the
        canonical resolver this method reuses unmodified, per this
        milestone's own instructions) already costs one `taxonomy_labels`
        query per reviewed Visit with a real species label through its own
        `_visit_review_outcome` -- the exact same cost `zone_insights`/
        `wildlife_insights` already pay in production today. This index
        only prevents a *second*, additional per-Visit query for this
        report's own confirmed/provisional resolution on top of that
        pre-existing one (see `test_taxonomy_resolution_adds_no_second_
        per_visit_query` in tests/test_place_activity_report_repository.py,
        which measures exactly this distinction). Removing the resolver's
        own pre-existing per-Visit cost would mean changing
        `_stream_visit_summary_from_models`/`_visit_review_outcome`
        themselves, which are shared by nearly every Visit-reading feature
        in the product -- out of scope for this tightly-bounded milestone;
        see the final report's "known limitations."

        On a key claimed by more than one label (a real possible data-
        hygiene edge case -- two labels sharing an overlapping alias), the
        lowest-`id` label wins, exactly like the unbatched helper's
        id-ordered linear scan (labels are iterated in `id` order and a key
        already claimed is never overwritten).
        """

        index: dict[str, TaxonomyLabelModel] = {}
        labels = session.scalars(
            select(TaxonomyLabelModel).order_by(TaxonomyLabelModel.id)
        ).all()
        for label in labels:
            taxonomy_label = _taxonomy_label_from_model(label)
            candidates = [
                taxonomy_label.id,
                taxonomy_label.label,
                taxonomy_label.display_name,
                *taxonomy_label.aliases,
            ]
            for candidate in candidates:
                key = _taxonomy_key(candidate)
                if key and key not in index:
                    index[key] = label
        return index

    def _place_activity_coverage_summary(
        self,
        session: Session,
        *,
        stream_ids: list[str],
        period_start_at: datetime,
        period_end_at: datetime,
    ) -> tuple[CoverageSummary, bool]:
        """Place-wide monitoring coverage from durable
        `MonitoringExposureIntervalModel` history only (see
        `compute_coverage_summary` and "Monitoring coverage" in
        docs/place-activity-report-contract.md) -- never inferred from Visit
        timestamps, camera configuration, or current runtime state.

        Batches across every in-scope Stream into at most two queries total
        (a grouped MIN and a ranged interval fetch), instead of the
        O(Streams) round trips `_zone_insights_exposure` costs by being
        called once per Stream in a loop -- a Place-wide report can span far
        more Streams than one bounded Zone Insights view. `_zone_insights_
        exposure` is left unmodified: its own per-Stream shape and return
        type (aggregated `healthy_seconds`, not raw intervals) are already
        relied on by `zone_insights`, and this report needs the raw
        intervals so the pure `compute_coverage_summary` can compute gaps
        itself rather than this method re-deriving them.

        Coverage policy (Place Intelligence Backend Hardening v1's
        coverage-policy audit; see "Monitoring coverage" in
        docs/place-activity-report-contract.md): unlike `zone_insights`'
        own aggregate exposure -- which *sums* independent per-Stream
        camera-hours and therefore cannot honestly represent a Stream with
        zero history any way other than all-or-nothing -- this report's
        coverage is a *union*: "was this Place being watched by any camera
        at this moment." A Stream with no durable exposure history at all
        (for example one just added, mid-period, that has not yet recorded
        its first healthy frame) contributes nothing to that union either
        way, so excluding it from the coverage figure loses no honest
        information -- it only stops one not-yet-reporting Stream from
        retroactively blanking out years of otherwise-trustworthy coverage
        from every *other* Stream. The figure is therefore withheld
        (`history_available_from=None`) only when *no* in-scope Stream has
        ever recorded any durable history -- not merely when one of several
        does not. The second return value reports whether any in-scope
        Stream lacks durable history at all, so the caller's own
        `warnings` can disclose that honestly without inventing a
        materiality judgment here.
        """

        monitored_intervals, history_available_from, streams_without_history = (
            self._monitoring_exposure_intervals_and_history(
                session,
                stream_ids=stream_ids,
                period_start_at=period_start_at,
                period_end_at=period_end_at,
            )
        )
        return (
            compute_coverage_summary(
                period_start_at=period_start_at,
                period_end_at=period_end_at,
                monitored_intervals=monitored_intervals,
                history_available_from=history_available_from,
            ),
            streams_without_history,
        )

    def _monitoring_exposure_intervals_and_history(
        self,
        session: Session,
        *,
        stream_ids: list[str],
        period_start_at: datetime,
        period_end_at: datetime,
    ) -> tuple[list[TimeInterval], datetime | None, bool]:
        """Raw durable `MonitoringExposureIntervalModel` history for one
        `[period_start_at, period_end_at)` window across `stream_ids`: the
        overlapping intervals themselves, the earliest durable history among
        Streams that have any (`None` if none do), and whether any in-scope
        Stream lacks durable history entirely.

        Extracted from `_place_activity_coverage_summary` (its sole caller
        until Historical Baseline Maturity + New/Regular Species v1 added a
        second one, `_historical_usable_dates` -- see
        docs/historical-baseline-maturity-contract.md) so both compute their
        history-availability figure from the exact same "grouped MIN + one
        ranged interval fetch" query shape rather than two independently-
        written queries that could silently drift apart. Pure extraction:
        `_place_activity_coverage_summary`'s own observable behavior is
        unchanged (proven by its full pre-existing test suite passing
        unmodified).
        """

        if not stream_ids:
            return [], None, False

        history_starts = dict(
            session.execute(
                select(
                    MonitoringExposureIntervalModel.stream_id,
                    func.min(MonitoringExposureIntervalModel.started_at),
                )
                .where(MonitoringExposureIntervalModel.stream_id.in_(stream_ids))
                .group_by(MonitoringExposureIntervalModel.stream_id)
            ).all()
        )
        streams_without_history = len(history_starts) < len(stream_ids)
        if not history_starts:
            # No in-scope Stream has ever recorded any durable exposure --
            # an honest, full "not yet computable," not a partial figure
            # with nothing durable behind it at all.
            return [], None, streams_without_history

        # The earliest durable history among Streams that have any -- a
        # Stream with none contributes nothing here either way (see
        # `_place_activity_coverage_summary`'s own docstring), so it is
        # simply excluded from this min() rather than forcing the whole
        # figure to None.
        history_available_from = _as_utc(min(history_starts.values()))

        rows = session.scalars(
            select(MonitoringExposureIntervalModel).where(
                MonitoringExposureIntervalModel.stream_id.in_(stream_ids),
                MonitoringExposureIntervalModel.started_at < period_end_at,
                func.coalesce(
                    MonitoringExposureIntervalModel.ended_at,
                    MonitoringExposureIntervalModel.last_confirmed_fresh_at,
                )
                > period_start_at,
            )
        ).all()
        monitored_intervals = [
            TimeInterval(
                _as_utc(row.started_at),
                _as_utc(
                    row.ended_at if row.ended_at is not None else row.last_confirmed_fresh_at
                ),
            )
            for row in rows
        ]
        return monitored_intervals, history_available_from, streams_without_history

    def _historical_usable_dates(
        self,
        session: Session,
        *,
        stream_ids: list[str],
        window_end_at: datetime,
        local_timezone: tzinfo,
    ) -> tuple[frozenset[date], bool, float]:
        """Place-local usable-day facts for the trailing
        `HISTORICAL_BASELINE_WINDOW_DAYS`-day window ending at
        `window_end_at`, from the same durable `MonitoringExposureIntervalModel`
        ledger `_place_activity_coverage_summary` reads -- never inferred
        from Visit timestamps or current runtime state. Shared by both the
        Place-wide `HistoricalPlaceBaseline` and Bird Log's per-label
        regularity figures, so both always agree on the same usable-day set
        (see `usable_dates_from_daily_monitored_seconds`'s docstring).

        Returns `(usable_dates, has_any_monitoring_history, total_monitored_
        seconds_in_window)`. `has_any_monitoring_history` is a separate
        signal from an empty `usable_dates` set -- see
        `compute_historical_place_baseline`'s docstring for why a Place
        monitored heavily outside this window still has a real, known
        (possibly zero) total for the window, not a fabricated "not yet
        computable" absence.
        """

        window_start_at = window_end_at - timedelta(days=HISTORICAL_BASELINE_WINDOW_DAYS)
        monitored_intervals, history_available_from, _streams_without_history = (
            self._monitoring_exposure_intervals_and_history(
                session,
                stream_ids=stream_ids,
                period_start_at=window_start_at,
                period_end_at=window_end_at,
            )
        )
        daily_monitored_seconds = bucket_intervals_by_local_day(
            monitored_intervals,
            window_start_at=window_start_at,
            window_end_at=window_end_at,
            local_timezone=local_timezone,
        )
        usable_dates = usable_dates_from_daily_monitored_seconds(daily_monitored_seconds)
        total_monitored_seconds = sum(daily_monitored_seconds.values())
        return usable_dates, history_available_from is not None, total_monitored_seconds

    def _daylight_bucket_by_visit_id(
        self, session: Session, visits: list[VisitFact], *, local_timezone: tzinfo, now: datetime,
    ) -> dict[str, DaylightBucket]:
        """Place / Yard Intelligence v2: a bounded, absence-safe day/night
        classification for `temporal_pattern.compute_taxon_temporal_
        patterns`'s daylight dimension, reusing the exact same solar
        primitives `get_place_environmental_context_today`/`get_visit_
        environmental_context` already rely on -- never a second solar
        computation.

        Returns `{}` immediately, at zero cost, when the Place's coordinate
        setting is not configured -- solar/daylight is opt-in (see
        docs/environmental-context-foundation-v1-contract.md), and missing
        environmental data must never break core Place intelligence.

        Bounded to at most one `_get_daylight_window_in_session` resolution
        per *distinct local calendar date* in `visits` (never per-Visit):
        every Visit sharing a local date reuses that date's own resolved
        [sunrise, sunset) window. This is a deliberate, disclosed
        simplification -- a Visit very close to midnight UTC could in
        principle want a window resolved from an adjacent UTC date -- of
        the same honest-approximation character as this product's existing
        "no civil timezone from longitude" and "~11 km coarse location"
        disclosures, not a silent inaccuracy.
        """

        settings = session.get(EnvironmentalContextSettingsModel, 1)
        latitude = settings.coarse_latitude if settings is not None else None
        longitude = settings.coarse_longitude if settings is not None else None
        if latitude is None or longitude is None:
            return {}

        visits_by_local_date: dict[date, list[VisitFact]] = {}
        for visit in visits:
            if visit.confirmed_taxon is None:
                continue
            local_date = visit.activity_started_at.astimezone(local_timezone).date()
            visits_by_local_date.setdefault(local_date, []).append(visit)

        result: dict[str, DaylightBucket] = {}
        for visits_on_date in visits_by_local_date.values():
            representative_instant = visits_on_date[0].activity_started_at
            window = self._get_daylight_window_in_session(
                session, now=now, instant=representative_instant, latitude=latitude, longitude=longitude,
            )
            if window is None:
                continue
            sunrise_at, sunset_at = window
            for visit in visits_on_date:
                result[visit.visit_id] = solar_context.classify_daylight_state(
                    visit.activity_started_at, sunrise_at, sunset_at
                )
        return result

    def _historical_place_baseline_and_species_statuses(
        self,
        session: Session,
        *,
        stream_ids: list[str],
        taxonomy_index: dict[str, TaxonomyLabelModel],
        window_end_at: datetime,
        local_timezone: tzinfo,
        period_start_at: datetime,
        period_end_at: datetime,
    ) -> HistoricalPlaceIntelligence:
        """Compute the Place-wide `HistoricalPlaceBaseline`, every
        all-time-confirmed taxon's `SpeciesHistoricalStatus`, the Gate C --
        Meaningful Change Detection v1 `PlaceChangeSummary` (see
        docs/meaningful-change-detection-contract.md), Gate C --
        Per-Species Zone + Time Pattern Intelligence v1's per-taxon
        `TaxonPlacePattern` (see "Per-species Zone and time patterns" in
        docs/place-activity-report-contract.md), and -- Place / Yard
        Intelligence v2 -- each taxon's `RegularityNarrative`,
        `SeasonalPattern`, `TaxonTemporalPattern`, and
        `TaxonHabitatAssociation` list (see
        docs/place-yard-intelligence-v2-contract.md), for `ProductRepository.
        place_activity_report`'s own Today integration and (independently
        anchored) `wildlife_journal_overview`/`wildlife_journal_history`'s
        Bird Log integration. Read-only, like every other method in this
        file's reporting family.

        The Place / Yard Intelligence v2 facts are computed from the exact
        same `usable_dates`/`window_visits`/`taxa`/`statuses`/
        `change_summary` this method already assembles below -- zero
        additional queries for regularity/seasonal, one additional bounded
        `list_place_phenology_observations()` query for habitat
        association (skipped entirely when no phenology has ever been
        recorded), and the bounded, absence-safe solar resolution described
        in `_daylight_bucket_by_visit_id` above for the temporal pattern's
        daylight dimension only (its hour-band dimension costs nothing
        extra).

        The change summary and taxon place patterns are both computed from
        the exact same `usable_dates`/`window_visits`/`taxa` this method
        already fetches for historical baseline -- zero additional queries
        beyond what this method already issued before Gate C existed.

        `window_end_at` anchors the trailing `HISTORICAL_BASELINE_WINDOW_
        DAYS`-day regularity window -- deliberately the caller's own report
        `period_end_at`, not "now", so a report for a past period always
        reproduces the same historical facts regardless of when it is
        re-viewed (see product-doctrine.md's "Derived insights... must
        remain reproducible from persisted facts"). `period_start_at`/
        `period_end_at` are the window used only for the per-taxon "is this
        confirmation this taxon's all-time-first" check -- ordinarily the
        same as the report's own period.

        Two bounded queries beyond the shared usable-dates lookup: one cheap
        `GROUP BY reviewed_label` aggregate for all-time first/last-confirmed
        per taxon (independent of Visit volume -- bounded by distinct
        confirmed-label count, not Visit count), and one Visit query scoped
        to the trailing window (mirroring `place_activity_report`'s own
        bounded Visit query shape) for distinct-usable-day/regularity
        accounting. Both reuse the caller's already-preloaded `taxonomy_
        index` -- no second per-row taxonomy lookup.
        """

        usable_dates, has_any_monitoring_history, total_monitored_seconds = (
            self._historical_usable_dates(
                session,
                stream_ids=stream_ids,
                window_end_at=window_end_at,
                local_timezone=local_timezone,
            )
        )

        def resolve_wildlife_taxon(label: str) -> TaxonFact | None:
            taxonomy = taxonomy_index.get(_taxonomy_key(label))
            if taxonomy is None:
                return None
            taxon = taxon_fact_from_taxonomy_label(_taxonomy_label_from_model(taxonomy))
            # Mirrors `place_activity_report._classify`'s CONFIRMED_WILDLIFE
            # branch exactly (`is_wildlife_category` alone already excludes
            # both "false_positive" and "unknown" -- see
            # `mockingbird.wildlife_taxonomy`'s denylist) -- never a second,
            # independently-drifting truth-precedence rule.
            return taxon if is_wildlife_category(taxon.category) else None

        def resolve_any_taxon(label: str) -> TaxonFact | None:
            # Deliberately broader than resolve_wildlife_taxon above (any
            # resolvable taxonomy row, any category) so Gate C's own
            # Place-wide `overall` change aggregate can recognize a
            # confirmed "unknown_bird"/"unknown_animal" abstention as real
            # wildlife activity -- see place_change_summary.py's own truth
            # contract. This never changes `taxa`/`compute_species_
            # historical_statuses`'s existing output: both already ignore
            # any classification other than CONFIRMED_WILDLIFE, so a Visit
            # resolved here to a non-wildlife or "unknown" category is
            # filtered out downstream exactly as before this milestone.
            taxonomy = taxonomy_index.get(_taxonomy_key(label))
            if taxonomy is None:
                return None
            return taxon_fact_from_taxonomy_label(_taxonomy_label_from_model(taxonomy))

        taxa: dict[str, TaxonFact] = {}
        all_time_first_confirmed_at: dict[str, datetime] = {}
        all_time_last_confirmed_at: dict[str, datetime] = {}
        if stream_ids:
            all_time_rows = session.execute(
                select(
                    VisitModel.reviewed_label,
                    func.min(EventModel.started_at),
                    func.max(EventModel.started_at),
                )
                .join(EventModel, VisitModel.event_id == EventModel.id)
                .where(
                    VisitModel.is_superseded.is_(False),
                    VisitModel.review_status == ReviewStatus.reviewed.value,
                    VisitModel.reviewed_label.is_not(None),
                    EventModel.stream_id.in_(stream_ids),
                )
                .group_by(VisitModel.reviewed_label)
            ).all()
            for reviewed_label, first_at, last_at in all_time_rows:
                taxon = resolve_wildlife_taxon(reviewed_label)
                if taxon is None:
                    continue
                # A data-hygiene edge case (two raw labels normalizing to the
                # same taxon) merges honestly rather than picking one
                # arbitrarily -- matches every other taxonomy-normalizing
                # aggregate in this file.
                taxa[taxon.label] = taxon
                first_at, last_at = _as_utc(first_at), _as_utc(last_at)
                if taxon.label not in all_time_first_confirmed_at or first_at < all_time_first_confirmed_at[taxon.label]:
                    all_time_first_confirmed_at[taxon.label] = first_at
                if taxon.label not in all_time_last_confirmed_at or last_at > all_time_last_confirmed_at[taxon.label]:
                    all_time_last_confirmed_at[taxon.label] = last_at

        distinct_taxa_count = len(taxa)
        earliest_authoritative_record_at = (
            min(all_time_first_confirmed_at.values()) if all_time_first_confirmed_at else None
        )
        latest_authoritative_record_at = (
            max(all_time_last_confirmed_at.values()) if all_time_last_confirmed_at else None
        )

        baseline = compute_historical_place_baseline(
            window_start_at=window_end_at - timedelta(days=HISTORICAL_BASELINE_WINDOW_DAYS),
            window_end_at=window_end_at,
            usable_dates=usable_dates,
            has_any_monitoring_history=has_any_monitoring_history,
            total_monitored_seconds=total_monitored_seconds,
            distinct_taxa_count=distinct_taxa_count,
            earliest_authoritative_record_at=earliest_authoritative_record_at,
            latest_authoritative_record_at=latest_authoritative_record_at,
        )

        window_visits: list[VisitFact] = []
        # Note: unlike the historical-baseline-only computation this method
        # originally performed, this query must run whenever Streams exist
        # even if `taxa` (all-time confirmed *wildlife* taxa) is empty --
        # Gate C's `overall` aggregate still needs to see a confirmed
        # "unknown_bird"/"unknown_animal" abstention even when no named
        # species has ever been confirmed at this Place.
        if stream_ids:
            window_start_at = window_end_at - timedelta(days=HISTORICAL_BASELINE_WINDOW_DAYS)
            # Gate C -- Per-Species Zone + Time Pattern Intelligence v1 needs
            # each Visit's own Zone alongside its taxon/timestamp, so this
            # query now also joins ZoneModel -- deliberately on the Visit's
            # own `zone_id` only, never coalesced with `EventModel.
            # primary_zone_id` the way the canonical `_stream_visit_summary_
            # from_models` resolver does for its own, different purpose. See
            # `compute_taxon_place_patterns`'s docstring for why an
            # Event-level fallback would risk lending a multi-subject
            # Event's founding sibling's Zone to another sibling that was
            # never actually inside it.
            window_rows = session.execute(
                select(
                    VisitModel.id,
                    VisitModel.reviewed_label,
                    EventModel.started_at,
                    ZoneModel.id,
                    ZoneModel.name,
                )
                .join(EventModel, VisitModel.event_id == EventModel.id)
                .outerjoin(
                    ZoneModel,
                    and_(
                        ZoneModel.id == VisitModel.zone_id,
                        ZoneModel.stream_id == EventModel.stream_id,
                    ),
                )
                .where(
                    VisitModel.is_superseded.is_(False),
                    VisitModel.review_status == ReviewStatus.reviewed.value,
                    VisitModel.reviewed_label.is_not(None),
                    EventModel.stream_id.in_(stream_ids),
                    EventModel.started_at >= window_start_at,
                    EventModel.started_at < window_end_at,
                )
            ).all()
            for visit_id, reviewed_label, started_at, zone_id, zone_name in window_rows:
                taxon = resolve_any_taxon(reviewed_label)
                if taxon is None:
                    continue
                window_visits.append(
                    VisitFact(
                        visit_id=visit_id,
                        zone_id=zone_id,
                        zone_name=zone_name,
                        activity_started_at=_as_utc(started_at),
                        resolution="reviewed",
                        confirmed_taxon=taxon,
                    )
                )

        # Acoustic Productization, Licensing & Field Acceptance v1: this
        # method's own `window_visits` feeds `total_confirmed_count` (Bird
        # Log/Today's per-taxon historical status) and Gate C's per-zone/
        # per-hour `reviewed_visit_count` (`compute_taxon_place_patterns`)
        # -- every one of this method's 6 call sites shares this single
        # fix. Mirrors `place_activity_report`'s own, separately-applied
        # `_associated_visit_ids_to_exclude_from_counting` call for its
        # `visit_facts` (a different list, computed earlier in that
        # caller) -- that existing call does not reach into this method's
        # own independent `window_visits` query, which is why the same
        # exclusion is needed here too, not redundant with it.
        if len(window_visits) >= 2:
            excluded_visit_ids = self._associated_visit_ids_to_exclude_from_counting(
                session, [fact.visit_id for fact in window_visits],
            )
            if excluded_visit_ids:
                window_visits = [
                    fact for fact in window_visits if fact.visit_id not in excluded_visit_ids
                ]

        statuses = compute_species_historical_statuses(
            window_visits,
            taxa=taxa,
            all_time_first_confirmed_at=all_time_first_confirmed_at,
            all_time_last_confirmed_at=all_time_last_confirmed_at,
            usable_dates=usable_dates,
            local_timezone=local_timezone,
            period_start_at=period_start_at,
            period_end_at=period_end_at,
            baseline_maturity=baseline.maturity,
        )
        change_summary = compute_place_change_summary(
            window_visits,
            taxa=taxa,
            usable_dates=usable_dates,
            local_timezone=local_timezone,
            window_end_at=window_end_at,
        )
        taxon_place_patterns = compute_taxon_place_patterns(
            window_visits, local_timezone=local_timezone
        )

        species_historical_statuses = {status.taxon.label: status for status in statuses}
        change_status_by_label = {status.taxon.label: status for status in change_summary.taxa}

        # Place / Yard Intelligence v2, Phase 4: pure synthesis, zero
        # additional queries -- see regularity_narrative.py's own docstring.
        regularity_narratives: dict[str, RegularityNarrative] = {}
        for label, historical_status in species_historical_statuses.items():
            change_status = change_status_by_label.get(label)
            regularity_narratives[label] = compute_regularity_narrative(
                historical_status.status,
                change_status.status if change_status is not None else None,
                reference_presence_days=(
                    change_status.reference_presence_days if change_status is not None else None
                ),
                # Mobile & Remote Experience v1: lets `returned_after_absence`
                # distinguish a real established-taxon return from a merely
                # young taxon whose reference window predates its own
                # existence -- the same guard place_story.py's own checkpoint
                # scan already applies, now shared rather than duplicated.
                first_confirmed_at=all_time_first_confirmed_at.get(label),
                reference_window_start_at=change_summary.windows.reference_window_start_at,
            )

        # Phase 5: reuses the exact same window_visits/usable_dates/taxa
        # already fetched above -- zero additional queries.
        seasonal_patterns = compute_seasonal_patterns(
            window_visits,
            taxa=taxa,
            usable_dates=usable_dates,
            local_timezone=local_timezone,
            reference_month=window_end_at.astimezone(local_timezone).month,
        )

        # Phase 6 + the day/night slice of Phase 10: the hour-band dimension
        # is free (reuses window_visits); the daylight dimension costs the
        # bounded, absence-safe solar resolution in `_daylight_bucket_by_
        # visit_id` above.
        daylight_by_visit_id = self._daylight_bucket_by_visit_id(
            session, window_visits, local_timezone=local_timezone, now=datetime.now(UTC),
        )
        temporal_patterns = compute_taxon_temporal_patterns(
            window_visits, daylight_by_visit_id=daylight_by_visit_id, local_timezone=local_timezone,
        )

        # Phase 11: one additional bounded query (Place-wide phenology
        # facts are always few) reusing the already-open session -- see
        # habitat_association.py's own docstring for why this is the
        # honest ceiling of what this milestone can build (no reviewed
        # before/after change-event model exists). Never touches a
        # per-Source phenology row (source_id is not None) -- this method's
        # own scope is Place-wide, matching `list_place_phenology_
        # observations`'s own default filter.
        phenology_rows = session.execute(
            select(
                PlacePhenologyObservationModel.subject_label,
                PlacePhenologyObservationModel.phenomenon,
                PlacePhenologyObservationModel.observed_start_date,
                PlacePhenologyObservationModel.observed_end_date,
            ).where(PlacePhenologyObservationModel.source_id.is_(None))
        ).all()
        phenology_observations = [
            PhenologyIntervalFact(
                subject_label=subject_label,
                phenomenon=phenomenon,
                observed_start_date=observed_start_date,
                observed_end_date=observed_end_date,
            )
            for subject_label, phenomenon, observed_start_date, observed_end_date in phenology_rows
        ]
        habitat_associations: dict[str, list[TaxonHabitatAssociation]] = {}
        if phenology_observations:
            for association in compute_habitat_associations(
                window_visits,
                taxa=taxa,
                usable_dates=usable_dates,
                local_timezone=local_timezone,
                phenology_observations=phenology_observations,
                window_end_at=window_end_at,
            ):
                habitat_associations.setdefault(association.taxon.label, []).append(association)

        # Environmental Context v2 (Phase 6): read-only over whatever
        # weather has already been cached via Today/Visit lookups -- never
        # a live provider call from inside report generation (see
        # docs/environmental-context-v2-contract.md "Phase 6/10" for why).
        # Skipped entirely (empty dict) when weather is not configured/
        # enabled, or nothing has been cached yet for this window -- a
        # coverage limitation this method's own docstring records as a
        # recorded future opportunity ("proactively backfill the report's
        # own comparison window"), not a silent bias: missing/disabled
        # weather data must never break core Place intelligence, mirroring
        # habitat association's identical coverage-safety discipline above.
        weather_associations: dict[str, list[TaxonWeatherAssociation]] = {}
        env_settings = session.get(EnvironmentalContextSettingsModel, 1)
        if (
            env_settings is not None
            and env_settings.weather_enabled
            and env_settings.coarse_latitude is not None
            and env_settings.coarse_longitude is not None
        ):
            weather_window_start = (
                window_end_at - timedelta(days=weather_provider.WEATHER_MAX_PAST_DAYS)
            ).date()
            # Upper-bounded at `window_end_at`'s own date too: `usable_dates`
            # below is already scoped to this report's own trailing window,
            # so a cached weather row from *after* window_end_at (e.g. a
            # historical report re-viewed after more recent Today lookups
            # cached newer dates) would be excluded from the association
            # result regardless via that intersection -- this bound is a
            # belt-and-suspenders query-efficiency tightening, not a
            # correctness fix on its own.
            weather_window_end = window_end_at.date()
            weather_rows = session.execute(
                select(
                    EnvironmentalContextRecordModel.metric,
                    EnvironmentalContextRecordModel.value_numeric,
                    EnvironmentalContextRecordModel.observed_at,
                    EnvironmentalContextRecordModel.for_date,
                ).where(
                    EnvironmentalContextRecordModel.source_id.is_(None),
                    EnvironmentalContextRecordModel.provider_key == weather_provider.WEATHER_PROVIDER_KEY,
                    EnvironmentalContextRecordModel.metric.in_(("air_temperature", "precipitation_amount")),
                    EnvironmentalContextRecordModel.basis_latitude == env_settings.coarse_latitude,
                    EnvironmentalContextRecordModel.basis_longitude == env_settings.coarse_longitude,
                    EnvironmentalContextRecordModel.for_date >= weather_window_start,
                    EnvironmentalContextRecordModel.for_date <= weather_window_end,
                )
            ).all()
            if weather_rows:
                weather_observations = tuple(
                    weather_provider.HourlyWeatherObservation(
                        metric=metric,
                        value_numeric=value_numeric if value_numeric is not None else 0.0,
                        unit="",
                        observed_at=_as_utc(observed_at),
                        for_date=for_date if for_date is not None else _as_utc(observed_at).date(),
                    )
                    for metric, value_numeric, observed_at, for_date in weather_rows
                )
                # Bucketed by `local_timezone` (not the storage layer's own
                # UTC `for_date`) -- this axis is intersected against
                # `usable_dates`/taxon presence dates below, which are
                # already local-day-bucketed by the rest of this reporting
                # pipeline (`presence_dates_by_taxon`); see
                # `condition_bands._bucket_date`'s own docstring for why a
                # UTC/local mismatch here would silently misalign whole
                # days for a Place far from UTC, not just round a few
                # boundary hours.
                temperature_hour_counts = condition_bands.daily_hour_counts(
                    weather_observations, metric="air_temperature", local_timezone=local_timezone,
                )
                temperature_usable_dates = condition_bands.usable_environmental_dates(
                    temperature_hour_counts
                )
                temperature_means = condition_bands.daily_mean(
                    weather_observations,
                    metric="air_temperature",
                    dates=temperature_usable_dates,
                    local_timezone=local_timezone,
                )
                temperature_baseline = condition_bands.compute_temperature_baseline(temperature_means)
                temperature_bands = {
                    day: band
                    for day, mean_c in temperature_means.items()
                    if (band := condition_bands.classify_temperature_day(mean_c, temperature_baseline))
                    is not None
                }

                precipitation_hour_counts = condition_bands.daily_hour_counts(
                    weather_observations, metric="precipitation_amount", local_timezone=local_timezone,
                )
                precipitation_usable_dates = condition_bands.usable_environmental_dates(
                    precipitation_hour_counts
                )
                precipitation_sums = condition_bands.daily_sum(
                    weather_observations,
                    metric="precipitation_amount",
                    dates=precipitation_usable_dates,
                    local_timezone=local_timezone,
                )
                precipitation_bands = {
                    day: condition_bands.classify_precipitation_day(total_mm)
                    for day, total_mm in precipitation_sums.items()
                }

                for association in compute_weather_associations(
                    window_visits,
                    taxa=taxa,
                    usable_dates=usable_dates,
                    local_timezone=local_timezone,
                    temperature_bands=temperature_bands,
                    precipitation_bands=precipitation_bands,
                ):
                    weather_associations.setdefault(association.taxon.label, []).append(association)

        return HistoricalPlaceIntelligence(
            baseline=baseline,
            species_historical_statuses=species_historical_statuses,
            change_summary=change_summary,
            taxon_place_patterns=taxon_place_patterns,
            regularity_narratives=regularity_narratives,
            seasonal_patterns=seasonal_patterns,
            temporal_patterns=temporal_patterns,
            habitat_associations=habitat_associations,
            weather_associations=weather_associations,
            taxa=taxa,
            all_time_first_confirmed_at=all_time_first_confirmed_at,
            all_time_last_confirmed_at=all_time_last_confirmed_at,
            usable_dates=usable_dates,
            window_visits=window_visits,
        )

    def list_likely_species_overview(self, *, limit: int = 20) -> LikelySpeciesOverviewResponse:
        """Bird Log's provisional counterpart to `wildlife_journal_overview`
        below: currently-unreviewed Visits grouped by their top-1 automatic
        species suggestion (`_dashboard_today_is_likely_species`, the same
        day-agnostic check `_dashboard_today_summary`'s own `likely_today`
        uses). Confirmed reviewed truth never appears here; it stays in the
        Wildlife Journal overview. Bounded to a most-recent slice, matching
        every other dashboard-style read in this class -- never a full
        table scan. Deliberately not pre-filtered on `species_guess`: that
        convenience field is only ever set by the automatic BioCLIP write
        path, while the grouping itself must recognize any current
        SpeciesSuggestion evidence, including one created through a
        different adapter or route."""

        bounded_limit = max(1, min(limit, 50))
        with self.session_factory() as session:
            rows = session.execute(
                select(VisitModel, EventModel, StreamModel, CameraSourceModel)
                .join(EventModel, VisitModel.event_id == EventModel.id)
                .join(StreamModel, EventModel.stream_id == StreamModel.id)
                .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                .where(
                    VisitModel.is_superseded.is_(False),
                    VisitModel.review_status == ReviewStatus.needs_review.value,
                    CameraSourceModel.status != SourceStatus.archived.value,
                )
                .order_by(EventModel.started_at.desc(), EventModel.id.desc(), VisitModel.id.desc())
                .limit(501)
            ).all()
            grouped: dict[str, list[DashboardVisitSummary]] = {}
            for visit, event, _stream, _source in rows[:500]:
                if not self._dashboard_today_is_nature_event(event.event_type):
                    continue
                summary = self._dashboard_visit_summary_from_models(session, visit, event)
                if not self._dashboard_today_is_likely_species(session, summary):
                    continue
                assert summary.suggested_label is not None
                grouped.setdefault(
                    self._normalize_label_from_session(session, summary.suggested_label), []
                ).append(summary)

            species = [
                self._dashboard_today_species(
                    session, label, summaries, distinct_days=1, is_confirmed=False,
                )
                for label, summaries in grouped.items()
            ]
            species.sort(key=lambda item: item.latest_visit.activity_started_at, reverse=True)
            return LikelySpeciesOverviewResponse(species=species[:bounded_limit])

    def wildlife_journal_overview(
        self,
        payload: WildlifeJournalOverviewRequest,
        *,
        now: datetime | None = None,
    ) -> WildlifeJournalOverviewResponse:
        """Return bounded label summaries from the same active reviewed truth as Insights."""

        local_now = (now or datetime.now().astimezone()).astimezone()
        local_timezone = local_now.tzinfo
        recent_end = local_now.date()
        recent_start = recent_end - timedelta(days=13)

        with self.session_factory() as session:
            # Historical Baseline Maturity + New/Regular Species v1 (see
            # docs/historical-baseline-maturity-contract.md): Place-wide
            # usable-day facts, anchored to "now" (unlike `place_activity_
            # report`'s own period-anchored window) -- Bird Log is a live
            # view, not a fixed past report, so "regular as of right now" is
            # the correct question here.
            stream_ids = list(
                session.scalars(
                    select(StreamModel.id)
                    .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                    .where(CameraSourceModel.status != SourceStatus.archived.value)
                ).all()
            )
            window_end_at = _as_utc(local_now)
            window_start_at = window_end_at - timedelta(days=HISTORICAL_BASELINE_WINDOW_DAYS)
            usable_dates, _has_history, _total_seconds = self._historical_usable_dates(
                session, stream_ids=stream_ids, window_end_at=window_end_at, local_timezone=local_timezone
            )
            # `baseline_maturity` itself now comes from the canonical call's
            # own `historical_baseline.maturity` below (identical formula,
            # same `usable_dates`) -- `usable_dates` is still needed here as
            # the defensive per-label fallback's own input.

            # Canonical New/Regular Species v1 (Everyday Discovery / Product
            # Experience v2; see docs/canonical-new-regular-species-contract.md):
            # this call also backs Gate C -- Meaningful Change Detection v1
            # (docs/meaningful-change-detection-contract.md), so each label
            # can also carry a `change_status` -- one bounded interval query
            # (not O(labels)/O(Visits)) plus a taxonomy index and two further
            # bounded queries. `species_historical_statuses` was previously
            # discarded here in favor of an independently-recomputed `is_
            # regular`/`distinct_confirmed_usable_days` below -- that was
            # exactly the kind of second, drift-prone computation the
            # canonical-semantics contract closes; it is now the source of
            # truth for both fields, with the old computation kept only as a
            # defensive fallback for a label this call's own Stream scope
            # cannot see (see the per-label loop below).
            #
            # `period_start_at` is deliberately *today's* local midnight, not
            # `window_start_at` (366 days back), even though this call also
            # anchors the regularity/baseline lookback at `window_end_at`:
            # `compute_species_historical_statuses`'s "new"/"first_record"
            # check fires whenever a taxon's all-time-first confirmation
            # falls inside `[period_start_at, period_end_at)`, and that
            # priority-1 check runs *before* the "regular" check -- passing
            # the full 366-day window here would wrongly keep every taxon
            # first confirmed at any point in the last year permanently
            # "new"/"first_record" and never "regular" until a full year had
            # elapsed. Today's own call (`_dashboard_today_summary`) already
            # narrows this to its own day boundaries for the identical
            # reason; Bird Log is a live view, so "today" (not a fixed report
            # period) is its equivalent narrow window. `period_start_at`/
            # `period_end_at` affect only this one check -- `change_summary`/
            # `taxon_place_patterns` below key off `window_end_at` alone.
            local_day_start_at = _as_utc(
                datetime.combine(local_now.date(), datetime.min.time(), local_timezone)
            )
            taxonomy_index = self._taxonomy_label_index(session)
            _historical_place_intelligence = self._historical_place_baseline_and_species_statuses(
                session,
                stream_ids=stream_ids,
                taxonomy_index=taxonomy_index,
                window_end_at=window_end_at,
                local_timezone=local_timezone,
                period_start_at=local_day_start_at,
                period_end_at=window_end_at,
            )
            species_historical_statuses = _historical_place_intelligence.species_historical_statuses
            change_summary = _historical_place_intelligence.change_summary
            baseline_maturity = _historical_place_intelligence.baseline.maturity
            change_status_by_label = {status.taxon.label: status for status in change_summary.taxa}

            records = self._wildlife_journal_confirmed_records(session)
            grouped: dict[str, list[dict[str, Any]]] = {}
            for record in records:
                grouped.setdefault(record["label"], []).append(record)

            summaries: list[WildlifeJournalLabelSummary] = []
            for label, label_records in grouped.items():
                ordered = self._wildlife_journal_ordered_records(label_records)
                daily_counts = Counter(
                    record["observed_at"].astimezone(local_timezone).date()
                    for record in ordered
                    if recent_start
                    <= record["observed_at"].astimezone(local_timezone).date()
                    <= recent_end
                )
                # Canonical New/Regular Species v1: source `distinct_
                # confirmed_usable_days`/`is_regular`/`historical_status`
                # from the exact same `SpeciesHistoricalStatus` Today's
                # digest uses (see the canonical call above), rather than an
                # independently-recomputed local count -- see docs/canonical-
                # new-regular-species-contract.md for why the two are no
                # longer allowed to drift. Falls back to the previous local
                # computation only in the defensive edge case where this
                # label's confirmed records fall entirely outside the
                # canonical call's own Stream scope (e.g. an archived
                # Stream) -- `species_historical_statuses` would then have no
                # entry for it at all, and a real confirmed label must never
                # silently vanish from Bird Log just because it can't be
                # canonically classified.
                canonical_status = species_historical_statuses.get(label)
                if canonical_status is not None:
                    distinct_confirmed_usable_days = canonical_status.distinct_confirmed_usable_days
                    is_regular = canonical_status.status == "regular"
                    historical_status: SpeciesHistoricalStatusValue | None = canonical_status.status
                else:
                    confirmed_dates_in_window = {
                        record["observed_at"].astimezone(local_timezone).date()
                        for record in ordered
                        if window_start_at <= record["observed_at"] < window_end_at
                    }
                    distinct_confirmed_usable_days = len(confirmed_dates_in_window & usable_dates)
                    is_regular = distinct_confirmed_usable_days >= MIN_DISTINCT_USABLE_DAYS_FOR_REGULAR
                    historical_status = None
                summaries.append(
                    WildlifeJournalLabelSummary(
                        label=label,
                        display_name=ordered[0]["display_name"],
                        observation_count=self._deduplicated_observation_count(session, ordered),
                        first_observed_at=ordered[0]["observed_at"],
                        latest_observed_at=ordered[-1]["observed_at"],
                        stream_count=len({record["summary"].stream_id for record in ordered}),
                        zone_count=len(
                            {
                                record["summary"].zone_id
                                for record in ordered
                                if record["summary"].zone_id is not None
                            }
                        ),
                        recent_activity=[
                            WildlifeJournalRecentDay(
                                local_date=recent_start + timedelta(days=offset),
                                count=daily_counts[recent_start + timedelta(days=offset)],
                            )
                            for offset in range(14)
                        ],
                        representative=self._wildlife_journal_representative(session, ordered),
                        distinct_confirmed_usable_days=distinct_confirmed_usable_days,
                        is_regular=is_regular,
                        historical_status=historical_status,
                        change_status=taxon_change_status_response(change_status_by_label.get(label)),
                    )
                )

            if payload.order == WildlifeJournalOrder.most_observed:
                summaries.sort(
                    key=lambda item: (
                        -item.observation_count,
                        -item.latest_observed_at.timestamp(),
                        item.display_name.lower(),
                        item.label,
                    )
                )
            elif payload.order == WildlifeJournalOrder.alphabetical:
                summaries.sort(key=lambda item: (item.display_name.lower(), item.label))
            elif payload.order == WildlifeJournalOrder.first_observed:
                summaries.sort(
                    key=lambda item: (
                        item.first_observed_at,
                        item.display_name.lower(),
                        item.label,
                    )
                )
            else:
                summaries.sort(
                    key=lambda item: (
                        item.latest_observed_at,
                        item.label,
                    ),
                    reverse=True,
                )
            return WildlifeJournalOverviewResponse(
                order=payload.order, labels=summaries[:100], baseline_maturity=baseline_maturity
            )

    def wildlife_journal_history(
        self,
        label: str,
        payload: WildlifeJournalHistoryRequest,
        *,
        now: datetime | None = None,
    ) -> WildlifeJournalHistoryResponse | None:
        """Read one validated wildlife label and a bounded page of its current history."""

        local_now = (now or datetime.now().astimezone()).astimezone()
        local_timezone = local_now.tzinfo
        start_date, end_date = self._wildlife_journal_date_range(payload, local_now)
        start_at = (
            _as_utc(datetime.combine(start_date, datetime.min.time(), local_timezone))
            if start_date is not None
            else None
        )
        end_at = (
            _as_utc(
                datetime.combine(
                    end_date + timedelta(days=1),
                    datetime.min.time(),
                    local_timezone,
                )
            )
            if end_date is not None
            else None
        )

        with self.session_factory() as session:
            taxonomy = self._taxonomy_label_model_for_input(session, label)
            # Everyday Product / Discovery UX Closure v1: this guard used to require
            # exactly `bird`, which 404'd the drill-down for a confirmed non-bird
            # wildlife taxon (squirrel, deer, ...) even after `_wildlife_journal_
            # confirmed_records` above was fixed to list it on the overview page --
            # match that same wildlife-denylist boundary here instead.
            if taxonomy is None or not is_wildlife_category(taxonomy.category):
                return None
            canonical_label = taxonomy.label
            all_label_records = [
                record
                for record in self._wildlife_journal_confirmed_records(session)
                if record["label"] == canonical_label
            ]

            # Historical Baseline Maturity + New/Regular Species v1 (see
            # docs/historical-baseline-maturity-contract.md) -- same
            # now-anchored usable-day facts `wildlife_journal_overview`
            # computes, reused here rather than re-derived, since this is an
            # independently-fetched detail view for one label.
            stream_ids = list(
                session.scalars(
                    select(StreamModel.id)
                    .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                    .where(CameraSourceModel.status != SourceStatus.archived.value)
                ).all()
            )
            history_window_end_at = _as_utc(local_now)
            history_window_start_at = history_window_end_at - timedelta(
                days=HISTORICAL_BASELINE_WINDOW_DAYS
            )
            usable_dates, _has_history, _total_seconds = self._historical_usable_dates(
                session,
                stream_ids=stream_ids,
                window_end_at=history_window_end_at,
                local_timezone=local_timezone,
            )

            # Canonical New/Regular Species v1 (Everyday Discovery / Product
            # Experience v2; see docs/canonical-new-regular-species-contract.md)
            # -- see the identical comment in `wildlife_journal_overview` for
            # why `period_start_at` is deliberately *today*, not the full
            # 366-day `history_window_start_at`, and why `species_historical_
            # statuses`/`historical_baseline.maturity` are now this label's
            # source of truth (with the previous local computation kept only
            # as a defensive fallback).
            local_day_start_at = _as_utc(
                datetime.combine(local_now.date(), datetime.min.time(), local_timezone)
            )
            taxonomy_index = self._taxonomy_label_index(session)
            historical_place_intelligence = self._historical_place_baseline_and_species_statuses(
                session,
                stream_ids=stream_ids,
                taxonomy_index=taxonomy_index,
                window_end_at=history_window_end_at,
                local_timezone=local_timezone,
                period_start_at=local_day_start_at,
                period_end_at=history_window_end_at,
            )
            species_historical_statuses = historical_place_intelligence.species_historical_statuses
            change_summary = historical_place_intelligence.change_summary
            baseline_maturity = historical_place_intelligence.baseline.maturity
            canonical_status = species_historical_statuses.get(canonical_label)
            if canonical_status is not None:
                distinct_confirmed_usable_days = canonical_status.distinct_confirmed_usable_days
                is_regular = canonical_status.status == "regular"
                historical_status: SpeciesHistoricalStatusValue | None = canonical_status.status
            else:
                confirmed_dates_in_window = {
                    record["observed_at"].astimezone(local_timezone).date()
                    for record in all_label_records
                    if history_window_start_at <= record["observed_at"] < history_window_end_at
                }
                distinct_confirmed_usable_days = len(confirmed_dates_in_window & usable_dates)
                is_regular = distinct_confirmed_usable_days >= MIN_DISTINCT_USABLE_DAYS_FOR_REGULAR
                historical_status = None
            change_status = next(
                (status for status in change_summary.taxa if status.taxon.label == canonical_label), None
            )
            records = [
                record
                for record in self._wildlife_journal_confirmed_records(
                    session,
                    start_at=start_at,
                    end_at=end_at,
                )
                if record["label"] == canonical_label
                and (payload.stream_id is None or record["summary"].stream_id == payload.stream_id)
                and (payload.zone_id is None or record["summary"].zone_id == payload.zone_id)
            ]
            if payload.favorites_only and records:
                favorite_visit_ids = set(
                    session.scalars(
                        select(VisitOrganizationModel.visit_id).where(
                            VisitOrganizationModel.visit_id.in_(
                                {record["summary"].id for record in records}
                            ),
                            VisitOrganizationModel.is_favorite.is_(True),
                        )
                    ).all()
                )
                records = [
                    record for record in records if record["summary"].id in favorite_visit_ids
                ]
            ordered = self._wildlife_journal_ordered_records(records)
            stream_breakdown = self._wildlife_journal_breakdown(ordered, grouping="stream")[:50]
            zone_breakdown = self._wildlife_journal_breakdown(ordered, grouping="zone")[:50]
            hour_counts = Counter(
                record["observed_at"].astimezone(local_timezone).hour for record in ordered
            )
            # Gate C -- Per-Species Zone + Time Pattern Intelligence v1: the
            # raw breakdown/hour-count facts above stay ungated (an honest
            # count is never overconfident), but "busiest"/"peak" are
            # superlative claims -- reuse the exact same reviewed-Visit floor
            # `compute_taxon_place_patterns` applies to its own `most_active_
            # zone`/`most_active_hour`, so Today and Bird Log never disagree
            # on how much reviewed history earns a "most active" statement.
            # "No Zone" is bucketed in zone_breakdown (see `_wildlife_journal_
            # breakdown`) but, like `PlaceActivityReport.busiest_zone`, can
            # never itself be crowned busiest.
            has_pattern_support = len(ordered) >= MIN_REVIEWED_VISITS_FOR_MOST_ACTIVE_PATTERN
            busiest_zone_entry = next(
                (entry for entry in zone_breakdown if entry.id != self._NO_ZONE_BREAKDOWN_ID),
                None,
            )
            tagged_visit_ids = set()
            if payload.tag_id is not None and records:
                tagged_visit_ids = set(
                    session.scalars(
                        select(VisitTagMembershipModel.visit_id)
                        .join(VisitTagModel, VisitTagModel.id == VisitTagMembershipModel.tag_id)
                        .where(
                            VisitTagMembershipModel.tag_id == payload.tag_id,
                            VisitTagModel.archived_at.is_(None),
                            VisitTagMembershipModel.visit_id.in_(
                                {record["summary"].id for record in records}
                            ),
                        )
                    ).all()
                )
            gallery_ordered = (
                [record for record in ordered if record["summary"].id in tagged_visit_ids]
                if payload.tag_id is not None
                else ordered
            )
            gallery_records = list(reversed(gallery_ordered))
            if payload.gallery_order == WildlifeJournalGalleryOrder.oldest:
                gallery_records = gallery_ordered
            page_records = gallery_records[payload.offset : payload.offset + payload.page_size + 1]
            has_more = len(page_records) > payload.page_size
            page_records = page_records[: payload.page_size]
            curation_visit_ids = set(
                session.scalars(
                    select(VisitCurationHistoryModel.visit_id).where(
                        VisitCurationHistoryModel.visit_id.in_(
                            {record["summary"].id for record in page_records}
                        )
                    )
                ).all()
            ) if page_records else set()
            revision_counts = Counter(
                session.execute(
                    select(ReviewLabelModel.target_id).where(
                        ReviewLabelModel.target_type == "visit",
                        ReviewLabelModel.target_id.in_(
                            {record["summary"].id for record in page_records}
                        ),
                    )
                ).scalars().all()
            ) if page_records else Counter()
            organization_by_visit_id = {
                model.visit_id: model
                for model in session.scalars(
                    select(VisitOrganizationModel).where(
                        VisitOrganizationModel.visit_id.in_(
                            {record["summary"].id for record in page_records}
                        )
                    )
                ).all()
            } if page_records else {}
            collection_counts = dict(
                session.execute(
                    select(
                        VisitCollectionMembershipModel.visit_id,
                        func.count(VisitCollectionMembershipModel.collection_id),
                    )
                    .join(
                        VisitCollectionModel,
                        VisitCollectionModel.id == VisitCollectionMembershipModel.collection_id,
                    )
                    .where(
                        VisitCollectionMembershipModel.visit_id.in_(
                            {record["summary"].id for record in page_records}
                        ),
                        VisitCollectionModel.archived_at.is_(None),
                    )
                    .group_by(VisitCollectionMembershipModel.visit_id)
                ).all()
            ) if page_records else {}
            tags_by_visit_id: dict[str, list[str]] = {}
            if page_records:
                tag_rows = session.execute(
                    select(VisitTagMembershipModel.visit_id, VisitTagModel.name)
                    .join(VisitTagModel, VisitTagModel.id == VisitTagMembershipModel.tag_id)
                    .where(
                        VisitTagMembershipModel.visit_id.in_(
                            {record["summary"].id for record in page_records}
                        ),
                        VisitTagModel.archived_at.is_(None),
                    )
                    .order_by(VisitTagModel.name.collate("NOCASE"), VisitTagModel.id)
                ).all()
                for visit_id, tag_name in tag_rows:
                    tags_by_visit_id.setdefault(visit_id, []).append(tag_name)
            all_ordered = self._wildlife_journal_ordered_records(all_label_records)
            first_on_stream: dict[str, str] = {}
            first_in_zone: dict[str, str] = {}
            for record in all_ordered:
                summary = record["summary"]
                first_on_stream.setdefault(summary.stream_id, summary.id)
                if summary.zone_id is not None:
                    first_in_zone.setdefault(summary.zone_id, summary.id)
            # Everyday Discovery / Product Experience v2 (Phase B; see docs/
            # multimodal-list-presentation-contract.md): collapse this page's
            # confidently-associated pairs into one row each, exactly as
            # Today's lists do -- see `_collapse_associated_multimodal_
            # journal_observations`'s own docstring. A pair may occasionally
            # straddle a page boundary, in which case only the visible side
            # collapses; this is the same accepted bound every other
            # pagination-vs-presentation tradeoff in this method already has.
            page_observations = [
                WildlifeJournalObservation(
                    visit_id=record["summary"].id,
                    event_id=record["summary"].event_id,
                    stream_id=record["summary"].stream_id,
                    stream_name=record["stream_name"],
                    source_name=record["source_name"],
                    zone_id=record["summary"].zone_id,
                    zone_name=record["summary"].zone_name,
                    observed_at=record["observed_at"],
                    activity_started_at=record["summary"].activity_started_at,
                    activity_ended_at=record["summary"].activity_ended_at,
                    duration_seconds=record["summary"].duration_seconds,
                    evidence_frame_count=record["summary"].evidence_frame_count,
                    reviewed_label=canonical_label,
                    display_name=record["display_name"],
                    primary_evidence=record["summary"].primary_evidence,
                    has_curation_history=record["summary"].id in curation_visit_ids,
                    has_review_revision=revision_counts[record["summary"].id] > 1,
                    is_first_on_stream=(
                        first_on_stream.get(record["summary"].stream_id)
                        == record["summary"].id
                    ),
                    is_first_in_zone=(
                        record["summary"].zone_id is not None
                        and first_in_zone.get(record["summary"].zone_id)
                        == record["summary"].id
                    ),
                    is_favorite=bool(
                        organization_by_visit_id.get(record["summary"].id)
                        and organization_by_visit_id[record["summary"].id].is_favorite
                    ),
                    has_note=bool(
                        organization_by_visit_id.get(record["summary"].id)
                        and organization_by_visit_id[record["summary"].id].note
                        and organization_by_visit_id[record["summary"].id].note.strip()
                    ),
                    collection_count=collection_counts.get(record["summary"].id, 0),
                    tags=tags_by_visit_id.get(record["summary"].id, [])[:MAX_TAGS_PER_VISIT],
                    evidence_modality=record["summary"].evidence_modality,
                )
                for record in page_records
            ]
            # Everyday Discovery / Product Experience v2 (Phase B; see docs/
            # multimodal-list-presentation-contract.md) then Camera / Source
            # + Multi-Camera Maturity v1, Phase I: collapse this page's
            # confidently-associated pairs into one row each, exactly as
            # Today's lists do -- see each collapse method's own docstring. A
            # pair may occasionally straddle a page boundary, in which case
            # only the visible side collapses; this is the same accepted
            # bound every other pagination-vs-presentation tradeoff in this
            # method already has.
            page_observations = self._collapse_associated_multimodal_journal_observations(
                session, page_observations,
            )
            page_observations = self._collapse_associated_cross_camera_journal_observations(
                session, page_observations,
            )
            gallery = WildlifeJournalGallery(
                order=payload.gallery_order,
                observations=page_observations,
                has_more=has_more,
                next_offset=(payload.offset + payload.page_size) if has_more else None,
            )
            display_name = _taxonomy_label_from_model(taxonomy).display_name
            first_record = ordered[0] if ordered else None
            latest_record = ordered[-1] if ordered else None
            first_all_record = all_ordered[0] if all_ordered else None
            # Biodiversity & Place Intelligence v1: the taxon's true
            # all-time latest observation, deliberately distinct from
            # `latest_record` above (which can be `None`, or an older
            # observation, whenever the caller's own date-range/Stream/
            # Zone filter excludes the most recent real sighting) -- see
            # "Taxon Place History" in docs/biodiversity-place-
            # intelligence-v1-contract.md. Composed into `place_context`
            # after this session closes (below); plain data captured here,
            # no live ORM object.
            latest_all_record = all_ordered[-1] if all_ordered else None
            is_new_label_in_range = bool(
                first_all_record is not None
                and start_date is not None
                and end_date is not None
                and start_date
                <= first_all_record["observed_at"].astimezone(local_timezone).date()
                <= end_date
            )
            response = WildlifeJournalHistoryResponse(
                label=canonical_label,
                display_name=display_name,
                scope=WildlifeJournalScope(
                    preset=payload.preset,
                    start_date=start_date,
                    end_date=end_date,
                    stream_id=payload.stream_id,
                    zone_id=payload.zone_id,
                    favorites_only=payload.favorites_only,
                    tag_id=payload.tag_id,
                    timezone_name=local_now.tzname() or "local time",
                ),
                observation_count=self._deduplicated_observation_count(session, ordered),
                first_observation=(
                    self._wildlife_journal_representative(session, [first_record])
                    if first_record is not None
                    else None
                ),
                latest_observation=(
                    self._wildlife_journal_representative(session, [latest_record])
                    if latest_record is not None
                    else None
                ),
                representative=self._wildlife_journal_representative(session, ordered),
                # Everyday Product / Discovery UX Closure v1: this was the one
                # ungated superlative claim of the three on this response --
                # busiest_zone/peak_activity_hour already apply the same
                # has_pattern_support floor above; a single confirmed Visit
                # should not crown its own Stream "busiest" any more than it
                # should crown a Zone or hour.
                busiest_stream=stream_breakdown[0] if stream_breakdown and has_pattern_support else None,
                busiest_zone=busiest_zone_entry if has_pattern_support else None,
                peak_activity_hour=(
                    max(hour_counts, key=lambda hour: (hour_counts[hour], -hour))
                    if hour_counts and has_pattern_support
                    else None
                ),
                stream_breakdown=stream_breakdown,
                zone_breakdown=zone_breakdown,
                activity_by_hour=[
                    WildlifeJournalHourBucket(hour=hour, count=hour_counts[hour])
                    for hour in range(24)
                ],
                is_new_label_in_range=is_new_label_in_range,
                distinct_confirmed_usable_days=distinct_confirmed_usable_days,
                is_regular=is_regular,
                baseline_maturity=baseline_maturity,
                historical_status=historical_status,
                change_status=taxon_change_status_response(change_status),
                regularity_narrative=_regularity_narrative_response(
                    historical_place_intelligence.regularity_narratives.get(canonical_label)
                ),
                seasonal_pattern=_seasonal_pattern_response(
                    historical_place_intelligence.seasonal_patterns.get(canonical_label)
                ),
                temporal_pattern=_temporal_pattern_response(
                    historical_place_intelligence.temporal_patterns.get(canonical_label)
                ),
                habitat_associations=[
                    _habitat_association_response(association)
                    for association in historical_place_intelligence.habitat_associations.get(
                        canonical_label, []
                    )
                ],
                weather_associations=[
                    _weather_association_response(association)
                    for association in historical_place_intelligence.weather_associations.get(
                        canonical_label, []
                    )
                ],
                activity_library_drilldown=WildlifeJournalDrilldown(
                    confirmed_label=canonical_label,
                    start_date=start_date,
                    end_date=end_date,
                    stream_id=payload.stream_id,
                    zone_id=payload.zone_id,
                ),
                gallery=gallery,
            )

        # Biodiversity & Place Intelligence v1: intentionally outside the
        # session above -- `_taxon_place_context` makes its own independent,
        # already-existing repository calls (`get_visit_environmental_
        # context`/`list_place_phenology_observations`), never nested
        # inside this method's own open session.
        if latest_all_record is not None:
            response = response.model_copy(
                update={
                    "place_context": self._taxon_place_context(
                        visit_id=latest_all_record["summary"].id,
                        observed_at=latest_all_record["observed_at"],
                    )
                }
            )
        return response

    def _taxon_place_context(self, *, visit_id: str, observed_at: datetime) -> TaxonPlaceContext:
        """One taxon's single most recent reviewed observation's habitat/
        environmental context -- see "Taxon Place History" in
        docs/biodiversity-place-intelligence-v1-contract.md. Two already-
        existing, independently-sessioned reads, never a new query shape;
        O(1) per taxon-history request (a single-taxon view), never
        O(gallery size)."""

        visit_context = self.get_visit_environmental_context(visit_id)
        # `visit_context is None` only means the Visit itself no longer
        # exists (see `get_visit_environmental_context`'s own docstring) --
        # not expected here since `visit_id` was just read from a real
        # confirmed record, but handled defensively rather than raising.
        environmental_context = (
            SolarContext(
                available=visit_context.available,
                reason=visit_context.reason,
                sunrise_at=visit_context.sunrise_at,
                sunset_at=visit_context.sunset_at,
                daylight_state=visit_context.daylight_state,
                provider_key=visit_context.provider_key,
                information_class=visit_context.information_class,
                basis_latitude=visit_context.basis_latitude,
                basis_longitude=visit_context.basis_longitude,
            )
            if visit_context is not None
            else SolarContext(available=False, reason=None)
        )
        phenology_context = [
            entry
            for entry in self.list_place_phenology_observations(as_of=observed_at.astimezone(UTC).date())
            if entry.status == "current"
        ]
        return TaxonPlaceContext(
            observed_at=observed_at,
            environmental_context=environmental_context,
            phenology_context=phenology_context,
        )

    def place_biodiversity_summary(
        self, *, now: datetime | None = None
    ) -> PlaceBiodiversitySummaryResponse:
        """A Place-wide, "as of right now" biodiversity summary -- see
        docs/biodiversity-place-intelligence-v1-contract.md. Mirrors
        `wildlife_journal_overview`'s exact session/anchoring convention (a
        live view, not a fixed report period, "regular"/"new" anchored to
        "now" and today's local midnight respectively) so a taxon's status
        here can never disagree with what Bird Log shows for it at the same
        moment. The three composed reads beyond the canonical call
        (`list_likely_species_overview`/`get_place_habitat_context`/
        `get_place_environmental_context_today`) run after this session
        closes -- each already independently sessioned, never nested."""

        local_now = (now or datetime.now().astimezone()).astimezone()
        local_timezone = local_now.tzinfo
        with self.session_factory() as session:
            stream_ids = list(
                session.scalars(
                    select(StreamModel.id)
                    .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                    .where(CameraSourceModel.status != SourceStatus.archived.value)
                ).all()
            )
            window_end_at = _as_utc(local_now)
            local_day_start_at = _as_utc(
                datetime.combine(local_now.date(), datetime.min.time(), local_timezone)
            )
            taxonomy_index = self._taxonomy_label_index(session)
            historical_place_intelligence = self._historical_place_baseline_and_species_statuses(
                session,
                stream_ids=stream_ids,
                taxonomy_index=taxonomy_index,
                window_end_at=window_end_at,
                local_timezone=local_timezone,
                period_start_at=local_day_start_at,
                period_end_at=window_end_at,
            )

        summary = compute_place_biodiversity_summary(
            historical_place_intelligence.species_historical_statuses.values(),
            historical_baseline=historical_place_intelligence.baseline,
            generated_at=window_end_at,
        )
        return place_biodiversity_summary_response(
            summary,
            provisional_taxa=self.list_likely_species_overview(limit=20).species,
            habitat_context=self.get_place_habitat_context(),
            environmental_context=self.get_place_environmental_context_today(),
        )

    def place_story(
        self,
        *,
        start_at: datetime | None = None,
        end_at: datetime | None = None,
        kinds: list[str] | None = None,
        taxon: str | None = None,
        feature_id: str | None = None,
        page_size: int = 30,
        offset: int = 0,
        now: datetime | None = None,
        local_timezone: tzinfo | None = None,
    ) -> PlaceStoryResponse:
        """Build one Place Story page -- a derived, read-only composition
        over already-authoritative facts (see docs/place-story-seasonal-
        timeline-v1-report.md). Every fact source below is read fresh from
        current rows on every call, exactly like `place_activity_report`/
        `get_place_feature_detail`; nothing here is cached or persisted, so
        a reviewed correction to any underlying fact is reflected on the
        very next call with no invalidation step (Phase 15 of the governing
        brief).

        Wildlife-derived events (`first_seen`/`return`/`regularity_change`/
        `noteworthy_activity`/`diversity_milestone`) are bounded to the same
        trailing `HISTORICAL_BASELINE_WINDOW_DAYS` (366-day) window every
        other regularity/baseline feature in this codebase already uses --
        a request spanning further back than that will still see every
        Reviewed Place Feature/phenology fact in range, but wildlife
        milestones older than that window are a recorded, bounded v1 gap
        (see the report's "Remaining major PRODUCT opportunities"), not a
        silent omission.
        """

        generation_moment = now or datetime.now(UTC)
        resolved_local_timezone = local_timezone or resolve_host_local_timezone(generation_moment)
        period_end_at = _as_utc(end_at) if end_at is not None else generation_moment
        period_start_at = (
            _as_utc(start_at)
            if start_at is not None
            else period_end_at - timedelta(days=PLACE_STORY_DEFAULT_LOOKBACK_DAYS)
        )
        wildlife_period_start_at = max(
            period_start_at, period_end_at - timedelta(days=HISTORICAL_BASELINE_WINDOW_DAYS)
        )

        with self.session_factory() as session:
            stream_ids = list(
                session.scalars(
                    select(StreamModel.id)
                    .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                    .where(CameraSourceModel.status != SourceStatus.archived.value)
                ).all()
            )
            taxonomy_index = self._taxonomy_label_index(session)
            intelligence = self._historical_place_baseline_and_species_statuses(
                session,
                stream_ids=stream_ids,
                taxonomy_index=taxonomy_index,
                window_end_at=period_end_at,
                local_timezone=resolved_local_timezone,
                period_start_at=wildlife_period_start_at,
                period_end_at=period_end_at,
            )

            wildlife_sources: list[list[PlaceStoryEvent]] = [
                compute_first_seen_events(
                    list(intelligence.species_historical_statuses.values()),
                    period_start_at=wildlife_period_start_at,
                    period_end_at=period_end_at,
                    local_timezone=resolved_local_timezone,
                ),
                compute_diversity_milestone_events(
                    intelligence.all_time_first_confirmed_at, intelligence.taxa,
                    local_timezone=resolved_local_timezone,
                ),
                detect_regularity_transition_events(
                    intelligence.window_visits,
                    taxa=intelligence.taxa,
                    all_time_first_confirmed_at=intelligence.all_time_first_confirmed_at,
                    all_time_last_confirmed_at=intelligence.all_time_last_confirmed_at,
                    usable_dates=intelligence.usable_dates,
                    local_timezone=resolved_local_timezone,
                    period_start_at=wildlife_period_start_at,
                    period_end_at=period_end_at,
                    baseline_window_days=HISTORICAL_BASELINE_WINDOW_DAYS,
                ),
                detect_overall_activity_events(
                    intelligence.window_visits,
                    usable_dates=intelligence.usable_dates,
                    local_timezone=resolved_local_timezone,
                    period_start_at=wildlife_period_start_at,
                    period_end_at=period_end_at,
                    baseline_window_days=HISTORICAL_BASELINE_WINDOW_DAYS,
                ),
            ]

            feature_events, comparison_events = self._place_story_feature_events(
                session,
                now=generation_moment,
                local_timezone=resolved_local_timezone,
                taxonomy_index=taxonomy_index,
            )
            phenology_events = self._place_story_phenology_events(session)

        kinds_set = set(kinds) if kinds else None
        period_start_date = period_start_at.astimezone(resolved_local_timezone).date()
        period_end_date = period_end_at.astimezone(resolved_local_timezone).date()
        page = build_place_story(
            [*wildlife_sources, feature_events, comparison_events, phenology_events],
            event_date_start=period_start_date,
            event_date_end=period_end_date,
            kinds=kinds_set,  # type: ignore[arg-type]
            taxon_label=taxon,
            feature_id=feature_id,
            offset=offset,
            page_size=page_size,
        )

        return PlaceStoryResponse(
            generated_at=generation_moment,
            period_start_at=period_start_at,
            period_end_at=period_end_at,
            entries=[_place_story_entry(event) for event in page.events],
            has_more=page.has_more,
            next_offset=page.next_offset,
            total_matched=page.total_matched,
            is_early_experience=intelligence.baseline.maturity == "insufficient",
        )

    def _place_story_feature_events(
        self,
        session: Session,
        *,
        now: datetime,
        local_timezone: tzinfo,
        taxonomy_index: dict[str, TaxonomyLabelModel],
    ) -> tuple[list[PlaceStoryEvent], list[PlaceStoryEvent]]:
        """Every Reviewed Place Feature change event, projected directly
        (Phase 7), plus a `comparison_insight` for every one whose
        before/after comparison has matured (Phase 8) -- reusing
        `_compute_feature_change_event_comparison` completely unmodified
        (the exact method `get_place_feature_detail` already uses), never a
        second before/after computation path. Every change event is
        fetched regardless of its own `effective_date` -- a mature
        comparison's own `comparison_insight` event can be dated *later*
        than its parent change event (see `comparison_insight_event`'s
        docstring), so pre-filtering by date here could silently drop a
        still-relevant insight; the final `build_place_story` call is what
        actually scopes both resulting event streams to the caller's
        requested period, independently, by each event's own `event_date`.
        """

        feature_models = {model.id: model for model in session.scalars(select(PlaceFeatureModel)).all()}
        event_models = session.scalars(
            select(PlaceFeatureChangeEventModel).order_by(PlaceFeatureChangeEventModel.effective_date.desc())
        ).all()

        feature_events: list[PlaceStoryEvent] = []
        comparison_events: list[PlaceStoryEvent] = []
        stream_ids_by_feature: dict[str, list[str]] = {}
        for event_model in event_models:
            feature_model = feature_models.get(event_model.feature_id) if event_model.feature_id else None
            feature_name = feature_model.name if feature_model is not None else "This Place"
            feature_events.append(
                feature_change_event_to_story_event(
                    change_event_id=event_model.id,
                    feature_id=event_model.feature_id,
                    feature_name=feature_name,
                    event_type=event_model.event_type,
                    effective_date=event_model.effective_date,
                    note=event_model.note,
                    prior_value=event_model.prior_value,
                    new_value=event_model.new_value,
                    zone_id=feature_model.zone_id if feature_model is not None else None,
                    source_id=feature_model.source_id if feature_model is not None else None,
                )
            )

            if feature_model is None:
                continue  # a Place-level change event has no Feature monitoring scope to compare against
            if feature_model.id not in stream_ids_by_feature:
                stream_ids_by_feature[feature_model.id] = self._feature_monitoring_stream_ids(
                    session, feature_model
                )
            stream_ids = stream_ids_by_feature[feature_model.id]
            if not stream_ids:
                continue
            comparison = self._compute_feature_change_event_comparison(
                session, feature_model, stream_ids, event_model,
                now=now, local_timezone=local_timezone, taxonomy_index=taxonomy_index,
            )
            if comparison.maturity not in ("early_signal", "comparable"):
                continue
            association = comparison.association
            if association is None or association.status not in (
                "more_common_under_condition", "less_common_under_condition",
            ):
                continue
            assert comparison.window_days is not None and comparison.post_end is not None
            comparison_events.append(
                comparison_insight_event(
                    change_event_id=event_model.id,
                    feature_id=feature_model.id,
                    feature_name=feature_model.name,
                    event_type=event_model.event_type,
                    maturity=comparison.maturity,
                    window_days=comparison.window_days,
                    post_end=comparison.post_end,
                    association_status=association.status,
                    # Environmental-context caveat composition onto this
                    # comparison is a deliberately bounded v1 gap -- see
                    # the report's "Remaining major PRODUCT opportunities."
                    # Never fabricated; simply omitted when not computed.
                    weather_caveat=None,
                )
            )
        return feature_events, comparison_events

    def _place_story_phenology_events(self, session: Session) -> list[PlaceStoryEvent]:
        """Every Reviewed, Place-wide phenology observation, projected
        directly (Phase 10) -- mirrors `list_place_phenology_observations`'s
        own `source_id.is_(None)` Place-wide scope."""

        models = session.scalars(
            select(PlacePhenologyObservationModel).where(PlacePhenologyObservationModel.source_id.is_(None))
        ).all()
        return [
            phenology_observation_to_story_event(
                observation_id=model.id,
                subject_label=model.subject_label,
                phenomenon=model.phenomenon,
                observed_start_date=model.observed_start_date,
                observed_end_date=model.observed_end_date,
                note=model.note,
            )
            for model in models
        ]

    @staticmethod
    def _wildlife_journal_date_range(
        payload: WildlifeJournalHistoryRequest,
        local_now: datetime,
    ) -> tuple[date | None, date | None]:
        if payload.preset == WildlifeJournalRangePreset.all_time:
            return None, None
        if payload.preset == WildlifeJournalRangePreset.today:
            return local_now.date(), local_now.date()
        if payload.preset == WildlifeJournalRangePreset.last_7_days:
            return local_now.date() - timedelta(days=6), local_now.date()
        if payload.preset == WildlifeJournalRangePreset.last_30_days:
            return local_now.date() - timedelta(days=29), local_now.date()
        if payload.preset == WildlifeJournalRangePreset.this_year:
            return date(local_now.year, 1, 1), local_now.date()
        assert payload.start_date is not None and payload.end_date is not None
        return payload.start_date, payload.end_date

    def _wildlife_journal_confirmed_records(
        self,
        session: Session,
        *,
        start_at: datetime | None = None,
        end_at: datetime | None = None,
    ) -> list[dict[str, Any]]:
        # This single resolver keeps Journal, Insights, and Activity Library on the
        # existing latest-review, active-Visit truth boundary.
        #
        # Everyday Product / Discovery UX Closure v1: `VisitReviewOutcome.
        # confirmed_bird` is deliberately bird-only (see `_visit_review_outcome`),
        # but this resolver's own contract is "confirmed wildlife" -- MockingBird
        # is "bird-first but wildlife-native" (product-doctrine.md). A confirmed
        # non-bird wildlife taxon (squirrel, deer, ...) resolves to the coarser
        # `non_bird` outcome, which also contains non-wildlife categories (pet/
        # person/vehicle) -- re-resolve the actual taxonomy category for that
        # narrower bucket via the same canonical resolver `_visit_review_outcome`
        # itself used, so a real confirmed wildlife encounter is never silently
        # invisible here just because it isn't a bird.
        records: list[dict[str, Any]] = []
        for record in self._wildlife_insight_records(session, start_at=start_at, end_at=end_at):
            summary = record["summary"]
            if summary.review_outcome == VisitReviewOutcome.confirmed_bird:
                records.append(record)
            elif summary.review_outcome == VisitReviewOutcome.non_bird and summary.reviewed_label:
                taxonomy = self._taxonomy_label_model_for_input(session, summary.reviewed_label)
                if taxonomy is not None and is_wildlife_category(taxonomy.category):
                    records.append(record)
        return records

    @staticmethod
    def _wildlife_journal_ordered_records(
        records: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        return sorted(
            records,
            key=lambda record: (record["observed_at"], record["summary"].id),
        )

    def _representative_evidence_candidate(
        self,
        session: Session,
        summary: StreamVisitSummary,
    ) -> EvidenceCandidateFact | None:
        """One Visit's contribution to representative-evidence ranking, or
        `None` when this Visit has nothing safe to offer -- see "Evidence
        contract" and "No-image semantics" in docs/representative-species-
        evidence-contract.md. Reuses `summary.primary_evidence` verbatim
        (the same already-resolved, already-Visit-scoped pick the Evidence
        Gallery/Bird Log/Wildlife Insights all already use, see docs/
        multi-subject-visit-assembly-review-v1.md for why this can never
        cross into a sibling Visit's own evidence) rather than re-deriving
        which frame is primary. `session.get` is a same-session identity-map
        lookup here, not a new query: `summary.primary_evidence` was already
        resolved from this exact `MediaAssetModel` row earlier in the same
        request (see "Backend architecture" in the contract doc).
        """

        frame = summary.primary_evidence
        if frame is None:
            return None
        asset = session.get(MediaAssetModel, frame.media_asset_id)
        if asset is None or not Path(asset.local_path).is_file():
            # Deleted/missing media since this frame was linked: this Visit
            # honestly contributes no candidate rather than pointing a
            # report at a broken image (regression: missing/deleted media
            # gracefully yields no representative).
            return None
        subject_box = frame.normalized_track_box or frame.normalized_crop_box
        subject_width: int | None = None
        subject_height: int | None = None
        if subject_box is not None and frame.width and frame.height:
            left, top, right, bottom = subject_box
            subject_width = round((right - left) * frame.width)
            subject_height = round((bottom - top) * frame.height)
        return EvidenceCandidateFact(
            visit_id=summary.id,
            media_asset_id=frame.media_asset_id,
            captured_at=frame.captured_at,
            is_native_resolution=frame.resolution_provenance == "synchronized",
            has_subject_region=subject_width is not None and subject_height is not None,
            subject_pixel_area=(subject_width or 0) * (subject_height or 0),
            asset_pixel_area=(frame.width or 0) * (frame.height or 0),
        )

    def _representative_evidence_response(
        self,
        session: Session,
        summaries: Sequence[StreamVisitSummary],
    ) -> RepresentativeEvidence | None:
        """The one canonical per-taxon representative-evidence selector --
        reused, unmodified, by both `place_activity_report` (Today) and
        `wildlife_journal_overview` (Bird Log); see "Backend architecture"
        in docs/representative-species-evidence-contract.md. `summaries`
        must already be truth-filtered to exactly the confirmed Visits
        eligible to represent one taxon -- this method resolves no truth of
        its own. Bounded to the most recent `MAX_REPRESENTATIVE_EVIDENCE_
        CANDIDATES` summaries so an unbounded reviewed history (Bird Log has
        no period limit) cannot make this an unbounded scan.
        """

        bounded = (
            summaries[-MAX_REPRESENTATIVE_EVIDENCE_CANDIDATES:]
            if len(summaries) > MAX_REPRESENTATIVE_EVIDENCE_CANDIDATES
            else summaries
        )
        candidates: list[EvidenceCandidateFact] = []
        frame_by_visit_id: dict[str, VisitEvidenceFrame] = {}
        for summary in bounded:
            candidate = self._representative_evidence_candidate(session, summary)
            if candidate is None:
                continue
            candidates.append(candidate)
            assert summary.primary_evidence is not None  # implied by candidate is not None
            frame_by_visit_id[summary.id] = summary.primary_evidence
        winner = select_representative_evidence(candidates)
        if winner is None:
            return None
        return RepresentativeEvidence(
            visit_id=winner.visit_id,
            evidence=frame_by_visit_id[winner.visit_id],
        )

    def _wildlife_journal_representative(
        self,
        session: Session,
        records: list[dict[str, Any]],
    ) -> WildlifeJournalRepresentative | None:
        if not records:
            return None
        ordered = self._wildlife_journal_ordered_records(records)
        # Gate C -- Representative Species Evidence v1: delegates the actual
        # "which Visit's evidence wins" decision to the same canonical
        # selector Today uses, so Bird Log never independently picks a
        # "prettier" image -- see "Time scope" in docs/representative-
        # species-evidence-contract.md.
        representative_evidence = self._representative_evidence_response(
            session, [record["summary"] for record in ordered]
        )
        if representative_evidence is not None:
            selected = next(
                record for record in ordered if record["summary"].id == representative_evidence.visit_id
            )
            primary_evidence = representative_evidence.evidence
        else:
            # No recent confirmed Visit for this label has safe, present
            # evidence -- keep the latest reviewed observation visible even
            # without media, exactly as before this milestone.
            selected = ordered[-1]
            primary_evidence = None
        summary: StreamVisitSummary = selected["summary"]
        return WildlifeJournalRepresentative(
            visit_id=summary.id,
            event_id=summary.event_id,
            stream_id=summary.stream_id,
            stream_name=selected["stream_name"],
            source_name=selected["source_name"],
            zone_id=summary.zone_id,
            zone_name=summary.zone_name,
            label=selected["label"],
            display_name=selected["display_name"],
            observed_at=selected["observed_at"],
            primary_evidence=primary_evidence,
        )

    # Gate C -- Per-Species Zone + Time Pattern Intelligence v1: a Visit
    # outside every configured Zone must not be silently dropped from
    # `zone_breakdown` (see "Partial-Zone semantics" in
    # docs/place-activity-report-contract.md) -- it is bucketed under the
    # exact same "No Zone" wording `place_activity_report.py` already
    # established (`NO_ZONE_LABEL`), so Today and Bird Log describe the
    # same concept with the same words. This sentinel id can never collide
    # with a real `ZoneModel.id` (a normal id-prefixed identifier), and is
    # never shown to a user -- `WildlifeJournalBreakdown.id` only ever
    # backs a React list key on the frontend.
    _NO_ZONE_BREAKDOWN_ID = "no-zone"

    @staticmethod
    def _wildlife_journal_breakdown(
        records: list[dict[str, Any]],
        *,
        grouping: str,
    ) -> list[WildlifeJournalBreakdown]:
        grouped: dict[str, tuple[str, int]] = {}
        for record in records:
            summary: StreamVisitSummary = record["summary"]
            if grouping == "stream":
                key, name = summary.stream_id, record["stream_name"]
            elif summary.zone_id is None:
                key, name = ProductRepository._NO_ZONE_BREAKDOWN_ID, NO_ZONE_LABEL
            else:
                key, name = summary.zone_id, summary.zone_name or "Current Zone unavailable"
            existing = grouped.get(key)
            grouped[key] = (name, (existing[1] if existing is not None else 0) + 1)
        return sorted(
            [
                WildlifeJournalBreakdown(id=key, name=name, count=count)
                for key, (name, count) in grouped.items()
            ],
            key=lambda item: (-item.count, item.name.lower(), item.id),
        )

    def dataset_coverage_summary(self) -> DatasetCoverageSummary:
        with self.session_factory() as session:
            return self._dataset_coverage_summary(session)

    def dataset_quality_summary(self) -> DatasetQualitySummary:
        with self.session_factory() as session:
            return self._dataset_quality_summary(session)

    def classifier_readiness_report(self) -> ClassifierReadinessReport:
        with self.session_factory() as session:
            return self._classifier_readiness_report(session)

    def build_classifier_training_manifest(self) -> ClassifierTrainingManifestResponse:
        with self.session_factory() as session:
            return self._classifier_training_manifest(session)

    def create_classifier_manifest_export(
        self,
        payload: ClassifierManifestFileExportRequest,
    ) -> ClassifierManifestFileExportResponse:
        with self.session_factory() as session:
            manifest = self._classifier_training_manifest(session)

        return self._write_classifier_manifest_export(payload, manifest)

    def visit_is_dataset_ready(self, visit: Visit) -> bool:
        with self.session_factory() as session:
            return self._visit_is_dataset_ready(session, visit)

    def event_is_dataset_ready(self, event: Event) -> bool:
        with self.session_factory() as session:
            return self._event_is_dataset_ready(session, event)

    def review_summary_for_dataset_state(self, dataset_ready: bool) -> str:
        if dataset_ready:
            return "Ready for local dataset export. Corrected label will be used as local dataset truth."

        return "Needs review before export. Detections are evidence, not final truth."

    def dataset_export_detail(self, export_id: str) -> DatasetExportDetail | None:
        dataset_export = self.get_dataset_export(export_id)
        manifest = self.build_dataset_manifest(export_id)
        if dataset_export is None or manifest is None:
            return None
        return DatasetExportDetail(export=dataset_export, manifest=manifest)

    # -------------------------------------------------------------------
    # Research / Conservation / Export Interoperability v1 (see docs/
    # research-conservation-export-contract.md). Read-only except for the
    # explicit, bounded collection-management writes and the export file
    # writers below; none of this ever creates or mutates Visit/Event/
    # ReviewLabel/SpeciesSuggestion truth. Reuses the same canonical
    # resolvers (`_stream_visit_summary_from_models`, `_visit_is_dataset_
    # ready`, `_taxonomy_label_model_for_input`, `_place_activity_coverage_
    # summary`) every other reporting surface already relies on -- this
    # section never re-derives truth or coverage independently.
    # -------------------------------------------------------------------

    def _research_observation_for_visit(
        self,
        session: Session,
        visit: VisitModel,
        event: EventModel,
        *,
        taxonomy_index: dict[str, TaxonomyLabelModel] | None = None,
    ) -> ResearchObservation:
        """Build one provider-neutral `ResearchObservation` from a Visit,
        including its full `ResearchExportEligibility` verdict. Always
        returns a record -- even an ineligible one -- so a caller can report
        *why* a record was excluded (see "Research-safe eligibility" in the
        governing milestone brief); callers that only want trusted rows
        filter on `.eligibility.eligible` themselves."""

        summary = self._stream_visit_summary_from_models(session, visit, event, taxonomy_index=taxonomy_index)
        stream_model = session.get(StreamModel, event.stream_id)
        source_model = (
            session.get(CameraSourceModel, stream_model.source_id) if stream_model is not None else None
        )

        reviewed_taxonomy = (
            self._taxonomy_label_model_for_input(session, summary.reviewed_label, taxonomy_index=taxonomy_index)
            if summary.reviewed_label
            else None
        )
        # Reuses the exact same defense-in-depth "authoritative, current,
        # not superseded" re-check `_visit_is_dataset_ready` already
        # established for reviewed-only Dataset Export, rather than a second
        # independent truth check -- see docs/review-decision-provenance-
        # contract.md.
        is_dataset_ready = self._visit_is_dataset_ready(session, _visit_from_model(visit))
        effective_label = self._current_effective_review_label_model_for_visit(session, visit.id)

        primary_evidence_asset = (
            session.get(MediaAssetModel, summary.primary_evidence.media_asset_id)
            if summary.primary_evidence is not None
            else None
        )
        # `MediaAssetModel.captured_at` (not `VisitEvidenceFrame.captured_at`,
        # which always carries a fallback value) is `None` precisely when the
        # underlying frame's real capture time was unknown -- see "Frame-time
        # semantics" in docs/offline-recorded-media-observation-contract.md.
        capture_timestamp_known = (
            primary_evidence_asset is not None and primary_evidence_asset.captured_at is not None
        )

        candidate_ledger = session.scalars(
            select(ObservationCandidateVisitModel).where(ObservationCandidateVisitModel.visit_id == visit.id)
        ).first()
        provider_key = candidate_ledger.provider_key if candidate_ledger is not None else None
        acquisition_type = _research_acquisition_type_for_provider_key(provider_key)
        is_offline = acquisition_type in ("recorded_video", "still_image")

        suggestion = session.scalars(
            select(SpeciesSuggestionModel)
            .where(SpeciesSuggestionModel.visit_id == visit.id)
            .order_by(
                SpeciesSuggestionModel.created_at.desc(),
                SpeciesSuggestionModel.rank,
                SpeciesSuggestionModel.id.desc(),
            )
        ).first()
        suggested_taxonomy = (
            self._taxonomy_label_model_for_input(session, suggestion.suggested_label, taxonomy_index=taxonomy_index)
            if suggestion is not None
            else None
        )

        evidence_frames = self._visit_evidence_frames_from_visit(session, visit, event)
        evidence_records: list[ResearchEvidenceRecord] = []
        for frame in evidence_frames:
            asset = session.get(MediaAssetModel, frame.media_asset_id)
            evidence_records.append(
                ResearchEvidenceRecord(
                    media_id=frame.media_asset_id,
                    evidence_role=frame.evidence_role,
                    captured_at=frame.captured_at,
                    width=frame.width,
                    height=frame.height,
                    content_type=frame.content_type,
                    resolution_provenance=frame.resolution_provenance,
                    is_crop=frame.normalized_crop_box is not None,
                    content_sha256=asset.content_sha256 if asset is not None else None,
                )
            )

        # Defense-in-depth, not the primary enforcement (see docs/privacy-
        # ignore-zone-contract.md): a Visit triggered *directly* inside a
        # Privacy/Ignore Zone is already refused at candidate-creation time
        # (`blocked_privacy_zone`), so this branch exists for the one real
        # remaining case -- a Zone later *reclassified* to privacy/ignore
        # after a Visit already existed under it. Respect that current
        # intent at export time even though the Visit's own creation
        # predates it; this never redacts pixels, only withholds export.
        is_privacy_restricted = summary.zone_type in (ZoneType.privacy, ZoneType.ignore)

        eligibility = evaluate_research_export_eligibility(
            review_status=summary.review_status.value,
            is_authoritative_review=is_dataset_ready,
            is_structurally_superseded=visit.is_superseded,
            taxon_category=reviewed_taxonomy.category if reviewed_taxonomy is not None else None,
            has_scientific_name=bool(reviewed_taxonomy.scientific_name) if reviewed_taxonomy is not None else False,
            has_suggestion=summary.has_suggestion,
            capture_timestamp_known=capture_timestamp_known,
            has_evidence_media=summary.evidence_frame_count > 0,
            resolution_provenance_known=(
                summary.primary_evidence is not None and summary.primary_evidence.resolution_provenance is not None
            ),
            is_privacy_restricted=is_privacy_restricted,
        )

        return ResearchObservation(
            observation_id=visit.id,
            event_id=event.id,
            source_id=source_model.id if source_model is not None else event.stream_id,
            source_name=source_model.name if source_model is not None else "",
            stream_id=event.stream_id,
            stream_name=stream_model.name if stream_model is not None else "",
            acquisition_type=acquisition_type,
            acquisition_provider=provider_key,
            is_offline_acquisition=is_offline,
            captured_at=summary.activity_started_at,
            captured_at_end=summary.activity_ended_at,
            capture_timestamp_confidence="recorded" if capture_timestamp_known else "unknown",
            review_status=summary.review_status.value,
            reviewed_at=_as_utc(effective_label.created_at) if effective_label is not None else None,
            reviewed_by=effective_label.reviewer_identity if effective_label is not None else None,
            classification=eligibility.classification,
            taxon_label=reviewed_taxonomy.label if reviewed_taxonomy is not None else None,
            taxon_display_name=reviewed_taxonomy.display_name if reviewed_taxonomy is not None else None,
            taxon_scientific_name=reviewed_taxonomy.scientific_name if reviewed_taxonomy is not None else None,
            taxon_category=reviewed_taxonomy.category if reviewed_taxonomy is not None else None,
            is_species=reviewed_taxonomy.is_species if reviewed_taxonomy is not None else None,
            zone_id=summary.zone_id,
            zone_name=summary.zone_name,
            zone_type=summary.zone_type.value if summary.zone_type is not None else None,
            resolution_provenance=(
                summary.primary_evidence.resolution_provenance if summary.primary_evidence is not None else None
            ),
            evidence=tuple(evidence_records),
            eligibility=eligibility,
            evidence_modality="acoustic" if event.event_type == "acoustic_observation_candidate" else "visual",
            multimodal_association=self._strongest_multimodal_tier(session, visit.id),
            suggested_taxon_label=(
                suggested_taxonomy.label if suggested_taxonomy is not None
                else (suggestion.suggested_label if suggestion is not None else None)
            ),
            suggested_taxon_display_name=suggested_taxonomy.display_name if suggested_taxonomy is not None else None,
            suggested_taxon_scientific_name=(
                suggested_taxonomy.scientific_name if suggested_taxonomy is not None
                else (suggestion.suggested_scientific_name if suggestion is not None else None)
            ),
            suggested_by=suggestion.adapter_name if suggestion is not None else None,
            suggested_confidence=suggestion.confidence if suggestion is not None else None,
            suggested_at=_as_utc(suggestion.created_at) if suggestion is not None else None,
        )

    def _research_scope_stream_ids(
        self, session: Session, filters: ResearchExportFilters,
    ) -> list[str] | None:
        """`None` means "every configured Stream" -- an explicit, distinct
        state from an empty list (which would mean "no Stream at all")."""

        if filters.stream_ids is not None:
            return list(filters.stream_ids)
        if filters.source_ids is not None:
            return list(
                session.scalars(
                    select(StreamModel.id).where(StreamModel.source_id.in_(filters.source_ids))
                ).all()
            )
        return None

    def _research_collection_visit_ids(self, session: Session, collection_id: str) -> list[str]:
        collection = session.get(ResearchCollectionModel, collection_id)
        if collection is None:
            raise ValueError("missing_research_collection")
        return list(json.loads(collection.visit_ids_json))

    def _research_observations_for_scope(
        self,
        session: Session,
        *,
        filters: ResearchExportFilters,
        taxonomy_index: dict[str, TaxonomyLabelModel] | None = None,
    ) -> list[ResearchObservation]:
        """Every Visit in scope, each resolved to a `ResearchObservation`
        (including ineligible ones -- see `_research_observation_for_visit`).
        Never filters on eligibility itself; callers decide what to do with
        an ineligible record (exclude it from a trusted table, or count it
        toward a skip-reasons summary)."""

        stream_ids = self._research_scope_stream_ids(session, filters)
        query = (
            select(VisitModel, EventModel)
            .join(EventModel, VisitModel.event_id == EventModel.id)
            .where(VisitModel.is_superseded.is_(False))
        )
        if stream_ids is not None:
            query = query.where(EventModel.stream_id.in_(stream_ids))
        start_at = _as_utc(filters.start_at) if filters.start_at is not None else None
        end_at = _as_utc(filters.end_at) if filters.end_at is not None else None
        if start_at is not None:
            query = query.where(EventModel.started_at >= start_at)
        if end_at is not None:
            query = query.where(EventModel.started_at < end_at)
        if filters.collection_id is not None:
            collection_visit_ids = self._research_collection_visit_ids(session, filters.collection_id)
            query = query.where(VisitModel.id.in_(collection_visit_ids))

        rows = session.execute(
            query.order_by(EventModel.started_at, EventModel.id, VisitModel.id)
        ).all()

        observations = [
            self._research_observation_for_visit(session, visit, event, taxonomy_index=taxonomy_index)
            for visit, event in rows
        ]

        if filters.taxon_labels is not None:
            allowed = set(filters.taxon_labels)
            observations = [obs for obs in observations if obs.taxon_label in allowed]
        if filters.acquisition_scope != "both":
            want_offline = filters.acquisition_scope == "offline"
            observations = [obs for obs in observations if obs.is_offline_acquisition == want_offline]

        return observations

    def _offline_acquisition_effort_for_scope(
        self,
        session: Session,
        *,
        stream_ids: list[str] | None,
        start_at: datetime | None,
        end_at: datetime | None,
    ) -> OfflineAcquisitionEffort:
        """Live monitoring effort and offline acquisition effort are always
        computed from two independent sources (see "Effort accounting" in
        the governing milestone brief): this method never touches
        `MonitoringExposureIntervalModel`."""

        video_query = select(RecordedMediaAnalysisRunModel).where(
            RecordedMediaAnalysisRunModel.status == "completed"
        )
        if stream_ids is not None:
            video_query = video_query.where(RecordedMediaAnalysisRunModel.stream_id.in_(stream_ids))
        if start_at is not None:
            video_query = video_query.where(RecordedMediaAnalysisRunModel.completed_at >= start_at)
        if end_at is not None:
            video_query = video_query.where(RecordedMediaAnalysisRunModel.completed_at < end_at)
        runs = session.scalars(video_query.order_by(RecordedMediaAnalysisRunModel.completed_at.asc())).all()

        # Keep only the latest completed run per distinct MediaAsset -- never
        # double-count a reprocessing attempt (see `RecordedVideoAcquisition
        # Fact`'s own dedup contract in mockingbird.research.acquisition_
        # effort).
        latest_by_asset: dict[str, RecordedMediaAnalysisRunModel] = {}
        for run in runs:
            latest_by_asset[run.media_asset_id] = run

        video_facts = [
            RecordedVideoAcquisitionFact(
                media_asset_id=run.media_asset_id,
                stream_id=run.stream_id,
                source_duration_seconds=run.source_duration_seconds,
                frames_analyzed=run.frames_analyzed,
                completed_at=_as_utc(run.completed_at or run.created_at),
            )
            for run in latest_by_asset.values()
        ]

        image_query = select(MediaAssetModel).where(MediaAssetModel.media_type == "image")
        if stream_ids is not None:
            image_query = image_query.where(MediaAssetModel.stream_id.in_(stream_ids))
        if start_at is not None:
            image_query = image_query.where(MediaAssetModel.created_at >= start_at)
        if end_at is not None:
            image_query = image_query.where(MediaAssetModel.created_at < end_at)
        # A still image counts toward offline acquisition effort only when it
        # is itself the folder-imported source file (identified the same way
        # `_folder_import_duplicate_exists` already does) -- never a
        # machine-created candidate evidence crop, which would double-count
        # against the very Visit the effort figure is meant to contextualize.
        still_facts = [
            StillImageAcquisitionFact(
                media_asset_id=asset.id,
                stream_id=asset.stream_id,
                captured_at=_as_utc(asset.captured_at) if asset.captured_at is not None else None,
            )
            for asset in session.scalars(image_query).all()
            if _folder_import_note_fields(asset.notes).get("provider_key") == "folder_import_future"
        ]

        # Acoustic / BirdNET Observation Foundation v1: the audio analog of
        # the recorded-video query above -- same "latest completed run per
        # distinct MediaAsset, never double-count a reprocessing attempt"
        # dedup discipline.
        audio_query = select(AcousticAnalysisRunModel).where(
            AcousticAnalysisRunModel.status == "completed"
        )
        if stream_ids is not None:
            audio_query = audio_query.where(AcousticAnalysisRunModel.stream_id.in_(stream_ids))
        if start_at is not None:
            audio_query = audio_query.where(AcousticAnalysisRunModel.completed_at >= start_at)
        if end_at is not None:
            audio_query = audio_query.where(AcousticAnalysisRunModel.completed_at < end_at)
        audio_runs = session.scalars(
            audio_query.order_by(AcousticAnalysisRunModel.completed_at.asc())
        ).all()
        latest_audio_by_asset: dict[str, AcousticAnalysisRunModel] = {}
        for run in audio_runs:
            latest_audio_by_asset[run.media_asset_id] = run
        audio_facts = [
            RecordedAudioAcquisitionFact(
                media_asset_id=run.media_asset_id,
                stream_id=run.stream_id,
                source_duration_seconds=run.source_duration_seconds,
                windows_analyzed=run.windows_analyzed,
                completed_at=_as_utc(run.completed_at or run.created_at),
            )
            for run in latest_audio_by_asset.values()
        ]

        return compute_offline_acquisition_effort(
            recorded_videos=video_facts, still_images=still_facts, recorded_audio=audio_facts,
        )

    def _research_export_id(self, output_name: str | None, *, prefix: str = "research-export") -> str:
        base_name = output_name or prefix
        timestamp = datetime.now(UTC).strftime("%Y%m%dT%H%M%S%fZ")
        return f"{base_name}-{timestamp}-{uuid.uuid4().hex[:8]}"

    def _research_export_output_dir(self, export_root: Path, directory_name: str) -> Path:
        output_dir = (export_root / directory_name).resolve(strict=False)
        if not output_dir.is_relative_to(export_root):
            raise ValueError("research export path must stay under the export root")
        return output_dir

    def _write_csv(self, path: Path, fieldnames: list[str], rows: list[dict[str, Any]]) -> None:
        with path.open("w", encoding="utf-8", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=fieldnames)
            writer.writeheader()
            for row in rows:
                writer.writerow({name: row.get(name) for name in fieldnames})

    def research_export_eligibility_preview(
        self, filters: ResearchExportFilters,
    ) -> tuple[list[ResearchObservation], "Counter[str]"]:
        """Side-effect-free: every observation in scope plus a required-
        reason skip breakdown for the ineligible ones -- the bounded
        eligibility/check step "Research-safe external sharing" in the
        governing milestone brief calls for, reusable by both the API and
        the export writers below so they never compute this twice."""

        with self.session_factory() as session:
            taxonomy_index = self._taxonomy_label_index(session)
            observations = self._research_observations_for_scope(
                session, filters=filters, taxonomy_index=taxonomy_index
            )
        excluded_reasons: Counter[str] = Counter()
        for observation in observations:
            if not observation.eligibility.eligible:
                for reason in observation.eligibility.required_reasons:
                    excluded_reasons[reason] += 1
        return observations, excluded_reasons

    def export_research_dataset(self, payload: ResearchExportRequest) -> ResearchExportResponse:
        """Generic research-safe CSV/JSON export (see "Generic research
        export" in the governing milestone brief). Always trusted-only by
        construction: a provisional/unresolved/rejected/superseded record
        never reaches `observations.csv`/`.jsonl` -- only its exclusion
        reason is counted, in `manifest.excluded_reasons`."""

        observations, excluded_reasons = self.research_export_eligibility_preview(payload.filters)
        eligible = sorted_observations([obs for obs in observations if obs.eligibility.eligible])

        export_id = self._research_export_id(payload.output_name)
        generated_at = datetime.now(UTC)
        media_ids = {item.media_id for obs in eligible for item in obs.evidence}

        manifest = ResearchExportManifest(
            schema_version=RESEARCH_EXPORT_SCHEMA_VERSION,
            export_id=export_id,
            generated_at=generated_at,
            application_version=MOCKINGBIRD_VERSION,
            eligibility_policy_version=RESEARCH_ELIGIBILITY_POLICY_VERSION,
            filters=payload.filters,
            source_ids=sorted({obs.source_id for obs in eligible}),
            observation_count=len(eligible),
            media_count=len(media_ids),
            excluded_count=len(observations) - len(eligible),
            excluded_reasons=dict(sorted(excluded_reasons.items())),
            content_fingerprint=observations_content_fingerprint(eligible),
        )
        file_names = ["observations.csv", "observations.jsonl", "media.csv", "sources.csv", "effort.csv", "manifest.json"]

        if payload.dry_run:
            return ResearchExportResponse(
                export_id=export_id,
                output_directory=None,
                files=[
                    ClassifierManifestExportFile(
                        name=name, relative_path=name,
                        content_type=RESEARCH_EXPORT_CONTENT_TYPES[name], size_bytes=None,
                    )
                    for name in file_names
                ],
                observation_count=manifest.observation_count,
                media_count=manifest.media_count,
                excluded_count=manifest.excluded_count,
                excluded_reasons=manifest.excluded_reasons,
                manifest=manifest,
                dry_run=True,
            )

        with self.session_factory() as session:
            stream_ids = self._research_scope_stream_ids(session, payload.filters)
            start_at = _as_utc(payload.filters.start_at) if payload.filters.start_at is not None else None
            end_at = _as_utc(payload.filters.end_at) if payload.filters.end_at is not None else None
            coverage, _ = self._place_activity_coverage_summary(
                session,
                stream_ids=stream_ids if stream_ids is not None else list(session.scalars(select(StreamModel.id)).all()),
                period_start_at=start_at or datetime(1970, 1, 1, tzinfo=UTC),
                period_end_at=end_at or generated_at,
            )
            offline_effort = self._offline_acquisition_effort_for_scope(
                session, stream_ids=stream_ids, start_at=start_at, end_at=end_at,
            )

        export_root = self.research_export_root.resolve(strict=False)
        export_root.mkdir(parents=True, exist_ok=True)
        output_dir = self._research_export_output_dir(export_root, export_id)
        temporary_dir = self._research_export_output_dir(export_root, f".{export_id}.tmp")
        if output_dir.exists() or temporary_dir.exists():
            raise ValueError("research export directory already exists")

        temporary_dir.mkdir()
        try:
            self._write_csv(
                temporary_dir / "observations.csv",
                list(RESEARCH_OBSERVATION_CSV_FIELDNAMES),
                [research_observation_to_csv_row(obs) for obs in eligible],
            )
            self._write_jsonl(
                temporary_dir / "observations.jsonl",
                [research_observation_to_json(obs) for obs in eligible],
            )
            self._write_csv(
                temporary_dir / "media.csv",
                list(RESEARCH_MEDIA_CSV_FIELDNAMES),
                media_records_for_observations(eligible),
            )
            self._write_csv(
                temporary_dir / "sources.csv",
                list(RESEARCH_SOURCES_CSV_FIELDNAMES),
                source_records_for_observations(eligible),
            )
            self._write_csv(
                temporary_dir / "effort.csv",
                list(RESEARCH_EFFORT_CSV_FIELDNAMES),
                self._research_effort_rows(coverage=coverage, offline=offline_effort),
            )
            self._write_json(temporary_dir / "manifest.json", manifest.model_dump(mode="json"))
            temporary_dir.rename(output_dir)
        except Exception:
            shutil.rmtree(temporary_dir, ignore_errors=True)
            raise

        return ResearchExportResponse(
            export_id=export_id,
            output_directory=str(output_dir),
            files=[
                ClassifierManifestExportFile(
                    name=name, relative_path=name,
                    content_type=RESEARCH_EXPORT_CONTENT_TYPES[name],
                    size_bytes=(output_dir / name).stat().st_size,
                )
                for name in file_names
            ],
            observation_count=manifest.observation_count,
            media_count=manifest.media_count,
            excluded_count=manifest.excluded_count,
            excluded_reasons=manifest.excluded_reasons,
            manifest=manifest,
            dry_run=False,
        )

    def _research_effort_rows(
        self, *, coverage: CoverageSummary, offline: OfflineAcquisitionEffort,
    ) -> list[dict[str, Any]]:
        return [
            {
                "kind": "live_monitoring", "monitored_seconds": coverage.monitored_seconds,
                "usable_day_count": None, "count": None,
            },
            {
                "kind": "offline_recorded_video", "monitored_seconds": offline.recorded_video_analyzed_seconds,
                "usable_day_count": None, "count": offline.recorded_video_count,
            },
            {
                "kind": "offline_still_image", "monitored_seconds": None,
                "usable_day_count": None, "count": offline.still_image_count,
            },
            {
                "kind": "offline_recorded_audio", "monitored_seconds": offline.recorded_audio_analyzed_seconds,
                "usable_day_count": None, "count": offline.recorded_audio_count,
            },
        ]

    def export_camtrap_dp_package(self, payload: CamtrapDpExportRequest) -> CamtrapDpExportResponse:
        """Camtrap DP interoperability export (target spec v1.0.2 -- see
        docs/research-conservation-export-contract.md "Camtrap DP
        mapping")."""

        with self.session_factory() as session:
            taxonomy_index = self._taxonomy_label_index(session)
            observations = self._research_observations_for_scope(
                session, filters=payload.filters, taxonomy_index=taxonomy_index
            )

        options = CamtrapDpMappingOptions(
            site_name=payload.site_name,
            latitude=payload.latitude,
            longitude=payload.longitude,
            include_machine_classifications=payload.include_machine_classifications,
        )
        package = build_camtrap_dp_package(observations, options=options)
        validation_result = validate_camtrap_dp_package(package)
        validation = CamtrapDpValidation(
            valid=validation_result.valid,
            errors=list(validation_result.errors),
            warnings=list(validation_result.warnings),
        )

        export_id = self._research_export_id(payload.output_name, prefix="camtrap-dp")
        file_names = ["deployments.csv", "media.csv", "observations.csv", "datapackage.json"]

        if payload.dry_run:
            return CamtrapDpExportResponse(
                export_id=export_id,
                output_directory=None,
                files=[
                    ClassifierManifestExportFile(
                        name=name, relative_path=name,
                        content_type=CAMTRAP_DP_EXPORT_CONTENT_TYPES[name], size_bytes=None,
                    )
                    for name in file_names
                ],
                profile_version=package.profile_version,
                deployment_count=len(package.deployments),
                media_count=len(package.media),
                observation_count=len(package.observations),
                validation=validation,
                dry_run=True,
            )

        export_root = self.research_export_root.resolve(strict=False)
        export_root.mkdir(parents=True, exist_ok=True)
        output_dir = self._research_export_output_dir(export_root, export_id)
        temporary_dir = self._research_export_output_dir(export_root, f".{export_id}.tmp")
        if output_dir.exists() or temporary_dir.exists():
            raise ValueError("camtrap dp export directory already exists")

        temporary_dir.mkdir()
        try:
            self._write_csv(
                temporary_dir / "deployments.csv",
                list(CAMTRAP_DEPLOYMENT_CSV_FIELDNAMES),
                [camtrap_deployment_to_row(deployment) for deployment in package.deployments],
            )
            self._write_csv(
                temporary_dir / "media.csv",
                list(CAMTRAP_MEDIA_CSV_FIELDNAMES),
                [camtrap_media_to_row(media) for media in package.media],
            )
            self._write_csv(
                temporary_dir / "observations.csv",
                list(CAMTRAP_OBSERVATION_CSV_FIELDNAMES),
                [camtrap_observation_to_row(observation) for observation in package.observations],
            )
            self._write_json(
                temporary_dir / "datapackage.json",
                camtrap_dp_datapackage_descriptor(
                    package, generated_at=datetime.now(UTC), software_version=MOCKINGBIRD_VERSION,
                ),
            )
            temporary_dir.rename(output_dir)
        except Exception:
            shutil.rmtree(temporary_dir, ignore_errors=True)
            raise

        return CamtrapDpExportResponse(
            export_id=export_id,
            output_directory=str(output_dir),
            files=[
                ClassifierManifestExportFile(
                    name=name, relative_path=name,
                    content_type=CAMTRAP_DP_EXPORT_CONTENT_TYPES[name],
                    size_bytes=(output_dir / name).stat().st_size,
                )
                for name in file_names
            ],
            profile_version=package.profile_version,
            deployment_count=len(package.deployments),
            media_count=len(package.media),
            observation_count=len(package.observations),
            validation=validation,
            dry_run=False,
        )

    def conservation_report(self, payload: ConservationReportRequest) -> ConservationReportResponse:
        """Read-only Conservation Reporting v1 entry point (see
        "Conservation Reporting v1" in the governing milestone brief).
        Never creates or mutates ReviewLabel/SpeciesSuggestion/Visit/Event
        state -- reuses the exact same canonical per-Visit resolver
        (`_stream_visit_summary_from_models`) `place_activity_report`/
        `zone_insights` already rely on, and the same coverage primitives
        (`_place_activity_coverage_summary`,
        `_monitoring_exposure_intervals_and_history`) for live monitoring
        effort. This is an independent, additional caller of those shared
        resolvers, not a second truth/coverage computation."""

        period_start_at = _as_utc(payload.start_at)
        period_end_at = _as_utc(payload.end_at)
        generated_at = datetime.now(UTC)
        local_timezone = resolve_host_local_timezone(generated_at)

        with self.session_factory() as session:
            stream_ids = (
                list(payload.stream_ids)
                if payload.stream_ids is not None
                else list(
                    session.scalars(
                        select(StreamModel.id)
                        .join(CameraSourceModel, StreamModel.source_id == CameraSourceModel.id)
                        .where(CameraSourceModel.status != SourceStatus.archived.value)
                    ).all()
                )
            )
            taxonomy_index = self._taxonomy_label_index(session)

            def resolve_taxon(label: str | None) -> TaxonFact | None:
                if not label:
                    return None
                taxonomy = taxonomy_index.get(_taxonomy_key(label))
                return taxon_fact_from_taxonomy_label(_taxonomy_label_from_model(taxonomy)) if taxonomy else None

            visit_facts: list[VisitFact] = []
            confirmed_wildlife_with_evidence = 0
            if stream_ids:
                rows = session.execute(
                    select(VisitModel, EventModel)
                    .join(EventModel, VisitModel.event_id == EventModel.id)
                    .where(
                        VisitModel.is_superseded.is_(False),
                        EventModel.stream_id.in_(stream_ids),
                        EventModel.started_at >= period_start_at,
                        EventModel.started_at < period_end_at,
                    )
                    .order_by(EventModel.started_at, EventModel.id, VisitModel.id)
                ).all()
                for visit, event in rows:
                    summary = self._stream_visit_summary_from_models(
                        session, visit, event, taxonomy_index=taxonomy_index
                    )
                    confirmed_taxon = resolve_taxon(summary.reviewed_label)
                    visit_facts.append(
                        visit_fact_from_stream_visit_summary(
                            summary,
                            confirmed_taxon=confirmed_taxon,
                            provisional_taxon=resolve_taxon(summary.suggested_label),
                        )
                    )
                    if (
                        summary.review_status == ReviewStatus.reviewed
                        and confirmed_taxon is not None
                        and is_wildlife_category(confirmed_taxon.category)
                        and summary.evidence_frame_count > 0
                    ):
                        confirmed_wildlife_with_evidence += 1

            coverage, _streams_without_history = self._place_activity_coverage_summary(
                session, stream_ids=stream_ids, period_start_at=period_start_at, period_end_at=period_end_at,
            )
            monitored_intervals, history_available_from, _ = self._monitoring_exposure_intervals_and_history(
                session, stream_ids=stream_ids, period_start_at=period_start_at, period_end_at=period_end_at,
            )
            usable_day_count: int | None = None
            if history_available_from is not None:
                daily_seconds = bucket_intervals_by_local_day(
                    monitored_intervals,
                    window_start_at=period_start_at,
                    window_end_at=period_end_at,
                    local_timezone=local_timezone,
                )
                usable_day_count = len(usable_dates_from_daily_monitored_seconds(daily_seconds))

            offline_effort = self._offline_acquisition_effort_for_scope(
                session, stream_ids=stream_ids, start_at=period_start_at, end_at=period_end_at,
            )
            scientific_names_by_label = {
                model.label: model.scientific_name for model in taxonomy_index.values()
            }

        report = compute_place_activity_report(
            visit_facts, period_start_at=period_start_at, period_end_at=period_end_at,
            local_timezone=local_timezone, coverage=coverage, generated_at=generated_at,
        )
        conservation = compute_conservation_report(
            report,
            visits=visit_facts,
            scientific_names_by_label=scientific_names_by_label,
            offline_acquisition=offline_effort,
            live_monitoring_usable_day_count=usable_day_count,
            confirmed_wildlife_visits_with_evidence_count=confirmed_wildlife_with_evidence,
            local_timezone=local_timezone,
            generated_at=generated_at,
        )

        return ConservationReportResponse(
            period_start_at=conservation.period_start_at,
            period_end_at=conservation.period_end_at,
            generated_at=conservation.generated_at,
            maturity=conservation.maturity,
            live_monitoring_monitored_seconds=conservation.live_monitoring_monitored_seconds,
            live_monitoring_usable_day_count=conservation.live_monitoring_usable_day_count,
            offline_recorded_video_count=conservation.offline_acquisition.recorded_video_count,
            offline_recorded_video_analyzed_seconds=conservation.offline_acquisition.recorded_video_analyzed_seconds,
            offline_recorded_video_unknown_duration_count=(
                conservation.offline_acquisition.recorded_video_unknown_duration_count
            ),
            offline_still_image_count=conservation.offline_acquisition.still_image_count,
            offline_recorded_audio_count=conservation.offline_acquisition.recorded_audio_count,
            offline_recorded_audio_analyzed_seconds=(
                conservation.offline_acquisition.recorded_audio_analyzed_seconds
            ),
            offline_recorded_audio_unknown_duration_count=(
                conservation.offline_acquisition.recorded_audio_unknown_duration_count
            ),
            confirmed_species=[
                ConservationSpeciesEntry(
                    label=record.label,
                    display_name=record.display_name,
                    scientific_name=record.scientific_name,
                    is_species=record.is_species,
                    confirmed_visit_count=record.confirmed_visit_count,
                    occurrence_day_count=record.occurrence_day_count,
                    first_confirmed_at=record.first_confirmed_at,
                    last_confirmed_at=record.last_confirmed_at,
                    occurrence_note=record.occurrence_note,
                )
                for record in conservation.confirmed_species
            ],
            confirmed_unidentified_wildlife_visit_count=conservation.confirmed_unidentified_wildlife_visit_count,
            reviewed_wildlife_visit_count=conservation.reviewed_wildlife_visit_count,
            provisional_wildlife_visit_count=conservation.provisional_wildlife_visit_count,
            unresolved_visit_count=conservation.unresolved_visit_count,
            total_visit_count=conservation.total_visit_count,
            first_activity_at=conservation.first_activity_at,
            last_activity_at=conservation.last_activity_at,
            confirmed_wildlife_visits_with_evidence_count=conservation.confirmed_wildlife_visits_with_evidence_count,
        )

    def create_research_collection(self, payload: ResearchCollectionCreate) -> ResearchCollection:
        """Explicit, bounded named research collection (see "Bounded
        research collaboration / contributor network" in the governing
        milestone brief). Membership is a capped, explicit id list -- never
        an implicit "everything reviewed" set -- and every included id is
        still resolved through the ordinary Visit/ReviewLabel truth boundary
        at read/export time, never cached as a second truth store here."""

        with self.session_factory() as session:
            with session.begin():
                collection_id = self._next_id(session, ResearchCollectionModel, "research-collection")
                now = datetime.now(UTC)
                model = ResearchCollectionModel(
                    id=collection_id,
                    name=payload.name,
                    description=payload.description,
                    curator_identity=_clean_optional_text(payload.curator_identity),
                    visit_ids_json=json.dumps(list(payload.visit_ids)),
                    eligibility_policy_version=RESEARCH_ELIGIBILITY_POLICY_VERSION,
                    created_at=now,
                    updated_at=now,
                )
                session.add(model)
                session.flush()
                taxonomy_index = self._taxonomy_label_index(session)
                eligible_count, excluded_count = self._research_collection_counts(
                    session, payload.visit_ids, taxonomy_index
                )
                return self._research_collection_response(model, eligible_count, excluded_count)

    def get_research_collection(self, collection_id: str) -> ResearchCollection | None:
        with self.session_factory() as session:
            model = session.get(ResearchCollectionModel, collection_id)
            if model is None:
                return None
            taxonomy_index = self._taxonomy_label_index(session)
            eligible_count, excluded_count = self._research_collection_counts(
                session, json.loads(model.visit_ids_json), taxonomy_index,
            )
            return self._research_collection_response(model, eligible_count, excluded_count)

    def list_research_collections(self) -> list[ResearchCollectionSummary]:
        with self.session_factory() as session:
            models = session.scalars(
                select(ResearchCollectionModel).order_by(ResearchCollectionModel.created_at.desc())
            ).all()
            return [
                ResearchCollectionSummary(
                    id=model.id,
                    name=model.name,
                    curator_identity=model.curator_identity,
                    visit_count=len(json.loads(model.visit_ids_json)),
                    created_at=_as_utc(model.created_at),
                )
                for model in models
            ]

    def _research_collection_counts(
        self,
        session: Session,
        visit_ids: list[str],
        taxonomy_index: dict[str, TaxonomyLabelModel],
    ) -> tuple[int, int]:
        """Contributing a record to a collection never grants taxonomic
        authority (see "Contributor authority" in the governing milestone
        brief): membership is resolved through the ordinary eligibility
        boundary every time, never cached as its own truth."""

        eligible = 0
        excluded = 0
        for visit_id in visit_ids:
            visit_model = session.get(VisitModel, visit_id)
            event_model = session.get(EventModel, visit_model.event_id) if visit_model is not None else None
            if visit_model is None or event_model is None:
                excluded += 1
                continue
            observation = self._research_observation_for_visit(
                session, visit_model, event_model, taxonomy_index=taxonomy_index
            )
            if observation.eligibility.eligible:
                eligible += 1
            else:
                excluded += 1
        return eligible, excluded

    def _research_collection_response(
        self, model: ResearchCollectionModel, eligible_count: int, excluded_count: int,
    ) -> ResearchCollection:
        return ResearchCollection(
            id=model.id,
            name=model.name,
            description=model.description,
            curator_identity=model.curator_identity,
            visit_ids=json.loads(model.visit_ids_json),
            eligibility_policy_version=model.eligibility_policy_version,
            created_at=_as_utc(model.created_at),
            updated_at=_as_utc(model.updated_at),
            eligible_observation_count=eligible_count,
            excluded_count=excluded_count,
        )

    def _resolve_import_stream(
        self,
        session: Session,
        stream_id: str | None,
    ) -> StreamModel:
        if stream_id:
            stream_model = session.get(StreamModel, stream_id)
            if stream_model is None:
                raise ValueError("missing_stream")
            return stream_model

        streams = list(session.scalars(select(StreamModel).order_by(StreamModel.id)).all())
        if len(streams) != 1:
            raise ValueError("stream_required")
        return streams[0]

    def _resolve_source_import_stream(
        self,
        session: Session,
        *,
        source_id: str,
        stream_id: str | None,
    ) -> tuple[StreamModel, str | None]:
        if stream_id:
            stream_model = session.get(StreamModel, stream_id)
            if stream_model is None:
                raise ValueError("missing_stream")
            if stream_model.source_id != source_id:
                raise ValueError("stream_source_mismatch")
            return stream_model, None

        streams = list(
            session.scalars(
                select(StreamModel).where(StreamModel.source_id == source_id).order_by(StreamModel.id)
            ).all()
        )
        if not streams:
            raise ValueError("stream_required")
        return (
            streams[0],
            "No stream was supplied; MockingBird used the first stream for this Source.",
        )

    def _resolve_import_zone(
        self,
        session: Session,
        zone_id: str | None,
        stream_id: str,
    ) -> ZoneModel | None:
        if zone_id is None:
            return None

        zone_model = session.get(ZoneModel, zone_id)
        if zone_model is None:
            raise ValueError("missing_zone")
        if zone_model.stream_id != stream_id:
            raise ValueError("zone_stream_mismatch")
        return zone_model

    def _resolve_source_import_zone(
        self,
        session: Session,
        *,
        zone_id: str | None,
        stream_id: str,
    ) -> ZoneModel | None:
        if zone_id is None:
            return None

        zone_model = session.get(ZoneModel, zone_id)
        if zone_model is None:
            raise ValueError("missing_zone")
        if zone_model.stream_id != stream_id:
            raise ValueError("zone_stream_mismatch")
        if zone_model.zone_type in {ZoneType.privacy.value, ZoneType.ignore.value}:
            raise ValueError("zone_blocked")
        return zone_model

    def _folder_import_duplicate_exists(
        self,
        session: Session,
        *,
        source_id: str,
        relative_source_path: str,
        size_bytes: int | None,
        modified_at: datetime | None,
        content_sha256: str | None = None,
    ) -> bool:
        # v0.1 Acquisition/Ingest Interoperability Closure v1 ("II.12
        # Duplicate protection"): a real content-hash match (the same
        # bytes, imported under a different relative path/name -- a moved
        # or renamed file, or a second copy of the same clip in a
        # different folder) is checked first and independently of the
        # existing path/size/mtime signal below; `content_sha256` reuses
        # the same `MediaAssetModel` column Localization Attribution v1
        # already added for a different purpose, populated for every
        # folder-imported asset since this milestone (see the creation
        # loop) but never for one imported before it -- an older asset
        # with `content_sha256 IS NULL` never matches here, an honest
        # "cannot content-check that one," not a false negative treated as
        # a false positive.
        if content_sha256 and session.scalar(
            select(MediaAssetModel.id).where(
                MediaAssetModel.source_id == source_id,
                MediaAssetModel.content_sha256 == content_sha256,
            )
        ):
            return True

        size_value = "" if size_bytes is None else str(size_bytes)
        modified_value = "" if modified_at is None else modified_at.isoformat()
        assets = session.scalars(
            select(MediaAssetModel).where(MediaAssetModel.source_id == source_id)
        ).all()
        for asset in assets:
            fields = _folder_import_note_fields(asset.notes)
            if (
                fields.get("provider_key") == "folder_import_future"
                and fields.get("source_id") == source_id
                and fields.get("relative_source_path") == relative_source_path
                and fields.get("size_bytes", "") == size_value
                and fields.get("modified_at", "") == modified_value
            ):
                return True
        return False

    def _taxonomy_label_model_for_input(
        self,
        session: Session,
        input_label: str,
        *,
        taxonomy_index: dict[str, TaxonomyLabelModel] | None = None,
    ) -> TaxonomyLabelModel | None:
        """Resolve one input label/id/alias to its `TaxonomyLabelModel`.

        `taxonomy_index` is an optional performance escape hatch: a
        report-scoped caller that already preloaded the whole table once
        (`_taxonomy_label_index`, same key construction/id-ordered
        tie-break) can pass it here to turn what would otherwise be a fresh
        full-table scan on every call into an O(1) dict lookup. Omitting it
        (the default) preserves this method's original per-call query
        exactly, unchanged, for every one of its many existing callers --
        several of which back truth-writing paths
        (`_normalize_label_from_session` alone underlies every review-
        correction creation path) where a stale/report-scoped snapshot
        would be the wrong tool. See `_stream_visit_summary_from_models`'s
        own docstring for where the index is threaded from.
        """

        lookup_key = _taxonomy_key(input_label)
        if not lookup_key:
            return None

        if taxonomy_index is not None:
            return taxonomy_index.get(lookup_key)

        labels = session.scalars(select(TaxonomyLabelModel).order_by(TaxonomyLabelModel.id)).all()
        for label in labels:
            taxonomy_label = _taxonomy_label_from_model(label)
            candidates = [
                taxonomy_label.id,
                taxonomy_label.label,
                taxonomy_label.display_name,
                *taxonomy_label.aliases,
            ]
            if lookup_key in {_taxonomy_key(candidate) for candidate in candidates}:
                return label
        return None

    def _normalize_label_from_session(self, session: Session, input_label: str) -> str:
        label_model = self._taxonomy_label_model_for_input(session, input_label)
        if label_model is not None:
            return label_model.label
        return _freeform_label(input_label)

    def _adapter_subject_and_species(
        self,
        session: Session,
        normalized_label: str,
    ) -> tuple[str, str | None]:
        taxonomy_label = self._taxonomy_label_model_for_input(session, normalized_label)
        taxonomy = _taxonomy_label_from_model(taxonomy_label) if taxonomy_label else None
        if taxonomy is not None and taxonomy.category == LabelCategory.bird and taxonomy.is_species:
            return "bird", taxonomy.label
        if normalized_label == "unknown_bird":
            return "unknown_bird", "unknown_bird"
        return normalized_label, None

    def _default_demo_zone(self, session: Session, stream_id: str) -> ZoneModel | None:
        zones = list(
            session.scalars(
                select(ZoneModel).where(ZoneModel.stream_id == stream_id).order_by(ZoneModel.id)
            ).all()
        )
        for zone in zones:
            if zone.is_active and zone.zone_type not in {
                ZoneType.ignore.value,
                ZoneType.privacy.value,
            }:
                return zone
        return zones[0] if zones else None

    def _write_media_file(self, filename: str, content: bytes) -> tuple[str, Path]:
        self.media_root.mkdir(parents=True, exist_ok=True)
        path = self.media_root / filename
        if path.exists():
            name = Path(filename)
            counter = 2
            while True:
                candidate = self.media_root / f"{name.stem}-{counter}{name.suffix}"
                if not candidate.exists():
                    path = candidate
                    break
                counter += 1
        path.write_bytes(content)
        return path.name, path

    def _copy_media_file(self, filename: str, source_path: Path) -> tuple[str, Path]:
        self.media_root.mkdir(parents=True, exist_ok=True)
        path = self.media_root / filename
        if path.exists():
            name = Path(filename)
            counter = 2
            while True:
                candidate = self.media_root / f"{name.stem}-{counter}{name.suffix}"
                if not candidate.exists():
                    path = candidate
                    break
                counter += 1
        shutil.copyfile(source_path, path)
        return path.name, path

    def _external_url_preview_media_notes(
        self,
        *,
        source_id: str,
        stream_id: str,
        fetched_at: datetime,
        content_type: str,
        bytes_written: int,
        url_host: str | None,
        note: str | None,
    ) -> str:
        lines = [
            "Saved explicit external_url still-image preview.",
            "Creates no Events, Visits, ReviewLabels, or truth.",
            "provider_key=external_url",
            f"source_id={source_id}",
            f"stream_id={stream_id}",
            f"fetched_at={fetched_at.isoformat()}",
            f"content_type={content_type}",
            f"bytes_written={bytes_written}",
        ]
        if url_host:
            lines.append(f"url_host={url_host}")
        cleaned_note = _clean_optional_text(note)
        if cleaned_note is not None:
            lines.append(f"note={cleaned_note}")
        return "\n".join(lines)

    def _local_camera_frame_media_notes(
        self,
        *,
        source_id: str,
        stream_id: str,
        captured_at: datetime,
        content_type: str,
        bytes_written: int,
        playback_type: str,
        camera_label: str | None,
    ) -> str:
        lines = [
            "Saved explicit local camera frame capture.",
            "Creates no Events, Visits, ReviewLabels, exports, or truth.",
            "provider_key=local_usb",
            f"playback_type={playback_type}",
            f"source_id={source_id}",
            f"stream_id={stream_id}",
            f"captured_at={captured_at.isoformat()}",
            f"content_type={content_type}",
            f"bytes_written={bytes_written}",
        ]
        cleaned_camera_label = _clean_optional_text(camera_label)
        if cleaned_camera_label is not None:
            lines.append(f"camera={cleaned_camera_label}")
        return "\n".join(lines)

    def _live_motion_frame_media_notes(
        self,
        *,
        source_id: str,
        stream_id: str,
        captured_at: datetime,
        content_type: str,
        bytes_written: int,
        frame_sequence: int,
        playback_type: str | None,
        note: str | None,
    ) -> str:
        lines = [
            "Saved best live motion frame from active stream.",
            "Creates no Events, Visits, ReviewLabels, exports, or truth.",
            f"source_id={source_id}",
            f"stream_id={stream_id}",
            f"captured_at={captured_at.isoformat()}",
            f"content_type={content_type}",
            f"bytes_written={bytes_written}",
            f"frame_sequence={frame_sequence}",
        ]
        cleaned_playback_type = _clean_optional_text(playback_type)
        if cleaned_playback_type is not None:
            lines.append(f"playback_type={cleaned_playback_type}")
        cleaned_note = _clean_optional_text(note)
        if cleaned_note is not None:
            lines.append(f"note={cleaned_note}")
        return "\n".join(lines)

    def _preview_folder_import_for_path(self, folder: Path) -> FolderImportPreview:
        if not folder.exists():
            raise ValueError("folder_missing")
        if not folder.is_dir():
            raise ValueError("folder_not_directory")

        supported_files: list[FolderImportCandidate] = []
        skipped_files: list[FolderImportSkippedFile] = []

        # Folder import is an explicit, non-recursive local source path.
        for path in sorted(folder.iterdir(), key=lambda item: item.name.lower()):
            if not path.is_file():
                skipped_files.append(
                    FolderImportSkippedFile(filename=path.name, reason="not_file")
                )
                continue

            media_type_info = _media_type_for_path(path)
            if media_type_info is None:
                skipped_files.append(
                    FolderImportSkippedFile(
                        filename=path.name,
                        reason="unsupported_content_type",
                    )
                )
                continue

            file_size = path.stat().st_size
            if file_size <= 0:
                skipped_files.append(
                    FolderImportSkippedFile(filename=path.name, reason="empty_file")
                )
                continue

            content_type, media_type = media_type_info
            supported_files.append(
                FolderImportCandidate(
                    filename=path.name,
                    path=str(path),
                    content_type=content_type,
                    media_type=media_type,
                    file_size_bytes=file_size,
                )
            )

        return FolderImportPreview(
            folder_path=str(folder),
            supported_files=supported_files,
            skipped_files=skipped_files,
            supported_count=len(supported_files),
            skipped_count=len(skipped_files),
        )

    def _create_detection_proposal_review_records(
        self,
        session: Session,
        *,
        proposal_model: DetectionProposalModel,
        payload: DetectionProposalDecisionCreate,
        created_at: datetime,
    ) -> tuple[Event, Visit]:
        asset_model = session.get(MediaAssetModel, proposal_model.media_asset_id)
        if asset_model is None:
            raise ValueError("missing_media_asset")

        stream_model = session.get(StreamModel, proposal_model.stream_id)
        if stream_model is None:
            raise ValueError("missing_stream")

        zone_model = self._resolve_import_zone(
            session,
            proposal_model.zone_id,
            proposal_model.stream_id,
        )
        event_id = self._next_id(session, EventModel, "event-detection")
        visit_id = self._next_id(session, VisitModel, "visit-detection")
        detection_id = self._next_id(session, DetectionModel, "detection-proposal")
        event_title = (
            payload.event_title.strip()
            if payload.event_title and payload.event_title.strip()
            else f"Detection proposal: {proposal_model.label}"
        )
        subject_label = (
            payload.subject_label.strip()
            if payload.subject_label and payload.subject_label.strip()
            else proposal_model.suggested_subject_label
        )
        species_guess = (
            payload.species_guess.strip()
            if payload.species_guess and payload.species_guess.strip()
            else proposal_model.suggested_species
        )

        event_model = EventModel(
            id=event_id,
            stream_id=stream_model.id,
            title=event_title,
            event_type=proposal_model.suggested_event_type,
            started_at=created_at,
            ended_at=created_at,
            primary_zone_id=zone_model.id if zone_model else None,
            review_status=ReviewStatus.needs_review.value,
        )
        visit_model = VisitModel(
            id=visit_id,
            event_id=event_id,
            subject_label=subject_label,
            species_guess=species_guess,
            confidence=proposal_model.confidence,
            reviewed_label=None,
            review_status=ReviewStatus.needs_review.value,
            representative_media_path=asset_model.local_path,
        )
        detection_model = DetectionModel(
            id=detection_id,
            event_id=event_id,
            label=proposal_model.label,
            confidence=proposal_model.confidence,
            zone_id=zone_model.id if zone_model else None,
            bbox_json=proposal_model.bbox_json,
        )
        session.add_all([event_model, visit_model, detection_model])
        session.flush()
        self._sync_review_alert(session, visit_model, created_at)
        return self._event_from_model(session, event_model), _visit_from_model(visit_model)

    def _create_media_product_records(
        self,
        session: Session,
        *,
        stream_model: StreamModel,
        zone_model: ZoneModel | None,
        content: bytes,
        original_filename: str,
        content_type: str,
        media_type: str,
        title: str | None,
        event_type: str,
        default_title: str,
        subject_label: str,
        species_guess: str | None,
        notes: str | None,
    ) -> tuple[MediaAsset, Event, Visit]:
        media_id = self._next_id(session, MediaAssetModel, "media-asset")
        event_id = self._next_id(session, EventModel, "event-media")
        visit_id = self._next_id(session, VisitModel, "visit-media")
        filename = f"{media_id}-{_safe_filename(original_filename)}"
        filename, local_path = self._write_media_file(filename, content)
        created_at = datetime.now(UTC)

        asset_model = MediaAssetModel(
            id=media_id,
            source_id=stream_model.source_id,
            stream_id=stream_model.id,
            filename=filename,
            content_type=content_type,
            media_type=media_type,
            local_path=str(local_path),
            original_filename=original_filename or filename,
            file_size_bytes=len(content),
            created_at=created_at,
            notes=notes,
        )
        event_model = EventModel(
            id=event_id,
            stream_id=stream_model.id,
            title=title.strip() if title and title.strip() else default_title,
            event_type=event_type,
            started_at=created_at,
            ended_at=created_at,
            primary_zone_id=zone_model.id if zone_model else None,
            review_status=ReviewStatus.needs_review.value,
        )
        visit_model = VisitModel(
            id=visit_id,
            event_id=event_id,
            subject_label=subject_label.strip() or "unknown_animal",
            species_guess=(
                species_guess.strip()
                if species_guess and species_guess.strip()
                else None
            ),
            confidence=None,
            reviewed_label=None,
            review_status=ReviewStatus.needs_review.value,
            representative_media_path=str(local_path),
        )
        session.add_all([asset_model, event_model, visit_model])
        session.flush()
        self._sync_review_alert(session, visit_model, created_at)
        self._sync_storage_alert(session, created_at)

        return (
            _media_asset_from_model(asset_model),
            self._event_from_model(session, event_model),
            _visit_from_model(visit_model),
        )

    def _media_asset_for_path_from_session(
        self,
        session: Session,
        media_path: str | None,
    ) -> MediaAsset | None:
        if media_path is None:
            return None

        asset = session.scalar(
            select(MediaAssetModel).where(MediaAssetModel.local_path == media_path)
        )
        return _media_asset_from_model(asset) if asset else None

    def _zones_for_stream(self, session: Session, stream_id: str) -> list[Zone]:
        zones = session.scalars(
            select(ZoneModel).where(ZoneModel.stream_id == stream_id).order_by(ZoneModel.id)
        ).all()
        return [_zone_from_model(zone) for zone in zones]

    def _visit_models_for_event(self, session: Session, event_id: str) -> list[VisitModel]:
        return list(
            session.scalars(
                select(VisitModel)
                .where(
                    VisitModel.event_id == event_id,
                    VisitModel.is_superseded.is_(False),
                )
                .order_by(VisitModel.id)
            ).all()
        )

    def _visits_for_event(self, session: Session, event_id: str) -> list[Visit]:
        return [_visit_from_model(visit) for visit in self._visit_models_for_event(session, event_id)]

    def _review_label_models_for_event(
        self,
        session: Session,
        event_id: str,
    ) -> list[ReviewLabelModel]:
        labels = list(
            session.scalars(
                select(ReviewLabelModel)
                .where(
                    ReviewLabelModel.target_type == "event",
                    ReviewLabelModel.target_id == event_id,
                )
                .order_by(ReviewLabelModel.created_at, ReviewLabelModel.id)
            ).all()
        )
        return self._effective_review_label_models(labels)

    def _review_label_models_for_visit(
        self,
        session: Session,
        visit_id: str,
    ) -> list[ReviewLabelModel]:
        labels = list(
            session.scalars(
                select(ReviewLabelModel)
                .where(
                    ReviewLabelModel.target_type == "visit",
                    ReviewLabelModel.target_id == visit_id,
                )
                .order_by(ReviewLabelModel.created_at, ReviewLabelModel.id)
            ).all()
        )
        return self._effective_review_label_models(labels)

    def _review_label_history_models_for_visit(
        self,
        session: Session,
        visit_id: str,
        *,
        limit: int = 50,
    ) -> list[ReviewLabelModel]:
        bounded_limit = max(1, min(limit, 50))
        return list(
            session.scalars(
                select(ReviewLabelModel)
                .where(
                    ReviewLabelModel.target_type == "visit",
                    ReviewLabelModel.target_id == visit_id,
                )
                .order_by(ReviewLabelModel.created_at.desc(), ReviewLabelModel.id.desc())
                .limit(bounded_limit)
            ).all()
        )

    def _review_label_history_models_for_event(
        self,
        session: Session,
        event_id: str,
        *,
        limit: int = 50,
    ) -> list[ReviewLabelModel]:
        bounded_limit = max(1, min(limit, 50))
        return list(
            session.scalars(
                select(ReviewLabelModel)
                .where(
                    ReviewLabelModel.target_type == "event",
                    ReviewLabelModel.target_id == event_id,
                )
                .order_by(ReviewLabelModel.created_at.desc(), ReviewLabelModel.id.desc())
                .limit(bounded_limit)
            ).all()
        )

    def _effective_review_label_models(
        self,
        labels: list[ReviewLabelModel],
    ) -> list[ReviewLabelModel]:
        """Resolve exactly one current *authoritative* truth row per target
        from append-only history.

        A non-authoritative row (diagnostic assessment, or an omitted
        origin) never becomes "the effective row" here, regardless of how
        recent it is -- it must never shadow a genuine prior human/
        imported-curated correction, and a target with only non-
        authoritative rows correctly has no effective truth at all yet.
        See docs/review-decision-provenance-contract.md.
        """

        reversed_label_ids = {
            label.reversal_of_review_label_id
            for label in labels
            if label.reversal_of_review_label_id is not None
        }
        superseded_label_ids = {
            label.supersedes_review_label_id
            for label in labels
            if label.supersedes_review_label_id is not None
        }
        effective_by_target: dict[tuple[str, str], ReviewLabelModel] = {}
        for label in labels:
            if (
                label.reversal_of_review_label_id is not None
                or label.id in reversed_label_ids
                or label.id in superseded_label_ids
                or label.review_action == "reopen"
                or not review_provenance.is_authority_eligible(label.review_origin)
            ):
                continue
            target_key = (label.target_type, label.target_id)
            current = effective_by_target.get(target_key)
            if current is None or (label.created_at, label.id) > (current.created_at, current.id):
                effective_by_target[target_key] = label
        return sorted(
            effective_by_target.values(),
            key=lambda label: (label.created_at, label.id),
        )

    def _current_effective_review_label_model_for_visit(
        self,
        session: Session,
        visit_id: str,
    ) -> ReviewLabelModel | None:
        """The latest *authoritative* row for this Visit, used to find what
        a revise/reopen action would act on. A later non-authoritative
        diagnostic row must never be treated as the thing being revised or
        reopened -- see docs/review-decision-provenance-contract.md."""

        return max(
            (
                label
                for label in self._review_label_models_for_visit(session, visit_id)
                if review_provenance.is_authority_eligible(label.review_origin)
            ),
            key=lambda label: (label.created_at, label.id),
            default=None,
        )

    def _current_effective_review_label_model_for_event(
        self,
        session: Session,
        event_id: str,
    ) -> ReviewLabelModel | None:
        """The latest *authoritative* row for this Event -- the Event-level
        sibling of `_current_effective_review_label_model_for_visit`, above,
        for the no-Visit-ever-existed review queue item type (raw activity/
        person/vehicle events)."""

        return max(
            (
                label
                for label in self._review_label_models_for_event(session, event_id)
                if review_provenance.is_authority_eligible(label.review_origin)
            ),
            key=lambda label: (label.created_at, label.id),
            default=None,
        )

    def _visit_review_history_from_session(
        self,
        session: Session,
        visit: VisitModel,
    ) -> VisitReviewHistory:
        current = self._current_effective_review_label_model_for_visit(session, visit.id)
        entries = [
            VisitReviewHistoryEntry(
                action=_review_history_action_for_model(label),
                label=label.label,
                notes=label.notes,
                created_at=_as_utc(label.created_at),
                is_current=current is not None and label.id == current.id,
                review_origin=label.review_origin,
                is_authoritative=review_provenance.is_authority_eligible(label.review_origin),
            )
            for label in self._review_label_history_models_for_visit(session, visit.id)
        ]
        return VisitReviewHistory(
            visit_id=visit.id,
            review_status=ReviewStatus(visit.review_status),
            reviewed_label=visit.reviewed_label,
            review_state_token=self._review_state_token(session, "visit", visit.id),
            entries=entries,
        )

    def _review_state_token(
        self,
        session: Session,
        target_type: str,
        target_id: str,
    ) -> str:
        if target_type == "visit":
            visit = session.get(VisitModel, target_id)
            if visit is None:
                return "missing"
            labels = self._review_label_models_for_visit(session, target_id)
            return _review_state_token_value(
                target_type,
                target_id,
                visit.review_status,
                visit.reviewed_label,
                _latest_review_label_model_id(labels),
                self._visit_curation_state(session, visit),
            )
        if target_type == "event":
            event = session.get(EventModel, target_id)
            if event is None:
                return "missing"
            labels = self._review_label_models_for_event(session, target_id)
            return _review_state_token_value(
                target_type,
                target_id,
                event.review_status,
                None,
                _latest_review_label_model_id(labels),
            )
        return "missing"

    def _review_correction_result_for_model(
        self,
        session: Session,
        label_model: ReviewLabelModel,
    ) -> ReviewCorrectionResult:
        visit: Visit | None = None
        event: Event | None = None
        if label_model.target_type == "visit":
            visit_model = session.get(VisitModel, label_model.target_id)
            if visit_model is not None:
                visit = _visit_from_model(visit_model)
                event_model = session.get(EventModel, visit_model.event_id)
                if event_model is not None:
                    event = self._event_from_model(session, event_model)
        elif label_model.target_type == "event":
            event_model = session.get(EventModel, label_model.target_id)
            if event_model is not None:
                event = self._event_from_model(session, event_model)
        return ReviewCorrectionResult(
            review_label=_review_label_from_model(label_model),
            visit=visit,
            event=event,
            review_queue_count=len(self._review_queue_items(session)),
            analytics=self._analytics_summary(session),
        )

    def _visit_review_reopen_response(
        self,
        session: Session,
        visit_id: str,
        *,
        idempotent: bool = False,
    ) -> VisitReviewReopenResponse:
        visit = session.get(VisitModel, visit_id)
        if visit is None:
            raise ValueError("missing_visit")
        event = session.get(EventModel, visit.event_id)
        if event is None:
            raise ValueError("missing_event")
        return VisitReviewReopenResponse(
            visit=_visit_from_model(visit),
            event=self._event_from_model(session, event),
            review_queue_count=len(self._review_queue_items(session)),
            analytics=self._analytics_summary(session),
            review_state_token=self._review_state_token(session, "visit", visit.id),
            idempotent=idempotent,
            message="This Visit was reopened and is ready for another explicit correction.",
        )

    def _fast_review_undo_response(
        self,
        session: Session,
        reversal: ReviewLabelModel,
        *,
        idempotent: bool = False,
    ) -> FastReviewUndoResponse:
        return FastReviewUndoResponse(
            reversal_review_label_id=reversal.id,
            target_type=ReviewQueueBulkCorrectionTargetType(reversal.target_type),
            target_id=reversal.target_id,
            review_queue_count=len(self._review_queue_items(session)),
            analytics=self._analytics_summary(session),
            idempotent=idempotent,
            message="The Fast Review correction was reversed and the prior review state restored.",
        )

    def _review_labels_for_event(self, session: Session, event_id: str) -> list[ReviewLabel]:
        return [
            _review_label_from_model(label)
            for label in self._review_label_models_for_event(session, event_id)
        ]

    def _review_labels_for_visit(self, session: Session, visit_id: str) -> list[ReviewLabel]:
        return [
            _review_label_from_model(label)
            for label in self._review_label_models_for_visit(session, visit_id)
        ]

    def _create_review_label_in_session(
        self,
        session: Session,
        payload: ReviewCorrectionCreate,
        created_at: datetime | None = None,
        *,
        fast_review_session_id: str | None = None,
        fast_review_idempotency_key: str | None = None,
        supersedes_review_label_id: str | None = None,
        review_action: str | None = None,
        revision_idempotency_key: str | None = None,
        review_origin: str | None = None,
        reviewer_identity: str | None = None,
        reviewed_by_user_id: str | None = None,
    ) -> tuple[ReviewLabel, Visit | None, Event | None]:
        # Review Decision Provenance / Truth Boundary v1 (see
        # docs/review-decision-provenance-contract.md): `review_origin` is an
        # explicit caller-supplied fact, never inferred, and never defaults
        # to "human" merely because it was omitted. `is_authoritative`
        # gates every mutation below -- a non-authoritative Review Decision
        # (an omitted origin, or an explicit `agent_diagnostic`) is still
        # durably persisted for transparency, but it can never establish or
        # correct `VisitModel`/`EventModel` reviewed truth. This is the one
        # place in the product that flips a Visit/Event to "reviewed", so
        # gating here is sufficient to also keep Bird Log, Wildlife
        # Insights, Dataset Export, and classifier manifests correct
        # without touching any of their own read paths (they all key off
        # `review_status`/`reviewed_label`, set only here).
        review_provenance.validate_review_origin(review_origin, reviewer_identity, notes=payload.notes)
        is_authoritative = review_provenance.is_authority_eligible(review_origin)

        normalized_label = self._normalize_label_from_session(session, payload.label)
        label_model = ReviewLabelModel(
            id=self._next_id(session, ReviewLabelModel, "review-label"),
            target_type=payload.target_type,
            target_id=payload.target_id,
            label=normalized_label,
            notes=payload.notes,
            created_at=created_at or datetime.now(UTC),
            fast_review_session_id=fast_review_session_id,
            fast_review_idempotency_key=fast_review_idempotency_key,
            supersedes_review_label_id=supersedes_review_label_id,
            review_action=review_action,
            revision_idempotency_key=revision_idempotency_key,
            review_origin=review_origin,
            reviewer_identity=_clean_optional_text(reviewer_identity),
            reviewed_by_user_id=reviewed_by_user_id,
        )

        visit: Visit | None = None
        event: Event | None = None

        if payload.target_type == "visit":
            visit_model = session.get(VisitModel, payload.target_id)
            if visit_model is None:
                raise ValueError("missing_visit")

            event_model = session.get(EventModel, visit_model.event_id)
            if visit_model.is_superseded:
                # Superseded Visits remain auditable history, not active review
                # truth. Preserve an explicit historical correction without
                # changing the resulting Visit or its Event's current state.
                session.add(label_model)
                session.flush()
                return _review_label_from_model(label_model), _visit_from_model(visit_model), None

            if not is_authoritative:
                # A non-authoritative Review Decision (diagnostic assessment,
                # or a request that omitted provenance) is recorded as an
                # auditable, visible row attached to this Visit, but it must
                # never silently become "this Visit was reviewed" -- leave
                # the Visit/Event exactly as they already were.
                session.add(label_model)
                session.flush()
                return (
                    _review_label_from_model(label_model),
                    _visit_from_model(visit_model),
                    self._event_from_model(session, event_model) if event_model is not None else None,
                )

            if fast_review_session_id is not None:
                label_model.prior_review_status = visit_model.review_status
                label_model.prior_reviewed_label = visit_model.reviewed_label
                label_model.prior_event_review_status = (
                    event_model.review_status if event_model is not None else None
                )

            # Everyday Discovery / Product Experience v2 (Phase L): captured
            # before the overwrite below so a stale milestone alert for the
            # label this Visit is being corrected *away from* can be
            # resolved at the end of this method -- see `_sync_journal_
            # milestone_alert`'s docstring for why that only ever evaluates
            # the Visit's new label, never the one it is leaving.
            prior_reviewed_label = visit_model.reviewed_label

            # Site-Specific Learning & Local Adaptation v1 (reversibility --
            # see "Reversibility" in docs/scene-confusor-suspicion-
            # contract.md): this Visit already carried authoritative
            # reviewed truth *before* this write, so the label about to be
            # superseded (via `revise_visit_review`, or any other path that
            # re-labels an already-reviewed Visit) may itself have
            # contributed to a scene-confusor region's counts. Captured
            # before `label_model` is added below, so this query cannot see
            # the new row and mistake it for the thing being superseded.
            was_already_reviewed = visit_model.review_status == ReviewStatus.reviewed.value
            prior_effective_label = (
                self._current_effective_review_label_model_for_visit(session, visit_model.id)
                if was_already_reviewed
                else None
            )

            session.add(label_model)
            visit_model.reviewed_label = normalized_label
            visit_model.review_status = ReviewStatus.reviewed.value
            review_moment = created_at or datetime.now(UTC)
            if prior_effective_label is not None:
                self._retract_scene_confusor_region_contribution(
                    session, prior_effective_label, now=review_moment,
                )
            # Scene confusor reviewed-truth interaction (see docs/scene-
            # confusor-suspicion-contract.md): reached only for an
            # authority-eligible review (this branch already required
            # `is_authoritative` above -- an agent-diagnostic or omitted-
            # provenance review never reaches here, so it can never
            # protect or strengthen a region either). A no-op for any
            # non-Stage-7 Visit or one with no recurring history yet.
            self._update_scene_confusor_region_from_review(
                session, visit_model, normalized_label, now=review_moment, label_model=label_model,
            )

            if event_model is not None:
                child_visits = self._visit_models_for_event(session, event_model.id)
                if all(
                    child_visit.review_status != ReviewStatus.needs_review.value
                    for child_visit in child_visits
                ):
                    event_model.review_status = ReviewStatus.reviewed.value
                event = self._event_from_model(session, event_model)

            visit = _visit_from_model(visit_model)

        elif payload.target_type == "event":
            event_model = session.get(EventModel, payload.target_id)
            if event_model is None:
                raise ValueError("missing_event")

            session.add(label_model)
            if is_authoritative:
                event_model.review_status = ReviewStatus.reviewed.value
            event = self._event_from_model(session, event_model)
        else:
            raise ValueError("unsupported_target")

        session.flush()
        if payload.target_type == "visit" and is_authoritative:
            current_visit = session.get(VisitModel, payload.target_id)
            if current_visit is not None:
                now = created_at or datetime.now(UTC)
                self._sync_review_alert(session, current_visit, now)
                self._sync_journal_milestone_alert(session, current_visit, now)
                if prior_reviewed_label and prior_reviewed_label != normalized_label:
                    self._maybe_resolve_stale_journal_milestone_alert(
                        session, old_label=prior_reviewed_label, now=now,
                    )
        return _review_label_from_model(label_model), visit, event

    def _review_queue_bulk_correction_skip_reason(
        self,
        session: Session,
        target_type: ReviewQueueBulkCorrectionTargetType,
        target_id: str,
    ) -> str | None:
        if target_type == ReviewQueueBulkCorrectionTargetType.visit:
            visit_model = session.get(VisitModel, target_id)
            if visit_model is None:
                return "Visit was not found."
            if visit_model.is_superseded:
                return "Visit was superseded by curation and is retained only in history."
            if visit_model.review_status != ReviewStatus.needs_review.value:
                return "Visit is already reviewed or not eligible for Review Queue correction."
            if session.get(EventModel, visit_model.event_id) is None:
                return "Visit Event was not found."
            return None

        event_model = session.get(EventModel, target_id)
        if event_model is None:
            return "Event was not found."
        if event_model.review_status != ReviewStatus.needs_review.value:
            return "Event is already reviewed or not eligible for Review Queue correction."
        if any(
            visit.review_status == ReviewStatus.needs_review.value
            for visit in self._visit_models_for_event(session, event_model.id)
        ):
            return "Event has reviewable Visits; correct Visits first."
        return None

    def _event_from_model(self, session: Session, event: EventModel) -> Event:
        detections = session.scalars(
            select(DetectionModel)
            .where(DetectionModel.event_id == event.id)
            .order_by(DetectionModel.id)
        ).all()
        return Event(
            id=event.id,
            stream_id=event.stream_id,
            title=event.title,
            event_type=event.event_type,
            started_at=_as_utc(event.started_at),
            ended_at=_as_utc(event.ended_at) if event.ended_at else None,
            primary_zone_id=event.primary_zone_id,
            review_status=ReviewStatus(event.review_status),
            detections=[_detection_from_model(detection) for detection in detections],
        )

    def _has_authoritative_review_label(self, labels: list[ReviewLabelModel]) -> bool:
        return any(review_provenance.is_authority_eligible(label.review_origin) for label in labels)

    def _visit_is_dataset_ready(self, session: Session, visit: Visit) -> bool:
        # Defense in depth (Part 7 hardening, docs/review-decision-
        # provenance-contract.md): `review_status`/`reviewed_label` should
        # only ever be set together by an authoritative write (see
        # `_create_review_label_in_session`), so this condition is expected
        # to be structurally redundant with the fallback existence checks
        # below -- but a reviewed-only Dataset Export promises human-
        # reviewed truth, so this function re-verifies the fallback
        # against actual origin rather than trusting bare row existence.
        visit_model = session.get(VisitModel, visit.id)
        if visit_model is None or visit_model.is_superseded:
            return False
        return visit.review_status == ReviewStatus.reviewed and (
            visit.reviewed_label is not None
            or self._has_authoritative_review_label(self._review_label_models_for_visit(session, visit.id))
            or self._has_authoritative_review_label(self._review_label_models_for_event(session, visit.event_id))
        )

    def _event_is_dataset_ready(self, session: Session, event: Event) -> bool:
        visits = self._visits_for_event(session, event.id)
        if visits:
            return all(self._visit_is_dataset_ready(session, visit) for visit in visits)

        if session.scalar(
            select(func.count(VisitModel.id)).where(VisitModel.event_id == event.id)
        ):
            return False

        return event.review_status == ReviewStatus.reviewed and self._has_authoritative_review_label(
            self._review_label_models_for_event(session, event.id)
        )

    def _latest_label(self, labels: list[ReviewLabel]) -> str | None:
        """The latest *authoritative* label among the given ReviewLabels --
        every caller uses this to resolve an effective truth label (export,
        classifier manifests, dataset quality), so a non-authoritative
        diagnostic assessment must never win here even if it is the most
        recent row. See docs/review-decision-provenance-contract.md."""

        eligible = [label for label in labels if label.is_authoritative]
        if not eligible:
            return None
        return max(eligible, key=lambda label: label.created_at).label

    def _adapter_evaluation_item(
        self,
        session: Session,
        *,
        proposal_model: DetectionProposalModel,
        adapter: ModelAdapter | None,
    ) -> AdapterEvaluationItem:
        proposal_label = self._normalize_label_from_session(session, proposal_model.label)
        reviewed_label, review_status = self._proposal_review_truth(session, proposal_model)

        if proposal_model.status == DetectionProposalStatus.rejected.value:
            outcome = AdapterEvaluationOutcome.rejected_evidence
            review_status = ReviewStatus.rejected
        elif reviewed_label is None:
            outcome = (
                AdapterEvaluationOutcome.converted_needs_review
                if proposal_model.event_id is not None or proposal_model.visit_id is not None
                else AdapterEvaluationOutcome.awaiting_review
            )
        elif reviewed_label in {"unknown_bird", "unknown_animal"}:
            outcome = AdapterEvaluationOutcome.unknown_reviewed_label
        elif reviewed_label == proposal_label:
            outcome = AdapterEvaluationOutcome.matched_reviewed_truth
        else:
            outcome = AdapterEvaluationOutcome.mismatched_reviewed_truth

        return AdapterEvaluationItem(
            proposal_id=proposal_model.id,
            detection_run_id=proposal_model.run_id,
            adapter_id=adapter.id if adapter else None,
            media_asset_id=proposal_model.media_asset_id,
            event_id=proposal_model.event_id,
            visit_id=proposal_model.visit_id,
            proposal_label=proposal_label,
            proposal_display_name=self._display_name_for_label(session, proposal_label),
            proposal_confidence=proposal_model.confidence,
            reviewed_label=reviewed_label,
            reviewed_display_name=(
                self._display_name_for_label(session, reviewed_label)
                if reviewed_label is not None
                else None
            ),
            review_status=review_status,
            outcome=outcome,
            notes=_adapter_evaluation_note(outcome),
        )

    def _proposal_review_truth(
        self,
        session: Session,
        proposal_model: DetectionProposalModel,
    ) -> tuple[str | None, ReviewStatus]:
        if proposal_model.visit_id is not None:
            visit_model = session.get(VisitModel, proposal_model.visit_id)
            if visit_model is not None:
                if visit_model.is_superseded:
                    return None, ReviewStatus.needs_review
                visit_status = ReviewStatus(visit_model.review_status)
                visit_label = visit_model.reviewed_label or self._latest_label(
                    self._review_labels_for_visit(session, visit_model.id)
                )
                if visit_status == ReviewStatus.reviewed and visit_label is not None:
                    return self._normalize_label_from_session(session, visit_label), visit_status

                event_model = session.get(EventModel, visit_model.event_id)
                if event_model is not None:
                    event_status = ReviewStatus(event_model.review_status)
                    event_label = self._latest_label(
                        self._review_labels_for_event(session, event_model.id)
                    )
                    if event_status == ReviewStatus.reviewed and event_label is not None:
                        return (
                            self._normalize_label_from_session(session, event_label),
                            event_status,
                        )
                return None, visit_status

        if proposal_model.event_id is not None:
            event_model = session.get(EventModel, proposal_model.event_id)
            if event_model is not None:
                event_status = ReviewStatus(event_model.review_status)
                event_label = self._latest_label(
                    self._review_labels_for_event(session, event_model.id)
                )
                if event_status == ReviewStatus.reviewed and event_label is not None:
                    return self._normalize_label_from_session(session, event_label), event_status
                return None, event_status

        return None, ReviewStatus.needs_review

    def _display_name_for_label(self, session: Session, label: str) -> str:
        taxonomy_label = self._taxonomy_label_model_for_input(session, label)
        if taxonomy_label is not None:
            return _taxonomy_label_from_model(taxonomy_label).display_name
        return _display_name_from_label(label)

    def _zone_context(
        self,
        session: Session,
        zone_id: str | None,
    ) -> tuple[str | None, str | None, ZoneType | None]:
        if zone_id is None:
            return None, None, None

        zone = session.get(ZoneModel, zone_id)
        if zone is None:
            return zone_id, None, None

        zone_schema = _zone_from_model(zone)
        return zone_schema.id, zone_schema.name, zone_schema.zone_type

    def _visit_export_record(
        self,
        session: Session,
        visit: Visit,
        event: Event,
        stream: Stream,
        export: DatasetExport,
    ) -> DatasetExportRecord:
        zone_id, zone_name, zone_type = (
            self._zone_context(session, visit.zone_id or event.primary_zone_id)
            if export.include_zone_context
            else (None, None, None)
        )
        label = (
            visit.reviewed_label
            or self._latest_label(self._review_labels_for_visit(session, visit.id))
            or self._latest_label(self._review_labels_for_event(session, event.id))
            or visit.species_guess
            or visit.subject_label
        )
        taxonomy_label = self._taxonomy_label_model_for_input(session, label)
        taxonomy = _taxonomy_label_from_model(taxonomy_label) if taxonomy_label else None

        return DatasetExportRecord(
            record_id=f"record-{visit.id}",
            event_id=event.id,
            visit_id=visit.id,
            stream_id=event.stream_id,
            source_id=stream.source_id,
            label=label,
            label_display_name=taxonomy.display_name if taxonomy else None,
            label_category=taxonomy.category if taxonomy else None,
            is_species=taxonomy.is_species if taxonomy else None,
            subject_label=visit.subject_label,
            zone_id=zone_id,
            zone_name=zone_name,
            zone_type=zone_type,
            reviewed=visit.review_status == ReviewStatus.reviewed,
            dataset_ready=self._visit_is_dataset_ready(session, visit),
            media_path=visit.representative_media_path,
            started_at=event.started_at,
            detections=event.detections if export.include_detections else [],
        )

    def _event_export_record(
        self,
        session: Session,
        event: Event,
        stream: Stream,
        export: DatasetExport,
    ) -> DatasetExportRecord:
        zone_id, zone_name, zone_type = (
            self._zone_context(session, event.primary_zone_id)
            if export.include_zone_context
            else (None, None, None)
        )
        label = self._latest_label(self._review_labels_for_event(session, event.id)) or (
            event.detections[0].label if event.detections else event.event_type
        )
        taxonomy_label = self._taxonomy_label_model_for_input(session, label)
        taxonomy = _taxonomy_label_from_model(taxonomy_label) if taxonomy_label else None

        return DatasetExportRecord(
            record_id=f"record-{event.id}",
            event_id=event.id,
            visit_id=None,
            stream_id=event.stream_id,
            source_id=stream.source_id,
            label=label,
            label_display_name=taxonomy.display_name if taxonomy else None,
            label_category=taxonomy.category if taxonomy else None,
            is_species=taxonomy.is_species if taxonomy else None,
            subject_label=event.event_type,
            zone_id=zone_id,
            zone_name=zone_name,
            zone_type=zone_type,
            reviewed=event.review_status == ReviewStatus.reviewed,
            dataset_ready=self._event_is_dataset_ready(session, event),
            media_path=None,
            started_at=event.started_at,
            detections=event.detections if export.include_detections else [],
        )

    def _export_records_for_current_reviews(
        self,
        session: Session,
        export: DatasetExport,
    ) -> tuple[list[DatasetExportRecord], Counter[str]]:
        records: list[DatasetExportRecord] = []
        skipped_reasons: Counter[str] = Counter()
        visits = self._visits_for_eventless_query(session)
        selected_visit_ids = (
            set(export.selected_visit_ids)
            if export.selected_visit_ids is not None
            else None
        )
        event_ids_with_visits = {visit.event_id for visit in visits}
        event_ids_with_any_visits = set(session.scalars(select(VisitModel.event_id)).all())

        for visit in visits:
            if selected_visit_ids is not None and visit.id not in selected_visit_ids:
                continue
            event_model = session.get(EventModel, visit.event_id)
            if event_model is None:
                skipped_reasons["missing_event"] += 1
                continue

            event = self._event_from_model(session, event_model)
            stream_model = session.get(StreamModel, event.stream_id)
            if stream_model is None:
                skipped_reasons["missing_stream"] += 1
                continue
            stream = _stream_from_model(stream_model)

            dataset_ready = self._visit_is_dataset_ready(session, visit)
            if export.reviewed_only and not dataset_ready:
                skipped_reasons["needs_review"] += 1
                continue

            records.append(self._visit_export_record(session, visit, event, stream, export))

        event_ids_with_any_visits = set(session.scalars(select(VisitModel.event_id)).all())
        event_models = session.scalars(select(EventModel).order_by(EventModel.started_at)).all()
        for event_model in event_models:
            if selected_visit_ids is not None:
                continue
            if event_model.id in event_ids_with_visits or event_model.id in event_ids_with_any_visits:
                continue

            stream_model = session.get(StreamModel, event_model.stream_id)
            if stream_model is None:
                skipped_reasons["missing_stream"] += 1
                continue
            stream = _stream_from_model(stream_model)
            event = self._event_from_model(session, event_model)

            dataset_ready = self._event_is_dataset_ready(session, event)
            if export.reviewed_only and not dataset_ready:
                skipped_reasons["needs_review"] += 1
                continue

            records.append(self._event_export_record(session, event, stream, export))

        return records, skipped_reasons

    def _build_dataset_manifest_for_export(
        self,
        session: Session,
        dataset_export: DatasetExport,
    ) -> DatasetExportManifest:
        # Dataset manifests use corrections as truth, detections as evidence,
        # and imported media paths as local references.
        records, skipped_reasons = self._export_records_for_current_reviews(session, dataset_export)
        return DatasetExportManifest(
            export=dataset_export,
            records=records,
            skipped_count=sum(skipped_reasons.values()),
            skipped_reasons=dict(skipped_reasons),
            generated_at=datetime.now(UTC),
        )

    def _review_queue_items(
        self,
        session: Session,
        *,
        include_reviewed: bool = False,
    ) -> list[ReviewQueueItem]:
        queue: list[ReviewQueueItem] = []
        recency_by_item_id: dict[str, float] = {}
        visits = self._visits_for_eventless_query(session)

        # One coherent model-adapter/BioCLIP status snapshot for this whole
        # queue build, not one fresh (expensive local filesystem/model-
        # bundle validation) resolution per review item -- see
        # `_ReviewAdapterStatusContext`. This is the primary fix for the
        # BioCLIP Status / Review Queue Performance v1 defect: before it,
        # a ~87-item backlog performed on the order of ~200
        # `get_bioclip_status()` calls in one `dashboard_summary()`
        # request; status/model-bundle validation no longer scales with
        # review-item count.
        adapter_status = _ReviewAdapterStatusContext.resolve()

        for visit in visits:
            if visit.review_status != ReviewStatus.needs_review and not (
                include_reviewed and visit.review_status == ReviewStatus.reviewed
            ):
                continue

            event_model = session.get(EventModel, visit.event_id)
            if event_model is None:
                continue

            event = self._event_from_model(session, event_model)
            zone_id, zone_name, zone_type = self._zone_context(
                session,
                visit.zone_id or event.primary_zone_id,
            )
            suggestion_model = session.scalars(
                select(SpeciesSuggestionModel)
                .where(
                    SpeciesSuggestionModel.visit_id == visit.id,
                    SpeciesSuggestionModel.status == SpeciesSuggestionStatus.pending.value,
                )
                .order_by(
                    SpeciesSuggestionModel.created_at.desc(),
                    SpeciesSuggestionModel.rank,
                    SpeciesSuggestionModel.id.desc(),
                )
            ).first()
            suggestion = (
                _species_suggestion_from_model(suggestion_model)
                if suggestion_model is not None
                else None
            )
            stream_name, source_id, source_name = self._review_queue_stream_context(
                session,
                event.stream_id,
            )
            visit_model = session.get(VisitModel, visit.id)
            if visit_model is None:
                continue
            evidence_frames = self._visit_evidence_frames_from_visit(
                session,
                visit_model,
                event_model,
            )
            media_asset = self._media_asset_for_path_from_session(
                session,
                visit.representative_media_path,
            )
            evidence = self._motion_evidence_for_review_queue_item(
                session,
                event_id=event.id,
                visit_id=visit.id,
                media_asset_id=media_asset.id if media_asset else None,
            )
            if media_asset is None and evidence is None and evidence_frames:
                # Stage 7 candidate Visits (and any future Visit-evidence-link
                # -only creation path) have neither a legacy
                # `representative_media_path` nor MotionEvidence -- their
                # evidence lives only in `VisitEvidenceLinkModel` rows,
                # already resolved into `evidence_frames` above. Reuse the
                # same primary-link fact the Visit was actually created with
                # instead of leaving the review card with no image at all.
                # Existing Visits with either signal already set are
                # untouched: this branch only runs when both are absent.
                primary_frame = next(
                    (frame for frame in evidence_frames if frame.is_primary),
                    evidence_frames[0],
                )
                primary_model = session.get(MediaAssetModel, primary_frame.media_asset_id)
                media_asset = (
                    _media_asset_from_model(primary_model) if primary_model is not None else None
                )
            activity_context = self._review_queue_activity_context(evidence)
            best_media_asset_id = (
                media_asset.id
                if media_asset is not None
                else evidence.snapshot_media_asset_id
                if evidence is not None
                else None
            )
            focus_crop_context = self._review_focus_crop_context(
                session,
                zone_id=zone_id,
                media_asset_id=best_media_asset_id,
                evidence=evidence,
            )
            queue_item = ReviewQueueItem(
                id=f"review-queue-{visit.id}",
                item_type="visit",
                target_type="visit",
                target_id=visit.id,
                title=f"Review {visit.subject_label} visit",
                stream_id=event.stream_id,
                stream_name=stream_name,
                source_id=source_id,
                source_name=source_name,
                event_id=event.id,
                visit_id=visit.id,
                primary_zone_id=zone_id,
                primary_zone_name=zone_name,
                primary_zone_type=zone_type,
                zone_id=zone_id,
                zone_name=zone_name,
                zone_type=zone_type,
                best_media_asset_id=best_media_asset_id,
                **activity_context,
                suggested_label=(
                    suggestion.suggested_label
                    if suggestion is not None
                    else visit.species_guess or visit.subject_label
                ),
                suggestion_id=suggestion.id if suggestion is not None else None,
                suggestion_confidence=(
                    suggestion.confidence if suggestion is not None else None
                ),
                suggestion_reason=suggestion.notes if suggestion is not None else None,
                suggestion_creates_truth=False,
                **_review_focus_crop_fields(focus_crop_context),
                media_asset=media_asset,
                evidence_frames=evidence_frames,
                effective_primary=self._effective_primary_preview_from_visit(session, visit_model),
                stale_species_suggestions=self._visit_has_stale_species_suggestions(
                    session,
                    visit_id=visit.id,
                    effective_media_asset_id=best_media_asset_id,
                ),
                review_status=visit.review_status,
                reviewed_label=visit.reviewed_label,
                review_state_token=self._review_state_token(session, "visit", visit.id),
                reason="Confirm or correct the suggested species label.",
                **_review_queue_product_context(
                    session=session,
                    stream_id=event.stream_id,
                    evidence=evidence,
                    review_status=visit.review_status,
                    media_asset=media_asset,
                    evidence_frames=evidence_frames,
                    fallback_captured_at=event.started_at,
                    event_type=event.event_type,
                    subject_label=visit.subject_label,
                ),
            )
            queue_item.identification = self._review_identification_summary_for_item(
                session,
                queue_item,
                adapter_status=adapter_status,
            )
            queue.append(queue_item)
            recency_by_item_id[queue_item.id] = _review_queue_timestamp(event.started_at)

        visit_event_ids = {item.event_id for item in queue if item.event_id is not None}
        event_ids_with_historical_visits = set(
            session.scalars(select(VisitModel.event_id)).all()
        )
        event_models = session.scalars(select(EventModel).order_by(EventModel.started_at)).all()
        for event_model in event_models:
            event = self._event_from_model(session, event_model)
            if (
                (
                    event.review_status != ReviewStatus.needs_review
                    and not (
                        include_reviewed and event.review_status == ReviewStatus.reviewed
                    )
                )
                or event.id in visit_event_ids
                or event.id in event_ids_with_historical_visits
            ):
                continue
            zone_id, zone_name, zone_type = self._zone_context(session, event.primary_zone_id)
            stream_name, source_id, source_name = self._review_queue_stream_context(
                session,
                event.stream_id,
            )
            evidence = self._motion_evidence_for_review_queue_item(
                session,
                event_id=event.id,
                visit_id=None,
                media_asset_id=None,
            )
            media_asset_model = (
                session.get(MediaAssetModel, evidence.snapshot_media_asset_id)
                if evidence is not None and evidence.snapshot_media_asset_id is not None
                else None
            )
            media_asset = _media_asset_from_model(media_asset_model) if media_asset_model else None
            activity_context = self._review_queue_activity_context(evidence)
            best_media_asset_id = (
                media_asset.id
                if media_asset is not None
                else evidence.snapshot_media_asset_id
                if evidence is not None
                else None
            )
            focus_crop_context = self._review_focus_crop_context(
                session,
                zone_id=zone_id,
                media_asset_id=best_media_asset_id,
                evidence=evidence,
            )
            event_effective_label = (
                self._current_effective_review_label_model_for_event(session, event.id)
                if event.review_status == ReviewStatus.reviewed.value
                else None
            )
            event_reviewed_label = (
                event_effective_label.label if event_effective_label is not None else None
            )

            queue_item = ReviewQueueItem(
                id=f"review-queue-{event.id}",
                item_type="event",
                target_type="event",
                target_id=event.id,
                title=event.title,
                stream_id=event.stream_id,
                stream_name=stream_name,
                source_id=source_id,
                source_name=source_name,
                event_id=event.id,
                visit_id=None,
                primary_zone_id=zone_id,
                primary_zone_name=zone_name,
                primary_zone_type=zone_type,
                zone_id=zone_id,
                zone_name=zone_name,
                zone_type=zone_type,
                best_media_asset_id=best_media_asset_id,
                **activity_context,
                suggested_label=event.detections[0].label if event.detections else None,
                **_review_focus_crop_fields(focus_crop_context),
                media_asset=media_asset,
                review_status=event.review_status,
                reviewed_label=event_reviewed_label,
                review_state_token=self._review_state_token(session, "event", event.id),
                reason="Review detected outdoor activity and correct the event meaning.",
                **_review_queue_product_context(
                    session=session,
                    stream_id=event.stream_id,
                    evidence=evidence,
                    review_status=event.review_status,
                    media_asset=media_asset,
                    evidence_frames=[],
                    fallback_captured_at=event.started_at,
                    event_type=event.event_type,
                ),
            )
            queue_item.identification = self._review_identification_summary_for_item(
                session,
                queue_item,
                adapter_status=adapter_status,
            )
            queue.append(queue_item)
            recency_by_item_id[queue_item.id] = _review_queue_timestamp(event.started_at)

        # Fresh outdoor activity is the user's next decision. Keep new live
        # candidates ahead of sample and older unresolved items without changing
        # any review status, evidence, or truth boundary.
        return sorted(
            queue,
            key=lambda item: (recency_by_item_id.get(item.id, 0.0), item.id),
            reverse=True,
        )

    def _dataset_quality_summary(self, session: Session) -> DatasetQualitySummary:
        issues: list[DatasetQualityIssue] = []
        export_ready_count = 0
        needs_review_count = 0

        def add_issue(
            *,
            severity: str,
            issue_type: str,
            title: str,
            description: str,
            target_type: str,
            target_id: str,
            suggested_action: str,
            event_id: str | None = None,
            visit_id: str | None = None,
            media_asset_id: str | None = None,
            label: str | None = None,
        ) -> None:
            issues.append(
                DatasetQualityIssue(
                    id=f"quality-{issue_type}-{target_type}-{target_id}",
                    severity=severity,
                    issue_type=issue_type,
                    title=title,
                    description=description,
                    target_type=target_type,
                    target_id=target_id,
                    event_id=event_id,
                    visit_id=visit_id,
                    media_asset_id=media_asset_id,
                    label=label,
                    suggested_action=suggested_action,
                    link_path=f"{target_type}:{target_id}",
                )
            )

        def has_conflicting_corrections(labels: list[ReviewLabelModel]) -> bool:
            # Only authoritative corrections can conflict with each other in
            # a way that needs human cleanup attention -- a diagnostic
            # assessment honestly disagreeing with the actual reviewed
            # label is expected, not a data-quality problem. See
            # docs/review-decision-provenance-contract.md.
            #
            # Callers must pass raw per-target history (`_review_label_
            # history_models_for_visit`/`_for_event`), never the collapsed
            # single-effective-row view `_review_label_models_for_visit`/
            # `_for_event` return -- `_effective_review_label_models`
            # resolves history down to exactly one current row per target
            # by design, so it can structurally never contain two rows to
            # disagree with each other. Two independent, unlinked plain
            # corrections (no `supersedes_review_label_id`/`revision_
            # idempotency_key` connecting them) are exactly the case this
            # exists to catch.
            normalized_labels = {
                self._normalize_label_from_session(session, label.label)
                for label in labels
                if review_provenance.is_authority_eligible(label.review_origin)
            }
            return len(normalized_labels) > 1

        def add_record_issues(
            *,
            target_type: str,
            target_id: str,
            event: Event,
            visit_id: str | None,
            label: str,
            has_review_truth: bool,
            dataset_ready: bool,
            media_path: str | None,
            media_asset_id: str | None,
            review_label_models: list[ReviewLabelModel],
            review_label_history_models: list[ReviewLabelModel],
        ) -> None:
            nonlocal export_ready_count
            nonlocal needs_review_count

            normalized_label = self._normalize_label_from_session(session, label)
            taxonomy_label = self._taxonomy_label_model_for_input(session, normalized_label)

            if dataset_ready:
                export_ready_count += 1
            else:
                needs_review_count += 1
                add_issue(
                    severity="high",
                    issue_type="needs_review",
                    title="Review needed before export",
                    description=(
                        "This record is not export-ready because corrected labels are not "
                        "available as local dataset truth yet."
                    ),
                    target_type=target_type,
                    target_id=target_id,
                    event_id=event.id,
                    visit_id=visit_id,
                    media_asset_id=media_asset_id,
                    label=normalized_label,
                    suggested_action="Open the Review Queue and save a corrected label.",
                )

            if normalized_label in {"unknown_bird", "unknown_animal"}:
                add_issue(
                    severity="medium",
                    issue_type="unknown_label",
                    title="Unknown label needing review",
                    description=(
                        f"{_display_name_from_label(normalized_label)} is useful as a "
                        "temporary review label, but should be resolved before clean exports."
                    ),
                    target_type=target_type,
                    target_id=target_id,
                    event_id=event.id,
                    visit_id=visit_id,
                    media_asset_id=media_asset_id,
                    label=normalized_label,
                    suggested_action="Resolve the unknown label to a reviewed species or activity label.",
                )

            if has_review_truth and taxonomy_label is None:
                add_issue(
                    severity="low",
                    issue_type="freeform_label",
                    title="Freeform label outside taxonomy",
                    description=(
                        "This corrected label is allowed, but it is not part of the current "
                        "taxonomy and may need cleanup before future model work."
                    ),
                    target_type=target_type,
                    target_id=target_id,
                    event_id=event.id,
                    visit_id=visit_id,
                    media_asset_id=media_asset_id,
                    label=normalized_label,
                    suggested_action="Review whether this should map to an existing taxonomy label.",
                )

            if normalized_label == "false_positive":
                add_issue(
                    severity="low",
                    issue_type="false_positive",
                    title="False positive record",
                    description=(
                        "False positives are useful cleanup signals, but they should not be "
                        "treated as species truth."
                    ),
                    target_type=target_type,
                    target_id=target_id,
                    event_id=event.id,
                    visit_id=visit_id,
                    media_asset_id=media_asset_id,
                    label=normalized_label,
                    suggested_action="Keep as cleanup evidence or exclude from species-focused exports.",
                )

            zone_missing = event.primary_zone_id is None or session.get(ZoneModel, event.primary_zone_id) is None
            if dataset_ready and zone_missing:
                add_issue(
                    severity="medium",
                    issue_type="missing_zone",
                    title="Export-ready record missing zone context",
                    description=(
                        "This reviewed record can export, but zone context would make the "
                        "dataset easier to audit and compare."
                    ),
                    target_type=target_type,
                    target_id=target_id,
                    event_id=event.id,
                    visit_id=visit_id,
                    media_asset_id=media_asset_id,
                    label=normalized_label,
                    suggested_action="Add or choose zone context for future records when possible.",
                )

            imported_media_missing = (
                dataset_ready
                and media_path is not None
                and not media_path.startswith("demo://")
                and media_asset_id is None
            )
            if imported_media_missing:
                add_issue(
                    severity="medium",
                    issue_type="missing_media",
                    title="Reviewed record missing local media reference",
                    description=(
                        "This record looks like imported media, but the local media reference "
                        "is not attached to a media asset."
                    ),
                    target_type=target_type,
                    target_id=target_id,
                    event_id=event.id,
                    visit_id=visit_id,
                    media_asset_id=None,
                    label=normalized_label,
                    suggested_action="Recheck the local media reference before relying on this export record.",
                )

            if has_conflicting_corrections(review_label_history_models):
                add_issue(
                    severity="medium",
                    issue_type="conflicting_corrections",
                    title="Conflicting corrections",
                    description=(
                        "This target has multiple different correction labels. The latest "
                        "label is used as truth, but cleanup will make the dataset easier to trust."
                    ),
                    target_type=target_type,
                    target_id=target_id,
                    event_id=event.id,
                    visit_id=visit_id,
                    media_asset_id=media_asset_id,
                    label=normalized_label,
                    suggested_action="Review correction history and keep the intended final label.",
                )

        visits = self._visits_for_eventless_query(session)
        event_ids_with_visits = {visit.event_id for visit in visits}

        for visit in visits:
            event_model = session.get(EventModel, visit.event_id)
            if event_model is None or session.get(StreamModel, event_model.stream_id) is None:
                continue

            event = self._event_from_model(session, event_model)
            visit_labels = self._review_label_models_for_visit(session, visit.id)
            event_labels = self._review_label_models_for_event(session, event.id)
            label = (
                visit.reviewed_label
                or self._latest_label([_review_label_from_model(label) for label in visit_labels])
                or self._latest_label([_review_label_from_model(label) for label in event_labels])
                or visit.species_guess
                or visit.subject_label
            )
            media_asset = self._media_asset_for_path_from_session(
                session,
                visit.representative_media_path,
            )
            visit_dataset_ready = self._visit_is_dataset_ready(session, visit)
            add_record_issues(
                target_type="visit",
                target_id=visit.id,
                event=event,
                visit_id=visit.id,
                label=label,
                # `dataset_ready` already means "review_status is reviewed
                # AND an authoritative label backs it" -- reuse it rather
                # than recomputing a second, looser existence check that a
                # non-authoritative diagnostic row alone could satisfy. See
                # docs/review-decision-provenance-contract.md.
                has_review_truth=visit_dataset_ready,
                dataset_ready=visit_dataset_ready,
                media_path=visit.representative_media_path,
                media_asset_id=media_asset.id if media_asset else None,
                review_label_models=visit_labels,
                review_label_history_models=self._review_label_history_models_for_visit(
                    session, visit.id
                ),
            )

        event_models = session.scalars(select(EventModel).order_by(EventModel.started_at)).all()
        for event_model in event_models:
            if event_model.id in event_ids_with_visits or event_model.id in event_ids_with_any_visits:
                continue
            if session.get(StreamModel, event_model.stream_id) is None:
                continue

            event = self._event_from_model(session, event_model)
            event_labels = self._review_label_models_for_event(session, event.id)
            label = self._latest_label([_review_label_from_model(label) for label in event_labels]) or (
                event.detections[0].label if event.detections else event.event_type
            )
            event_dataset_ready = self._event_is_dataset_ready(session, event)
            add_record_issues(
                target_type="event",
                target_id=event.id,
                event=event,
                visit_id=None,
                label=label,
                has_review_truth=event_dataset_ready,
                dataset_ready=event_dataset_ready,
                media_path=None,
                media_asset_id=None,
                review_label_models=event_labels,
                review_label_history_models=self._review_label_history_models_for_event(
                    session, event.id
                ),
            )

        severity_counts = Counter(issue.severity for issue in issues)
        type_counts = Counter(issue.issue_type for issue in issues)
        return DatasetQualitySummary(
            issue_count=len(issues),
            high_count=severity_counts["high"],
            medium_count=severity_counts["medium"],
            low_count=severity_counts["low"],
            freeform_label_count=type_counts["freeform_label"],
            unknown_label_count=type_counts["unknown_label"],
            missing_zone_count=type_counts["missing_zone"],
            missing_media_count=type_counts["missing_media"],
            conflicting_correction_count=type_counts["conflicting_corrections"],
            false_positive_count=type_counts["false_positive"],
            export_ready_count=export_ready_count,
            needs_review_count=needs_review_count,
            # Every count above already reflects the complete, untruncated
            # `issues` list; only the detailed list actually returned for
            # display is bounded, so a large real history cannot make the
            # page itself unbounded (see MAX_DATASET_QUALITY_ISSUES).
            issues=sorted(
                issues, key=lambda issue: (issue.severity, issue.issue_type, issue.target_id)
            )[:MAX_DATASET_QUALITY_ISSUES],
            generated_at=datetime.now(UTC),
            local_first_note=(
                "Dataset QA uses corrected labels as local dataset truth. Detection and "
                "proposal labels remain evidence until review; QA highlights cleanup targets "
                "for exports and coverage for future model work."
            ),
        )

    def _dataset_coverage_summary(self, session: Session) -> DatasetCoverageSummary:
        coverage: dict[str, _CoverageAccumulator] = {}
        target_species_models = session.scalars(
            select(TaxonomyLabelModel)
            .where(
                TaxonomyLabelModel.category == LabelCategory.bird.value,
                TaxonomyLabelModel.is_species.is_(True),
            )
            .order_by(TaxonomyLabelModel.sort_order, TaxonomyLabelModel.display_name)
        ).all()
        target_species_labels = [label.label for label in target_species_models]
        target_sort_order = {
            label.label: label.sort_order if label.sort_order is not None else 999_999
            for label in target_species_models
        }

        def ensure_coverage(input_label: str) -> _CoverageAccumulator:
            normalized_label = self._normalize_label_from_session(session, input_label)
            if normalized_label in coverage:
                return coverage[normalized_label]

            taxonomy_label = self._taxonomy_label_model_for_input(session, normalized_label)
            if taxonomy_label is not None:
                taxonomy = _taxonomy_label_from_model(taxonomy_label)
                accumulator = _CoverageAccumulator(
                    label=taxonomy.label,
                    display_name=taxonomy.display_name,
                    category=taxonomy.category.value,
                    is_species=taxonomy.is_species,
                )
            else:
                accumulator = _CoverageAccumulator(
                    label=normalized_label,
                    display_name=_display_name_from_label(normalized_label),
                    category="custom",
                    is_species=False,
                )
            coverage[accumulator.label] = accumulator
            return accumulator

        for target in target_species_models:
            ensure_coverage(target.label)

        reviewed_record_count = 0
        export_ready_count = 0
        needs_review_count = 0
        unknown_bird_count = 0
        unknown_animal_count = 0
        false_positive_count = 0

        def add_coverage_record(
            *,
            label: str,
            dataset_ready: bool,
            media_path: str | None,
            seen_at: datetime,
        ) -> None:
            nonlocal reviewed_record_count
            nonlocal export_ready_count
            nonlocal needs_review_count
            nonlocal unknown_bird_count
            nonlocal unknown_animal_count
            nonlocal false_positive_count

            item = ensure_coverage(label)
            if dataset_ready:
                item.reviewed_record_count += 1
                item.export_ready_count += 1
                reviewed_record_count += 1
                export_ready_count += 1
            else:
                item.needs_review_count += 1
                needs_review_count += 1

            if item.label in {"unknown_bird", "unknown_animal"}:
                item.unknown_count += 1
            if item.label == "unknown_bird":
                unknown_bird_count += 1
            elif item.label == "unknown_animal":
                unknown_animal_count += 1
            elif item.label == "false_positive":
                false_positive_count += 1

            if media_path and self._media_asset_for_path_from_session(session, media_path) is not None:
                item.media_asset_count += 1

            seen_at = _as_utc(seen_at)
            item.first_seen_at = (
                seen_at
                if item.first_seen_at is None or seen_at < item.first_seen_at
                else item.first_seen_at
            )
            item.last_seen_at = (
                seen_at
                if item.last_seen_at is None or seen_at > item.last_seen_at
                else item.last_seen_at
            )

        visits = self._visits_for_eventless_query(session)
        event_ids_with_visits = {visit.event_id for visit in visits}
        event_ids_with_any_visits = set(session.scalars(select(VisitModel.event_id)).all())

        for visit in visits:
            event_model = session.get(EventModel, visit.event_id)
            if event_model is None or session.get(StreamModel, event_model.stream_id) is None:
                continue

            event = self._event_from_model(session, event_model)
            label = (
                visit.reviewed_label
                or self._latest_label(self._review_labels_for_visit(session, visit.id))
                or self._latest_label(self._review_labels_for_event(session, event.id))
                or visit.species_guess
                or visit.subject_label
            )
            add_coverage_record(
                label=label,
                dataset_ready=self._visit_is_dataset_ready(session, visit),
                media_path=visit.representative_media_path,
                seen_at=event.started_at,
            )

        event_models = session.scalars(select(EventModel).order_by(EventModel.started_at)).all()
        for event_model in event_models:
            if event_model.id in event_ids_with_visits or event_model.id in event_ids_with_any_visits:
                continue
            if session.get(StreamModel, event_model.stream_id) is None:
                continue

            event = self._event_from_model(session, event_model)
            label = self._latest_label(self._review_labels_for_event(session, event.id)) or (
                event.detections[0].label if event.detections else event.event_type
            )
            add_coverage_record(
                label=label,
                dataset_ready=self._event_is_dataset_ready(session, event),
                media_path=None,
                seen_at=event.started_at,
            )

        covered_target_species = [
            label
            for label in target_species_labels
            if coverage[label].reviewed_record_count > 0
        ]
        missing_target_species = [
            label
            for label in target_species_labels
            if coverage[label].reviewed_record_count == 0
        ]
        gaps = [
            DatasetCoverageGap(
                label=label,
                display_name=coverage[label].display_name,
                reason="missing_reviewed_examples",
                target_category=LabelCategory.bird.value,
            )
            for label in missing_target_species
        ]
        if unknown_bird_count > 0:
            gaps.append(
                DatasetCoverageGap(
                    label="unknown_bird",
                    display_name=ensure_coverage("unknown_bird").display_name,
                    reason="unknown_birds_need_review",
                    target_category=LabelCategory.bird.value,
                )
            )
        if unknown_animal_count > 0:
            gaps.append(
                DatasetCoverageGap(
                    label="unknown_animal",
                    display_name=ensure_coverage("unknown_animal").display_name,
                    reason="unknown_animals_need_review",
                    target_category=LabelCategory.unknown.value,
                )
            )

        species = [
            DatasetCoverageSpecies(
                label=item.label,
                display_name=item.display_name,
                category=item.category,
                is_species=item.is_species,
                reviewed_record_count=item.reviewed_record_count,
                export_ready_count=item.export_ready_count,
                needs_review_count=item.needs_review_count,
                unknown_count=item.unknown_count,
                media_asset_count=item.media_asset_count,
                first_seen_at=item.first_seen_at,
                last_seen_at=item.last_seen_at,
            )
            for item in sorted(
                coverage.values(),
                key=lambda item: (
                    0 if item.label in target_sort_order else 1,
                    target_sort_order.get(item.label, 999_999),
                    item.display_name,
                ),
            )
        ]

        return DatasetCoverageSummary(
            reviewed_record_count=reviewed_record_count,
            export_ready_count=export_ready_count,
            needs_review_count=needs_review_count,
            unknown_bird_count=unknown_bird_count,
            unknown_animal_count=unknown_animal_count,
            false_positive_count=false_positive_count,
            reviewed_species_count=sum(
                item.reviewed_record_count for item in coverage.values() if item.is_species
            ),
            target_species_count=len(target_species_labels),
            covered_target_species_count=len(covered_target_species),
            missing_target_species_count=len(missing_target_species),
            species=species,
            gaps=gaps,
            generated_at=datetime.now(UTC),
            local_first_note=(
                "Dataset coverage uses corrected labels as local dataset truth. "
                "Detection and proposal labels remain evidence until review; coverage is "
                "a signal for future model work and does not run training or classification."
            ),
        )

    def _classifier_readiness_report(self, session: Session) -> ClassifierReadinessReport:
        species_examples: dict[str, dict[str, int | list[str]]] = {}
        skipped_reasons: Counter[str] = Counter()
        warnings: list[str] = []
        reviewed_examples = 0
        media_backed_reviewed_examples = 0
        export_ready_examples = 0
        unknown_label_count = 0
        false_positive_count = 0
        out_of_taxonomy_count = 0
        low_example_threshold = 2
        minimum_species_threshold = 2

        target_species_models = session.scalars(
            select(TaxonomyLabelModel)
            .where(
                TaxonomyLabelModel.category == LabelCategory.bird.value,
                TaxonomyLabelModel.is_species.is_(True),
            )
            .order_by(TaxonomyLabelModel.sort_order, TaxonomyLabelModel.display_name)
        ).all()
        target_species_labels = [label.label for label in target_species_models]
        target_sort_order = {
            label.label: label.sort_order if label.sort_order is not None else 999_999
            for label in target_species_models
        }
        media_backed_target_counts: Counter[str] = Counter()

        def latest_label_from_models(labels: list[ReviewLabelModel]) -> str | None:
            return self._latest_label([_review_label_from_model(label) for label in labels])

        def has_conflicting_corrections(labels: list[ReviewLabelModel]) -> bool:
            # Only authoritative corrections can conflict with each other in
            # a way that needs human cleanup attention -- a diagnostic
            # assessment honestly disagreeing with the actual reviewed
            # label is expected, not a data-quality problem. See
            # docs/review-decision-provenance-contract.md.
            normalized_labels = {
                self._normalize_label_from_session(session, label.label)
                for label in labels
                if review_provenance.is_authority_eligible(label.review_origin)
            }
            return len(normalized_labels) > 1

        def add_skip(reason: str) -> None:
            skipped_reasons[reason] += 1

        def ensure_species_summary(label: str) -> dict[str, int | list[str]]:
            if label not in species_examples:
                species_examples[label] = {
                    "reviewed_examples": 0,
                    "media_backed_examples": 0,
                    "export_ready_examples": 0,
                    "warnings": [],
                }
            return species_examples[label]

        visits = self._visits_for_eventless_query(session)
        for visit in visits:
            event_model = session.get(EventModel, visit.event_id)
            if event_model is None or session.get(StreamModel, event_model.stream_id) is None:
                add_skip("insufficient_metadata")
                continue

            event = self._event_from_model(session, event_model)
            visit_labels = self._review_label_models_for_visit(session, visit.id)
            event_labels = self._review_label_models_for_event(session, event.id)
            label = (
                visit.reviewed_label
                or latest_label_from_models(visit_labels)
                or latest_label_from_models(event_labels)
            )
            dataset_ready = self._visit_is_dataset_ready(session, visit)

            if not dataset_ready:
                add_skip(
                    "unreviewed"
                    if visit.review_status != ReviewStatus.reviewed
                    else "missing_review_label"
                )
                continue

            if label is None:
                add_skip("missing_review_label")
                continue

            normalized_label = self._normalize_label_from_session(session, label)
            taxonomy_label = self._taxonomy_label_model_for_input(session, normalized_label)
            taxonomy = _taxonomy_label_from_model(taxonomy_label) if taxonomy_label else None
            media_asset = self._media_asset_for_path_from_session(
                session,
                visit.representative_media_path,
            )
            has_media_asset = media_asset is not None
            has_conflicts = has_conflicting_corrections(visit_labels) or (
                not visit_labels and has_conflicting_corrections(event_labels)
            )

            reviewed_examples += 1
            if has_media_asset:
                media_backed_reviewed_examples += 1
            else:
                add_skip("missing_media")

            if normalized_label in {"unknown_bird", "unknown_animal"}:
                unknown_label_count += 1
                add_skip("unknown_label")
            if normalized_label == "false_positive":
                false_positive_count += 1
                add_skip("false_positive_policy_excluded")
            if taxonomy is None:
                out_of_taxonomy_count += 1
                add_skip("out_of_taxonomy")
            if has_conflicts:
                add_skip("conflicting_corrections")

            is_known_species = (
                taxonomy is not None
                and taxonomy.category == LabelCategory.bird
                and taxonomy.is_species
            )
            if not is_known_species:
                continue

            species_summary = ensure_species_summary(taxonomy.label)
            species_summary["reviewed_examples"] = int(species_summary["reviewed_examples"]) + 1
            if has_media_asset:
                species_summary["media_backed_examples"] = (
                    int(species_summary["media_backed_examples"]) + 1
                )
                media_backed_target_counts[taxonomy.label] += 1
            if has_media_asset and not has_conflicts:
                species_summary["export_ready_examples"] = (
                    int(species_summary["export_ready_examples"]) + 1
                )
                export_ready_examples += 1

        species: list[ClassifierReadinessSpeciesSummary] = []
        for label, counts in species_examples.items():
            species_warnings = list(counts["warnings"])
            if int(counts["media_backed_examples"]) == 0:
                species_warnings.append("missing_media")
            if int(counts["export_ready_examples"]) < low_example_threshold:
                species_warnings.append("low_example_count")
            species.append(
                ClassifierReadinessSpeciesSummary(
                    label=label,
                    reviewed_examples=int(counts["reviewed_examples"]),
                    media_backed_examples=int(counts["media_backed_examples"]),
                    export_ready_examples=int(counts["export_ready_examples"]),
                    warnings=species_warnings,
                )
            )

        species.sort(
            key=lambda item: (
                target_sort_order.get(item.label, 999_999),
                _display_name_from_label(item.label),
            )
        )
        missing_target_labels = [
            label for label in target_species_labels if media_backed_target_counts[label] == 0
        ]

        covered_species_count = sum(
            1 for item in species if item.media_backed_examples > 0
        )
        if media_backed_reviewed_examples == 0:
            warnings.append(
                "No reviewed media-backed examples are ready for classifier manifest export."
            )
        if covered_species_count < minimum_species_threshold:
            warnings.append("Fewer than 2 taxonomy species have media-backed reviewed examples.")
        if any("low_example_count" in item.warnings for item in species):
            warnings.append("Some species have fewer than 2 media-backed reviewed examples.")
        if unknown_label_count > 0:
            warnings.append("Unknown labels need review before classifier export.")
        if false_positive_count > 0:
            warnings.append("False-positive labels are excluded from species classifier export.")
        if out_of_taxonomy_count > 0:
            warnings.append("Reviewed labels outside taxonomy need cleanup before classifier export.")
        if skipped_reasons["missing_media"] > 0:
            warnings.append("Some reviewed visits are missing MediaAsset-backed media references.")
        if skipped_reasons["conflicting_corrections"] > 0:
            warnings.append("Conflicting corrections should be cleaned before classifier export.")

        ready_for_manifest_export = export_ready_examples > 0
        if not ready_for_manifest_export:
            recommended_next_step = (
                "Review and correct media-backed visits with taxonomy species labels before "
                "classifier manifest export."
            )
        elif warnings:
            recommended_next_step = (
                "Safe next step: keep cleaning readiness warnings while implementing the "
                "manifest export foundation without training or model runtime."
            )
        else:
            recommended_next_step = (
                "Ready to implement classifier training manifest export foundation using "
                "reviewed correction truth only."
            )

        return ClassifierReadinessReport(
            ready_for_manifest_export=ready_for_manifest_export,
            reviewed_examples=reviewed_examples,
            media_backed_reviewed_examples=media_backed_reviewed_examples,
            export_ready_examples=export_ready_examples,
            species=species,
            missing_target_labels=missing_target_labels,
            unknown_label_count=unknown_label_count,
            false_positive_count=false_positive_count,
            out_of_taxonomy_count=out_of_taxonomy_count,
            skipped=[
                ClassifierReadinessSkipSummary(reason=reason, count=count)
                for reason, count in sorted(skipped_reasons.items())
            ],
            warnings=warnings,
            recommended_next_step=recommended_next_step,
        )

    def _classifier_training_manifest(
        self,
        session: Session,
    ) -> ClassifierTrainingManifestResponse:
        target_species_models = session.scalars(
            select(TaxonomyLabelModel)
            .where(
                TaxonomyLabelModel.category == LabelCategory.bird.value,
                TaxonomyLabelModel.is_species.is_(True),
            )
            .order_by(TaxonomyLabelModel.sort_order, TaxonomyLabelModel.display_name)
        ).all()
        target_species_labels = {label.label for label in target_species_models}
        taxonomy_entries = [
            ClassifierManifestTaxonomyEntry(
                label=label.label,
                taxonomy_id=label.id,
                common_name=label.display_name,
                scientific_name=label.scientific_name,
                aliases=list(_taxonomy_label_from_model(label).aliases),
            )
            for label in target_species_models
        ]
        example_payloads: list[dict[str, Any]] = []
        skipped_records: list[ClassifierManifestSkippedRecord] = []

        def latest_label_model(labels: list[ReviewLabelModel]) -> ReviewLabelModel | None:
            # Authoritative-only: this resolves the effective reviewed
            # label for classifier training eligibility, so a
            # non-authoritative diagnostic row must never win. See
            # docs/review-decision-provenance-contract.md.
            eligible = [label for label in labels if review_provenance.is_authority_eligible(label.review_origin)]
            if not eligible:
                return None
            return max(eligible, key=lambda label: (_as_utc(label.created_at), label.id))

        def has_conflicting_corrections(labels: list[ReviewLabelModel]) -> bool:
            # Only authoritative corrections can conflict with each other in
            # a way that needs human cleanup attention -- a diagnostic
            # assessment honestly disagreeing with the actual reviewed
            # label is expected, not a data-quality problem. See
            # docs/review-decision-provenance-contract.md.
            normalized_labels = {
                self._normalize_label_from_session(session, label.label)
                for label in labels
                if review_provenance.is_authority_eligible(label.review_origin)
            }
            return len(normalized_labels) > 1

        def add_skipped(
            *,
            visit: Visit,
            event_id: str | None,
            media_asset_id: str | None,
            label: str | None,
            reason: str,
            detail: str | None = None,
        ) -> None:
            skipped_records.append(
                ClassifierManifestSkippedRecord(
                    record_id=f"record-{visit.id}",
                    record_type="visit",
                    visit_id=visit.id,
                    event_id=event_id,
                    media_asset_id=media_asset_id,
                    label=label,
                    reason=reason,
                    detail=detail,
                )
            )

        def split_for_example(example_id: str, example_count: int) -> str:
            if example_count < 3:
                return "train"

            bucket = int(hashlib.sha256(example_id.encode("utf-8")).hexdigest()[:8], 16) % 100
            if bucket < 80:
                return "train"
            if bucket < 90:
                return "validation"
            return "test"

        for visit in self._visits_for_eventless_query(session):
            event_model = session.get(EventModel, visit.event_id)
            if event_model is None:
                add_skipped(
                    visit=visit,
                    event_id=visit.event_id,
                    media_asset_id=None,
                    label=visit.reviewed_label or visit.species_guess or visit.subject_label,
                    reason="insufficient_metadata",
                    detail="Visit event metadata is missing.",
                )
                continue

            stream_model = session.get(StreamModel, event_model.stream_id)
            if stream_model is None:
                add_skipped(
                    visit=visit,
                    event_id=event_model.id,
                    media_asset_id=None,
                    label=visit.reviewed_label or visit.species_guess or visit.subject_label,
                    reason="insufficient_metadata",
                    detail="Visit stream metadata is missing.",
                )
                continue

            event = self._event_from_model(session, event_model)
            stream = _stream_from_model(stream_model)
            zone_model = (
                session.get(ZoneModel, event.primary_zone_id)
                if event.primary_zone_id is not None
                else None
            )
            if zone_model is not None and zone_model.zone_type == ZoneType.privacy.value:
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=None,
                    label=visit.reviewed_label or visit.species_guess or visit.subject_label,
                    reason="privacy_zone",
                    detail="Privacy zone visits are excluded from classifier manifests.",
                )
                continue
            if zone_model is not None and zone_model.zone_type == ZoneType.ignore.value:
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=None,
                    label=visit.reviewed_label or visit.species_guess or visit.subject_label,
                    reason="ignore_zone",
                    detail="Ignore zone visits are excluded from classifier manifests.",
                )
                continue

            visit_labels = self._review_label_models_for_visit(session, visit.id)
            event_labels = self._review_label_models_for_event(session, event.id)
            review_label_model = latest_label_model(visit_labels) or latest_label_model(event_labels)
            label = visit.reviewed_label or (
                review_label_model.label if review_label_model is not None else None
            )
            fallback_label = label or visit.species_guess or visit.subject_label
            dataset_ready = self._visit_is_dataset_ready(session, visit)

            if not dataset_ready:
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=None,
                    label=fallback_label,
                    reason=(
                        "unreviewed"
                        if visit.review_status != ReviewStatus.reviewed
                        else "missing_review_label"
                    ),
                    detail="Only reviewed correction truth can enter classifier manifests.",
                )
                continue

            if label is None:
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=None,
                    label=fallback_label,
                    reason="missing_review_label",
                    detail="Reviewed visit has no correction label.",
                )
                continue

            normalized_label = self._normalize_label_from_session(session, label)
            has_conflicts = has_conflicting_corrections(visit_labels) or (
                not visit_labels and has_conflicting_corrections(event_labels)
            )
            if has_conflicts:
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=None,
                    label=normalized_label,
                    reason="conflicting_corrections",
                    detail="Multiple correction labels exist for this reviewed visit.",
                )
                continue
            if normalized_label in {"unknown_bird", "unknown_animal"}:
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=None,
                    label=normalized_label,
                    reason="unknown_label",
                    detail="Unknown reviewed labels are cleanup targets, not species examples.",
                )
                continue
            if normalized_label == "false_positive":
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=None,
                    label=normalized_label,
                    reason="false_positive_policy_excluded",
                    detail="False positives are excluded until a negative training policy exists.",
                )
                continue

            media_asset = self._media_asset_for_path_from_session(
                session,
                visit.representative_media_path,
            )
            if media_asset is None:
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=None,
                    label=normalized_label,
                    reason="missing_media",
                    detail="Visit has no existing MediaAsset-backed local media reference.",
                )
                continue
            if media_asset.media_type != "image":
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=media_asset.id,
                    label=normalized_label,
                    reason="unsupported_media_type",
                    detail="Initial classifier manifests include imported image media only.",
                )
                continue
            if media_asset.stream_id != stream.id:
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=media_asset.id,
                    label=normalized_label,
                    reason="insufficient_metadata",
                    detail="MediaAsset stream does not match the reviewed visit stream.",
                )
                continue

            taxonomy_label_model = self._taxonomy_label_model_for_input(session, normalized_label)
            taxonomy = (
                _taxonomy_label_from_model(taxonomy_label_model)
                if taxonomy_label_model
                else None
            )
            is_target_species = (
                taxonomy is not None
                and taxonomy.label in target_species_labels
                and taxonomy.category == LabelCategory.bird
                and taxonomy.is_species
            )
            if not is_target_species:
                add_skipped(
                    visit=visit,
                    event_id=event.id,
                    media_asset_id=media_asset.id,
                    label=normalized_label,
                    reason="out_of_taxonomy",
                    detail="Reviewed label is not a target bird species taxonomy label.",
                )
                continue

            example_id = f"classifier-example-{visit.id}"
            example_payloads.append(
                {
                    "example_id": example_id,
                    "visit_id": visit.id,
                    "event_id": event.id,
                    "media_asset_id": media_asset.id,
                    "source_id": media_asset.source_id or stream.source_id,
                    "stream_id": stream.id,
                    "zone_id": event.primary_zone_id,
                    "local_media_path": media_asset.local_path,
                    "label": taxonomy.label,
                    "taxonomy_id": taxonomy.id,
                    "common_name": taxonomy.display_name,
                    "scientific_name": taxonomy.scientific_name,
                    "reviewed_label_id": (
                        review_label_model.id if review_label_model is not None else None
                    ),
                    "reviewed_at": (
                        _as_utc(review_label_model.created_at).isoformat()
                        if review_label_model is not None
                        else None
                    ),
                    "created_at": _as_utc(event.started_at).isoformat(),
                    "quality_flags": [],
                    "provenance": {
                        "manifest_source": "classifier_training_manifest_preview",
                        "truth_source": "review_label",
                        "review_target_type": (
                            review_label_model.target_type
                            if review_label_model is not None
                            else "visit"
                        ),
                        "review_target_id": (
                            review_label_model.target_id
                            if review_label_model is not None
                            else visit.id
                        ),
                        "media_reference": "media_asset.local_path",
                        "evidence_only_sources": [
                            "SpeciesSuggestion",
                            "MotionEvidence",
                            "DetectionProposal",
                        ],
                    },
                }
            )

        example_count = len(example_payloads)
        examples = [
            ClassifierManifestExample(
                **payload,
                split=split_for_example(payload["example_id"], example_count),
            )
            for payload in example_payloads
        ]
        label_counts = Counter(example.label for example in examples)
        split_counts = Counter(example.split for example in examples)
        skip_counts = Counter(record.reason for record in skipped_records)
        warnings: list[str] = []

        if example_count == 0:
            warnings.append(
                "No reviewed media-backed bird species examples are ready for manifest export."
            )
        elif example_count < 3:
            warnings.append("Small manifest preview uses train split only until more examples exist.")
        elif {"train", "validation", "test"} - set(split_counts):
            warnings.append("Split coverage is limited; add more reviewed examples before training.")
        if skip_counts["missing_media"] > 0:
            warnings.append("Some reviewed visits are missing MediaAsset-backed media references.")
        if skip_counts["unknown_label"] > 0:
            warnings.append("Unknown labels need correction before classifier training.")
        if skip_counts["false_positive_policy_excluded"] > 0:
            warnings.append("False positives are excluded until negative training policy exists.")
        if skip_counts["out_of_taxonomy"] > 0:
            warnings.append("Some reviewed labels are outside target bird species taxonomy.")
        if skip_counts["conflicting_corrections"] > 0:
            warnings.append("Conflicting corrections should be cleaned before classifier export.")

        summary = ClassifierManifestSummary(
            examples=example_count,
            skipped=len(skipped_records),
            labels=dict(sorted(label_counts.items())),
            splits=dict(sorted(split_counts.items())),
            warnings=warnings,
        )

        return ClassifierTrainingManifestResponse(
            manifest_version="classifier-training-preview-v1",
            generated_at=datetime.now(UTC).isoformat(),
            examples=examples,
            skipped_records=skipped_records,
            taxonomy=taxonomy_entries,
            summary=summary,
            warnings=warnings,
        )

    def _write_classifier_manifest_export(
        self,
        payload: ClassifierManifestFileExportRequest,
        manifest: ClassifierTrainingManifestResponse,
    ) -> ClassifierManifestFileExportResponse:
        if payload.media_policy == "copy_media" and not payload.dry_run:
            raise ValueError("copy_media export is dry-run only in this phase.")

        created_at = datetime.now(UTC).isoformat()
        export_id = self._classifier_manifest_export_id(payload.output_name)
        file_names = self._classifier_manifest_export_file_names(payload)
        planned_media_files: list[ClassifierManifestPlannedMediaFile] = []
        skipped_media: list[ClassifierManifestSkippedMediaRecord] = []
        total_planned_media_bytes: int | None = None

        if payload.media_policy == "copy_media":
            (
                planned_media_files,
                skipped_media,
                total_planned_media_bytes,
            ) = self._plan_classifier_manifest_media_copy(manifest)

        if payload.dry_run:
            return ClassifierManifestFileExportResponse(
                export_id=export_id,
                output_directory=None,
                files=[
                    ClassifierManifestExportFile(
                        name=name,
                        relative_path=name,
                        content_type=CLASSIFIER_MANIFEST_EXPORT_CONTENT_TYPES[name],
                        size_bytes=None,
                    )
                    for name in file_names
                ],
                examples=len(manifest.examples),
                skipped=len(manifest.skipped_records),
                warnings=manifest.warnings,
                created_at=created_at,
                dry_run=True,
                media_policy=payload.media_policy,
                planned_media_files=planned_media_files,
                skipped_media=skipped_media,
                total_planned_media_bytes=total_planned_media_bytes,
            )

        export_root = self.classifier_manifest_export_root.resolve(strict=False)
        export_root.mkdir(parents=True, exist_ok=True)
        output_dir = self._classifier_manifest_output_dir(export_root, export_id)
        temporary_dir = self._classifier_manifest_output_dir(
            export_root,
            f".{export_id}.tmp",
        )
        if output_dir.exists() or temporary_dir.exists():
            raise ValueError("classifier manifest export directory already exists")

        temporary_dir.mkdir()
        try:
            self._write_classifier_manifest_files(
                temporary_dir,
                file_names,
                payload,
                manifest,
                export_id,
                created_at,
            )
            temporary_dir.rename(output_dir)
        except Exception:
            shutil.rmtree(temporary_dir, ignore_errors=True)
            raise

        return ClassifierManifestFileExportResponse(
            export_id=export_id,
            output_directory=str(output_dir),
            files=[
                ClassifierManifestExportFile(
                    name=name,
                    relative_path=name,
                    content_type=CLASSIFIER_MANIFEST_EXPORT_CONTENT_TYPES[name],
                    size_bytes=(output_dir / name).stat().st_size,
                )
                for name in file_names
            ],
            examples=len(manifest.examples),
            skipped=len(manifest.skipped_records),
            warnings=manifest.warnings,
            created_at=created_at,
            dry_run=False,
            media_policy=payload.media_policy,
            planned_media_files=[],
            skipped_media=[],
            total_planned_media_bytes=None,
        )

    def _classifier_manifest_export_id(self, output_name: str | None) -> str:
        base_name = output_name or "classifier-manifest"
        timestamp = datetime.now(UTC).strftime("%Y%m%dT%H%M%S%fZ")
        return f"{base_name}-{timestamp}-{uuid.uuid4().hex[:8]}"

    def _classifier_manifest_output_dir(self, export_root: Path, directory_name: str) -> Path:
        output_dir = (export_root / directory_name).resolve(strict=False)
        if not output_dir.is_relative_to(export_root):
            raise ValueError("classifier manifest export path must stay under the export root")
        return output_dir

    def _classifier_manifest_export_file_names(
        self,
        payload: ClassifierManifestFileExportRequest,
    ) -> list[str]:
        file_names = [
            "manifest.jsonl",
            "taxonomy.json",
            "skipped_records.jsonl",
        ]
        if payload.include_summary:
            file_names.append("summary.json")
        if payload.include_csv:
            file_names.append("manifest.csv")
        return file_names

    def _plan_classifier_manifest_media_copy(
        self,
        manifest: ClassifierTrainingManifestResponse,
    ) -> tuple[
        list[ClassifierManifestPlannedMediaFile],
        list[ClassifierManifestSkippedMediaRecord],
        int | None,
    ]:
        planned_media_files: list[ClassifierManifestPlannedMediaFile] = []
        skipped_media: list[ClassifierManifestSkippedMediaRecord] = []

        for example in manifest.examples:
            source_path = example.local_media_path
            if not source_path:
                skipped_media.append(
                    ClassifierManifestSkippedMediaRecord(
                        example_id=example.example_id,
                        media_asset_id=example.media_asset_id,
                        source_path=None,
                        reason="media_source_missing",
                        detail="Manifest example has no local media path to copy.",
                    )
                )
                continue

            path = Path(source_path)
            suffix = path.suffix.lower()
            if suffix not in CLASSIFIER_MANIFEST_COPY_IMAGE_EXTENSIONS:
                skipped_media.append(
                    ClassifierManifestSkippedMediaRecord(
                        example_id=example.example_id,
                        media_asset_id=example.media_asset_id,
                        source_path=source_path,
                        reason="unsupported_media_type",
                        detail="Media-copy dry-run initially supports image file extensions only.",
                    )
                )
                continue
            if not path.exists() or not path.is_file():
                skipped_media.append(
                    ClassifierManifestSkippedMediaRecord(
                        example_id=example.example_id,
                        media_asset_id=example.media_asset_id,
                        source_path=source_path,
                        reason="stale_media_reference",
                        detail="Local media path does not point to an existing file.",
                    )
                )
                continue

            try:
                size_bytes = path.stat().st_size
            except OSError:
                skipped_media.append(
                    ClassifierManifestSkippedMediaRecord(
                        example_id=example.example_id,
                        media_asset_id=example.media_asset_id,
                        source_path=source_path,
                        reason="stale_media_reference",
                        detail="Local media size could not be read with filesystem metadata.",
                    )
                )
                continue

            planned_media_files.append(
                ClassifierManifestPlannedMediaFile(
                    example_id=example.example_id,
                    media_asset_id=example.media_asset_id,
                    source_path=source_path,
                    planned_relative_path=(
                        f"media/{self._classifier_manifest_safe_media_stem(example.example_id)}"
                        f"{suffix}"
                    ),
                    size_bytes=size_bytes,
                    reason=None,
                )
            )

        total_planned_media_bytes = sum(
            planned.size_bytes or 0 for planned in planned_media_files
        )
        return planned_media_files, skipped_media, total_planned_media_bytes

    def _classifier_manifest_safe_media_stem(self, example_id: str) -> str:
        safe = re.sub(r"[^A-Za-z0-9._-]+", "-", example_id).strip(".-")
        return safe or "classifier-example"

    def _write_classifier_manifest_files(
        self,
        output_dir: Path,
        file_names: list[str],
        payload: ClassifierManifestFileExportRequest,
        manifest: ClassifierTrainingManifestResponse,
        export_id: str,
        created_at: str,
    ) -> None:
        if "manifest.jsonl" in file_names:
            self._write_jsonl(
                output_dir / "manifest.jsonl",
                [example.model_dump(mode="json") for example in manifest.examples],
            )
        if "taxonomy.json" in file_names:
            self._write_json(
                output_dir / "taxonomy.json",
                [entry.model_dump(mode="json") for entry in manifest.taxonomy],
            )
        if "skipped_records.jsonl" in file_names:
            self._write_jsonl(
                output_dir / "skipped_records.jsonl",
                [record.model_dump(mode="json") for record in manifest.skipped_records],
            )
        if "summary.json" in file_names:
            self._write_json(
                output_dir / "summary.json",
                self._classifier_manifest_export_summary(
                    payload,
                    manifest,
                    export_id,
                    created_at,
                    file_names,
                ),
            )
        if "manifest.csv" in file_names:
            self._write_classifier_manifest_csv(output_dir / "manifest.csv", manifest)

    def _classifier_manifest_export_summary(
        self,
        payload: ClassifierManifestFileExportRequest,
        manifest: ClassifierTrainingManifestResponse,
        export_id: str,
        created_at: str,
        file_names: list[str],
    ) -> dict[str, Any]:
        return {
            "export_id": export_id,
            "created_at": created_at,
            "manifest_version": manifest.manifest_version,
            "manifest_generated_at": manifest.generated_at,
            "media_policy": payload.media_policy,
            "split_seed": payload.split_seed,
            "dry_run": payload.dry_run,
            "include_csv": payload.include_csv,
            "include_summary": payload.include_summary,
            "examples": len(manifest.examples),
            "skipped": len(manifest.skipped_records),
            "skipped_reasons": dict(
                sorted(Counter(record.reason for record in manifest.skipped_records).items())
            ),
            "labels": manifest.summary.labels,
            "splits": manifest.summary.splits,
            "warnings": manifest.warnings,
            "files": file_names,
        }

    def _write_jsonl(self, path: Path, records: list[dict[str, Any]]) -> None:
        with path.open("w", encoding="utf-8") as handle:
            for record in records:
                handle.write(json.dumps(record, sort_keys=True))
                handle.write("\n")

    def _write_json(self, path: Path, payload: Any) -> None:
        with path.open("w", encoding="utf-8") as handle:
            json.dump(payload, handle, indent=2, sort_keys=True)
            handle.write("\n")

    def _write_classifier_manifest_csv(
        self,
        path: Path,
        manifest: ClassifierTrainingManifestResponse,
    ) -> None:
        fieldnames = [
            "example_id",
            "visit_id",
            "event_id",
            "media_asset_id",
            "source_id",
            "stream_id",
            "zone_id",
            "local_media_path",
            "label",
            "taxonomy_id",
            "common_name",
            "scientific_name",
            "reviewed_label_id",
            "reviewed_at",
            "created_at",
            "split",
            "quality_flags",
            "provenance",
        ]
        with path.open("w", encoding="utf-8", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=fieldnames)
            writer.writeheader()
            for example in manifest.examples:
                row = example.model_dump(mode="json")
                row["quality_flags"] = json.dumps(row["quality_flags"], sort_keys=True)
                row["provenance"] = json.dumps(row["provenance"], sort_keys=True)
                writer.writerow({field: row.get(field) for field in fieldnames})

    def _analytics_summary(self, session: Session) -> AnalyticsSummary:
        event_ids_with_any_visits = set(session.scalars(select(VisitModel.event_id)).all())
        active_event_ids = {
            visit.event_id for visit in self._visits_for_eventless_query(session)
        }
        events = [
            self._event_from_model(session, event)
            for event in session.scalars(select(EventModel).order_by(EventModel.started_at)).all()
            if event.id not in event_ids_with_any_visits or event.id in active_event_ids
        ]
        visits = self._visits_for_eventless_query(session)
        review_labels = self.list_review_labels_from_session(session)

        needs_review_count = sum(
            event.review_status == ReviewStatus.needs_review for event in events
        ) + sum(visit.review_status == ReviewStatus.needs_review for visit in visits)

        species_counts: Counter[str] = Counter()
        for visit in visits:
            if visit.review_status != ReviewStatus.reviewed or not visit.reviewed_label:
                continue
            species_counts[
                self._normalize_label_from_session(session, visit.reviewed_label)
            ] += 1

        visit_event_ids = {visit.event_id for visit in visits}
        for label in review_labels:
            if label.target_type == "visit":
                continue
            if label.target_type == "event" and (
                label.target_id in visit_event_ids
                or label.target_id in event_ids_with_any_visits
            ):
                continue
            species_counts[self._normalize_label_from_session(session, label.label)] += 1

        label_display_names: dict[str, str] = {}
        label_categories: dict[str, LabelCategory] = {}
        species_label_ids: list[str] = []
        for label in species_counts:
            taxonomy_label = self._taxonomy_label_model_for_input(session, label)
            if taxonomy_label is None:
                continue
            taxonomy = _taxonomy_label_from_model(taxonomy_label)
            label_display_names[label] = taxonomy.display_name
            label_categories[label] = taxonomy.category
            if taxonomy.is_species:
                species_label_ids.append(label)

        zone_activity_counts: Counter[str] = Counter()
        events_by_id = {event.id: event for event in events}
        for visit in visits:
            event = events_by_id.get(visit.event_id)
            zone_id = visit.zone_id or (event.primary_zone_id if event is not None else None)
            if zone_id is not None:
                zone_activity_counts[zone_id] += 1
        for event in events:
            if event.id not in visit_event_ids and event.primary_zone_id is not None:
                zone_activity_counts[event.primary_zone_id] += 1

        return AnalyticsSummary(
            event_count=len(events),
            visit_count=len(visits),
            needs_review_count=needs_review_count,
            species_counts=dict(species_counts),
            label_display_names=label_display_names,
            label_categories=label_categories,
            species_label_ids=species_label_ids,
            zone_activity_counts=dict(zone_activity_counts),
        )

    def list_review_labels_from_session(self, session: Session) -> list[ReviewLabel]:
        labels = session.scalars(
            select(ReviewLabelModel).order_by(ReviewLabelModel.created_at, ReviewLabelModel.id)
        ).all()
        return [
            _review_label_from_model(label)
            for label in self._effective_review_label_models(list(labels))
            if label.target_type != "visit"
            or (
                (visit := session.get(VisitModel, label.target_id)) is not None
                and not visit.is_superseded
            )
        ]

    def _visits_for_eventless_query(self, session: Session) -> list[Visit]:
        # Every active product surface shares this resolver so split and merge
        # provenance remains auditable without becoming duplicate observation truth.
        visits = session.scalars(
            select(VisitModel)
            .where(VisitModel.is_superseded.is_(False))
            .order_by(VisitModel.id)
        ).all()
        return [_visit_from_model(visit) for visit in visits]

    def _next_id(self, session: Session, model: type, prefix: str) -> str:
        count = session.scalar(select(func.count(model.id))) or 0
        candidate_number = count + 1
        while True:
            candidate = f"{prefix}-{candidate_number:03d}"
            if session.get(model, candidate) is None:
                return candidate
            candidate_number += 1


